        }
        else if (HttpContext.Current.Session["user_type"].ToString() == "PC")
        {
            return "progcoord";
        }
        else if (HttpContext.Current.Session["user_type"].ToString() == "I2")
        {
            return "instructor";
        }
        else if (HttpContext.Current.Session["user_type"].ToString() == "D")
        {
            return "dean";
        }
        else if (HttpContext.Current.Session["user_type"].ToString() == "FA")
