    [WebMethod(EnableSession = true)]
    public string LoginCheck(String username, string Password, bool remember_val)
    {
        try
        {
            ServerLog.ExceptionLog("inside LoginCheck.");
            EncryptPassword encrpt = new EncryptPassword();

            string pass = Password;
            //Password = encrpt.sbs_encrypt(Password.ToString().Trim());

            Password = encoding_decoding.encryptPassword(Password.ToString().Trim());

            FormsAuthentication.SetAuthCookie(username, false); // create auth cookie

            //if (FormsAuthentication.Authenticate(username, pass))
            //{
            //    FormsAuthentication.RedirectFromLoginPage(username, false);
            //}
            //else
            //{
            //    FormsAuthentication.RedirectFromLoginPage(username, true);
            //}

            //DataTable dt_email = objmaster.get_all_student_data();

            //if (dt_email != null)
            //{
            //    DataRow[] dr = dt_email.Select("mail='" + username + "'");

            //    if (dr.Length > 0)
            //    {
            //        DataTable dt_alumini_registration_dtl = objmaster.get_alumini_registration_details(dr[0]["user_id"].ToString(), "Y", "");

            //        if (dt_alumini_registration_dtl != null)
            //        {
            //            string check_pass = dr[0]["user_id"].ToString() + dr[0]["year_code"].ToString();

            //            if (pass == check_pass)
            //            {
            //                HttpContext.Current.Session["reset_flag"] = "R";
            //                return "change_password";
            //            }
            //        }
            //    }
            //}

            Login objLogin = new BLL.Utilities.Login();
            ServerLog.ExceptionLog("First Step 1");

            SessionMaster.Createdby = username.ToString().Trim();
            SessionMaster.CreatedHost = HttpContext.Current.Request.UserHostName.ToString();

            LoginInfo objLoginInfo = objLogin.CheckIn(username.ToString().Trim(), Password, HttpContext.Current.Request.UserHostAddress, HttpContext.Current.Request.UserHostName, ClientType.Browser, BLL.Utilities.Module.SND, "HelpList#1");

            ServerLog.ExceptionLog("First CheckIn" + objLoginInfo.ServerMessage + objLoginInfo.LoginStatus);
            if (objLoginInfo.LoginStatus == 2)
            {
                return "Login status is 2" + objLoginInfo.ServerMessage + objLoginInfo.LoginStatus;
            }

            ServerLog.ExceptionLog("Second CheckIn" + objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows.Count);

            if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString() == "S" || objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString() == "E")
            {
                DataTable dt_alumini_registration_dtl_1st = objmaster.get_alumini_registration_details(objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_id"].ToString(), "Y", "");
                if (dt_alumini_registration_dtl_1st == null)
                {
                    ServerLog.ExceptionLog("Second CheckIn NULL");
                }


                if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString() == "E")
                {
                    DataTable dt_multiple_email_check = objmaster.Get_multiple_same_email_user(username);

                    if (dt_multiple_email_check != null)
                    {
                        if (dt_multiple_email_check.Rows.Count > 1)
                        {
                            return "multiple_mail";
                        }
                    }
                }
                else if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString() == "S" && dt_alumini_registration_dtl_1st != null)
                {
                    //return "Alumni";
                    DataTable dt_multiple_email_check = objmaster.Get_multiple_same_email_user(username);
                    bool non_student = false;

                    if (dt_multiple_email_check != null)
                    {
                        for (int p = 0; p < dt_multiple_email_check.Rows.Count; p++)
                        {
                            if (dt_multiple_email_check.Rows[p]["user_type"].ToString() != "S")
                            {
                                non_student = true;
                            }
                        }
                        if (non_student)
                        {
                            objLoginInfo = objLogin.CheckIn(username.ToString().Trim(), Password, HttpContext.Current.Request.UserHostAddress, HttpContext.Current.Request.UserHostName, ClientType.Browser, BLL.Utilities.Module.SND, "HelpList#2");
                        }
                    }
                }
                else if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString() == "S" && dt_alumini_registration_dtl_1st == null)
                {
                    if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["prog_level_code"].ToString() == "PHD")
                    {
                        DataTable dt_phd_student = objmaster.Get_multiple_same_email_user_PHD(username);
                        if (dt_phd_student != null)
                        {
                            if (dt_phd_student.Rows.Count > 1)
                            {
                                return "multiple_mail";
                            }
                        }
                    }
                    else
                    {
                        DataTable dt_multiple_email_check = objmaster.Get_multiple_same_email_user(username);

                        if (dt_multiple_email_check != null)
                        {
                            if (dt_multiple_email_check.Rows.Count > 1)
                            {
                                return "multiple_mail";
                            }
                        }
                    }

                }
            }

            if (objLoginInfo != null)
            {
                if (objLoginInfo.LoginStatus == 1)
                {
                    try
                    {
                        //Session["StartPeriod"] = System.DateTime.Now.Month.ToString("00") + "/" + System.DateTime.Now.ToString("01/yyyy");
                        //Session["EndPeriod"] = System.DateTime.Now.Month.ToString("00") + "/" + System.DateTime.DaysInMonth(System.DateTime.Now.Year, System.DateTime.Now.Month).ToString("00") + "/" + System.DateTime.Now.ToString("yyyy");
                        HttpContext.Current.Session["is_special_user"] = false;
                        if (objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_dept"].ToString().Trim() == "SpecialAdmin")
                            HttpContext.Current.Session["is_special_user"] = true;
                        HttpContext.Current.Session["start_date"] = System.DateTime.Now.Month.ToString("00") + "/" + System.DateTime.Now.ToString("01/yyyy");
                        HttpContext.Current.Session["end_date"] = System.DateTime.Now.Month.ToString("00") + "/" + System.DateTime.DaysInMonth(System.DateTime.Now.Year, System.DateTime.Now.Month).ToString("00") + "/" + System.DateTime.Now.ToString("yyyy");
                        HttpContext.Current.Session["SessionId"] = objLoginInfo.SessionId.ToString().Trim();
                        HttpContext.Current.Session["UserId"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_id"].ToString(); //txtUserName.Text.Trim();
                        Clientsession.Getuser_ID(Session["UserId"].ToString());
                        HttpContext.Current.Session["UserName"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_name"].ToString();
                        HttpContext.Current.Session["first_name"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["first_name"].ToString();
                        //HttpContext.Current.Session["semester_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["semester_code"].ToString();
                        HttpContext.Current.Session["dept_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["dept_code"].ToString();
                        HttpContext.Current.Session["prog_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["prog_code"].ToString();
                        HttpContext.Current.Session["prog_level_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["prog_level_code"].ToString();
                        HttpContext.Current.Session["user_type"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["user_type"].ToString();
                        HttpContext.Current.Session["year_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["year_code"].ToString();
                        HttpContext.Current.Session["created_by"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["created_by"].ToString();
                        HttpContext.Current.Session["student_code"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["student_no"].ToString();
                        HttpContext.Current.Session["gender"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["gender"].ToString();
                        HttpContext.Current.Session["designation"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["designation"].ToString();
                        HttpContext.Current.Session["is_submit"] = objLoginInfo.ds_BusinessAreaInfo.Tables["dt_usermst"].Rows[0]["is_submit"].ToString();
