                        //                return "multiple_mail";
                        //            }
                        //        }
                        //    }
                        //}

                        //if (HttpContext.Current.Session["user_type"] != null && HttpContext.Current.Session["user_type"].ToString() == "S")
                        //{
                        //    DataTable dt_alumini_registration_dtl = objmaster.get_alumini_registration_details(HttpContext.Current.Session["UserId"].ToString(), "Y", "");

                        //    if (dt_alumini_registration_dtl != null)
                        //    {
                        //        return "Alumni";
                        //    }

                        //    if (HttpContext.Current.Session["user_dept"] != null && HttpContext.Current.Session["user_dept"] != "")
                        //    {
                        //        if (HttpContext.Current.Session["user_dept"].ToString() == "F")
                        //        {
                        //            return "foren";
                        //        }
                        //    }

                        //    objBLReturnObject.ServerMessage = "student";
                        //    return objBLReturnObject.ServerMessage;
                        //}
                        //else
                        //{
                        //    return "adminmaster";
                        //}

                        return objBLReturnObject.ServerMessage;
                    }
                    catch (Exception ex)
