    [WebMethod(EnableSession = true)]
    public string send_forgot_password(string email_id)
    {
        try
        {
            EncryptPassword encrpt = new EncryptPassword();
            DataTable dt_user = objmaster.get_all_user_mst_data();

            string sending_email = ConfigurationSettings.AppSettings["email"].ToString();
            string sending_password = ConfigurationSettings.AppSettings["password"].ToString();
            string host = ConfigurationSettings.AppSettings["host"].ToString();
            int port = Convert.ToInt32(ConfigurationSettings.AppSettings["port"].ToString());

            ServerLog.ExceptionLog("1" + sending_email.ToString() + "-" + sending_password.ToString() + "-" + host + "-" + port);

            string password = "";
            string user_id = "";

            if (dt_user != null)
            {
                DataRow[] dr = dt_user.Select("mail = '" + email_id.ToString().Trim().ToLower() + "'");

                ServerLog.ExceptionLog("2" + dr.Length.ToString() + "-" + email_id.ToString().Trim().ToLower());
                if (dr.Length > 0)
                {
                    password = dr[0]["password"].ToString();
                    user_id = dr[0]["user_id"].ToString();

                    //string Password = encoding_decoding.decryptPassword(password.ToString().Trim());

                    string str_path = HttpContext.Current.Request.Url.Authority;

                    for (int i = 0; i < (HttpContext.Current.Request.Url.Segments.Length - 2); i++)
                    {
                        str_path = str_path + HttpContext.Current.Request.Url.Segments[i];
                    }

                    var str_encr = "";
                    Payment objPayment = new Payment();
                    str_encr = objPayment.Encrypt_AES(user_id + "|" + email_id, "1000672598201019");
                    str_encr = Server.UrlEncode(str_encr);

                    SmtpClient SmtpServer = new SmtpClient();

                    SmtpServer.Credentials = new System.Net.NetworkCredential(sending_email, sending_password);

                    ////SmtpServer.DeliveryMethod = SmtpDeliveryMethod.Network;

                    SmtpServer.Port = port;
                    SmtpServer.Host = host;
                    SmtpServer.EnableSsl = true;

                    MailMessage mail = new MailMessage();

                    string TomailIds = email_id.ToString().Trim().ToLower();

                    mail.From = new MailAddress(sending_email, sending_email, System.Text.Encoding.UTF8);
                    mail.To.Add(TomailIds);
                    mail.Subject = "Forgot Password - CEPT";

                    //mail.Body = "Your password is : '" + Password + "'";
                    mail.Body = "<br/><p>By clicking on the following button, you can reset your password.</p>";
                    mail.Body += "<div style=\"text-align:center; padding:10px 0 10px 0;\">";
                    mail.Body += "<a href='" + HttpContext.Current.Request.Url.Scheme + "://" + str_path + "ResetPassword.aspx?UN=" + str_encr + "' style=\"background:#337BC4; color:#fff; text-decoration:none; font-size:13px; display:inline-block; padding:10px;\">Reset Password</a></div>";
                    mail.Body += "<br /><p>Sincerely,<br />-- CEPT</p>";
                    mail.IsBodyHtml = true;

                    SmtpServer.Send(mail);
                }
                else
                {
                    return "This email id is not match in master";
                }
            }
            else
            {
                return "no user data found in user master";
            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("5-" + ex.ToString());
            return "Problem in Change Password";
            //return ex.ToString();
        }

        return "Password is sent in your mail account(If mail not found in Inbox then check in Spam)";
    }

