    [WebMethod(EnableSession = true)]
    public string get_user_data_for_pay_slip_kotak()
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();
        string Gender = "";
        decimal amount = 0;
        string last_date_of_fees = "";

        if (HttpContext.Current.Session["gender"].ToString() == "T")
        {
            Gender = "F";
        }
        else
        {
            Gender = HttpContext.Current.Session["gender"].ToString();
        }

        DataTable dt_user_fees_data = objmaster.get_user_data_for_pay_slip_new(user_id, HttpContext.Current.Session["semester_code"].ToString(), current_ws_sem, current_ws_year, Gender);

        if (dt_user_fees_data != null)
        {
            string str_payslip_number = "";
            dt_user_fees_data.Columns.Add("institution_name");
            dt_user_fees_data.Columns.Add("payslip_number");
            dt_user_fees_data.Columns.Add("bank_acc_no");

            //DataTable get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, "", current_ws_sem, current_ws_year);

            DataTable get_fees_dtl = new DataTable();

            if (CFP_Student)
            {
                if (CFP_Sem == "1")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_1(user_id, "", current_ws_sem, current_ws_year);
                }
                else if (CFP_Sem == "2")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, "", current_ws_sem, current_ws_year);
                }
            }
            else
            {
                get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, "", current_ws_sem, current_ws_year);
            }

            if (get_fees_dtl != null)
            {
                int no_of_installment = Convert.ToInt32(get_fees_dtl.Rows[0]["no_of_installment"].ToString());
                int cur_installment = 0;

                for (int i = 1; i <= no_of_installment; i++)
                {
                    if (get_fees_dtl.Rows[0]["is_installment" + i + "_paid"].ToString() != "Y")
                    {
                        cur_installment = i;
                        break;
                    }
                }

                amount = Convert.ToDecimal(get_fees_dtl.Rows[0]["installment" + cur_installment].ToString());

                //Add Fine Logic Start - 23 09 2019

                DataTable dt_fine_dtl = objmaster.get_fine_dtl_for_fees(user_id, get_fees_dtl.Rows[0]["semester_type"].ToString(), get_fees_dtl.Rows[0]["year_semester"].ToString());

                if (cur_installment == 1)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date"].ToString();
                }
                else if (cur_installment == 2)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date2"].ToString();
                }
                else if (cur_installment == 3)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date3"].ToString();
                }

                //bool fine_added = false;
                decimal fine_amount = 0;

                if (DateTime.Now > Convert.ToDateTime(last_date_of_fees))//If Todays Date is greater than last date of fees, calculate fine and add.
                {
                    String days = (DateTime.Now - Convert.ToDateTime(last_date_of_fees)).TotalDays.ToString();

                    int total_days = Convert.ToInt32(Math.Ceiling(Convert.ToDecimal(days)));

                    //if (total_days <= 7)
                    //{
                    //    if (dt_fine_dtl.Rows[0]["fine"].ToString() != "")
                    //    {
                    //        fine_amount = Convert.ToDecimal(total_days) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine"].ToString());
                    //        amount = Convert.ToDecimal(amount + fine_amount);//Add Fine
                    //                                                         //fine_added = true;
                    //    }
                    //}
                    //else if (total_days <= 84)
                    //{
                    //    if (dt_fine_dtl.Rows[0]["fine2"].ToString() != "")
                    //    {
                    //        fine_amount = Convert.ToDecimal(total_days) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine2"].ToString());
                    //        amount = Convert.ToDecimal(amount + fine_amount);//Add Fine
                    //                                                         //fine_added = true;
                    //    }
                    //}
                    //else 
                    //{ 

                    //}

                    if (dt_fine_dtl.Rows[0]["fine"].ToString() != "")
                    {
                        fine_amount = Convert.ToDecimal(total_days) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine"].ToString());
                        amount = Convert.ToDecimal(amount + fine_amount);//Add Fine
                                                                         //fine_added = true;
                    }
                }

                //if (fine_added)
                //{
                //fine_amount update user_fees_installment_dtl
                bool fine_updated = objmaster.update_fine_user_fees_installment_dtl(fine_amount, cur_installment.ToString(), user_id, get_fees_dtl.Rows[0]["semester_type"].ToString(), get_fees_dtl.Rows[0]["year_semester"].ToString());
                //}

                //End

                switch (dt_user_fees_data.Rows[0]["dept_code"].ToString())
                {
                    case "1":
                        str_payslip_number = "CEPTFAK";
                        dt_user_fees_data.Rows[0]["institution_name"] = "CEPTFAK - FACULTY OF ARCHITECTURE";
                        dt_user_fees_data.Rows[0]["bank_acc_no"] = "0312849199";
                        break;
                    case "2":
                        str_payslip_number = "CEPTFDK";
                        dt_user_fees_data.Rows[0]["institution_name"] = "CEPTFDK - FACULTY OF DESIGN";
                        dt_user_fees_data.Rows[0]["bank_acc_no"] = "0312849236";
                        break;
                    case "3":
                        str_payslip_number = "CEPTFMK";
                        dt_user_fees_data.Rows[0]["institution_name"] = "CEPTFMK - FACULTY OF MANAGEMENT";
                        dt_user_fees_data.Rows[0]["bank_acc_no"] = "0312849229";
                        break;
                    case "4":
                        str_payslip_number = "CEPTFPK";
                        dt_user_fees_data.Rows[0]["institution_name"] = "CEPTFPK - FACULTY OF PLANNING";
                        dt_user_fees_data.Rows[0]["bank_acc_no"] = "0312849205";
                        break;
                    case "5":
                        str_payslip_number = "CEPTFTK";
                        dt_user_fees_data.Rows[0]["institution_name"] = "CEPTFTK - FACULTY OF TECHNOLOGY";
                        dt_user_fees_data.Rows[0]["bank_acc_no"] = "0312849212";
                        break;
                }

                str_payslip_number += user_id + current_ws_sem + current_ws_year.Substring(2, 2);

                if (no_of_installment == 1)
                {
                    //DataTable dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");

                    DataTable dt_user_fees_choice = new DataTable();

                    if (CFP_Student)
                    {
                        if (CFP_Sem == "1")
                        {
                            dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 1st Sem Fees");
                        }
                        else if (CFP_Sem == "2")
                        {
                            dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 2nd Sem Fees");
                        }
                    }
                    else
                    {
                        dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");
                    }

                    if (dt_user_fees_choice != null)
                        str_payslip_number += dt_user_fees_choice.Rows[0]["fees_status"].ToString();
                    else
                        str_payslip_number += "F";
                }
                else
                {
                    str_payslip_number += cur_installment;
                }

                Payment objPayment = new Payment();
                DataTable dt_trans_detail = objPayment.GetTransactionDetails(str_payslip_number);

                if (dt_trans_detail != null && dt_trans_detail.Rows.Count > 0)
                {
                    if (dt_trans_detail.Rows[0]["payment_response_code"] == "100")
                    {
                    }
                }
                else
                {
                    DS_Payment obDS_Payment = new DS_Payment();
                    DS_Payment.applicationpaymenttransactionRow trans_row = obDS_Payment.applicationpaymenttransaction.NewapplicationpaymenttransactionRow();

                    trans_row.user_id = user_id;
                    trans_row.transaction_id = str_payslip_number;
                    trans_row.current_sem_code = HttpContext.Current.Session["semester_code"].ToString();
                    trans_row.semester_type = current_ws_sem;
                    trans_row.year_semester = current_ws_year;
                    trans_row.dept_id = dt_user_fees_data.Rows[0]["dept_code"].ToString();
                    trans_row.payment_send_flag = BLL.Utilities1.Constant.YES;
                    trans_row.payment_return_flag = BLL.Utilities1.Constant.NO;
                    trans_row.amount = amount;
                    trans_row.status_is_active = BLL.Utilities1.Constant.STATUS_ACTIVE;
                    trans_row.status_refund = BLL.Utilities1.Constant.NO;
                    trans_row.status_is_payment_received = BLL.Utilities1.Constant.NO;
                    trans_row.created_date = DateTime.Now;
                    trans_row.created_by = user_id;
                    trans_row.created_host = HttpContext.Current.Request.UserHostName;
                    trans_row.cash_collected_by = cur_installment.ToString();

                    obDS_Payment.applicationpaymenttransaction.AddapplicationpaymenttransactionRow(trans_row);

                    objBLReturnObject = objmaster.Save_manually_Online_transaction_data(obDS_Payment, user_id, HttpContext.Current.Request.UserHostName);
                }
            }

            dt_user_fees_data.Rows[0]["payslip_number"] = str_payslip_number;

            jsondata = GetJson1(dt_user_fees_data);
        }

        return jsondata;
    }

