    [WebMethod(EnableSession = true)]
    public string get_user_data_for_pay_slip_for_manually_student_wise(string student, string fees_status)
    {
        string Gender = "";
        string semester = "";
        string installment_status = "";
        decimal amount = 0, main_fees = 0, fees1 = 0, deposit = 0;

        //DataTable dt = objmaster.check_credit_choice_by_student("", "", student, "");

        //if (dt != null)
        //{
        //  semester = dt.Rows[0]["semester_code"].ToString();

        DataTable dt_gender = objmaster.get_user_data_for_pay_slip(student, semester, current_ws_sem, current_ws_year);

        if (dt_gender != null)
        {
            Gender = dt_gender.Rows[0]["gender"].ToString();

            if (Gender == "")
            {
                return "gender";
            }
        }
        else
        {
            return "fees_detail";
        }
        //}
        //else
        //{
        //    return "student data not found.";
        //}

        if (Gender == "T")
        {
            Gender = "F";
        }
        else
        {

        }


        DataTable dt1 = objmaster.get_student_payslip_number(student, current_ws_sem, current_ws_year);
        Boolean status = true;
        if (dt1 != null)
        {
            if (dt1.Rows.Count == 0)
            {
                status = objmaster.Insert_Payslip_Number(student, HttpContext.Current.Request.UserHostName, semester, current_ws_sem, current_ws_year);
            }
        }
        else
        {
            status = objmaster.Insert_Payslip_Number(student, HttpContext.Current.Request.UserHostName, semester, current_ws_sem, current_ws_year);
        }

        if (status == false)
        {
            //obj_data["status"] = false;
            //obj_data["message"] = "Problem in Generate Payslip Number.";

            return "Problem in Generate Payslip Number.";
        }

        DataTable mandatory_time_day_data = objmaster.get_user_data_for_pay_slip_new(student, semester, current_ws_sem, current_ws_year, Gender);

        if (mandatory_time_day_data != null)
        {

            mandatory_time_day_data.Columns.Add("payslip_number");

            DataTable dt_number = objmaster.get_student_payslip_number(student, current_ws_sem, current_ws_year);

            if (dt_number != null)
            {
                if (dt_number.Rows.Count > 0)
                {
                    mandatory_time_day_data.Rows[0]["payslip_number"] = dt_number.Rows[0]["payslip_number"].ToString();
                }
            }

            DataTable get_installment_data = objmaster.get_installment_data(student, current_ws_sem, current_ws_year);

            if (get_installment_data != null)
            {
                if (get_installment_data.Rows[0]["installment_status"].ToString() == "Y")
                {
                    installment_status = "Y";
                }
                else
                {
                    installment_status = "N";
                }

            }


            if (mandatory_time_day_data.Rows[0]["fees"].ToString() != "")
            {
                main_fees = Convert.ToDecimal(mandatory_time_day_data.Rows[0]["fees"]);
            }
            if (mandatory_time_day_data.Rows[0]["fees1"].ToString() != "")
            {
                fees1 = Convert.ToDecimal(mandatory_time_day_data.Rows[0]["fees1"]);
            }
            if (mandatory_time_day_data.Rows[0]["deposit"].ToString() != "")
            {
                deposit = Convert.ToDecimal(mandatory_time_day_data.Rows[0]["deposit"]);
            }


            if (fees_status == "F")
            {

                if (installment_status == "Y")
                {
                    amount = ((main_fees + fees1) / 2) + deposit;
                }
                else
                {
                    amount = main_fees + fees1 + deposit;
                }

            }
            else
            {
                if (installment_status == "Y")
                {
                    amount = ((main_fees + fees1) / 4) + deposit;
                }
                else
                {
                    amount = ((main_fees + fees1) / 2) + deposit;
                }
            }

            mandatory_time_day_data.Columns.Add("amount");

            mandatory_time_day_data.Rows[0]["amount"] = amount.ToString();

            jsondata = GetJson1(mandatory_time_day_data);


        }

        return jsondata;
    }

