    public string[] get_saved_registerd_course_for_drop_course(string flag)
    {
        string[] data = new string[3];
        string sem_code = "";
        string json = "";


        DataTable get_assigned_data = null;

        //DataTable dt = objmaster.check_credit_choice_by_student("", "", student, "");

