        if (flag == "C")
        {
            get_assigned_data = objmaster.Get_student_assigned_current_sem_data_report(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year, "", "");
        }
        else
        {
            get_assigned_data = objmaster.Get_student_assigned_current_sem_data_report_for_drop_course(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);
        }

        DataTable ws_get_data = objmaster.WS_Get_student_assigned_current_sem_data_report_for_drop_course(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

        if (get_assigned_data != null)
        {
            json = GetJson1(get_assigned_data);
        }

        data[0] = jsondata;
        data[1] = json;
        if (ws_get_data != null)
        {
            data[2] = GetJson1(ws_get_data);
        }
        else { data[2] = null; }


        return data;
    }

