    [WebMethod]
    public string get_user_data(string dept_code, string prog_code, string year_code, string semester_type, string year_semester, string modified_on, string stud_code)
    {
        DataTable dt = objmaster.Get_student_data_for_report(year_code, dept_code, prog_code, semester_type, year_semester, stud_code);

        if (dt != null)
        {
            if (semester_type != "" && year_semester != "" && modified_on != "")
            {
                DateTime temp_date1 = new DateTime(Int32.Parse(modified_on.Split('/')[2]), Int32.Parse(modified_on.Split('/')[0]), Int32.Parse(modified_on.Split('/')[1]));

                dt = dt.Select("modified_date>='" + temp_date1 + "' and modified_date<'" + temp_date1.AddDays(1) + "'").CopyToDataTable();
            }

            jsondata = GetJson1(dt);
        }

        return jsondata;
    }

