    [WebMethod(EnableSession = true)]
    public string[] Get_instructor_code_for_course_code_for_feedback(string course_code, string course_typology)
    {
        string[] jsonarry = new string[7];

        DataTable get_student_data = objmaster.Get_instructor_code_for_course_code_new(course_code, current_feedback_sem, current_feedback_year);

        DataTable dt_student_sub_group_instructor = objmaster.get_student_sub_group_instructor(HttpContext.Current.Session["UserId"].ToString(), course_code, current_feedback_sem, current_feedback_year);

        DataTable dt_temp = get_student_data.Clone();
        if (get_student_data != null)
        {
            for (int i = 0; i < get_student_data.Rows.Count; i++)
            {
                DataTable disable_instructor_feedback = objmaster.Get_instructor_code_for_course_code_feedback_disable(get_student_data.Rows[i]["course_code"].ToString(), get_student_data.Rows[i]["instructor_code"].ToString(), HttpContext.Current.Session["UserId"].ToString(), current_feedback_sem, current_feedback_year);
                if (disable_instructor_feedback == null)
                {
                    dt_temp.ImportRow(get_student_data.Rows[i]);
                }
            }
        }

        if (dt_temp != null)
        {
            if (dt_student_sub_group_instructor != null)
            {
                for (int i = 0; i < dt_temp.Rows.Count; i++)
                {
                    DataRow[] dr = dt_student_sub_group_instructor.Select("instructor_code='" + dt_temp.Rows[i]["instructor_code"] + "' and instructor_type='Instructor'");

                    if (dr.Length == 0)
                    {
                        dt_temp.Rows.RemoveAt(i--);
                    }
                }
            }

            if (dt_temp != null && dt_temp.Rows.Count > 0)
            {
                jsonarry[0] = GetJson1(dt_temp);
            }
        }

        DataTable get_feedback_instruction_data = objmaster.Get_feedback_instruction_mst_data_new(course_typology, current_feedback_sem, current_feedback_year);

        if (get_feedback_instruction_data != null)
        {
            jsonarry[1] = GetJson1(get_feedback_instruction_data);
        }

        DataTable get_saved_feedbcak_data = objmaster.Get_student_saved_feedback_data_for_submit(course_code, HttpContext.Current.Session["UserId"].ToString(), current_feedback_sem, current_feedback_year);

        if (get_saved_feedbcak_data != null)
        {
            jsonarry[2] = GetJson1(get_saved_feedbcak_data);
        }

        DataTable get_taught_supported_feedback = objmaster.get_taught_supported_value(course_code, HttpContext.Current.Session["UserId"].ToString(), current_feedback_sem, current_feedback_year);

        if (get_taught_supported_feedback != null)
        {
            jsonarry[3] = GetJson1(get_taught_supported_feedback);
        }

        DataTable get_AA_instructor_data = objmaster.Get_AA_instructor_code_for_course_code(course_code, current_feedback_sem, current_feedback_year);

        if (get_AA_instructor_data != null)
