                    for (int i = 0; i < dt_temp_aa.Rows.Count; i++)
                    {
                        DataRow[] dr = dt_student_sub_group_instructor.Select("instructor_code='" + dt_temp_aa.Rows[i]["instructor_code"] + "' and instructor_type='Instructor'");

                        if (dr.Length == 0)
                        {
                            dt_temp_aa.Rows.RemoveAt(i--);
