            //}
        }

        DataTable get_TA_instructor_data = objmaster.Get_TA_instructor_code_for_course_code(course_code, current_feedback_sem, current_feedback_year);

        if (get_TA_instructor_data != null)
        {
            DataTable dt_temp_ta = get_TA_instructor_data.Clone();

            for (int i = 0; i < get_TA_instructor_data.Rows.Count; i++)
            {
                DataTable disable_instructor_feedback_aa = objmaster.Get_instructor_code_for_course_code_feedback_disable(get_TA_instructor_data.Rows[i]["course_code"].ToString(), get_TA_instructor_data.Rows[i]["instructor_code"].ToString(), HttpContext.Current.Session["UserId"].ToString(), current_feedback_sem, current_feedback_year);
                if (disable_instructor_feedback_aa == null)
                {
                    dt_temp_ta.ImportRow(get_TA_instructor_data.Rows[i]);
                }
            }

            if (dt_temp_ta != null)
            {
                if (dt_student_sub_group_instructor != null)
                {
                    for (int i = 0; i < dt_temp_ta.Rows.Count; i++)
                    {
                        DataRow[] dr = dt_student_sub_group_instructor.Select("instructor_code='" + dt_temp_ta.Rows[i]["instructor_code"] + "' and instructor_type='Instructor'");

                        if (dr.Length == 0)
                        {
                            dt_temp_ta.Rows.RemoveAt(i--);
