    [WebMethod]
    public string get_course_wise_feedback_receipt_report(string year_code, string sem_code, string dept_code, string course_code, string program_level_code)
    {
        DataTable get_allocate_data = objmaster.get_feedback_allocate_course_wise_report(year_code, sem_code, dept_code, course_code, program_level_code);

        DataTable get_feedback_data = objmaster.get_feedback_course_wise_report(year_code, sem_code, dept_code, course_code, program_level_code);

        if (get_allocate_data != null)
        {
            DataTable dt = new DataTable();

            dt.Columns.Add("course_code");
            dt.Columns.Add("course_name");
            dt.Columns.Add("mandatory");
            dt.Columns.Add("elective");
            dt.Columns.Add("mandatory_fb");
            dt.Columns.Add("elective_fb");

            //  dt.PrimaryKey = new DataColumn[] {  dt.Columns[0] };

            string code = "";
            string name = "";

            string coursecode = "";
            string coursename = "";

            DataRow dr;

            for (int i = 0; i < get_allocate_data.Rows.Count; i++)
            {
                code = get_allocate_data.Rows[i]["course_code"].ToString();
                name = get_allocate_data.Rows[i]["course_name"].ToString();

                if (code == "1015")
                {

                }

                DataRow[] dr1 = get_allocate_data.Select("course_code = '" + code + "'");

                if (code != coursecode)
                {
                    dr = dt.NewRow();

                    dr["mandatory"] = "0";
                    dr["elective"] = "0";
                    dr["mandatory_fb"] = "0";
                    dr["elective_fb"] = "0";

                    DataRow[] dr2 = get_feedback_data.Select("course_code = '" + code + "'");

                    dr["course_code"] = code;
                    dr["course_name"] = name;

                    if (dr1.Length == 1)
                    {
                        if (dr1[0]["course_type"].ToString() == "M")
                        {
                            dr["mandatory"] = dr1[0]["total_course"].ToString();
                        }
                        else
                        {

                            dr["elective"] = dr1[0]["total_course"].ToString();

                        }
                    }


                    if (dr1.Length == 2)
                    {
                        if (dr1[0]["course_type"].ToString().Trim() == "M")
                        {
                            dr["mandatory"] = dr1[0]["total_course"].ToString();

                        }
                        else
                        {
                            dr["elective"] = dr1[0]["total_course"].ToString();
                        }

                        if (dr1[1]["course_type"].ToString() == "E")
                        {
                            dr["elective"] = dr1[1]["total_course"].ToString();

                        }
                        else
                        {
                            dr["mandatory"] = dr1[1]["total_course"].ToString();
                        }
                    }

                    if (dr2.Length == 1)
                    {
                        if (dr2[0]["course_type"].ToString() == "M")
                        {
                            dr["mandatory_fb"] = dr2[0]["total_feedback_course"].ToString();
                        }
                        else
                        {

                            dr["elective_fb"] = dr2[0]["total_feedback_course"].ToString();

                        }
                    }

                    if (dr2.Length == 2)
                    {
                        if (dr2[0]["course_type"].ToString().Trim() == "M")
                        {
                            dr["mandatory_fb"] = dr2[0]["total_feedback_course"].ToString();

                        }
                        else
                        {
                            dr["elective_fb"] = dr2[0]["total_feedback_course"].ToString();
                        }

                        if (dr2[1]["course_type"].ToString() == "E")
                        {
                            dr["elective_fb"] = dr2[1]["total_feedback_course"].ToString();

                        }
                        else
                        {
                            dr["mandatory_fb"] = dr2[1]["total_feedback_course"].ToString();
                        }
                    }

                    dt.Rows.Add(dr);
                }

                coursecode = get_allocate_data.Rows[i]["course_code"].ToString();
                coursename = get_allocate_data.Rows[i]["course_code"].ToString();
            }

            if (dt != null)
            {
                jsondata = GetJson1(dt);
            }

        }
        return jsondata;
    }

    [WebMethod]
    public string get_course_faculty_wise_feedback_report(string year_code, string sem_code, string dept_code)
    {
        DataTable get_feedback_data = objmaster.get_feedback_course_instructor_wise_report(year_code, sem_code, dept_code);

        DataTable get_instructor_mail = objmaster.get_course_instructor_with_mail(year_code, sem_code, "");

        if (get_feedback_data != null)
        {

            string code = "";
            string name = "";
            string faculty_name = "", faculty_mail = "";

            for (int i = 0; i < get_feedback_data.Rows.Count; i++)
            {
                code = get_feedback_data.Rows[i]["course_code"].ToString();
                name = get_feedback_data.Rows[i]["course_name"].ToString();

                faculty_name = "";
                faculty_mail = "";

                DataRow[] dr = get_instructor_mail.Select("course_code = '" + code + "'");

                if (dr.Length > 0)
                {
                    for (int j = 0; j < dr.Length; j++)
                    {
                        faculty_name += dr[j]["instructor_name"].ToString() + ", ";

                        if (dr[j]["mail"].ToString() != "")
                        {
                            faculty_mail += dr[j]["mail"].ToString() + ", ";
                        }


                    }
                    if (faculty_name != String.Empty)
                        get_feedback_data.Rows[i]["faculty_name"] = faculty_name.Trim().TrimEnd(',');
                    if (faculty_mail != String.Empty)
                        get_feedback_data.Rows[i]["faculty_mail"] = faculty_mail.Trim().TrimEnd(',');
                }


            }

            if (get_feedback_data != null)
            {
                jsondata = GetJson1(get_feedback_data);
            }

        }
        return jsondata;
    }

