    [WebMethod]
    public string get_course_faculty_wise_feedback_report_for_send_pdf(string year_code, string sem_code, string dept_code, string program_level_code, string prog_code)
    {
        DataTable get_feedback_data = objmaster.get_feedback_course_instructor_wise_report_for_send_pdf(year_code, sem_code, dept_code, program_level_code, prog_code);

        //DataTable get_instructor_mail = objmaster.get_course_instructor_with_mail(year_code, sem_code, "");
        if (get_feedback_data != null)
        {
            string semester = "";
            string dep_name = "";
            if (sem_code == "S")
            {
                semester = "Spring";
            }
            else
            {
                semester = "Monsoon";
            }
            get_feedback_data.Columns.Add("pdfstatus");
            for (int i = 0; i < get_feedback_data.Rows.Count; i++)
            {

                switch (get_feedback_data.Rows[i]["dept_name"].ToString())
                {
                    case "Architecture":
                        dep_name = "FA";
                        break;
                    case "Design":
                        dep_name = "FD";
                        break;
                    case "Management":
                        dep_name = "FM";
                        break;
                    case "Planning":
                        dep_name = "FP";
                        break;
                    case "Technology":
                        dep_name = "FT";
                        break;
                    case "CEPT Foundation Program":
                        dep_name = "CFP";
                        break;
                    case "Doctoral Programs":
                        dep_name = "DP";
                        break;
                    default:
                        dep_name = "CFP";
                        break;

                }
                string filename = dep_name + "_" + get_feedback_data.Rows[i]["course_code"].ToString() + "_" + get_feedback_data.Rows[i]["instructor_name"].ToString().Replace("'", " ") + "_" + semester + "_" + year_code + ".pdf";
                if (File.Exists(Server.MapPath("~/FeedbackPdf") + "\\" + filename))
                {
                    get_feedback_data.Rows[i]["pdfstatus"] = "Y";

                }
                else
                {
                    get_feedback_data.Rows[i]["pdfstatus"] = "N";
                }
            }
            jsondata = GetJson1(get_feedback_data);
        }


        return jsondata;
    }

