    [WebMethod]
    public string print_faculty_report_new1(string year_code, string sem_code, string course_type, string course_code, string dept_code)
    {

        if (course_code != "" && course_type == "")
        {
            DataTable dt_get_course_type = objmaster.Get_course_data_type_wise(sem_code, year_code, "", course_code, dept_code);

            if (dt_get_course_type != null)
            {
                if (dt_get_course_type.Rows[0]["course_typology"].ToString() == "3" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "4")
                {
                    course_type = "lecture";
                }

                if (dt_get_course_type.Rows[0]["course_typology"].ToString() == "5" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "6")
                {
                    course_type = "seminar";
                }

                if (dt_get_course_type.Rows[0]["course_typology"].ToString() == "7")
                {
                    course_type = "studio";
                }

                if (dt_get_course_type.Rows[0]["course_typology"].ToString() == "9" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "1" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "8")
                {
                    course_type = "workshop";
                }
            }
        }

        string type_code = "";
        string department = "";

        string semester = "";
        decimal total_course = 0;
        decimal total_instructor = 0;

        decimal faculty = 0;
        decimal cross_faculty = 0;


        decimal first_course_feedback = 0;
        decimal second_course_feedback = 0;
        decimal three_course_feedback = 0;
        decimal four_course_feedback = 0;
        decimal five_course_feedback = 0;
        decimal six_course_feedback = 0;

        decimal first_course_medain = 0, second_course_median = 0, three_course_median = 0, four_course_median = 0, five_course_median = 0, six_course_median = 0;

        //decimal first_course_medain_avg = 0, second_course_median = 0, three_course_median = 0, four_course_median = 0, five_course_median = 0, six_course_median = 0;

        decimal first_course_avg = 0;
        decimal second_course_avg = 0;
        decimal three_course_avg = 0;
        decimal four_course_avg = 0;
        decimal five_course_avg = 0;
        decimal six_course_avg = 0;

        decimal overall_course_rating = 0, overall_course_rating_median = 0;

        decimal architecture_per = 0, design_per = 0, management_per = 0, planning_per = 0, technology_per = 0;

        decimal architecture_student = 0, design_student = 0, management_student = 0, planning_student = 0, technology_student = 0;

        decimal first_instructor_feedback = 0;
        decimal second_instructor_feedback = 0;
        decimal three_instructor_feedback = 0;
        decimal four_instructor_feedback = 0;
        decimal five_instructor_feedback = 0;
        decimal six_instructor_feedback = 0;

        decimal first_instructor_medain = 0, second_instructor_median = 0, three_instructor_median = 0, four_instructor_median = 0, five_instructor_median = 0, six_instructor_median = 0;

        decimal first_instructor_avg = 0;
        decimal second_instructor_avg = 0;
        decimal three_instructor_avg = 0;
        decimal four_instructor_avg = 0;
        decimal five_instructor_avg = 0;
        decimal six_instructor_avg = 0;

        decimal overall_feedback_rating = 0, overall_instructor_rating_median = 0;

        decimal first_studio_medain = 0, second_studio_median = 0, three_studio_median = 0, four_studio_median = 0, five_studio_median = 0, six_studio_median = 0;
        decimal first_lecture_medain = 0, second_lecture_median = 0, three_lecture_median = 0, four_lecture_median = 0, five_lecture_median = 0, six_lecture_median = 0;
        decimal first_seminar_medain = 0, second_seminar_median = 0, three_seminar_median = 0, four_seminar_median = 0, five_seminar_median = 0, six_seminar_median = 0;
        decimal first_workshop_medain = 0, second_workshop_median = 0, three_workshop_median = 0, four_workshop_median = 0, five_workshop_median = 0, six_workshop_median = 0;


        decimal first_instructor_studio_medain = 0, second_instructor_studio_median = 0, three_instructor_studio_median = 0, four_instructor_studio_median = 0, five_instructor_studio_median = 0, six_instructor_studio_median = 0;
        decimal first_instructor_lecture_medain = 0, second_instructor_lecture_median = 0, three_instructor_lecture_median = 0, four_instructor_lecture_median = 0, five_instructor_lecture_median = 0, six_instructor_lecture_median = 0;
        decimal first_instructor_seminar_medain = 0, second_instructor_seminar_median = 0, three_instructor_seminar_median = 0, four_instructor_seminar_median = 0, five_instructor_seminar_median = 0, six_instructor_seminar_median = 0;
        decimal first_instructor_workshop_medain = 0, second_instructor_workshop_median = 0, three_instructor_workshop_median = 0, four_instructor_workshop_median = 0, five_instructore_workshop_median = 0, six_instructor_workshop_median = 0;

        DataTable dt_find_overall_course_median = new DataTable();

        DataRow dr_find_overall_course_median = null;

        dt_find_overall_course_median.Columns.Add("median_course");

        decimal first_number_overall_course_medain = 0, second_number_overall_course_median = 0;


        DataTable dt_find_overall_instructor_median = new DataTable();

        DataRow dr_find_overall_instructor_median = null;

        dt_find_overall_instructor_median.Columns.Add("median_instructor");

        decimal first_number_overall_instructor_medain = 0, second_number_overall_instructor_median = 0;


        if (course_type == "lecture")
        {
            type_code = "('3','4')";
        }
        else if (course_type == "seminar")
        {
            type_code = "('5','6')";
        }
        else if (course_type == "studio")
        {
            type_code = "('7')";
        }
        else if (course_type == "workshop")
        {
            type_code = "('9','1','8')";
        }
        else
        {
            type_code = "('3','4','5','6','7','9','1','8')";
        }

        if (sem_code == "S")
        {
            semester = "Spring";
        }
        if (sem_code == "M")
        {
            semester = "Monster";
        }

        #region Retrieve Data

