                    #region instructor median


                    for (int k = 1; k <= 6; k++)
                    {
                        DataRow[] dr_instructor_median = median_course_data.Select(" sr_no = '" + k + "' and course_type IN " + course_typology + " and dept_code ='" + dept_code + "' and instructor_code <> '' ", "sr_no ASC,number ASC");



                        firt_number = 0;
                        first_number_data = 0;
                        second_number_data = 0;

                        decimal total = 0;
                        decimal median_number = 0;
                        Decimal total_median_value = 0;

                        if (dr_instructor_median.Length > 0)
                        {
                            total = dr_instructor_median.Length;

                            median_number = (total + 1) / 2;

                            string[] split_data = median_number.ToString().Split('.');



                            if (course_type == "studio")
                            {


                                if (first_instructor_studio_medain == 0 || second_instructor_studio_median == 0 || three_instructor_studio_median == 0 || four_instructor_studio_median == 0 || five_instructor_studio_median == 0 || six_instructor_studio_median == 0)
                                {
                                    switch (k)
                                    {
                                        case 1:

                                            for (int n = 0; n < dr_instructor_median.Length; n++)
                                            {
