                    {
                        course_type = "lecture";
                    }

                    if (dt_get_course_type.Rows[0]["course_typology"].ToString() == "5" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "6" || dt_get_course_type.Rows[0]["course_typology"].ToString() == "13")
                    {
                        course_type = "seminar";
                    }

