    [WebMethod]
    public string print_faculty_report_latest_from_link(string year_code, string sem_code, string course_type, string course_code, string dept_code, string selected_instructor)
    {
        try
        {
            DataTable dt_typology_data = objmaster.Get_typology_data();
            Dictionary<string, string> dict_type_code = new Dictionary<string, string>();
            string type_code = "";

            if (dt_typology_data != null)
            {
                string temp_type_code_all = "";

                for (int i = 1; i <= 4; i++)
                {
                    DataRow[] dr_typology_data = dt_typology_data.Select("sub_group='SG00" + i.ToString() + "'");
                    string temp_type_code = "";

                    if (dr_typology_data.Length > 0)
                    {
                        for (var j = 0; j < dr_typology_data.Length; j++)
                        {
                            temp_type_code += "'" + dr_typology_data[j]["type_code"].ToString() + "'";
                        }
                    }

                    temp_type_code_all += temp_type_code;
                    dict_type_code["SG00" + i] = "(" + temp_type_code.Replace("''", "','") + ")";
                }

                dict_type_code["all"] = "(" + temp_type_code_all.Replace("''", "','") + ")";
            }

            if (course_code != "" && course_type == "")
            {
                DataTable dt_get_course_type = objmaster.Get_course_data_type_wise(sem_code, year_code, "", course_code, dept_code);

