    [WebMethod(EnableSession = true)]
    public string print_feedback_instructor_report(string sem_code, string year_code, string instructor_code, string instructor_name)
    {
        string semester_name = "";


        if (sem_code == "M")
        {
            semester_name = "Monsoon";
        }
        else
        {
            semester_name = "Spring";
        }

        DataTable dt_course = objmaster.get_course_data_by_instructor(sem_code, year_code, instructor_code, "");

        DataTable dt_feedback_calculation_data = objmaster.get_feedback_calculation_data_by_semester(sem_code, year_code);

        DataTable dt_course_time = objmaster.get_course_wise_time_by_instructor(sem_code, year_code);

        DataTable dt_allocate_data = objmaster.get_allocate_data_course_type_wise(sem_code, year_code);

        DataTable dt_typology_data = objmaster.Get_typology_data();

        decimal total_credits = 0, total_students = 0, total_average1 = 0, instructor_average = 0, course_overall_average = 0, instructor_overall_average = 0, total_hrs = 0, course_hrs = 0, madatory_student = 0, elective_student = 0;
        int count = 0;

        string course_div = "";

        if (dt_course != null)
        {

            for (int i = 0; i < dt_course.Rows.Count; i++)
            {
                total_credits += Convert.ToDecimal(dt_course.Rows[i]["course_credits"]);

                string course_code = dt_course.Rows[i]["course_code"].ToString();
                string course_name = dt_course.Rows[i]["course_name"].ToString();
                string course_credit = dt_course.Rows[i]["course_credits"].ToString();
                string course_type = "";
                if (dt_feedback_calculation_data != null)
                {
                    DataRow[] dr_instructor_avreage = dt_feedback_calculation_data.Select(" instructor_code = '" + instructor_code + "' and related_feedback = 'instructor'   and course_code = '" + dt_course.Rows[i]["course_code"].ToString() + "' ");

                    if (dr_instructor_avreage.Length > 0)
                    {
                        course_hrs = 0;
                        elective_student = 0;
                        madatory_student = 0;
                        course_type = "";
                        course_overall_average = 0;

                        count += 1;
                        total_students += Convert.ToDecimal(dr_instructor_avreage[0]["total_average1_student"]);
                        total_average1 += Convert.ToDecimal(dr_instructor_avreage[0]["overall_average1"]);

                        instructor_overall_average = Convert.ToDecimal(dr_instructor_avreage[0]["overall_average1"]);

                        DataRow[] dr_timing_hrs = dt_course_time.Select("course_code = '" + course_code + "'");

                        //if (dr_instructor_avreage[0]["course_typology"].ToString() == "3" || dr_instructor_avreage[0]["course_typology"].ToString() == "4")
                        //{
                        //    course_type = "Lecture";
                        //}
                        //if (dr_instructor_avreage[0]["course_typology"].ToString() == "5" || dr_instructor_avreage[0]["course_typology"].ToString() == "6")
                        //{
                        //    course_type = "Seminar";
                        //}
                        //if (dr_instructor_avreage[0]["course_typology"].ToString() == "7")
                        //{
                        //    course_type = "Studio";
                        //}
                        //if (dr_instructor_avreage[0]["course_typology"].ToString() == "9" || dr_instructor_avreage[0]["course_typology"].ToString() == "1" || dr_instructor_avreage[0]["course_typology"].ToString() == "8")
                        //{
                        //    course_type = "Workshop";
                        //}

                        DataRow[] dr_typology_data = dt_typology_data.Select("type_code='" + dr_instructor_avreage[0]["course_typology"].ToString() + "'");

                        if (dr_typology_data.Length > 0)
                        {
                            switch (dr_typology_data[0]["sub_group"].ToString())
                            {
                                case "SG001":
                                    course_type = "lecture";
                                    break;
                                case "SG002":
