    [WebMethod]
    public string get_feedback_data(string year_code, string sem_code, string dept_code, string course_code)
    {
        DataTable get_non_completed_data = objmaster.get_not_completed_feedback_report(year_code, sem_code, dept_code, course_code);

        DataTable get_completed_data = objmaster.get_completed_feedback_report(year_code, sem_code, dept_code, course_code);

        DataTable get_not_filled_data = objmaster.get_not_filled_feedback_report(year_code, sem_code, dept_code, course_code);

        DataTable get_total_feedback_data = objmaster.get_total_allocate_feedback_report(year_code, sem_code, dept_code, course_code);

        if (get_completed_data != null)
        {
            DataTable dt = new DataTable();
            DataRow dr;
            dt.Columns.Add("dept");
            dt.Columns.Add("prog");
            dt.Columns.Add("dept_code");
            dt.Columns.Add("prog_code");
            dt.Columns.Add("total_allocate");
            dt.Columns.Add("not_filled_feedback");
            dt.Columns.Add("total_feedback_received");
            dt.Columns.Add("completed");
            dt.Columns.Add("completed_percentage");
            dt.Columns.Add("non_completed");

            DataTable get_department = objmaster.Get_department_data();

            for (int i = 0; i < get_department.Rows.Count; i++)
            {
                if (i <= 5)// Add = by Ananth 21052019
                {
                    dr = dt.NewRow();

                    dr["dept"] = get_department.Rows[i]["dept_name"];
                    dr["prog"] = "UG";
                    dr["dept_code"] = get_department.Rows[i]["dept_code"];
                    dr["prog_code"] = '1';

                    dt.Rows.Add(dr);

                    dr = dt.NewRow();

                    dr["dept"] = "";
                    dr["prog"] = "PG";
                    dr["dept_code"] = get_department.Rows[i]["dept_code"];
                    dr["prog_code"] = '2';

                    dt.Rows.Add(dr);
                }
            }

            string code = "";
            string name = "";

            string coursecode = "";
            string coursename = "";

            decimal non_completed = 0, completed = 0;

            for (int i = 0; i < dt.Rows.Count; i++)
            {
                non_completed = 0;
                completed = 0;

                DataRow[] dr1 = get_non_completed_data.Select("dept_code = '" + dt.Rows[i]["dept_code"] + "' and prog_code = '" + dt.Rows[i]["prog_code"] + "'");

                DataRow[] dr2 = get_completed_data.Select("dept_code = '" + dt.Rows[i]["dept_code"] + "' and prog_code = '" + dt.Rows[i]["prog_code"] + "'");

                DataRow[] dr3 = get_not_filled_data.Select("dept_code = '" + dt.Rows[i]["dept_code"] + "' and prog_code = '" + dt.Rows[i]["prog_code"] + "'");

                DataRow[] dr4 = get_total_feedback_data.Select("dept_code = '" + dt.Rows[i]["dept_code"] + "' and prog_code = '" + dt.Rows[i]["prog_code"] + "'");

                if (dr1.Length > 0)
                {
                    dt.Rows[i]["non_completed"] = dr1[0]["total"].ToString();

                    non_completed = Convert.ToDecimal(dr1[0]["total"].ToString());
                }

                if (dr4.Length > 0)
                {
                    dt.Rows[i]["total_allocate"] = dr4[0]["total"].ToString();
                }

                if (dr2.Length > 0)
                {
                    dt.Rows[i]["completed"] = dr2[0]["total"].ToString();

                    completed = Convert.ToDecimal(dr2[0]["total"].ToString());

                    if (dr2[0]["total"].ToString() != "")
                    {
                        dt.Rows[i]["completed_percentage"] = Math.Round(completed * 100 / Convert.ToDecimal(dt.Rows[i]["total_allocate"].ToString()), 1, MidpointRounding.AwayFromZero); ;
                    }

                }

                dt.Rows[i]["total_feedback_received"] = non_completed + completed;

                if (dr3.Length > 0)
                {
                    dt.Rows[i]["not_filled_feedback"] = dr3[0]["total"].ToString();
                }

            }

            if (dt != null)
            {
                jsondata = GetJson1(dt);
            }

        }
        return jsondata;
    }

