    [WebMethod]
    public string get_student_feedback_data(string sem_code, string year_code, string dept_code, string prog_code)
    {
        DataTable get_feedback_disable_data = objmaster.get_feedback_disable_course_data(sem_code, year_code, "");

        string disable_course = MakeInQueryString(get_feedback_disable_data, "course_code");

        DataSet get_all_student_feedback_data = objmaster.Get_student_wise_feedback_data(sem_code, year_code, dept_code, prog_code, disable_course);

        DataTable dt_typology_data = objmaster.Get_typology_data();

        if (get_all_student_feedback_data != null)
        {
            decimal lecture = 0, seminar = 0, studio = 0, workshop = 0, others = 0;

            if (get_all_student_feedback_data.Tables[1].Rows.Count > 0)
            {
                get_all_student_feedback_data.Tables[1].Columns.Add("lecture");
                get_all_student_feedback_data.Tables[1].Columns.Add("seminar");
                get_all_student_feedback_data.Tables[1].Columns.Add("studio");
                get_all_student_feedback_data.Tables[1].Columns.Add("workshop");
                get_all_student_feedback_data.Tables[1].Columns.Add("others");
                get_all_student_feedback_data.Tables[1].Columns.Add("status");

                for (int i = 0; i < get_all_student_feedback_data.Tables[1].Rows.Count; i++)
                {
                    lecture = seminar = studio = workshop = others = 0;

                    string user_id = get_all_student_feedback_data.Tables[1].Rows[i]["user_id"].ToString();

                    if (user_id == "PUM20169")
                    {
                        string testig = "";
                    }

                    if (get_all_student_feedback_data.Tables[0].Rows.Count > 0)
                    {
                        DataRow[] dr = get_all_student_feedback_data.Tables[0].Select(" user_id = '" + user_id + "' ");

                        if (dr.Length > 0)
                        {
                            for (int j = 0; j < dr.Length; j++)
                            {
                                //if (dr[j]["course_typology"].ToString() == "3" || dr[j]["course_typology"].ToString() == "4" || dr[j]["course_typology"].ToString() == "12" || dr[j]["course_typology"].ToString() == "8" || dr[j]["course_typology"].ToString() == "18")
                                //{
                                //    lecture += 1;
                                //}
                                //else if (dr[j]["course_typology"].ToString() == "5" || dr[j]["course_typology"].ToString() == "6" || dr[j]["course_typology"].ToString() == "13" || dr[j]["course_typology"].ToString() == "19")
                                //{
                                //    seminar += 1;
                                //}
                                //else if (dr[j]["course_typology"].ToString() == "1" || dr[j]["course_typology"].ToString() == "9" || dr[j]["course_typology"].ToString() == "22")
                                //{
                                //    workshop += 1;
                                //}
                                //else if (dr[j]["course_typology"].ToString() == "7" || dr[j]["course_typology"].ToString() == "14" || dr[j]["course_typology"].ToString() == "20")
                                //{
                                //    studio += 1;
                                //}
                                //else
                                //{
                                //    others += 1;
                                //}

                                DataRow[] dr_typology_data = dt_typology_data.Select("type_code='" + dr[j]["course_typology"].ToString() + "'");

                                if (dr_typology_data.Length > 0)
                                {
                                    switch (dr_typology_data[0]["sub_group"].ToString())
                                    {
                                        case "SG001":
                                            lecture += 1;
                                            break;
                                        case "SG002":
                                            seminar += 1;
                                            break;
                                        case "SG003":
                                            studio += 1;
                                            break;
                                        case "SG004":
                                            workshop += 1;
                                            break;
                                        default:
                                            others += 1;
                                            break;
                                    }
                                }
                            }
                        }
                    }

                    get_all_student_feedback_data.Tables[1].Rows[i]["lecture"] = lecture.ToString();
                    get_all_student_feedback_data.Tables[1].Rows[i]["seminar"] = seminar.ToString();
                    get_all_student_feedback_data.Tables[1].Rows[i]["studio"] = studio.ToString();
                    get_all_student_feedback_data.Tables[1].Rows[i]["workshop"] = workshop.ToString();
                    get_all_student_feedback_data.Tables[1].Rows[i]["others"] = others.ToString();


                    if (get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"].ToString() != "" && get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"] != DBNull.Value)
                    {
                        if (Convert.ToInt32(get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"]) == (lecture + seminar + studio + workshop))
                        {
                            get_all_student_feedback_data.Tables[1].Rows[i]["status"] = "completed";
                        }
                        else
                        {
                            get_all_student_feedback_data.Tables[1].Rows[i]["status"] = "Not Completed";
                        }
                    }
                    else
                    {

                        get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"] = 0;
                        if (lecture + seminar + studio + workshop == 0)
                        {
                            get_all_student_feedback_data.Tables[1].Rows[i]["status"] = "Completed";
                        }
                        else
                        {
                            get_all_student_feedback_data.Tables[1].Rows[i]["status"] = "Not Completed";

                        }

                    }
                }
            }

            if (get_all_student_feedback_data.Tables[1] != null)
            {
                jsondata = GetJson1(get_all_student_feedback_data.Tables[1]);
            }

        }
        return jsondata;
    }

    [WebMethod]
    public string get_feedback_report_instructor_wise(string sem_code, string year_code, string dept_code, string instructor_code)
    {
        DataTable dt_feedback_data = objmaster.get_feedback_report_instructor_wise(sem_code, year_code, dept_code, instructor_code);
        DataTable dt_typology_data = objmaster.Get_typology_data();

        Dictionary<string, string> dict_type_code = new Dictionary<string, string>();

        if (dt_typology_data != null)
        {
            string temp_type_code_all = "";

            for (int i = 1; i <= 4; i++)
            {
                DataRow[] dr_typology_data = dt_typology_data.Select("sub_group='SG00" + i.ToString() + "'");
                string temp_type_code = "";

                if (dr_typology_data.Length > 0)
                {
                    for (var j = 0; j < dr_typology_data.Length; j++)
                    {
                        temp_type_code += "'" + dr_typology_data[j]["type_code"].ToString() + "'";
                    }
                }

                temp_type_code_all += temp_type_code;
                dict_type_code["SG00" + i] = "(" + temp_type_code.Replace("''", "','") + ")";
            }

            dict_type_code["all"] = "(" + temp_type_code_all.Replace("''", "','") + ")";
        }

        if (dt_feedback_data != null)
        {
            dt_feedback_data.Columns.Add("overall_course_faculty_avg");
            dt_feedback_data.Columns.Add("overall_instructor_Faculty_avg");

            for (int i = 0; i < dt_feedback_data.Rows.Count; i++)
            {
                string course_typology = "";
                string course_dept_code = dt_feedback_data.Rows[i]["dept_code"].ToString();

                string course_semester = dt_feedback_data.Rows[i]["semester_type"].ToString();
                string course_year = dt_feedback_data.Rows[i]["year_semester"].ToString();

                DataTable median_course_data = null;

                string course_type_name = "";

                //if (dt_feedback_data.Rows[i]["course_type"].ToString() == "3" || dt_feedback_data.Rows[i]["course_type"].ToString() == "4" || dt_feedback_data.Rows[i]["course_type"].ToString() == "12")
                //{
                //    course_typology = "('3','4','12')";
                //    course_type_name = "lecture";
                //}
                //if (dt_feedback_data.Rows[i]["course_type"].ToString() == "5" || dt_feedback_data.Rows[i]["course_type"].ToString() == "6" || dt_feedback_data.Rows[i]["course_type"].ToString() == "13")
                //{
                //    course_typology = "('5','6','13')";
                //    course_type_name = "seminar";
                //}
                //if (dt_feedback_data.Rows[i]["course_type"].ToString() == "7" || dt_feedback_data.Rows[i]["course_type"].ToString() == "14")
                //{
                //    course_typology = "('7','14')";
                //    course_type_name = "studio";
                //}
                //if (dt_feedback_data.Rows[i]["course_type"].ToString() == "9" || dt_feedback_data.Rows[i]["course_type"].ToString() == "1" || dt_feedback_data.Rows[i]["course_type"].ToString() == "8")
                //{
                //    course_typology = "('9','1','8')";
                //    course_type_name = "workshop";
                //}

                DataRow[] dr_typology_data = dt_typology_data.Select("type_code='" + dt_feedback_data.Rows[i]["course_type"].ToString() + "'");

                if (dr_typology_data.Length > 0)
                {
                    switch (dr_typology_data[0]["sub_group"].ToString())
                    {
                        case "SG001":
                            course_type_name = "lecture";
                            course_typology = dict_type_code["SG001"];
                            break;
                        case "SG002":
                            course_type_name = "seminar";
                            course_typology = dict_type_code["SG002"];
                            break;
                        case "SG003":
                            course_type_name = "studio";
                            course_typology = dict_type_code["SG003"];
                            break;
                        case "SG004":
                            course_type_name = "workshop";
                            course_typology = dict_type_code["SG004"];
                            break;
                    }
                }

                Decimal total_course_average2_overall = 0, total_instructor_average2_overall = 0;

                DataTable dt_feedback_instruction_data = objmaster.Get_feedback_instruction_mst_data_report(course_typology, course_semester, course_year);
                DataTable dt_feedback_Faculty_avg_data = objmaster.Get_feedback_Faculty_avg_data(course_type_name, course_semester, course_year, course_dept_code);

                bool course_flag = false;
                bool instructor_flag = false;

                if (dt_feedback_Faculty_avg_data != null)
                {
                    DataRow[] dr_find_course_faculty_avg = dt_feedback_Faculty_avg_data.Select("related_feedback ='course'");

                    if (dr_find_course_faculty_avg.Length > 0)
                    {
                        dt_feedback_data.Rows[i]["overall_course_faculty_avg"] = dr_find_course_faculty_avg[0]["overall_average2"];
                    }
                    else
                    {
                        course_flag = true;
                    }

                    DataRow[] dr_find_instructor_faculty_avg = dt_feedback_Faculty_avg_data.Select("related_feedback ='instructor'");

                    if (dr_find_course_faculty_avg.Length > 0)
                    {
                        dt_feedback_data.Rows[i]["overall_instructor_Faculty_avg"] = dr_find_instructor_faculty_avg[0]["overall_average2"];
                    }
                    else
                    {
                        instructor_flag = true;
                    }
                }
                else
                {
                    course_flag = true;
                    instructor_flag = true;
                }

                if (course_flag == true || instructor_flag == true)
                {
                    median_course_data = objmaster.Get_feedback_median_data(course_semester, course_year);
                }

                if (course_flag == true)
                {
                    #region Find course Faculty Avg

                    DataRow[] dr_get_feedback_course = dt_feedback_instruction_data.Select("feedback_type ='course'");

                    if (dr_get_feedback_course.Length > 0)
                    {
                        for (int j = 0; j < dr_get_feedback_course.Length; j++)
                        {
                            if (dt_feedback_instruction_data.Rows[j]["feedback_type"].ToString() == "course")
                            {
                                DataRow[] dr_median_course = median_course_data.Select("releted_feedback = 'course' and sr_no ='" + dr_get_feedback_course[j]["sr_no"] + "' and course_type IN " + course_typology + " and dept_code ='" + course_dept_code + "'");
                                Decimal total_course_median_value = 0;

                                decimal total = 0;
                                decimal median_number = 0;

                                if (dr_median_course.Length > 0)
                                {
                                    total = dr_median_course.Length;

                                    median_number = (total + 1) / 2;

                                    string[] split_data = median_number.ToString().Split('.');

                                    for (int n = 0; n < dr_median_course.Length; n++)
                                    {
                                        total_course_median_value += Convert.ToDecimal(dr_median_course[n]["number"]);
                                    }

                                    total_course_average2_overall += Math.Round(total_course_median_value / total, 1, MidpointRounding.AwayFromZero);
                                }
                            }
                        }

                        if (total_course_average2_overall > 0)
                        {
                            dt_feedback_data.Rows[i]["overall_course_faculty_avg"] = Math.Round(total_course_average2_overall / dr_get_feedback_course.Length, 1, MidpointRounding.AwayFromZero);
                        }
                    }

                    #endregion
                }

                if (instructor_flag == true)
                {
                    #region Find Instructor Faculty Avg

                    DataRow[] dr_get_feedback_instructor = dt_feedback_instruction_data.Select("feedback_type ='instructor'");

                    if (dr_get_feedback_instructor.Length > 0)
                    {
                        for (int j = 0; j < dr_get_feedback_instructor.Length; j++)
                        {
                            DataRow[] dr_median_instructor = median_course_data.Select(" sr_no = '" + dr_get_feedback_instructor[j]["sr_no"] + "' and course_type IN " + course_typology + " and dept_code ='" + course_dept_code + "' and instructor_code <> '' and releted_feedback ='instructor' ", "sr_no ASC,number ASC");

                            Decimal total_instructor_median_value = 0;

                            decimal total = 0;
                            decimal median_number = 0;

                            if (dr_median_instructor.Length > 0)
                            {
                                total = dr_median_instructor.Length;

                                median_number = (total + 1) / 2;

                                string[] split_data = median_number.ToString().Split('.');

                                for (int n = 0; n < dr_median_instructor.Length; n++)
                                {
                                    total_instructor_median_value += Convert.ToDecimal(dr_median_instructor[n]["number"]);
                                }

                                total_instructor_average2_overall += Math.Round(total_instructor_median_value / total, 1, MidpointRounding.AwayFromZero);
                            }
                        }

                        if (total_instructor_average2_overall > 0)
                        {
                            dt_feedback_data.Rows[i]["overall_instructor_Faculty_avg"] = Math.Round(total_instructor_average2_overall / dr_get_feedback_instructor.Length, 1, MidpointRounding.AwayFromZero);
                        }
                    }

                    #endregion
                }
            }

            if (dt_feedback_data != null)
            {
                jsondata = GetJson1(dt_feedback_data);
            }
        }
        return jsondata;
    }

