    [WebMethod]
    public string Get_chart_data_for_registration(string year_code, string sem_code)
    {
        DataTable registration_data = objmaster.Get_Chart_data_for_registration(sem_code, year_code);

        DataTable cross_registration_data = objmaster.Get_Chart_data_for_cross_registration(sem_code, year_code);


        DataTable dt = new DataTable();
        dt.Columns.Add("registration");
        dt.Columns.Add("cross_registration");
        DataRow dr_reg = null;


        if (registration_data != null)
        {


            dr_reg = dt.NewRow();
            dr_reg["registration"] = registration_data.Rows.Count.ToString();

            dt.Rows.Add(dr_reg);



        }

        if (cross_registration_data != null)
        {
            if (dt.Rows.Count == 1)
            {
                dr_reg["cross_registration"] = cross_registration_data.Rows.Count.ToString();
            }
            else
            {
                dr_reg = dt.NewRow();
                dr_reg["cross_registration"] = cross_registration_data.Rows.Count.ToString();

                dt.Rows.Add(dr_reg);
            }


        }

        if (dt.Rows.Count > 0)
        {
            jsondata = GetJson1(dt);
        }

        return jsondata;
    }

