    [WebMethod(EnableSession = true)]
    public string Get_student_assigned_current_sem_data_for_feedback_dashboard()
    {

        //a obj = new a();
        //a obj1 = new b();
        //b obj2 = new b();

        //string aa = obj.Talk();
        //string bb = obj1.Talk();
        //string cc = obj2.Talk();

        //Rational r1 = new Rational(3, 2);
        //Rational r2 = new Rational(2, 3);

        //Rational result = null;

        //// Testing + operator on types
        //result = r1 + r2;


        //DataTable get_saved_data = objmaster.Get_student_assigned_current_sem_data(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Session["semester_code"].ToString(), current_feedback_sem, current_feedback_year);

        DataTable get_feedback_disable_data = objmaster.get_feedback_disable_course_data(current_feedback_sem, current_feedback_year, "");

        string disable_course = MakeInQueryString(get_feedback_disable_data, "course_code");

        DataTable get_saved_data = objmaster.Get_student_assigned_current_sem_data_for_feedback(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Session["semester_code"].ToString(), current_feedback_sem, current_feedback_year, disable_course);

        if (get_saved_data != null)
        {
            get_saved_data.Columns.Add("Status");
        }


        DataTable get_saved_feedbcak_data = objmaster.Get_student_saved_feedback_data_for_Feedback_dashboard("", HttpContext.Current.Session["UserId"].ToString(), current_feedback_sem, current_feedback_year);

        if (get_saved_feedbcak_data != null)
        {
            for (int i = 0; i < get_saved_data.Rows.Count; i++)
            {
                //string[] course = get_saved_data.Rows[i]["course"].ToString().Split('-');

                string[] course = get_saved_data.Rows[i]["course_code"].ToString().Split('~');

                DataRow[] dr = get_saved_feedbcak_data.Select("course_code = '" + course[0] + "'");

                if (dr.Length > 0)
                {
                    if (dr[0]["submit_status"].ToString() == "N")
                    {
                        if (dr[0]["last_modified_date"].ToString() != "")
                        {
                            get_saved_data.Rows[i]["Status"] = "Saved but not Complete";
                        }
