    [WebMethod(EnableSession = true)]
    public string Get_elective_course_data_for_student()
    {
        DataTable dt_elective = objmaster.Get_elective_current_sem_course_data_for_student_new1(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year, HttpContext.Current.Session["prog_level_code"].ToString());

        DataTable dt_elective_instructor = objmaster.Get_elective_instructor_data_for_student_new1(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year, HttpContext.Current.Session["prog_level_code"].ToString());

        DataTable dt_elective_time_day = objmaster.Get_elective_time_days_data_for_student_new1(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year, HttpContext.Current.Session["prog_level_code"].ToString());

        DataTable dt_elective_area = objmaster.Get_elective_Area_data_for_student_new1(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year, HttpContext.Current.Session["prog_level_code"].ToString());

        DataTable dt_saved_data = objmaster.Get_saved_student_course_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

        DataTable dt_registered_priority_data = objmaster.get_total_student_with_first_priority(current_ws_sem, current_ws_year);

        DataTable dt_course_type = objmaster.Get_courseTypemst_data();

        if (dt_elective != null)
        {
            for (int i = 0; i < dt_elective.Rows.Count; i++)
            {
                Ds_Student_Course_detail.student_elective_courseRow student_elective = obj_student.student_elective_course.Newstudent_elective_courseRow();

                string course_code = dt_elective.Rows[i]["course_code"].ToString();

                string instructor = "";
                string course_time = "";
                string time1 = "";
                string timing = "";
                string day = "";
                string area = "";
                string day1 = "";
                string course_day = "";

                student_elective.department = dt_elective.Rows[i]["dept_name"].ToString();
                student_elective.course_code = dt_elective.Rows[i]["course_code"].ToString();
                student_elective.course_name = dt_elective.Rows[i]["course_name"].ToString();
                student_elective.semester = dt_elective.Rows[i]["semester_code"].ToString();
                student_elective.credits = dt_elective.Rows[i]["course_credits"].ToString();
                student_elective.course_desc = dt_elective.Rows[i]["course_desc"].ToString();
                student_elective.prerequisite = dt_elective.Rows[i]["prerequisite"].ToString();
                student_elective.course_typology = dt_elective.Rows[i]["course_typology"].ToString();
                student_elective.course_outline = dt_elective.Rows[i]["course_outline"].ToString();
                student_elective.week1 = dt_elective.Rows[i]["week1"].ToString();
                student_elective.week2 = dt_elective.Rows[i]["week2"].ToString();
                student_elective.week3 = dt_elective.Rows[i]["week3"].ToString();
                student_elective.week4 = dt_elective.Rows[i]["week4"].ToString();
                student_elective.week5 = dt_elective.Rows[i]["week5"].ToString();
                student_elective.week6 = dt_elective.Rows[i]["week6"].ToString();
                student_elective.week7 = dt_elective.Rows[i]["week7"].ToString();
                student_elective.week8 = dt_elective.Rows[i]["week8"].ToString();
                student_elective.week9 = dt_elective.Rows[i]["week9"].ToString();
                student_elective.week10 = dt_elective.Rows[i]["week10"].ToString();
                student_elective.week11 = dt_elective.Rows[i]["week11"].ToString();
                student_elective.week12 = dt_elective.Rows[i]["week12"].ToString();
                student_elective.week13 = dt_elective.Rows[i]["week13"].ToString();
                student_elective.week14 = dt_elective.Rows[i]["week14"].ToString();
                student_elective.week15 = dt_elective.Rows[i]["week15"].ToString();
                student_elective.week16 = dt_elective.Rows[i]["week16"].ToString();

                student_elective.course_structure = dt_elective.Rows[i]["course_structure"].ToString();

                student_elective.remark = dt_elective.Rows[i]["remark"].ToString();
                student_elective.eval_method1 = dt_elective.Rows[i]["eval_method1"].ToString();
                student_elective.eval_method4 = dt_elective.Rows[i]["eval_method4"].ToString();
                student_elective.eval_method5 = dt_elective.Rows[i]["eval_method5"].ToString();

                student_elective.gpa_ngpa = dt_elective.Rows[i]["gpa_ngpa"].ToString();

                if (dt_saved_data != null)
                {
                    DataRow[] dr_elec = dt_saved_data.Select("course_code = '" + course_code + "' and course_type = 'E' and dept_code ='" + dt_elective.Rows[i]["dept_code"].ToString() + "'");

                    if (dr_elec.Length > 0)
                    {
                        if (dr_elec[0]["doc_no"].ToString() != "")
                        {
                            student_elective.doc_no = dr_elec[0]["doc_no"].ToString();
                        }
                    }
                }

                if (dt_course_type != null)
                {
                    DataRow[] dr_type = dt_course_type.Select("type_code ='" + dt_elective.Rows[i]["course_typology"].ToString() + "'");

                    if (dr_type.Length > 0)
                    {
                        if (dr_type[0]["type_name"].ToString() != "")
                        {
                            student_elective.Course_type_name = dr_type[0]["type_name"].ToString();
                        }
                    }
                }

                if (dt_elective_area != null)
                {
                    DataRow[] dr = dt_elective_area.Select("course_code = '" + course_code + "' and area_code in ('11','33','34') ");

                    if (dr.Length > 0 && dr != null)
                    {
                        continue;
                    }
                    else
                    {
                        DataRow[] dr_area = dt_elective_area.Select("course_code = '" + course_code + "' ");

                        for (int j = 0; j < dr_area.Length; j++)
                        {
                            area += dr_area[j]["area_name"].ToString() + ", ";
                        }

                        if (area != String.Empty)
                            student_elective.area = area.Trim().TrimEnd(',');
                    }
                }

                if (dt_elective_instructor != null)
                {
                    DataRow[] dr_instructor = dt_elective_instructor.Select("course_code = '" + course_code + "'");

                    if (dr_instructor.Length > 0 && dr_instructor != null)
                    {
                        for (int j = 0; j < dr_instructor.Length; j++)
                        {
                            instructor += dr_instructor[j]["instructor_name"].ToString() + ", ";
                        }

                        if (instructor != String.Empty)
                            student_elective.instructor = instructor.Trim().TrimEnd(',');
                    }
                }

                if (dt_elective_time_day != null)
                {
                    DataRow[] dr_time = dt_elective_time_day.Select("course_code = '" + course_code + "'");

                    if (dr_time.Length > 0 && dr_time != null)
                    {
                        for (int j = 0; j < dr_time.Length; j++)
                        {
                            timing = dr_time[j]["time"].ToString();
                            course_day = dr_time[j]["day_name"].ToString();

                            if (timing != time1 || day1 != course_day)
                            {
                                course_time += dr_time[j]["time"].ToString() + ", ";
                            }

                            day += dr_time[j]["day_name"].ToString() + ", ";
                            time1 = dr_time[j]["time"].ToString();
                            day1 = dr_time[j]["day_name"].ToString();
                        }

                        if (course_time != String.Empty)
                            student_elective.time = course_time.Trim().TrimEnd(',');

                        if (day != String.Empty)
                            student_elective.days = day.Trim().TrimEnd(',');
                    }
                }

                if (dt_registered_priority_data != null)
                {
                    DataRow[] dr_priority = dt_registered_priority_data.Select("course_code = '" + course_code + "'");
                    if (dr_priority.Length > 0)
                    {
                        student_elective.total_reg_student = dr_priority[0]["total_student"].ToString();
                        student_elective.total_priority = dr_priority[0]["total_priority"].ToString();
                    }
                    else
                    {
                        student_elective.total_reg_student = "0";
                        student_elective.total_priority = "0";
                    }
                }
                else
                {
                    student_elective.total_reg_student = "0";
                    student_elective.total_priority = "0";
                }

                obj_student.student_elective_course.Addstudent_elective_courseRow(student_elective);
            }

            DataTable dt = obj_student.student_elective_course;

            if (dt.Rows.Count > 0)
            {
                DataColumn dc1 = new DataColumn("semester_type", typeof(string));
                dc1.DefaultValue = dt_elective.Rows[0]["semester_type"].ToString();
                dt.Columns.Add(dc1);

                DataColumn dc2 = new DataColumn("year_semester", typeof(string));
                dc2.DefaultValue = dt_elective.Rows[0]["year_semester"].ToString();
                dt.Columns.Add(dc2);
            }

            DataTable dtOut = null;
            dt.DefaultView.Sort = "course_code";
            dtOut = dt.DefaultView.ToTable();

            if (dtOut.Rows.Count > 0)
            {
                jsondata = GetJson1(dtOut);
            }
            else
            {
                return "no data";
            }
        }
        else
        {
            return "no data";
        }

        return jsondata;
    }

