    [WebMethod(EnableSession = true)]
    public string Check_time_validation(string mandatory_time, string elective_time, string course_code, string sem_code, string flag)
    {
        Masters objmaster = new Masters();

        int re = 0;
        String[] st = new String[6];

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            #region  check  Successful completion of course required (pass or fial)

            string pre_course_code = "";

            DataTable course_mst_detail = objmaster.Get_course_data_for_modification(current_ws_sem, current_ws_year, course_code);

            if (course_mst_detail != null)
            {
                Dictionary<string, string> pre_course_data = ser.Deserialize<Dictionary<string, string>>(course_mst_detail.Rows[0]["prerequisite"].ToString());
                if (pre_course_data.Count > 0)
                {
                    try
                    {
                        pre_course_code = pre_course_data["pre_course_code"].ToString();
                    }
                    catch (Exception)
                    {
                    }
                }
            }

            if (pre_course_code != "")
            {
                Dictionary<string, string> objparam = new Dictionary<string, string>();
                objparam.Add("user_id", HttpContext.Current.Session["UserId"].ToString());
                objparam.Add("course_code", pre_course_code);

                DataTable dt_pass_fail = objmaster.Get_course_time_day_data_for_catalog_report(objparam);

                if (dt_pass_fail != null)
                {
                    string pass_flag = "F";

                    for (int pf = 0; pf < dt_pass_fail.Rows.Count; pf++)
                    {
                        if (dt_pass_fail.Rows[pf]["result"].ToString() == "PASS")
                        {
                            pass_flag = "P";
                            break;
                        }
                    }

                    if (pass_flag == "F")
                    {
                        return "You can not select this course because you have not passed the course : " + pre_course_code;
                    }
                }
                else
                {
                    return "You can not select this course because you have not passed the course : " + pre_course_code;
                }
            }

            #endregion

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(mandatory_time);

            List<Dictionary<string, object>> elective_data = ser.Deserialize<List<Dictionary<string, object>>>(elective_time);

            DataTable dt_mandatory_time_day = objmaster.Get_mandatory_time_days_data_for_student(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year);

            DataTable dt_elective_time_day = objmaster.Get_elective_time_days_data_for_student_new1(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year, HttpContext.Current.Session["prog_level_code"].ToString());

            if (flag == "M")
            {
                if (dt_mandatory_time_day != null)
                {
                    DataRow[] dr = dt_mandatory_time_day.Select("course_code = '" + course_code + "' and semester_code ='" + sem_code + "'");

                    if (dr.Length > 0 && dr != null)
                    {
                        for (int i = 0; i < data.Count; i++)
                        {
                            if (course_code == data[i]["course_code"].ToString())
                            {
                            }
                            else
                            {
                                if ((course_code == "2015" && data[i]["course_code"].ToString() == "2044") || (course_code == "2044" && data[i]["course_code"].ToString() == "2015") || (course_code == "2008" && data[i]["course_code"].ToString() == "2060") || (course_code == "2060" && data[i]["course_code"].ToString() == "2008"))
                                {
                                }
                                else
                                {
                                    DataRow[] dr_check = dt_mandatory_time_day.Select("course_code='" + data[i]["course_code"].ToString() + "' and semester_code ='" + data[i]["semester_code"].ToString() + "' ");

                                    if (dr_check.Length > 0 && dr_check != null)
                                    {
                                        for (int j = 0; j < dr.Length; j++)
                                        {
                                            string last_from_time = dr[j]["from_time"].ToString();
                                            string last_to_time = dr[j]["to_time"].ToString();
                                            string last_day_code = dr[j]["day_code"].ToString();

                                            for (int k = 0; k < dr_check.Length; k++)
                                            {
                                                string from_time = dr_check[k]["from_time"].ToString();
                                                string to_time = dr_check[k]["to_time"].ToString();
                                                string day_code = dr_check[k]["day_code"].ToString();

                                                if (last_day_code == day_code)
                                                {
                                                    if (Convert.ToDecimal(last_from_time.Replace(':', '.')) > Convert.ToDecimal(from_time.Replace(':', '.')) && Convert.ToDecimal(last_from_time.Replace(':', '.')) < Convert.ToDecimal(to_time.Replace(':', '.')))
                                                    {
                                                        return "You can not select this Course. Course " + course_code + " timing Conflicts with Course " + data[i]["course_code"].ToString();
                                                    }

                                                    if (Convert.ToDecimal(last_to_time.Replace(':', '.')) > Convert.ToDecimal(from_time.Replace(':', '.')) && Convert.ToDecimal(last_to_time.Replace(':', '.')) < Convert.ToDecimal(to_time.Replace(':', '.')))
                                                    {
                                                        return "You can not select this Course. Course " + course_code + " timing Conflicts with Course " + data[i]["course_code"].ToString();
                                                    }

                                                    if (Convert.ToDecimal(last_from_time.Replace(':', '.')) == Convert.ToDecimal(from_time.Replace(':', '.')))
                                                    {
                                                        return "You can not select this Course. Course " + course_code + " timing Conflicts with Course " + data[i]["course_code"].ToString();
                                                    }

                                                    if (Convert.ToDecimal(last_to_time.Replace(':', '.')) == Convert.ToDecimal(to_time.Replace(':', '.')))
                                                    {
                                                        return "You can not select this Course. Course " + course_code + " timing Conflicts with Course " + data[i]["course_code"].ToString();
                                                    }

                                                    if (Convert.ToDecimal(from_time.Replace(':', '.')) > Convert.ToDecimal(last_from_time.Replace(':', '.')) && Convert.ToDecimal(last_to_time.Replace(':', '.')) > Convert.ToDecimal(to_time.Replace(':', '.')))
                                                    {
                                                        return "ok:This Course " + course_code + " timing Conflicts with Course " + elective_data[i]["course_code"].ToString();
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        if (dt_elective_time_day != null)
                        {
                            for (int i = 0; i < elective_data.Count; i++)
                            {
                                DataRow[] dr_check = dt_elective_time_day.Select("course_code='" + elective_data[i]["course_code"].ToString() + "' and semester_code ='" + elective_data[i]["semester_code"].ToString() + "' ");

                                if (dr_check.Length > 0 && dr_check != null)
                                {
                                    for (int j = 0; j < dr.Length; j++)
                                    {
                                        string last_from_time = dr[j]["from_time"].ToString();
                                        string last_to_time = dr[j]["to_time"].ToString();
                                        string last_day_code = dr[j]["day_code"].ToString();

                                        for (int k = 0; k < dr_check.Length; k++)
                                        {
                                            string from_time = dr_check[k]["from_time"].ToString();
                                            string to_time = dr_check[k]["to_time"].ToString();
                                            string day_code = dr_check[k]["day_code"].ToString();

                                            if (last_day_code == day_code)
                                            {
                                                if (Convert.ToDecimal(last_from_time.Replace(':', '.')) > Convert.ToDecimal(from_time.Replace(':', '.')) && Convert.ToDecimal(last_from_time.Replace(':', '.')) < Convert.ToDecimal(to_time.Replace(':', '.')))
                                                {
                                                    return "You can not select this Course. Mandatory Course " + course_code + " timing Conflicts with elective Course " + elective_data[i]["course_code"].ToString();
                                                }

                                                if (Convert.ToDecimal(last_to_time.Replace(':', '.')) > Convert.ToDecimal(from_time.Replace(':', '.')) && Convert.ToDecimal(last_to_time.Replace(':', '.')) < Convert.ToDecimal(to_time.Replace(':', '.')))
                                                {
                                                    return "You can not select this Course. Mandatory Course " + course_code + " timing Conflicts with elective Course " + elective_data[i]["course_code"].ToString();
                                                }

                                                if (Convert.ToDecimal(last_from_time.Replace(':', '.')) == Convert.ToDecimal(from_time.Replace(':', '.')))
                                                {
                                                    return "You can not select this Course. Mandatory Course " + course_code + " timing Conflicts with elective Course " + elective_data[i]["course_code"].ToString();
                                                }

                                                if (Convert.ToDecimal(last_to_time.Replace(':', '.')) == Convert.ToDecimal(to_time.Replace(':', '.')))
                                                {
