                                                if (Convert.ToDecimal(from_time.Replace(':', '.')) > Convert.ToDecimal(last_from_time.Replace(':', '.')) && Convert.ToDecimal(last_to_time.Replace(':', '.')) > Convert.ToDecimal(to_time.Replace(':', '.')))
                                                {
