    [WebMethod(EnableSession = true)]
    public string[] Get_fees_status_new()
    {
        DataTable fees_status = objmaster.Get_fees_status_for_student(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Session["semester_code"].ToString(), current_ws_sem, current_ws_year);

        string total_selected_credits = "0";

        if (fees_status != null)
        {
            if (fees_status.Rows[0]["fees_status"].ToString() != "")
            {
                string flag = objmaster.get_user_fees_selection_rights(Session["year_code"].ToString());

                DataTable dt_fees_type_save_by_student = objmaster.Get_student_fees_type_saved_data_for_before_paid_fees(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

                if (flag == "Y")
                {
                    if (dt_fees_type_save_by_student != null)
                    {
                        if (dt_fees_type_save_by_student.Rows[0]["fees_status"].ToString() == "F")
                        {
                            if (dt_fees_type_save_by_student.Rows[0]["credit_choice"].ToString() != "")
                            {
                                total_selected_credits = dt_fees_type_save_by_student.Rows[0]["credit_choice"].ToString();
                            }
                            else
                            {
                                total_selected_credits = "20";
                            }
                        }
                        else if (dt_fees_type_save_by_student.Rows[0]["fees_status"].ToString() == "H")
                        {
                            if (dt_fees_type_save_by_student.Rows[0]["credit_selected"].ToString() != "")
                            {
                                total_selected_credits = dt_fees_type_save_by_student.Rows[0]["credit_selected"].ToString();
                            }
                        }
                    }
                    else
                    {
                        total_selected_credits = "20";
                    }
                }
                else
                {
                    if (fees_status.Rows[0]["fees_status"].ToString() == "F")
                    {
                        if (dt_fees_type_save_by_student != null)
                        {
                            if (dt_fees_type_save_by_student.Rows[0]["credit_choice"].ToString() != "")
                            {
                                total_selected_credits = dt_fees_type_save_by_student.Rows[0]["credit_choice"].ToString();
                            }
                            else
                            {
                                total_selected_credits = "20";
                            }
                        }
                        else
                        {
                            total_selected_credits = "20";
                        }
                    }
                }
            }

            jsonarray[0] = GetJson1(fees_status);
            jsonarray[1] = total_selected_credits;

            DataTable dt_user_fees_choice_bifurcation_dtl = objmaster.Get_user_fees_choice_bifurcation_dtl(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);
            if (dt_user_fees_choice_bifurcation_dtl != null)
            {
                jsonarray[2] = GetJson1(dt_user_fees_choice_bifurcation_dtl);
            }
            else
            {
                jsonarray[2] = "";
            }

            DataTable dt_registration_data = objmaster.check_student_allocate_current_sem_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

            if (dt_registration_data != null)
            {
                jsonarray[3] = "Registered";
            }
            else
            {
                jsonarray[3] = "";
            }

            if (HttpContext.Current.Session["year_code"] != null)
            {
                jsonarray[4] = HttpContext.Current.Session["year_code"].ToString();
            }
            else
            {
                jsonarray[4] = "";
            }

            //Mayur 06072021
            //DataTable dt_credit_combination_dtl = objmaster.Get_credit_combination_dtl(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);
            //if (dt_credit_combination_dtl != null)
            //{
            //    jsonarray[5] = GetJson1(dt_credit_combination_dtl);
            //}
            //else
            //{
            //    jsonarray[5] = "";
            //}
            //Mayur 06072021
        }

        return jsonarray;
    }

