    [WebMethod(EnableSession = true)]
    public string get_instructor_details_course_wise(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code)//Ananth 02052019
    {
        DataTable get_allocate_course_data = objmaster.get_allocate_dtl_prog_dept_wise_for_faculty_report(sem_code, year_code);
        DataTable get_instructor_course_data = objmaster.get_instructor_dtl_for_faculty_report(sem_code, year_code, dept_code, prog_code, prog_level_code);

        string directory_path = @"C:/Ceptreg_Log/temp.txt";

        if (get_instructor_course_data != null)
        {

            System.IO.File.WriteAllText(directory_path, "get_instructor_course_data.Rows.Count : " + get_instructor_course_data.Rows.Count + Environment.NewLine);

        }
        decimal total_course = 0;

        if (get_instructor_course_data != null)
        {
            System.IO.File.WriteAllText(directory_path, "get_instructor_course_data.Rows.Count : " + get_instructor_course_data.Rows.Count + Environment.NewLine);

            for (int i = 0; i < get_instructor_course_data.Rows.Count; i++)
            {
                String course_code = get_instructor_course_data.Rows[i]["course_code"].ToString().Trim();

                if (course_code == "2526")
                {
                }

                Ds_Student_Course_detail.faculty_detailsRow total_report = obj_student.faculty_details.Newfaculty_detailsRow();

                total_course = 0;
                total_report.sr_no = i + 1;
                total_report.instructor_code = get_instructor_course_data.Rows[i]["instructor_code"].ToString();
                total_report.name = get_instructor_course_data.Rows[i]["instructor_name"].ToString();
                total_report.course_code = course_code;
                total_report.typology = get_instructor_course_data.Rows[i]["type_name"].ToString();
                total_report.course_type = get_instructor_course_data.Rows[i]["course_type"].ToString();
                total_report.course_name = get_instructor_course_data.Rows[i]["course_name"].ToString();
                total_report.course_credits = get_instructor_course_data.Rows[i]["course_credits"].ToString();
                total_report.instructor_contact_hrs = get_instructor_course_data.Rows[i]["instructor_contact_hrs"].ToString();
                total_report.percent_load = get_instructor_course_data.Rows[i]["percent_load"].ToString();
                //total_report.designation = get_instructor_course_data.Rows[i]["designation"].ToString();
                total_report.dept_name = get_instructor_course_data.Rows[i]["dept_name"].ToString();
                total_report.prog_name = get_instructor_course_data.Rows[i]["prog_name"].ToString();

                if (get_allocate_course_data != null)
                {
                    DataRow[] dr = get_allocate_course_data.Select("course_code = '" + course_code + "'");

                    if (dr.Length > 0)
                    {
                        for (int j = 0; j < dr.Length; j++)
                        {
                            if (dr[j]["dept_code"].ToString() == "1")
                            {
                                if (dr[j]["prog_code"].ToString() == "1")
                                {
                                    total_report.FA_UG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "2")
                                {
                                    total_report.FA_PG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "3")
                                {
                                    total_report.FA_PHD = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                            }
                            else if (dr[j]["dept_code"].ToString() == "2")
                            {
                                if (dr[j]["prog_code"].ToString() == "1")
                                {
                                    total_report.FD_UG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "2")
                                {
                                    total_report.FD_PG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                            }
                            else if (dr[j]["dept_code"].ToString() == "3")
                            {
                                if (dr[j]["prog_code"].ToString() == "1")
                                {
                                    total_report.FM_UG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "2")
                                {
                                    total_report.FM_PG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                            }
                            else if (dr[j]["dept_code"].ToString() == "4")
                            {
                                if (dr[j]["prog_code"].ToString() == "1")
                                {
                                    total_report.FP_UG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "2")
                                {
                                    total_report.FP_PG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "3")
                                {
                                    total_report.FP_PHD = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                            }
                            else if (dr[j]["dept_code"].ToString() == "5")
                            {
                                if (dr[j]["prog_code"].ToString() == "1")
                                {
                                    total_report.FT_UG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                                else if (dr[j]["prog_code"].ToString() == "2")
                                {
                                    total_report.FT_PG = dr[j]["progcode"].ToString();
                                    total_course += Convert.ToDecimal(dr[j]["progcode"].ToString());
                                }
                            }
                        }
                    }
                }

                total_report.total_course = total_course;

                obj_student.faculty_details.Addfaculty_detailsRow(total_report);
            }

            DataTable dt = obj_student.faculty_details;

            System.IO.File.WriteAllText(directory_path, "obj_student.faculty_details : " + obj_student.faculty_details + Environment.NewLine);

            if (dt != null)
            {
                var user_id = HttpContext.Current.Session["UserId"].ToString();
                var user_type = HttpContext.Current.Session["user_type"].ToString();

                dt.Columns.Add("total_contact_hrs");
                dt.Columns.Add("total_preparation_hrs");
                dt.Columns.Add("rate_band");
                dt.Columns.Add("total_amount_paid");

                DataTable vising_faculty_data = objmaster.get_authorize_detail(sem_code, year_code, user_id, "Faculty_Report|-");

                if (vising_faculty_data != null)
                {
                    //vising_faculty_data = vising_faculty_data.Select("hr_approved='Y'").CopyToDataTable();

                    vising_faculty_data.Columns.Add("total_amount_paid");

                    for (int i = 0; i < vising_faculty_data.Rows.Count; i++)
                    {
                        if (vising_faculty_data.Rows[i]["rate_band"].ToString() != "" && vising_faculty_data.Rows[i]["total_hrs_in_semester"].ToString() != "")
                        {
                            vising_faculty_data.Rows[i]["total_amount_paid"] = (Convert.ToDouble(vising_faculty_data.Rows[i]["rate_band"].ToString()) * Convert.ToDouble(vising_faculty_data.Rows[i]["total_hrs_in_semester"].ToString())).ToString();
                        }
                    }

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        DataRow[] dr_visiting_faculty_data = vising_faculty_data.Select("instructor_code='" + dt.Rows[i]["instructor_code"] + "' and course_code='" + dt.Rows[i]["course_code"] + "'");

                        if (dr_visiting_faculty_data.Length > 0)
                        {
                            dt.Rows[i]["total_contact_hrs"] = dr_visiting_faculty_data[0]["total_contact_hrs"].ToString();
                            dt.Rows[i]["total_preparation_hrs"] = dr_visiting_faculty_data[0]["total_preparation_hrs"].ToString();
                            dt.Rows[i]["rate_band"] = dr_visiting_faculty_data[0]["rate_band"].ToString();
                            dt.Rows[i]["total_amount_paid"] = dr_visiting_faculty_data[0]["total_amount_paid"].ToString();
                        }
                    }
                }

                jsondata = GetJson1(dt);
            }
        }

        return jsondata;
    }

