    [WebMethod]
    public string[] Get_all_student_data_for_manaally_allocation(string year_code, string dept_code, string prog_code, string sem_code, string course_code, string prog_level = "", string batch_year = "")
    {
        //DataTable Get_student_data = objmaster.Get_student_data_new("", dept_code, prog_code);
        DataTable Get_student_data = objmaster.Get_student_data_new(batch_year, dept_code, prog_code, prog_level);

