    [WebMethod]
    public string get_registration_report_data(string dept_code, string semester, string year_code)
    {

        DataTable get_data = new DataTable();
        DataTable sws_get_data = new DataTable();

        get_data = objmaster.get_registration_report_data_after_allocation(dept_code, semester, year_code);

        if (get_data == null)
        {
            get_data = objmaster.get_registration_report_data(dept_code, semester, year_code);
        }

        if (get_data != null)
        {
            sws_get_data = objmaster.Get_user_fees_choice_bifurcation_dtl("", semester, year_code);
        }


        DataTable dt = new DataTable();

        dt.Columns.Add("code");
        dt.Columns.Add("name");
        dt.Columns.Add("elective_course");
        dt.Columns.Add("elective_credits");
        dt.Columns.Add("mandatory_course");
        dt.Columns.Add("mandatory_credits");
        dt.Columns.Add("sws_credits");

        //dt.Columns.Add("total_credits");

        string user_id = "";

        DataRow dr;


        if (get_data != null)
        {

            for (int i = 0; i < get_data.Rows.Count; i++)
            {
                if (user_id != get_data.Rows[i]["user_id"].ToString())
                {
                    string sws_creadit = "";
                    if (sws_get_data != null)
                    {
                        DataRow[] sws_dr = sws_get_data.Select("user_id = '" + get_data.Rows[i]["user_id"].ToString() + "'");
                        if (sws_dr.Length > 0)
                        {
                            sws_creadit = sws_dr[0]["sws_credits"].ToString();
                        }

                    }


                    if (get_data.Rows[i]["course_type"].ToString() == "E")
                    {
                        dr = dt.NewRow();
                        dr["code"] = get_data.Rows[i]["user_id"].ToString();
                        dr["name"] = get_data.Rows[i]["user_name"].ToString();
                        dr["elective_course"] = get_data.Rows[i]["course_code"].ToString();
