    [WebMethod]
    public string get_assigned_report_data(string dept_code, string semester, string year_code, string prog_level_code)
    {
        DataTable get_data = objmaster.get_assigned_report_data(dept_code, semester, year_code, prog_level_code);

        DataTable dt = new DataTable();

        dt.Columns.Add("code");
        dt.Columns.Add("name");
        //add column akshy
        dt.Columns.Add("mail");
        dt.Columns.Add("applicant_mobile_no");

        dt.Columns.Add("student_level");
        dt.Columns.Add("student_faculty");
        dt.Columns.Add("gender");
        dt.Columns.Add("elective_course");
        dt.Columns.Add("elective_credits");
        dt.Columns.Add("mandatory_course");
        dt.Columns.Add("mandatory_credits");
        dt.Columns.Add("prog_level_name");
        dt.Columns.Add("prog_level_code");
        dt.Columns.Add("prog_level_desc");
        dt.Columns.Add("BachCode");
        dt.Columns.Add("AdmissionYear");
        //dt.Columns.Add("total_credits");

        string user_id = "";

        DataRow dr;

        if (get_data != null)
        {
            for (int i = 0; i < get_data.Rows.Count; i++)
            {
                string a = get_data.Rows[i]["user_id"].ToString();

                if (a == "PA100513")
                {
                }

                if (user_id != get_data.Rows[i]["user_id"].ToString())
                {
                    if (get_data.Rows[i]["course_type"].ToString() == "E")
                    {
                        dr = dt.NewRow();

                        dr["code"] = get_data.Rows[i]["user_id"].ToString();
                        dr["name"] = get_data.Rows[i]["user_name"].ToString();

                        dr["mail"] = get_data.Rows[i]["mail"].ToString();
                        dr["applicant_mobile_no"] = get_data.Rows[i]["applicant_mobile_no"].ToString();

                        dr["student_level"] = get_data.Rows[i]["prog_name"].ToString();
                        dr["student_faculty"] = get_data.Rows[i]["dept_name"].ToString();
                        dr["gender"] = get_data.Rows[i]["gender"].ToString();
                        dr["elective_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr["elective_credits"] = get_data.Rows[i]["credits"].ToString();
                        dr["prog_level_name"] = get_data.Rows[i]["prog_level_name"].ToString();
                        dr["prog_level_code"] = get_data.Rows[i]["prog_level_code"].ToString();
                        dr["prog_level_desc"] = get_data.Rows[i]["prog_level_desc"].ToString();
                        dr["BachCode"] = get_data.Rows[i]["year_code"].ToString();
                        dr["AdmissionYear"] = get_data.Rows[i]["admission_year"].ToString();

                        dt.Rows.Add(dr);
                    }
                    else
                    {
                        dr = dt.NewRow();

                        dr["code"] = get_data.Rows[i]["user_id"].ToString();
                        dr["name"] = get_data.Rows[i]["user_name"].ToString();

                        dr["mail"] = get_data.Rows[i]["mail"].ToString();
                        dr["applicant_mobile_no"] = get_data.Rows[i]["applicant_mobile_no"].ToString();

                        dr["student_level"] = get_data.Rows[i]["prog_name"].ToString();
                        dr["student_faculty"] = get_data.Rows[i]["dept_name"].ToString();
                        dr["gender"] = get_data.Rows[i]["gender"].ToString();
                        dr["mandatory_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr["mandatory_credits"] = get_data.Rows[i]["credits"].ToString();
                        dr["prog_level_name"] = get_data.Rows[i]["prog_level_name"].ToString();
                        dr["prog_level_code"] = get_data.Rows[i]["prog_level_code"].ToString();
                        dr["prog_level_desc"] = get_data.Rows[i]["prog_level_desc"].ToString();
                        dr["BachCode"] = get_data.Rows[i]["year_code"].ToString();
                        dr["AdmissionYear"] = get_data.Rows[i]["admission_year"].ToString();

                        dt.Rows.Add(dr);
                    }
                }
                else
                {
                    DataRow[] dr1 = dt.Select("code = '" + get_data.Rows[i]["user_id"].ToString() + "'");

                    if (dr1.Length > 0)
                    {
                        dr1[0]["mandatory_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr1[0]["mandatory_credits"] = get_data.Rows[i]["credits"].ToString();
                        //dr1[0]["total_course"] = Convert.ToInt32(dr1[0]["mandatory_course"]) + Convert.ToInt32(dr1[0]["elective_course"]);
                        //dr1[0]["total_credits"] = Convert.ToInt32(dr1[0]["mandatory_credits"]) + Convert.ToInt32(dr1[0]["elective_credits"]);
                    }
                }

                user_id = get_data.Rows[i]["user_id"].ToString();
            }

            if (dt != null)
            {
                jsondata = GetJson1(dt);
            }
        }

        return jsondata;
    }

    [WebMethod]
    public string get_financial_report_data(string dept_code, string semester, string year_code)
    {
        DataTable get_data = objmaster.get_financial_report_data(dept_code, semester, year_code);

        DataTable get_fees_data = objmaster.Get_manually_fees_status(semester, year_code);

        DataTable get_online_fees_data = objmaster.Get_online_fees_status(semester, year_code);

        DataTable get_replacement_user_data = objmaster.get_replacement_user_data(semester, year_code);

        DataTable dt = new DataTable();

        dt.Columns.Add("code");
        dt.Columns.Add("application_id");
        dt.Columns.Add("name");
        dt.Columns.Add("year_desc");
        dt.Columns.Add("department_name");
        dt.Columns.Add("program");
        dt.Columns.Add("gender");
        dt.Columns.Add("elective_credits");
        dt.Columns.Add("mandatory_credits");
        dt.Columns.Add("total_credits");
        dt.Columns.Add("semester_type");
        dt.Columns.Add("year_semester");
        dt.Columns.Add("fees_status");
        dt.Columns.Add("fees_date");
        dt.Columns.Add("payment_mode");
        dt.Columns.Add("payment_reference");

        //dt.Columns.Add("total_credits");

        string user_id = "";

        DataRow dr;

        Decimal total_credits = 0;


        if (get_data != null)
        {

            for (int i = 0; i < get_data.Rows.Count; i++)
            {
                string a = get_data.Rows[i]["user_id"].ToString();

                if (a == "13141550014")
                {

                }

                if (user_id != get_data.Rows[i]["user_id"].ToString())
                {
                    dr = dt.NewRow();

                    total_credits = 0;

                    dr["code"] = get_data.Rows[i]["user_id"].ToString();
                    dr["name"] = get_data.Rows[i]["user_name"].ToString();
                    dr["year_desc"] = get_data.Rows[i]["year_desc"].ToString();
                    dr["department_name"] = get_data.Rows[i]["dept_name"].ToString();
                    dr["program"] = get_data.Rows[i]["prog_name"].ToString();
                    dr["gender"] = get_data.Rows[i]["gender"].ToString();
                    dr["year_semester"] = year_code;
                    dr["elective_credits"] = "0";
                    if (semester == "M")
                    {
                        dr["semester_type"] = "Monsoon";
                    }
                    else
                    {
                        dr["semester_type"] = "Spring";
                    }


                    DataRow[] dr_fees = get_fees_data.Select("user_id = '" + get_data.Rows[i]["user_id"].ToString() + "'");

                    if (dr_fees.Length > 0)
                    {
                        if (get_online_fees_data != null)
                        {

                            DataRow[] dr_online_fees = get_online_fees_data.Select("user_id = '" + get_data.Rows[i]["user_id"].ToString() + "'");

                            if (dr_online_fees.Length > 0)
                            {
                                dr["fees_date"] = dr_online_fees[0]["date"];
                                dr["payment_mode"] = "Online";
                                dr["payment_reference"] = dr_online_fees[0]["payment_transaction_reference_id"];

                                dr["fees_status"] = dr_online_fees[0]["amount"];
                            }
                            else
                            {
                                dr["fees_date"] = dr_fees[0]["date"];
                                dr["payment_mode"] = "ICICI";

                                dr["fees_status"] = dr_fees[0]["fees_amount"];

                            }
                        }
                        else
                        {
                            dr["fees_date"] = dr_fees[0]["date"];
                            dr["payment_mode"] = "ICICI";

                            dr["fees_status"] = dr_fees[0]["fees_amount"];
                        }
                    }
                    if (get_replacement_user_data != null)
                    {
                        DataRow[] dr_replace_user_id = get_replacement_user_data.Select("new_user_id = '" + get_data.Rows[i]["user_id"].ToString() + "'");

                        if (dr_replace_user_id.Length > 0)
                        {
                            dr["application_id"] = dr_replace_user_id[0]["old_user_id"];
                        }
                    }

                    if (get_data.Rows[i]["course_type"].ToString() == "E")
                    {
                        //dr["elective_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr["elective_credits"] = get_data.Rows[i]["credits"].ToString();

                        total_credits += Convert.ToDecimal(get_data.Rows[i]["credits"].ToString());

                        dr["total_credits"] = total_credits.ToString();

                        dt.Rows.Add(dr);
                    }
                    else
                    {
                        //dr = dt.NewRow();



                        //dr["code"] = get_data.Rows[i]["user_id"].ToString();
                        //dr["name"] = get_data.Rows[i]["user_name"].ToString();

                        // dr["mandatory_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr["mandatory_credits"] = get_data.Rows[i]["credits"].ToString();

                        total_credits += Convert.ToDecimal(get_data.Rows[i]["credits"].ToString());

                        dr["total_credits"] = total_credits.ToString();

                        dt.Rows.Add(dr);
                    }





                }
                else
                {
                    DataRow[] dr1 = dt.Select("code = '" + get_data.Rows[i]["user_id"].ToString() + "'");

                    if (dr1.Length > 0)
                    {
                        //  dr1[0]["mandatory_course"] = get_data.Rows[i]["course_code"].ToString();
                        dr1[0]["mandatory_credits"] = get_data.Rows[i]["credits"].ToString();

                        total_credits += Convert.ToDecimal(get_data.Rows[i]["credits"].ToString());

                        dr1[0]["total_credits"] = total_credits.ToString();
                        //dr1[0]["total_course"] = Convert.ToInt32(dr1[0]["mandatory_course"]) + Convert.ToInt32(dr1[0]["elective_course"]);
                        //dr1[0]["total_credits"] = Convert.ToInt32(dr1[0]["mandatory_credits"]) + Convert.ToInt32(dr1[0]["elective_credits"]);

                    }

                }


                user_id = get_data.Rows[i]["user_id"].ToString();

            }





            if (dt != null)
            {
                jsondata = GetJson1(dt);
            }
        }
        return jsondata;
    }

