    [WebMethod(EnableSession = true)]
    public string insert_update_fine_dtl(string semeter_type, string year_code, string user_id, string remarks, string installmentfine, string installment_no)
    {
        Dictionary<string, object> param = new Dictionary<string, object>();
        Boolean status = true;
        try
        {
            string host_user_id = HttpContext.Current.Session["UserId"].ToString();
            string host_name = HttpContext.Current.Request.UserHostName;
            status = objmaster.insert_update_fine_dtl(host_user_id, host_name, semeter_type, year_code, user_id, remarks, installmentfine, installment_no);

            if (status == true)
            {
                param["status"] = true;
                return JsonConvert.SerializeObject(param);
            }
            else
            {
                param["status"] = false;
                param["message"] = "Problem in Saved data.";
                return JsonConvert.SerializeObject(param);
            }
        }
        catch (Exception)
        {

            param["status"] = false;
            param["message"] = "Problem in Saved data.";
            return JsonConvert.SerializeObject(param);
        }
    }

