                //    else if (dt_foundation_fees_sem_dtl_user.Rows[0]["cur_foundation_sem"].ToString() == "2")
                //    {
                //        get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, "", "", "");
                //    }
                //}
                //else
                //{
                //    get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, "", "", "");
                //}

                //DataTable dt_cur_sem = objmaster.Get_cept_current_sem_data("fees_installment");

                if (get_fees_dtl != null)
                {
                    if (get_fees_dtl.Rows[0]["is_installment" + data["installment_no"].ToString() + "_paid"].ToString() == "Y")
                    {
                        obj_data["status"] = false;
                        obj_data["message"] = "You can not Accept/Reject Payslip. Fees already paid for this Installment";
                        return JsonConvert.SerializeObject(obj_data);
                    }
                    else
                    {
                        DataTable dt_user_upload_data = objmaster.get_user_installment_payslip_data(user_id, data["semester_type"].ToString(), data["year_semester"].ToString(), data["installment_no"].ToString());//dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString()

                        if (dt_user_upload_data == null)
                        {
                            obj_data["status"] = false;
                            obj_data["message"] = "Payslip Detail not found for Installment , Please try again.";
                            return JsonConvert.SerializeObject(obj_data);
                        }
                        else
                        {
                            DSC_Fees_Installment Fees_Installment = new DSC_Fees_Installment();

                            if (data["is_admin_approved"].ToString() == "A")
                            {
                                get_fees_dtl.Rows[0]["is_installment" + data["installment_no"].ToString() + "_paid"] = "Y";

                                Fees_Installment.user_fees_installment_dtl.ImportRow(get_fees_dtl.Rows[0]);
                            }

                            dt_user_upload_data.Columns.Remove("user_name");
                            dt_user_upload_data.Columns.Remove("prog_name");

                            DataRow dr = dt_user_upload_data.Rows[0];

                            dr["is_admin_approved"] = data["is_admin_approved"].ToString();

                            if (data["is_admin_approved"].ToString() == "R")
                            {
                                dr["remarks"] = data["remark"].ToString();
                            }

                            dr["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                            dr["last_modified_date"] = DateTime.Now;
                            dr["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                            Fees_Installment.user_installment_payslip_dtl.ImportRow(dr);

                            objBLReturnObject = objMaster.save_installment_payslip_dtl(Fees_Installment, "", user_id, HttpContext.Current.Request.UserHostName);

                            if (objBLReturnObject.ExecutionStatus == 2)
                            {
                                obj_data["status"] = false;
                                obj_data["message"] = "Problem in update data " + objBLReturnObject.ServerMessage;
                                return JsonConvert.SerializeObject(obj_data);
                            }
                            else if (objBLReturnObject.ExecutionStatus == 1)
                            {
                                if (data["is_admin_approved"].ToString() == "A")
                                {
                                    DataTable dt = objmaster.Get_student_fees_saved_data_for_manually_accept(data["user_id"].ToString(), data["semester_type"].ToString(), data["year_semester"].ToString());//dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString()

                                    DataTable dt_current_sem = objmaster.get_fee_collection_student_current_semester_dtl();

                                    //DataTable dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");

                                    DataTable dt_user_fees_choice = objmaster.get_user_fees_choice_approve_payslip(user_id, data["semester_type"].ToString(), data["year_semester"].ToString());

                                    //if (dt_foundation_fees_sem_dtl_user != null)
                                    //{
                                    //    if (dt_foundation_fees_sem_dtl_user.Rows[0]["cur_foundation_sem"].ToString() == "1")
                                    //    {
                                    //        dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 1st Sem Fees");
                                    //    }
                                    //    else if (dt_foundation_fees_sem_dtl_user.Rows[0]["cur_foundation_sem"].ToString() == "2")
                                    //    {
                                    //        dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 2nd Sem Fees");
                                    //    }
                                    //}
                                    //else
                                    //{
                                    //    dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");
                                    //}

                                    string fees_status = "F";

                                    if (dt_user_fees_choice != null)
                                    {
                                        if (dt_user_fees_choice.Rows[0]["fees_status"].ToString() == "H")
                                        {
                                            fees_status = "H";
                                        }
                                    }

                                    if (dt != null)
                                    {
                                        DataRow modify_fees_row = dt.Rows[0];

                                        modify_fees_row["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                                        modify_fees_row["last_midified_date"] = System.DateTime.Now;
                                        modify_fees_row["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                                        modify_fees_row["fees_status"] = fees_status;
                                        modify_fees_row["year_code"] = data["year_code"].ToString() + "-I";

                                        obj_fees_status.user_fees_status.ImportRow(modify_fees_row);
                                    }
                                    else
                                    {
                                        DSC_fees_status.user_fees_statusRow user_fees = obj_fees_status.user_fees_status.Newuser_fees_statusRow();

                                        user_fees.doc_no = re.ToString();
                                        user_fees.user_id = data["user_id"].ToString();
                                        user_fees.fees_status = fees_status;
                                        user_fees.cancel_flag = "N";
                                        user_fees.semester_type = data["semester_type"].ToString();//current_fees_sem
                                        user_fees.year_semester = data["year_semester"].ToString();//current_fees_year
                                        user_fees.dept_code = data["dept_code"].ToString();
                                        user_fees.year_code = data["year_code"].ToString() + "-I";
                                        user_fees.installment_status = "N";
                                        user_fees.created_by = HttpContext.Current.Session["UserId"].ToString();
                                        user_fees.created_date = System.DateTime.Now;
                                        user_fees.created_host = HttpContext.Current.Request.UserHostName;

                                        if (dt_current_sem != null)
                                        {
                                            DataRow[] dr1 = dt_current_sem.Select("student_id='" + data["user_id"].ToString() + "'");

                                            if (dr1.Length > 0)
                                            {
                                                user_fees.semester_code = dr1[0]["semester_code"].ToString();
                                            }
                                            else
                                            {
                                                user_fees.semester_code = "1";
                                            }
                                        }
                                        else
                                        {
                                            user_fees.semester_code = "1";
                                        }

                                        obj_fees_status.user_fees_status.Adduser_fees_statusRow(user_fees);
                                    }

                                    //Start 12 03 2020 Mahroofbhai Call
                                    Boolean paid_fine = objMaster.success_fine_paid_offline_icici(data["installment_no"].ToString(), data["user_id"].ToString(), data["semester_type"].ToString(), data["year_semester"].ToString());
                                    //End 12 03 2020 Mahroofbhai Call
                                }

                                objBLReturnObject = objMaster.save_upload_manually_payslip_dtl(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);

                                obj_data["status"] = true;
                                obj_data["message"] = "";
                                return JsonConvert.SerializeObject(obj_data);
                            }
                        }
                    }
                }
                else
                {
                    obj_data["status"] = false;
                    obj_data["message"] = "Fees Detail not found for Student , Please try again.";
                    return JsonConvert.SerializeObject(obj_data);
                }
            }
        }
        catch (Exception ex)
        {
            obj_data["status"] = false;
            obj_data["message"] = "Problem in Save DATA." + ex.ToString();
            return JsonConvert.SerializeObject(obj_data);
        }

        obj_data["status"] = false;
        obj_data["message"] = objBLReturnObject.ServerMessage;
        return JsonConvert.SerializeObject(obj_data);
    }

