    [WebMethod(EnableSession = true)]
    public string change_instructor_mst(string instructor_code, string instructor_name, string email, string flag, string user_type, string des_letter, string instructor_first_name = "", string instructor_last_name = "")
    {
        Dictionary<string, object> param = new Dictionary<string, object>();

        try
        {
            Boolean status = true;
            DataTable dt_user_mst_data = objmaster.get_all_user_mst_data();
            if (flag == "D")
            {
                status = objMaster.update_instructor(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName, instructor_code, instructor_name.Trim(), "Y", email, user_type, des_letter, instructor_first_name, instructor_last_name);
            }
            else
            {
                if (instructor_code != "")
                {
                    if (email != "")
                    {
                        if (dt_user_mst_data != null)
                        {
                            DataRow[] dr_email = dt_user_mst_data.Select("user_id  = '" + instructor_code + "'");

                            if (dr_email.Length > 0)
                            {
                                if (email == dr_email[0]["mail"].ToString())
                                {
                                }
                                else
                                {
                                    dr_email = dt_user_mst_data.Select("mail = '" + email.ToString().Trim().ToLower() + "'");

                                    if (dr_email.Length > 0)
                                    {
                                        param["status"] = false;
                                        param["message"] = "This Email Address is already in our master data";
                                        return JsonConvert.SerializeObject(param);
                                    }
                                }
                            }
                            else
                            {
                                dr_email = dt_user_mst_data.Select("mail = '" + email.ToString().Trim().ToLower() + "'");

                                if (dr_email.Length > 0)
                                {
                                    param["status"] = false;
                                    param["message"] = "This Email Address is already in our master data";
                                    return JsonConvert.SerializeObject(param);
                                }
                            }
                        }
                    }

                    status = objMaster.update_instructor(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName, instructor_code, instructor_name.Trim(), "N", email, user_type, des_letter, instructor_first_name, instructor_last_name);
                }
                else
                {
                    if (email != "")
                    {
                        if (dt_user_mst_data != null)
                        {
                            DataRow[] dr_email = dt_user_mst_data.Select("mail = '" + email.ToString().Trim().ToLower() + "'");

                            if (dr_email.Length > 0)
                            {
                                param["status"] = false;
                                param["message"] = "This email address is already in our master data";
                                return JsonConvert.SerializeObject(param);
                            }
                        }
                    }

                    status = objMaster.Insert_instructor(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName, instructor_code, instructor_name.Trim(), "N", email, user_type, des_letter, instructor_first_name, instructor_last_name);
                }
            }

            if (status == true)
            {
                param["status"] = true;
                return JsonConvert.SerializeObject(param);
            }
            else
            {
                param["status"] = false;
                param["message"] = "Problem in Saved / Update instructor data.";
                return JsonConvert.SerializeObject(param);
            }
        }
        catch (Exception ex)
        {
            param["status"] = false;
            param["message"] = "Problem in Saved / Update data.";
            return JsonConvert.SerializeObject(param);
        }

        param["status"] = true;
        return JsonConvert.SerializeObject(param);
    }


