    [WebMethod(EnableSession = true)]
    public string Save_student_course_dtl(string mandatory_course, string elective_course, string status_flag)
    {
        // Save Compliance Details in compliance_entry table.

        int re = 0;

        try
        {

            DataTable dt_check_blocklist = objmaster.get_registration_block_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

            if (dt_check_blocklist != null)
            {
                return "Please contact your concern person for registration.";
            }

            //if (HttpContext.Current.Session["prog_code"].ToString() != "3")
            //{
            //    return "Registration is closed for Spring-2015";
            //}

            if (re == 0)
            {
                return "Registration hase been closed for Spring-2017";
            }

            string semester = "";

            if (HttpContext.Current.Session["semester_code"].ToString() != "")
            {
                semester = HttpContext.Current.Session["semester_code"].ToString();
            }

            DataTable dt_check_allocate_data = objmaster.get_student_course_allocate_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);


            if (dt_check_allocate_data != null)
            {
                return "You can not Save & Register Course.Course allocation is already completed for current semester.";
            }

            DataTable dt_check_registed_data = objmaster.check_student_allocate_current_sem_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);


            if (dt_check_registed_data != null)
            {
                return "You already registered your Course.";
            }




            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> mandatory_data = ser.Deserialize<List<Dictionary<string, object>>>(mandatory_course);
            List<Dictionary<string, object>> elective_data = ser.Deserialize<List<Dictionary<string, object>>>(elective_course);


            #region check total credits and priority sequence
            int count_credit = 0;

            for (int i = 0; i < mandatory_data.Count; i++)
            {
                count_credit += Convert.ToInt16(mandatory_data[i]["credits"].ToString());
            }

            for (int i = 0; i < elective_data.Count; i++)
            {
                string flag = "N";

                count_credit += Convert.ToInt16(elective_data[i]["credits"].ToString());

                if (Convert.ToInt16(elective_data[i]["priority"].ToString()) == 1)
                {

                }
                else
                {
                    for (int j = 0; j < elective_data.Count; j++)
                    {
                        if (Convert.ToInt16(elective_data[i]["priority"].ToString()) - 1 == Convert.ToInt16(elective_data[j]["priority"].ToString()))
                        {
                            flag = "N";
                            break;
                        }
                        else
                        {
                            flag = "Y";
                        }
                    }

                    if (flag == "Y")
                    {
                        return "You can not save/register your course.You have not select priority in sequence.please select priority in sequence.";
                    }
                }
            }

            if (count_credit > 30)
            {
                return "You can not opt for more than 30 credits for saving.";
            }
            #endregion

            if (status_flag == "R")
            {
                DataTable fees_status = objmaster.Get_fees_status_for_student(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Session["semester_code"].ToString(), current_ws_sem, current_ws_year);

                if (fees_status != null)
                {
                    if (fees_status.Rows[0]["fees_status"].ToString() == "H" || fees_status.Rows[0]["fees_status"].ToString() == "F")
                    {
                        //if (fees_status.Rows[0]["fees_status"].ToString() == "H")
                        //{
                        //    if (count_credit > 12)
                        //    {
                        //        return "You can not opt for more than 12 credits for registering because you are paid half fees.";
                        //    }
                        //}
                    }
                    else
                    {
                        return "You can not Register for the Course. Please pay your fees for current semester and than only you will be eligible for Registration.";
                    }
                }
                else
                {
                    return "You can not Register for the Course. Please pay your fees for current semester and than only you will be eligible for Registration.";
                }
            }
            //else
            //{
            //    DataTable fees_status = objmaster.Get_fees_status_for_student(HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Session["semester_code"].ToString());

            //    if (fees_status != null)
            //    {
            //        if (fees_status.Rows[0]["fees_status"].ToString() == "H" || fees_status.Rows[0]["fees_status"].ToString() == "F")
            //        {
            //            if (fees_status.Rows[0]["fees_status"].ToString() == "H")
            //            {
            //                if (count_credit > 12)
            //                {
            //                    return "You can not opt for more than 12 credits for saving because you are paid half fees.";
            //                }
            //            }
            //        }
            //        else
            //        {
            //            return "You can not Register for the Course. Please pay your fees for current semester and than only you will be eligible for Registration.";
            //        }
            //    }
            //    else
            //    {
            //        return "You can not Register for the Course. Please pay your fees for current semester and than only you will be eligible for Registration.";
            //    }
            //}

            #region check time validation

            DataTable dt_mandatory_time_day = objmaster.Get_mandatory_time_days_data_for_student(HttpContext.Current.Session["dept_code"].ToString(), HttpContext.Current.Session["prog_code"].ToString(), current_ws_sem, current_ws_year);

