                                                if (Convert.ToDecimal(last_to_time.Replace(':', '.')) > Convert.ToDecimal(from_time.Replace(':', '.')) && Convert.ToDecimal(last_to_time.Replace(':', '.')) < Convert.ToDecimal(to_time.Replace(':', '.')))
                                                {
                                                    return "You can not select this Course.Mandatory Course code " + course_code + " timing is Conflict with elective  Course code" + elective_data[i]["course_code"].ToString();
