                save_student_course.semester_code = elective_data[i]["semester_code"].ToString();
                save_student_course.semester_code = elective_data[i]["semester_code"].ToString();
                save_student_course.user_id = HttpContext.Current.Session["UserId"].ToString();
                save_student_course.current_sem_code = HttpContext.Current.Session["semester_code"].ToString();
                save_student_course.year_code = HttpContext.Current.Session["year_code"].ToString();
                save_student_course.course_type = "E";
                save_student_course.credits = elective_data[i]["credits"].ToString();
                save_student_course.gpa_nongpa = elective_data[i]["gpa_nongpa"].ToString();
                save_student_course.priority = elective_data[i]["priority"].ToString();

                DataTable dt = objmaster.Get_department_data();

                DataRow[] dr = dt.Select("dept_name = '" + elective_data[i]["department"].ToString() + "'");

                if (dr.Length > 0 && dr != null)
                {
                    save_student_course.dept_code = dr[0]["dept_code"].ToString();
                }

                if (status_flag == "S")
                {
                    save_student_course.status = "S";
                }
                else if (status_flag == "R")
                {
                    save_student_course.status = "R";
                }

                //if (HttpContext.Current.Session["semester_code"].ToString() == "1"
                //|| HttpContext.Current.Session["semester_code"].ToString() == "3"
                //|| HttpContext.Current.Session["semester_code"].ToString() == "5"
                //|| HttpContext.Current.Session["semester_code"].ToString() == "7"
                //|| HttpContext.Current.Session["semester_code"].ToString() == "9")
                //{
                //    save_student_course.semester_type = "M";
                //}
                //else
                //{
                //    save_student_course.semester_type = "S";
                //}

                ////int year = System.DateTime.Now.Year;

                //save_student_course.year_semester = System.DateTime.Now.Year.ToString();

                save_student_course.semester_type = current_ws_sem.ToString();
                save_student_course.year_semester = current_ws_year.ToString();
                save_student_course.cancel_flag = "N";
                save_student_course.created_by = HttpContext.Current.Session["UserId"].ToString();
                save_student_course.created_date = System.DateTime.Now;
                save_student_course.created_host = HttpContext.Current.Request.UserHostName;

                obj_student.student_wise_course_dtl.Addstudent_wise_course_dtlRow(save_student_course);
            }

            ////objBLReturnObject = objMaster.save_user_fees(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            objBLReturnObject = objmaster.Save_student_course_dtl(obj_student, HttpContext.Current.Session["UserId"].ToString(), semester, HttpContext.Current.Request.UserHostName, current_ws_sem, current_ws_year);
        }
        catch (Exception ex)
        {
            return "Problem in Save DATA.";
        }
        finally
        {

        }

        string msg = "";

        if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
        {
            if (status_flag == "S")
            {
                msg = "Data Saved Successfully";
            }
            else if (status_flag == "R")
            {
                msg = "Data Registered Successfully";

                if (thesis_guide != "" && Session["UserId"] != null)
                {
                    DataTable dt_Students = objmaster.get_Student_transcript_dtl(Session["UserId"].ToString());
                    DSC_Transcript_Detail obj_transcript = new DSC_Transcript_Detail();

                    if (dt_Students != null)
                    {
                        dt_Students.Rows[0]["dissertation_supervisor"] = thesis_guide;
                        dt_Students.Rows[0]["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                        dt_Students.Rows[0]["last_modified_date"] = DateTime.Now;
                        dt_Students.Rows[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                        obj_transcript.student_transcript_dtl.ImportRow(dt_Students.Rows[0]);
                    }
                    else
                    {
                        DSC_Transcript_Detail.student_transcript_dtlRow student_transcript_row = obj_transcript.student_transcript_dtl.Newstudent_transcript_dtlRow();

                        student_transcript_row.doc_no = Session["UserId"].ToString();
                        student_transcript_row.user_id = Session["UserId"].ToString();
                        student_transcript_row.graduation_year = "";
                        student_transcript_row.name_of_the_degree = "";
                        student_transcript_row.previous_degree = "";
                        student_transcript_row.topic_type = "";
                        student_transcript_row.dissertation_topic = "";
                        student_transcript_row.dissertation_supervisor = thesis_guide;
                        student_transcript_row.specialization = "";
                        student_transcript_row.major = "";
                        student_transcript_row.minor = "";
                        student_transcript_row.transcript_no = "";
                        student_transcript_row.created_by = HttpContext.Current.Session["UserId"].ToString();
                        student_transcript_row.created_date = DateTime.Now;
                        student_transcript_row.created_host = HttpContext.Current.Request.UserHostName;

                        obj_transcript.student_transcript_dtl.Addstudent_transcript_dtlRow(student_transcript_row);
                    }

                    objBLReturnObject = objMaster.save_Student_transcript_dtl(obj_transcript, "2000", "", HttpContext.Current.Request.UserHostName);
                }

                //Insert/Update Credits Details in SWS Fees Waiver Table
                try
                {
                    string sem = "";

                    if (current_ws_sem == "S")
                    {
                        sem = current_ws_sem;
                    }
                    else if (current_ws_sem == "M")
                    {
                        sem = "W";
                    }

                    DataTable dt_waiver_dtl = objmaster.get_student_ws_waiver_dtl(Session["UserId"].ToString(), current_ws_sem, current_ws_year);
                    DataTable dt_credits_bifurcation = objmaster.Get_user_fees_choice_bifurcation_dtl(Session["UserId"].ToString(), current_ws_sem, current_ws_year);
                    XSD.Masters_WS.DSC_fees_status_WS obj_fees_status = new XSD.Masters_WS.DSC_fees_status_WS();

                    if (dt_credits_bifurcation != null)
                    {
                        int mand_credits = 0, elec_credits = 0, sws_credits = 0, total_credits = 0;
                        if (dt_credits_bifurcation.Rows[0]["mandatory_credits"].ToString() != "")
                        {
                            mand_credits = Int32.Parse(dt_credits_bifurcation.Rows[0]["mandatory_credits"].ToString());
                        }
                        if (dt_credits_bifurcation.Rows[0]["elective_credits"].ToString() != "")
                        {
                            elec_credits = Int32.Parse(dt_credits_bifurcation.Rows[0]["elective_credits"].ToString());
                        }
                        if (dt_credits_bifurcation.Rows[0]["sws_credits"].ToString() != "")
                        {
                            sws_credits = Int32.Parse(dt_credits_bifurcation.Rows[0]["sws_credits"].ToString());
                        }

                        total_credits = mand_credits + elec_credits + sws_credits;

                        if (total_credits > 20)
                        {
                            if ((20 - (mand_credits + elec_credits)) > 0)
                            {
                                sws_credits = 20 - (mand_credits + elec_credits);
                            }
                            else
                            {
                                sws_credits = 0;
                            }
                        }

                        if (dt_waiver_dtl != null)
                        {
                            dt_waiver_dtl.Rows[0]["fees_type"] = "Y";

                            if (dt_waiver_dtl.Rows[0]["fees_waiver_credits"].ToString() == "")
                            {
                                dt_waiver_dtl.Rows[0]["fees_waiver_credits"] = sws_credits.ToString();
                            }
                            else
                            {
                                int credits = Int32.Parse(dt_waiver_dtl.Rows[0]["fees_waiver_credits"].ToString());

                                dt_waiver_dtl.Rows[0]["fees_waiver_credits"] = (credits + sws_credits).ToString();
                            }

                            dt_waiver_dtl.Rows[0]["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                            dt_waiver_dtl.Rows[0]["last_midified_date"] = DateTime.Now;
                            dt_waiver_dtl.Rows[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                            obj_fees_status.ws_user_fees_status.ImportRow(dt_waiver_dtl.Rows[0]);
                        }
                        else
                        {
                            XSD.Masters_WS.DSC_fees_status_WS.ws_user_fees_statusRow user_fees = obj_fees_status.ws_user_fees_status.Newws_user_fees_statusRow();

                            user_fees.doc_no = "1";
                            user_fees.user_id = HttpContext.Current.Session["UserId"].ToString();
                            user_fees.dept_code = HttpContext.Current.Session["dept_code"].ToString();
                            user_fees.fees_type = "Y";
                            user_fees.fees_waiver_credits = sws_credits.ToString();
                            user_fees.year_code = HttpContext.Current.Session["year_code"].ToString();
                            user_fees.cancel_flag = "N";
                            user_fees.semester_type = sem;//current_ws_sem;
                            user_fees.year_type = current_ws_year;
                            user_fees.created_by = HttpContext.Current.Session["UserId"].ToString();
                            user_fees.created_date = DateTime.Now;
                            user_fees.created_host = HttpContext.Current.Request.UserHostName;

                            obj_fees_status.ws_user_fees_status.Addws_user_fees_statusRow(user_fees);
                        }

                        BLL.Master_WS.Masters_WS objMaster_ws = new BLL.Master_WS.Masters_WS();

                        objBLReturnObject = objMaster_ws.save_ws_user_fees(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    }
                }
                catch (Exception ex)
                {

                }
            }
        }

        return msg;
    }

    [WebMethod(EnableSession = true)]
    public string Create_online_payment()
    {
        //Save Compliance Details in compliance_entry table.

        int re = 0;
        string user_id = "";
        string current_sem_code = "";
        string message = "";
        string transaction_id = "";
        decimal amount = 0, main_fees = 0, fees1 = 0, deposit = 0;

        string dept_code = "";
        string gender = "";
        string trans_code = "";
        string closed = "";

        Dictionary<string, object> obj_data = new Dictionary<string, object>();

        try
        {
            Dictionary<string, object> param = new Dictionary<string, object>();

            //if (HttpContext.Current.Session["year_code"].ToString() == "Y2016")
            //{
            //    if (HttpContext.Current.Session["prog_code"].ToString() == "2")
            //    {
            //        if (HttpContext.Current.Session["UserId"].ToString() != "21161700015" && HttpContext.Current.Session["UserId"].ToString() != "22161700429")
            //        {
            //            if (HttpContext.Current.Session["UserId"].ToString() != "21161700015" && HttpContext.Current.Session["UserId"].ToString() != "22161700429")
            //            {
            //                closed = "";
            //            }
            //        }
            //    }
            //}

            //closed = "";

            if (closed == "")
            {
                obj_data["status"] = false;
                obj_data["message"] = "Payment has closed.";

                return JsonConvert.SerializeObject(obj_data);
            }

            if (HttpContext.Current.Session["UserId"].ToString() != null)
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            if (HttpContext.Current.Session["semester_code"].ToString() != null)
            {
                current_sem_code = HttpContext.Current.Session["semester_code"].ToString();
            }

            Boolean status = true;
            DataTable dt = objmaster.get_student_payslip_number(user_id, current_ws_sem, current_ws_year);

            if (dt != null)
            {
                if (dt.Rows.Count == 0)
                {
                    status = objmaster.Insert_Payslip_Number(user_id, HttpContext.Current.Request.UserHostName, current_sem_code, current_ws_sem, current_ws_year);
                }
            }
            else
            {
                status = objmaster.Insert_Payslip_Number(user_id, HttpContext.Current.Request.UserHostName, current_sem_code, current_ws_sem, current_ws_year);
            }

            if (status == false)
            {
                obj_data["status"] = false;
                obj_data["message"] = "Problem in Generate Payslip Number.";

                return JsonConvert.SerializeObject(obj_data);
            }

            if (HttpContext.Current.Session["gender"].ToString() != null)
            {
                gender = HttpContext.Current.Session["gender"].ToString();

                if (gender == "T")
                {
                    gender = "F";
                }
            }
            else
            {
                obj_data["status"] = false;
                obj_data["message"] = "Your Gender is not Found.";

                return JsonConvert.SerializeObject(obj_data);
            }

            if (HttpContext.Current.Session["dept_code"].ToString() != null)
            {
                dept_code = HttpContext.Current.Session["dept_code"].ToString();
            }
            else
            {
                obj_data["status"] = false;
                obj_data["message"] = "Your Faculty is not Found.";

                return JsonConvert.SerializeObject(obj_data);
            }

            //if (dept_code == "5")
            //{
            //     obj_data["status"] = false;
            //     obj_data["message"] = "Your are not eligible for 2nd installment of fees.";
            //    return JsonConvert.SerializeObject(obj_data);
            //}

            if (user_id == "" || current_sem_code == "")
            {
                obj_data["status"] = false;
                obj_data["message"] = "Student Code or Semester code not found.please refresh your current page";

                return JsonConvert.SerializeObject(obj_data);
            }

            string semester = "";

            if (HttpContext.Current.Session["semester_code"] != "")
            {
                semester = HttpContext.Current.Session["semester_code"].ToString();
            }

            DataTable dt_check_allocate_data = objmaster.get_student_course_allocate_data(user_id, current_ws_sem, current_ws_year);

            if (dt_check_allocate_data != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "You can not Payment your fees Course.Course allocation is already completed for current semester.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_check_registed_data = objmaster.Get_student_registered_current_sem_data(user_id, current_ws_sem, current_ws_year);

            if (dt_check_registed_data != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "You can not payment your fees.You already registered your Course.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_fees_status_check = objmaster.Get_fees_status_for_student_for_fees_payment(user_id, current_ws_sem, current_ws_year);

            if (dt_fees_status_check != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "Fees is already paid for current semester.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_total_credits = objmaster.Get_total_credits_for_pay_slip(user_id, current_ws_sem, current_ws_year);

            if (dt_total_credits != null)
            {
                DataTable dt_fees_discount_dtl = objmaster.get_discount_fees_for_student(user_id, current_ws_sem, current_ws_year);
                if (dt_fees_discount_dtl == null)
                {
                    DataTable dt_user_fees_data = objmaster.get_user_data_for_pay_slip_new(user_id, semester, current_ws_sem, current_ws_year, gender);
                    DataTable get_installment_data = objmaster.get_installment_data(user_id, current_ws_sem, current_ws_year);

                    if (dt_user_fees_data != null)
                    {
                        int total_credits = 0;

                        if (dt_total_credits.Rows[0]["credits"].ToString() != "")
                        {
                            total_credits = Convert.ToInt16(dt_total_credits.Rows[0]["credits"]);
                        }
                        else
                        {
                            obj_data["status"] = false;
                            obj_data["message"] = "Total Credits not found for current semester.Please First Save your course for Online payment";

                            return JsonConvert.SerializeObject(obj_data);
                        }

                        if (dt_user_fees_data.Rows[0]["fees"].ToString() != "")
                        {
                            main_fees = Convert.ToDecimal(dt_user_fees_data.Rows[0]["fees"]);

                            fees1 = Convert.ToDecimal(dt_user_fees_data.Rows[0]["fees1"]);

                            deposit = Convert.ToDecimal(dt_user_fees_data.Rows[0]["deposit"]);
                        }
                        else
                        {
                            obj_data["status"] = false;
                            obj_data["message"] = "Fees Data not found";

                            return JsonConvert.SerializeObject(obj_data);
                        }

                        string installment_status = "N";

                        if (get_installment_data != null)
                        {
                            if (get_installment_data.Rows[0]["installment_status"].ToString() == "Y")
                            {
                                installment_status = "Y";
                            }
                        }

                        if (total_credits > 12)
                        {
                            if (installment_status == "Y")
                            {
                                amount = ((main_fees + fees1) / 2) + deposit;
                            }
                            else
                            {
                                amount = main_fees + fees1 + deposit;
                            }
                        }
                        else
                        {
                            if (installment_status == "Y")
                            {
                                amount = ((main_fees + fees1) / 4) + deposit;
                            }
                            else
                            {
                                amount = ((main_fees + fees1) / 2) + deposit;
                            }
                        }

                        trans_code = dt_user_fees_data.Rows[0]["bank_code"].ToString() + dt_user_fees_data.Rows[0]["user_id"].ToString() + semester;
                    }
                    else
                    {
                        obj_data["status"] = false;
                        obj_data["message"] = "Fees Data not found";
                        return JsonConvert.SerializeObject(obj_data);
                    }
                }
                else
                {
                    if (dt_fees_discount_dtl.Rows[0]["amount"].ToString() != "")
                    {
                        amount = Convert.ToDecimal(dt_fees_discount_dtl.Rows[0]["amount"]);
                    }
                }
            }
            else
            {
                obj_data["status"] = false;
                obj_data["message"] = "Your Total Credits not found";
                return JsonConvert.SerializeObject(obj_data);
            }

            Payment objPayment = new Payment();

            bool result = objPayment.RedirectToPaymentGateway(param, ref message, user_id, amount, current_sem_code, current_ws_sem, current_ws_year, dept_code, trans_code, ref transaction_id);

            string hmac_url = Payment.Get_hmac_url(dept_code);

            string return_url = Payment.Get_return_url(dept_code);

            //string base_url = "http://registration.cept.ac.in/ceptreg/Student/";

            //string base_url = "http://122.170.103.168/cept/Student/";

            string str_path = "";

            if (HttpContext.Current.Request.Url.Segments.Length == 3)
            {
                str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + "Student/";
            }
            else if (HttpContext.Current.Request.Url.Segments.Length == 4)
            {
                str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1] + "Student/";
            }

            string base_url = str_path;

            obj_data["status"] = result;
            obj_data["message"] = message;
            obj_data["user_id"] = user_id;
            obj_data["amount"] = amount;
            obj_data["transaction_id"] = transaction_id;
            obj_data["merchant_id"] = HttpContext.Current.Session["MerchantId"];
            obj_data["currency"] = "INR";
            obj_data["hmac_url"] = hmac_url;
            obj_data["return_url"] = base_url + return_url;

            return JsonConvert.SerializeObject(obj_data);
        }
        catch (Exception ex)
        {
            obj_data["status"] = false;
            obj_data["message"] = "Problem in Save DATA.";
            return JsonConvert.SerializeObject(obj_data);
        }

        return message;
    }

