                dic_payment_dtl["return_url"] = "https://connect.cept.ac.in/Student/" + objPayment.Get_Eazypay_return_url(dept_code);

                dic_payment_dtl["reference_no"] = transaction_id;
                dic_payment_dtl["sub_merchant_id"] = sub_merchant_id;
                dic_payment_dtl["transaction_amount"] = amount;
                dic_payment_dtl["paymode"] = "9";

                //obj_data["eazypay_return_url"] = objPayment.Get_eazypay_encrypted_url(ref dic_payment_dtl);
            }
            else if (pg_type == "hdfc")
            {
                Dictionary<string, object> dic_payment_dtl = new Dictionary<string, object>();

                dic_payment_dtl["merchant_id"] = objPayment.Get_HDFC_MerchantId(dept_code);
                dic_payment_dtl["order_id"] = transaction_id;
                dic_payment_dtl["amount"] = amount;
                dic_payment_dtl["currency"] = "INR";
                dic_payment_dtl["redirect_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + objPayment.Get_HDFC_return_url(dept_code);
                dic_payment_dtl["cancel_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + objPayment.Get_HDFC_return_url(dept_code);
                dic_payment_dtl["language"] = "EN";

                dic_payment_dtl["merchant_param1"] = user_id;
                dic_payment_dtl["merchant_param2"] = HttpContext.Current.Session["UserName"];
                dic_payment_dtl["merchant_param3"] = dept_code;

                obj_data["hdfc_request_url"] = objPayment.Get_HDFC_request_url(dept_code);
                obj_data["encRequest"] = objPayment.Get_HDFC_encrypted_request(ref dic_payment_dtl);
                obj_data["access_code"] = objPayment.Get_HDFC_access_code(dept_code);
            }
            else if (pg_type == "kotak")
            {
                Dictionary<string, object> dic_payment_dtl = new Dictionary<string, object>();

                dic_payment_dtl["merchant_id"] = objPayment.Get_Kotak_MerchantId(dept_code);
                dic_payment_dtl["order_id"] = transaction_id;
                dic_payment_dtl["amount"] = amount;
                dic_payment_dtl["currency"] = "INR";
                dic_payment_dtl["redirect_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + objPayment.Get_Kotak_return_url(dept_code);
                dic_payment_dtl["cancel_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + objPayment.Get_Kotak_return_url(dept_code);
                dic_payment_dtl["language"] = "EN";

                dic_payment_dtl["merchant_param1"] = user_id;
                dic_payment_dtl["merchant_param2"] = HttpContext.Current.Session["UserName"];
                dic_payment_dtl["merchant_param3"] = dept_code;
                dic_payment_dtl["merchant_param4"] = ""; // 19062019

                obj_data["kotak_request_url"] = objPayment.Get_Kotak_request_url(dept_code);
                obj_data["encRequest"] = objPayment.Get_Kotak_encrypted_request(ref dic_payment_dtl);
                obj_data["access_code"] = objPayment.Get_Kotak_access_code(dept_code);
            }

            return JsonConvert.SerializeObject(obj_data);
        }
        catch (Exception ex)
        {
            obj_data["status"] = false;

            obj_data["message"] = "Problem in Save DATA.";

            return JsonConvert.SerializeObject(obj_data);
        }

        string msg = "";



        return message;

    }

