                                if (installment_status == "Y")
                                {
                                    //  amount = ((((main_fees + fees1) * Convert.ToDecimal(total_credits)) / total_devided_credits) / 4) + deposit;

                                    amount = ((((main_fees + fees1) * Convert.ToDecimal(total_credits)) / total_devided_credits) / 2) + deposit;
                                }
                                else
                                {
                                    // amount = ((main_fees + fees1) / 2) + deposit;

                                    amount = (((main_fees + fees1) * Convert.ToDecimal(total_credits)) / total_devided_credits) + deposit;
                                }
                            }
                            //  }
                        }
                        else
                        {
                            obj_data["status"] = false;
                            obj_data["message"] = "Fees Data not found";
                            return JsonConvert.SerializeObject(obj_data);
                        }

                    }
                    else
                    {
                        obj_data["status"] = false;
                        obj_data["message"] = "Fees type not saved by you for current semester.Please First Save your Fees Type for Online payment";
                        return JsonConvert.SerializeObject(obj_data);
                    }
                }
                else
                {
                    if (flag == "N")
                    {
                        if (dt_user_fees_data != null)
                        {
                            if (dt_user_fees_data.Rows[0]["fees"].ToString() != "")
                            {
                                main_fees = Convert.ToDecimal(dt_user_fees_data.Rows[0]["fees"]);

                                fees1 = Convert.ToDecimal(dt_user_fees_data.Rows[0]["fees1"]);

                                deposit = Convert.ToDecimal(dt_user_fees_data.Rows[0]["deposit"]);
                            }
                            else
                            {
                                obj_data["status"] = false;
                                obj_data["message"] = "Fees Data not found";

                                return JsonConvert.SerializeObject(obj_data);
                            }


                            if (installment_status == "Y")
                            {
                                amount = ((main_fees + fees1) / 2) + deposit;
                            }
                            else
                            {
                                amount = main_fees + fees1 + deposit;
                            }


                        }
                        else
                        {
                            obj_data["status"] = false;
                            obj_data["message"] = "Fees Data not found";
                            return JsonConvert.SerializeObject(obj_data);
                        }
                    }
                    else
                    {
                        obj_data["status"] = false;
                        obj_data["message"] = "Fees type not saved by you for current semester.Please Save your Fees type for Online payment";
                        return JsonConvert.SerializeObject(obj_data);
                    }
                }
            }
            else
            {
                if (dt_fees_discount_dtl.Rows[0]["amount"].ToString() != "")
                {
                    amount = Convert.ToDecimal(dt_fees_discount_dtl.Rows[0]["amount"]);
                }

            }

            obj_data["status"] = true;


            return JsonConvert.SerializeObject(obj_data);

        }
        catch (Exception ex)
        {
            return "Problem in Save DATA.";
        }

        string msg = "";



        return message;

    }

    [WebMethod(EnableSession = true)]
    public string Check_Fees_Payment_Block()
    {
        Dictionary<string, object> obj_data = new Dictionary<string, object>();

        DataTable dt_blocklist_fees_reg = objmaster.student_fees_registration_blocklist(current_ws_sem, current_ws_year, HttpContext.Current.Session["UserId"].ToString());

        if (dt_blocklist_fees_reg != null && dt_blocklist_fees_reg.Rows.Count > 0)
        {
            string semester_name = "";

            if (current_ws_sem == "S")
            {
                semester_name = "Spring";
            }
            else if (current_ws_sem == "M")
            {
                semester_name = "Monsoon";
            }

            obj_data["status"] = false;
            obj_data["message"] = "Your Fees Payment has been block for the " + semester_name + " " + current_ws_year + " Semester.";
        }
        else
        {
            obj_data["status"] = true;
            obj_data["message"] = "Fees Payment not blocked.";
        }

        return JsonConvert.SerializeObject(obj_data);
    }

    [WebMethod(EnableSession = true)]
    public string save_user_fees_type_before_paid_fees(string fees_status, string selected_credits)
    {
        // Save Compliance Details in compliance_entry table.

        Dictionary<string, object> obj_data = new Dictionary<string, object>();
        try
        {
            DataTable dt_blocklist_fees_reg = objmaster.student_fees_registration_blocklist(current_ws_sem, current_ws_year, HttpContext.Current.Session["UserId"].ToString());

            if (dt_blocklist_fees_reg != null && dt_blocklist_fees_reg.Rows.Count > 0)
            {
                string semester_name = "";

                if (current_ws_sem == "S")
                {
                    semester_name = "Spring";
                }
                else if (current_ws_sem == "M")
                {
                    semester_name = "Monsoon";
                }

                obj_data["status"] = false;
                obj_data["message"] = "Your Fees Payment has been block for the " + semester_name + " " + current_ws_year + " Semester.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_check_allocate_data = objmaster.get_student_course_allocate_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

            if (dt_check_allocate_data != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "You can not Pay your Fees. Course allocation is already completed for Current Semester.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_check_registed_data = objmaster.Get_student_registered_current_sem_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);


            if (dt_check_registed_data != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "You can not Pay your Fees. You have already registered your Courses.";

                return JsonConvert.SerializeObject(obj_data);
            }

            DataTable dt_fees_status_check = objmaster.Get_fees_status_for_student_for_fees_payment(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);


            if (dt_fees_status_check != null)
            {
                obj_data["status"] = false;
                obj_data["message"] = "You have already paid the Fees for current semester.";

                return JsonConvert.SerializeObject(obj_data);
            }


            JavaScriptSerializer ser = new JavaScriptSerializer();

            DataTable dt = objmaster.Get_student_fees_type_saved_data_for_before_paid_fees(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

            DSC_fees_status.user_fees_choiceRow user_fees = obj_fees_status.user_fees_choice.Newuser_fees_choiceRow();


            if (dt != null)
            {

                if (dt.Rows.Count > 0)
                {
                    DataRow TranRow = dt.Rows[0];

                    TranRow["fees_status"] = fees_status;
                    TranRow["credit_selected"] = selected_credits;
                    if (fees_status == "H")
                    {
                        TranRow["credit_choice"] = "";
                    }

                    TranRow["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                    TranRow["last_modified_date"] = System.DateTime.Now;
                    TranRow["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                    obj_fees_status.user_fees_choice.ImportRow(TranRow);
                }
                else
                {


                    user_fees.user_id = HttpContext.Current.Session["UserId"].ToString();

                    user_fees.fees_status = fees_status;
                    user_fees.credit_selected = selected_credits;

                    user_fees.created_by = HttpContext.Current.Session["UserId"].ToString();
                    user_fees.created_date = System.DateTime.Now;
                    user_fees.created_host = HttpContext.Current.Request.UserHostName;

                    user_fees.cancel_flag = "N";
                    user_fees.semester_type = current_ws_sem;
                    user_fees.year_semester = current_ws_year;

                    //obj_workflow.New_cad_workflow_mst.AddNew_cad_workflow_mstRow(user_fees);
                    obj_fees_status.user_fees_choice.Adduser_fees_choiceRow(user_fees);
                }
            }
            else
            {
                user_fees.user_id = HttpContext.Current.Session["UserId"].ToString();

                user_fees.fees_status = fees_status;
                user_fees.credit_selected = selected_credits;

                user_fees.created_by = HttpContext.Current.Session["UserId"].ToString();
                user_fees.created_date = System.DateTime.Now;
                user_fees.created_host = HttpContext.Current.Request.UserHostName;

                user_fees.cancel_flag = "N";
                user_fees.semester_type = current_ws_sem;
                user_fees.year_semester = current_ws_year;

                //obj_workflow.New_cad_workflow_mst.AddNew_cad_workflow_mstRow(user_fees);
                obj_fees_status.user_fees_choice.Adduser_fees_choiceRow(user_fees);

            }



            //objBLReturnObject = objMaster.save_user_fees(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            objBLReturnObject = objMaster.save_user_fees_type_selected_by_student_before_fees(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            //ServerLog.FeesLog("Fees Type saved before payment user_id:" + HttpContext.Current.Session["UserId"].ToString() + "semester:" + DateTime.Now + "message" + objBLReturnObject.ServerMessage);
            //ServerLog.InvalidLoginLog(objBLReturnObject.ExecutionStatus.ToString());
            if (objBLReturnObject.ExecutionStatus == 1)
            {
                obj_data["status"] = true;
                obj_data["message"] = objBLReturnObject.ServerMessage;
            }
            else
            {
                obj_data["status"] = false;
                obj_data["message"] = objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {

            obj_data["status"] = false;
            obj_data["message"] = "Problem in Save DATA.";

            //  ServerLog.FeesLogError("user_id:" + HttpContext.Current.Session["UserId"].ToString() + "semester:" + HttpContext.Current.Session["semester_code"].ToString() + " Error in Webservice method save_user_fees_type_before_paid_fees " + DateTime.Now);
        }

        return JsonConvert.SerializeObject(obj_data);

    }

