    //<summery>This WebService User to Manually Course Allocation (Vertical Course  and Normal Course).
    // 1. Vertical Course Allocation Update Multiple Tables Like Student Course Allocation Dtl, Vertical Studio selection dtl.
    // 2. Vertical Course Allocation User Not Fill Perfrences Insert Row in Vertical Studio selection dtl.
    // 3. Normal Course Manually Allocated.
    //</summery>
    [WebMethod(EnableSession = true)]
    public string save_data_for_allocation(string manually_data, string course_code, string sem_code, string year, string dept_code, string prog_code)
    {
        //Save Compliance Details in compliance_entry table.

        int re = 0;

        try
        {
            int res = 0;
            int res_new = 0;
            int deallocated_count = 0;
            string userid = "";
            string parent_course_code = "";
            string child_course = "";
            string insert_user_id = "";
            int new_user_count = 0;
            string deallocated_user = "";
            string course_priority = "";
            Vertical_Studio_User_List.Parent_Course = "";
            Vertical_Studio_User_List.User_id = "";
            Vertical_Studio_User_List.New_User_insert = "";
            Vertical_Studio_User_List.deallocated_user_id = "";
            Vertical_Studio_User_List.Parent_Course = "";
            Vertical_Studio_User_List.Child_Course = "";

            DataTable course_data = objmaster.Get_all_course_data(sem_code, year);

            DataTable user_data = objmaster.Get_student_data_new("", dept_code, prog_code);

            DataTable get_old_allocate_data = objmaster.get_student_allcate_course_dtl_data(sem_code, year, course_code);

            DataTable get_register_user = objmaster.get_register_user(sem_code, year);
            DataTable get_vertical_course_dtl = objmaster.get_vertical_course_dtl(sem_code, year, prog_code, dept_code, course_code);

            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(manually_data);

            if (course_code != null)
            {
                for (int i = 0; i < data.Count; i++)
                {
                    if (get_vertical_course_dtl != null)
                    {
                        if (data[i]["cancel_flag"].ToString() == "N")
                        {
                            if (data[i]["user_id"].ToString() == "UG191170")
                            {
                                string ss = "";
                            }
                            DataRow[] dr_user = get_register_user.Select("user_id = '" + data[i]["user_id"].ToString() + "' and status ='A'");
                            DataRow[] dr_course_reg_Status = null;
                            if (dr_user.Length <= 0)
                            {
                                DataRow[] dr_reg_user = get_register_user.Select("user_id = '" + data[i]["user_id"].ToString() + "' and status ='R'");
                                if (dr_reg_user.Length > 0)
                                {

                                    // User This Course Register Or Not 
                                    for (int w = 0; w < get_vertical_course_dtl.Rows.Count; w++)
                                    {
                                        dr_course_reg_Status = get_register_user.Select("user_id = '" + data[i]["user_id"].ToString() + "' and course_code ='" + course_code + "' and parent_course ='" + get_vertical_course_dtl.Rows[w]["course_code"].ToString() + "'");
                                        if (dr_course_reg_Status.Length > 0)
                                        {
                                            break;
                                        }
                                    }
                                    // DataRow[] dr_course_reg_Status = get_register_user.Select("user_id = '" + data[i]["user_id"].ToString() + "' and course_code ='" + course_code + "' and parent_course ='" + get_vertical_course_dtl.Rows[0]["course_code"].ToString() + "'");
                                    if (dr_course_reg_Status.Length <= 0)
                                    {
                                        continue;
                                    }
                                    course_priority = dr_course_reg_Status[0]["priority"].ToString();
                                    if (res == 0)
                                    {
                                        parent_course_code = get_vertical_course_dtl.Rows[0]["course_code"].ToString();//"'" + get_vertical_course_dtl.Rows[0]["course_code"].ToString() + "'";
                                        child_course = course_code;//"'" + dr_reg_user[0]["course_code"].ToString() + "'";
                                        userid = "'" + dr_reg_user[0]["user_id"].ToString() + "'";
                                        Vertical_Studio_User_List.Parent_Course = parent_course_code;
                                        Vertical_Studio_User_List.Child_Course = child_course;
                                        Vertical_Studio_User_List.User_id = userid;
                                        Vertical_Studio_User_List.semester = sem_code;
                                        Vertical_Studio_User_List.year = year;
                                        // Vertical_Studio_User_List.vertical_course = "False";
                                        res = res + 1;
                                    }
                                    else
                                    {
                                        userid += ",'" + dr_reg_user[0]["user_id"].ToString() + "'";
                                        Vertical_Studio_User_List.User_id = userid;
                                        res = res + 1;
                                    }
                                }
                                else
                                {
                                    if (res_new == 0)
                                    {
                                        insert_user_id = "'" + data[i]["user_id"].ToString() + "'";
                                        Vertical_Studio_User_List.Parent_Course = get_vertical_course_dtl.Rows[0]["course_code"].ToString();
                                        Vertical_Studio_User_List.Child_Course = course_code;
                                        // Vertical_Studio_User_List.User_id = userid;
                                        Vertical_Studio_User_List.semester = sem_code;
                                        Vertical_Studio_User_List.year = year;

                                        DataTable dt_exits = objmaster.get_vertical_user_course_exits(sem_code, year, data[i]["user_id"].ToString(), get_vertical_course_dtl.Rows[0]["course_code"].ToString());
                                        if (dt_exits != null)
                                        {
                                            Vertical_Studio_User_List.New_User_insert = insert_user_id;
                                            res_new = res_new + 1;
                                        }
                                        else
                                        {
                                            Vertical_Studio_User_List.New_User_insert = insert_user_id;
                                            res_new = res_new + 1;
                                            new_user_count = 1;
                                        }
                                    }
                                    else
                                    {
                                        insert_user_id += ",'" + data[i]["user_id"].ToString() + "'";

                                        DataTable dt_exits_ = objmaster.get_vertical_user_course_exits(sem_code, year, data[i]["user_id"].ToString(), get_vertical_course_dtl.Rows[0]["course_code"].ToString());
                                        if (dt_exits_ != null)
                                        {
                                            Vertical_Studio_User_List.New_User_insert = insert_user_id;
                                            res_new = res_new + 1;
                                        }
                                        else
                                        {
                                            Vertical_Studio_User_List.New_User_insert = insert_user_id;
                                            res_new = res_new + 1;
                                            new_user_count = 1;
                                        }

                                    }

                                }

                                Ds_Student_Course_detail.student_course_allocate_dtlRow save_student_course = obj_student.student_course_allocate_dtl.Newstudent_course_allocate_dtlRow();

                                if (get_old_allocate_data != null)
                                {
                                    DataRow[] dr = get_old_allocate_data.Select("user_id = '" + data[i]["user_id"].ToString() + "'");

                                    if (dr.Length > 0)
                                    {
                                        re = re + i;

                                        save_student_course.doc_no = dr[0]["doc_no"].ToString();

                                        save_student_course.cancel_flag = data[i]["cancel_flag"].ToString();

                                        save_student_course.created_by = dr[0]["created_by"].ToString();
                                        if (dr[0]["created_date"].ToString() != "")
                                        {
                                            save_student_course.created_date = Convert.ToDateTime(dr[0]["created_date"].ToString());
                                        }
                                        else
                                        {
                                        }

                                        save_student_course.created_host = dr[0]["created_host"].ToString();

                                        save_student_course.last_modified_by = HttpContext.Current.Session["UserId"].ToString() + "- manually";
                                        save_student_course.last_modified_date = System.DateTime.Now;
                                        save_student_course.last_modified_host = HttpContext.Current.Request.UserHostName;
                                    }
                                    else
                                    {
                                        re = re + i;

                                        save_student_course.doc_no = re.ToString();

                                        save_student_course.created_by = HttpContext.Current.Session["UserId"].ToString() + "- manually";
                                        save_student_course.created_date = System.DateTime.Now;
                                        save_student_course.created_host = HttpContext.Current.Request.UserHostName;
                                    }
                                }
                                else
                                {
                                    re = re + i;

                                    save_student_course.doc_no = re.ToString();

                                    save_student_course.created_by = HttpContext.Current.Session["UserId"].ToString() + "- manually";
                                    save_student_course.created_date = System.DateTime.Now;
                                    save_student_course.created_host = HttpContext.Current.Request.UserHostName;
                                }

                                save_student_course.user_id = data[i]["user_id"].ToString();

                                if (user_data != null)
                                {
                                    DataRow[] dr1 = user_data.Select("user_id = '" + data[i]["user_id"].ToString() + "'");

                                    if (dr1.Length > 0)
                                    {
                                        save_student_course.year_code = dr1[0]["year_code"].ToString();
                                    }
                                }

                                DataTable dt = objmaster.check_credit_choice_by_student("", "", data[i]["user_id"].ToString(), "");

                                if (dt != null)
                                {
                                    save_student_course.current_sem_code = dt.Rows[0]["semester_code"].ToString();
                                }
                                else
                                {
                                    return "semester detail not found of user : " + data[i]["user_id"].ToString();
                                }

                                save_student_course.course_code = course_code;

                                if (course_data != null)
                                {
                                    DataRow[] dr = course_data.Select("course_code = '" + course_code + "'");

                                    if (dr.Length > 0)
                                    {

                                        save_student_course.semester_code = dr[0]["semester_code"].ToString();
                                        save_student_course.credits = dr[0]["course_credits"].ToString();

                                        if (data[i]["course_type"].ToString() == "E")
                                        {
                                            save_student_course.dept_code = dr[0]["dept_code"].ToString();
                                            //save_student_course.gpa_nongpa = data[i]["gpa_nongpa"].ToString();
                                        }
                                        else { save_student_course.dept_code = dr[0]["dept_code"].ToString(); }  // NitinBhai add 11022021 This Maditory Course
                                    }
                                }

                                save_student_course.priority = course_priority;
                                save_student_course.gpa_nongpa = data[i]["gpa_nongpa"].ToString();
                                save_student_course.course_type = data[i]["course_type"].ToString();
                                save_student_course.semester_type = sem_code;
                                save_student_course.year_semester = year.ToString();
                                save_student_course.cancel_flag = "N";
                                obj_student.student_course_allocate_dtl.Addstudent_course_allocate_dtlRow(save_student_course);

                                // only New User Insert 
                                if (new_user_count != 0)
                                {
                                    Ds_Student_Course_detail.student_course_allocate_dtlRow save_student_course_ = obj_student.student_course_allocate_dtl.Newstudent_course_allocate_dtlRow();

                                    save_student_course_.doc_no = new_user_count.ToString();

                                    save_student_course_.created_by = HttpContext.Current.Session["UserId"].ToString() + "- manually";
                                    save_student_course_.created_date = System.DateTime.Now;
                                    save_student_course_.created_host = HttpContext.Current.Request.UserHostName;

                                    save_student_course_.user_id = data[i]["user_id"].ToString();

                                    if (user_data != null)
                                    {
                                        DataRow[] dr1 = user_data.Select("user_id = '" + data[i]["user_id"].ToString() + "'");

                                        if (dr1.Length > 0)
                                        {
                                            save_student_course_.year_code = dr1[0]["year_code"].ToString();
                                        }
                                    }

                                    DataTable check_credit_dt = objmaster.check_credit_choice_by_student("", "", data[i]["user_id"].ToString(), "");

                                    if (check_credit_dt != null)
                                    {
                                        save_student_course_.current_sem_code = check_credit_dt.Rows[0]["semester_code"].ToString();
                                    }
                                    else
                                    {
                                        return "semester detail not found of user : " + data[i]["user_id"].ToString();
                                    }

                                    save_student_course_.course_code = get_vertical_course_dtl.Rows[0]["course_code"].ToString();//course_code;

                                    if (course_data != null)
                                    {
                                        // DataRow[] dr = course_data.Select("course_code = '" + course_code + "'");
                                        DataRow[] dr = course_data.Select("course_code = '" + get_vertical_course_dtl.Rows[0]["course_code"].ToString() + "'");

                                        if (dr.Length > 0)
                                        {

                                            save_student_course_.semester_code = dr[0]["semester_code"].ToString();
                                            save_student_course_.credits = dr[0]["course_credits"].ToString();

                                            if (data[i]["course_type"].ToString() == "E")
                                            {
                                                save_student_course_.dept_code = dr[0]["dept_code"].ToString();
                                                //save_student_course_.gpa_nongpa = data[i]["gpa_nongpa"].ToString();
                                            }
                                        }
                                    }

                                    save_student_course_.gpa_nongpa = data[i]["gpa_nongpa"].ToString();
                                    save_student_course_.course_type = data[i]["course_type"].ToString();
                                    save_student_course_.semester_type = sem_code;
                                    save_student_course_.year_semester = year.ToString();
                                    save_student_course_.cancel_flag = "Y";

                                    obj_student.student_course_allocate_dtl.Addstudent_course_allocate_dtlRow(save_student_course_);
                                    new_user_count = 0;
                                }


                            }
                        }
                        else
                        {
                            if (get_old_allocate_data != null)
                            {
                                DataRow[] dr1 = get_old_allocate_data.Select("user_id = '" + data[i]["user_id"].ToString() + "'");

                                if (dr1.Length > 0)
                                {    //deallocated Users
