    [WebMethod(EnableSession = true)]
    public string Save_transaction_details(string transactionId, string payment_ref_no, string citrus_ref_no, string auth_code)
    {
        DataTable dtTranDetail = objmaster.GetTransactionDetails(transactionId);

        if (dtTranDetail != null && dtTranDetail.Rows.Count > 0)
        {
            string user_id = dtTranDetail.Rows[0]["user_id"].ToString();

            try
            {
                DS_Payment obDS_Payment = new DS_Payment();

                obDS_Payment.EnforceConstraints = false;

                DataRow TranRow = dtTranDetail.Rows[0];

                //string program_course_id = TranRow["program_course_id"].ToString();
                TranRow["payment_return_flag"] = "Y";
                TranRow["payment_response_code"] = "0";
                TranRow["payment_response_msg"] = "Transaction Successful";
                TranRow["payment_transaction_reference_id"] = payment_ref_no;
                TranRow["payment_authorization_code"] = auth_code;
                //TranRow["Citrus_PaymentMode"] = Request["paymentMode"];
                TranRow["Citrus_TxRefNo"] = citrus_ref_no;
                //TranRow["Citrus_TxGateway"] = Request["TxGateway"];
                //TranRow["Citrus_IssuerRefNo"] = Request["issuerCode"];
                TranRow["Citrus_TxStatus"] = "SUCCESS";
                TranRow["status_is_payment_received"] = "Y";
                TranRow["last_modified_date"] = DateTime.Now;
                TranRow["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                TranRow["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                obDS_Payment.applicationpaymenttransaction.ImportRow(TranRow);

                DS_Payment.user_activity_logRow activity_row = obDS_Payment.user_activity_log.Newuser_activity_logRow();

                activity_row.activity_user = HttpContext.Current.Session["UserId"].ToString();
                activity_row.to_user = TranRow["user_id"].ToString();
                activity_row.activity_text = "Add online transaction details";
                activity_row.ref_no = transactionId;
                activity_row.screen_name = "Generate Online Application";
                activity_row.created_date = DateTime.Now;
                activity_row.created_host = HttpContext.Current.Request.UserHostName;

                obDS_Payment.user_activity_log.Adduser_activity_logRow(activity_row);

                if (true)//objBLReturnObject.ExecutionStatus == 1
                {
                    if (dtTranDetail.Rows[0]["cash_collected_by"].ToString().Trim() != "")
                    {
                        string result = update_installation_payment_manually(user_id, dtTranDetail.Rows[0]["cash_collected_by"].ToString(), dtTranDetail.Rows[0]["semester_type"].ToString(), dtTranDetail.Rows[0]["year_semester"].ToString(), dtTranDetail.Rows[0]["amount"].ToString());
                        if (result == "Amount is mismatch with Installment Details. Verify Installment Amount.")
                        {
                            return result;
                        }
                        else
                        {
                            objBLReturnObject = objMaster.Save_manually_Online_transaction_data(obDS_Payment, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                        }
                    }

                    if (user_id != null && user_id != string.Empty)
                    {
                        DataTable dtCandidatePersonalDetails = objmaster.retrieve_student_data_for_modification(user_id);

                        if (dtCandidatePersonalDetails != null && dtCandidatePersonalDetails.Rows.Count > 0)
                        {
                            #region Email
                            try
                            {
                                DataTable dt_transaction_data = objmaster.get_transactionsdetail_for_mail_send(transactionId);

                                Dictionary<string, string> email_data = new Dictionary<string, string>();

                                email_data["student_email"] = dtCandidatePersonalDetails.Rows[0]["mail"].ToString().Trim().ToLower();
                                email_data["user_name"] = dtCandidatePersonalDetails.Rows[0]["user_name"].ToString().Trim().ToLower();
                                email_data["year_code"] = dtCandidatePersonalDetails.Rows[0]["year_code"].ToString().Trim().ToLower();
                                email_data["prog_code"] = dtCandidatePersonalDetails.Rows[0]["prog_code"].ToString().Trim().ToLower();
                                email_data["dept_code"] = dtCandidatePersonalDetails.Rows[0]["dept_code"].ToString().Trim().ToLower();
                                //email_data["program_name"] = "Cept Faculty of Technology";
                                email_data["program_name"] = "";

                                if (dtCandidatePersonalDetails.Rows[0]["prog_level_name"].ToString() != "")
                                {
                                    email_data["program_name"] = dtCandidatePersonalDetails.Rows[0]["prog_level_name"].ToString();
                                }
                                else
                                {
                                    email_data["program_name"] = "Cept Faculty of Technology";
                                }

                                email_data["transaction_id"] = transactionId;
                                email_data["pg_transaction_id"] = citrus_ref_no;
                                email_data["user_id"] = user_id;
                                email_data["amount"] = "";
                                email_data["transaction_date"] = "";
                                if (dt_transaction_data != null)
                                {
                                    email_data["amount"] = dt_transaction_data.Rows[0]["amount"].ToString();
                                    email_data["transaction_date"] = dt_transaction_data.Rows[0]["payment_return_date"].ToString();
                                }

                                string TomailIds = dtCandidatePersonalDetails.Rows[0]["mail"].ToString().Trim().ToLower();

                                //Log.PaymentTransactionLog("Mail id : " + dtCandidatePersonalDetails.Rows[0]["mail"].ToString().Trim().ToLower());
                                Mail objmail = new Mail();
                                string mail_status = objmail.SendEmailOnfeesPaymentSuccess(email_data);

                                if (mail_status == "success")
                                {
                                    return objBLReturnObject.ServerMessage + " " + "Mail has been sent";
                                }
                            }
                            catch (Exception ex)
                            {
                                return objBLReturnObject.ServerMessage + " " + "Mail has not been sent";
                            }
                            #endregion
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                return ex.ToString();
            }
        }
        else
        {
            return "No data found for this Transaction Id";
        }

        return objBLReturnObject.ServerMessage;
    }

