    [WebMethod(EnableSession = true)] // save feedback remarks
    public string send_fees_status_mail(string dept_code, string student_email, string user_id, string user_name, string prog_level_code)
    {
        string mail_status = "";
        string program_name = "", ug_prog_name = "";
        string admin_email = "", admin_password = "";

        DataTable get_student_mail = objmaster.Get_fees_status_for_student_for_fees_payment(user_id, current_fees_sem, current_fees_year);

        if (get_student_mail != null)
        {
            if (get_student_mail.Rows[0]["fees_status"].ToString() != "")
            {

                switch (dept_code)
                {
                    case "1":
                        admin_email = "fa.admissions@cept.ac.in";
                        admin_password = "cept@2015";
                        ug_prog_name = "Bachelor's in Architecture";
                        break;
                    case "2":
                        admin_email = "fd.admissions@cept.ac.in";
                        admin_password = "cept@2015";
                        ug_prog_name = "Bachelor's in Design";
                        break;
                    case "3":
                        admin_email = "fm.admissions@cept.ac.in";
                        admin_password = "cept@2015";
                        break;
                    case "4":
                        admin_email = "fp.admissions@cept.ac.in";
                        admin_password = "cept@2015";
                        ug_prog_name = "Bachelor`s in Planning";
                        break;
                    case "5":
                        admin_email = "ft.admissions@cept.ac.in";
                        admin_password = "cept@2015";
                        ug_prog_name = "Bachelor's in Technology";
                        break;
                    default:
                        break;

                }

                if (admin_email == "" || admin_password == "")
                {
                    return "No email address or password found of admin";
                }


                if (prog_level_code != "")
                {
                    program_name = objmaster.Get_programme_level_name_data(prog_level_code);

                    if (program_name == "")
                    {
                        return "Your Program details not found in master.";
                    }
                }
                else
                {
                    program_name = ug_prog_name;
                }


                string subject = "CEPT admissions confirmation";
                string remark = "Dear <b>" + user_name + " (Application no." + user_id + ")</b>,";

                remark += "<br /><br />Welcome to CEPT.";
                remark += "<br />We have received your part payment for securing your admission in <b>" + program_name + "</b>.";
                remark += "<br />Thank you.We will shortly send the Admission Letter and other details.";
                remark += "<br /><br />For any further assistance please mention your application number during any further communication.";

                remark += "<br /><br /><br />Regards,";

                remark += "<br />Chairman -Admissions";
                remark += "<br /><b>Note: This is an auto-generated mail, please do not reply.</b>";

                mail_status = objmail.SendFeesStatusMail(admin_email, admin_password, student_email, remark, subject);

                ServerLog.ExceptionLog("-----------------------------------------------------");
                ServerLog.ExceptionLog(mail_status.ToString());
                ServerLog.ExceptionLog("-----------------------------------------------------");

                return mail_status;
            }
            else
            {
                return "Please first submit fees for this student";
            }
        }
        else
        {
            return "Please first submit fess for this student";
        }



        return "3";

    }

