                                //user_mst.Rows[j].Delete();
                                dt_error.Rows.Add(dr_error);
                            }
                            else
                            {
                                dr_error = dt_error.NewRow();

                                dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                                dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                                dr_error["Remark"] = "Student Code is not available in User Master.";
                                //user_mst.Rows[j].Delete();
                                dt_error.Rows.Add(dr_error);
                            }
                        }
                    }

                    if (user_mst.Rows[j]["user_name"].ToString() == "")
                    {
                        dr_error = dt_error.NewRow();

                        dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                        dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                        dr_error["Remark"] = "User Name is null";
                        //user_mst.Rows[j].Delete();
                        dt_error.Rows.Add(dr_error);
                    }

                    if (user_mst.Rows[j]["course_code"].ToString() == "")
                    {
                        dr_error = dt_error.NewRow();

                        dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                        dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                        dr_error["Remark"] = "Course Code is null";
                        //user_mst.Rows[j].Delete();
                        dt_error.Rows.Add(dr_error);
                    }
                    else if (dt_course_mst_data != null)
                    {
                        DataRow[] dr = dt_course_mst_data.Select("course_code = '" + user_mst.Rows[j]["course_code"].ToString().Trim() + "'");

                        if (dr.Length <= 0)
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                            dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                            dr_error["Remark"] = "Course Code '" + user_mst.Rows[j]["course_code"].ToString().Trim() + "' is not available in Course Master.";
                            //user_mst.Rows[j].Delete();
                            dt_error.Rows.Add(dr_error);
                        }
                        else if (dt_dept_wise_course_data != null)
                        {
                            DataRow[] dr1 = dt_dept_wise_course_data.Select("course_code = '" + user_mst.Rows[j]["course_code"].ToString().Trim() + "'");

                            if (dr1.Length <= 0)
                            {
                                dr_error = dt_error.NewRow();

                                dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                                dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                                dr_error["Remark"] = "Course '" + user_mst.Rows[j]["course_code"].ToString().Trim() + "' is not allocated to any department for this Semester.";
                                //user_mst.Rows[j].Delete();
                                dt_error.Rows.Add(dr_error);
                            }
                        }
                    }

                    if (Convert.ToInt32(user_mst.Rows[j]["marks"].ToString()) < 0)
                    {
                        dr_error = dt_error.NewRow();

                        dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                        dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                        dr_error["Remark"] = "Marks must be greater than or equal to zero";
                        //user_mst.Rows[j].Delete();
                        dt_error.Rows.Add(dr_error);
                    }

                    if (dt_student_wise_course_upload_data != null)
                    {
                        DataRow[] dr = dt_student_wise_course_upload_data.Select("user_id = '" + user_mst.Rows[j]["user_id"].ToString().Trim() + "'" + " and course_code = '" + user_mst.Rows[j]["course_code"].ToString().Trim() + "'" + " and semester_type = '" + semester_type.ToString().Trim() + "'" + " and year_semester = '" + year_code.ToString().Trim() + "'");

                        if (dr.Length > 0)
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(j + 2);
                            dr_error["User_Id"] = user_mst.Rows[j]["user_id"].ToString();
                            dr_error["Remark"] = "Duplicate Entry Found";
                            //user_mst.Rows[j].Delete();
                            dt_error.Rows.Add(dr_error);
                        }
                    }
                }

                // user_mst.AcceptChanges();
                //checkduplicatedata(user_mst, "Student Code");
                //checkduplicatedata(user_mst, "EMail ID");

                if (dt_error.Rows.Count > 0)
                {

                    jsondata = GetJson1(dt_error);

                    return jsondata;
                }

                int re = 0;
                bool flag = true;


                temp_student_wise_course stud_wise_course = new temp_student_wise_course();

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    re = re + 1;
                    //DSC_userdataupload.user_mstRow user_row = obj_userdataupload.user_mst.Newuser_mstRow();

                    temp_student_wise_course.temp_student_wise_courseRow stud_wise_course_row = stud_wise_course._temp_student_wise_course.Newtemp_student_wise_courseRow();

                    stud_wise_course_row.doc_no = re.ToString();
                    stud_wise_course_row.user_id = user_mst.Rows[i]["user_id"].ToString().Trim();
                    stud_wise_course_row.user_name = user_mst.Rows[i]["user_name"].ToString().Trim();
