    [WebMethod(EnableSession = true)]
    public string get_all_approved_course_list_new(string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)//Ananth 25042019
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = "A1";
        //var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        DataTable course_data = new DataTable();

        //course_data = objmaster.get_approved_course_list_new(user_id, user_type, user_prog_code, sem_code, year_code, "", "");
        course_data = objmaster.get_approved_course_list_all_new(user_id, user_type, user_prog_code, sem_code, year_code, "", "", dept_code);

        DataTable pending_approval_list = new DataTable();

        if (course_data != null)
        {
            DataTable instructor_data = objmaster.Get_course_instructor_data_for_modification(sem_code, year_code, "");
            DataTable instructor_AA_data = objmaster.Get_course_instructor_AA_data_for_modification(sem_code, year_code, "");
            DataTable instructor_TA_data = objmaster.Get_course_instructor_TA_data_for_modification(sem_code, year_code, "");
            DataTable area_data = objmaster.Get_course_area_data_for_modification(sem_code, year_code, "");
            DataTable time_data = objmaster.Get_course_time_day_data_for_modification(sem_code, year_code, "");
            DataTable type_data = objmaster.Get_typology_data();
            DataTable dept_data = objmaster.Get_department_data();
            DataTable prog_data = objmaster.Get_programme_data();
            DataTable prog_level_data = objmaster.Get_programme_level_mst_data();

            pending_approval_list.Columns.Add("course_code");
            pending_approval_list.Columns.Add("type");
            pending_approval_list.Columns.Add("course_type");
            pending_approval_list.Columns.Add("title");
            pending_approval_list.Columns.Add("credit");
            pending_approval_list.Columns.Add("occurence_week");
            pending_approval_list.Columns.Add("course_outline");
            pending_approval_list.Columns.Add("instructor");
            pending_approval_list.Columns.Add("instructor_AA");
            pending_approval_list.Columns.Add("instructor_TA");
            pending_approval_list.Columns.Add("course_desc");
            pending_approval_list.Columns.Add("prerequisite");

            pending_approval_list.Columns.Add("gpa_ngpa");  ////Retured By Ananth

            pending_approval_list.Columns.Add("faculty");
            pending_approval_list.Columns.Add("program");
            pending_approval_list.Columns.Add("program_level_code");
            pending_approval_list.Columns.Add("semester");
            pending_approval_list.Columns.Add("day");
            pending_approval_list.Columns.Add("time");
            pending_approval_list.Columns.Add("area");
            pending_approval_list.Columns.Add("intake");
            pending_approval_list.Columns.Add("remark");
            pending_approval_list.Columns.Add("faculty_approval");
            pending_approval_list.Columns.Add("progcoord_approval");
            pending_approval_list.Columns.Add("ugpg_approval");

            pending_approval_list.Columns.Add("week1");
            pending_approval_list.Columns.Add("week2");
            pending_approval_list.Columns.Add("week3");
            pending_approval_list.Columns.Add("week4");
            pending_approval_list.Columns.Add("week5");
            pending_approval_list.Columns.Add("week6");
            pending_approval_list.Columns.Add("week7");
            pending_approval_list.Columns.Add("week8");
            pending_approval_list.Columns.Add("week9");
            pending_approval_list.Columns.Add("week10");
            pending_approval_list.Columns.Add("week11");
            pending_approval_list.Columns.Add("week12");
            pending_approval_list.Columns.Add("week13");
            pending_approval_list.Columns.Add("week14");
            pending_approval_list.Columns.Add("week15");
            pending_approval_list.Columns.Add("week16");

            pending_approval_list.Columns.Add("week_reference1");
            pending_approval_list.Columns.Add("week_reference2");
            pending_approval_list.Columns.Add("week_reference3");
            pending_approval_list.Columns.Add("week_reference4");
            pending_approval_list.Columns.Add("week_reference5");
            pending_approval_list.Columns.Add("week_reference6");
            pending_approval_list.Columns.Add("week_reference7");
            pending_approval_list.Columns.Add("week_reference8");
            pending_approval_list.Columns.Add("week_reference9");
            pending_approval_list.Columns.Add("week_reference10");
            pending_approval_list.Columns.Add("week_reference11");
            pending_approval_list.Columns.Add("week_reference12");
            pending_approval_list.Columns.Add("week_reference13");
            pending_approval_list.Columns.Add("week_reference14");
            pending_approval_list.Columns.Add("week_reference15");
            pending_approval_list.Columns.Add("week_reference16");


            pending_approval_list.Columns.Add("course_structure");
            pending_approval_list.Columns.Add("course_typology");

            pending_approval_list.Columns.Add("eval_method1");
            pending_approval_list.Columns.Add("backlog");// mode kapil 30112020
            pending_approval_list.Columns.Add("studio_level");// mode kapil 30112020
            pending_approval_list.Columns.Add("studio_mode");// mode kapil 30112020
            pending_approval_list.Columns.Add("Focuse");// mode kapil 30112020
            pending_approval_list.Columns.Add("CouseSubTitle");// mode kapil 30112020

            for (int i = 0; i < course_data.Rows.Count; i++)
            {
                DataRow dr = pending_approval_list.NewRow();

                dr["course_code"] = course_data.Rows[i]["course_code"];
                dr["gpa_ngpa"] = course_data.Rows[i]["gpa_ngpa"];   //Retured By Ananth
                dr["studio_mode"] = course_data.Rows[i]["studio_mode"];    // mode kapil 30112020
                dr["backlog"] = course_data.Rows[i]["backlog"];    // mode kapil 30112020
                dr["studio_level"] = course_data.Rows[i]["sub_category_id"];    // mode kapil 30112020
                dr["Focuse"] = course_data.Rows[i]["Focuse"];
                dr["CouseSubTitle"] = course_data.Rows[i]["CouseSubTitle"];

                DataRow[] type = type_data.Select("type_code = '" + course_data.Rows[i]["course_typology"] + "'");
                if (type.Length > 0)
                {
