    [WebMethod]
    public string get_course_catalog_data(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code)//Ananth 25042019
    {

        try
        {

            DataTable course_data = objmaster.get_course_mst_data_for_catalog_report(sem_code, year_code, dept_code, prog_code, prog_level_code);

            DataTable pending_approval_list = new DataTable();

            if (course_data != null)
            {
                DataTable instructor_data = objmaster.Get_course_instructor_data_for_catalog_report(sem_code, year_code);
                DataTable area_data = objmaster.Get_course_area_data_for_catalog_report(sem_code, year_code);
                DataTable time_data = objmaster.Get_course_time_day_data_for_catalog_report(sem_code, year_code);
                DataTable type_data = objmaster.Get_typology_data();
                DataTable dept_data = objmaster.Get_department_data();
                DataTable prog_data = objmaster.Get_programme_data();
                DataTable prog_level_data = objmaster.Get_programme_level_mst_data();

                pending_approval_list.Columns.Add("course_code");
                pending_approval_list.Columns.Add("type");
                pending_approval_list.Columns.Add("course_type");
                pending_approval_list.Columns.Add("title");
                pending_approval_list.Columns.Add("credit");
                pending_approval_list.Columns.Add("occurence_week");
                pending_approval_list.Columns.Add("course_outline");
                pending_approval_list.Columns.Add("instructor");
                pending_approval_list.Columns.Add("course_desc");
                pending_approval_list.Columns.Add("prerequisite");
                pending_approval_list.Columns.Add("faculty");
                pending_approval_list.Columns.Add("program");
                pending_approval_list.Columns.Add("program_level_code");
                pending_approval_list.Columns.Add("semester");
                pending_approval_list.Columns.Add("day");
                pending_approval_list.Columns.Add("time");
                pending_approval_list.Columns.Add("area");
                pending_approval_list.Columns.Add("intake");
                pending_approval_list.Columns.Add("remark");
                pending_approval_list.Columns.Add("prep_self_study_hrs");

                pending_approval_list.Columns.Add("gpa_ngpa_new");  ////Retured By Ananth

                for (int i = 0; i < course_data.Rows.Count; i++)
                {
                    DataRow dr = pending_approval_list.NewRow();

                    dr["course_code"] = course_data.Rows[i]["course_code"];
                    dr["gpa_ngpa_new"] = course_data.Rows[i]["gpa_ngpa_new"]; ////Retured By Ananth

                    DataRow[] type = type_data.Select("type_code = '" + course_data.Rows[i]["course_typology"] + "'");
                    if (type.Length > 0)
                    {
                        dr["type"] = type[0]["type_name"];
                    }
                    else
                    {
                        dr["type"] = "";
                    }

                    dr["course_type"] = course_data.Rows[i]["course_type"];
                    dr["title"] = course_data.Rows[i]["course_name"];
                    dr["credit"] = course_data.Rows[i]["course_credits"];
                    dr["occurence_week"] = course_data.Rows[i]["occurrence_week"];
                    dr["course_outline"] = course_data.Rows[i]["course_outline"];
                    dr["prep_self_study_hrs"] = course_data.Rows[i]["prep_self_study_hrs"];

                    DataRow[] instructors = instructor_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");

                    string instructor = "";
                    for (int j = 0; j < instructors.Length; j++)
                    {
                        instructor = instructor + instructors[j]["instructor_name"] + ", ";
                    }
                    if (instructor == "")
                    {
                        dr["instructor"] = instructor;
                    }
                    else
                    {
                        dr["instructor"] = instructor.Remove(instructor.Length - 2, 2);
                    }

                    dr["course_desc"] = course_data.Rows[i]["course_desc"];
                    dr["prerequisite"] = course_data.Rows[i]["prerequisite"];

                    DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");
                    if (dept.Length > 0)
                    {
                        dr["faculty"] = dept[0]["dept_name"];
                    }
                    else
                    {
                        dr["faculty"] = "";
                    }

                    DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
                    if (prog.Length > 0)
                    {
                        dr["program"] = prog[0]["prog_name"];
                    }
                    else
                    {
                        dr["program"] = "";
                    }

                    DataRow[] prog_level = prog_level_data.Select("prog_level_code = '" + course_data.Rows[i]["prog_level_code"] + "'");
                    if (prog_level.Length > 0)
                    {
                        dr["program_level_code"] = prog_level[0]["prog_level_desc"];
                    }
                    else
                    {
                        dr["program_level_code"] = "";
                    }

                    dr["semester"] = course_data.Rows[i]["semester_code"];

                    DataRow[] daytimes = time_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                    string day = "";
                    string time = "";

                    if (daytimes.Length > 0)
                    {
                        for (int j = 0; j < daytimes.Length; j++)
                        {
                            day = day + daytimes[j]["day_name"] + ", ";
                            time = time + daytimes[j]["from_time"] + "-" + daytimes[j]["To_time"] + ", ";
                        }
                        if (day == "")
                        {
                            dr["day"] = day;
                        }
                        else
                        {
                            dr["day"] = day.Remove(day.Length - 2, 2);
                        }
                        if (time == "")
                        {
                            dr["time"] = time;
                        }
                        else
                        {
                            dr["time"] = time.Remove(time.Length - 2, 2);
                        }
                    }
                    else
                    {
                        dr["day"] = "";
                        dr["time"] = "";

                    }

                    string area = "";
                    if (area_data != null)
                    {
                        DataRow[] areas = area_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        for (int j = 0; j < areas.Length; j++)
                        {
                            area = area + areas[j]["area_name"] + ", ";
                        }
                    }

                    if (area == "")
                    {
                        dr["area"] = area;
                    }
                    else
                    {
                        dr["area"] = area.Remove(area.Length - 2, 2);
                    }

                    dr["intake"] = course_data.Rows[i]["available_seat"];
                    dr["remark"] = course_data.Rows[i]["remark"];

                    pending_approval_list.Rows.Add(dr);
                }

                if (pending_approval_list != null)
                {
                    jsondata = GetJson1(pending_approval_list);
                }

            }


            return jsondata;

        }
        catch (Exception ex)
        {

            return ex.ToString();
        }
    }

