                    }

                    dr["course_desc"] = course_data.Rows[i]["course_desc"];
                    dr["prerequisite"] = course_data.Rows[i]["prerequisite"];

                    DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");
                    if (dept.Length > 0)
                    {
                        dr["faculty"] = dept[0]["dept_name"];
                    }
                    else
                    {
                        dr["faculty"] = "";
                    }

                    DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
                    if (prog.Length > 0)
                    {
                        dr["program"] = prog[0]["prog_name"];
                    }
                    else
                    {
                        dr["program"] = "";
                    }

