    [WebMethod(EnableSession = true)]
    public string inital_approve_course_I2(String d_course_code, String semester, String year)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();

        string result = "";
        try
        {
            var user_id_tbl = HttpContext.Current.Session["UserId"].ToString();
            result = objmaster.inital_approve_course_I2(d_course_code, semester, year, user_id);
        }
        catch (Exception ex)
        {
            return ex.ToString();
        }
        return result;

    }

    [WebMethod(EnableSession = true)]
    public string get_approved_course_list_new_fa(string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)
