                    {
                        dr["instructor_AA"] = instructor_AA;
                    }
                    else
                    {
                        dr["instructor_AA"] = instructor_AA.Remove(instructor_AA.Length - 2, 2);
                    }
                }
                else
                {
                    dr["instructor_AA"] = "";
                }

                if (instructor_TA_data != null)
                {
                    DataRow[] instructors_TA = instructor_TA_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                    string instructor_TA = "";
                    for (int j = 0; j < instructors_TA.Length; j++)
                    {
                        instructor_TA = instructor_TA + instructors_TA[j]["instructor_name"] + ", ";
                    }
                    if (instructor_TA == "")
                    {
                        dr["instructor_TA"] = instructor_TA;
                    }
                    else
                    {
                        dr["instructor_TA"] = instructor_TA.Remove(instructor_TA.Length - 2, 2);
                    }
                }
                else
                {
                    dr["instructor_TA"] = "";
                }

                dr["course_desc"] = course_data.Rows[i]["course_desc"];
                dr["prerequisite"] = course_data.Rows[i]["prerequisite"];

                DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");
                if (dept.Length > 0)
                {
                    dr["faculty"] = dept[0]["dept_name"];
                }
                else
                {
                    dr["faculty"] = "";
                }

                DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
