                dr["week12"] = course_data.Rows[i]["week12"];
                dr["week13"] = course_data.Rows[i]["week13"];
                dr["week14"] = course_data.Rows[i]["week14"];
                dr["week15"] = course_data.Rows[i]["week15"];
                dr["week16"] = course_data.Rows[i]["week16"];

                dr["week_reference1"] = course_data.Rows[i]["week_reference1"];
                dr["week_reference2"] = course_data.Rows[i]["week_reference2"];
                dr["week_reference3"] = course_data.Rows[i]["week_reference3"];
                dr["week_reference4"] = course_data.Rows[i]["week_reference4"];
                dr["week_reference5"] = course_data.Rows[i]["week_reference5"];
