    [WebMethod]
    public string[] get_all_tables_course_data(string sem_code, string year_code, string course_code)
    {
        string[] data = new string[11];

        DataTable course_data = objmaster.Get_course_data_for_modification(sem_code, year_code, course_code);

        if (course_data != null)
        {
            data[0] = GetJson1(course_data);
        }

        DataTable course_dept_data = objmaster.Get_course_department_data_for_modification(sem_code, year_code, course_code);

        if (course_dept_data != null)
        {
            data[1] = GetJson1(course_dept_data);
        }

        DataTable course_instructor_data = objmaster.Get_course_instructor_data_for_modification(sem_code, year_code, course_code);

        if (course_instructor_data != null)
        {
            data[2] = GetJson1(course_instructor_data);
        }

        DataTable course_area_data = objmaster.Get_course_area_data_for_modification(sem_code, year_code, course_code);

        if (course_area_data != null)
        {
