        {
            data[5] = GetJson1(course_instructor_tutorial_data);
        }

        DataTable course_time_tutorial_data = objmaster.Get_course_time_day_tutorial_data_for_modification(sem_code, year_code, course_code);

        if (course_time_tutorial_data != null)
        {
            data[6] = GetJson1(course_time_tutorial_data);
        }

        DataTable course_wise_AA_data = objmaster.Get_AA_instructor_code_for_course_code(course_code, sem_code, year_code);

