        {
            data[7] = GetJson1(course_wise_AA_data);
        }

        DataTable course_wise_TA_data = objmaster.Get_TA_instructor_code_for_course_code(course_code, sem_code, year_code);

        if (course_wise_TA_data != null)
        {
            data[8] = GetJson1(course_wise_TA_data);
        }

        DataTable course_weekly_percent_criteria = objmaster.Get_course_weekly_percent_criteria(course_code, sem_code, year_code);

        if (course_weekly_percent_criteria != null)
        {
            data[9] = GetJson1(course_weekly_percent_criteria);
        }

        DataTable instructor_wise_time_dtl = objmaster.Get_instructor_wise_course_time(course_code, sem_code, year_code);
        if (instructor_wise_time_dtl != null)
        {
            DataTable dtt = new DataTable();
            DataTable dataTable = new DataTable();
            if (course_instructor_data != null)
            {
                for (int i = 0; i < course_instructor_data.Rows.Count; i++)
                {
                    DataRow[] dr_pending_approval_list_new = instructor_wise_time_dtl.Select("course_code = '" + course_code + "' AND semester_type = '" + sem_code + "' AND year_semester = '" + year_code + "' AND instructor_code = '" + course_instructor_data.Rows[i]["instructor_code"] + "'");
                    if (i == 0)
                    {
                        if (dr_pending_approval_list_new.Length > 0)
                        {
                            dataTable = dr_pending_approval_list_new.CopyToDataTable();

                        }
                    }
                    else
                    {
                        if (dr_pending_approval_list_new.Length > 0)
                        {
                            dtt = dr_pending_approval_list_new.CopyToDataTable();
                            dataTable.Merge(dtt);

                        }

                    }


                }
                data[10] = GetJson1(dataTable);
            }
            else { data[10] = GetJson1(instructor_wise_time_dtl); }




            //data[10] = GetJson1(instructor_wise_time_dtl);


        }

        return data;
    }


