    [WebMethod(EnableSession = true)]
    public string update_course_tables_data(string All_table_course_data)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        //var daynow = ""; if (DateTime.Now.Day < 10) { daynow = "0" + DateTime.Now.Day; } else { daynow = DateTime.Now.Day.ToString(); };
        //var month = ""; if (DateTime.Now.Month < 10) { month = "0" + DateTime.Now.Month; } else { month = DateTime.Now.Month.ToString(); };
        //var datenow = "Temp" + daynow + month;
        if (RateBand.AdditionalHours != null)
        {
            RateBand.AdditionalHours.Clear();
        }
        RateBand.aa_additiona_hrs.Clear();
        RateBand.aa_contact_hrs.Clear();
        RateBand.aa_total_hrs.Clear();
        RateBand.aa_weeks.Clear();
        RateBand.ta_additiona_hrs.Clear();
        RateBand.ta_contact_hrs.Clear();
        RateBand.ta_total_hrs.Clear();
        RateBand.ta_weeks.Clear();
        RateBand.user_type_ta_aa.Clear();


        int re = 0;
        string sem_code = "";

        string directory_path = "C:/Ceptreg_Log/Course_mst_log/";
        string filename = "error";
        var duplicat_value = "";

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            //Dictionary<string, object> data = ser.Deserialize<Dictionary<string, object>>(All_table_course_data);
            ArrayList Course_Master_data = ser.Deserialize<ArrayList>(All_table_course_data);
            Dictionary<string, object> course_weekly_percent_criteria = (Dictionary<string, object>)Course_Master_data[11];
            //var course_data = data["course_data"];
            Dictionary<string, object> course_data = (Dictionary<string, object>)Course_Master_data[0];
            Dictionary<string, object> course_dept = (Dictionary<string, object>)Course_Master_data[1];
            ArrayList instructor = (ArrayList)Course_Master_data[2];
            ArrayList area = (ArrayList)Course_Master_data[3];
            ArrayList daytime = (ArrayList)Course_Master_data[4];
            string action = (string)Course_Master_data[5];
            string new_code = ((string)Course_Master_data[6]).ToString();
            ArrayList instructor_tutorial = (ArrayList)Course_Master_data[7];
            ArrayList daytime_tutorial = (ArrayList)Course_Master_data[8];
            ArrayList instructor_AA = (ArrayList)Course_Master_data[9];
            ArrayList instructor_TA = (ArrayList)Course_Master_data[10];
            //07052022
            ArrayList instructor_time_slot = (ArrayList)Course_Master_data[12];

            string formattedInstructors = "";
            string formattedTA = "";
            string formattedAA = "";
            string CombinData = "";

            if (instructor.Count > 0)
            {
                formattedInstructors = string.Join(", ", instructor.Cast<Dictionary<string, object>>()
                .Select(dict => "'" + dict["instructor_code"].ToString() + "'"));
                CombinData += formattedInstructors;
            }

            if (instructor_TA.Count > 0)
            {
                formattedTA = string.Join(", ", instructor_TA.Cast<Dictionary<string, object>>().Select(dict => "'" + dict["instructor_code"].ToString() + "'"));
            }
            if (instructor_AA.Count > 0)
            {
                formattedAA = string.Join(", ", instructor_AA.Cast<Dictionary<string, object>>().Select(dict => "'" + dict["instructor_code"].ToString() + "'"));
            }
            CombinData = string.Join(", ", new[] { formattedInstructors, formattedTA, formattedAA }.Where(s => !string.IsNullOrWhiteSpace(s)));





            filename = new_code + " (" + DateTime.Now.ToFileTimeUtc().ToString() + ")";
            System.IO.File.WriteAllText(@"" + directory_path + filename + ".txt", "New Course_code : " + new_code + Environment.NewLine);
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "Old Course_code : " + course_data["course_code"] + Environment.NewLine);
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "Action : " + action + Environment.NewLine);
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "User ID : " + user_id + Environment.NewLine);
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "============================================================================================" + Environment.NewLine);
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "JSON Course_data Length : " + course_data.Count + Environment.NewLine);
