    [WebMethod(EnableSession = true)]
    public string update_course_tables_data_studio_proposal(string All_table_course_data)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        if (RateBand.AdditionalHours != null)
        {
            RateBand.AdditionalHours.Clear();
        }
        RateBand.aa_additiona_hrs.Clear();
        RateBand.aa_contact_hrs.Clear();
        RateBand.aa_total_hrs.Clear();
        RateBand.aa_weeks.Clear();

        RateBand.ta_additiona_hrs.Clear();
        RateBand.ta_contact_hrs.Clear();
        RateBand.ta_total_hrs.Clear();
        RateBand.ta_weeks.Clear();
        RateBand.user_type_ta_aa.Clear();


        //var daynow = ""; if (DateTime.Now.Day < 10) { daynow = "0" + DateTime.Now.Day; } else { daynow = DateTime.Now.Day.ToString(); };
        //var month = ""; if (DateTime.Now.Month < 10) { month = "0" + DateTime.Now.Month; } else { month = DateTime.Now.Month.ToString(); };
        //var datenow = "Temp" + daynow + month;

        int re = 0;
        string sem_code = "";
        bool mail_status = false;

        string directory_path = "C:/Ceptreg_Log/Course_mst_log/";
        string filename = "error";
        var duplicat_value = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            //Dictionary<string, object> data = ser.Deserialize<Dictionary<string, object>>(All_table_course_data);
            ArrayList Course_Master_data = ser.Deserialize<ArrayList>(All_table_course_data);
            Dictionary<string, object> course_weekly_percent_criteria = (Dictionary<string, object>)Course_Master_data[11];
            //var course_data = data["course_data"];
            Dictionary<string, object> course_data = (Dictionary<string, object>)Course_Master_data[0];
            Dictionary<string, object> course_dept = (Dictionary<string, object>)Course_Master_data[1];
            ArrayList instructor = (ArrayList)Course_Master_data[2];
            ArrayList area = (ArrayList)Course_Master_data[3];
