                    RateBand.aa_total_hrs.Add(((Dictionary<string, object>)instructor_TA[i])["instructor_code"].ToString().Trim(), total_hrs);
                }

                if (((Dictionary<string, object>)instructor_TA[i])["additional_hours"].ToString().Trim() != "")
                {
                    string additional_hours = ((Dictionary<string, object>)instructor_TA[i])["additional_hours"].ToString().Trim();
                    RateBand.AdditionalHours.Add(((Dictionary<string, object>)instructor_TA[i])["instructor_code"].ToString().Trim(), additional_hours);
                }


                course_wise_instructor_row.cancel_flag = "N";
                course_wise_instructor_row.created_by = user_id;
                course_wise_instructor_row.created_date = DateTime.Now;
                course_wise_instructor_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                course_wise_instructor_row.semester_type = course_data["semester_type"].ToString();
                course_wise_instructor_row.year_semester = course_data["year_semester"].ToString();

                course_master_upload.course_wise_TA.Addcourse_wise_TARow(course_wise_instructor_row);
            }

            // Add New Instructor Time Slot 
            for (int i = 0; i < instructor_time_slot.Count; i++)
            {
                re = re + 1;
                DSC_Course_Master.instructor_wise_course_timeRow instructor_Wise_Course_TimeRow = course_master_upload.instructor_wise_course_time.Newinstructor_wise_course_timeRow();

                instructor_Wise_Course_TimeRow.doc_no = re.ToString();
                instructor_Wise_Course_TimeRow.course_code = course_data["course_code"].ToString().Trim();
                instructor_Wise_Course_TimeRow.instructor_code = ((Dictionary<string, object>)instructor_time_slot[i])["instructor_code"].ToString().Trim();
                instructor_Wise_Course_TimeRow.from_time = ((Dictionary<string, object>)instructor_time_slot[i])["from_time"].ToString().Trim();
                instructor_Wise_Course_TimeRow.to_time = ((Dictionary<string, object>)instructor_time_slot[i])["to_time"].ToString().Trim();
                instructor_Wise_Course_TimeRow.day_code = ((Dictionary<string, object>)instructor_time_slot[i])["day_code"].ToString().Trim();
                instructor_Wise_Course_TimeRow.room_id = ((Dictionary<string, object>)instructor_time_slot[i])["room_id"].ToString().Trim();
                instructor_Wise_Course_TimeRow.time_sq_no = ((Dictionary<string, object>)instructor_time_slot[i])["time_sq_no"].ToString().Trim();
                instructor_Wise_Course_TimeRow.cancel_flag = "N";
                instructor_Wise_Course_TimeRow.created_by = user_id;
                instructor_Wise_Course_TimeRow.created_date = DateTime.Now.ToString();
                instructor_Wise_Course_TimeRow.created_host = HttpContext.Current.Request.UserHostName.ToString();
                instructor_Wise_Course_TimeRow.semester_type = course_data["semester_type"].ToString();
                instructor_Wise_Course_TimeRow.year_semester = course_data["year_semester"].ToString();

                course_master_upload.instructor_wise_course_time.Addinstructor_wise_course_timeRow(instructor_Wise_Course_TimeRow);

            }


            //////////////////////////////////////////////////////////

            // // 

            //if (user_type != "CW")
            //{
            //    objmaster.delete_department_wise_course_dtl_detail(course_data["course_code"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());
            //    objmaster.delete_coursewiseinstructor_detail(course_data["course_code"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());
            //    objmaster.delete_coursewisetime_detail(course_data["course_code"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());
            //    objmaster.delete_coursewisearea_detail(course_data["course_code"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());
            //}

            if (course_data["course_code"].ToString().Trim() == new_code)
            {
                System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "============================================================================================" + Environment.NewLine);
                System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "objMaster.update_course_tables_data()" + Environment.NewLine);
                objBLReturnObject = objMaster.update_course_tables_data(course_master_upload, user_type, user_id, HttpContext.Current.Request.UserHostName);
            }
            else
            {
                System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "============================================================================================" + Environment.NewLine);
                System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "objMaster.excel_course_master_upload()" + Environment.NewLine);
                //objBLReturnObject = objMaster.excel_course_master_upload(course_master_upload, "2000", user_id, HttpContext.Current.Request.UserHostName);
                objBLReturnObject = objMaster.update_course_tables_data_as_new(course_master_upload, "2000", user_id, HttpContext.Current.Request.UserHostName, course_data["course_code"].ToString().Trim());
            }

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                if (course_data["course_code"].ToString().Trim() != new_code)
                {
                    objmaster.delete_coursedata_coursemst(course_data["course_code"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());

                }
                // Check To Be Later Instr ....
                bool status_to_be_later = objmaster.update_delete_studio_instr(instructor, course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), new_code, user_id);

                //bool duplicate_inst_status = 
                bool duplicate_status = objmaster.DeleteDuplicat_value_v2(duplicat_value, new_code, course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim());
                //Rate Band Calculation
                string rate_band_status = get_vf_course_wise_workload_detail_v2(course_data["course_code"].ToString(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), "Y");
                // update no of tutor
                bool no_of_tutor_update = objmaster.updatenooftutor_status_new(course_data["course_code"].ToString(), course_data["no_of_tutor"].ToString().Trim(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), user_id);
                //new development 19012023
                dynamic update_workload_table = objmaster.UpdateForworkloaddtl(course_data["course_code"].ToString(), course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), action);

                //Workload Details Table Row update Cancel_falg ='Y'
                //1
                if (course_data["course_code"].ToString().Trim() != new_code)
                {
                    bool status_inst_workload = objmaster.update_workload_dtl_course_status(course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), course_data["course_code"].ToString(), user_id);
                }

                bool RateBandstatus = objmaster.UpdateCourseWiseWorkLoad("", user_id, course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), HttpContext.Current.Request.UserHostName, "", course_data["course_code"].ToString());

                if (mail_status)
                {
                    DataTable dt_send_mail_data = objmaster.Get_VF_TA_AA_Letter_Email_Body("StudioBrief", "email");
                    DataTable studio_details = objmaster.GetDetailsStudioCodeWise(course_data["course_code"].ToString().Trim(), "");
                    DataTable user_dtl = new DataTable();
                    user_dtl = objmaster.Get_studio_tutor_cotutor(studio_details.Rows[0]["studio_code"].ToString());
                    //user_dtl = objmaster.check_user_by_user_id(studio_details.Rows[0]["user_id"].ToString());

                    DataTable mail_from_id_password = objmaster.check_frommail_id_password("StudioBrief");

                    bool status = objmail.sendmailforBriefsubmit(user_id, "", user_dtl, mail_from_id_password, dt_send_mail_data);
                    mail_status = false;
                }
            }

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else //if (objBLReturnObject.ExecutionStatus == 1)
            {

                string activity_description = "";
                string activity_action_name = "";
                string activity_type = "Studio";
                if (action == "A")
                {
                    activity_description = "Studio Brief Details Submit";
                    activity_action_name = "Submit";
                }
                else
                {
                    activity_description = "Studio Brief Details Save";
                    activity_action_name = "Save";
                }
                //for (int i = 0; i < instructor.Count; i++) 
                //{
                //string instructor_data = ((Dictionary<string, object>)instructor[i])["instructor_code"].ToString().Trim();
                string status_log = studio_log_create(user_id, activity_type, activity_description, activity_action_name, user_id, "", course_data["course_code"].ToString());

                //}




                DSC_Course_Log course_log = new DSC_Course_Log();

                DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                course_log_row.log_id = "1";
                course_log_row.user_id = user_id;
                course_log_row.course_code = course_data["course_code"].ToString();
                course_log_row.remark = "Modify Course";
                course_log_row.created_by = user_id;
                course_log_row.created_date = DateTime.Now;
                course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }

        }
        catch (Exception ex)
        {
            System.IO.File.AppendAllText(@"" + directory_path + filename + ".txt", "============================================================================================" + Environment.NewLine + ex.ToString());
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }

    [WebMethod(EnableSession = true)]
    public string update_course_room_data(string All_table_course_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string create_update_query = "";

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> daytime = ser.Deserialize<List<Dictionary<string, object>>>(All_table_course_data);

            DSC_Course_Master course_master_upload = new DSC_Course_Master();

            if (daytime.Count > 0)
            {
                DataTable course_room_detail = objmaster.Get_course_wise_time(daytime[0]["course_code"].ToString(), daytime[0]["sem_code"].ToString(), daytime[0]["year_code"].ToString());

                if (course_room_detail != null)
                {
                    for (int i = 0; i < daytime.Count; i++)
                    {
                        DataRow[] dr_datetime = course_room_detail.Select("doc_no='" + ((Dictionary<string, object>)daytime[i])["doc_no"].ToString().Trim() + "'");

                        if (dr_datetime.Length > 0)
                        {
                            DSC_Course_Master.course_wise_timeRow course_wise_time_row = course_master_upload.course_wise_time.Newcourse_wise_timeRow();

                            course_wise_time_row.ItemArray = dr_datetime[0].ItemArray;
                            string room_id_code = ((Dictionary<string, object>)daytime[i])["room_id"].ToString().Trim();
                            course_wise_time_row.room_id = ((Dictionary<string, object>)daytime[i])["room_id"].ToString().Trim();
                            course_wise_time_row.last_modified_by = user_id;
                            course_wise_time_row.last_modified_date = DateTime.Now;
                            course_wise_time_row.last_modified_host = HttpContext.Current.Request.UserHostName;
                            create_update_query += " update instructor_wise_course_time set room_id ='" + ((Dictionary<string, object>)daytime[i])["room_id"].ToString().Trim() + "',last_modified_by='" + user_id + "',last_modified_date='" + DateTime.Now + "',last_modified_host='" + HttpContext.Current.Request.UserHostName + "' " +
                                " where semester_type='" + daytime[0]["sem_code"].ToString() + "' and year_semester='" + daytime[0]["year_code"].ToString() + "' " +
                                " and course_code='" + daytime[0]["course_code"].ToString() + "' and time_sq_no='" + ((Dictionary<string, object>)daytime[i])["time_seq_no"].ToString().Trim() + "' ";
                            course_master_upload.course_wise_time.Addcourse_wise_timeRow(course_wise_time_row);
                        }
                    }
                }

                objBLReturnObject = objMaster.update_course_rooms_data(course_master_upload, user_type, user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 1)
                {
                    bool status = objMaster.Excute_update_query(create_update_query);
                    objBLReturnObject.ServerMessage = objBLReturnObject.ServerMessage;
                }

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                }
                else //if (objBLReturnObject.ExecutionStatus == 1)
                {
                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
                    course_log_row.course_code = ((Dictionary<string, object>)daytime[0])["course_code"].ToString().Trim();
                    course_log_row.remark = "Modify Room";
                    course_log_row.created_by = user_id;
                    course_log_row.created_date = DateTime.Now;
                    course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                    course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                    BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                    Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                }
            }
        }
        catch (Exception ex)
        {
            objBLReturnObject.ServerMessage = "Problem in update DATA.";
            return objBLReturnObject.ServerMessage;
        }

        return objBLReturnObject.ServerMessage;
    }

