    //26112019
    [WebMethod(EnableSession = true)]
    public string save_new_course_data(string All_table_course_data)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        if (RateBand.AdditionalHours != null)
        {
            RateBand.AdditionalHours.Clear();
        }
        RateBand.aa_additiona_hrs.Clear();
        RateBand.aa_contact_hrs.Clear();
        RateBand.aa_total_hrs.Clear();
        RateBand.aa_weeks.Clear();

        RateBand.ta_additiona_hrs.Clear();
        RateBand.ta_contact_hrs.Clear();
        RateBand.ta_total_hrs.Clear();
        RateBand.ta_weeks.Clear();
        RateBand.user_type_ta_aa.Clear();

        int re = 0;
        string sem_code = "";
        try
        {

            JavaScriptSerializer ser = new JavaScriptSerializer();

            //Dictionary<string, object> data = ser.Deserialize<Dictionary<string, object>>(All_table_course_data);
            ArrayList Course_Master_data = ser.Deserialize<ArrayList>(All_table_course_data);

            Dictionary<string, object> course_weekly_percent_criteria = (Dictionary<string, object>)Course_Master_data[10];

            //var course_data = data["course_data"];
            Dictionary<string, object> course_data = (Dictionary<string, object>)Course_Master_data[0];
            Dictionary<string, object> course_dept = (Dictionary<string, object>)Course_Master_data[1];
            ArrayList instructor = (ArrayList)Course_Master_data[2];
            ArrayList area = (ArrayList)Course_Master_data[3];
            ArrayList daytime = (ArrayList)Course_Master_data[4];
            string action = (string)Course_Master_data[5];
            ArrayList instructor_tutorial = (ArrayList)Course_Master_data[6];
            ArrayList daytime_tutorial = (ArrayList)Course_Master_data[7];
            ArrayList instructor_AA = (ArrayList)Course_Master_data[8];
            ArrayList instructor_TA = (ArrayList)Course_Master_data[9];

            //For Previous semester and year
            string previousSemester = (string)Course_Master_data[11];
            string previousYear = (string)Course_Master_data[12];

            string saveFor = (string)Course_Master_data[13];
            ArrayList instructor_time_slot = (ArrayList)Course_Master_data[14];

            string semester_type = "";
            string year_semester = "";

            DataTable cur_sem = objmaster.Get_Current_Semester_Detail();

            if (previousSemester != "" && previousYear != "" && saveFor == "P")
            {
                semester_type = previousSemester;
                year_semester = previousYear;
            }
            else
            {
                semester_type = cur_sem.Rows[0]["sem_code"].ToString();
                year_semester = cur_sem.Rows[0]["year_code"].ToString();
            }

            DSC_Course_Master course_master_upload = new DSC_Course_Master();


            DataTable all_course_data = objmaster.Get_all_course_data_For_Modification(semester_type, year_semester);

            //if (course_data["course_code"].ToString().Trim() != new_code)
            //{

            if (all_course_data != null)
            {
                DataRow[] dr_all = all_course_data.Select("course_code='" + course_data["course_code"].ToString().Trim() + "'");

                if (dr_all.Length > 0)
                {
                    return "Course Code is already Available , You can not enter same Course Code again";
                }
            }

            //}

            // // Course Master

            //DataTable Course_mst_Detail = objmaster.Get_course_data_for_modification(course_data["semester_type"].ToString().Trim(), course_data["year_semester"].ToString().Trim(), course_data["course_code"].ToString().Trim());

            DSC_Course_Master.course_mstRow course_mst_row = course_master_upload.course_mst.Newcourse_mstRow();

            DSC_Course_Master.course_weekly_percent_criteriaRow course_weekly_percent_criteria_row = course_master_upload.course_weekly_percent_criteria.Newcourse_weekly_percent_criteriaRow();


            course_mst_row.doc_no = "1";
            course_mst_row.course_code = course_data["course_code"].ToString().Trim();
            course_mst_row.course_desc = course_data["course_description"].ToString().Trim();
            course_mst_row.course_outline = course_data["course_outline"].ToString().Trim();
            course_mst_row.prerequisite = course_data["course_prerequisite"].ToString().Trim();
            course_mst_row.course_name = course_data["course_name"].ToString().Trim();
            course_mst_row.course_credits = course_data["credits"].ToString().Trim();
            course_mst_row.course_type = course_data["type"].ToString().Trim();
            course_mst_row.project = course_data["project"].ToString().Trim();
            course_mst_row.project_name = course_data["project_name"].ToString().Trim();
            course_mst_row.room_id = course_data["room_id"].ToString().Trim();
            course_mst_row.tutorial_offered = course_data["tutorial_offered"].ToString().Trim();
            course_mst_row.backlog = course_data["backlog"].ToString().Trim();//Mayur 25042019
            course_mst_row.studio_mode = course_data["studio_mode"].ToString().Trim();//Mayur 25042019
            course_mst_row.problem_statement = course_data["problem_statement"].ToString().Trim(); // 10-06-2019
            course_mst_row.occurrence_week = daytime.Count.ToString().Trim();
            course_mst_row.remark = course_data["remark"].ToString().Trim();
            course_mst_row.instructor_contact_hrs = course_data["instructor_contact_hrs"].ToString().Trim();
