    [WebMethod]
    public string get_course_data_department_wise(string sem_code, string year_code, string dept_code)
    {
        DataTable get_data = objmaster.get_course_data_department_wise(sem_code, year_code, dept_code);

        if (get_data != null)
        {
            get_data.Columns.Add("instructor");
            get_data.Columns.Add("instructor_TA");

            DataTable get_AA_data = objmaster.get_saved_course_AA_data(sem_code, year_code, "");

            DataTable get_TA_data = objmaster.get_saved_course_TA_data(sem_code, year_code, "");

            if (get_AA_data != null || get_TA_data != null)
            {
                for (int i = 0; i < get_data.Rows.Count; i++)
                {
                    if (get_AA_data != null)
                    {
                        DataRow[] dr_AA = get_AA_data.Select("course_code = '" + get_data.Rows[i]["course_code"].ToString() + "'");
                        string instructor = "";

                        if (dr_AA.Length > 0)
                        {
                            for (int j = 0; j < dr_AA.Length; j++)
                            {
                                instructor = instructor + dr_AA[j]["instructor_name"] + ", ";
                            }

                            if (instructor != "")
                            {
                                get_data.Rows[i]["instructor"] = instructor.Remove(instructor.Length - 2, 2);
                            }
                        }
                    }

                    if (get_TA_data != null)
                    {
                        DataRow[] dr_TA = get_TA_data.Select("course_code = '" + get_data.Rows[i]["course_code"].ToString() + "'");
                        string instructor1 = "";

                        if (dr_TA.Length > 0)
                        {
                            for (int k = 0; k < dr_TA.Length; k++)
                            {
                                instructor1 = instructor1 + dr_TA[k]["instructor_name"] + ", ";
                            }
                            if (instructor1 != "")
                            {
                                get_data.Rows[i]["instructor_TA"] = instructor1.Remove(instructor1.Length - 2, 2);
                            }
                        }
                    }
                }
            }

            jsondata = GetJson1(get_data);
        }

        return jsondata;
    }

