    [WebMethod(EnableSession = true)]
    public string save_course_wise_AA(string course_AA_data, string sem_code, string year_code, string course_code)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();

        int re = 0;
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(course_AA_data);

            DSC_Course_Master course_master_upload = new DSC_Course_Master();

            for (int i = 0; i < data.Count; i++)
            {
                re = re + 1;
                DSC_Course_Master.course_wise_AARow course_wise_instructor_row = course_master_upload.course_wise_AA.Newcourse_wise_AARow();

                course_wise_instructor_row.course_code = course_code;
                course_wise_instructor_row.instructor_code = data[i]["instructor_code"].ToString().Trim();
                //  course_wise_instructor_row.percent_load = ((Dictionary<string, object>)instructor[i])["percent_load"].ToString().Trim();
                course_wise_instructor_row.cancel_flag = "N";
                course_wise_instructor_row.created_by = user_id;
                course_wise_instructor_row.created_date = DateTime.Now;
                course_wise_instructor_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                course_wise_instructor_row.semester_type = sem_code;
                course_wise_instructor_row.year_semester = year_code;

                course_master_upload.course_wise_AA.Addcourse_wise_AARow(course_wise_instructor_row);
            }

            objBLReturnObject = objMaster.save_course_AA_data(course_master_upload, "2000", user_id, HttpContext.Current.Request.UserHostName);
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

