    [WebMethod]
    public string get_tutor_image_data(string instructor_code)
    {
        DataTable tutor_image_data = objmaster.get_tutor_image_data(instructor_code);

        if (tutor_image_data != null)
        {
            DataTable dt = new DataTable();
            dt.TableName = "CloneTable";
            dt = tutor_image_data.Clone();
            string[] value_split = instructor_code.Trim().Split(',');
            for (int i = 0; i < value_split.Length; i++)
            {
                DataRow[] inst_code = tutor_image_data.Select("instructor_code = '" + value_split[i].Replace("'", "") + "'");
                foreach (var item in inst_code)
                {
                    dt.Rows.Add(item.ItemArray);
                }

            }
            if (dt != null)
            {
                DataTable dataTable = objmaster.Get_last_semester_tutor_description(instructor_code);
                if (dataTable != null)
                {
                    dt.Rows[0]["education_description"] = dataTable.Rows[0]["tutor_description"].ToString();
                }

            }
            return jsondata = GetJson1(dt);
        }



        if (tutor_image_data != null)
        {
            jsondata = GetJson1(tutor_image_data);
        }

        return jsondata;
    }

