    [WebMethod(EnableSession = true)]
    public string save_course_data_for_other_dept(string sem_code, string year_code, string course_code, string course_other_dept)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> Course_data = ser.Deserialize<List<Dictionary<string, object>>>(course_other_dept);

            DSC_Course_Master course_master_upload = new DSC_Course_Master();

            for (int i = 0; i < Course_data.Count; i++)
            {
                DSC_Course_Master.course_other_dept_dtlRow dept_wise_course_row = course_master_upload.course_other_dept_dtl.Newcourse_other_dept_dtlRow();

                dept_wise_course_row.dept_code = Course_data[i]["dept_code"].ToString().Trim();
                dept_wise_course_row.course_code = course_code;
                dept_wise_course_row.semester_code = Course_data[i]["semester"].ToString().Trim();
                dept_wise_course_row.course_type = "M";
                dept_wise_course_row.prog_code = Course_data[i]["prog_code"].ToString().Trim();
                dept_wise_course_row.prog_level_code = Course_data[i]["prog_level_code"].ToString().Trim();
                dept_wise_course_row.cancel_flag = "N";
                dept_wise_course_row.created_by = user_id;
                dept_wise_course_row.created_date = DateTime.Now;
                dept_wise_course_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                dept_wise_course_row.semester_type = sem_code;
                dept_wise_course_row.year_semester = year_code;

                course_master_upload.course_other_dept_dtl.Addcourse_other_dept_dtlRow(dept_wise_course_row);
            }

            objBLReturnObject = objMaster.save_course_data_for_other_dept(course_master_upload, "2000", user_id, HttpContext.Current.Request.UserHostName, course_code);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else
            {
                DSC_Course_Log course_log = new DSC_Course_Log();

                DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                course_log_row.log_id = "1";
                course_log_row.user_id = user_id;
                course_log_row.course_code = course_code;
                course_log_row.remark = "Other Dept Add";
                course_log_row.created_by = user_id;
                course_log_row.created_date = DateTime.Now;
                course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

