    [WebMethod(EnableSession = true)]
    public string get_students_completed_credits_report_data(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string enrollment_year, string ReportType)
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();
        string user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable course_data = objmaster.get_students_completed_credits_report_data(sem_code, year_code, user_id, user_type, dept_code, prog_code, prog_level_code, enrollment_year);

        if (ReportType == "NEW" && prog_code == "1")
        {


            DataTable Student_course_data = objmaster.TotalAggregetSubjectData(sem_code, year_code, user_id, user_type, dept_code, prog_code, prog_level_code, enrollment_year);
            if (Student_course_data == null)
            {
                if (course_data != null)
                {
                    return jsondata = GetJson1(course_data);
                }
            }
            DataTable dt_cfp = Student_course_data.Select("course_code IN ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')").CopyToDataTable();
            DataTable dt_course = Student_course_data.Select("course_code Not IN ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')").CopyToDataTable();
            double aggregate = 0;
            int sem1_pass_aggregate = 50;
            int sem2_pass_aggregate = 60;
            double semno = 0;
            int pass_marks = 50;
