            {
                for (int i = 0; i < course_data.Rows.Count; i++)
                {
                    failcredit = 0;
                    totalcredit = 0;
                    MandatoryCreditAllocated = 0;
                    MandatoryCreditPassed = 0;
                    MandatoryCreditFailed = 0;
                    ElectiveCreditAllocated = 0;
                    ElectiveCreditPassed = 0;
                    ElectiveCreditFailed = 0;


                    if (course_data.Rows[i]["user_id"].ToString() == "PG180088")
                    {
                        string ss = "";
                    }
                    DataRow[] dr = Student_course_data.Select("user_id = '" + course_data.Rows[i]["user_id"].ToString() + "' and course_code IN ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')");
                    if (dr.Length > 0)
                    {
                        int yearcode = Convert.ToInt32(dr[0]["yc"].ToString().Substring(1));
                        if (yearcode == 2017 || yearcode == 2018 || yearcode == 2019)
                        {
                            sem1_pass_aggregate = 50;
                        }
                        else if (yearcode >= 2023)
                        {
                            sem1_pass_aggregate = 55;
                            pass_marks = 55;
                        }
                        else
                        {
                            sem1_pass_aggregate = 60;
                            pass_marks = 60;
                        }

                        if (yearcode == 2019)
                        {
                            sem2_pass_aggregate = 65;
                        }


                        if (yearcode >= 2019)
                        {
                            if (sem_code != "" && year_code != "")
                            {
                                if (sem_code != "S" && Convert.ToInt32(year_code) != 2019 || sem_code == "S" && Convert.ToInt32(year_code) > 2019
                                || sem_code == "M" && Convert.ToInt32(year_code) >= 2019)
                                {
                                    grade_style = "NEW";
                                }
                            }
                            else { grade_style = "NEW"; }

                        }

                        if (grade_style == "OLD")
                        {
                            total_marks = 0;
                            total_credits_found = 0;
                            aggregate = 0;
                            final_aggregate = 0;
                            for (int k = 0; k < dr.Length; k++)
                            {
                                if (dr[k]["course_code"].ToString() == "CFP001")
                                {
                                    semno = 1;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
