                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
                                else if (dr[k]["course_code"].ToString() == "CFP005")
                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
                                else if (dr[k]["course_code"].ToString() == "CFP006")
                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
                                else if (dr[k]["course_code"].ToString() == "CFP008")
                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
                                else if (dr[k]["course_code"].ToString() == "CFP009")
                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
