                                {
                                    semno = 2;
                                    total_marks += Convert.ToInt32(dr[k]["Total"].ToString()) * Convert.ToInt32(dr[k]["credits"]);
                                }
                                total_credits_found += Convert.ToInt32(dr[k]["credits"]);
                            }


                            aggregate = total_marks / total_credits_found;

                            final_aggregate = aggregate;
                            if (semno == 1 && final_aggregate >= sem1_pass_aggregate || semno == 2 && final_aggregate >= sem2_pass_aggregate)
                            {
                                totalcredit += total_credits_found;
                                MandatoryCreditAllocated += total_credits_found;
                                MandatoryCreditPassed += total_credits_found;
                            }
                            else
                            {
                                failcredit += total_credits_found;
                                MandatoryCreditAllocated += total_credits_found;
                                MandatoryCreditFailed += total_credits_found;
                            }
                        }
                        else if (grade_style == "NEW")
                        {
                            total_marks = 0;
                            total_credits_found = 0;
                            aggregate = 0;
                            final_aggregate = 0;
                            for (int k = 0; k < dr.Length; k++)
                            {
                                if (dr[k]["course_code"].ToString() == "CFP001")
                                {
                                    semno = 1;

