                                {
                                    semno = 2;

                                }

                                if (semno == 1)
                                {
                                    int totalmarks = Convert.ToInt32(dr[k]["Total"].ToString());
                                    if (!(totalmarks >= pass_marks))
                                    {
                                        MandatoryCreditAllocated += Convert.ToInt32(dr[k]["credits"].ToString());
                                        MandatoryCreditFailed += Convert.ToInt32(dr[k]["credits"].ToString());
                                    }
                                    else
                                    {
                                        MandatoryCreditAllocated += Convert.ToInt32(dr[k]["credits"].ToString());
                                        MandatoryCreditPassed += Convert.ToInt32(dr[k]["credits"].ToString());
                                    }
                                }
                                else if (semno == 2)
                                {
                                    int totalmarks = Convert.ToInt32(dr[k]["Total"].ToString());
                                    if (!(totalmarks >= 60))
