                        }
                    }

                    DataRow[] dr_course = Student_course_data.Select("user_id = '" + course_data.Rows[i]["user_id"].ToString() + "' and course_code Not IN ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')");

                    if (dr_course.Length > 0)
                    {
                        int yearcode = Convert.ToInt32(dr_course[0]["yc"].ToString().Substring(1));
                        if (yearcode == 2017 || yearcode == 2018 || yearcode == 2019)
                        {
                            pass_marks = 50;
                        }
                        else if (yearcode == 2020 || yearcode == 2021 || yearcode == 2022)
                        {
                            pass_marks = 55;
                        }
                        else if (yearcode >= 2023)
                        {
                            pass_marks = 55;
                        }
                        else
                        {
                            pass_marks = 60;
                        }

                        for (int p = 0; p < dr_course.Length; p++)
                        {
                            if (pass_marks <= Convert.ToInt32(dr_course[p]["Total"].ToString()))
                            {
                                if (dr_course[p]["c_type"].ToString() == "M")
                                {
                                    MandatoryCreditAllocated += Convert.ToInt32(dr_course[p]["credits"]);
                                    MandatoryCreditPassed += Convert.ToInt32(dr_course[p]["credits"]);
                                }
                                else if (dr_course[p]["c_type"].ToString() == "E")
                                {
                                    ElectiveCreditAllocated += Convert.ToInt32(dr_course[p]["credits"]);
                                    ElectiveCreditPassed += Convert.ToInt32(dr_course[p]["credits"]);
                                }
                                totalcredit += Convert.ToInt32(dr_course[p]["credits"]);
                            }
                            else
                            {
                                failcredit += Convert.ToInt32(dr_course[p]["credits"]);

                                if (dr_course[p]["c_type"].ToString() == "M")
                                {
                                    MandatoryCreditAllocated += Convert.ToInt32(dr_course[p]["credits"]);
                                    MandatoryCreditFailed += Convert.ToInt32(dr_course[p]["credits"]);
                                }
                                else if (dr_course[p]["c_type"].ToString() == "E")
                                {

                                    ElectiveCreditAllocated += Convert.ToInt32(dr_course[p]["credits"]);
                                    ElectiveCreditFailed += Convert.ToInt32(dr_course[p]["credits"]);
                                }
                            }
                        }
                    }

                    course_data.Rows[i]["M_Passed"] = MandatoryCreditPassed;
                    course_data.Rows[i]["M_Failed"] = MandatoryCreditFailed;
                    course_data.Rows[i]["E_Passed"] = ElectiveCreditPassed;
                    course_data.Rows[i]["E_Failed"] = ElectiveCreditFailed;

                }
            }

        }
        if (course_data != null)
        {
            jsondata = GetJson1(course_data);
        }

        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string get_students_completed_credits_sgpa_cgpa_report_data(string enrollment_year, string dept_code, string prog_code)
    {

        bool getsemestatus = objmaster.InsertDataSemesterCount(enrollment_year);
        decimal gpa_multiplication_sem = 0;
        decimal total_gpa_credit_sem = 0;

        string user_id = HttpContext.Current.Session["UserId"].ToString();
        string user_type = HttpContext.Current.Session["user_type"].ToString();
        if (user_type == "S" || user_type == "E")
        {
            DataTable dt_student_dtl = objmaster.get_user_dept_code_student(user_id);
            dept_code = dt_student_dtl.Rows[0]["dept_code"].ToString();
            prog_code = dt_student_dtl.Rows[0]["prog_code"].ToString();
            enrollment_year = dt_student_dtl.Rows[0]["year_code"].ToString();

        }
        List<Dictionary<string, string>> lst_dic_tran_sem_year = new List<Dictionary<string, string>>();
        lst_dic_tran_sem_year.Add(new Dictionary<string, string>());
        lst_dic_tran_sem_year[0]["sem_code"] = "M";
        string year_semester = enrollment_year.Replace("Y", "");
        lst_dic_tran_sem_year[0]["year_code"] = year_semester;
        DataTable get_current_sem_data = new DataTable();

        DataTable dt_parameter = objmaster.Get_cept_current_sem_data("all");

        DataTable semester_course_data_sgpa = get_student_SemesterGPA_comparison_report_for_CGPA("M", year_semester, dept_code, prog_code, enrollment_year);

        for (int i = 0; i < 15; i++)
        {
            lst_dic_tran_sem_year.Add(new Dictionary<string, string>());

            if (lst_dic_tran_sem_year[i]["sem_code"] == "M")
            {
                lst_dic_tran_sem_year[i + 1]["sem_code"] = "S";
                lst_dic_tran_sem_year[i + 1]["year_code"] = (Convert.ToInt32(lst_dic_tran_sem_year[i]["year_code"]) + 1).ToString();
            }
            else if (lst_dic_tran_sem_year[i]["sem_code"] == "S")
            {
                lst_dic_tran_sem_year[i + 1]["sem_code"] = "M";
                lst_dic_tran_sem_year[i + 1]["year_code"] = lst_dic_tran_sem_year[i]["year_code"];
            }

            //write logic for getting SGPA
            DataTable semester_course_data_sgpa_cgpa = get_student_SemesterGPA_comparison_report_for_CGPA(lst_dic_tran_sem_year[i + 1]["sem_code"].ToString(), lst_dic_tran_sem_year[i + 1]["year_code"].ToString(), dept_code, prog_code, enrollment_year);

            if (semester_course_data_sgpa_cgpa != null)
            {
                //Add into one datatable

                DataRow[] dr_pending_approval_list_new = semester_course_data_sgpa_cgpa.Select("year_code_actual = '" + enrollment_year + "'");

                if (dr_pending_approval_list_new.Length > 0)
                {
                    DataTable dtt = dr_pending_approval_list_new.CopyToDataTable();
                    semester_course_data_sgpa.Merge(dtt);
                }
            }

            if (lst_dic_tran_sem_year[i + 1]["sem_code"].ToString() == dt_parameter.Rows[0]["sem_code"].ToString() && lst_dic_tran_sem_year[i + 1]["year_code"].ToString() == dt_parameter.Rows[0]["year_code"].ToString() && semester_course_data_sgpa_cgpa == null)
            {
                if (user_type == "S" || user_type == "E")
                {
                    get_current_sem_data = objmaster.Get_current_sem_allocated_course_credits(lst_dic_tran_sem_year[i + 1]["sem_code"].ToString(), lst_dic_tran_sem_year[i + 1]["year_code"].ToString(), user_id);
                }

            }
        }
        DataView dv = semester_course_data_sgpa.DefaultView;
        dv.Sort = "user_id asc";
        semester_course_data_sgpa = dv.ToTable();
        semester_course_data_sgpa.Columns.Add("Total_CGPA");
        semester_course_data_sgpa.Columns.Add("Sequence_No", typeof(int));
        int sequenceNo = 1;
        string previousUserId = semester_course_data_sgpa.Rows[0]["user_id"].ToString();
        for (int i = 0; i < semester_course_data_sgpa.Rows.Count; i++)
        {
            string currentUserId = semester_course_data_sgpa.Rows[i]["user_id"].ToString();
            if (currentUserId != previousUserId)
            {
                sequenceNo = 1;
                previousUserId = currentUserId;
            }
            semester_course_data_sgpa.Rows[i]["Sequence_No"] = sequenceNo;
            sequenceNo++;
        }



        semester_course_data_sgpa.Columns.Add("Cumulative_Total_Value", typeof(decimal));
        semester_course_data_sgpa.Columns.Add("Cumulative_Value", typeof(decimal));


        decimal cumulativeTotalSum = 0;
        decimal cumulativeSum = 0;
        string previousUserId_new = semester_course_data_sgpa.Rows[0]["user_id"].ToString();

        for (int i = 0; i < semester_course_data_sgpa.Rows.Count; i++)
        {
            string currentUserId = semester_course_data_sgpa.Rows[i]["user_id"].ToString();

            if (currentUserId != previousUserId_new)
            {
                cumulativeTotalSum = 0;
                cumulativeSum = 0;
                previousUserId_new = currentUserId;
            }

            decimal currentValue = Convert.ToDecimal(semester_course_data_sgpa.Rows[i]["gpa_multiplication"].ToString() == "" ? "0" : semester_course_data_sgpa.Rows[i]["gpa_multiplication"].ToString());
            cumulativeTotalSum += currentValue;
            decimal valuesdata = Convert.ToDecimal(semester_course_data_sgpa.Rows[i]["total_gpa_credit"].ToString() == "" ? "0" : semester_course_data_sgpa.Rows[i]["total_gpa_credit"].ToString());
            cumulativeSum += valuesdata;
            semester_course_data_sgpa.Rows[i]["Cumulative_Total_Value"] = cumulativeTotalSum;
            semester_course_data_sgpa.Rows[i]["Cumulative_Value"] = cumulativeSum;
        }


        //DataTable dt_student_data = objmaster.Get_student_data(enrollment_year, "");
        DataTable dt_student_data = objmaster.Get_student_data_deptprog_proglevel(enrollment_year);
        //dt_student_data = dt_student_data.Select("user_id = 'UC9916'").CopyToDataTable();

        DataTable dt_new = new DataTable();
        dt_new.Clear();
        dt_new.Columns.Add("user_id");
        dt_new.Columns.Add("user_name");
        dt_new.Columns.Add("year_code_actual");
        dt_new.Columns.Add("semester_type");
        dt_new.Columns.Add("year_semester");
        dt_new.Columns.Add("credits_completed");
        dt_new.Columns.Add("sem_grade_point_ratio_actual");
        dt_new.Columns.Add("Total_CGPA");
        dt_new.Columns.Add("dept_name");
        dt_new.Columns.Add("prog_name");
        dt_new.Columns.Add("prog_level_name");
        dt_new.Columns.Add("gpa_multiplication_sem");
        dt_new.Columns.Add("total_gpa_credit_sem");
        dt_new.Columns.Add("semester_wise_total_credit");
        dt_new.Columns.Add("earn_gpa_credit");
        dt_new.Columns.Add("earn_ngpa_credit");
        dt_new.Columns.Add("statussave").DefaultValue = "N";
        dt_new.Columns.Add("semwisetoalmarks");
        dt_new.Columns.Add("semwisemarks");




        dt_new.Columns.Add("TotalCreditRegistered");
        dt_new.Columns.Add("CreditCompleted");
