        dt_new.Columns.Add("semester_wise_cgpa_four_digit");
        dt_new.Columns.Add("dept_code");
        dt_new.Columns.Add("prog_code");
        dt_new.Columns.Add("SemesterCode");


        if (dt_student_data != null)
        {
            for (int j = 0; j < dt_student_data.Rows.Count; j++)
            {
                gpa_multiplication_sem = Convert.ToDecimal(0);
                total_gpa_credit_sem = Convert.ToDecimal(0);

                DataRow[] dr_cgpa_dtl = semester_course_data_sgpa.Select("user_id = '" + dt_student_data.Rows[j]["user_id"].ToString() + "'");
                if (dr_cgpa_dtl.Length > 0)
                {
                    for (int k = 0; k < dr_cgpa_dtl.Length; k++)
                    {
                        if (dr_cgpa_dtl[k].ItemArray[14].ToString() != "" && dr_cgpa_dtl[k].ItemArray[15].ToString() != "")
                        {
                            gpa_multiplication_sem = Decimal.Add(Convert.ToDecimal(gpa_multiplication_sem), Convert.ToDecimal(dr_cgpa_dtl[k].ItemArray[14].ToString()));
                            total_gpa_credit_sem = Decimal.Add(Convert.ToDecimal(total_gpa_credit_sem), Convert.ToDecimal(dr_cgpa_dtl[k].ItemArray[15].ToString()));
                        }
                    }

                    DataTable dtt = dr_cgpa_dtl.CopyToDataTable();

                    if (dtt.Rows.Count > 0)
                    {
                        for (int o = 0; o < dtt.Rows.Count; o++)
