                            DataRow[] dr_cgpa_dtl_new = semester_course_data_sgpa.Select("user_id = '" + dtt.Rows[o]["user_id"].ToString() + "' and semester_type = '" + dtt.Rows[o]["semester_type"].ToString() + "' and year_semester = '" + dtt.Rows[o]["year_semester"].ToString() + "'");


                            DataTable dt_total_credits = objmaster.Get_student_course_allocated_count(dtt.Rows[o]["semester_type"].ToString(), dtt.Rows[o]["year_semester"].ToString(), dtt.Rows[o]["user_id"].ToString());
