                        dt_new.Rows[j]["semester_wise_cgpa_four_digit"] = dr[0]["semester_wise_cgpa_four_digit"];
                        dt_new.Rows[j]["dept_code"] = dr[0]["dept_code"];
                        dt_new.Rows[j]["prog_code"] = dr[0]["prog_code"];
                    }
                    else
                    {
                        dt_new.Rows[j]["statussave"] = "N";
                        dt_new.Rows[j]["TotalCreditRegistered"] = "-";
                        dt_new.Rows[j]["CreditCompleted"] = "-";
                        dt_new.Rows[j]["EarnGPACredits"] = "-";
                        dt_new.Rows[j]["EarnNGPACredits"] = "-";
                        dt_new.Rows[j]["SemesterGPA"] = "-";
                        dt_new.Rows[j]["TotalCGPA"] = "-";
                        dt_new.Rows[j]["semester_wise_cgpa"] = "-";
                        dt_new.Rows[j]["Total_cgpa_four_digit"] = "-";
                        dt_new.Rows[j]["semester_wise_cgpa_four_digit"] = "-";
                        dt_new.Rows[j]["dept_code"] = "-";
                        dt_new.Rows[j]["prog_code"] = "-";
                    }
                }
            }
        }

        if (GetYearWiseSemesterCode != null)
        {
            for (int j = 0; j < dt_new.Rows.Count; j++)
            {
                DataRow[] dr = GetYearWiseSemesterCode.Select("Semester = '" + dt_new.Rows[j]["semester_type"].ToString().Trim() + " " + dt_new.Rows[j]["year_semester"].ToString().Trim() + "'");

                if (dr.Length > 0)
                {
                    dt_new.Rows[j]["SemesterCode"] = dr[0]["SemesterCount"];
                }
            }
        }

        jsondata = GetJson1(dt_new);

        return jsondata;
    }

