    [WebMethod(EnableSession = true)]
    public string get_student_data_for_vertical_course(string course_code, string semester, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        string json_col = "";
        bool status_details = false;
        bool L2_status = false;
        bool L3_status = false;
        bool L4_status = false;

        string col_name = "";
        //var user_type = HttpContext.Current.Session["user_type"].ToString();
        DataTable shortlisted_value = objmaster.total_student_shortlis(course_code, current_ws_sem, current_ws_year);
        DataTable dt_vertical_course_dtl = objmaster.get_vertical_studio_course_for_instructor(user_id, current_ws_sem, current_ws_year);
        DataTable department_wise_level_code = objmaster.Get_course_department_data_for_modification(current_ws_sem, current_ws_year, course_code);
        if (dt_vertical_course_dtl != null)
        {
            DataRow[] dr_vertical_course_dtl = dt_vertical_course_dtl.Select("course_code='" + course_code + "'");

            if (dr_vertical_course_dtl.Length > 0)
            {
                DataTable dt_student_data = objmaster.get_student_data_for_vertical_course(course_code, current_ws_sem, current_ws_year);
                //changes09072020
                if (dt_student_data != null)
                {
                    //DataTable priority_status = objMaster.get_semester_wise_preference(current_ws_sem, current_ws_year);
                    DataTable priority_status = get_only_table_dtl(current_ws_sem, current_ws_year);
                    dt_student_data.Columns.Add("priority_status");
                    dt_student_data.Columns.Add("parameter_status");
                    dt_student_data.Columns.Add("short_list_count");

                    dt_student_data.Columns.Add("checkbox_true_false");
                    foreach (DataRow row in dt_student_data.Rows)
                    {
                        DataRow[] dt = priority_status.Select("preference_number = '" + row["priority"] + "'");
                        if (dt.Length > 0)
                        {
                            if (dt[0]["status"].ToString() == "E")
                            {
                                row["priority_status"] = "E";
                                col_name = "";
                                if (department_wise_level_code.Rows[0]["dept_code"].ToString() == "1")
                                {
                                    col_name = "FA";
                                }
                                else if (department_wise_level_code.Rows[0]["dept_code"].ToString() == "2")
                                {
                                    col_name = "FD";
                                }
                                else if (department_wise_level_code.Rows[0]["dept_code"].ToString() == "3")
                                {
                                    col_name = "FM";
                                }
                                else if (department_wise_level_code.Rows[0]["dept_code"].ToString() == "4")
                                {
                                    col_name = "FP";
                                }
                                else if (department_wise_level_code.Rows[0]["dept_code"].ToString() == "5")
                                {
                                    col_name = "FT";
                                }
                                json_col = dt[0][col_name].ToString();
                                //status_details = true;
                                L2_status = false;
                                L3_status = false;
                                L4_status = false;
                                bool check_status = true;
                                JavaScriptSerializer ser = new JavaScriptSerializer();
                                // Sub Categoriy
                                ArrayList level_value = ser.Deserialize<ArrayList>(json_col);
                                if (col_name != "FM")
                                {
                                    L2_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[0])["value"].ToString().Trim());
                                    L3_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[1])["value"].ToString().Trim());
                                    L4_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[2])["value"].ToString().Trim());
                                }
                                else
                                {
                                    L2_status = Convert.ToBoolean("false");
                                    L3_status = Convert.ToBoolean("false");
                                    L4_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[0])["value"].ToString().Trim());
                                }
                                if (L2_status == true || L3_status == true || L4_status == true)
                                {
                                    check_status = true;
                                    if (L2_status)
                                    {
                                        if (department_wise_level_code.Rows[0]["sub_category_id"].ToString() == "L2")
                                        {
                                            row["priority_status"] = "E";
                                            check_status = false;
                                        }
                                        // else { row["priority_status"] = "D"; }
                                    }
                                    if (L3_status)
                                    {
                                        if (department_wise_level_code.Rows[0]["sub_category_id"].ToString() == "L3")
                                        {
                                            row["priority_status"] = "E";
                                            check_status = false;
                                        }
                                        //else { row["priority_status"] = "D"; }
                                    }
                                    if (L4_status)
                                    {
                                        if (department_wise_level_code.Rows[0]["sub_category_id"].ToString() == "L4")
                                        {
                                            row["priority_status"] = "E";
                                            check_status = false;
                                        }
                                        //else { row["priority_status"] = "D"; }
                                    }

                                }
                                else
                                {
                                    row["priority_status"] = "D";
                                }

                                if (check_status)
                                {
                                    row["priority_status"] = "D";

                                }

                            }
                            else
                            {
                                row["priority_status"] = "D";
                            }
                        }
                        else
                        {
                            row["priority_status"] = "D";
                        }

                    }
                    DataTable dtparameter = objMaster.get_parameter_value("Studio Allocation");
                    DataTable check_box = objmaster.Check_Checkbox_enable_disable(course_code, current_ws_sem, current_ws_year);
                    if (dtparameter != null)
                    {
                        string valueparameter = dtparameter.Rows[0]["parameter_value"].ToString();
                        for (int i = 0; i < dt_student_data.Rows.Count; i++)
                        {
                            dt_student_data.Rows[i]["parameter_status"] = valueparameter;
                            if (check_box != null)
                            {
                                dt_student_data.Rows[i]["checkbox_true_false"] = check_box.Rows[0]["Checkbox"].ToString();
                            }
                            else { dt_student_data.Rows[i]["checkbox_true_false"] = "False"; }

                        }
                    }
                    dt_student_data.Rows[0]["short_list_count"] = shortlisted_value.Rows[0]["countrow"].ToString();
                }




                if (dt_student_data != null)
                {
                    jsondata = GetJson1(dt_student_data);
                }
            }
        }

        return jsondata;
    }

