    [WebMethod(EnableSession = true)]
    public string allocate_vertical_studio_course(string student_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> data = ser.Deserialize<Dictionary<string, object>>(student_data);

            DataTable dt_vertical_course_dtl = objmaster.get_vertical_studio_course_for_instructor(user_id, current_ws_sem, current_ws_year);

            if (dt_vertical_course_dtl != null)
            {
                DataRow[] dr_vertical_course_dtl = dt_vertical_course_dtl.Select("course_code='" + data["course_code"].ToString() + "'");

                if (dr_vertical_course_dtl.Length > 0)
                {
                    DataTable dt_student_data = objmaster.get_student_data_for_vertical_course(data["course_code"].ToString(), current_ws_sem, current_ws_year);
                    DataTable dt_course_data = objmaster.get_vertical_studio_course_data(data["course_code"].ToString(), current_ws_sem, current_ws_year);
                    DataTable dt_allocation_dtl = objmaster.get_student_course_allocation(data["user_id"].ToString(), current_ws_sem, current_ws_year);
                    DataTable dt_course_alloc_dtl = objmaster.get_course_allocated_seats(data["course_code"].ToString(), current_ws_sem, current_ws_year);

                    if (dt_course_data != null)
                    {
                        int available_seats = 0;
                        if (Int32.TryParse(dt_course_data.Rows[0]["available_seat"].ToString(), out available_seats) && available_seats > 0)
                        {
                            if (dt_course_alloc_dtl != null)
                            {
                                if (available_seats <= Int32.Parse(dt_course_alloc_dtl.Rows[0]["allocated_seats"].ToString()))
                                {
                                    return return_ajax_string("False2", "Can not Allocate Course. No seats are available to allocate course");
                                }
                            }
                        }
                        else
                        {
                            return return_ajax_string("False2", "Can not Allocate Course. No seats are available to allocate course");
                        }
                    }
                    else
                    {
                        return return_ajax_string("False2", "Can not Allocate Course. Course Data not Found. Please try again.");
                    }

                    if (dt_student_data != null)
                    {
                        // add a column for vertical_studio_allocation.aspx remove column 05082021
                        dt_student_data.Columns.Remove("user_name");
                        dt_student_data.Columns.Remove("portfolio_link");
                        dt_student_data.Columns.Remove("gender");
                        dt_student_data.Columns.Remove("studio_type");
                        DataRow[] dr_student_data = dt_student_data.Select("user_id='" + data["user_id"].ToString() + "' and cancel_flag='N'");

                        if (dr_student_data.Length > 0)
                        {
                            DSC_Vertical_Studio_Selection_dtl dsc_vertical_studio = new DSC_Vertical_Studio_Selection_dtl();

                            DSC_Vertical_Studio_Selection_dtl.vertical_studio_selection_dtlRow vertical_studio_row = dsc_vertical_studio.vertical_studio_selection_dtl.Newvertical_studio_selection_dtlRow();

                            vertical_studio_row.ItemArray = dr_student_data[0].ItemArray;

                            vertical_studio_row.status = "A";
                            vertical_studio_row.remarks = data["remarks"].ToString();
                            vertical_studio_row.last_modified_by = user_id;
                            vertical_studio_row.last_modified_date = DateTime.Now;
                            vertical_studio_row.last_modified_host = HttpContext.Current.Request.UserHostName;

                            dsc_vertical_studio.vertical_studio_selection_dtl.Addvertical_studio_selection_dtlRow(vertical_studio_row);

                            Ds_Student_Course_detail.student_course_allocate_dtlRow studio_course_new = obj_student.student_course_allocate_dtl.Newstudent_course_allocate_dtlRow();

                            if (dt_allocation_dtl != null)
                            {
                                DataRow[] dr_allocation_dtl = dt_allocation_dtl.Select("course_code='" + data["parent_course"].ToString() + "'");

                                if (dr_allocation_dtl.Length > 0)
                                {
                                    DataRow[] dr_allocation_dtl2 = dt_allocation_dtl.Select("course_code='" + data["course_code"].ToString() + "'");

                                    if (dr_allocation_dtl2.Length <= 0)
                                    {
                                        Ds_Student_Course_detail.student_course_allocate_dtlRow studio_parent_course = obj_student.student_course_allocate_dtl.Newstudent_course_allocate_dtlRow();

                                        studio_parent_course.ItemArray = dr_allocation_dtl[0].ItemArray;
                                        studio_parent_course.cancel_flag = "Y";
                                        studio_parent_course.last_modified_by = user_id;
                                        studio_parent_course.last_modified_date = DateTime.Now;
                                        studio_parent_course.last_modified_host = HttpContext.Current.Request.UserHostName;

                                        obj_student.student_course_allocate_dtl.Addstudent_course_allocate_dtlRow(studio_parent_course);

                                        studio_course_new.doc_no = "new";
                                        studio_course_new.user_id = data["user_id"].ToString();
                                        studio_course_new.year_code = studio_parent_course.year_code.ToString();
                                        studio_course_new.course_code = data["course_code"].ToString();
                                        studio_course_new.semester_code = dt_course_data.Rows[0]["semester_code"].ToString();
                                        studio_course_new.current_sem_code = studio_parent_course.current_sem_code.ToString();
                                        studio_course_new.course_type = data["course_type"].ToString();
                                        studio_course_new.credits = dt_course_data.Rows[0]["course_credits"].ToString();
                                        studio_course_new.gpa_nongpa = data["gpa_ngpa"].ToString();

                                        try { studio_course_new.dept_code = studio_parent_course.dept_code.ToString(); }
                                        catch (Exception ex) { }

                                        studio_course_new.cancel_flag = "N";
                                        studio_course_new.created_by = user_id;
                                        studio_course_new.created_date = DateTime.Now;
                                        studio_course_new.created_host = HttpContext.Current.Request.UserHostName;
                                        studio_course_new.semester_type = studio_parent_course.semester_type.ToString();
                                        studio_course_new.year_semester = studio_parent_course.year_semester.ToString();

                                        obj_student.student_course_allocate_dtl.Addstudent_course_allocate_dtlRow(studio_course_new);

                                        objBLReturnObject = objMaster.allocate_vertical_studio_course(dsc_vertical_studio, obj_student, "2000", user_id, HttpContext.Current.Request.UserHostName);

                                        if (objBLReturnObject.ExecutionStatus == 1)
                                        {
                                            return return_ajax_string("True", objBLReturnObject.ServerMessage);
                                        }
                                        else
                                        {
                                            objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                                            return return_ajax_string("False", objBLReturnObject.ServerMessage);
                                        }
                                    }
                                    else
                                    {
                                        return return_ajax_string("False2", "Can not Allocate Course. Course is already Allocated to student");
                                    }
                                }
                                else
                                {
                                    return return_ajax_string("False2", "Problem in Allocation. Allocation not found for course " + data["parent_course"].ToString());
                                }
                            }
                            else
                            {
                                return return_ajax_string("False2", "Problem in Allocation. Allocation not found for course " + data["parent_course"].ToString());
                            }
                        }
                        else
                        {
                            return return_ajax_string("False2", "Can not Allocate Course. Other Course is already Allocated to student");
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("False", "Problem in update DATA. " + ex.ToString());
        }

        return objBLReturnObject.ServerMessage;
    }

