    [WebMethod(EnableSession = true)]
    public string get_vertical_studio_allocation_status(int page_no, string course_code, string dept_code, string sub_cat_id)//kapil 09072020
    {
        //var user_id = HttpContext.Current.Session["UserId"].ToString();
        //var user_type = HttpContext.Current.Session["user_type"].ToString();

        int limit = 20;
        string str = "";
        string allocte_student = "";
        //int brcount = 4;
        //int brrowcount = 4;
