        DataTable allocate_dt_parent = new DataTable();
        DataTable final_dt_vertical_course_dtl = new DataTable();

        DataTable dt_vertical_course_dtl = objmaster.get_vertical_studio_allocation_status(current_ws_sem, current_ws_year, page_no, limit, course_code, dept_code, sub_cat_id);

        if (dt_vertical_course_dtl == null)
        {
            page_no = 1;

            dt_vertical_course_dtl = objmaster.get_vertical_studio_allocation_status(current_ws_sem, current_ws_year, page_no, limit, course_code, dept_code, sub_cat_id);
        }

        if (dt_vertical_course_dtl != null)
        {
            //final_dt_vertical_course_dtl = objmaster.get_count_priority_studio_allocation(dt_vertical_course_dtl, current_ws_sem, current_ws_year);

            dt_vertical_course_dtl.Columns.Add("count_priority", typeof(string));
            final_dt_vertical_course_dtl = objmaster.get_count_priority_studio_allocation_V2(current_ws_sem, current_ws_year);
            dt_vertical_course_dtl.Columns.Add("allocate_stu");
            dt_vertical_course_dtl.Columns.Add("short_list_stu");

            //Mahroofbhai Said 27122021 Remove 2 column
            if (dt_vertical_course_dtl.Rows.Count > 0)
            {
                allocate_dt_parent = objmaster.get_student_allcate_course_dtl_data_V2(current_ws_sem, current_ws_year);
                dt_parent = objmaster.first_priority_shortlist_student_V2(current_ws_sem, current_ws_year);

                for (int i = 0; i < dt_vertical_course_dtl.Rows.Count; i++)
                {
                    str = "";
                    allocte_student = "";
                    //allocate_dt = objmaster.get_student_allcate_course_dtl_data(current_ws_sem, current_ws_year, dt_vertical_course_dtl.Rows[i]["course_code"].ToString());
                    //dt = objmaster.first_priority_shortlist_student(dt_vertical_course_dtl.Rows[i]["course_code"].ToString(), current_ws_sem, current_ws_year);
                    DataTable dt_CC = new DataTable();
                    DataTable dt_CC_data = new DataTable();
                    DataTable dt = new DataTable();
                    DataTable allocate_dt = new DataTable();
                    if (final_dt_vertical_course_dtl.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").Length != 0)
                    {
                        dt_CC_data.Columns.Add("course_code", typeof(string));
                        dt_CC_data.Columns.Add("priority", typeof(string));
                        dt_CC_data.Columns.Add("count_priority", typeof(string));

                        dt_CC = final_dt_vertical_course_dtl.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").CopyToDataTable();
                        dt_CC.DefaultView.Sort = "priority ASC";
                        dt_CC = dt_CC.DefaultView.ToTable();

                        var grouped = from table in dt_CC.AsEnumerable()
                                      group table by new { placeCol = table["priority"] } into groupby
                                      select new
                                      {
                                          Value = groupby.Key,
                                          ColumnValues = groupby
                                      };

                        foreach (var key in grouped)
                        {
                            DataRow dr = dt_CC_data.NewRow();
                            dr["course_code"] = dt_vertical_course_dtl.Rows[i]["course_code"].ToString();
                            dr["priority"] = key.Value.placeCol.ToString();
                            int a = 0;
                            foreach (var columnValue in key.ColumnValues)
                            {
                                a = a + 1;
                                Console.WriteLine(columnValue["user_id"].ToString());
                            }
                            dr["count_priority"] = a.ToString();
                            dt_CC_data.Rows.Add(dr);
                        }

                        dt_vertical_course_dtl.Rows[i]["count_priority"] = GetJson1(dt_CC_data);
                    }
                    else
                    {
                        dt_vertical_course_dtl.Rows[i]["count_priority"] = "\"\"";
                    }
                    if (allocate_dt_parent.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").Length != 0)
                    {
                        allocate_dt = allocate_dt_parent.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").CopyToDataTable();
                    }
                    if (dt_parent != null && dt_parent.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").Length != 0)
                    {
                        dt = dt_parent.Select("course_code='" + dt_vertical_course_dtl.Rows[i]["course_code"].ToString() + "'").CopyToDataTable();
                    }

                    if (dt != null)
                    {
                        for (int j = 0; j < dt.Rows.Count; j++)
                        {
                            if (j < dt.Rows.Count - 1)
                            {
                                str = str + dt.Rows[j]["user_id"].ToString() + ", ";
                            }
                            else
                            {
                                str = str + dt.Rows[j]["user_id"].ToString();
                            }
                        }
                        dt_vertical_course_dtl.Rows[i]["short_list_stu"] = str;
                    }

                    if (allocate_dt != null)
                    {
                        for (int k = 0; k < allocate_dt.Rows.Count; k++)
                        {
                            if (k < allocate_dt.Rows.Count - 1)
                            {
                                allocte_student = allocte_student + allocate_dt.Rows[k]["user_id"].ToString() + ", ";
                            }
                            else
                            {
                                allocte_student = allocte_student + allocate_dt.Rows[k]["user_id"].ToString();
                            }
                        }
                        dt_vertical_course_dtl.Rows[i]["allocate_stu"] = allocte_student;
                    }
                }

            }
            //Mahroofbhai Said 27122021 Remove 2 column

            //get_student_allcate_course_dtl_data(sem_code, year_code, course_code);

            jsondata = GetJson1(dt_vertical_course_dtl);
        }
        else
        {
            jsondata = "\"\"";//If null
        }

        return return_ajax_data(page_no.ToString(), jsondata);
    }

