    [WebMethod(EnableSession = true)]
    public string save_student_vertical_studio_course_priority(string jsonString)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string User_id;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "user id not found");
            }
            else
            {
                User_id = HttpContext.Current.Session["UserId"].ToString();
            }

            List<Dictionary<string, object>> registration_data = ser.Deserialize<List<Dictionary<string, object>>>(jsonString);
            DSC_Vertical_Studio_Selection_dtl obj_Vertical_Studio_Selection = new DSC_Vertical_Studio_Selection_dtl();

            for (int i = 0; i < registration_data.Count; i++)
            {
                DSC_Vertical_Studio_Selection_dtl.vertical_studio_selection_dtlRow Vertical_Studio_Selection_row = obj_Vertical_Studio_Selection.vertical_studio_selection_dtl.Newvertical_studio_selection_dtlRow();

                int random_no;
                string status = registration_data[i]["status"].ToString();

                if (status == "R" && status != String.Empty)
                {
                    Random random = new Random();
                    random_no = random.Next(1000, 9999);
                    Vertical_Studio_Selection_row.random_number = Convert.ToString(random_no);
                }

                Vertical_Studio_Selection_row.user_id = User_id;
                Vertical_Studio_Selection_row.course_code = registration_data[i]["course_code"].ToString();
                Vertical_Studio_Selection_row.parent_course = registration_data[i]["parent_course"].ToString();
                Vertical_Studio_Selection_row.priority = Convert.ToInt16(registration_data[i]["priority"].ToString());
                Vertical_Studio_Selection_row.status = registration_data[i]["status"].ToString();
                Vertical_Studio_Selection_row.semester_type = current_ws_sem;
                Vertical_Studio_Selection_row.year_semester = current_ws_year;
                Vertical_Studio_Selection_row.cancel_flag = "N";
                Vertical_Studio_Selection_row.created_by = HttpContext.Current.Session["UserId"].ToString();
                Vertical_Studio_Selection_row.created_date = DateTime.Now;
                Vertical_Studio_Selection_row.created_host = HttpContext.Current.Request.UserHostName;

                ////course_master_upload.course_wise_time.Addcourse_wise_timeRow(course_wise_time_row);

                obj_Vertical_Studio_Selection.vertical_studio_selection_dtl.Addvertical_studio_selection_dtlRow(Vertical_Studio_Selection_row);
            }

            objBLReturnObject = objMaster.save_vertical_studio_selection_data(obj_Vertical_Studio_Selection, "2000", HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                return return_ajax_string("0", "Data Saved Successfully");
            }
            else
            {
                return return_ajax_string("1", "Problem in Save data");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }

        return objBLReturnObject.ServerMessage;
    }

