    [WebMethod(EnableSession = true)]
    public string shortlist_student_report(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string course_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        DataTable get_data = objmaster.get_shortlist_course_data(sem_code, year_code, dept_code, prog_code, prog_level_code, course_code);

        DataTable dt_vertical_course_dtl = objmaster.get_vertical_studio_course_for_instructor(user_id, sem_code, year_code);

        if (get_data != null)
        {
            get_data.Columns.Add("user_status");
            if (dt_vertical_course_dtl != null)
            {
                get_data.Rows[0]["user_status"] = "E";
            }
            else
            {
                get_data.Rows[0]["user_status"] = "D";
            }
            jsondata = GetJson1(get_data);
        }
        else
        {
            return null;
        }

        return jsondata;
    }

