            //        vertical_Preference_MstRow.status = data[i]["status"].ToString();
            //        vertical_Preference_MstRow.cancel_flag = "N";
            //        vertical_Preference_MstRow.semester_type = data[i]["semester_type"].ToString();
            //        vertical_Preference_MstRow.year_semester = data[i]["year_semester"].ToString();

            //        dSC_DRP.vertical_preference_mst.Addvertical_preference_mstRow(vertical_Preference_MstRow);

            //}

            //objBLReturnObject = objMaster.save_preference_dtl(dSC_DRP, "2000", user_id, HttpContext.Current.Request.UserHostName);


            DataTable get_preference_dtl = objmaster.get_semester_wise_preference(data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());
            for (int i = 0; i < data.Count; i++)
            {
                //DataRow[] dr = get_preference_dtl.Select("doc_no ='" + data[i]["doc_no"].ToString() + "'");
                DataRow[] dr = get_preference_dtl.Select("preference_name ='" + data[i]["preference"].ToString() + "'");

                if (dr.Length > 0)
                {
                    if (data[i]["status"].ToString() != "")
                    {
                        for (int k = 0; k < dr.Length; k++)
                        {
                            dr[0]["status"] = data[i]["status"].ToString();

                            //JavaScriptSerializer ser = new JavaScriptSerializer();
                            //if (col_name != "FM")
                            //{
                            //    L2_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[0])["value"].ToString().Trim());
                            //    L3_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[1])["value"].ToString().Trim());
                            //    L4_status = Convert.ToBoolean(((Dictionary<string, object>)level_value[2])["value"].ToString().Trim());
                            //}

                            if (dr[k]["dept_code"].ToString() == "1")
                            {
                                ArrayList level_value_fa = ser.Deserialize<ArrayList>(data[i]["value_FA"].ToString());
                                dr[k]["Level_L2"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fa[0])["value"].ToString().Trim());
                                dr[k]["Level_L3"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fa[1])["value"].ToString().Trim());
                                dr[k]["Level_L4"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fa[2])["value"].ToString().Trim());
                                dr[k]["dept_code"] = "1";

                            }
                            if (dr[k]["dept_code"].ToString() == "2")
                            {
                                ArrayList level_value_fd = ser.Deserialize<ArrayList>(data[i]["value_FD"].ToString());
                                dr[k]["Level_L2"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fd[0])["value"].ToString().Trim());
                                dr[k]["Level_L3"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fd[1])["value"].ToString().Trim());
                                dr[k]["Level_L4"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fd[2])["value"].ToString().Trim());
                                dr[k]["dept_code"] = "2";
                            }
                            if (dr[k]["dept_code"].ToString() == "3")
                            {
                                ArrayList level_value_fm = ser.Deserialize<ArrayList>(data[i]["value_FM"].ToString());
                                dr[k]["Level_L2"] = "False";
                                dr[k]["Level_L3"] = "False";
                                dr[k]["Level_L4"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fm[0])["value"].ToString().Trim());
                                dr[k]["dept_code"] = "3";
                            }
                            if (dr[k]["dept_code"].ToString() == "4")
                            {
                                ArrayList level_value_fp = ser.Deserialize<ArrayList>(data[i]["value_FP"].ToString());
                                dr[k]["Level_L2"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fp[0])["value"].ToString().Trim());
                                dr[k]["Level_L3"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fp[1])["value"].ToString().Trim());
                                dr[k]["Level_L4"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_fp[2])["value"].ToString().Trim());
                                dr[k]["dept_code"] = "4";
                            }
                            if (dr[k]["dept_code"].ToString() == "5")
                            {
                                ArrayList level_value_ft = ser.Deserialize<ArrayList>(data[i]["value_FT"].ToString());
                                dr[k]["Level_L2"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_ft[0])["value"].ToString().Trim());
                                dr[k]["Level_L3"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_ft[1])["value"].ToString().Trim());
                                dr[k]["Level_L4"] = Convert.ToBoolean(((Dictionary<string, object>)level_value_ft[2])["value"].ToString().Trim());
                                dr[k]["dept_code"] = "5";
                            }
                            dr[k]["doc_no"] = dr[k]["doc_no"];
                            dr[k]["last_modified_by"] = user_id;
                            dr[k]["last_modified_date"] = DateTime.Now;
                            dr[k]["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                            dSC_DRP.vertical_preference_mst.ImportRow(dr[k]);
                        }





                        //dr[0]["FA"] = data[i]["value_FA"].ToString();
                        //dr[0]["FD"] = data[i]["value_FD"].ToString(); 
                        //dr[0]["FT"] = data[i]["value_FT"].ToString();
                        //dr[0]["FP"] = data[i]["value_FP"].ToString();
                        //dr[0]["FM"] = data[i]["value_FM"].ToString();


                    }

                }
            }

            objBLReturnObject = objMaster.save_preference_dtl(dSC_DRP, "2000", user_id, HttpContext.Current.Request.UserHostName);


            if (objBLReturnObject.ExecutionStatus == 1)
            {
                bool status = objmaster.duplicat_value_insert_vertical_preference_mst(data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());
            }
            else if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

