    [WebMethod(EnableSession = true)]
    public string get_semester_wise_preference(string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        DataTable preference_data = objmaster.get_semester_wise_preference(sem_code, year_code);
        DataTable count_number = objmaster.get_total_count_number(sem_code, year_code);
        //int count_row = Convert.ToInt32(count_number.Rows[0]["count"].ToString());
        if (preference_data != null)
        {
            DataTable dt = new DataTable();
            dt.Clear();
            dt.Columns.Add("doc_no");
            dt.Columns.Add("preference_number");
            dt.Columns.Add("preference_name");
            dt.Columns.Add("status");
            dt.Columns.Add("semester_type");
            dt.Columns.Add("year_semester");
            dt.Columns.Add("cancel_flag");
            dt.Columns.Add("FA");
            dt.Columns.Add("FD");
            dt.Columns.Add("FT");
            dt.Columns.Add("FP");
            dt.Columns.Add("FM");
            for (int i = 0; i < Convert.ToInt32(count_number.Rows.Count); i++)
            {
                DataRow[] dr = preference_data.Select("preference_number = '" + count_number.Rows[i]["preference_number"] + "'");
                if (dr.Length > 0)
                {
                    DataRow dataRow = dt.NewRow();
                    for (int k = 0; k < dr.Length; k++)
                    {
                        if (k == 0)
                        {
                            dataRow["doc_no"] = dr[k]["doc_no"].ToString();
                            dataRow["preference_number"] = dr[k]["preference_number"].ToString();
                            dataRow["preference_name"] = dr[k]["preference_name"].ToString(); ;
                            dataRow["status"] = dr[k]["status"].ToString(); ;
                            dataRow["semester_type"] = dr[k]["semester_type"].ToString(); ;
                            dataRow["year_semester"] = dr[k]["year_semester"].ToString(); ;
                            dataRow["cancel_flag"] = "N";
                        }
                        string strmsg = "";
                        if (dr[k]["dept_code"].ToString() == "1")
                        {
                            strmsg = "[{\"key\":\"FA_L2\",\"value\":\"" + dr[k]["Level_L2"].ToString() + "\"},{\"key\":\"FA_L3\",\"value\":\"" + dr[k]["Level_L3"].ToString() + "\"},{\"key\":\"FA_L4\",\"value\":\"" + dr[k]["Level_L4"].ToString() + "\"}]";
                            dataRow["FA"] = strmsg;
                        }

                        if (dr[k]["dept_code"].ToString() == "2")
                        {
                            strmsg = "[{\"key\":\"FD_L2\",\"value\":\"" + dr[k]["Level_L2"].ToString() + "\"},{\"key\":\"FD_L3\",\"value\":\"" + dr[k]["Level_L3"].ToString() + "\"},{\"key\":\"FD_L4\",\"value\":\"" + dr[k]["Level_L4"].ToString() + "\"}]";
                            dataRow["FD"] = strmsg;
                        }
                        if (dr[k]["dept_code"].ToString() == "3")
                        {
                            strmsg = "[{\"key\":\"FM_L2\",\"value\":\"" + dr[k]["Level_L2"].ToString() + "\"},{\"key\":\"FM_L3\",\"value\":\"" + dr[k]["Level_L3"].ToString() + "\"},{\"key\":\"FM_L4\",\"value\":\"" + dr[k]["Level_L4"].ToString() + "\"}]";
                            dataRow["FM"] = strmsg;
                        }
                        if (dr[k]["dept_code"].ToString() == "4")
                        {
                            strmsg = "[{\"key\":\"FP_L2\",\"value\":\"" + dr[k]["Level_L2"].ToString() + "\"},{\"key\":\"FP_L3\",\"value\":\"" + dr[k]["Level_L3"].ToString() + "\"},{\"key\":\"FP_L4\",\"value\":\"" + dr[k]["Level_L4"].ToString() + "\"}]";
                            dataRow["FP"] = strmsg;
                        }
                        if (dr[k]["dept_code"].ToString() == "5")
                        {
                            strmsg = "[{\"key\":\"FT_L2\",\"value\":\"" + dr[k]["Level_L2"].ToString() + "\"},{\"key\":\"FT_L3\",\"value\":\"" + dr[k]["Level_L3"].ToString() + "\"},{\"key\":\"FT_L4\",\"value\":\"" + dr[k]["Level_L4"].ToString() + "\"}]";
                            dataRow["FT"] = strmsg;
                        }



                    }
                    dt.Rows.Add(dataRow);
                }
            }

            if (dt != null)
            {
                return jsondata = GetJson1(dt);
            }
        }

        if (preference_data != null)
        {
            jsondata = GetJson1(preference_data);
        }
        return jsondata;
    }

