    [WebMethod(EnableSession = true)]
    public string save_thesis_drp_data(string thesis_drp_dataa)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string User_id;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "user id not found");
            }
            else
            {
                User_id = HttpContext.Current.Session["UserId"].ToString();
            }

            Dictionary<string, object> thesis_drp_data = ser.Deserialize<Dictionary<string, object>>(thesis_drp_dataa);

            DSC_Course_Master obj_Thesis_drp = new DSC_Course_Master();

            DataTable dt_current_thesis_sem = objmaster.get_current_thesis_drp_semester();


            DSC_Course_Master.student_thesis_drp_dtlRow student_Thesis_Drp_DtlRow = obj_Thesis_drp.student_thesis_drp_dtl.Newstudent_thesis_drp_dtlRow();

            thesis_drp_data["user_id"] = User_id;

            student_Thesis_Drp_DtlRow.user_id = User_id;
            student_Thesis_Drp_DtlRow.instructor_code = thesis_drp_data["instructor_code"].ToString();

            student_Thesis_Drp_DtlRow.course_code = thesis_drp_data["course_code"].ToString();
            student_Thesis_Drp_DtlRow.form_type = thesis_drp_data["type"].ToString();
            student_Thesis_Drp_DtlRow.topic = thesis_drp_data["topic"].ToString();
            student_Thesis_Drp_DtlRow.thesis_abstract = thesis_drp_data["abstract"].ToString();
            student_Thesis_Drp_DtlRow.thesis_references = thesis_drp_data["references"].ToString();
            student_Thesis_Drp_DtlRow.is_submit = thesis_drp_data["is_submit"].ToString();
            student_Thesis_Drp_DtlRow.status = "N";
            if (student_Thesis_Drp_DtlRow.form_type == "25")
            {
                student_Thesis_Drp_DtlRow.semester_type = dt_current_thesis_sem.Rows[0]["sem_code"].ToString();
                student_Thesis_Drp_DtlRow.year_semester = dt_current_thesis_sem.Rows[0]["year_code"].ToString();
                student_Thesis_Drp_DtlRow.student_code = User_id;
            }
            else if (student_Thesis_Drp_DtlRow.form_type == "29")
            {
                student_Thesis_Drp_DtlRow.semester_type = thesis_drp_data["sem_code"].ToString();
                student_Thesis_Drp_DtlRow.year_semester = thesis_drp_data["year_code"].ToString();
                student_Thesis_Drp_DtlRow.student_code = thesis_drp_data["student_code"].ToString();
            }
            student_Thesis_Drp_DtlRow.cancel_flag = "N";
            student_Thesis_Drp_DtlRow.created_by = HttpContext.Current.Session["UserId"].ToString();
            student_Thesis_Drp_DtlRow.created_date = DateTime.Now;
            student_Thesis_Drp_DtlRow.created_host = HttpContext.Current.Request.UserHostName;

            obj_Thesis_drp.student_thesis_drp_dtl.Addstudent_thesis_drp_dtlRow(student_Thesis_Drp_DtlRow);


            objBLReturnObject = objMaster.save_student_thesis_drp_dtl(obj_Thesis_drp, "2000", HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName, thesis_drp_data);

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                return return_ajax_string("0", "Data Saved Successfully");
            }
            else
            {
                return return_ajax_string("1", "Problem in Save data or Sending Mail");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string save_course_wise_drp_data(string thesis_drp_dataa)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string User_id;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "user id not found");
            }
            else
            {
                User_id = HttpContext.Current.Session["UserId"].ToString();
            }

            Dictionary<string, object> thesis_drp_data = ser.Deserialize<Dictionary<string, object>>(thesis_drp_dataa);

            DSC_Course_Master obj_Thesis_drp = new DSC_Course_Master();

            DataTable dt_current_thesis_sem = objmaster.get_current_thesis_drp_semester();


            DSC_Course_Master.course_wise_drp_dtlRow course_wise_drp_dtlRow = obj_Thesis_drp.course_wise_drp_dtl.Newcourse_wise_drp_dtlRow();
