            {
                if (v == 0)
                {
                    dept_code += "'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                    prog_code += "'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                }
                else
                {
                    dept_code += ",'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                    prog_code += ",'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                }
            }
        }

        DataTable course_data = objmaster.Get_student_for_drp(dept_code, prog_code);

        if (course_data != null)
        {
            jsondata = GetJson1(course_data);
        }
        return jsondata;
    }

