    [WebMethod(EnableSession = true)]
    public string save_all_drp_value(string student_drp_Data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            string doc_numbers = "";
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(student_drp_Data);


            DataTable student_course_drp = objmaster.get_student_wise_drp_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString(), data[0]["drp_code"].ToString());

            if (student_course_drp != null)
            {
                //New logic
                for (int p = 0; p < data.Count; p++)
                {
                    DataRow[] dataRows = student_course_drp.Select("user_id = '" + data[p]["user_id"].ToString() + "'");
                    if (dataRows.Length > 0)
                    {
                        if (doc_numbers == "")
                        {
                            doc_numbers = "'" + dataRows[0]["doc_no"].ToString() + "'";
                        }
                        else { doc_numbers += ",'" + dataRows[0]["doc_no"].ToString() + "'"; }


                    }
                }

                //old logic
                //for (int k = 0; k < student_course_drp.Rows.Count; k++)
                //{
                //    if (k == 0)
                //    {
                //        doc_numbers = "'" + student_course_drp.Rows[k]["doc_no"].ToString() + "'";
                //    }
                //    else
                //    {
                //        doc_numbers += ",'" + student_course_drp.Rows[k]["doc_no"].ToString() + "'";
                //    }
                //}
            }

            DSC_DRP dSC_DRP = new DSC_DRP();

            for (int i = 0; i < data.Count; i++)
            {
                DataTable dt_next_doc_no = objmaster.GetNextDocNobyDocType("STUDENTDRP");


                if (data[i]["seats"].ToString() != "")
                {

                    int next_doc_no = Convert.ToInt32(dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString()) + 1;
                    bool update_no = objmaster.UpdateNextDocNo(next_doc_no, "STUDENTDRP");
                    //dt_next_doc_no = objmaster.GetNextDocNobyDocType("STUDENTDRP");

                    DSC_DRP.student_wise_drp_dtlRow student_Wise_Drp_DtlRow = dSC_DRP.student_wise_drp_dtl.Newstudent_wise_drp_dtlRow();
                    student_Wise_Drp_DtlRow.doc_no = next_doc_no.ToString();
                    student_Wise_Drp_DtlRow.user_id = data[i]["user_id"].ToString();
                    student_Wise_Drp_DtlRow.course_code = data[i]["course_code"].ToString();
                    student_Wise_Drp_DtlRow.drp_code = data[i]["drp_code"].ToString();
                    student_Wise_Drp_DtlRow.seat_type = data[i]["seats"].ToString();
                    student_Wise_Drp_DtlRow.cancel_flag = "N";
                    student_Wise_Drp_DtlRow.created_by = user_id;
                    student_Wise_Drp_DtlRow.created_date = DateTime.Now;
                    student_Wise_Drp_DtlRow.created_host = HttpContext.Current.Request.UserHostName;

                    student_Wise_Drp_DtlRow.semester_type = data[i]["semester_type"].ToString();
                    student_Wise_Drp_DtlRow.year_semester = data[i]["year_semester"].ToString();
                    dSC_DRP.student_wise_drp_dtl.Addstudent_wise_drp_dtlRow(student_Wise_Drp_DtlRow);
                }
            }

            objBLReturnObject = objMaster.save_drp_dtl(dSC_DRP, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                if (student_course_drp != null)
                {
                    Boolean status = objmaster.update_drp_student(doc_numbers, user_id, HttpContext.Current.Request.UserHostName);
                }

            }
            else if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

