    [WebMethod(EnableSession = true)]
    public string update_drp_value(string faculty_drp_Data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            string doc_numbers = "";
            DataTable dt = new DataTable();
            JavaScriptSerializer ser = new JavaScriptSerializer();
            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(faculty_drp_Data);
            DSC_Course_Master dSC_DRP = new DSC_Course_Master();
            DataTable get_drp_dtl = objmaster.get_course_wise_drp_dtl("", data[0]["semester"].ToString(), data[0]["year"].ToString(), "");
            for (int i = 0; i < data.Count; i++)
            {
                DataRow[] dr = get_drp_dtl.Select("doc_no ='" + data[i]["doc_no"].ToString() + "'");

                if (dr.Length > 0)
                {
                    if (data[i]["inst_code"].ToString() != "")
                    {
                        dr[0]["instructor_code"] = data[i]["inst_code"].ToString();
                    }
                    if (data[i]["doc"].ToString() != "")
                    {
                        dr[0]["doc_path"] = data[i]["doc"].ToString();
                    }

                    dr[0]["last_modified_by"] = user_id;
                    dr[0]["last_modified_date"] = DateTime.Now;
                    dr[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                    dSC_DRP.course_wise_drp_dtl.ImportRow(dr[0]);

                }
            }

            objBLReturnObject = objMaster.update_drp_dtl(dSC_DRP, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

