    [WebMethod(EnableSession = true)]
    public string course_wise_midterm_exam_dtl(string sem_code, string year_code, string dept_code, string prog_code, string exam_type)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        DataTable course_exam_data = objmaster.course_wise_entered_marks_list_AD(sem_code, year_code, dept_code, prog_code, user_type);

        DataTable course_exam_midterm_data = objmaster.course_wise_midterm_exam_dtl(sem_code, year_code, dept_code, prog_code, user_type, exam_type);

        DataTable dt_submit_eligibility = objmaster.exam_submit_eligibility_dtl(sem_code, year_code);

        if (course_exam_midterm_data != null)
        {
            course_exam_midterm_data.Columns.Add("course_name");
            course_exam_midterm_data.Columns.Add("total_exams");
            course_exam_midterm_data.Columns.Add("total_students");
            course_exam_midterm_data.Columns.Add("faculty_approval");
            course_exam_midterm_data.Columns.Add("progcoordinate_approval");
            course_exam_midterm_data.Columns.Add("ugpg_approval");
            course_exam_midterm_data.Columns.Add("dean_approval");

            course_exam_midterm_data.Columns.Add("exam_1_eligible");
            course_exam_midterm_data.Columns.Add("exam_2_eligible");
            course_exam_midterm_data.Columns.Add("exam_3_eligible");
            course_exam_midterm_data.Columns.Add("exam_4_eligible");
            course_exam_midterm_data.Columns.Add("exam_5_eligible");
            course_exam_midterm_data.Columns.Add("exam_6_eligible");
            course_exam_midterm_data.Columns.Add("exam_7_eligible");
            course_exam_midterm_data.Columns.Add("exam_8_eligible");
            course_exam_midterm_data.Columns.Add("exam_9_eligible");
            course_exam_midterm_data.Columns.Add("exam_10_eligible");


            if (course_exam_data != null)
            {
                for (int i = 0; i < course_exam_midterm_data.Rows.Count; i++)
                {
                    DataRow[] dr = course_exam_data.Select("course_code='" + course_exam_midterm_data.Rows[i]["course_code"] + "'");

                    if (dr.Length > 0)
                    {
                        course_exam_midterm_data.Rows[i]["course_name"] = dr[0]["course_name"];
                        course_exam_midterm_data.Rows[i]["total_exams"] = dr[0]["total_exams"];
                        course_exam_midterm_data.Rows[i]["total_students"] = dr[0]["total_students"];
                        course_exam_midterm_data.Rows[i]["faculty_approval"] = dr[0]["faculty_approval"];
                        course_exam_midterm_data.Rows[i]["progcoordinate_approval"] = dr[0]["progcoordinate_approval"];
                        course_exam_midterm_data.Rows[i]["ugpg_approval"] = dr[0]["ugpg_approval"];
                        course_exam_midterm_data.Rows[i]["dean_approval"] = dr[0]["dean_approval"];
                    }

                    for (int j = 1; j <= 10; j++)
                    {
                        DataRow[] dr_exam = dt_submit_eligibility.Select("course_code='" + course_exam_midterm_data.Rows[i]["course_code"] + "' and exam_" + j + "_eligible='N'");

                        if (dr_exam.Length > 0)
                            course_exam_midterm_data.Rows[i]["exam_" + j + "_eligible"] = "N";
                        else
                            course_exam_midterm_data.Rows[i]["exam_" + j + "_eligible"] = "Y";
                    }
                }
            }

            jsondata = GetJson1(course_exam_midterm_data);
        }
        return jsondata;
    }
