    [WebMethod(EnableSession = true)]
    public string submit_exam_marks_all(string req_obj)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> dict_req_obj = ser.Deserialize<Dictionary<string, object>>(req_obj);

            string semester = dict_req_obj["sem_code"].ToString();
            string year = dict_req_obj["year_code"].ToString();
            ArrayList arr_exam_data = (ArrayList)dict_req_obj["exam_dtl"];

            DataTable course_exam_data = objmaster.course_wise_exam_list("", semester, year);

            DSC_GradingMaster exam_master_add = new DSC_GradingMaster();

            for (int i = 0; i < arr_exam_data.Count; i++)
            {
                Dictionary<string, object> dict_exam_data = (Dictionary<string, object>)arr_exam_data[i];

                DataRow[] dr = course_exam_data.Select("course_code='" + dict_exam_data["course_code"].ToString() + "' and exam_code='" + dict_exam_data["exam_code"].ToString() + "'");

                if (dr.Length > 0)
                {
                    dr[0]["is_submit"] = "Y";
                    dr[0]["last_modified_by"] = user_id;
                    dr[0]["last_modified_date"] = DateTime.Now;
                    dr[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                    exam_master_add.exam_master.ImportRow(dr[0]);
                }
            }

            objBLReturnObject = objMaster.course_wise_exam_add(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                objBLReturnObject.ServerMessage = "Exams Submitted Successfully";
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string publish_all_course_grade(string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        try
        {
            if (user_type == "A1")
            {
                DataTable course_avail_data = objmaster.chk_publish_all_course_avlblty_in_student_marks(user_id, user_type, sem_code, year_code);
                //DataTable course_avail_data = null;

                if (course_avail_data != null)
                {
                    if (course_avail_data.Rows.Count > 0)
                    {
                        return "Please Enter all course grade to Publish Course Grade";
                    }
                }
                else if (course_avail_data == null)
                {
                    DataTable course_exam_data = objmaster.course_wise_entered_marks_list(user_id, user_type, sem_code, year_code, user_prog_code, "", "");

                    DataRow[] dr_faculty_not_approved = course_exam_data.Select("faculty_approval not in ('Approved')");
                    DataRow[] dr_prog_not_approved = course_exam_data.Select("progcoordinate_approval not in ('Approved')");

                    if (dr_faculty_not_approved.Length > 0)
                    {
                        //return "Please Submit all course grade to Publish Course Grade";
                        return "Faculty Approval is pending , You can not Publish Course Grade";
                    }
                    else if (dr_prog_not_approved.Length > 0)
                    {
                        return "Program Coordinator Approval is pending , You can not Publish Course Grade";
                    }
                    else
                    {
                        DataTable course_stud_marks_data = objmaster.chk_publish_all_student_marks(user_id, user_type, sem_code, year_code);

                        DataRow[] dr_null_exams = course_stud_marks_data.Select("total_exams is null");

                        if (dr_null_exams.Length > 0)
                        {
                            return "Exams not Found for Courses , You can not Publish Course Grade";
                        }
                        else
                        {
                            bool flag = true;
                            int i;
                            for (i = 0; i < course_stud_marks_data.Rows.Count; i++)
                            {
                                if (course_stud_marks_data.Rows[i]["total_exams"] == System.DBNull.Value) { flag = false; break; }
                                else
                                {
                                    for (int j = 1; j <= Convert.ToInt32(course_stud_marks_data.Rows[i]["total_exams"].ToString()); j++)
                                    {
                                        if (course_stud_marks_data.Rows[i]["exam_" + j] == System.DBNull.Value)
                                        {
                                            if (course_stud_marks_data.Rows[i]["absent_exam_" + j] == System.DBNull.Value || course_stud_marks_data.Rows[i]["absent_exam_" + j] == null || course_stud_marks_data.Rows[i]["absent_exam_" + j] == "")
                                            {
                                                flag = false; break;
                                            }
                                        }
                                    }
                                    if (!flag) break;
                                }
                                //if (course_stud_marks_data.Rows[i]["attendance"] == System.DBNull.Value) { flag = false; break; }
                            }

                            if (!flag)
                            {
                                //return "Student Marks/Attendance not Found for Courses , You can not Publish Course Grade";
                                return "Student Marks not Found for Courses , You can not Publish Course Grade";
                            }
                            else
                            {
                                return objmaster.publish_all_student_marks(sem_code, year_code);
                            }
                        }
                    }
                }
            }
            else
            {
                return "You are not Authorized to Publish Course";
            }
        }
        catch (Exception e)
        {
            return e.Message.ToString();
        }
        return "You can not Publish Course Grade";
    }

    [WebMethod(EnableSession = true)]
    public string publish_selected_course_grade(string publish_data, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        //bool save_grade = true;

        try
        {
            //17092021
            if (user_type == "AD" || user_type == "A1")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                List<string> lst_publish_data = ser.Deserialize<List<string>>(publish_data);

                DataTable course_exam_data = objmaster.course_wise_entered_marks_list(user_id, user_type, sem_code, year_code, user_prog_code, "", "");

                if (lst_publish_data.Count > 0 && course_exam_data != null)
                {
                    string str_publish_course_list = "";

                    for (int i = 0; i < lst_publish_data.Count; i++)
                    {
                        DataRow[] dr_course_data = course_exam_data.Select("course_code='" + lst_publish_data[i] + "'");

                        if (dr_course_data.Length > 0)
                        {
                            if (dr_course_data[0]["faculty_approval"].ToString() == "Approved" && dr_course_data[0]["progcoordinate_approval"].ToString() == "Approved")
                            {
                                if (i != 0)
                                    str_publish_course_list += ",";

                                str_publish_course_list += "'" + lst_publish_data[i].ToString() + "'";

                                //bool save_grade_data = save_student_wise_grade(lst_publish_data[i].ToString(), sem_code, year_code);
                                //if (!save_grade_data)
                                //{
                                //    save_grade = false;
                                //}
                            }
                        }
                    }

                    Dictionary<string, string> dic_response = objmaster.publish_selected_student_marks(str_publish_course_list, sem_code, year_code, user_id);
                    return return_ajax_string(dic_response["status"], dic_response["message"]);

                    //if (dic_response["status"] == "True" && save_grade)
                    //{
                    //    return return_ajax_string(dic_response["status"], dic_response["message"]);
                    //}
                    //else if (dic_response["status"] == "True" && !save_grade)
                    //{
                    //    return return_ajax_string(dic_response["status"], "All Courses are Published Successfully. But Grade not commited into database.");
                    //}
                    //else
                    //{
                    //    return return_ajax_string(dic_response["status"], dic_response["message"]);
                    //}
                }
                else
                {
                    return return_ajax_string("False", "No Data Found to Publish Course");
                }
            }
            else
            {
                return return_ajax_string("False", "You are not Authorized to Publish Course");
            }
        }
        catch (Exception e)
        {
            return return_ajax_string("False", e.Message.ToString());
        }
        return return_ajax_string("False", "You can not Publish Course Grade");
    }


