                                if (i != 0)
                                    str_publish_course_list += ",";

                                str_publish_course_list += "'" + lst_publish_data[i].ToString() + "'";

                                //bool save_grade_data = save_student_wise_grade(lst_publish_data[i].ToString(), sem_code, year_code);
                                //if (!save_grade_data)
                                //{
                                //    save_grade = false;
                                //}
                            }
                        }
                    }

                    Dictionary<string, string> dic_response = objmaster.publish_midterm_selected_student_marks(str_publish_course_list, sem_code, year_code, user_id);
                    return return_ajax_string(dic_response["status"], dic_response["message"]);

                    //if (dic_response["status"] == "True" && save_grade)
                    //{
                    //    return return_ajax_string(dic_response["status"], dic_response["message"]);
                    //}
                    //else if (dic_response["status"] == "True" && !save_grade)
                    //{
                    //    return return_ajax_string(dic_response["status"], "All Courses are Published Successfully. But Grade not commited into database.");
                    //}
                    //else
                    //{
                    //    return return_ajax_string(dic_response["status"], dic_response["message"]);
                    //}
                }
                else
                {
                    return return_ajax_string("False", "No Data Found to Publish Course");
                }
            }
            else
            {
                return return_ajax_string("False", "You are not Authorized to Publish Course");
            }
        }
        catch (Exception e)
        {
            return return_ajax_string("False", e.Message.ToString());
        }
        return return_ajax_string("False", "You can not Publish Course Grade");
    }


