                exam_master_row.final_mark = (student_course_grade.Select("student_code='" + data[i]["student_code"].ToString() + "'"))[0]["final_mark"].ToString();
                exam_master_row.final_grade = (student_course_grade.Select("student_code='" + data[i]["student_code"].ToString() + "'"))[0]["final_grade"].ToString();
                exam_master_row.final_grade_point = (student_course_grade.Select("student_code='" + data[i]["student_code"].ToString() + "'"))[0]["final_grade_point"].ToString();

                //Added 25 09 2019 : To save grade into database. = Start

                exam_master_add.student_exam_marks_dtl.Addstudent_exam_marks_dtlRow(exam_master_row);
            }

            bool cancel_marks = objmaster.CancelCourseWiseMarks(data[0]["course_code"].ToString(), data[0]["sem_code"].ToString(), data[0]["year_code"].ToString(), user_id);

            if (cancel_marks)
            {
                objBLReturnObject = objMaster.save_student_marks(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

