    [WebMethod(EnableSession = true)]
    public string submit_course_grade(string course_code, string sem_code, string year_code, string page)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable data = objmaster.grade_submit_detail_list(course_code, sem_code, year_code);

        DSC_GradingMaster grade_master = new DSC_GradingMaster();

        if (data != null)
        {
            try
            {
                if (data.Rows.Count > 0)
                {
                    bool prog_approved = true;

                    for (int i = 0; i < data.Rows.Count; i++)
                    {

                        DSC_GradingMaster.grade_submit_detailRow grade_submit_row = grade_master.grade_submit_detail.Newgrade_submit_detailRow();

                        grade_submit_row.doc_no = data.Rows[i]["doc_no"].ToString();
                        grade_submit_row.course_code = data.Rows[i]["course_code"].ToString();

                        grade_submit_row.faculty_approved = data.Rows[i]["faculty_approved"].ToString();
                        grade_submit_row.progcoordinate_approved = data.Rows[i]["progcoordinate_approved"].ToString();

                        if (page == "EDIT")
                        {
                            if (data.Rows[i]["faculty_approved"].ToString() == "N")
                            {
                                if (user_type == "I2" || user_type == "PC" || user_type == "D")
                                {
                                    grade_submit_row.faculty_approved = "Y";
                                    //Write Here logics
                                    //bool save_grade_data = save_student_wise_grade(data.Rows[i]["course_code"].ToString(), data.Rows[i]["semester_type"].ToString(), data.Rows[i]["year_semester"].ToString());

                                    //if (!save_grade_data)
                                    //{
                                    //    return "Problem in saving Final Marks and Grade";
                                    //}
                                }
                                if (user_type == "FA" || user_type == "AD")
                                {
                                    grade_submit_row.faculty_approved = "Y";
                                    grade_submit_row.progcoordinate_approved = "Y";
                                }
                            }
                            else
                            {
                                if (user_type == "FA" || user_type == "AD")
                                {
                                    if (data.Rows[i]["progcoordinate_approved"].ToString() == "N")
                                    {
                                        grade_submit_row.progcoordinate_approved = "Y";
                                    }
                                    else
                                    {
                                        return "You have already submitted the course";
                                    }
                                }
                                else
                                {
                                    return "You have already submitted the course";
                                }
                            }
                        }

                        if (page == "VIEW")
                        {
                            if (data.Rows[i]["faculty_approved"].ToString() == "Y")
                            {
                                if (data.Rows[i]["progcoordinate_approved"].ToString() == "N")
                                {
                                    if (user_type == "PC") grade_submit_row.progcoordinate_approved = "Y";
                                }
                                else
                                {
                                    return "You have already submitted the course";
                                }
                            }
                            else
                            {
                                return "Course not Submitted by faculty, You can Submit course after Faculty Submit the course";
                            }
                        }

                        grade_submit_row.ugpgoffice_approved = data.Rows[i]["ugpgoffice_approved"].ToString();
                        grade_submit_row.dean_approved = data.Rows[i]["dean_approved"].ToString();

                        grade_submit_row.cancel_flag = "N";
                        grade_submit_row.created_by = data.Rows[i]["created_by"].ToString();
                        if (data.Rows[i]["created_date"].ToString() != "" && data.Rows[i]["created_date"].ToString() != null)
                        { grade_submit_row.created_date = Convert.ToDateTime(data.Rows[i]["created_date"]); }
                        grade_submit_row.last_modified_by = user_id;
                        grade_submit_row.last_modified_date = DateTime.Now;
                        grade_submit_row.semester_type = data.Rows[i]["semester_type"].ToString();
                        grade_submit_row.year_semester = data.Rows[i]["year_semester"].ToString();


                        grade_master.grade_submit_detail.Addgrade_submit_detailRow(grade_submit_row);

                    }

                    //bool cancel_grade = objmaster.CancelCourseGradeSubmitDetails(course_code, sem_code, year_code, user_id);

                    //if (cancel_grade)
                    //{
                    objBLReturnObject = objMaster.save_submit_course_grade(grade_master, "2000", HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    //}

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                }
            }
            catch (Exception ex)
            {
                return "Problem in update DATA.";
            }
        }
        else
        {
            try
            {
                if (user_type == "I2" || user_type == "PC" || user_type == "D" || user_type == "FA" || user_type == "AD")
                {
                    DSC_GradingMaster.grade_submit_detailRow grade_submit_row = grade_master.grade_submit_detail.Newgrade_submit_detailRow();

                    grade_submit_row.doc_no = "";
