    [WebMethod(EnableSession = true)]
    public string commit_selected_course_grade(string commit_data, string sem_code, string year_code)
    {
        bool save_grade_data = true;

        JavaScriptSerializer ser = new JavaScriptSerializer();
        String final_response_success = "<b><center><h4><u>Grade Commited Successfully</u></h4></center></b><br>";
        Boolean unsuccess_attemp = true;
        Boolean success_attemp = true;

        String final_response_unsuccess = "<br><b><center><h4><u>Unsuccess Committed Grade Courses</u></h4></center></b><br>";

        List<string> lst_commit_data = ser.Deserialize<List<string>>(commit_data);

        if (lst_commit_data.Count > 0)
        {
            ServerLog.CommitGradeLog("Semester : " + sem_code + " " + year_code);

            for (int i = 0; i < lst_commit_data.Count; i++)
            {
                ServerLog.CommitGradeLog("1. Start Commiting : " + lst_commit_data[i].ToString());

                save_grade_data = save_student_wise_grade(lst_commit_data[i].ToString(), sem_code, year_code, "Y");

                if (!save_grade_data)
                {
                    ServerLog.CommitGradeLog("3. Unsuccess : " + lst_commit_data[i].ToString());
                    unsuccess_attemp = false;
                    final_response_unsuccess += " " + lst_commit_data[i].ToString() + ",";
                }
                else
                {
                    ServerLog.CommitGradeLog("2. Success : " + lst_commit_data[i].ToString());
                    success_attemp = false;
                    final_response_success += " " + lst_commit_data[i].ToString() + ",";
                }
            }
        }

        final_response_success = final_response_success.Remove(final_response_success.Length - 1);

        final_response_unsuccess = final_response_unsuccess.Remove(final_response_unsuccess.Length - 1);

        if (!unsuccess_attemp && success_attemp)
        {
            return final_response_unsuccess;
        }
        else if (!success_attemp && unsuccess_attemp)
        {
            return final_response_success;
        }
        else
        {
            final_response_success = final_response_success + "<br>";

            return final_response_success + final_response_unsuccess;
        }

        //if (save_grade_data)
        //{
        //    return "Grade Commited Successfully.";
        //}
        //else
        //{
        //    return "Course Grade not Committed into the Portal.";
        //}
    }

    [WebMethod(EnableSession = true)]
    public string verify_student_grade(string student_code, string sem_code, string year_code)
    {
        var user_id = student_code;
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            DataTable dt_course_detail = objmaster.get_Course_Detail_Verify(user_id, sem_code, year_code);

            DataTable dt_ws_course_detail = objmaster.get_WS_Course_Detail(user_id, sem_code, year_code);

            if (dt_course_detail != null || dt_ws_course_detail != null)
            {
                DataTable dt_stud_detail = objmaster.get_Student_Detail(user_id, sem_code, year_code);

                DataTable dt_grade_range = objmaster.get_Grade_Range(user_id, sem_code, year_code);

                DataTable dt_ws_grade_range = objmaster.get_WS_Grade_Range(user_id, sem_code, year_code);

                DataTable dt_course_grade_detail = objmaster.Calculate_grade(dt_stud_detail, dt_course_detail, dt_grade_range);

                DataTable dt_ws_course_grade_detail = objmaster.WS_Calculate_grade(dt_stud_detail, dt_ws_course_detail, dt_ws_grade_range);

                DataTable dt_foundation_detail = objmaster.get_student_foundation_status(user_id, sem_code, year_code);

                DataTable dt_credit_detail = objmaster.Calculate_credits(dt_course_grade_detail, dt_ws_course_grade_detail);

                ArrayList a = new ArrayList();
                if (dt_stud_detail != null)
                {
                    a.Add(GetJson1(dt_stud_detail));
                }
                else
                {
                    a.Add("null");
                }

                if (dt_course_grade_detail != null)
                {
                    a.Add(GetJson1(dt_course_grade_detail));
                }
                else
                {
                    a.Add("null");
                }

                if (dt_ws_course_detail != null)
                {
                    a.Add(GetJson1(dt_ws_course_detail));
                }
                else
                {
                    a.Add("null");
                }

                if (dt_credit_detail != null)
                {
                    a.Add(GetJson1(dt_credit_detail));
                }
                else
                {
                    a.Add("null");
                }

                a.Add("null");

                if (dt_foundation_detail != null)
                {
                    a.Add(GetJson1(dt_foundation_detail));
                }
                else
                {
                    a.Add("null");
                }

                if (dt_course_grade_detail != null || dt_ws_course_detail != null)
                {
                    jsondata = "{\"stud_detail\":" + a[0] + ",\"course_grade_detail\":" + a[1] + ",\"ws_course_grade_detail\":" + a[2] + ",\"credit_detail\":" + a[3] + ",\"mid_term_marks\":" + a[4] + ",\"foundation_dtl\":" + a[5] + "}";
                    return "{\"status\":\"true\",\"message\":" + jsondata + "}";
                }
                else
                {
                    return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
                }
            }
            else
            {
                return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
            }
        }
        catch (Exception ex)
        {
        }
        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string submit_exam_marks(string course_code, string sem_code, string year_code, string exam_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();

        DataTable course_exam_data = objmaster.course_wise_exam_list(course_code, sem_code, year_code);

        if (course_exam_data != null)
        {
            DataRow[] dr = course_exam_data.Select("exam_code='" + exam_code + "'");

            if (dr.Length > 0)
            {
                jsondata = objmaster.submit_exam_marks(user_id, course_code, sem_code, year_code, exam_code);

                if (dr[0].ItemArray[5].ToString() == "MT")
                {
                    DataTable course_exam_data_MT = objmaster.course_wise_exam_list_MT(course_code, sem_code, year_code, exam_code);

                    if (course_exam_data_MT == null)
                    {
                        string midterm_submit = midterm_submit_course_grade(course_code, sem_code, year_code, "EDIT");

                        if (midterm_submit == "Data Saved Successfully")
                        {
                            jsondata = "Exam Submitted Successfully";
                        }
                    }
                }
            }
            else
            {
                jsondata = "Exam not Found";
            }
        }
        else
        {
            jsondata = "No Exams Found";
        }

        return jsondata;
    }

