    [WebMethod(EnableSession = true)]
    public string course_wise_student_marks_list(string course_code, string sem_code, string year_code)
    {
        DataTable student_marks_data = objmaster.course_wise_student_marks_list(course_code, sem_code, year_code);

        if (student_marks_data == null)
        {
            student_marks_data = objmaster.course_wise_student_marks_list(course_code, sem_code, year_code);

            if (student_marks_data == null)
            {
                DataTable student_wise_course_dtl = objmaster.get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

                if (student_wise_course_dtl != null)
                {
                    try
                    {
                        var user_id = HttpContext.Current.Session["UserId"].ToString();
                        var user_type = HttpContext.Current.Session["user_type"].ToString();

                        DSC_GradingMaster exam_master_add = new DSC_GradingMaster();

                        for (int i = 0; i < student_wise_course_dtl.Rows.Count; i++)
