                            exam_master_row.doc_no = (i + 1).ToString();
                            exam_master_row.student_code = student_wise_course_dtl.Rows[i]["user_id"].ToString();
                            exam_master_row.course_code = course_code;
                            exam_master_row.cancel_flag = "N";
