                            exam_master_row.created_date = DateTime.Now;
                            exam_master_row.semester_type = sem_code;
                            exam_master_row.year_semester = year_code;


                            exam_master_add.student_exam_marks_dtl.Addstudent_exam_marks_dtlRow(exam_master_row);
                        }

                        bool cancel_marks = objmaster.CancelCourseWiseMarks(course_code, sem_code, year_code, user_id);

                        if (cancel_marks)
                        {
                            objBLReturnObject = objMaster.save_students_for_marks_entry(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);
                        }

                        if (objBLReturnObject.ExecutionStatus == 2)
                        {
                            objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        }

                        if (objBLReturnObject.ExecutionStatus == 1)
                        {
                            student_marks_data = objmaster.course_wise_student_marks_list(course_code, sem_code, year_code);
                        }
                    }
                    catch (Exception ex)
                    {
                        //return ex.ToString();
                    }
                }
            }
        }

        if (student_marks_data != null)
        {
            DataTable student_wise_course_dtl = objmaster.get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

            if (student_wise_course_dtl != null)
            {
                //if (student_wise_course_dtl.Rows.Count > student_marks_data.Rows.Count)
                //{
                try
                {
                    var user_id = HttpContext.Current.Session["UserId"].ToString();
                    var user_type = HttpContext.Current.Session["user_type"].ToString();

                    DSC_GradingMaster exam_master_add = new DSC_GradingMaster();

                    for (int i = 0; i < student_wise_course_dtl.Rows.Count; i++)
                    {
                        DataRow[] dr = student_marks_data.Select("student_code='" + student_wise_course_dtl.Rows[i]["user_id"] + "'");

                        if (dr.Length == 0)
                        {
                            DSC_GradingMaster.student_exam_marks_dtlRow exam_master_row = exam_master_add.student_exam_marks_dtl.Newstudent_exam_marks_dtlRow();

                            exam_master_row.doc_no = (i + 1).ToString();
                            exam_master_row.student_code = student_wise_course_dtl.Rows[i]["user_id"].ToString();
                            exam_master_row.course_code = course_code;
                            exam_master_row.cancel_flag = "N";
                            exam_master_row.created_by = user_id;
                            exam_master_row.created_date = DateTime.Now;
                            exam_master_row.semester_type = sem_code;
                            exam_master_row.year_semester = year_code;

                            exam_master_add.student_exam_marks_dtl.Addstudent_exam_marks_dtlRow(exam_master_row);
                        }
                    }

                    if (exam_master_add.student_exam_marks_dtl.Count > 0)
                    {
                        //bool cancel_marks = objmaster.CancelCourseWiseMarks(course_code, sem_code, year_code, user_id);

                        //if (cancel_marks)
                        //{
                        objBLReturnObject = objMaster.save_students_for_marks_entry(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);
                        //}

                        if (objBLReturnObject.ExecutionStatus == 2)
                        {
                            objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        }

                        if (objBLReturnObject.ExecutionStatus == 1)
                        {
                            student_marks_data = objmaster.course_wise_student_marks_list(course_code, sem_code, year_code);
                        }
                    }
                }
                catch (Exception ex)
                {
                    //return ex.ToString();
                }
                //}
            }
        }

        string temp = save_calculated_weighted_marks(course_code, sem_code, year_code);

        if (student_marks_data != null)
        {
            DataTable dt_instructor_sub_group_students = objmaster.get_instructor_sub_group_students(HttpContext.Current.Session["UserId"].ToString(), course_code, sem_code, year_code);

            if (dt_instructor_sub_group_students != null)
            {
                for (int i = 0; i < student_marks_data.Rows.Count; i++)
                {
                    DataRow[] dr_instructor_sub_group_students = dt_instructor_sub_group_students.Select("user_id='" + student_marks_data.Rows[i]["student_code"].ToString() + "'");

                    if (dr_instructor_sub_group_students.Length == 0)
                    {
                        student_marks_data.Rows.RemoveAt(i--);
                    }
                }
            }

            DataView view = student_marks_data.DefaultView;
            view.Sort = "student_code ASC";
            DataTable sortedDate = view.ToTable();

            jsondata = GetJson1(sortedDate);
        }
        return jsondata;
    }
