    [WebMethod(EnableSession = true)]
    public string get_course_wise_avg_sd_range(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string course_typology)
    {
        DataTable dt_filter_data_ini = objmaster.FilterCourseResults(null, dept_code, prog_code, prog_level_code, sem_code, year_code, course_typology, "FIRST");

        if (dt_filter_data_ini == null)
        {
            ArrayList all = new ArrayList();
            all.Add("null");
            all.Add("null");
            jsondata = "{\"course_grade_detail\":" + all[0] + ",\"absolute_grade_range\":" + all[1] + "}";
            //return "{\"status\":\"true\",\"message\":" + jsondata + "}";
            return return_ajax_data("True", jsondata);
        }

        //////////////////////// SD Call Demo ///////////////////////
        /**/
        /**/
        //double mean = 0;
        /**/
        //double variance = 0;
        /**/
        //double sd = 0;
        /**/
        ////double[] temp_arr = { 9, 2, 5, 4, 12, 7, 8, 11, 9, 3, 7, 4, 12, 5, 4, 10, 9, 6, 9, 4 };
        /**/
        ////double[] temp_arr = { 90, 2, 50, 54, 12, 77, 68, 11, 93, 39, 70, 45, 72, 65, 54, 10, 59, 86, 79, 64 };  // with fail marks & >90
        /**/
        ////double[] temp_arr = { 90, 92, 51, 54, 52, 77, 68, 61, 93, 69, 70, 55, 72, 65, 54, 80, 59, 86, 79, 64 };  // with >90
        /**/
        //double[] temp_arr = { 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71, 71 };
        /**/
        //calculate_mean_sd(temp_arr, out mean, out variance, out sd);
        /**/
        //DataTable dt_grade_range = calculate_marks_range_for_grade(mean, sd);
        /**/
        /////////////////////////////////////////////////////////////

        //save_course_wise_avg_sd_range(sem_code,year_code);

        int absolute_grading_stud_limit = 20;

        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        DataTable course_exam_data = objmaster.get_course_wise_avg_sd_range(sem_code, year_code);

        DataTable dt_course_with_no_grade = objmaster.get_course_list_with_no_avg_sd_range(sem_code, year_code);

        //DataTable dt_course_allocate_data_for_grade = objmaster.get_course_allocate_data_for_grade(sem_code, year_code);

        //DataTable dt_student_marks_data_for_grade = objmaster.get_student_marks_data_for_grade(sem_code, year_code);

        if (dt_course_with_no_grade != null && course_exam_data != null)
        {
            for (int i = 0; i < dt_course_with_no_grade.Rows.Count; i++)
            {
                DataRow dr = course_exam_data.NewRow();

                dr["course_code"] = dt_course_with_no_grade.Rows[i]["course_code"].ToString();
                dr["A_plus_from"] = "90";
                dr["A_plus_to"] = "100";
                dr["A_to"] = "89";
                dr["D_plus_from"] = "50";
                dr["F_from"] = "0";
                dr["F_to"] = "49";

                course_exam_data.Rows.Add(dr);
            }
        }

        DataTable dt_prog_wise_courses = objmaster.Get_course_for_student_wise_grade(sem_code, year_code, user_prog_code);

        DataTable dt_Grade_Range = objmaster.get_Grade_Range("", sem_code, year_code);

        DataTable dt_Cancel_Grade_Range = objmaster.get_Cancel_Grade_Range("", sem_code, year_code);

        DataTable dt_old_grade_range = get_Old_Grade_Range();

        if (dt_prog_wise_courses != null && course_exam_data != null)
        {
            var temp = (from tbl1 in course_exam_data.AsEnumerable()
                        join tbl2 in dt_prog_wise_courses.AsEnumerable() on tbl1["course_code"].ToString() equals tbl2["course_code"].ToString()
                        select tbl1).CopyToDataTable();

            course_exam_data = temp;

            course_exam_data.Columns.Add("D_from");
            course_exam_data.Columns.Add("D_to");
            course_exam_data.Columns.Add("D_minus_from");
            course_exam_data.Columns.Add("D_minus_to");
            course_exam_data.Columns.Add("grade_type");
            course_exam_data.Columns.Add("grade_submitted");
            course_exam_data.Columns.Add("grade_submitted_date_time");
            course_exam_data.Columns.Add("previous_grade_submitted_date_time");

            if (dt_Grade_Range != null)
            {
                //var temp_res = (from tbl1 in course_exam_data.AsEnumerable()
                //                join tbl2 in dt_Grade_Range.AsEnumerable() on tbl1.Field<string>("course_code").ToString() equals tbl2.Field<string>("course_code").ToString()
                //                into tbl3
                //                from res in tbl3.DefaultIfEmpty()
                //                select tbl1["grade_type"] = tbl3.FirstOrDefault()["grade_type"]
                //                ).ToArray();

                for (int i = 0; i < course_exam_data.Rows.Count; i++)
                {
                    DataRow[] dr_grade_range = dt_Grade_Range.Select("course_code='" + course_exam_data.Rows[i]["course_code"].ToString() + "'");

                    if (dr_grade_range.Length > 0)
                    {
                        if (dr_grade_range[0]["grade_type"].ToString() != "")
                        {
                            course_exam_data.Rows[i]["grade_type"] = dr_grade_range[0]["grade_type"].ToString();
                            course_exam_data.Rows[i]["grade_submitted"] = "Y";
                            if (dr_grade_range[0]["last_modified_date"].ToString() == "")
                            {
                                course_exam_data.Rows[i]["grade_submitted_date_time"] = dr_grade_range[0]["created_date"].ToString();
                            }
                            else
                            {
                                course_exam_data.Rows[i]["grade_submitted_date_time"] = dr_grade_range[0]["last_modified_date"].ToString();
                            }
                        }
                        else
                        {
                            course_exam_data.Rows[i]["grade_submitted"] = "N";
                            course_exam_data.Rows[i]["grade_submitted_date_time"] = "";
                        }
                    }
                    else
                    {
                        course_exam_data.Rows[i]["grade_submitted"] = "N";
                        course_exam_data.Rows[i]["grade_submitted_date_time"] = "";
                    }

                    if (dt_Cancel_Grade_Range != null)
                    {
                        DataRow[] dr_cancel_grade_range = dt_Cancel_Grade_Range.Select("course_code='" + course_exam_data.Rows[i]["course_code"].ToString() + "'");

                        if (dr_cancel_grade_range.Length > 0)
                        {
                            if (course_exam_data.Rows[i]["grade_submitted_date_time"].ToString() != "")
                            {
                                course_exam_data.Rows[i]["grade_submitted_date_time"] = "<span class='cls_hover' style='color: deepskyblue;'>" + course_exam_data.Rows[i]["grade_submitted_date_time"].ToString() + "</span>";
                                string str = "<div style='display:none;'>";

                                for (int d = 0; d < dr_cancel_grade_range.Length; d++)
                                {
                                    str += "<span style='color:chocolate;'>" + dr_cancel_grade_range[d]["created_date"].ToString() + "</span><br/>";
                                }
                                course_exam_data.Rows[i]["grade_submitted_date_time"] = course_exam_data.Rows[i]["grade_submitted_date_time"] + str + "</div>";
                            }
                        }
                        else
                        {

                        }
                    }
                }
            }

            for (int i = 0; i < course_exam_data.Rows.Count; i++)
            {
                if (course_exam_data.Rows[i]["Total_Students"].ToString() != "")
                {
                    if (Convert.ToInt32(course_exam_data.Rows[i]["Total_Students"].ToString()) <= absolute_grading_stud_limit)
                    {
                        course_exam_data.Rows[i]["A_plus_from"] = dt_old_grade_range.Rows[0]["A_plus_from"];
                        course_exam_data.Rows[i]["A_plus_to"] = dt_old_grade_range.Rows[0]["A_plus_to"];
                        course_exam_data.Rows[i]["A_from"] = dt_old_grade_range.Rows[0]["A_from"];
                        course_exam_data.Rows[i]["A_to"] = dt_old_grade_range.Rows[0]["A_to"];
                        course_exam_data.Rows[i]["A_minus_from"] = dt_old_grade_range.Rows[0]["A_minus_from"];
                        course_exam_data.Rows[i]["A_minus_to"] = dt_old_grade_range.Rows[0]["A_minus_to"];
                        course_exam_data.Rows[i]["B_plus_from"] = dt_old_grade_range.Rows[0]["B_plus_from"];
                        course_exam_data.Rows[i]["B_plus_to"] = dt_old_grade_range.Rows[0]["B_plus_to"];
                        course_exam_data.Rows[i]["B_from"] = dt_old_grade_range.Rows[0]["B_from"];
                        course_exam_data.Rows[i]["B_to"] = dt_old_grade_range.Rows[0]["B_to"];
                        course_exam_data.Rows[i]["B_minus_from"] = dt_old_grade_range.Rows[0]["B_minus_from"];
                        course_exam_data.Rows[i]["B_minus_to"] = dt_old_grade_range.Rows[0]["B_minus_to"];
                        course_exam_data.Rows[i]["C_plus_from"] = dt_old_grade_range.Rows[0]["C_plus_from"];
                        course_exam_data.Rows[i]["C_plus_to"] = dt_old_grade_range.Rows[0]["C_plus_to"];
                        course_exam_data.Rows[i]["C_from"] = dt_old_grade_range.Rows[0]["C_from"];
                        course_exam_data.Rows[i]["C_to"] = dt_old_grade_range.Rows[0]["C_to"];
                        course_exam_data.Rows[i]["C_minus_from"] = dt_old_grade_range.Rows[0]["C_minus_from"];
                        course_exam_data.Rows[i]["C_minus_to"] = dt_old_grade_range.Rows[0]["C_minus_to"];
                        course_exam_data.Rows[i]["D_plus_from"] = dt_old_grade_range.Rows[0]["D_plus_from"];
                        course_exam_data.Rows[i]["D_plus_to"] = dt_old_grade_range.Rows[0]["D_plus_to"];
                        course_exam_data.Rows[i]["D_from"] = dt_old_grade_range.Rows[0]["D_from"];
                        course_exam_data.Rows[i]["D_to"] = dt_old_grade_range.Rows[0]["D_to"];
                        course_exam_data.Rows[i]["D_minus_from"] = dt_old_grade_range.Rows[0]["D_minus_from"];
                        course_exam_data.Rows[i]["D_minus_to"] = dt_old_grade_range.Rows[0]["D_minus_to"];
                    }
                }
            }
        }
        else
        {
            course_exam_data = null;
        }

        //Filter Starts
        if (dept_code != "" || prog_code != "" || prog_level_code != "" || course_typology != "")
        {
            if (course_exam_data != null)
            {
                DataTable dt_filter_data = objmaster.FilterCourseResults(course_exam_data, dept_code, prog_code, prog_level_code, sem_code, year_code, course_typology, "SECOND");

                if (dt_filter_data != null)
                {
                    for (int c = 0; c < course_exam_data.Rows.Count; c++)
                    {
                        bool course_avail = false;

                        for (int u = 0; u < dt_filter_data.Rows.Count; u++)
                        {
