                    for (int mprCnt = 0; mprCnt < exam_master_add.course_wise_grade_range.Rows.Count; mprCnt++)
                    {
                        bool aval = false;

                        for (int z = 0; z < segments.Length; z++)
                        {
                            if (exam_master_add.course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() == segments[z])
                            {
                                aval = true;
                            }
                        }

                        if (!aval)
                        {
                            DataRow[] rows;
                            rows = exam_master_add.course_wise_grade_range.Select("course_code = '" + exam_master_add.course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() + "'");
                            foreach (DataRow row in rows)
                                exam_master_add.course_wise_grade_range.Rows.Remove(row);

                            mprCnt = mprCnt - 1;
                        }
                    }

                    if (ALL_Course)
                        cancel_ranged = objmaster.CancelCourseWiseGradeRange(sem_code, year_code, "ALL", user_id, exam_master_add);
                    else
                        cancel_ranged = objmaster.CancelCourseWiseGradeRange(sem_code, year_code, courses_selected, user_id, exam_master_add);

                    if (cancel_ranged)
                    {
                        objBLReturnObject = objMaster.save_course_wise_avg_sd_range(exam_master_add, "2000", "", HttpContext.Current.Request.UserHostName);
                    }
                    else
                    {
                        objBLReturnObject.ExecutionStatus = 2;
                        objBLReturnObject.ServerMessage = "Error While Cancelling Course Wise Grade Range.";
                        return objBLReturnObject.ServerMessage;
                    }

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                }
                else
                {
                    objBLReturnObject.ExecutionStatus = 2;
                    objBLReturnObject.ServerMessage = "Course Grade Range not updated.";
                    return objBLReturnObject.ServerMessage;
                }
            }
            catch (Exception ex)
            {
                return "Problem in update DATA.";
            }
        }
        else
        {
            objBLReturnObject.ExecutionStatus = 2;
            objBLReturnObject.ServerMessage = "Course Grade Range not updated.";
            return objBLReturnObject.ServerMessage;
        }
        return objBLReturnObject.ServerMessage;
    }

