    #region Student_Section

    [WebMethod(EnableSession = true)]
    public string get_student_maksheet(string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable dt_blocklist_marksheet_student = objmaster.student_block_marksheet_for_student(sem_code, year_code, user_id);

        if (dt_blocklist_marksheet_student != null && dt_blocklist_marksheet_student.Rows.Count > 0)
        {
            return "{\"status\":\"false\",\"message\":\" Please note that your grades will be visible within 12 hours after feedback submission.\"}";
        }


        try
        {
            DataTable dt_grade_submit_dtl = objmaster.grade_submit_detail_all_course(sem_code, year_code);

            if (dt_grade_submit_dtl != null)
            {
                if (dt_grade_submit_dtl.Rows.Count > 0)
                {
                    DataRow[] dr_grade_submit_dtl = dt_grade_submit_dtl.Select("ugpgoffice_approved = 'N'");

                    if (dr_grade_submit_dtl.Length > 0)
                    {
                        //return "Grade not published yet";
                        //return "{\"status\":\"false\",\"message\":\"Grade not published yet\"}";
                    }
                }
            }

            //DataTable dt_blocklist = objmaster.student_marksheet_blocklist(sem_code, year_code, user_id);

            //    if (dt_blocklist != null && dt_blocklist.Rows.Count > 0)
            //    {
            //        if (dt_blocklist.Select("block_type='project'").Length > 0)
            //        {
            //            return "{\"status\":\"false\",\"message\":\"Please publish your mandatory project on <a target=\\\"_blank\\\" href=\\\"https://portfolio.cept.ac.in/login\\\">https://portfolio.cept.ac.in/login</a>\"}";
            //        }
            //        else
            //        {
            //            return "{\"status\":\"false\",\"message\":\"Please contact your concern person for grade report.\"}";
            //        }
            //    }

            DataTable dt_blocklist_marksheet = objmaster.student_marksheet_blocklist_fees_not_paid(sem_code, year_code, user_id);

            if (dt_blocklist_marksheet != null && dt_blocklist_marksheet.Rows.Count > 0)
            {
                return "{\"status\":\"false\",\"message\":\" Hold the result due to non payment of balance fees/pending feedback of the semester.\"}";
            }

            bool flag = false;

            DataTable get_feedback_disable_data = objmaster.get_feedback_disable_course_data(sem_code, year_code, "");

            string disable_course = MakeInQueryString(get_feedback_disable_data, "course_code");

            DataSet get_all_student_feedback_data = objmaster.Get_student_wise_feedback_data(sem_code, year_code, "", "", disable_course);

            DataTable dt_typology_data = objmaster.Get_typology_data();

            if (get_all_student_feedback_data != null)
            {
                decimal lecture = 0, seminar = 0, studio = 0, workshop = 0, others = 0;

                if (get_all_student_feedback_data.Tables[1].Rows.Count > 0)
                {
                    lecture = seminar = studio = workshop = others = 0;

                    DataRow[] dr_feedback_total = get_all_student_feedback_data.Tables[1].Select("user_id ='" + user_id + "'");

                    if (dr_feedback_total.Length > 0)
                    {
                        if (get_all_student_feedback_data.Tables[0].Rows.Count > 0)
                        {
                            DataRow[] dr = get_all_student_feedback_data.Tables[0].Select(" user_id = '" + user_id + "' ");

                            if (dr.Length > 0)
                            {
                                for (int j = 0; j < dr.Length; j++)
                                {
                                    //if (dr[j]["course_typology"].ToString() == "3" || dr[j]["course_typology"].ToString() == "4" || dr[j]["course_typology"].ToString() == "8" || dr[j]["course_typology"].ToString() == "12" || dr[j]["course_typology"].ToString() == "18")
                                    //{
                                    //    lecture += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "5" || dr[j]["course_typology"].ToString() == "6" || dr[j]["course_typology"].ToString() == "13" || dr[j]["course_typology"].ToString() == "19")
                                    //{
                                    //    seminar += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "1" || dr[j]["course_typology"].ToString() == "9" || dr[j]["course_typology"].ToString() == "22")
                                    //{
                                    //    workshop += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "7" || dr[j]["course_typology"].ToString() == "14" || dr[j]["course_typology"].ToString() == "20")
                                    //{
                                    //    studio += 1;
                                    //}
                                    //else
                                    //{
                                    //    others += 1;
                                    //}

                                    DataRow[] dr_typology_data = dt_typology_data.Select("type_code='" + dr[j]["course_typology"].ToString() + "'");

                                    if (dr_typology_data.Length > 0)
                                    {
                                        switch (dr_typology_data[0]["sub_group"].ToString())
                                        {
                                            case "SG001":
                                                lecture += 1;
                                                break;
                                            case "SG002":
                                                seminar += 1;
                                                break;
                                            case "SG003":
                                                studio += 1;
                                                break;
                                            case "SG004":
                                                workshop += 1;
                                                break;
                                            default:
                                                others += 1;
                                                break;
                                        }
                                    }
                                }
                            }
                        }

                        if (dr_feedback_total[0]["total_feedback"].ToString() != "" && dr_feedback_total[0]["total_feedback"] != DBNull.Value)
                        {
                            if (Convert.ToInt32(dr_feedback_total[0]["total_feedback"]) == (lecture + seminar + studio + workshop))
                            {
                                flag = true;
                            }
                        }
                        else
                        {
                            //  get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"] = 0;
                            if (lecture + seminar + studio + workshop == 0)
                            {
                                flag = true;
                            }
                        }
                    }
                }
            }

            //if (HttpContext.Current.Session["year_code"].ToString() == "Y2012" )
            //{
            if ((sem_code == "S" && year_code == "2013") || (sem_code == "M" && year_code == "2013"))
            {
                flag = true;
            }
            // }

            DataTable dt_course_detail = objmaster.get_Course_Detail(user_id, sem_code, year_code);
            DataTable dt_ws_course_detail = objmaster.get_WS_Course_Detail(user_id, sem_code, year_code);
            if (dt_course_detail != null || dt_ws_course_detail != null)
            {
                flag = true;// This line is added to skip the feedback submit check. Remove this line to active feedback submit check.

                if (flag)
                {
                    DataTable dt_stud_detail = objmaster.get_Student_Detail(user_id, sem_code, year_code);
                    //DataTable dt_course_detail = objmaster.get_Course_Detail(user_id, sem_code, year_code);
                    DataTable dt_grade_range = objmaster.get_Grade_Range(user_id, sem_code, year_code);
                    //DataTable dt_ws_course_detail = objmaster.get_WS_Course_Detail(user_id, sem_code, year_code);
                    DataTable dt_ws_grade_range = objmaster.get_WS_Grade_Range(user_id, sem_code, year_code);

                    DataTable dt_course_grade_detail = objmaster.Calculate_grade(dt_stud_detail, dt_course_detail, dt_grade_range);

                    DataTable dt_ws_course_grade_detail = objmaster.WS_Calculate_grade(dt_stud_detail, dt_ws_course_detail, dt_ws_grade_range);

                    if (current_feedback_sem == sem_code && current_feedback_year == year_code)
                    {
                        string student_type = "";
                        bool feedback_check = false;
                        bool sws_feedback_check = false;

                        bool feedback_check_CFP = false;
                        bool feedback_check_Regular = false;

                        DataTable dt_feedback_data = objmaster.get_parameter_value("Feedback_dashboard");
                        if (dt_feedback_data.Rows[0]["parameter_value"].ToString() == "E") feedback_check = true;

                        DataTable dt_sws_feedback_data = objmaster.get_parameter_value("sws_feedback");
                        if (dt_sws_feedback_data.Rows[0]["parameter_value"].ToString() == "E") sws_feedback_check = true;

                        DataTable dt_cfp_status = objmaster.get_student_foundation_active_status(user_id);

                        if (dt_cfp_status == null)
                        {
                            DataTable dt_feedback_data_Regular = objmaster.get_parameter_value("Feedback Check of Regular students for Results");

                            if (dt_feedback_data_Regular.Rows[0]["parameter_value"].ToString() == "E")
                                feedback_check_Regular = true;
                            else
                                feedback_check_Regular = false;

                            if (feedback_check && feedback_check_Regular)
                                feedback_check = true;
                            else
                                feedback_check = false;

                            if (sws_feedback_check && feedback_check_Regular)
                                sws_feedback_check = true;
                            else
                                sws_feedback_check = false;
                        }
                        else
                        {
