                    }

                    //DataTable dt_credit_detail = objmaster.Calculate_credits(dt_course_grade_detail, dt_ws_course_grade_detail);

                    DataTable dt_foundation_detail = objmaster.get_student_foundation_status(user_id, sem_code, year_code);

                    //DataTable dt_mid_term_marks = objmaster.get_mid_term_student_marks(sem_code, year_code, user_id);

                    //High priority: Studio Results - Viewing condition. 13 11 2019
                    DataTable dt_mid_term_marks = objmaster.get_mid_term_student_marks(sem_code, year_code, user_id, true);

                    if (dt_mid_term_marks != null)
                    {
                        DataRow[] mid_rows;
                        mid_rows = dt_mid_term_marks.Select("sub_group_id='SG003'");

                        if (mid_rows.Length > 0)
                        {
                            foreach (DataRow row in mid_rows)
                            {
                                bool studioCheckPortfolio = false;//newly added

                                float MT_IN = float.Parse(row["mt_obtained_marks"].ToString()) + float.Parse(row["in_obtained_marks"].ToString());

                                if (MT_IN >= WebService.MT_IN_PASS_MARKS_BCT && row["prog_level_code"].ToString() == "UT") //newly added
                                {
                                    studioCheckPortfolio = true;//newly added
                                }
                                else if (MT_IN >= MT_IN_PASS_MARKS)
                                {
                                    studioCheckPortfolio = true;//newly added
                                }

                                if (studioCheckPortfolio) //newly added
                                {
                                    DataTable dt_blocklist_course_wise = objmaster.student_marksheet_blocklist_course_wise(sem_code, year_code, user_id, row["course_code"].ToString());

                                    if (dt_blocklist_course_wise != null && dt_blocklist_course_wise.Rows.Count > 0)
                                    {
                                        DataRow[] newrows;
                                        newrows = dt_course_grade_detail.Select("course_code = '" + row["course_code"].ToString() + "'");
                                        foreach (DataRow nrow in newrows)
                                            dt_course_grade_detail.Rows.Remove(nrow);
                                    }
                                }
                            }
                        } 
                    }
                    //High priority: Studio Results - Viewing condition. 13 11 2019

                    DataTable dt_credit_detail = objmaster.Calculate_credits(dt_course_grade_detail, dt_ws_course_grade_detail);

                    ArrayList a = new ArrayList();
                    if (dt_stud_detail != null)
                    {
                        a.Add(GetJson1(dt_stud_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }

                    if (dt_course_grade_detail != null)
                    {
                        a.Add(GetJson1(dt_course_grade_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }

                    if (dt_ws_course_detail != null)
                    {
                        a.Add(GetJson1(dt_ws_course_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }

                    if (dt_credit_detail != null)
                    {
                        a.Add(GetJson1(dt_credit_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }

                    //if (dt_mid_term_marks != null)
                    //{
                    //    a.Add(GetJson1(dt_mid_term_marks));
                    //}
                    //else
                    //{
                    a.Add("null");
                    //}

                    if (dt_foundation_detail != null)
                    {
                        a.Add(GetJson1(dt_foundation_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }

                    if (dt_course_grade_detail != null || dt_ws_course_detail != null)
                    {
                        jsondata = "{\"stud_detail\":" + a[0] + ",\"course_grade_detail\":" + a[1] + ",\"ws_course_grade_detail\":" + a[2] + ",\"credit_detail\":" + a[3] + ",\"mid_term_marks\":" + a[4] + ",\"foundation_dtl\":" + a[5] + "}";
                        //jsondata = GetJson1(dt_course_grade_detail);
                        return "{\"status\":\"true\",\"message\":" + jsondata + "}";
                    }
                    else
                    {
                        //return "No Marksheet found for selected Semester and Year";
                        return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
                    }

                }
                else
                {
                    //return "You have not completed the feedback, please fill the feedback to view your grades.";
                    //return "{\"status\":\"false\",\"message\":\"You have not completed the feedback, please fill the feedback to view your grades\"}";
                    return "{\"status\":\"falsee\",\"message\":\"Please submit the feedback to view the grade report\"}";
                }
            }
            else
            {
                return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
            }
        }
        catch (Exception ex)
        {
        }
        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string get_student_marksheet_blocklist()
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        string sem_code = "";
        string year_code = "";

        string prev_ws_sem = "";
        string prev_ws_year = "";

        sem_code = current_ws_sem;
        year_code = current_ws_year;

        string prev_sem_code = "", prev_year_code = "";

        if (sem_code == "M")
        {
            prev_sem_code = "S";
            prev_year_code = year_code;

            prev_ws_sem = "S";
            prev_ws_year = year_code;
        }
        else if (sem_code == "S")
        {
            prev_ws_sem = "W";
            prev_sem_code = "M";

            prev_year_code = (Int32.Parse(year_code) - 1).ToString();
            prev_ws_year = prev_year_code;
        }

        string semester_name = "";

        if (current_ws_sem == "S")
        {
            semester_name = "Spring " + current_ws_year;
        }
        else if (current_ws_sem == "M")
        {
            semester_name = "Monsoon " + current_ws_year;
        }
        bool checked_portfolio_status = false;

        DataTable dt_portfolio = objmaster.get_student_portfolio_course_dtl(prev_sem_code, prev_year_code, user_id);
        DataTable dt_GetStudentGradeBlock = null; 
        if (dt_portfolio != null)
        {
            dt_GetStudentGradeBlock = objmaster.GetStudentGradeBlock(sem_code, year_code, user_id, dt_portfolio.Rows[0]["course_code"].ToString());
        }
        if (dt_portfolio != null)
        {
            //DONE -- Myr 17072021
            DataTable dt_course_detail = objmaster.get_Course_Detail_cr_PORTFOLIO(user_id, prev_sem_code, prev_year_code, dt_portfolio.Rows[0]["course_code"].ToString());

            if (dt_course_detail == null) 
            {
                if (dt_GetStudentGradeBlock == null)
                {
                    return "{\"status\":\"false\",\"message\":\"Grade is not published yet. Try again later.\"}";
                }
                
            }

            DataTable dt_stud_detail = objmaster.get_Student_Detail(user_id, prev_sem_code, prev_year_code);

            DataTable dt_grade_range = objmaster.get_Grade_Range_CC(user_id, prev_sem_code, prev_year_code, dt_portfolio.Rows[0]["course_code"].ToString());

            if (dt_grade_range == null)
            {
                if (dt_GetStudentGradeBlock == null) 
                {
                    return "{\"status\":\"false\",\"message\":\"Grade Range is not submitted yet. Try again later.\"}";
                }
                
            }

            DataTable dt_course_grade_detail = objmaster.Calculate_grade(dt_stud_detail, dt_course_detail, dt_grade_range);

            if (dt_course_grade_detail != null)
            {
                if (dt_course_grade_detail.Select("course_code='" + dt_portfolio.Rows[0]["course_code"].ToString() + "'").Length > 0)
                {
                    if (dt_course_grade_detail.Rows[0]["remarks"].ToString() == "FAIL")
                    {
                        //do nothing
                    }
                    else if (dt_course_grade_detail.Rows[0]["remarks"].ToString() == "PASS")
                    {
                        checked_portfolio_status = true;
                    }
                    else
                    {
                        return "{\"status\":\"false\",\"message\":\"Problem while checking Portfolio Uploaded Status.\"}";
                    }
                }
                else
                {
                    return "{\"status\":\"false\",\"message\":\"Problem while calculating Grade.\"}";
                }
            }
            else
            {
                if (dt_GetStudentGradeBlock == null) 
                {
                    return "{\"status\":\"false\",\"message\":\"Problem while calculating Grade.\"}";
                }
                    
            }
        }

        if (checked_portfolio_status)
        {
            DataTable dt_portfolio_status = objmaster.get_student_portfolio_uploaded_status(prev_sem_code, prev_year_code, dt_portfolio.Rows[0]["course_code"].ToString(), user_id);

            if (dt_portfolio_status == null)
            {
                return "{\"status\":\"false\",\"message\":\"Please publish your mandatory project on <a target=\\\"_blank\\\" href=\\\"https://portfolio.cept.ac.in/login\\\">https://portfolio.cept.ac.in/login</a>\"}";
            }
        }

        DataTable dt_blocklist = objmaster.student_marksheet_blocklist(prev_sem_code, prev_year_code, user_id);

        if (dt_blocklist != null && dt_blocklist.Rows.Count > 0)
        {
            //if (dt_blocklist.Select("block_type='project'").Length > 0)
            //{
            //    return "{\"status\":\"false\",\"message\":\"Please publish your mandatory project on <a target=\\\"_blank\\\" href=\\\"https://portfolio.cept.ac.in/login\\\">https://portfolio.cept.ac.in/login</a>\"}";
            //}
            //else 
            if (dt_blocklist.Select("block_type='project'").Length > 0)
            {
                //return "{\"status\":\"false\",\"message\":\"Please publish your mandatory project on <a target=\\\"_blank\\\" href=\\\"https://portfolio.cept.ac.in/login\\\">https://portfolio.cept.ac.in/login</a>\"}";
                return "{\"status\":\"true\",\"message\":\"Portfolio Uploaded and Feedback Disabled.\"}";
            }
            else if (dt_blocklist.Select("block_type='blockregistration'").Length > 0)
            {
                return "{\"status\":\"false\",\"message\":\"Your registration process has been blocked for " + semester_name + " Semester.\"}";
            }
            else if (dt_blocklist.Select("block_type='feedbackdisable'").Length == 0)
            {
                return "{\"status\":\"false\",\"message\":\"Please contact your concern person for Midterm Marks.\"}";
            }
            else if (dt_blocklist.Select("block_type='feedbackdisable'").Length > 0)
            {
                return "{\"status\":\"true\",\"message\":\"Portfolio Uploaded and Feedback Disabled.\"}";
            }
        }

        //28 06 2020  Checking Feedback for Previous Semester before Registration

        DataTable dt_cfp_status = objmaster.get_student_foundation_active_status(user_id);

        bool feedback_check = false;

        if (dt_cfp_status == null)
        {
            DataTable dt_feedback_data_Regular = objmaster.get_parameter_value("Feedback Check of Reg students for Registration");

            if (dt_feedback_data_Regular.Rows[0]["parameter_value"].ToString() == "E")
                feedback_check = true;
            else
                feedback_check = false;
        }
        else
        {
            DataTable dt_feedback_data_CFP = objmaster.get_parameter_value("Feedback Check of CFP students for Registration");

            if (dt_feedback_data_CFP.Rows[0]["parameter_value"].ToString() == "E")
                feedback_check = true;
            else
                feedback_check = false;
        }

        if (feedback_check)
        {
            DataTable course_lists = objmaster.get_course_lists_to_check_previous_semester_feedback(prev_sem_code, prev_year_code, user_id);

            if (course_lists != null)
            {
                DataSet dt_feedback_logic = objmaster.Check_feedback_before_registration(user_id, prev_sem_code, prev_year_code, course_lists);

                for (int i = 0; i < dt_feedback_logic.Tables.Count; i++)
                {
                    if (dt_feedback_logic.Tables[i].Rows[0]["Feedback_Avaiable"].ToString() == "N")
                    {
                        return "{\"status\":\"false\",\"message\":\"Feedback not submitted for previous semester. Please fill the feedback.\"}";
                    }
                }
            }

            DataTable sws_course_lists = objmaster.get_course_lists_to_check_previous_semester_feedback_sws(prev_ws_sem, prev_ws_year, user_id);

            DataTable prev_sem_data = objmaster.get_parameter_value("SWS_feedback_course_for_registration");

            if (sws_course_lists != null && prev_sem_data.Rows[0]["parameter_value"].ToString() == "E")
            {
                DataSet dt_feedback_logic_sws = objmaster.Check_feedback_before_registration_sws(user_id, prev_ws_sem, prev_ws_year, sws_course_lists);

                for (int i = 0; i < dt_feedback_logic_sws.Tables.Count; i++)
                {
                    if (dt_feedback_logic_sws.Tables[i].Rows[0]["Feedback_Avaiable"].ToString() == "N")
                    {
                        return "{\"status\":\"false\",\"message\":\"SWS Feedback not submitted for previous semester. Please fill the feedback.\"}";
                    }
                }
            }
        }

        //28 06 2020  Checking Feedback for Previous Semester before Registration

        return "{\"status\":\"true\",\"message\":\"Portfolio Uploaded and Feedback Submitted.\"}";
    }

    [WebMethod(EnableSession = true)]
    public string get_student_midterm_marks(string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            DataTable dt_grade_submit_dtl = objmaster.grade_submit_detail_all_course(sem_code, year_code);

            if (dt_grade_submit_dtl != null)
            {
                if (dt_grade_submit_dtl.Rows.Count > 0)
                {
                    DataRow[] dr_grade_submit_dtl = dt_grade_submit_dtl.Select("ugpgoffice_approved = 'N'");

                    if (dr_grade_submit_dtl.Length > 0)
                    {
                        //return "Grade not published yet";
                        //return "{\"status\":\"false\",\"message\":\"Grade not published yet\"}";
                    }
                }
            }

            DataTable dt_blocklist = objmaster.student_marksheet_blocklist(sem_code, year_code, user_id);

            if (dt_blocklist != null && dt_blocklist.Rows.Count > 0)
            {
                if (dt_blocklist.Select("block_type='project'").Length > 0)
                {
                    return "{\"status\":\"false\",\"message\":\"Please publish your mandatory project on <a target=\\\"_blank\\\" href=\\\"https://portfolio.cept.ac.in/login\\\">https://portfolio.cept.ac.in/login</a>\"}";
                }
                else
                {
                    return "{\"status\":\"false\",\"message\":\"Please contact your concern person for Midterm Marks.\"}";
                }
            }

            bool flag = false;

            DataTable get_feedback_disable_data = objmaster.get_feedback_disable_course_data(sem_code, year_code, "");

            string disable_course = MakeInQueryString(get_feedback_disable_data, "course_code");

            DataSet get_all_student_feedback_data = objmaster.Get_student_wise_feedback_data(sem_code, year_code, "", "", disable_course);

            DataTable dt_typology_data = objmaster.Get_typology_data();

            if (get_all_student_feedback_data != null)
            {
                decimal lecture = 0, seminar = 0, studio = 0, workshop = 0, others = 0;

                if (get_all_student_feedback_data.Tables[1].Rows.Count > 0)
                {
                    lecture = seminar = studio = workshop = others = 0;

                    DataRow[] dr_feedback_total = get_all_student_feedback_data.Tables[1].Select("user_id ='" + user_id + "'");

                    if (dr_feedback_total.Length > 0)
                    {
                        if (get_all_student_feedback_data.Tables[0].Rows.Count > 0)
                        {
                            DataRow[] dr = get_all_student_feedback_data.Tables[0].Select(" user_id = '" + user_id + "' ");

                            if (dr.Length > 0)
                            {
                                for (int j = 0; j < dr.Length; j++)
                                {
                                    //if (dr[j]["course_typology"].ToString() == "3" || dr[j]["course_typology"].ToString() == "4" || dr[j]["course_typology"].ToString() == "8" || dr[j]["course_typology"].ToString() == "12" || dr[j]["course_typology"].ToString() == "18")
                                    //{
                                    //    lecture += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "5" || dr[j]["course_typology"].ToString() == "6" || dr[j]["course_typology"].ToString() == "13" || dr[j]["course_typology"].ToString() == "19")
                                    //{
                                    //    seminar += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "1" || dr[j]["course_typology"].ToString() == "9" || dr[j]["course_typology"].ToString() == "22")
                                    //{
                                    //    workshop += 1;
                                    //}
                                    //else if (dr[j]["course_typology"].ToString() == "7" || dr[j]["course_typology"].ToString() == "14" || dr[j]["course_typology"].ToString() == "20")
                                    //{
                                    //    studio += 1;
                                    //}
                                    //else
                                    //{
                                    //    others += 1;
                                    //}

                                    DataRow[] dr_typology_data = dt_typology_data.Select("type_code='" + dr[j]["course_typology"].ToString() + "'");

                                    if (dr_typology_data.Length > 0)
                                    {
                                        switch (dr_typology_data[0]["sub_group"].ToString())
                                        {
                                            case "SG001":
                                                lecture += 1;
                                                break;
                                            case "SG002":
                                                seminar += 1;
                                                break;
                                            case "SG003":
                                                studio += 1;
                                                break;
                                            case "SG004":
                                                workshop += 1;
                                                break;
                                            default:
                                                others += 1;
                                                break;
                                        }
                                    }
                                }
                            }
                        }

                        if (dr_feedback_total[0]["total_feedback"].ToString() != "" && dr_feedback_total[0]["total_feedback"] != DBNull.Value)
                        {
                            if (Convert.ToInt32(dr_feedback_total[0]["total_feedback"]) == (lecture + seminar + studio + workshop))
                            {
                                flag = true;
                            }
                        }
                        else
                        {
                            //  get_all_student_feedback_data.Tables[1].Rows[i]["total_feedback"] = 0;
                            if (lecture + seminar + studio + workshop == 0)
                            {
                                flag = true;
                            }
                        }
                    }
                }
            }

            DataTable dt_stud_detail = objmaster.get_Student_Detail(user_id, sem_code, year_code);

            DataTable dt_mid_term_marks = objmaster.get_mid_term_student_marks(sem_code, year_code, user_id, flag);

            ArrayList a = new ArrayList();
            if (dt_stud_detail != null)
            {
                a.Add(GetJson1(dt_stud_detail));
            }
            else
            {
                a.Add("null");
            }

            a.Add("null");

            a.Add("null");

            a.Add("null");

            if (dt_mid_term_marks != null)
            {
                a.Add(GetJson1(dt_mid_term_marks));
            }
            else
            {
                a.Add("null");
            }

            if (dt_mid_term_marks != null)
            {
                jsondata = "{\"stud_detail\":" + a[0] + ",\"course_grade_detail\":" + a[1] + ",\"ws_course_grade_detail\":" + a[2] + ",\"credit_detail\":" + a[3] + ",\"mid_term_marks\":" + a[4] + "}";
                //jsondata = GetJson1(dt_course_grade_detail);
                return "{\"status\":\"true\",\"message\":" + jsondata + "}";
            }
            else
            {
                //return "No Marksheet found for selected Semester and Year";
                return "{\"status\":\"false\",\"message\":\"No Midterm Marks found for selected Semester and Year\"}";
            }
        }
        catch (Exception ex)
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();
            return "{\"status\":\"false\",\"message\":" + ser.Serialize(ex.ToString()) + "}";
        }
        return jsondata;
    }


