    [WebMethod(EnableSession = true)]
    public string get_course_wise_result(string sem_code, string year_code, string prog_level_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable course_wise_result_data = objmaster.get_course_wise_result(sem_code, year_code, prog_level_code);
        string course_code = "";

        int absolute_grading_stud_limit = 20;
        //string temp = save_calculated_weighted_marks(course_code, sem_code, year_code);//While doing cancel flag Y logic made this comment due to same new entry created 
        DataTable course_grade_range = objmaster.get_course_wise_avg_sd_range(sem_code, year_code);
        DataTable dt_old_grade_range = get_Old_Grade_Range();
        DataTable student_course_grade = new DataTable();
        bool gpa_less_9_flag = false;

        if (course_grade_range != null)
        {
            DataTable dt_course_with_no_grade = objmaster.get_course_list_with_no_avg_sd_range(sem_code, year_code);

            //DataTable dt_course_allocate_data_for_grade = objmaster.get_course_allocate_data_for_grade(sem_code, year_code);

            //DataTable dt_student_marks_data_for_grade = objmaster.get_student_marks_data_for_grade(sem_code, year_code);

            if (dt_course_with_no_grade != null)
            {
                for (int i = 0; i < dt_course_with_no_grade.Rows.Count; i++)
                {
                    DataRow dr = course_grade_range.NewRow();

                    dr["course_code"] = dt_course_with_no_grade.Rows[i]["course_code"].ToString();
                    dr["A_plus_from"] = "90";
                    dr["A_plus_to"] = "100";
                    dr["A_to"] = "89";
                    dr["D_plus_from"] = "50";
                    dr["F_from"] = "0";
                    dr["F_to"] = "49";

                    course_grade_range.Rows.Add(dr);
                }
            }

            for (int p = 0; p < course_wise_result_data.Rows.Count; p++)
            {
                course_code = course_wise_result_data.Rows[p]["course_code"].ToString();
                DataRow[] course_range = course_grade_range.Select("course_code='" + course_wise_result_data.Rows[p]["course_code"] + "'");

                DataTable dt_Grade_Range = objmaster.get_Grade_Range("", sem_code, year_code);

                if (course_range.Length > 0)
                {
                    //DataRow[] student_subject_marks = (objmaster.get_subject_marks_for_grade(sem_code, year_code)).Select("course_code='" + course_code + "'");
                    // DataTable student_subject_marks = (objmaster.get_subject_marks_for_grade(sem_code, year_code)).Select("course_code='" + course_code + "'").CopyToDataTable();
                    DataTable student_subject_marks = objmaster.get_subject_marks_for_grade_course_wise(sem_code, year_code, course_code);

                    DataTable student_wise_course_dtl = objmaster.get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

                    if (student_subject_marks != null)
                    {
                        student_course_grade = objmaster.course_wise_student_marks_list(course_code, sem_code, year_code);

                        student_course_grade.Columns.Add("subject_marks");
                        student_course_grade.Columns.Add("course_grade");

                        if (course_range[0]["Total_Students"].ToString() != "")
                        {
                            if (Convert.ToInt32(course_range[0]["Total_Students"].ToString()) <= absolute_grading_stud_limit)
                            {
                                gpa_less_9_flag = true;
                            }
                        }

                        if (dt_Grade_Range != null && !gpa_less_9_flag)
                        {
                            DataRow[] dr_Grade_Range = dt_Grade_Range.Select("course_code='" + course_code + "'");

                            if (dr_Grade_Range.Length > 0 && dr_Grade_Range[0]["grade_type"].ToString() == "A")
                            {
                                gpa_less_9_flag = true;
                            }
                        }

                        for (int i = 0; i < student_course_grade.Rows.Count; i++)
                        {
                            //if (course_wise_result_data.Rows[p]["course_code"].ToString() == "CT2614")
                            //{
                            //    string test = "";
                            //}
                            double subject_marks = Convert.ToDouble((student_subject_marks.Select("student_code='" + student_course_grade.Rows[i]["student_code"].ToString() + "'"))[0]["subject_Marks"].ToString());

                            student_course_grade.Rows[i]["subject_marks"] = subject_marks;

                            int year = Convert.ToInt32((student_course_grade.Rows[i]["year_code"].ToString()).Substring(1));

                            DataRow[] dr = student_wise_course_dtl.Select("user_id='" + student_course_grade.Rows[i]["student_code"].ToString() + "'");

                            if (dr.Length > 0)
                            {
                                if (dr[0]["course_type"].ToString() == "E" && dr[0]["gpa_nongpa"].ToString() == "N" || dr[0]["course_type"].ToString() == "M" && dr[0]["gpa_nongpa"].ToString() == "N")
                                {
                                    if (year >= 2018)
                                    {
                                        if (subject_marks < 55)
                                        {
                                            student_course_grade.Rows[i]["course_grade"] = "NP";
                                        }
                                        else if (subject_marks >= 55)
                                        {
                                            student_course_grade.Rows[i]["course_grade"] = "P";
                                        }
                                    }
                                    else
                                    {
                                        if (subject_marks < 50)
                                        {
                                            student_course_grade.Rows[i]["course_grade"] = "NP";
                                        }
                                        else if (subject_marks >= 50)
                                        {
                                            student_course_grade.Rows[i]["course_grade"] = "P";
                                        }
                                    }
                                }
                                else if (year >= 2018)
                                {
                                    if (subject_marks < 55)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "F";
                                    }
                                    else if (subject_marks >= 90)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "O";
                                    }
                                    else if (subject_marks >= 80)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A";
                                    }
                                    else if (subject_marks >= 65)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B";
                                    }
                                    else if (subject_marks >= 55)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C";
                                    }
                                }
                                else if (year < 2014 || gpa_less_9_flag)
                                {
                                    if (subject_marks < 50)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "F";
                                    }
                                    else if (subject_marks >= 87)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["A_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["A_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["B_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["B_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["B_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["C_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["C_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["C_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["D_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "D+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["D_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "D";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(dt_old_grade_range.Rows[0]["D_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "D-";
                                    }
                                }
                                else
                                {
                                    if (subject_marks < 50)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "F";
                                    }
                                    else if (subject_marks >= 90)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A+";
                                    }
                                    else if (course_range[0]["SD"].ToString() == System.DBNull.Value.ToString())
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B-";
                                    }
                                    else if (Convert.ToDouble(course_range[0]["SD"].ToString()) == 0)
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["A_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["A_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "A-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["B_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["B_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["B_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "B-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["C_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C+";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["C_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["C_minus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "C-";
                                    }
                                    else if (subject_marks >= Convert.ToDouble(course_range[0]["D_plus_from"].ToString()))
                                    {
                                        student_course_grade.Rows[i]["course_grade"] = "D+";
                                    }
                                }




                            }
                        }
                        //if (course_wise_result_data.Rows[p]["course_code"].ToString() == "CT2614")
                        //{
                        //    string test = "";
                        //}
                        DataRow[] dr_fail_status = student_course_grade.Select("course_code = '" + course_wise_result_data.Rows[p]["course_code"].ToString() + "' and course_grade ='F' ");
                        if (dr_fail_status.Length > 0)
                        {
                            int passed = Convert.ToInt32(Convert.ToInt32(student_course_grade.Rows.Count.ToString()) - Convert.ToInt32(dr_fail_status.Length.ToString()));
                            course_wise_result_data.Rows[p]["students_passed"] = Convert.ToString(passed);
                            course_wise_result_data.Rows[p]["students_failed"] = dr_fail_status.Length.ToString();
                            course_wise_result_data.Rows[p]["students_enrolled"] = student_course_grade.Rows.Count.ToString();
                        }
                        else
                        {
                            course_wise_result_data.Rows[p]["students_failed"] = "0";
                            course_wise_result_data.Rows[p]["students_passed"] = student_course_grade.Rows.Count.ToString();
                            course_wise_result_data.Rows[p]["students_enrolled"] = student_course_grade.Rows.Count.ToString();
                        }

                    }
                }
            }
        }
        //if (student_course_grade != null)
        //{
        //    jsondata = GetJson1(student_course_grade);

        //}


        if (course_wise_result_data != null)
        {
            jsondata = GetJson1(course_wise_result_data);
        }
        return jsondata;
    }

