    [WebMethod(EnableSession = true)]
    public string get_student_wise_GP_Ratio_report(string sem_code, string year_code, string dept_code, string prog_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataSet student_wise_GP_Ratio_data = objmaster.get_student_wise_GP_Ratio_report(sem_code, year_code, dept_code, prog_code);

        DataTable dt_student_completed_credit_data = student_wise_GP_Ratio_data.Tables[0];
        DataTable dt_student_allocate_data = student_wise_GP_Ratio_data.Tables[1];

        DataTable dt_grade_range = objmaster.get_Grade_Range("", sem_code, year_code);
        DataTable dt_student_course_GP_data = null;

        if (dt_grade_range != null)
        {
            dt_student_course_GP_data = objmaster.Calculate_GP_grade_for_all_students(dt_student_completed_credit_data, dt_student_allocate_data, dt_grade_range);

            dt_student_completed_credit_data.Columns.Add("sem_grade_point_ratio");
            dt_student_completed_credit_data.Columns.Add("dept_name");
            for (int i = 0; i < dt_student_completed_credit_data.Rows.Count; i++)
            {
                DataRow[] dr_student_wise_course_GP = dt_student_course_GP_data.Select("user_id='" + dt_student_completed_credit_data.Rows[i]["user_id"].ToString() + "'");
                dt_student_completed_credit_data.Rows[i]["dept_name"] = dt_student_allocate_data.Rows[0]["dept_name"];
                if (dr_student_wise_course_GP.Length > 0)
                {
                    DataTable dt_credits = objmaster.Calculate_credits_for_all_students(dr_student_wise_course_GP.CopyToDataTable());

                    dt_student_completed_credit_data.Rows[i]["sem_grade_point_ratio"] = dt_credits.Rows[0]["grade_point_avg"];
                }
            }

            var query = from row in dt_student_course_GP_data.AsEnumerable()
                        group row by row.Field<string>("user_id") into users
                        orderby users.Key
                        select new
                        {
                            User = users.Key,
                            User_count = users.Count()
                        };

            if (dt_student_completed_credit_data.Rows.Count > 0)
            {
                int user_max_count = query.ToList().Max(a => a.User_count);

                for (int i = 1; i <= user_max_count; i++)
                {
                    dt_student_completed_credit_data.Columns.Add("course_" + i);
