                for (int j = 0; j < dr_student_course_GP_data.Length; j++)
                {
                    dt_student_completed_credit_data.Rows[i]["course_" + (j + 1)] = dr_student_course_GP_data[j]["course_code"] + "/" + dr_student_course_GP_data[j]["credits"] + "/" + dr_student_course_GP_data[j]["grade_point"];
                    //dt_student_completed_credit_data.Rows[i]["course_" + (j + 1)] = dr_student_course_GP_data[j]["course_code"];
                    //dt_student_completed_credit_data.Rows[i]["course_credit_" + (j + 1)] = dr_student_course_GP_data[j]["credits"];
                    //dt_student_completed_credit_data.Rows[i]["course_GP_" + (j + 1)] = dr_student_course_GP_data[j]["grade_point"];
                }
            }

            //dt_student_course_GP_data.Columns.Add("student_name");
            //dt_student_course_GP_data.Columns.Add("sem_grade_point_ratio");
            //dt_student_course_GP_data.Columns.Add("credits_completed");
            //dt_student_course_GP_data.Columns.Add("mandatory_credits_completed");
            //dt_student_course_GP_data.Columns.Add("elective_credits_completed");

            //for (int i = 0; i < dt_student_course_GP_data.Rows.Count; i++)
            //{
            //    DataRow[] dr_student_completed_credit_data = dt_student_completed_credit_data.Select("user_id='" + dt_student_course_GP_data.Rows[i]["user_id"].ToString() + "'");

            //    if (dr_student_completed_credit_data.Length > 0)
            //    {
            //        dt_student_course_GP_data.Rows[i]["student_name"] = dr_student_completed_credit_data[0]["user_name"];

            //        if (dr_student_completed_credit_data[0]["sem_grade_point_ratio"] == "-")
            //            dt_student_course_GP_data.Rows[i]["sem_grade_point_ratio"] = dr_student_completed_credit_data[0]["sem_grade_point_ratio"];
            //        else
            //            dt_student_course_GP_data.Rows[i]["sem_grade_point_ratio"] = Decimal.Round(Convert.ToDecimal(dr_student_completed_credit_data[0]["sem_grade_point_ratio"]), 2).ToString();

