                        if (Int32.TryParse(dt_student_course_GP_data.Rows[i]["year_code"].ToString().Substring(1), out allocation_year))
                        {
                            if (allocation_year < 2014)
                            {
                                dt_student_course_GP_data.Rows[i]["status"] = "Static";
                            }
                            else
                            {
                                if (dr_ws_course_grade_range[0]["A_plus_from"].ToString() == "87")
                                {
                                    dt_student_course_GP_data.Rows[i]["status"] = "Static";
                                }
                                else
                                {
                                    dt_student_course_GP_data.Rows[i]["status"] = "Relative";
                                }
                            }
                        }
                    }
                }
            }
        }

        if (dt_student_course_GP_data != null)
        {
            if (year_allocation != "")
            {
                DataRow[] dr_row = dt_student_course_GP_data.Select("year_code = '" + year_allocation + "'");
                if (dr_row.Length > 0)
                {
                    DataTable dt = new DataTable();
                    dt = dt_student_course_GP_data.Clone();
                    dt = dt_student_course_GP_data.Select("year_code = '" + year_allocation + "'").CopyToDataTable();
                    if (dt != null)
                    {
                        jsondata = GetJson1(dt);
                        return jsondata;
                    }
                }
                else { return jsondata; }


            }
            jsondata = GetJson1(dt_student_course_GP_data);
        }
        return jsondata;
    }

