    public void calculate_mean_sd(double[] arr, out double mean, out double variance, out double sd)
    {
        mean = 0;
        variance = 0;
        sd = 0;

        for (int i = 0; i < arr.Length; i++)
        {
            mean += arr[i];
        }
        mean = mean / arr.Length;

        for (int i = 0; i < arr.Length; i++)
        {
            variance += Math.Pow((arr[i] - mean), 2);
        }
        variance = variance / arr.Length;

        sd = Math.Sqrt(variance);
    }

    public DataTable calculate_marks_range_for_grade(double mean, double sd)
    {
        DataTable dt_grade_range = new DataTable();

        dt_grade_range.Columns.Add("grade");
        dt_grade_range.Columns.Add("range_from");
        dt_grade_range.Columns.Add("range_to");

        DataRow dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "A+"; dr_grade_range["range_from"] = Math.Round((mean + (1.74 * sd)) + 1); dr_grade_range["range_to"] = "100";
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "A"; dr_grade_range["range_from"] = Math.Round((mean + (1.07 * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + (1.74 * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "A-"; dr_grade_range["range_from"] = Math.Round((mean + (0.56 * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + (1.07 * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "B+"; dr_grade_range["range_from"] = Math.Round((mean + (0.15 * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + (0.56 * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "B"; dr_grade_range["range_from"] = Math.Round((mean + ((-0.16) * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + (0.15 * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "B-"; dr_grade_range["range_from"] = Math.Round((mean + ((-0.57) * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + ((-0.16) * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "C+"; dr_grade_range["range_from"] = Math.Round((mean + ((-1.08) * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + ((-0.57) * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "C"; dr_grade_range["range_from"] = Math.Round((mean + ((-1.75) * sd)) + 1); dr_grade_range["range_to"] = Math.Round(mean + ((-1.08) * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "C-"; dr_grade_range["range_from"] = "50"; dr_grade_range["range_to"] = Math.Round(mean + ((-1.75) * sd));
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        dr_grade_range["grade"] = "F"; dr_grade_range["range_from"] = "0"; dr_grade_range["range_to"] = "49";
        dt_grade_range.Rows.Add(dr_grade_range);
        dr_grade_range = dt_grade_range.NewRow();

        return dt_grade_range;

    }

