    [WebMethod(EnableSession = true)]
    public string save_Student_transcript_dtl(string transcript_dtl)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        Dictionary<string, string> obj_transcript_dtl = ser.Deserialize<Dictionary<string, string>>(transcript_dtl);

        if (obj_transcript_dtl["user_id"].ToString() != "")
        {
            DataTable dt_Students = objmaster.get_Student_transcript_dtl(obj_transcript_dtl["user_id"].ToString());
            DSC_Transcript_Detail obj_transcript = new DSC_Transcript_Detail();

            if (dt_Students != null)
            {
                //dt_Students.Rows[0]["graduation_year"] = obj_transcript_dtl["graduation_year"];
                dt_Students.Rows[0]["graduation_date_code"] = obj_transcript_dtl["graduation_year"];
                dt_Students.Rows[0]["name_of_the_degree"] = obj_transcript_dtl["name_of_the_degree"];

                if (obj_transcript_dtl["degree_code"] != null)
                { dt_Students.Rows[0]["degree_code"] = obj_transcript_dtl["degree_code"]; }

                else { dt_Students.Rows[0]["degree_code"] = DBNull.Value; }


                dt_Students.Rows[0]["previous_degree"] = obj_transcript_dtl["previous_degree"];
                //dt_Students.Rows[0]["topic_type"] = obj_transcript_dtl["topic_type"];

                if (obj_transcript_dtl["topic_type"] != null && obj_transcript_dtl["topic_type"] != "")
                {
                    dt_Students.Rows[0]["topic_type_code"] = obj_transcript_dtl["topic_type"];
                }
                else
                {
                    dt_Students.Rows[0]["topic_type_code"] = DBNull.Value;
                }
                //dt_Students.Rows[0]["topic_type_code"] = obj_transcript_dtl["topic_type"];
                dt_Students.Rows[0]["dissertation_topic"] = obj_transcript_dtl["dissertation_topic"];
                dt_Students.Rows[0]["dissertation_supervisor"] = obj_transcript_dtl["dissertation_supervisor"];
                dt_Students.Rows[0]["specialization"] = obj_transcript_dtl["specialization"];
                dt_Students.Rows[0]["major"] = obj_transcript_dtl["major"];
                dt_Students.Rows[0]["minor"] = obj_transcript_dtl["minor"];
                dt_Students.Rows[0]["transcript_no"] = obj_transcript_dtl["transcript_no"];
                if (obj_transcript_dtl["completion_date_code"] != null)
                    dt_Students.Rows[0]["completion_date_code"] = obj_transcript_dtl["completion_date_code"];
                else
                    dt_Students.Rows[0]["completion_date_code"] = DBNull.Value;
                dt_Students.Rows[0]["degree_code"] = dt_Students.Rows[0]["degree_code"].ToString();
                dt_Students.Rows[0]["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                dt_Students.Rows[0]["last_modified_date"] = DateTime.Now;
                dt_Students.Rows[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                obj_transcript.student_transcript_dtl.ImportRow(dt_Students.Rows[0]);
            }
            else
            {
                DSC_Transcript_Detail.student_transcript_dtlRow student_transcript_row = obj_transcript.student_transcript_dtl.Newstudent_transcript_dtlRow();

                student_transcript_row.doc_no = obj_transcript_dtl["user_id"];
                student_transcript_row.user_id = obj_transcript_dtl["user_id"];
                // student_transcript_row.graduation_year = obj_transcript_dtl["graduation_year"];
