    [WebMethod(EnableSession = true)]
    public string ws_send_for_review(string course_code, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable data = objmaster.ws_grade_submit_detail_list(course_code, sem_code, year_code);

        DSC_WS_GradingMaster grade_master = new DSC_WS_GradingMaster();

        if (data != null)
        {
            try
            {
                if (data.Rows.Count > 0)
                {
                    bool approved = true;

                    for (int i = 0; i < data.Rows.Count; i++)
                    {
                        if (data.Rows[i]["faculty_approved"].ToString() == "Y")
                        {
                            DSC_WS_GradingMaster.ws_grade_submit_detailRow grade_submit_row = grade_master.ws_grade_submit_detail.Newws_grade_submit_detailRow();

                            grade_submit_row.doc_no = data.Rows[i]["doc_no"].ToString();
                            grade_submit_row.course_code = data.Rows[i]["course_code"].ToString();

                            grade_submit_row.faculty_approved = data.Rows[i]["faculty_approved"].ToString();
                            //grade_submit_row.faculty_approved = "N";

                            grade_submit_row.progcoordinate_approved = data.Rows[i]["progcoordinate_approved"].ToString();
                            //grade_submit_row.progcoordinate_approved = "N";

                            //grade_submit_row.ugpgoffice_approved = data.Rows[i]["ugpgoffice_approved"].ToString();
                            grade_submit_row.ugpgoffice_approved = "N";

                            grade_submit_row.dean_approved = data.Rows[i]["dean_approved"].ToString();

                            grade_submit_row.cancel_flag = "N";
                            grade_submit_row.created_by = data.Rows[i]["created_by"].ToString();
                            if (data.Rows[i]["created_date"].ToString() != "" && data.Rows[i]["created_date"].ToString() != null)
                            { grade_submit_row.created_date = Convert.ToDateTime(data.Rows[i]["created_date"]); }
                            grade_submit_row.last_modified_by = user_id;
                            grade_submit_row.last_modified_date = DateTime.Now;
                            grade_submit_row.semester_type = data.Rows[i]["semester_type"].ToString();
                            grade_submit_row.year_semester = data.Rows[i]["year_semester"].ToString();


                            grade_master.ws_grade_submit_detail.Addws_grade_submit_detailRow(grade_submit_row);
                        }
                        else
                        {
                            approved = false;
                        }
                    }

                    if (approved)
                    {
                        objBLReturnObject = objMaster.ws_save_submit_course_grade(grade_master, "2000", HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    }
                    else
                    {
                        return "Course not Submitted by faculty, You can review course after Faculty Submit the course";
                    }

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        return "Course successfully sent for review";
                    }
                }
                else
                {
                    return "Course not Submitted by faculty, You can review course after Faculty Submit the course";
                }
            }
            catch (Exception ex)
            {
                return "Problem in update DATA.";
            }
        }
        else
        {
            return "Course not Submitted by faculty, You can review course after Faculty Submit the course";
        }
        return objBLReturnObject.ServerMessage;
    }

