    [WebMethod(EnableSession = true)]
    public string ws_course_wise_student_marks_list(string course_code, string sem_code, string year_code)
    {
        DataTable student_marks_data = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);

        if (student_marks_data == null)
        {
            student_marks_data = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);

            if (student_marks_data == null)
            {
                DataTable student_wise_course_dtl = objmaster.ws_get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

                if (student_wise_course_dtl != null)
                {
                    try
                    {
                        var user_id = HttpContext.Current.Session["UserId"].ToString();
                        var user_type = HttpContext.Current.Session["user_type"].ToString();

                        DSC_WS_GradingMaster exam_master_add = new DSC_WS_GradingMaster();

                        for (int i = 0; i < student_wise_course_dtl.Rows.Count; i++)
                        {
                            DSC_WS_GradingMaster.ws_student_exam_marks_dtlRow exam_master_row = exam_master_add.ws_student_exam_marks_dtl.Newws_student_exam_marks_dtlRow();

                            exam_master_row.doc_no = (i + 1).ToString();
                            exam_master_row.student_code = student_wise_course_dtl.Rows[i]["user_id"].ToString();
                            exam_master_row.course_code = course_code;
                            exam_master_row.cancel_flag = "N";
                            exam_master_row.created_by = user_id;
                            exam_master_row.created_date = DateTime.Now;
                            exam_master_row.semester_type = sem_code;
                            exam_master_row.year_semester = year_code;


                            exam_master_add.ws_student_exam_marks_dtl.Addws_student_exam_marks_dtlRow(exam_master_row);
                        }

                        objBLReturnObject = objMaster.ws_save_students_for_marks_entry(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);




                        if (objBLReturnObject.ExecutionStatus == 2)
                        {
                            objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        }

                        if (objBLReturnObject.ExecutionStatus == 1)
                        {
                            student_marks_data = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);
                        }
                    }
                    catch (Exception ex)
                    {
                        return ex.ToString();
                    }
                }
            }
        }

        if (student_marks_data != null)
        {
            DataTable student_wise_course_dtl = objmaster.ws_get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

            if (student_wise_course_dtl != null)
            {
                //if (student_wise_course_dtl.Rows.Count > student_marks_data.Rows.Count)
                //{
                try
                {
                    var user_id = HttpContext.Current.Session["UserId"].ToString();
                    var user_type = HttpContext.Current.Session["user_type"].ToString();

                    DSC_WS_GradingMaster exam_master_add = new DSC_WS_GradingMaster();

                    for (int i = 0; i < student_wise_course_dtl.Rows.Count; i++)
                    {
                        DataRow[] dr = student_marks_data.Select("student_code='" + student_wise_course_dtl.Rows[i]["user_id"] + "'");

                        if (dr.Length == 0)
                        {
                            DSC_WS_GradingMaster.ws_student_exam_marks_dtlRow exam_master_row = exam_master_add.ws_student_exam_marks_dtl.Newws_student_exam_marks_dtlRow();

                            exam_master_row.doc_no = (i + 1).ToString();
                            exam_master_row.student_code = student_wise_course_dtl.Rows[i]["user_id"].ToString();
                            exam_master_row.course_code = course_code;
                            exam_master_row.cancel_flag = "N";
                            exam_master_row.created_by = user_id;
                            exam_master_row.created_date = DateTime.Now;
                            exam_master_row.semester_type = sem_code;
                            exam_master_row.year_semester = year_code;

                            exam_master_add.ws_student_exam_marks_dtl.Addws_student_exam_marks_dtlRow(exam_master_row);
                        }
                    }

                    if (exam_master_add.ws_student_exam_marks_dtl.Count > 0)
                    {
                        objBLReturnObject = objMaster.ws_save_students_for_marks_entry(exam_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

                        if (objBLReturnObject.ExecutionStatus == 2)
                        {
                            objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        }

                        if (objBLReturnObject.ExecutionStatus == 1)
                        {
                            student_marks_data = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);
                        }
                    }
                }
                catch (Exception ex)
                {
                    return ex.ToString();
                }
                //}
            }
        }

        string temp = ws_save_calculated_weighted_marks(course_code, sem_code, year_code);

        if (student_marks_data != null)
        {
            jsondata = GetJson1(student_marks_data);
        }
        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string ws_get_student_wise_grade(string course_code, string sem_code, string year_code)
    {
        try
        {
            string temp = ws_save_calculated_weighted_marks(course_code, sem_code, year_code);

            DataTable student_course_grade = new DataTable();

            DataTable student_subject_marks = (objmaster.ws_get_subject_marks_for_grade(sem_code, year_code)).Select("course_code='" + course_code + "'").CopyToDataTable();

            DataTable student_wise_course_dtl = objmaster.ws_get_studentwisecourse_for_marks_entry(course_code, sem_code, year_code);

            if (student_subject_marks.Rows.Count > 0)
            {
                student_course_grade = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);

                student_course_grade.Columns.Add("subject_marks");
                student_course_grade.Columns.Add("course_grade");

                for (int i = 0; i < student_course_grade.Rows.Count; i++)
                {
                    double subject_marks = Convert.ToDouble((student_subject_marks.Select("student_code='" + student_course_grade.Rows[i]["student_code"].ToString() + "'"))[0]["subject_Marks"].ToString());

                    student_course_grade.Rows[i]["subject_marks"] = subject_marks;


                    if (2024 <= Convert.ToInt32(student_course_grade.Rows[i]["year_semester"].ToString()) && student_wise_course_dtl.Rows[0]["gpa_nongpa"].ToString() == "G")
                    {
                        if (subject_marks < 55)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "F";
                        }
                        else if (subject_marks >= 90)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "O";
                        }
                        else if (subject_marks >= 80)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "A";
                        }
                        else if (subject_marks >= 65)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "B";
                        }
                        else if (subject_marks >= 55)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "C";
                        }
                    }

                    else if (subject_marks < 50)
                    {
                        student_course_grade.Rows[i]["course_grade"] = "NP";
                    }

                    else if (2017 < Convert.ToInt32(student_course_grade.Rows[i]["year_code"].ToString().Substring(1)))
                    {
                        if (subject_marks >= 55)
                        {
                            student_course_grade.Rows[i]["course_grade"] = "P";
                        }
                        else
                        {
                            student_course_grade.Rows[i]["course_grade"] = "NP";
                        }
                    }
                    else if (subject_marks >= 50)
                    {
                        student_course_grade.Rows[i]["course_grade"] = "P";
                    }
                }
            }

            if (student_course_grade != null)
            {
                jsondata = GetJson1(student_course_grade);
            }
        }
        catch (Exception ex)
        {
            return ex.Message.ToString();
        }
        return jsondata;
    }

    public string ws_save_calculated_weighted_marks(string course_code, string sem_code, string year_code)
    {
        DataTable data = objmaster.ws_course_wise_student_marks_list(course_code, sem_code, year_code);

        DSC_WS_GradingMaster exam_master_add = new DSC_WS_GradingMaster();

        if (data != null)
        {
            try
            {
                if (data.Rows.Count > 0)
                {

                    DataTable exam_weightage_data = objmaster.ws_course_wise_exam_list(course_code, sem_code, year_code);

                    for (int i = 0; i < data.Rows.Count; i++)
                    {

                        DSC_WS_GradingMaster.ws_student_exam_marks_dtlRow exam_master_row = exam_master_add.ws_student_exam_marks_dtl.Newws_student_exam_marks_dtlRow();

                        exam_master_row.doc_no = data.Rows[i]["doc_no"].ToString();
                        exam_master_row.student_code = data.Rows[i]["student_code"].ToString();
                        exam_master_row.course_code = data.Rows[i]["course_code"].ToString();

                        if (data.Rows[i]["attendance"] != null && data.Rows[i]["attendance"].ToString() != "")
                        {
                            //kapil 03092021
                            exam_master_row.attendance = Convert.ToDouble(data.Rows[i]["attendance"].ToString());
                        }

                        if (data.Rows[i]["exam_1"] != null && data.Rows[i]["exam_1"].ToString() != "")
                        {
                            exam_master_row.exam_1 = Convert.ToDouble(data.Rows[i]["exam_1"].ToString());
                            exam_master_row.exam_1_w = (Convert.ToDouble(data.Rows[i]["exam_1"].ToString()) * Convert.ToDouble(exam_weightage_data.Select("exam_code='exam_1'")[0]["weightage"].ToString())) / 100;
                        }
                        if (data.Rows[i]["exam_2"] != null && data.Rows[i]["exam_2"].ToString() != "")
                        {
