    [WebMethod(EnableSession = true)]
    public string ws_submit_course_wise_grade_range_new(string sem_code, string year_code, string course_grade_type, string selected_course, bool ALL_Course)
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();
        string status = ws_save_course_wise_avg_sd_range_new(sem_code, year_code, course_grade_type, selected_course, ALL_Course, user_id);

        return status;
    }

    public string ws_save_course_wise_avg_sd_range_new(string sem_code, string year_code, string course_grade_type, string selected_course, bool ALL_Course, string user_id)
    {
        //if (Convert.ToInt32(year_code) < 2017)
