        //comment delete SWS Course Grade Range
        // objmaster.ws_delete_course_wise_grade_range(sem_code, year_code);

        string courses_selected = "";

        Boolean cancel_ranged = false;

        string[] segments = selected_course.Split('#');

        for (int i = 0; i < segments.Length; i++)
        {
            if (i == 0)
            {
                courses_selected = "'" + segments[i] + "'";
            }
            else
            {
                courses_selected += ", '" + segments[i] + "'";
            }
        }


        DataTable data = objmaster.ws_get_course_wise_avg_sd_range(sem_code, year_code);

        DataTable dt_grade_type = JsonConvert.DeserializeObject<DataTable>(course_grade_type);

        DSC_WS_GradingMaster exam_master_add = new DSC_WS_GradingMaster();

        if (data != null)
        {
            try
            {
                DataTable dt_course_with_no_grade = objmaster.ws_get_course_list_with_no_avg_sd_range(sem_code, year_code);
                //DataTable dt_course_allocate_data_for_grade = objmaster.get_course_allocate_data_for_grade(sem_code, year_code);
                //DataTable dt_student_marks_data_for_grade = objmaster.get_student_marks_data_for_grade(sem_code, year_code);

                if (dt_course_with_no_grade != null)
                {
                    for (int i = 0; i < dt_course_with_no_grade.Rows.Count; i++)
                    {
                        DataRow dr = data.NewRow();
                        dr["course_code"] = dt_course_with_no_grade.Rows[i]["course_code"].ToString();
                        dr["A_plus_from"] = "90";
                        dr["A_plus_to"] = "100";
                        dr["A_to"] = "89";
                        dr["D_plus_from"] = "50";
                        dr["F_from"] = "0";
                        dr["F_to"] = "49";

                        data.Rows.Add(dr);
                    }
                }

                if (data.Rows.Count > 0)
                {
                    DataTable dt_old_grade_range = get_Old_Grade_Range();

                    for (int i = 0; i < data.Rows.Count; i++)
                    {
                        if (data.Rows[i]["Total_Students"].ToString() != "")
                        {
                            if (Convert.ToInt32(data.Rows[i]["Total_Students"].ToString()) < 10)
                            {
                                data.Rows[i]["A_plus_from"] = dt_old_grade_range.Rows[0]["A_plus_from"];
                                data.Rows[i]["A_plus_to"] = dt_old_grade_range.Rows[0]["A_plus_to"];
                                data.Rows[i]["A_from"] = dt_old_grade_range.Rows[0]["A_from"];
                                data.Rows[i]["A_to"] = dt_old_grade_range.Rows[0]["A_to"];
                                data.Rows[i]["A_minus_from"] = dt_old_grade_range.Rows[0]["A_minus_from"];
                                data.Rows[i]["A_minus_to"] = dt_old_grade_range.Rows[0]["A_minus_to"];
                                data.Rows[i]["B_plus_from"] = dt_old_grade_range.Rows[0]["B_plus_from"];
                                data.Rows[i]["B_plus_to"] = dt_old_grade_range.Rows[0]["B_plus_to"];
                                data.Rows[i]["B_from"] = dt_old_grade_range.Rows[0]["B_from"];
                                data.Rows[i]["B_to"] = dt_old_grade_range.Rows[0]["B_to"];
                                data.Rows[i]["B_minus_from"] = dt_old_grade_range.Rows[0]["B_minus_from"];
                                data.Rows[i]["B_minus_to"] = dt_old_grade_range.Rows[0]["B_minus_to"];
                                data.Rows[i]["C_plus_from"] = dt_old_grade_range.Rows[0]["C_plus_from"];
                                data.Rows[i]["C_plus_to"] = dt_old_grade_range.Rows[0]["C_plus_to"];
                                data.Rows[i]["C_from"] = dt_old_grade_range.Rows[0]["C_from"];
                                data.Rows[i]["C_to"] = dt_old_grade_range.Rows[0]["C_to"];
                                data.Rows[i]["C_minus_from"] = dt_old_grade_range.Rows[0]["C_minus_from"];
                                data.Rows[i]["C_minus_to"] = dt_old_grade_range.Rows[0]["C_minus_to"];
                                data.Rows[i]["D_plus_from"] = dt_old_grade_range.Rows[0]["D_plus_from"];
                                data.Rows[i]["D_plus_to"] = dt_old_grade_range.Rows[0]["D_plus_to"];
                            }
                        }
                    }

                    for (int i = 0; i < data.Rows.Count; i++)
                    {
                        DataRow[] dr_grade_type = dt_grade_type.Select("course_code='" + data.Rows[i]["course_code"].ToString() + "'");

                        DSC_WS_GradingMaster.ws_course_wise_grade_rangeRow exam_master_row = exam_master_add.ws_course_wise_grade_range.Newws_course_wise_grade_rangeRow();

                        exam_master_row.doc_no = (i + 1).ToString();
                        exam_master_row.course_code = data.Rows[i]["course_code"].ToString();

                        if (dr_grade_type.Length > 0)
                        {
                            exam_master_row.grade_type = dr_grade_type[0]["grade_type"].ToString();
                        }

                        if (data.Rows[i]["Average"] != null && data.Rows[i]["Average"].ToString() != "")
                        {
