                        if (data.Rows[i]["SD"] != null && data.Rows[i]["SD"].ToString() != "")
                        {
                            exam_master_row.sd = Convert.ToDouble(data.Rows[i]["SD"].ToString());
                        }

                        if (dr_grade_type.Length > 0 && dr_grade_type[0]["grade_type"].ToString() == "R")
                        {
                            if (data.Rows[i]["A_plus_from"] != null && data.Rows[i]["A_plus_from"].ToString() != "")
                            {
                                exam_master_row.A_plus_from = Convert.ToInt32(data.Rows[i]["A_plus_from"].ToString());
                            }
                            if (data.Rows[i]["A_plus_to"] != null && data.Rows[i]["A_plus_to"].ToString() != "")
                            {
                                exam_master_row.A_plus_to = Convert.ToInt32(data.Rows[i]["A_plus_to"].ToString());
                            }
                            if (data.Rows[i]["A_from"] != null && data.Rows[i]["A_from"].ToString() != "")
                            {
                                exam_master_row.A_from = Convert.ToInt32(data.Rows[i]["A_from"].ToString());
                            }
                            if (data.Rows[i]["A_to"] != null && data.Rows[i]["A_to"].ToString() != "")
                            {
                                exam_master_row.A_to = Convert.ToInt32(data.Rows[i]["A_to"].ToString());
                            }
                            if (data.Rows[i]["A_minus_from"] != null && data.Rows[i]["A_minus_from"].ToString() != "")
                            {
                                exam_master_row.A_minus_from = Convert.ToInt32(data.Rows[i]["A_minus_from"].ToString());
                            }
                            if (data.Rows[i]["A_minus_to"] != null && data.Rows[i]["A_minus_to"].ToString() != "")
                            {
                                exam_master_row.A_minus_to = Convert.ToInt32(data.Rows[i]["A_minus_to"].ToString());
                            }

                            if (data.Rows[i]["B_plus_from"] != null && data.Rows[i]["B_plus_from"].ToString() != "")
                            {
                                exam_master_row.B_plus_from = Convert.ToInt32(data.Rows[i]["B_plus_from"].ToString());
                            }
                            if (data.Rows[i]["B_plus_to"] != null && data.Rows[i]["B_plus_to"].ToString() != "")
                            {
                                exam_master_row.B_plus_to = Convert.ToInt32(data.Rows[i]["B_plus_to"].ToString());
                            }
                            if (data.Rows[i]["B_from"] != null && data.Rows[i]["B_from"].ToString() != "")
                            {
                                exam_master_row.B_from = Convert.ToInt32(data.Rows[i]["B_from"].ToString());
                            }
                            if (data.Rows[i]["B_to"] != null && data.Rows[i]["B_to"].ToString() != "")
                            {
                                exam_master_row.B_to = Convert.ToInt32(data.Rows[i]["B_to"].ToString());
                            }
                            if (data.Rows[i]["B_minus_from"] != null && data.Rows[i]["B_minus_from"].ToString() != "")
                            {
                                exam_master_row.B_minus_from = Convert.ToInt32(data.Rows[i]["B_minus_from"].ToString());
                            }
                            if (data.Rows[i]["B_minus_to"] != null && data.Rows[i]["B_minus_to"].ToString() != "")
                            {
                                exam_master_row.B_minus_to = Convert.ToInt32(data.Rows[i]["B_minus_to"].ToString());
                            }

                            if (data.Rows[i]["C_plus_from"] != null && data.Rows[i]["C_plus_from"].ToString() != "")
                            {
                                exam_master_row.C_plus_from = Convert.ToInt32(data.Rows[i]["C_plus_from"].ToString());
                            }
                            if (data.Rows[i]["C_plus_to"] != null && data.Rows[i]["C_plus_to"].ToString() != "")
                            {
                                exam_master_row.C_plus_to = Convert.ToInt32(data.Rows[i]["C_plus_to"].ToString());
                            }
                            if (data.Rows[i]["C_from"] != null && data.Rows[i]["C_from"].ToString() != "")
                            {
                                exam_master_row.C_from = Convert.ToInt32(data.Rows[i]["C_from"].ToString());
                            }
                            if (data.Rows[i]["C_to"] != null && data.Rows[i]["C_to"].ToString() != "")
                            {
                                exam_master_row.C_to = Convert.ToInt32(data.Rows[i]["C_to"].ToString());
                            }
                            if (data.Rows[i]["C_minus_from"] != null && data.Rows[i]["C_minus_from"].ToString() != "")
                            {
                                exam_master_row.C_minus_from = Convert.ToInt32(data.Rows[i]["C_minus_from"].ToString());
                            }
                            if (data.Rows[i]["C_minus_to"] != null && data.Rows[i]["C_minus_to"].ToString() != "")
                            {
                                exam_master_row.C_minus_to = Convert.ToInt32(data.Rows[i]["C_minus_to"].ToString());
                            }

                            if (data.Rows[i]["D_plus_from"] != null && data.Rows[i]["D_plus_from"].ToString() != "")
                            {
                                exam_master_row.D_plus_from = Convert.ToInt32(data.Rows[i]["D_plus_from"].ToString());
                            }
                            if (data.Rows[i]["D_plus_to"] != null && data.Rows[i]["D_plus_to"].ToString() != "")
                            {
                                exam_master_row.D_plus_to = Convert.ToInt32(data.Rows[i]["D_plus_to"].ToString());
                            }
                        }
                        else
                        {
                            exam_master_row.A_plus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_plus_from"]);
                            exam_master_row.A_plus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_plus_to"]);
                            exam_master_row.A_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_from"]);
                            exam_master_row.A_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_to"]);
                            exam_master_row.A_minus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_minus_from"]);
                            exam_master_row.A_minus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["A_minus_to"]);
                            exam_master_row.B_plus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_plus_from"]);
                            exam_master_row.B_plus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_plus_to"]);
                            exam_master_row.B_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_from"]);
                            exam_master_row.B_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_to"]);
                            exam_master_row.B_minus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_minus_from"]);
                            exam_master_row.B_minus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["B_minus_to"]);
                            exam_master_row.C_plus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_plus_from"]);
                            exam_master_row.C_plus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_plus_to"]);
                            exam_master_row.C_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_from"]);
                            exam_master_row.C_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_to"]);
                            exam_master_row.C_minus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_minus_from"]);
                            exam_master_row.C_minus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["C_minus_to"]);
                            exam_master_row.D_plus_from = Convert.ToInt32(dt_old_grade_range.Rows[0]["D_plus_from"]);
                            exam_master_row.D_plus_to = Convert.ToInt32(dt_old_grade_range.Rows[0]["D_plus_to"]);
                        }

                        exam_master_row.cancel_flag = "N";
                        exam_master_row.created_by = HttpContext.Current.Session["UserId"].ToString();
                        exam_master_row.created_date = DateTime.Now;
                        exam_master_row.semester_type = sem_code;
                        exam_master_row.year_semester = year_code;

                        exam_master_add.ws_course_wise_grade_range.Addws_course_wise_grade_rangeRow(exam_master_row);
                    }

                    // objBLReturnObject = objMaster.ws_save_course_wise_avg_sd_range(exam_master_add, "2000", "", HttpContext.Current.Request.UserHostName);

                    for (int mprCnt = 0; mprCnt < exam_master_add.ws_course_wise_grade_range.Rows.Count; mprCnt++)
                    {
                        bool aval = false;

                        for (int z = 0; z < segments.Length; z++)
                        {
                            if (exam_master_add.ws_course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() == segments[z])
                            {
                                aval = true;
                            }
                        }

                        if (!aval)
                        {
                            DataRow[] rows;
                            rows = exam_master_add.ws_course_wise_grade_range.Select("course_code = '" + exam_master_add.ws_course_wise_grade_range.Rows[mprCnt]["course_code"].ToString() + "'");
                            foreach (DataRow row in rows)
                                exam_master_add.ws_course_wise_grade_range.Rows.Remove(row);

                            mprCnt = mprCnt - 1;
                        }
                    }

                    if (ALL_Course)
                        cancel_ranged = objmaster.ws_CancelCourseWiseGradeRange(sem_code, year_code, "ALL", user_id, exam_master_add);
                    else
                        cancel_ranged = objmaster.ws_CancelCourseWiseGradeRange(sem_code, year_code, courses_selected, user_id, exam_master_add);

                    if (cancel_ranged)
                    {
                        objBLReturnObject = objMaster.ws_save_course_wise_avg_sd_range(exam_master_add, "2000", "", HttpContext.Current.Request.UserHostName);
                    }
                    else
                    {
                        objBLReturnObject.ExecutionStatus = 2;
                        objBLReturnObject.ServerMessage = "Error While Cancelling Course Wise Grade Range.";
                        return objBLReturnObject.ServerMessage;
                    }
                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                }
            }
            catch (Exception ex)
            {
                return "Problem in update DATA.";
            }
        }
        else
        {
            objBLReturnObject.ExecutionStatus = 2;
            objBLReturnObject.ServerMessage = "Course Grade Range not updated.";
            return objBLReturnObject.ServerMessage;
        }

        return objBLReturnObject.ServerMessage;
    }
