    [WebMethod(EnableSession = true)]
    public string save_WS_course_data(string All_table_course_data)
    {
        //Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            


            JavaScriptSerializer ser = new JavaScriptSerializer();

            ArrayList Course_Master_data = ser.Deserialize<ArrayList>(All_table_course_data);

            Dictionary<string, object> course_data = (Dictionary<string, object>)Course_Master_data[0];
            string action = (string)Course_Master_data[1];

            DataTable cur_sem = objmaster.Get_cept_current_sem_data("ws_course");

            DataTable dt_course_budget_data = objmaster.Get_course_budget_data(cur_sem.Rows[0]["sem_code"].ToString(), cur_sem.Rows[0]["year_code"].ToString(), course_data["course_code"].ToString().Trim());

            DSC_ws_course_master ws_course_mst = new DSC_ws_course_master();
            DSC_ws_course_master.ws_course_proposalRow ws_course_mst_row = ws_course_mst.ws_course_proposal.Newws_course_proposalRow();

            DataTable dt_ws_course_data = objmaster.Get_ws_courseproposal_data(cur_sem.Rows[0]["sem_code"].ToString(), cur_sem.Rows[0]["year_code"].ToString());

            if (course_data["course_code"].ToString().Trim() != "" && dt_ws_course_data != null)
            {
                DataRow[] dr_course_data = dt_ws_course_data.Select("course_code='" + course_data["course_code"].ToString().Trim() + "'");

                if (dr_course_data.Length > 0)
                {
                    ws_course_mst_row.ItemArray = dr_course_data[0].ItemArray;

                    ws_course_mst_row.last_modified_by = user_id;
                    ws_course_mst_row.last_modified_date = DateTime.Now;
                    ws_course_mst_row.last_modified_host = HttpContext.Current.Request.UserHostName;
                }
            }
            else
            {
                ws_course_mst_row.course_code = "";
                ws_course_mst_row.instructor_approved = "N";
                ws_course_mst_row.dean_approved = "N";
                ws_course_mst_row.cancel_flag = "N";
                ws_course_mst_row.created_by = user_id;
                ws_course_mst_row.created_date = DateTime.Now;
                ws_course_mst_row.created_host = HttpContext.Current.Request.UserHostName;
                ws_course_mst_row.semester_type = cur_sem.Rows[0]["sem_code"].ToString();
                ws_course_mst_row.year_semester = cur_sem.Rows[0]["year_code"].ToString();
            }

            ws_course_mst_row.course_name = course_data["course_title"].ToString();
            ws_course_mst_row.category_location_wise = course_data["category_location_wise"].ToString();
            ws_course_mst_row.location = course_data["location"].ToString();
            ws_course_mst_row.available_seat = course_data["intake_capacity"].ToString();
            //ws_course_mst_row.minimum_seat = course_data["minimum_seat"].ToString();
            //ws_course_mst_row.waiting_seat = course_data["waiting_seat"].ToString();
            ws_course_mst_row.minimum_seat = course_data["minimum_seat"].ToString();
            ws_course_mst_row.is_cancel = "N";//By Default
            ws_course_mst_row.course_credits = course_data["credits"].ToString();
            ws_course_mst_row.gpa_status = course_data["gpa_status"].ToString();
            ws_course_mst_row.course_desc = course_data["description"].ToString();
            ws_course_mst_row.prerequisite = course_data["prerequisite"].ToString();
            ws_course_mst_row.is_open_for_professional = course_data["is_open_for_professional"].ToString();
            ws_course_mst_row.prerequisite_for_prof = course_data["professional_prerequisite"].ToString();
            ws_course_mst_row.total_instructors_involved = course_data["total_instructors_involved"].ToString();
            ws_course_mst_row.course_type = course_data["course_type"].ToString();


            DateTime temp_date = new DateTime();
            if (DateTime.TryParse(course_data["start_date"].ToString(), out temp_date))
                ws_course_mst_row.start_date = temp_date;
            if (DateTime.TryParse(course_data["end_date"].ToString(), out temp_date))
                ws_course_mst_row.end_date = temp_date;
            ws_course_mst_row.image_name = course_data["course_image"].ToString();
            ws_course_mst_row.image_source = course_data["image_source"].ToString();
            ws_course_mst_row.inhabitation = course_data["inhabitation"].ToString();
            ws_course_mst_row.methodology = course_data["methodology"].ToString();
            ws_course_mst_row.course_output1 = course_data["course_output1"].ToString();
            ws_course_mst_row.course_output2 = course_data["course_output2"].ToString();
            ws_course_mst_row.course_output3 = course_data["course_output3"].ToString();
            ws_course_mst_row.material_cost = course_data["material_cost"].ToString();
            ws_course_mst_row.food_stay = course_data["food_stay"].ToString();
            ws_course_mst_row.local_travel = course_data["local_travel"].ToString();
            ws_course_mst_row.approx_expense = course_data["approx_expense"].ToString();
            ws_course_mst_row.travel_expense = course_data["travel_expense"].ToString();
            ws_course_mst_row.total_expense = course_data["total_expense"].ToString();
            ws_course_mst_row.portfolio = ser.Serialize(course_data["portfolio"]);
            ws_course_mst_row.learning_outcomes = course_data["learning_outcomes"].ToString();
            ws_course_mst_row.termsandcondition = course_data["termsandcondition"].ToString();

            DateTime temp_date_tral = new DateTime();
            if (DateTime.TryParse(course_data["TravelStartDate"].ToString(), out temp_date_tral))
                ws_course_mst_row.TravelStartDate = temp_date_tral;
            if (DateTime.TryParse(course_data["TravelEndDate"].ToString(), out temp_date_tral))
