                ws_course_instructor_row.year_semester = year_code;//cur_sem.Rows[0]["year_code"].ToString();

                ws_course_mst.ws_course_proposal_instructor.Addws_course_proposal_instructorRow(ws_course_instructor_row);
            }

            ArrayList TA = (ArrayList)course_data["TA"];
            for (int i = 0; i < TA.Count; i++)
            {
                DSC_ws_course_master.ws_course_proposal_TARow ws_course_TA_row = ws_course_mst.ws_course_proposal_TA.Newws_course_proposal_TARow();

                // ws_course_TA_row.doc_no = (i + 1).ToString();
                ws_course_TA_row.course_code = course_data["course_code"].ToString().Trim();


                // old code 03092024
                //ws_course_TA_row.instructor_code = ((Dictionary<string, object>)TA[i])["instructor_code"].ToString().Trim();
                //ws_course_TA_row.instructor_type = ((Dictionary<string, object>)TA[i])["instructor_type"].ToString().Trim();
                //ws_course_TA_row.ContactHrs = ((Dictionary<string, object>)TA[i])["contact_hrs"].ToString().Trim();
                //ws_course_TA_row.AdditionalHrs = ((Dictionary<string, object>)TA[i])["Addtional_Hours"].ToString().Trim();
                //ws_course_TA_row.TotalHrs = ((Dictionary<string, object>)TA[i])["Total_Hours"].ToString().Trim();



                // New code 03092024 Add Validation Call For NitinBhai 
                var taDictionary = (Dictionary<string, object>)TA[i];

                ws_course_TA_row.instructor_code = taDictionary.ContainsKey("instructor_code")
                    && taDictionary["instructor_code"] != null
                    && taDictionary["instructor_code"].ToString().Trim() != ""
                    ? taDictionary["instructor_code"].ToString().Trim()
                    : null;

                ws_course_TA_row.instructor_type = taDictionary.ContainsKey("instructor_type")
                    && taDictionary["instructor_type"] != null
                    && taDictionary["instructor_type"].ToString().Trim() != ""
                    ? taDictionary["instructor_type"].ToString().Trim()
                    : null;

                ws_course_TA_row.ContactHrs = taDictionary.ContainsKey("contact_hrs")
                    && taDictionary["contact_hrs"] != null
                    && taDictionary["contact_hrs"].ToString().Trim() != ""
                    ? taDictionary["contact_hrs"].ToString().Trim()
                    : null;

                ws_course_TA_row.AdditionalHrs = taDictionary.ContainsKey("Addtional_Hours")
                    && taDictionary["Addtional_Hours"] != null
                    && taDictionary["Addtional_Hours"].ToString().Trim() != ""
                    ? taDictionary["Addtional_Hours"].ToString().Trim()
                    : null;


                if (taDictionary.ContainsKey("Total_Hours"))
                {
                    ws_course_TA_row.TotalHrs = taDictionary.ContainsKey("Total_Hours")
                    && taDictionary["Total_Hours"] != null
                    && taDictionary["Total_Hours"].ToString().Trim() != "" ? taDictionary["Total_Hours"].ToString().Trim() : null;

                }
                else
                {
                    ws_course_TA_row.TotalHrs = null;
                }


                ws_course_TA_row.cancel_flag = "N";
                ws_course_TA_row.created_by = user_id;
                ws_course_TA_row.created_date = DateTime.Now;
                ws_course_TA_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                ws_course_TA_row.semester_type = sem_code1;//cur_sem.Rows[0]["sem_code"].ToString();
                ws_course_TA_row.year_semester = year_code;//cur_sem.Rows[0]["year_code"].ToString();

                ws_course_mst.ws_course_proposal_TA.Addws_course_proposal_TARow(ws_course_TA_row);
            }
            ArrayList workplan = (ArrayList)course_data["workplan"];
            for (int i = 0; i < workplan.Count; i++)
            {
                DSC_ws_course_master.ws_course_proposal_workplanRow ws_course_workplan_row = ws_course_mst.ws_course_proposal_workplan.Newws_course_proposal_workplanRow();

                ws_course_workplan_row.course_code = course_data["course_code"].ToString().Trim();

                DateTime temp_workplandate = new DateTime();
                if (DateTime.TryParse(((Dictionary<string, object>)workplan[i])["workplan_date"].ToString(), out temp_date))
                    ws_course_workplan_row.workplan_date = temp_date;

                //ws_course_workplan_row.from_time = ((Dictionary<string, object>)workplan[i])["from_time"].ToString().Trim();
                //ws_course_workplan_row.To_time = ((Dictionary<string, object>)workplan[i])["to_time"].ToString().Trim();
                //ws_course_workplan_row.topic_covered = ((Dictionary<string, object>)workplan[i])["topic_covered"].ToString().Trim();
                //ws_course_workplan_row.methodology = ((Dictionary<string, object>)workplan[i])["methodology"].ToString().Trim();
                //ws_course_workplan_row.no_of_hrs = ((Dictionary<string, object>)workplan[i])["no_of_hrs"].ToString().Trim();
                //ws_course_workplan_row.faculty_involve = ((Dictionary<string, object>)workplan[i])["faculty_involve"].ToString().Trim();




                var workplanDictionary = (Dictionary<string, object>)workplan[i];

                ws_course_workplan_row.from_time = workplanDictionary.ContainsKey("from_time") && workplanDictionary["from_time"] != null
                    ? workplanDictionary["from_time"].ToString().Trim() : null;

                ws_course_workplan_row.To_time = workplanDictionary.ContainsKey("to_time") && workplanDictionary["to_time"] != null
                    ? workplanDictionary["to_time"].ToString().Trim()
                    : null;

                ws_course_workplan_row.topic_covered = workplanDictionary.ContainsKey("topic_covered") && workplanDictionary["topic_covered"] != null
                    ? workplanDictionary["topic_covered"].ToString().Trim()
                    : null;

                ws_course_workplan_row.methodology = workplanDictionary.ContainsKey("methodology") && workplanDictionary["methodology"] != null
                    ? workplanDictionary["methodology"].ToString().Trim()
                    : null;

                ws_course_workplan_row.no_of_hrs = workplanDictionary.ContainsKey("no_of_hrs") && workplanDictionary["no_of_hrs"] != null
                    ? workplanDictionary["no_of_hrs"].ToString().Trim()
                    : null;

                ws_course_workplan_row.faculty_involve = workplanDictionary.ContainsKey("faculty_involve") && workplanDictionary["faculty_involve"] != null
                    ? workplanDictionary["faculty_involve"].ToString().Trim() : null;


                ws_course_workplan_row.cancel_flag = "N";
                ws_course_workplan_row.created_by = user_id;
                ws_course_workplan_row.created_date = DateTime.Now;
                ws_course_workplan_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                ws_course_workplan_row.semester_type = sem_code1;//cur_sem.Rows[0]["sem_code"].ToString();
                ws_course_workplan_row.year_semester = year_code;//cur_sem.Rows[0]["year_code"].ToString();

                ws_course_mst.ws_course_proposal_workplan.Addws_course_proposal_workplanRow(ws_course_workplan_row);
            }


            //// // 

            objBLReturnObject = objMaster.save_ws_course_master(ws_course_mst, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                if (dt_publish_course_dtl != null)
                {
                    Dictionary<string, string> dic_response = objmaster.after_publish_course_data_save(course_data["course_code"].ToString().Trim(), dt_publish_course_dtl, sem_code1, year_code, user_id);
                    //return_ajax_string(dic_response["status"], dic_response["message"]);
                }
                if (TravelStartDate == "" && TravelEndDate == "")
                {
                    bool status = objmaster.UpdateWSDate(course_data["course_code"].ToString().Trim(), sem_code1, year_code);
                }
                DSC_Course_Log course_log = new DSC_Course_Log();

                DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                course_log_row.log_id = "1";
                course_log_row.user_id = user_id;
                course_log_row.course_code = course_data["course_code"].ToString();
                if (course_data["course_code"].ToString() == "") course_log_row.remark = "New WS Course Proposal";
                else course_log_row.remark = "Edit WS Course Proposal";
                course_log_row.created_by = user_id;
                course_log_row.created_date = DateTime.Now;
                course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                BLReturnObject Log_objBLReturnObject = new BLReturnObject(); 

                Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                //user_type == "I2" || user_type == "PC" || user_type == "D" || user_type == "FA"
                if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["is_submit"].ToString() != "Y" && user_type == "I2")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["dean_status"].ToString() != "Y" && user_type == "D")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if(dt_course_budget_data != null && dt_course_budget_data.Rows[0]["FA_status"].ToString() != "Y" && user_type == "FA")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }

                else if(dt_course_budget_data != null && dt_course_budget_data.Rows[0]["ugpg_status"].ToString() != "Y" && (user_type == "A1" || user_type == "A"))
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["is_submit"].ToString() == "Y" && user_type == "I2")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["dean_status"].ToString() == "Y" && user_type == "D")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["FA_status"].ToString() == "Y" && user_type == "FA")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data != null && user_type == "PC")
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }

                else if (dt_course_budget_data != null && dt_course_budget_data.Rows[0]["ugpg_status"].ToString() == "Y" && (user_type == "A1" || user_type == "A"))
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
                else if (dt_course_budget_data == null)
                {
                    return Log_objBLReturnObject.ServerMessage = "2";
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }


    [WebMethod(EnableSession = true)]
    public string get_ws_offered_course_list(string sem_code, string year_code, string dept_code)
    {
        //System.IO.File.AppendAllText(@"C:\Ceptreg_Log\WS_test.txt", "Method Starts : " + DateTime.Now + Environment.NewLine);

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        bool authorize = false;
        DataTable dt_dean_dtl = objmaster.get_semyearwise_dean_user_dtl(user_id, user_type, sem_code, year_code);
        DataTable dt_fa_dtl = objmaster.get_semyearwise_fa_user_dtl(user_id, user_type, sem_code, year_code);
        //System.IO.File.AppendAllText(@"C:\Ceptreg_Log\WS_test.txt", "After Dean detail : " + DateTime.Now + Environment.NewLine);

        if (user_type == "D")
        {
            if (dt_dean_dtl != null)
            {
                authorize = true;
            }
        }
        else if (user_type == "WSA" || user_type == "A" || user_type == "I2" || user_type == "PC" || user_type == "D")
        {
            authorize = true;
        }
        else if (user_type == "FA")
        {
            if (dt_fa_dtl != null)
            {
                authorize = true;
            }
        }

        if (authorize)
        {

            DataTable dt_ws_course_proposal_data = objmaster.Get_ws_courseproposal_data(sem_code, year_code);

            //System.IO.File.AppendAllText(@"C:\Ceptreg_Log\WS_test.txt", "After dt_ws_course_proposal_data : " + DateTime.Now + Environment.NewLine);

            DataTable dt_ws_course_proposal_instructor_data = objmaster.get_all_ws_course_proposal_instructor_data(sem_code, year_code);
            //System.IO.File.AppendAllText(@"C:\Ceptreg_Log\WS_test.txt", "After dt_ws_course_proposal_instructor_data : " + DateTime.Now + Environment.NewLine);

            DataTable dt_ws_course_proposal_workplan_data = objmaster.get_all_ws_course_proposal_workplan_data(sem_code, year_code);
            //System.IO.File.AppendAllText(@"C:\Ceptreg_Log\WS_test.txt", "After dt_ws_course_proposal_workplan_data : " + DateTime.Now + Environment.NewLine);
            DataTable WS_Course_Wise_TA_Details = objmaster.WS_Course_Wise_TA_Details(sem_code, year_code);

            if (dt_ws_course_proposal_data != null)
            {
                string str_course = "";
                DataRow[] dr_ws_course_proposal_data = null;
                if (dt_ws_course_proposal_instructor_data != null)
                {
                    //string str_course = "(";
                    str_course = "(";
                    DataRow[] dr_ws_course_instructor_data = dt_ws_course_proposal_instructor_data.Select("instructor_code='" + user_id + "'");

                    if (dr_ws_course_instructor_data.Length > 0)
                    {
                        str_course += "'" + dr_ws_course_instructor_data[0]["course_code"].ToString().Trim() + "'";
                        for (int i = 1; i < dr_ws_course_instructor_data.Length; i++)
                            str_course += ",'" + dr_ws_course_instructor_data[i]["course_code"].ToString().Trim() + "'";
                    }

                    str_course += ")";
                }

                if (user_type == "D" && dt_dean_dtl.Rows.Count > 0)
                {
                    string inhabitation = "(";

                    inhabitation += "'" + dt_dean_dtl.Rows[0]["dept_code"].ToString().Trim() + "'";
                    for (int i = 1; i < dt_dean_dtl.Rows.Count; i++)
                        inhabitation += ",'" + dt_dean_dtl.Rows[i]["dept_code"].ToString().Trim() + "'";

                    inhabitation += ")";

                    //dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("instructor_approved='Y' and (dean_approved not in ('A','S','R') or dean_approved is null) and inhabitation in " + inhabitation);
                    if (str_course == "()")
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("(instructor_approved='Y' and (dean_approved not in ('A','S','R') or dean_approved is null) and inhabitation in " + inhabitation + ") or (instructor_approved='N' and (dean_approved not in ('A') or dean_approved is null) and created_by = '" + user_id + "')");
                    else
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("(instructor_approved='Y' and (dean_approved not in ('A','S','R') or dean_approved is null) and inhabitation in " + inhabitation + ") or (instructor_approved='N' and (dean_approved not in ('A') or dean_approved is null) and course_code in " + str_course + ")");
                }
                else if (user_type == "WSA" || user_type == "A")
                {
                    dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("instructor_approved='Y' and (dean_approved not in ('A','S','R') or dean_approved is null)");
                }
                else if (user_type == "PC" || user_type == "D")
                {
                    if (str_course == "()")
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("instructor_approved='N' and (dean_approved not in ('A') or dean_approved is null) and created_by = '" + user_id + "'");
                    else
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("instructor_approved='N' and (dean_approved not in ('A') or dean_approved is null) and course_code in " + str_course);
                }
                else if (user_type == "I2")
                {
                    if (str_course == "()")
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("(dean_approved='N' or dean_approved='S') and (instructor_approved = 'Y' or instructor_approved = 'N') and created_by = '" + user_id + "'");
                    else
                        dr_ws_course_proposal_data = dt_ws_course_proposal_data.Select("(dean_approved='N' or dean_approved='S') and (instructor_approved = 'Y' or instructor_approved = 'N') and course_code in " + str_course);
                }

                else if (user_type == "FA")
                {
                    string inhabitation = "(";

                    inhabitation += "'" + dt_fa_dtl.Rows[0]["dept_code"].ToString().Trim() + "'";
                    for (int i = 1; i < dt_fa_dtl.Rows.Count; i++)
                        inhabitation += ",'" + dt_fa_dtl.Rows[i]["dept_code"].ToString().Trim() + "'";

                    inhabitation += ")";

