    [WebMethod(EnableSession = true)]
    public string WS_course_proposal_approve(string course_data)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> Course_Master_data = ser.Deserialize<Dictionary<string, object>>(course_data);

            //DataTable cur_sem = objmaster.Get_cept_current_sem_data("ws_course");

            if (Course_Master_data["course_code"].ToString().Trim() != "" && Course_Master_data["sem_code"].ToString().Trim() != "" && Course_Master_data["year_code"].ToString().Trim() != "")
            {
                DSC_ws_course_master ws_course_mst = new DSC_ws_course_master();
                DSC_ws_course_master.ws_course_proposalRow ws_course_mst_row = ws_course_mst.ws_course_proposal.Newws_course_proposalRow();

                DataTable dt_ws_course_data = objmaster.get_ws_course_proposal_data(Course_Master_data["course_code"].ToString(), Course_Master_data["sem_code"].ToString(), Course_Master_data["year_code"].ToString());

                if (dt_ws_course_data != null)
                {
                    ws_course_mst_row.ItemArray = dt_ws_course_data.Rows[0].ItemArray;

                    ws_course_mst_row.dean_approved = "A";
                }

                ws_course_mst.ws_course_proposal.Addws_course_proposalRow(ws_course_mst_row);

                //// // 

                objBLReturnObject = objMaster.save_ws_course_master_action(ws_course_mst, "2000", user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    return return_ajax_string("False", objBLReturnObject.ServerMessage);
                }
                else if (objBLReturnObject.ExecutionStatus == 1)
                {
                    bool status_mail = objmaster.send_mail_dean_pc_fa_department_wise(Course_Master_data["sem_code"].ToString().Trim(), Course_Master_data["year_code"].ToString(), Course_Master_data["course_code"].ToString().Trim());
                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
                    course_log_row.course_code = Course_Master_data["course_code"].ToString();
                    course_log_row.remark = "Course Proposal Approved";
                    course_log_row.created_by = user_id;
                    course_log_row.created_date = DateTime.Now;
                    course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                    course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                    BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                    Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                }
            }
            else
            {
                return return_ajax_string("False", "No Data to Approve");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("False", "Problem in update DATA.");
        }

        //return objBLReturnObject.ServerMessage;
        return return_ajax_string("True", objBLReturnObject.ServerMessage);

    }

