                    bool statusforsendforreview = objmaster.UpdateSendForReviewforCourseInfo(Course_Master_data["course_code"].ToString().Trim(), Course_Master_data["sem_code"].ToString().Trim(), Course_Master_data["year_code"].ToString().Trim());
