                        if (HttpContext.Current.Session["UserName"] != null && HttpContext.Current.Session["UserName"].ToString() != "")
                        {
                            Course_Master_data["user_name"] = HttpContext.Current.Session["UserName"].ToString();
                        }

                        else { Course_Master_data["user_name"] = ""; }


                        if (dt_ws_course_data.Rows[0]["inhabitation"].ToString() != "")
                        {
                            Course_Master_data["inhabitation"] = dt_ws_course_data.Rows[0]["inhabitation"].ToString();
                        }
                        else { Course_Master_data["inhabitation"] = ""; }

                        String[] res = objmail.Send_WS_course_proposal_sendforreview(Course_Master_data);

                        str_res = return_ajax_string(res[0], res[1]);
                    }
                    else
                    {
                        str_res = return_ajax_string("False", "User Detail not Found");
                    }

                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
