    [WebMethod(EnableSession = true)]
    public string update_ws_course_code(string changed_course_detail)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> Course_Master_data = ser.Deserialize<List<Dictionary<string, object>>>(changed_course_detail);

            DataTable dt_ws_course_data = objmaster.Get_ws_courseproposal_data(Course_Master_data[0]["sem_code"].ToString(), Course_Master_data[0]["year_code"].ToString());

            if (dt_ws_course_data != null)
            {
                DSC_ws_course_master ws_course_mst = new DSC_ws_course_master();

                for (int i = 0; i < Course_Master_data.Count; i++)
                {
                    if (Course_Master_data[i]["course_code"].ToString().Trim() != "" && Course_Master_data[i]["sem_code"].ToString().Trim() != "" && Course_Master_data[i]["year_code"].ToString().Trim() != "")
                    {
                        DataRow[] dr_ws_course_data = dt_ws_course_data.Select("course_code='" + Course_Master_data[i]["course_code"].ToString().Trim() + "'");

                        if (dr_ws_course_data.Length > 0)
                        {
                            DSC_ws_course_master.ws_course_proposalRow ws_course_mst_row = ws_course_mst.ws_course_proposal.Newws_course_proposalRow();

                            ws_course_mst_row.ItemArray = dr_ws_course_data[0].ItemArray;

                            ws_course_mst_row.ws_course_code = Course_Master_data[i]["ws_course_code"].ToString().Trim();

                            ws_course_mst_row.course_type = Course_Master_data[i]["course_type"].ToString().Trim();

                            ws_course_mst.ws_course_proposal.Addws_course_proposalRow(ws_course_mst_row);
                        }
                    }
                }

                //// // 

                objBLReturnObject = objMaster.save_ws_course_master_action(ws_course_mst, "2000", user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    return return_ajax_string("False", objBLReturnObject.ServerMessage);
                }
                else if (objBLReturnObject.ExecutionStatus == 1)
                {
                    bool changecoursecode = objmaster.Ws_changeCourseCodeWorkLoad(changed_course_detail, user_id, HttpContext.Current.Request.UserHostName, Course_Master_data[0]["sem_code"].ToString(), Course_Master_data[0]["year_code"].ToString());
                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();
                     
                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
                    course_log_row.course_code = Course_Master_data[0]["course_code"].ToString();
                    course_log_row.remark = "Course Code Changed to " + Course_Master_data[0]["ws_course_code"].ToString();
                    course_log_row.created_by = user_id;
                    course_log_row.created_date = DateTime.Now;
                    course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                    course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                    BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                    Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                }
            }
            else
            {
                return return_ajax_string("False", "No Data to Approve");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("False", "Problem in update DATA." + ex.ToString());
        }

        //return objBLReturnObject.ServerMessage;
        return return_ajax_string("True", objBLReturnObject.ServerMessage);

    }

    [WebMethod(EnableSession = true)]
    public string ws_publish_selected_courses(string publish_data, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        try
        {
            if (user_type == "WSA" || user_type == "A" || user_type == "A1")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                //List<string> lst_publish_data = ser.Deserialize<List<string>>(publish_data);
                List<Dictionary<string, object>> lst_publish_data = ser.Deserialize<List<Dictionary<string, object>>>(publish_data);

                DataTable dt_ws_course_data = objmaster.Get_ws_courseproposal_data(sem_code, year_code);

                if (lst_publish_data.Count > 0 && dt_ws_course_data != null)
                {
                    string str_publish_course_list = "";
                    string str_high_school_course = "";
                    string str_course_fees = "";
                    string str_update_workload = "";

                    for (int i = 0; i < lst_publish_data.Count; i++)
                    {
                        DataRow[] dr_course_data = dt_ws_course_data.Select("course_code='" + lst_publish_data[i]["course_code"] + "'");

                        if (dr_course_data.Length > 0)
                        {
                            if (dr_course_data[0]["dean_approved"].ToString() == "A" && dr_course_data[0]["ws_course_code"].ToString() != "")
                            {
                                if (i == 0)
                                    str_publish_course_list += "'" + lst_publish_data[i]["course_code"].ToString() + "'";
                                else
                                    str_publish_course_list += ",'" + lst_publish_data[i]["course_code"].ToString() + "'";

                                if (lst_publish_data[i]["course_type"].ToString() == "HS")
                                {
                                    if (str_high_school_course == "")
                                        str_high_school_course += "'" + lst_publish_data[i]["course_code"].ToString() + "'";
                                    else
                                        str_high_school_course += ",'" + lst_publish_data[i]["course_code"].ToString() + "'";
                                }

                                if (lst_publish_data[i]["course_fees"].ToString() != "")
                                {
                                    str_course_fees += @" 
                                                          update ws_course_mst set fees='" + lst_publish_data[i]["course_fees"].ToString() + "' " +
                                                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' " +
                                                        " and course_code in (select ws_course_code from ws_course_proposal " +
                                                        " where semester_type='" + sem_code + "' and year_semester='" + year_code + "' " +
                                                        " and course_code='" + lst_publish_data[i]["course_code"].ToString() + "') ";
                                }

                                str_update_workload += @" Update ws_instructor_workload_detail set course_code ='" + dr_course_data[0]["ws_course_code"].ToString() + @"',ws_course_code ='" + dr_course_data[0]["course_code"].ToString() + @"' 
                                                          where cancel_flag='N' and semester_type ='" + sem_code + "' and year_semester ='" + year_code + "' and course_code ='" + dr_course_data[0]["course_code"].ToString() + "'";
                            }
                        }
                    }

                    Dictionary<string, string> dic_response = objmaster.ws_publish_selected_courses(str_publish_course_list, str_high_school_course, str_course_fees, sem_code, year_code, user_id, str_update_workload);
                    return return_ajax_string(dic_response["status"], dic_response["message"]);
                }
                else
                {
                    return return_ajax_string("False", "No Data Found to Publish Course");
                }
            }
            else
            {
                return return_ajax_string("False", "You are not Authorized to Publish Course");
            }
        }
        catch (Exception e)
        {
            return return_ajax_string("False", e.Message.ToString());
        }
        return return_ajax_string("False", "Unable Publish Course");
    }

