        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        try
        {
            if (user_type == "WSA" || user_type == "A" || user_type == "A1")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                List<Dictionary<string, object>> lst_publish_data = ser.Deserialize<List<Dictionary<string, object>>>(publish_data);

                DataTable dt_ws_course_data = objmaster.Get_ws_courseproposal_data(sem_code, year_code);

                if (lst_publish_data.Count > 0 && dt_ws_course_data != null)
                {
                    string str_publish_course_list = "";

                    for (int i = 0; i < lst_publish_data.Count; i++)
                    {
                        DataRow[] dr_course_data = dt_ws_course_data.Select("ws_course_code='" + lst_publish_data[i]["course_code"].ToString() + "'");

