    [WebMethod(EnableSession = true)]
    public string save_credit_detail_year_wise(string credit_data)
    {
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> dict_credit_data = ser.Deserialize<Dictionary<string, object>>(credit_data);

            DSC_CreditsDetail obj_credit_detail = new DSC_CreditsDetail();

            DSC_CreditsDetail.credits_detail_year_wiseRow row = obj_credit_detail.credits_detail_year_wise.Newcredits_detail_year_wiseRow();

            row.year_code = dict_credit_data["year_code"].ToString();
            row.dept_code = dict_credit_data["dept_code"].ToString();
            row.prog_code = dict_credit_data["prog_code"].ToString();
            row.prog_level_code = dict_credit_data["prog_level_code"].ToString();
            row.total_credits = Int32.Parse(dict_credit_data["total_credits"].ToString());
            row.mandatory_credits = Int32.Parse(dict_credit_data["mandatory_credits"].ToString());
            row.elective_credits = Int32.Parse(dict_credit_data["elective_credits"].ToString());
            row.sws_credits = Int32.Parse(dict_credit_data["sws_credits"].ToString());
            row.cancel_flag = "N";
            row.created_by = HttpContext.Current.Session["UserId"].ToString();
            row.created_date = DateTime.Now;
            row.created_host = HttpContext.Current.Request.UserHostName;

            obj_credit_detail.credits_detail_year_wise.Addcredits_detail_year_wiseRow(row);

            objBLReturnObject = objmaster.save_credit_detail_year_wise(obj_credit_detail, "2000", "", HttpContext.Current.Request.UserHostName, dict_credit_data);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                objBLReturnObject.ServerMessage = "Data Saved Successfully";
            }
        }
        catch (Exception ex)
        {
            objBLReturnObject.ServerMessage = "Problem in update data";
        }

        return objBLReturnObject.ServerMessage;
    }

