        {
            a.Add(GetJson1(dt_earned_credits_dtl_foundation));
        }

        //Total allocated and earned current Sem - allocated_credits_cur_sem_details
        //DataTable dt_allocated_credits_dtl_cur_sem_year = objmaster.get_allocated_credits_dtl_cur_sem_year(user_id, current_ws_sem, current_ws_year);
        DataTable dt_allocated_credits_dtl_cur_sem_year = objmaster.get_allocated_credits_dtl_cur_sem_year_new(user_id, current_ws_sem, current_ws_year);

        if (dt_allocated_credits_dtl_cur_sem_year != null)
        {
            a.Add(GetJson1(dt_allocated_credits_dtl_cur_sem_year));
        }

        //Total allocated and earned current Sem - Logic Implemented of Feedback - earned_credits_cur_sem_details
        //DataTable dt_earned_credits_dtl_cur_sem_year = objmaster.get_earned_credits_dtl_cur_sem_year(user_id, current_ws_sem, current_ws_year);
        DataTable dt_earned_credits_dtl_cur_sem_year = objmaster.get_earned_credits_dtl_cur_sem_year_new(user_id, current_ws_sem, current_ws_year);

        if (dt_earned_credits_dtl_cur_sem_year != null)
        {
            a.Add(GetJson1(dt_earned_credits_dtl_cur_sem_year));
        }

        jsondata = "{\"other_sem_credits_detail\":" + a[0] + ",\"sem1_sem2_credits_details\":" + a[1] + ",\"allocated_credits_cur_sem_details\":" + a[2] + ",\"earned_credits_cur_sem_details\":" + a[3] + "}";

        return "{\"status\":\"true\",\"message\":" + jsondata + "}";
    }

