            if (registration_data.Count > 0)
            {
                ArrayList team_member_data_list = (ArrayList)registration_data["teamd_data"];

                DSC_BTG_Registration btg_registration_add = new DSC_BTG_Registration();
                DSC_BTG_Registration ref_objCourseMaster_upload = new DSC_BTG_Registration();

                DSC_BTG_Registration.BTG_payment_dtlRow BTG_payment_dtl_row = btg_registration_add.BTG_payment_dtl.NewBTG_payment_dtlRow();

                BTG_payment_dtl_row.transaction_id = "1";
