                BTG_payment_dtl_row.status_is_payment_received = "N";

                BTG_payment_dtl_row.created_by = ((Dictionary<string, object>)team_member_data_list[0])["name"].ToString();
                BTG_payment_dtl_row.created_date = DateTime.Now;
                BTG_payment_dtl_row.created_host = HttpContext.Current.Request.UserHostName;

                //course_master_upload.course_wise_time.Addcourse_wise_timeRow(course_wise_time_row);
                btg_registration_add.BTG_payment_dtl.AddBTG_payment_dtlRow(BTG_payment_dtl_row);
                if (team_member_data_list.Count > 0)
                {
                    for (int i = 0; i < team_member_data_list.Count; i++)
                    {
                        Dictionary<string, object> data = (Dictionary<string, object>)team_member_data_list[i];
                        DSC_BTG_Registration.BTG_team_member_dtlRow BTG_team_member_dtl_row = btg_registration_add.BTG_team_member_dtl.NewBTG_team_member_dtlRow();

                        BTG_team_member_dtl_row.transaction_id = "1";
                        BTG_team_member_dtl_row.sr_no = data["sr_no"].ToString();
                        BTG_team_member_dtl_row.name = data["name"].ToString();
                        BTG_team_member_dtl_row.email_id = data["email_id"].ToString();
                        BTG_team_member_dtl_row.mobile_no = data["mobile_no"].ToString();
                        BTG_team_member_dtl_row.college = data["college"].ToString();
                        BTG_team_member_dtl_row.department = data["department"].ToString();
                        BTG_team_member_dtl_row.year = data["year"].ToString();
                        BTG_team_member_dtl_row.cancel_flag = "N";
                        BTG_team_member_dtl_row.created_by = ((Dictionary<string, object>)team_member_data_list[0])["name"].ToString();
                        BTG_team_member_dtl_row.created_date = DateTime.Now;
                        BTG_team_member_dtl_row.created_host = HttpContext.Current.Request.UserHostName;

                        btg_registration_add.BTG_team_member_dtl.AddBTG_team_member_dtlRow(BTG_team_member_dtl_row);
                    }
                }

                objBLReturnObject = objmaster.save_btg_registration_data(btg_registration_add, "2000", "", HttpContext.Current.Request.UserHostName, ref ref_objCourseMaster_upload);

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                }
                else if (objBLReturnObject.ExecutionStatus == 1)
                {
                    if (ref_objCourseMaster_upload.BTG_payment_dtl.Rows[0]["amount"].ToString() != "0")
                    {
                        string message = "";
                        string transaction_id = "";
                        string user_id = "";
                        string dept_code = "5";
                        string current_sem_code = "";
                        string trans_code = "";
                        Payment objPayment = new Payment();
                        Dictionary<string, object> param = new Dictionary<string, object>();
                        Dictionary<string, object> obj_data = new Dictionary<string, object>();

                        //bool result = objPayment.SID_RedirectToPaymentGateway(param, ref message, user_id, amount, current_sem_code, current_ws_sem, current_ws_year, dept_code, trans_code, ref transaction_id);
                        bool result = true;

                        string MerchantId = Payment.GetMerchantId(dept_code);

                        string hmac_url = Payment.Get_hmac_url(dept_code);

                        //string return_url = Payment.Get_return_url(dept_code);
                        string return_url = "PaymentResponseNetBankingTechnology.aspx";

                        //string base_url = "http://registration.cept.ac.in/ceptreg/Student/";

                        //string base_url = "http://122.170.103.168/cept/Student/";

                        string str_path = "";
                        if (HttpContext.Current.Request.Url.Segments.Length == 3)
                        {
                            str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + "BTG/";
                        }
                        else if (HttpContext.Current.Request.Url.Segments.Length == 4)
                        {
                            str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1] + "BTG/";
                        }

                        string base_url = "https://" + str_path;

                        obj_data["status"] = result;
                        obj_data["message"] = message;
                        obj_data["user_id"] = ref_objCourseMaster_upload.BTG_payment_dtl.Rows[0]["user_id"];

                        obj_data["amount"] = ref_objCourseMaster_upload.BTG_payment_dtl.Rows[0]["amount"];
                        //obj_data["amount"] = 0;

                        obj_data["transaction_id"] = ref_objCourseMaster_upload.BTG_payment_dtl.Rows[0]["transaction_id"];
                        obj_data["merchant_id"] = MerchantId;
                        obj_data["currency"] = "INR";
                        obj_data["hmac_url"] = hmac_url;
                        obj_data["return_url"] = base_url + return_url;

                        return JsonConvert.SerializeObject(obj_data);

                        //return ser.Serialize(obj_data);
                    }
                    else
                    {
                        Dictionary<string, object> obj_data = new Dictionary<string, object>();

                        obj_data["status"] = false;
                        obj_data["message"] = "Problem in Payment Redirection, Please try again.";

                        return JsonConvert.SerializeObject(obj_data);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in Registration.";
        }

        return objBLReturnObject.ServerMessage;
    }

