        DataTable vising_faculty_data = objmaster.get_vf_personal_detail(sem_code, year_code, user_id, prog_code, prog_level_code);

        DataTable vf_other_dept_data = objmaster.get_vf_other_dept_detail(sem_code, year_code, user_id);

        string dept_code = "";
        if (user_detail != null) dept_code = user_detail.Rows[0]["dept_code"].ToString();

        if (vising_faculty_data != null)
        {
            vising_faculty_data.Columns.Add("other_dept");

            try
            {
                if (dept_code != "")
                {
                    for (int i = 0; i < vising_faculty_data.Rows.Count; i++)
                    {
                        string other_dept = "";

                        DataRow[] dr = vf_other_dept_data.Select("instructor_code='" + vising_faculty_data.Rows[i]["instructor_code"] + "' and dept_code not in ('" + dept_code + "')");

                        if (dr.Length > 0)
                        {
                            for (int j = 0; j < dr.Length; j++)
                            {
                                if (j == 0) other_dept = other_dept + dr[j]["dept_name"].ToString();
                                else other_dept = other_dept + " , " + dr[j]["dept_name"].ToString();
                            }
                        }

                        vising_faculty_data.Rows[i]["other_dept"] = other_dept;
                    }
                }
            }
            catch (Exception ex)
            {
            }

            jsondata = GetJson1(vising_faculty_data);
        }
        return jsondata;
    }

