    [WebMethod(EnableSession = true)]
    public string get_vf_rate_band_detail(string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)
    {
        try
        {
            var user_id = HttpContext.Current.Session["UserId"].ToString();
            var user_type = HttpContext.Current.Session["user_type"].ToString();
            //DataTable vising_faculty_data = objmaster.get_vf_rate_band_detail(sem_code, year_code, user_id, prog_code, prog_level_code, dept_code);
            DataTable vising_faculty_data = objmaster.get_vf_rate_band_detail_new(sem_code, year_code, user_id, prog_code, prog_level_code, dept_code);
            //Publish Letter
            string semester = "";
            if (sem_code == "S")
            {
                semester = "Spring";
            }
            else
            {
                semester = "Monsoon";
            }

            if (vising_faculty_data != null)
            {
                String path = Server.MapPath("~/LetterPDF");
                vising_faculty_data.Columns.Add("pdf_status").ToString();
                for (int k = 0; k < vising_faculty_data.Rows.Count; k++)
                {
                    String File_Name = vising_faculty_data.Rows[k]["instructor_code"].ToString() + "_" + vising_faculty_data.Rows[k]["instructor_name"].ToString().Replace(" ", "_") + "_" + vising_faculty_data.Rows[k]["dept_name"].ToString().Replace(" ", "_") + "_" + semester + "_" + year_code + ".pdf";
                    File_Name = File_Name.Replace(" ", "");
                    if (File.Exists(path + "\\" + File_Name))
                    {
                        vising_faculty_data.Rows[k]["pdf_status"] = "Y";
                    }
                    else
                    {
                        vising_faculty_data.Rows[k]["pdf_status"] = "N";
                    }
                }


                jsondata = GetJson1(vising_faculty_data);
            }
            return jsondata;
        }
        catch (Exception ex)
        {
            return "";
            //throw;
        }
    }

    [WebMethod(EnableSession = true)]
    public string get_authorize_detail(string sem_code, string year_code, string dept_code, string prog_code, string prog_level_code, string instructor_type)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        var user_typee = user_type;

        if (instructor_type == "") instructor_type = "-";

        DataTable vising_faculty_data = objmaster.get_authorize_detail(sem_code, year_code, user_id, user_typee + '|' + instructor_type, dept_code, prog_code, prog_level_code);

        try
        {
            if (vising_faculty_data != null)
            {
                if (user_type == "AC" || user_type == "F")
                {
                    vising_faculty_data = vising_faculty_data.Select("hr_approved='Y'").CopyToDataTable();
                }

                vising_faculty_data.Columns.Add("total_amount_paid");

                for (int i = 0; i < vising_faculty_data.Rows.Count; i++)
                {
                    if (vising_faculty_data.Rows[i]["rate_band"].ToString() != "" && vising_faculty_data.Rows[i]["total_hrs_in_semester"].ToString() != "")
                    {
                        vising_faculty_data.Rows[i]["total_amount_paid"] = (Convert.ToDouble(vising_faculty_data.Rows[i]["rate_band"].ToString()) * Convert.ToDouble(vising_faculty_data.Rows[i]["total_hrs_in_semester"].ToString())).ToString();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            vising_faculty_data = null;
        }

        if (vising_faculty_data != null)
        {
            jsondata = GetJson1(vising_faculty_data);
        }
        return jsondata;
    }



