    [WebMethod(EnableSession = true)]
    public string save_acceptance_detail(string sem_code, string year_code, string All_table_course_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        try
        {
            if (user_type == "FA")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                ArrayList All_Instructor_data = ser.Deserialize<ArrayList>(All_table_course_data);

                ArrayList instructor_data = (ArrayList)All_Instructor_data[0];
                string action = (string)All_Instructor_data[1];

                DataTable dt_workload_dtl = objmaster.Get_Workload_for_acceptance(sem_code, year_code, user_id, user_type);
                if (dt_workload_dtl != null)
                {
                    DSC_VF_Mgmt instructor_workload_upload = new DSC_VF_Mgmt();

                    for (int i = 0; i < instructor_data.Count; i++)
                    {
                        Dictionary<string, object> dic_instructor_data = (Dictionary<string, object>)instructor_data[i];

                        //DataRow[] dr = dt_workload_dtl.Select("instructor_code = '" + dic_instructor_data["instructor_code"].ToString() + "' and course_code = '" + dic_instructor_data["course_code"].ToString() + "'");
                        DataRow[] dr = dt_workload_dtl.Select("instructor_code = '" + dic_instructor_data["instructor_code"].ToString() + "' and course_code = '" + dic_instructor_data["course_code"].ToString() + "' and is_tutorial='" + dic_instructor_data["is_tutorial"].ToString() + "'");

                        if (dr.Length > 0)
                        {
                            if (dr[0]["hr_approved"].ToString() == "Y")
                            {
                                dr[0]["acceptance"] = dic_instructor_data["acceptance"].ToString();
                                dr[0]["acceptance_justification"] = dic_instructor_data["acceptance_justification"].ToString();
                                dr[0]["acceptance_type"] = dic_instructor_data["acceptance_type"].ToString();

                                DateTime acceptance_date = new DateTime();
                                if (DateTime.TryParse(dic_instructor_data["acceptance_date"].ToString(), out acceptance_date))
                                {
                                    dr[0]["acceptance_date"] = acceptance_date;
                                }
                                else
                                {
                                    dr[0]["acceptance_date"] = DateTime.Now;//System.DBNull.Value;
                                }

                                dr[0]["last_modified_by"] = user_id;
                                //dr[0]["last_modified_date"] = DateTime.Now;
                                dr[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                                instructor_workload_upload.instructor_workload_detail.ImportRow(dr[0]);
                            }
                        }
                    }

                    objBLReturnObject = objMaster.save_instructor_workload_data(instructor_workload_upload, user_type, user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        objBLReturnObject.ServerMessage = "Data Saved Successfully";
                    }

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                    else //if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        DSC_Course_Log course_log = new DSC_Course_Log();

                        DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                        course_log_row.log_id = "1";
                        course_log_row.user_id = user_id;
                        course_log_row.course_code = dt_workload_dtl.Rows[0]["course_code"].ToString();
                        course_log_row.remark = "Modify Workload";
                        course_log_row.created_by = user_id;
                        course_log_row.created_date = DateTime.Now;
                        course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                        course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                        BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                        Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA." + ex.ToString();
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }

