                    DataRow[] dr = vf_other_dept_data.Select("instructor_code='" + vising_faculty_data.Rows[i]["instructor_code"] + "'");

                    if (dr.Length > 0)
                    {
                        for (int j = 0; j < dr.Length; j++)
