    public string studio_log_create(string user_id, string activity_type, string activity_description, string activity_action_name, string created_by_user_id, string studio_code, string course_code)
    {
        DataTable dt = new DataTable();
        if (activity_type == "Studio")
        {
            dt = objmaster.Get_cept_current_sem_data("call_for_studio");
        }
        else if (activity_type == "StudioProposal")
        {
            dt = objmaster.Get_cept_current_sem_data("call_for_studio");
        }
        else if (activity_type == "TAApplication")
        {
            dt = objmaster.Get_cept_current_sem_data("TA Application");
        }

        DSC_Course_Log course_log = new DSC_Course_Log();
        DSC_Course_Log.studio_activity_logRow studio_activity_log_row = course_log.studio_activity_log.Newstudio_activity_logRow();
        studio_activity_log_row.log_id = "1";
        studio_activity_log_row.user_id = user_id;
        studio_activity_log_row.activity_type = activity_type;
        studio_activity_log_row.activity_description = activity_description;
        studio_activity_log_row.activity_action_name = activity_action_name;
        studio_activity_log_row.created_by = created_by_user_id;
        if (studio_code != "")
        {
            studio_activity_log_row.studio_code = studio_code;
        }
        if (course_code != "")
        {
            studio_activity_log_row.course_code = course_code;
        }
        studio_activity_log_row.created_date = DateTime.Now;
        studio_activity_log_row.created_host = HttpContext.Current.Request.UserHostName;
        if (dt != null)
        {
            studio_activity_log_row.semester_type = dt.Rows[0]["sem_code"].ToString();
            studio_activity_log_row.year_semester = dt.Rows[0]["year_code"].ToString();
        }


        course_log.studio_activity_log.Addstudio_activity_logRow(studio_activity_log_row);
        BLReturnObject Log_objBLReturnObject = new BLReturnObject();

        Log_objBLReturnObject = objmaster.add_studio_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);

        return "true";
    }

