    [WebMethod(EnableSession = true)]
    public string sws_save_instructor_data(string All_table_course_data)
    {


        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            ArrayList All_Instructor_data = ser.Deserialize<ArrayList>(All_table_course_data);

            Dictionary<string, object> instructor_data = (Dictionary<string, object>)All_Instructor_data[0];
            ArrayList reference_dtl = (ArrayList)All_Instructor_data[1];
            ArrayList education_dtl = (ArrayList)All_Instructor_data[2];
            ArrayList work_dtl = (ArrayList)All_Instructor_data[3];
            string action = (string)All_Instructor_data[4];

            DataTable dt_instructor = objmaster.get_instructor_data(instructor_data["instructor_code"].ToString());
            //changes 02102021
            DataTable dt_rate_band_range = objmaster.calculate_rate_band(instructor_data["highest_qualification"].ToString(), instructor_data["total_experiance"].ToString());

            DSC_VF_Mgmt instructor_master_upload = new DSC_VF_Mgmt();

            DSC_VF_Mgmt.instructor_mstRow instructor_mst_row = instructor_master_upload.instructor_mst.Newinstructor_mstRow();

            instructor_mst_row.doc_no = dt_instructor.Rows[0]["doc_no"].ToString();
            instructor_mst_row.instructor_code = instructor_data["instructor_code"].ToString();
            instructor_mst_row.user_id = dt_instructor.Rows[0]["user_id"].ToString();
            instructor_mst_row.VF_code = instructor_data["VF_code"].ToString();
            instructor_mst_row.instructor_name = instructor_data["first_name"].ToString() + " " + instructor_data["last_name"].ToString();
            instructor_mst_row.title = instructor_data["title"].ToString();
            //instructor_mst_row.first_name = instructor_data["first_name"].ToString();
            instructor_mst_row.first_name = instructor_data["first_name"].ToString().First().ToString().ToUpper() + instructor_data["first_name"].ToString().Substring(1);
            //instructor_mst_row.last_name = instructor_data["last_name"].ToString();
            instructor_mst_row.last_name = instructor_data["last_name"].ToString().First().ToString().ToUpper() + instructor_data["last_name"].ToString().Substring(1);
            instructor_mst_row.designation = dt_instructor.Rows[0]["designation"].ToString();
            instructor_mst_row.mail = instructor_data["mail"].ToString();

            instructor_mst_row.admin_approved = dt_instructor.Rows[0]["admin_approved"].ToString();
            instructor_mst_row.rateband_approved = dt_instructor.Rows[0]["rateband_approved"].ToString();
            instructor_mst_row.hr_approved = dt_instructor.Rows[0]["hr_approved"].ToString();

            instructor_mst_row.mobile_no = instructor_data["mobile_no"].ToString();
            instructor_mst_row.phone_no = instructor_data["phone_no"].ToString();
            instructor_mst_row.blood_group = instructor_data["blood_group"].ToString();
            instructor_mst_row.pan_card_no = instructor_data["pan_card_no"].ToString();
            instructor_mst_row.bank_account_number = instructor_data["bank_account_number"].ToString();
            instructor_mst_row.account_type = instructor_data["account_type"].ToString();
            instructor_mst_row.name_of_Bank = instructor_data["name_of_Bank"].ToString();
            instructor_mst_row.branch_name = instructor_data["branch_name"].ToString();
            instructor_mst_row.ifsc_code = instructor_data["ifsc_code"].ToString();
            instructor_mst_row.benificiary_name = instructor_data["benificiary_name"].ToString();

            if (instructor_data["dob"].ToString() != "") instructor_mst_row.dob = Convert.ToDateTime(instructor_data["dob"].ToString());

            instructor_mst_row.highest_qualification = instructor_data["highest_qualification"].ToString();
            instructor_mst_row.total_experiance = instructor_data["total_experiance"].ToString();
