                //else
                //{
                //    instructor_mst_row.rate_wise_designation = dt_instructor.Rows[0]["rate_wise_designation"].ToString();
                //}
            }

            instructor_mst_row.associated_with_cept_since = instructor_data["associated_with_cept_since"].ToString();
            instructor_mst_row.address = instructor_data["address"].ToString();
            instructor_mst_row.emergency_contact_name = instructor_data["emergency_contact_name"].ToString();
            instructor_mst_row.emergency_contact_number = instructor_data["emergency_contact_number"].ToString();



            // add city state country 18022021
            instructor_mst_row.city = instructor_data["city"].ToString();
            instructor_mst_row.state = instructor_data["state"].ToString();
            instructor_mst_row.country = instructor_data["country"].ToString();
