            //instructor_mst_row.degree = instructor_data["degree"].ToString();
            //instructor_mst_row.specialization = instructor_data["specialization"].ToString();
            //instructor_mst_row.university = instructor_data["university"].ToString();

            //if (instructor_data["date_of_issuance_certificate"].ToString() != "") instructor_mst_row.date_of_issuance_certificate = Convert.ToDateTime(instructor_data["date_of_issuance_certificate"].ToString());

            //instructor_mst_row.work_designation = instructor_data["work_designation"].ToString();
            //instructor_mst_row.work_institute = instructor_data["work_institute"].ToString();

            //if (instructor_data["work_start_date"].ToString() != "") instructor_mst_row.work_start_date = Convert.ToDateTime(instructor_data["work_start_date"].ToString());

            //if (instructor_data["work_end_date"].ToString() != "") instructor_mst_row.work_end_date = Convert.ToDateTime(instructor_data["work_end_date"].ToString());

            instructor_mst_row.achievements = instructor_data["achievements"].ToString();
            instructor_mst_row.area_of_interest = instructor_data["area_of_interest"].ToString();

            instructor_mst_row.cv_file_name = instructor_data["cv_file_name"].ToString();

            instructor_mst_row.cancel_flag = "N";
