                instructor_mst_row.admin_approved = "Y";
                instructor_mst_row.rateband_approved = "Y";
                instructor_mst_row.hr_approved = "N";
            }

            if (action == "S" && user_type == "FA")
            {
                //Changes BY Nitinbhai 02012024
                if (dt_instructor.Rows[0]["admin_approved"].ToString() == "Y")
                {
                    instructor_mst_row.admin_approved = "Y";
                    instructor_mst_row.rateband_approved = "Y";
                    instructor_mst_row.hr_approved = "N";
                }
                else
                {
                    instructor_mst_row.admin_approved = "N";
                    instructor_mst_row.rateband_approved = "N";
                    instructor_mst_row.hr_approved = "N";
                }

            }

            DataTable dt = new DataTable();
