            if (reference_dtl.Count > 0)
            {
                for (int i = 0; i < reference_dtl.Count; i++)
                {
                    Dictionary<string, object> dic_reference_dtl = (Dictionary<string, object>)reference_dtl[i];
                    DSC_VF_Mgmt.instructor_academic_work_dtlRow instructor_academic_work_row = instructor_master_upload.instructor_academic_work_dtl.Newinstructor_academic_work_dtlRow();

                    instructor_academic_work_row.instructor_code = instructor_data["instructor_code"].ToString();
                    instructor_academic_work_row.detail_type = "reference";
                    instructor_academic_work_row.sr_no = dic_reference_dtl["sr_no"].ToString();
