                    instructor_academic_work_row.created_by = user_id;
                    instructor_academic_work_row.created_date = DateTime.Now;
                    instructor_academic_work_row.created_host = HttpContext.Current.Request.UserHostName;

                    instructor_master_upload.instructor_academic_work_dtl.Addinstructor_academic_work_dtlRow(instructor_academic_work_row);
                }
            }

            if (education_dtl.Count > 0)
            {
                DataTable dataTable = new DataTable();
                dataTable = objmaster.get_instructor_academic_detail_sr_no_wise(instructor_data["instructor_code"].ToString(), "education");

                for (int i = 0; i < education_dtl.Count; i++)
                {
                    Dictionary<string, object> dic_education_dtl = (Dictionary<string, object>)education_dtl[i];
                    DSC_VF_Mgmt.instructor_academic_work_dtlRow instructor_academic_work_row = instructor_master_upload.instructor_academic_work_dtl.Newinstructor_academic_work_dtlRow();

                    instructor_academic_work_row.instructor_code = instructor_data["instructor_code"].ToString();
                    instructor_academic_work_row.detail_type = "education";
                    instructor_academic_work_row.sr_no = dic_education_dtl["sr_no"].ToString();
                    instructor_academic_work_row.degree = dic_education_dtl["degree"].ToString();
                    instructor_academic_work_row.specialization = dic_education_dtl["specialization"].ToString();
                    instructor_academic_work_row.university = dic_education_dtl["university"].ToString();

