                    if (dic_education_dtl["date_of_issuance_certificate"].ToString() != "") instructor_academic_work_row.date_of_issuance_certificate = Convert.ToDateTime(dic_education_dtl["date_of_issuance_certificate"].ToString());

                    instructor_academic_work_row.cancel_flag = "N";

                    instructor_academic_work_row.created_by = user_id;
                    instructor_academic_work_row.created_date = DateTime.Now;
                    instructor_academic_work_row.created_host = HttpContext.Current.Request.UserHostName;
                    if (dataTable != null)
                    {
                        int k = i + 1;
                        DataRow[] dr = dataTable.Select("sr_no = '" + Convert.ToString(k) + "'");
                        if (dr.Length > 0)
                        {
                            instructor_academic_work_row.edu_start_date = dr[0]["edu_start_date"].ToString();
                            instructor_academic_work_row.edu_end_date = dr[0]["edu_end_date"].ToString();
                            instructor_academic_work_row.edu_percentage = dr[0]["edu_percentage"].ToString();
                            instructor_academic_work_row.edu_mode = dr[0]["edu_mode"].ToString();
                            instructor_academic_work_row.edu_type = dr[0]["edu_type"].ToString();
                            instructor_academic_work_row.program_code = dr[0]["program_code"].ToString();



                        }


                    }

                    instructor_master_upload.instructor_academic_work_dtl.Addinstructor_academic_work_dtlRow(instructor_academic_work_row);
                }
            }

            if (work_dtl.Count > 0)
            {
                DataTable dataTable_ = new DataTable();
                dataTable_ = objmaster.get_instructor_academic_detail_sr_no_wise(instructor_data["instructor_code"].ToString(), "work");
                for (int i = 0; i < work_dtl.Count; i++)
                {
                    Dictionary<string, object> dic_work_dtl = (Dictionary<string, object>)work_dtl[i];
                    DSC_VF_Mgmt.instructor_academic_work_dtlRow instructor_academic_work_row = instructor_master_upload.instructor_academic_work_dtl.Newinstructor_academic_work_dtlRow();

                    instructor_academic_work_row.instructor_code = instructor_data["instructor_code"].ToString();
                    instructor_academic_work_row.detail_type = "work";
