                    instructor_academic_work_row.work_experience_type = dic_work_dtl["work_experience_type"].ToString();
                    instructor_academic_work_row.work_experience_months = dic_work_dtl["work_experience_months"].ToString();

                    //instructor_academic_work_row.work_start_date = Convert.ToDateTime(dic_work_dtl["work_start_date"].ToString());
                    if (dic_work_dtl["work_start_date"].ToString() != "") instructor_academic_work_row.work_start_date = Convert.ToDateTime(dic_work_dtl["work_start_date"].ToString());

                    //instructor_academic_work_row.work_end_date = Convert.ToDateTime(dic_work_dtl["work_end_date"].ToString());
                    if (dic_work_dtl["work_end_date"].ToString() != "") instructor_academic_work_row.work_end_date = Convert.ToDateTime(dic_work_dtl["work_end_date"].ToString());

                    instructor_academic_work_row.cancel_flag = "N";

                    instructor_academic_work_row.created_by = user_id;
                    instructor_academic_work_row.created_date = DateTime.Now;
                    instructor_academic_work_row.created_host = HttpContext.Current.Request.UserHostName;


                    if (dataTable_ != null)
                    {
                        //work_experience_year,work_experience_month
                        int k = i + 1;
                        DataRow[] dr1 = dataTable_.Select("sr_no = '" + Convert.ToString(k) + "'");
                        if (dr1.Length > 0)
                        {
                            instructor_academic_work_row.work_mode = dr1[0]["work_mode"].ToString();
                            instructor_academic_work_row.work_week_per_hours = dr1[0]["work_week_per_hours"].ToString();
                            instructor_academic_work_row.work_experience_cert = dr1[0]["work_experience_cert"].ToString();
                            instructor_academic_work_row.work_year_month = dr1[0]["work_year_month"].ToString();

                        }


                    }

                    instructor_master_upload.instructor_academic_work_dtl.Addinstructor_academic_work_dtlRow(instructor_academic_work_row);
                }
            }

            string str_img_update = "";
            if (dt_instructor.Rows[0]["user_id"].ToString() != "")
            {
                str_img_update = " update user_mst set profile_photo='" + instructor_data["image_path"].ToString() + "' where user_id='" + dt_instructor.Rows[0]["user_id"].ToString() + "' ";
            }

            objBLReturnObject = objMaster.save_instructor_data(instructor_master_upload, user_type, user_id, HttpContext.Current.Request.UserHostName, str_img_update);

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                //if (action == "A" && user_type == "FA")
                //{
                //    DataTable dt_instructor_submit_dtl = objMaster.get_instructor_submit_detail();
                //}
            }

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else //if (objBLReturnObject.ExecutionStatus == 1)
            {
                DSC_Course_Log course_log = new DSC_Course_Log();

                DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                course_log_row.log_id = "1";
                course_log_row.user_id = user_id;
                course_log_row.course_code = instructor_data["instructor_code"].ToString();
                course_log_row.remark = "Modify Instructor";
                course_log_row.created_by = user_id;
                course_log_row.created_date = DateTime.Now;
                course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }

        }
        catch (Exception ex)
        {
            return "Please Check Your Form Fill Data.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";



    }


