    [WebMethod(EnableSession = true)]
    public string get_vf_workload_detail(string sem_code, string year_code, string prog_code, string prog_level_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable dt_course_wise_instructor = objmaster.get_vf_workload_detail(sem_code, year_code, user_id, prog_code, prog_level_code, user_type);

        DataTable vising_faculty_data = null;

        if (dt_course_wise_instructor != null)
        {
            vising_faculty_data = dt_course_wise_instructor.Clone();

            var course_code = "";
            var instructor_code = "";
            var instructor_name = "";

            if (dt_course_wise_instructor.Rows.Count > 0)
            {
                course_code = dt_course_wise_instructor.Rows[0]["course_code"].ToString();
            }

            for (int i = 0; i < dt_course_wise_instructor.Rows.Count; i++)
            {
                if (dt_course_wise_instructor.Rows[i]["course_code"].ToString() == course_code)
                {
                    //instructor_code = instructor_code + dt_course_wise_instructor.Rows[i]["instructor_code"].ToString() + ", ";
                    instructor_code = instructor_code + dt_course_wise_instructor.Rows[i]["VF_code"].ToString() + ", ";

                    instructor_name = instructor_name + dt_course_wise_instructor.Rows[i]["instructor_name"].ToString() + ", ";
                }
                else
                {
                    DataRow dr = vising_faculty_data.NewRow();

                    dr["course_code"] = dt_course_wise_instructor.Rows[i - 1]["course_code"].ToString();
                    dr["course_name"] = dt_course_wise_instructor.Rows[i - 1]["course_name"].ToString();
                    if (instructor_code.Contains(",")) dr["instructor_code"] = instructor_code.Substring(0, instructor_code.Length - 2);
                    if (instructor_name.Contains(",")) dr["instructor_name"] = instructor_name.Substring(0, instructor_name.Length - 2);

                    vising_faculty_data.Rows.Add(dr);

                    course_code = dt_course_wise_instructor.Rows[i]["course_code"].ToString();
                    instructor_code = "";
                    instructor_name = "";
                    i--;
                }
            }

            if (dt_course_wise_instructor.Rows.Count > 0)
            {
                DataRow dr = vising_faculty_data.NewRow();

                dr["course_code"] = dt_course_wise_instructor.Rows[dt_course_wise_instructor.Rows.Count - 1]["course_code"].ToString();
                dr["course_name"] = dt_course_wise_instructor.Rows[dt_course_wise_instructor.Rows.Count - 1]["course_name"].ToString();
                if (instructor_code.Contains(",")) dr["instructor_code"] = instructor_code.Substring(0, instructor_code.Length - 2);
                if (instructor_name.Contains(",")) dr["instructor_name"] = instructor_name.Substring(0, instructor_name.Length - 2);

                vising_faculty_data.Rows.Add(dr);
            }
        }

        if (vising_faculty_data != null)
        {
            jsondata = GetJson1(vising_faculty_data);
        }
        return jsondata;
    }


    [WebMethod(EnableSession = true)]
    public string get_vf_course_wise_workload_detail(string course_code, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable dt_course_wise_instructor = objmaster.Get_CourseWiseInstructor_data(course_code, sem_code, year_code);

        DataTable instructor_workload_data = objmaster.get_vf_course_wise_workload_detail(course_code, sem_code, year_code);

        if (dt_course_wise_instructor != null)
        {
            try
            {
                DSC_VF_Mgmt instructor_workload_upload = new DSC_VF_Mgmt();

                if (instructor_workload_data == null)
                {
                    instructor_workload_data = objmaster.get_vf_course_wise_workload_detail(course_code, sem_code, year_code);

                    if (instructor_workload_data == null)
                    {
                        for (int i = 0; i < dt_course_wise_instructor.Rows.Count; i++)
                        {
                            double credits = 0, contact_hr_credit = 0, prep_hr_per_week = 0, percent_load = 0, total_contact_hrs = 0;

                            if (dt_course_wise_instructor.Rows[i]["course_credits"].ToString() != "") credits = Convert.ToDouble(dt_course_wise_instructor.Rows[i]["course_credits"].ToString());

                            if (dt_course_wise_instructor.Rows[i]["contact_hr_credit"].ToString() != "") contact_hr_credit = Convert.ToDouble(dt_course_wise_instructor.Rows[i]["contact_hr_credit"].ToString());

                            if (dt_course_wise_instructor.Rows[i]["prep_hr_per_week"].ToString() != "") prep_hr_per_week = Convert.ToDouble(dt_course_wise_instructor.Rows[i]["prep_hr_per_week"].ToString());

                            if (dt_course_wise_instructor.Rows[i]["percent_load"].ToString() != "") percent_load = Convert.ToDouble(dt_course_wise_instructor.Rows[i]["percent_load"].ToString());

                            if (dt_course_wise_instructor.Rows[i]["instructor_contact_hrs"].ToString() == "PR")
                            {
                                total_contact_hrs = (credits * contact_hr_credit * percent_load) / 100;
                            }
                            else if (dt_course_wise_instructor.Rows[i]["instructor_contact_hrs"].ToString() == "HW")
                            {
                                total_contact_hrs = percent_load;
                            }
                            else if (dt_course_wise_instructor.Rows[i]["instructor_contact_hrs"].ToString() == "HS")
                            {
                                total_contact_hrs = percent_load / 18;//17
                            }

                            DSC_VF_Mgmt.instructor_workload_detailRow instructor_workload_row = instructor_workload_upload.instructor_workload_detail.Newinstructor_workload_detailRow();

                            instructor_workload_row.doc_no = "new" + i;
                            instructor_workload_row.instructor_code = dt_course_wise_instructor.Rows[i]["instructor_code"].ToString();
                            instructor_workload_row.course_code = course_code;
                            instructor_workload_row.total_weeks = "18";//17

                            if (total_contact_hrs != 0) instructor_workload_row.total_contact_hrs = total_contact_hrs.ToString();

                            //if (total_contact_hrs != 0 && contact_hr_credit != 0)
                            if (total_contact_hrs != 0 && prep_hr_per_week != 0)
                            {
                                //instructor_workload_row.total_preparation_hrs = (total_contact_hrs * contact_hr_credit).ToString();
                                instructor_workload_row.total_preparation_hrs = (total_contact_hrs * prep_hr_per_week).ToString();
                            }

                            if (total_contact_hrs != 0)
                            {
                                //instructor_workload_row.total_hrs = (total_contact_hrs + (total_contact_hrs * contact_hr_credit)).ToString();
                                instructor_workload_row.total_hrs = (total_contact_hrs + (total_contact_hrs * prep_hr_per_week)).ToString();
                            }

                            //if ((total_contact_hrs + (total_contact_hrs * contact_hr_credit)) != 0)
                            //if ((total_contact_hrs + (total_contact_hrs * prep_hr_per_week)) != 0)
                            //{
                            //    //instructor_workload_row.total_hrs_in_semester = (Convert.ToInt32(instructor_workload_row.total_weeks.ToString()) * (total_contact_hrs + (total_contact_hrs * contact_hr_credit))).ToString();
                            //    instructor_workload_row.total_hrs_in_semester = (Convert.ToInt32(instructor_workload_row.total_weeks.ToString()) * (total_contact_hrs + (total_contact_hrs * prep_hr_per_week))).ToString();
                            //}

                            instructor_workload_row.total_hrs_in_semester = (total_contact_hrs * 18).ToString();//17

                            instructor_workload_row.admin_approved = "N";
                            instructor_workload_row.cancel_flag = "N";
                            instructor_workload_row.created_by = user_id;
                            instructor_workload_row.created_date = DateTime.Now;
                            instructor_workload_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                            instructor_workload_row.semester_type = sem_code;
                            instructor_workload_row.year_semester = year_code;
                            instructor_workload_row.is_tutorial = dt_course_wise_instructor.Rows[i]["is_tutorial"].ToString();

                            instructor_workload_upload.instructor_workload_detail.Addinstructor_workload_detailRow(instructor_workload_row);
                        }
                    }
                }
                else
                {
                    if (instructor_workload_data.Rows.Count > 0)
