                                        if (total_contact_hrs != 0) dr[0]["total_contact_hrs"] = total_contact_hrs.ToString();

                                        //if (total_contact_hrs != 0 && contact_hr_credit != 0)
                                        if (total_contact_hrs != 0 && prep_hr_per_week != 0)
                                        {
                                            //dr[0]["total_preparation_hrs"] = (total_contact_hrs * contact_hr_credit).ToString();
                                            dr[0]["total_preparation_hrs"] = (total_contact_hrs * prep_hr_per_week).ToString();
                                        }

                                        if (total_contact_hrs != 0)
                                        {
                                            //dr[0]["total_hrs"] = (total_contact_hrs + (total_contact_hrs * contact_hr_credit)).ToString();
                                            dr[0]["total_hrs"] = (total_contact_hrs + (total_contact_hrs * prep_hr_per_week)).ToString();
                                        }

                                        //if ((total_contact_hrs + (total_contact_hrs * contact_hr_credit)) != 0)
                                        //if ((total_contact_hrs + (total_contact_hrs * prep_hr_per_week)) != 0)
                                        //{
                                        //    //dr[0]["total_hrs_in_semester"] = (Convert.ToInt32(dr[0]["total_weeks"].ToString()) * (total_contact_hrs + (total_contact_hrs * contact_hr_credit))).ToString();
