                                        //}

                                        dr[0]["total_hrs_in_semester"] = (total_contact_hrs * 18).ToString();//17

                                        instructor_workload_upload.instructor_workload_detail.ImportRow(dr[0]);
                                    }
                                }
                            }

                            objBLReturnObject = objMaster.save_instructor_workload_data(instructor_workload_upload, user_type, user_id, HttpContext.Current.Request.UserHostName);
                        }
                    }
                }


                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                }
            }
            catch (Exception ex)
            {
                jsondata = ex.ToString();
            }
        }

        instructor_workload_data = objmaster.get_vf_course_wise_workload_detail(course_code, sem_code, year_code);

        if (instructor_workload_data != null)
        {
            instructor_workload_data.Columns.Add("percent_load");

            for (int i = 0; i < instructor_workload_data.Rows.Count; i++)
            {
                //DataRow[] dr = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "'");
                DataRow[] dr = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "' and is_tutorial='" + instructor_workload_data.Rows[i]["is_tutorial"].ToString() + "'");

                if (dr.Length > 0)
                {
                    instructor_workload_data.Rows[i]["percent_load"] = dr[0]["percent_load"];
                }

                DataRow[] dr1 = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "'");

                if (dr1.Length > 0)
                {
                    if (dr1[0]["rate_band_designation"].ToString() != "VFT")
                    {
                        instructor_workload_data.Rows[i]["designation"] = dr1[0]["rate_band_designation"];
                    }
                }
            }
        }

        if (instructor_workload_data != null)
        {
            jsondata = GetJson1(instructor_workload_data);
        }
        return jsondata;
    }

