    [WebMethod(EnableSession = true)]
    public string save_vf_course_wise_workload_detail(string All_table_course_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {

            JavaScriptSerializer ser = new JavaScriptSerializer();

            ArrayList All_Instructor_data = ser.Deserialize<ArrayList>(All_table_course_data);

            ArrayList instructor_data = (ArrayList)All_Instructor_data[0];
            string action = (string)All_Instructor_data[1];

            DataTable dt_course_workload_dtl = null;
            DataTable dt = null;

            if (instructor_data.Count > 0)
            {
                Dictionary<string, object> dic_instructor_data = (Dictionary<string, object>)instructor_data[0];
                dt_course_workload_dtl = objmaster.Get_CourseWiseWorkload_details(dic_instructor_data["course_code"].ToString(), dic_instructor_data["semester_type"].ToString(), dic_instructor_data["year_semester"].ToString());
                dt = objmaster.get_vf_course_wise_workload_detail_v2(dic_instructor_data["course_code"].ToString(), dic_instructor_data["semester_type"].ToString(), dic_instructor_data["year_semester"].ToString(), "N");
            }

            if (dt_course_workload_dtl != null)
            {
                DSC_VF_Mgmt instructor_workload_upload = new DSC_VF_Mgmt();

                for (int i = 0; i < instructor_data.Count; i++)
                {
                    Dictionary<string, object> dic_instructor_data = (Dictionary<string, object>)instructor_data[i];

                    DataRow[] dr = dt_course_workload_dtl.Select("instructor_code = '" + dic_instructor_data["instructor_code"].ToString() + "' and course_code = '" + dic_instructor_data["course_code"].ToString() + "' and is_tutorial = '" + dic_instructor_data["is_tutorial"].ToString() + "'");
                    DataRow[] dr_new = dt.Select("instructor_code = '" + dic_instructor_data["instructor_code"].ToString() + "' and course_code = '" + dic_instructor_data["course_code"].ToString() + "'");
                    if (dr.Length > 0)
                    {

                        if (dr[0]["admin_approved"].ToString() != "Y")
                        {
                            dr[0]["total_weeks"] = dic_instructor_data["total_weeks"];
                            dr[0]["total_contact_hrs"] = dic_instructor_data["total_contact_hrs"];
                            dr[0]["total_preparation_hrs"] = dic_instructor_data["total_preparation_hrs"];
                            dr[0]["total_hrs"] = dic_instructor_data["total_hrs"];
                            dr[0]["total_hrs_in_semester"] = dic_instructor_data["total_hrs_in_semester"];
                            if (dr_new.Length > 0)
                            {
                                dr[0]["total_exp"] = dr_new[0]["total_experiance"];
                                dr[0]["rate_band"] = dr_new[0]["rate_band"];
                                dr[0]["alternate_band"] = dr_new[0]["upper_rate_band"];
                            }
                            else
                            {
                                dr[0]["total_exp"] = dic_instructor_data["total_exp"];
                                dr[0]["rate_band"] = dic_instructor_data["rate_band"];
                                dr[0]["alternate_band"] = dic_instructor_data["alternate_band"];
                            }

                            dr[0]["justification"] = dic_instructor_data["justification"];
                            dr[0]["last_modified_by"] = user_id;
                            dr[0]["last_modified_date"] = DateTime.Now;
                            dr[0]["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                            dr[0]["hours_bifurcation"] = dic_instructor_data["hours_bifurcation"];

                            if (dic_instructor_data["additional_hours"] == "")
                                dr[0]["additional_hours"] = 0;
                            else
                                dr[0]["additional_hours"] = dic_instructor_data["additional_hours"];

                            if (action == "A" && user_type == "FA")
                            {
                                dr[0]["admin_approved"] = "Y";
                            }
                            else if (action == "A" && user_type == "A1")
                            {
                                // Not Update Any Column
                            }

                            instructor_workload_upload.instructor_workload_detail.ImportRow(dr[0]);
                        }
                    }
                }

                objBLReturnObject = objMaster.save_instructor_workload_data(instructor_workload_upload, user_type, user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 1)
                {
                }

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                }
                else //if (objBLReturnObject.ExecutionStatus == 1)
                {
                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();

                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
                    course_log_row.course_code = ((Dictionary<string, object>)instructor_data[0])["course_code"].ToString();
                    course_log_row.remark = "Modify Workload";
                    course_log_row.created_by = user_id;
                    course_log_row.created_date = DateTime.Now;
                    course_log_row.created_host = HttpContext.Current.Request.UserHostName;

                    course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                    BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                    Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }


