    [WebMethod(EnableSession = true)]
    public string send_Appointment_mail_to_visiting_faculty(string instructor_list)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        String Instructor_type_email = "";
        String tea_email = "";

        try
        {
            if (user_type == "HR" || user_type == "FA")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                //Dictionary<string,object> request_data = ser.Deserialize<Dictionary<string,object>>(instructor_list);

                Dictionary<string, object>[] dic_instructor_list = ser.Deserialize<Dictionary<string, object>[]>(instructor_list);

                Instructor_type_email = dic_instructor_list[0]["hdn_user_type"].ToString();
                tea_email = dic_instructor_list[0]["hdn_tea_letter"].ToString();

                string userType_for_Email = objmaster.get_user_type_for_letter_TA_AA(dic_instructor_list[0]["sem_code"].ToString(), dic_instructor_list[0]["year_code"].ToString(), dic_instructor_list[0]["instructor_code"].ToString());

                if (dic_instructor_list.Length > 0)
                {
                    DataTable dt_instructor_mst_data = objmaster.Get_All_instructor_mst_data();

                    DataTable AckDetails = objmaster.Get_VF_TA_AA_Letter_Email_Body_data(Instructor_type_email, tea_email, userType_for_Email);  //Ananth 10-07-2019

                    //string directory_path = "C:/Ceptreg_Log/Send_Appointment_Letter/";
                    string directory_path = HttpContext.Current.Server.MapPath("~/LetterPDF");
                    string str_path = HttpContext.Current.Request.Url.Authority;

                    for (int i = 0; i < (HttpContext.Current.Request.Url.Segments.Length - 2); i++)
                    {
                        str_path = str_path + HttpContext.Current.Request.Url.Segments[i];
                    }

                    if (dt_instructor_mst_data != null)
                    {
                        int PDF_status;

                        //objmaster.send_Appointment_mail_to_visiting_faculty(ref dic_instructor_list, dt_instructor_mst_data, directory_path, str_path, out PDF_status);
                        send_Appointment_mail_to_visiting_faculty(ref dic_instructor_list, dt_instructor_mst_data, directory_path, str_path, out PDF_status, HttpContext.Current.Session["UserName"].ToString(), HttpContext.Current.Session["email"].ToString());

                        if (PDF_status == dic_instructor_list.Length)
                        {
                            return "Unable to Create PDF";
                        }

                        if (dic_instructor_list.Length == 1 && dic_instructor_list[0]["status"] == "False")
                        {
                            return dic_instructor_list[0]["message"].ToString();
                        }

                        if (dic_instructor_list.Length > 0)
                        {
                            for (int i = 0; i < dic_instructor_list.Length; i++)
                            {
                                dic_instructor_list[i]["FA_name"] = HttpContext.Current.Session["UserName"].ToString();
                            } 
                        }
                        //dic_instructor_list[0]["FA_name"] = HttpContext.Current.Session["UserName"].ToString();

                        string res = objmail.Send_Appointment_Mail_to_visiting_faculty(dic_instructor_list, AckDetails);
                        return res;

                    }
                }
                else
                {
                    return "No Instructor found to Send Mail.";
                }

            }
            else
            {
                return "You are not Authorized to Send Mails.";
            }
        }
        catch (Exception ex)
        {
            return "Problem in Send Mails.";
        }
        return "";
    }

