                    string path = HttpContext.Current.Server.MapPath("~/LetterPDF");
                    string name_file = vising_faculty_data.Rows[i]["instructor_code"].ToString() + "_" + vising_faculty_data.Rows[i]["instructor_name"].ToString().Replace(" ", "_") + "_" + vising_faculty_data.Rows[i]["dept_name"].ToString().Replace(" ", "_") + "_" + semester + "_" + year_code + ".pdf";
                    path = path + "\\" + vising_faculty_data.Rows[i]["instructor_code"].ToString() + "_" + vising_faculty_data.Rows[i]["instructor_name"].ToString().Replace(" ", "_") + "_" + vising_faculty_data.Rows[i]["dept_name"].ToString().Replace(" ", "_") + "_" + semester + "_" + year_code + ".pdf";

                    if (File.Exists(path))
                    {
                        vising_faculty_data.Rows[i]["pdf_path"] = name_file;
                    }


                }

                DataTable dt_vf_finance_report_data = vising_faculty_data.Clone();

                for (int i = 0; i < vising_faculty_data.Rows.Count; i++)
