    [WebMethod(EnableSession = true)]
    public string save_VF_disbursement_data(string All_table_course_data)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            ArrayList VF_disbursement_data = ser.Deserialize<ArrayList>(All_table_course_data);

            ArrayList instructor_data = (ArrayList)VF_disbursement_data[0];
            string action = (string)VF_disbursement_data[1];

            DSC_VF_Mgmt vf_disbursement = new DSC_VF_Mgmt();

            DataTable dt_vf_disbursement_data = objmaster.vf_disbursement_data(((Dictionary<string, object>)instructor_data[0])["semester_type"].ToString().Trim(), ((Dictionary<string, object>)instructor_data[0])["year_semester"].ToString().Trim());

            for (int i = 0; i < instructor_data.Count; i++)
            {
                DSC_VF_Mgmt.instructor_disbursement_detailRow vf_disbursement_row = vf_disbursement.instructor_disbursement_detail.Newinstructor_disbursement_detailRow();

                DataRow[] dr = null;

                if (dt_vf_disbursement_data != null)
                    dr = dt_vf_disbursement_data.Select("instructor_code='" + ((Dictionary<string, object>)instructor_data[i])["instructor_code"].ToString().Trim() + "' and course_code='" + ((Dictionary<string, object>)instructor_data[i])["course_code"].ToString().Trim() + "'");

                if (dr != null && dr.Length > 0)
                {
                    //vf_disbursement_row.ItemArray = dr[0].ItemArray;

                    vf_disbursement_row.installment1_enabled = dr[0]["installment1_enabled"].ToString() == "" ? "Y" : dr[0]["installment1_enabled"].ToString();
                    vf_disbursement_row.installment2_enabled = dr[0]["installment2_enabled"].ToString() == "" ? "Y" : dr[0]["installment2_enabled"].ToString();
                    vf_disbursement_row.installment3_enabled = dr[0]["installment3_enabled"].ToString() == "" ? "Y" : dr[0]["installment3_enabled"].ToString();
                    vf_disbursement_row.installment4_enabled = dr[0]["installment4_enabled"].ToString() == "" ? "Y" : dr[0]["installment4_enabled"].ToString();
                    vf_disbursement_row.installment1_payment_status = dr[0]["installment1_payment_status"].ToString() == "" ? "N" : dr[0]["installment1_payment_status"].ToString();
                    vf_disbursement_row.installment2_payment_status = dr[0]["installment2_payment_status"].ToString() == "" ? "N" : dr[0]["installment2_payment_status"].ToString();
                    vf_disbursement_row.installment3_payment_status = dr[0]["installment3_payment_status"].ToString() == "" ? "N" : dr[0]["installment3_payment_status"].ToString();
                    vf_disbursement_row.installment4_payment_status = dr[0]["installment4_payment_status"].ToString() == "" ? "N" : dr[0]["installment4_payment_status"].ToString();
                    vf_disbursement_row.admin_approved = dr[0]["admin_approved"].ToString() == "" ? "N" : dr[0]["admin_approved"].ToString();
                    vf_disbursement_row.created_by = dr[0]["created_by"].ToString();
                    vf_disbursement_row.created_date = DateTime.Parse(dr[0]["created_date"].ToString());
                    vf_disbursement_row.created_host = dr[0]["created_host"].ToString();
                    vf_disbursement_row.last_modified_by = user_id;
                    vf_disbursement_row.last_modified_date = DateTime.Now;
                    vf_disbursement_row.last_modified_host = HttpContext.Current.Request.UserHostName.ToString();
                }
                else
                {
                    vf_disbursement_row.installment1_enabled = "Y";
                    vf_disbursement_row.installment2_enabled = "Y";
                    vf_disbursement_row.installment3_enabled = "Y";
                    vf_disbursement_row.installment4_enabled = "Y";
                    vf_disbursement_row.installment1_payment_status = "N";
                    vf_disbursement_row.installment2_payment_status = "N";
                    vf_disbursement_row.installment3_payment_status = "N";
                    vf_disbursement_row.installment4_payment_status = "N";
                    vf_disbursement_row.admin_approved = "N";
                    vf_disbursement_row.created_by = user_id;
                    vf_disbursement_row.created_date = DateTime.Now;
                    vf_disbursement_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                }

                vf_disbursement_row.instructor_code = ((Dictionary<string, object>)instructor_data[i])["instructor_code"].ToString().Trim();
                vf_disbursement_row.course_code = ((Dictionary<string, object>)instructor_data[i])["course_code"].ToString().Trim();
                vf_disbursement_row.total_amount_payable = ((Dictionary<string, object>)instructor_data[i])["total_amount_payable"].ToString().Trim();
                vf_disbursement_row.total_installments = ((Dictionary<string, object>)instructor_data[i])["total_installments"].ToString().Trim();

                DateTime dt_installment = new DateTime();
                if (DateTime.TryParse(((Dictionary<string, object>)instructor_data[i])["installment_1"].ToString().Trim(), out dt_installment))
                    vf_disbursement_row.installment1 = dt_installment;
                if (DateTime.TryParse(((Dictionary<string, object>)instructor_data[i])["installment_2"].ToString().Trim(), out dt_installment))
                    vf_disbursement_row.installment2 = dt_installment;
                if (DateTime.TryParse(((Dictionary<string, object>)instructor_data[i])["installment_3"].ToString().Trim(), out dt_installment))
                    vf_disbursement_row.installment3 = dt_installment;
                if (DateTime.TryParse(((Dictionary<string, object>)instructor_data[i])["installment_4"].ToString().Trim(), out dt_installment))
                    vf_disbursement_row.installment4 = dt_installment;

                //if (((Dictionary<string, object>)instructor_data[i])["payment_1"].ToString().Trim() != "")
                vf_disbursement_row.payment1 = ((Dictionary<string, object>)instructor_data[i])["payment_1"].ToString().Trim();
                //if (((Dictionary<string, object>)instructor_data[i])["payment_2"].ToString().Trim() != "")
                vf_disbursement_row.payment2 = ((Dictionary<string, object>)instructor_data[i])["payment_2"].ToString().Trim();
                //if (((Dictionary<string, object>)instructor_data[i])["payment_3"].ToString().Trim() != "")
                vf_disbursement_row.payment3 = ((Dictionary<string, object>)instructor_data[i])["payment_3"].ToString().Trim();
                //if (((Dictionary<string, object>)instructor_data[i])["payment_4"].ToString().Trim() != "")
                vf_disbursement_row.payment4 = ((Dictionary<string, object>)instructor_data[i])["payment_4"].ToString().Trim();

                vf_disbursement_row.cancel_flag = "N";
                vf_disbursement_row.semester_type = ((Dictionary<string, object>)instructor_data[i])["semester_type"].ToString().Trim();
                vf_disbursement_row.year_semester = ((Dictionary<string, object>)instructor_data[i])["year_semester"].ToString().Trim();

                //if (action == "A" && user_type == "A1")
                if (action == "A" && ((Dictionary<string, object>)instructor_data[i])["total_amount_payable"].ToString().Trim() != "")
                {
                    if (((Dictionary<string, object>)instructor_data[i])["total_installments"].ToString().Trim() != "" && ((Dictionary<string, object>)instructor_data[i])["total_installments"].ToString().Trim() != "0")
                    {
                        vf_disbursement_row.installment1_enabled = "N";
                        vf_disbursement_row.installment2_enabled = "N";
                        vf_disbursement_row.installment3_enabled = "N";
                        vf_disbursement_row.installment4_enabled = "N";
                        vf_disbursement_row.admin_approved = "Y";
                    }
                }

                if (dr != null && dr.Length > 0)
                {
                    if (dr[0]["admin_approved"].ToString() != "Y")
                    {
                        vf_disbursement.instructor_disbursement_detail.Addinstructor_disbursement_detailRow(vf_disbursement_row);
                    }
                }
                else
                {
                    vf_disbursement.instructor_disbursement_detail.Addinstructor_disbursement_detailRow(vf_disbursement_row);
                }
            }

            //// // 

            objBLReturnObject = objMaster.save_VF_disbursement_data(vf_disbursement, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                if (action == "A")
                {
                    //objBLReturnObject.ServerMessage = "Data Submitted Successfully";
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }

    [WebMethod(EnableSession = true)]
    public string VFDisbursement_send_for_review(string instructor_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> VF_disbursement_data = ser.Deserialize<Dictionary<string, object>>(instructor_data);

            DSC_VF_Mgmt vf_disbursement = new DSC_VF_Mgmt();

            DataTable dt_vf_disbursement_data = objmaster.vf_disbursement_data(VF_disbursement_data["sem_code"].ToString().Trim(), VF_disbursement_data["year_code"].ToString().Trim());

            DataRow[] dr = null;

            if (dt_vf_disbursement_data != null)
                dr = dt_vf_disbursement_data.Select("instructor_code='" + VF_disbursement_data["instructor_code"].ToString().Trim() + "' and course_code='" + VF_disbursement_data["course_code"].ToString().Trim() + "'");

            if (dr != null && dr.Length > 0)
            {
                DSC_VF_Mgmt.instructor_disbursement_detailRow vf_disbursement_row = vf_disbursement.instructor_disbursement_detail.Newinstructor_disbursement_detailRow();

                vf_disbursement_row.ItemArray = dr[0].ItemArray;

                vf_disbursement_row["installment" + VF_disbursement_data["cur_installment"].ToString().Trim() + "_enabled"] = "Y";

                vf_disbursement_row.admin_approved = "N";

                vf_disbursement.instructor_disbursement_detail.Addinstructor_disbursement_detailRow(vf_disbursement_row);
            }
            else
            {
                return "No Data Found for selected Instructor and Course";
            }

            objBLReturnObject = objMaster.save_VF_disbursement_data(vf_disbursement, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                objBLReturnObject.ServerMessage = "Successfully sent for Review";
            }
        }
        catch (Exception ex)
        {
            return "Problem in Sending for Review.";
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string VF_submit_payment(string payment_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        string return_status = "False";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> VF_disbursement_data = ser.Deserialize<List<Dictionary<string, object>>>(payment_data);

            if (VF_disbursement_data.Count > 0)
            {
                DSC_VF_Mgmt vf_disbursement = new DSC_VF_Mgmt();

                DataTable dt_vf_disbursement_data = objmaster.vf_disbursement_data(VF_disbursement_data[0]["sem_code"].ToString().Trim(), VF_disbursement_data[0]["year_code"].ToString().Trim());

                if (dt_vf_disbursement_data != null)
                {
                    for (int i = 0; i < VF_disbursement_data.Count; i++)
                    {
                        DataRow[] dr = dt_vf_disbursement_data.Select("instructor_code='" + VF_disbursement_data[i]["instructor_code"].ToString().Trim() + "' and course_code='" + VF_disbursement_data[i]["course_code"].ToString().Trim() + "'");

                        if (dr.Length > 0)
                        {
                            DSC_VF_Mgmt.instructor_disbursement_detailRow vf_disbursement_row = vf_disbursement.instructor_disbursement_detail.Newinstructor_disbursement_detailRow();

                            vf_disbursement_row.ItemArray = dr[0].ItemArray;

                            vf_disbursement_row["installment" + VF_disbursement_data[i]["cur_installment"].ToString().Trim() + "_enabled"] = "N";
                            vf_disbursement_row["installment" + VF_disbursement_data[i]["cur_installment"].ToString().Trim() + "_payment_status"] = "Y";

                            vf_disbursement_row["installment" + VF_disbursement_data[i]["cur_installment"].ToString().Trim() + "_payment_ref"] = VF_disbursement_data[i]["payment_ref"].ToString().Trim();
                            vf_disbursement_row["installment" + VF_disbursement_data[i]["cur_installment"].ToString().Trim() + "_payment_ref_date"] = VF_disbursement_data[i]["payment_ref_date"].ToString().Trim();
                            vf_disbursement_row["installment" + VF_disbursement_data[i]["cur_installment"].ToString().Trim() + "_disbursement_amount"] = VF_disbursement_data[i]["disbursement_amount"].ToString().Trim();

                            vf_disbursement.instructor_disbursement_detail.Addinstructor_disbursement_detailRow(vf_disbursement_row);
                        }
                    }

                    objBLReturnObject = objMaster.save_VF_disbursement_data(vf_disbursement, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        return_status = "False";
                        objBLReturnObject.ServerMessage = "Problem in Submit data " + objBLReturnObject.ServerMessage;
                    }
                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        String res = objmail.Send_Payment_Success_Mail_to_visiting_faculty(VF_disbursement_data);

                        return_status = "True";
                        objBLReturnObject.ServerMessage = "Payment Submitted Successfully" + res;
                    }
                }
                else
                {
                    return_status = "False";
                    objBLReturnObject.ServerMessage = "No Data Found in Database to Update Payment Status";
                }
            }
            else
            {
                return_status = "False";
                objBLReturnObject.ServerMessage = "No Data Found to Submit";
            }
        }
        catch (Exception ex)
        {
            return_status = "False";
            objBLReturnObject.ServerMessage = "Problem in Submit DATA.";
        }

        return return_ajax_string(return_status, objBLReturnObject.ServerMessage);
    }

