    public void send_Appointment_mail_to_visiting_faculty(ref Dictionary<string, object>[] dic_instructor_list, DataTable dt_instructor_mst_data, string directory_path, string str_path, out int PDF_status, string fa_name, string fa_mail)
    {
        PDF_status = 0;
        string directory_path_data = @"C:/Ceptreg_Log/Send_Appointment_Letter/Log/";
        string filename = "Visiting_Faculty_Mail_Log";

        System.IO.File.AppendAllText(@"" + directory_path_data + filename + ".txt", Environment.NewLine);
        System.IO.File.AppendAllText(@"" + directory_path_data + filename + ".txt", "=======================================================================================" + Environment.NewLine);
        System.IO.File.AppendAllText(@"" + directory_path_data + filename + ".txt", "=======================================================================================" + Environment.NewLine);
        System.IO.File.AppendAllText(@"" + directory_path_data + filename + ".txt", "Date : " + DateTime.Now + Environment.NewLine);
        System.IO.File.AppendAllText(@"" + directory_path_data + filename + ".txt", "=======================================================================================" + Environment.NewLine);
        try
        {
            //string[] delete_filenames = Directory.GetFiles(directory_path);
            //
            //for (int i = 0; i < delete_filenames.Length; i++)
            //{
            //    FileInfo file = new FileInfo(delete_filenames[i]);
            //    file.Delete();
            //}
            
            for (int i = 0; i < dic_instructor_list.Length; i++)
            {
                DataRow[] dr = dt_instructor_mst_data.Select("instructor_code = '" + dic_instructor_list[i]["instructor_code"] + "'");

                if (dr.Length > 0)
                {
                    if (dr[0]["mail"].ToString() != "")
                    {
                        dic_instructor_list[i]["status"] = "False";
                        dic_instructor_list[i]["destination_mail"] = dr[0]["mail"].ToString();
                        dic_instructor_list[i]["instructor_name"] = dr[0]["instructor_name"].ToString();
                        dic_instructor_list[i]["title"] = dr[0]["title"].ToString();
                        dic_instructor_list[i]["grade"] = dr[0]["rate_wise_designation"].ToString();

                        DataTable dt_doctoral_dtl = objmaster.get_VF_doctoral_detail(dic_instructor_list[i]["sem_code"].ToString(), dic_instructor_list[i]["year_code"].ToString(), dic_instructor_list[i]["instructor_code"].ToString());

                        string userType = objmaster.get_user_type_for_letter_TA_AA(dic_instructor_list[i]["sem_code"].ToString(), dic_instructor_list[i]["year_code"].ToString(), dic_instructor_list[i]["instructor_code"].ToString());

                        dic_instructor_list[i]["userType"] = userType;

                        ReportPrinter obReportPrinter = new ReportPrinter();

                        JavaScriptSerializer ser = new JavaScriptSerializer();

                        //obReportPrinter.PageFile = "https://" + str_path + "Admin/Master/HR_PrintLetter.aspx?iid=" + dic_instructor_list[i]["instructor_code"] + "&idept=" + dic_instructor_list[i]["dept_name"] + "&sc=" + dic_instructor_list[i]["sem_code"] + "&yc=" + dic_instructor_list[i]["year_code"] + "&FA_name=" + fa_name + "&FA_mail=" + fa_mail;
                        if (dic_instructor_list[i]["hdn_tea_letter"].ToString() == "TEA")
                        {
                            if (dt_doctoral_dtl != null && dt_doctoral_dtl.Rows.Count > 0 && dic_instructor_list[i]["prog_code"].Equals("3"))
                            {
                                dic_instructor_list[i]["userType"] = "VF_PHD";
                            }
                            // obReportPrinter.PageFile = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "Admin/Master/HR_TEA_PrintLetter.aspx?iid=" + dic_instructor_list[i]["instructor_code"] + "&idept=" + dic_instructor_list[i]["dept_name"] + "&sc=" + dic_instructor_list[i]["sem_code"] + "&yc=" + dic_instructor_list[i]["year_code"] + "&FA_name=" + fa_name + "&FA_mail=" + fa_mail;
                        }
                        else if (dic_instructor_list[i]["hdn_user_type"].ToString() == "VF")
                        {
                            if (dt_doctoral_dtl != null && dt_doctoral_dtl.Rows.Count > 0 && dic_instructor_list[i]["prog_code"].Equals("3"))
                            {
                                dic_instructor_list[i]["userType"] = "VF_PHD";
                                // obReportPrinter.PageFile = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "Admin/Master/HR_PrintLetter_phd.aspx?iid=" + dic_instructor_list[i]["instructor_code"] + "&idept=" + dic_instructor_list[i]["dept_name"] + "&sc=" + dic_instructor_list[i]["sem_code"] + "&yc=" + dic_instructor_list[i]["year_code"] + "&FA_name=" + fa_name + "&FA_mail=" + fa_mail;
                            }
                            else
                            {
                                //obReportPrinter.PageFile = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "Admin/Master/HR_PrintLetter.aspx?iid=" + dic_instructor_list[i]["instructor_code"] + "&idept=" + dic_instructor_list[i]["dept_name"] + "&sc=" + dic_instructor_list[i]["sem_code"] + "&yc=" + dic_instructor_list[i]["year_code"] + "&FA_name=" + fa_name + "&FA_mail=" + fa_mail;
                            }
                        }
                        else if (userType == "TA")
                        {
                            if (dt_doctoral_dtl != null && dt_doctoral_dtl.Rows.Count > 0)
                            {
                                dic_instructor_list[i]["hdn_user_type"] = "VF_PHD";
                            }
