    [WebMethod(EnableSession = true)]
    public string get_vf_core_faculty_report(string member_type, string semester, string year_code, string dept_code)
    {
        int countedu;
        int lendr;
        int insturlen;
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        DataTable dt_report = new DataTable();

        if (member_type == "VF")
        {
            #region VF Report data
            DataTable dt_instructor = objmaster.get_instructor_detail_report(semester, year_code, dept_code, user_id, user_type);
            DataTable dt_academic_work = objmaster.get_instructor_academic_detail();
            //DataTable dt_eduction = objmaster.get_instructor_eduction_detail();
            //  dt_report.Columns.Add("Instructor Code", typeof(String));
            dt_report.Columns.Add("Instructor Code", typeof(String));
            dt_report.Columns.Add("Title", typeof(String));
            dt_report.Columns.Add("Full Name", typeof(String));
            dt_report.Columns.Add("First Name", typeof(String));
            dt_report.Columns.Add("Last Name", typeof(String));
            dt_report.Columns.Add("Email ID", typeof(String));
            dt_report.Columns.Add("Mobile No", typeof(String));
            dt_report.Columns.Add("Alternate Contact No", typeof(String));
            dt_report.Columns.Add("Blood Group", typeof(String));
            dt_report.Columns.Add("Date of Birth", typeof(String));
            dt_report.Columns.Add("Highest Qualification", typeof(String));
            dt_report.Columns.Add("Total Experience (Year)", typeof(String));
            dt_report.Columns.Add("Associated With CEPT Since", typeof(String));
            dt_report.Columns.Add("Address", typeof(String));
            dt_report.Columns.Add("Emergency Contact Name", typeof(String));
            dt_report.Columns.Add("Emergency Contact Number", typeof(String));
            dt_report.Columns.Add("Achievements", typeof(String));
            dt_report.Columns.Add("Area of Interest", typeof(String));
            dt_report.Columns.Add("CV File Name", typeof(String));
            dt_report.Columns.Add("Associated With", typeof(String));
            dt_report.Columns.Add("Degree", typeof(String));
            dt_report.Columns.Add("Specialization", typeof(String));
            dt_report.Columns.Add("University", typeof(String));
            dt_report.Columns.Add("Date of Issuance Certificate", typeof(String));
            dt_report.Columns.Add("Designation (Work)", typeof(String));
            dt_report.Columns.Add("Institute (Work)", typeof(String));
            dt_report.Columns.Add("Start Date (Work)", typeof(String));
            dt_report.Columns.Add("End Date (Work)", typeof(String));
            dt_report.Columns.Add("Courses taught in Areas of Expertise", typeof(String));
            try
            {
                int row_cnt = 0;
                if (dt_instructor != null)
                {

                    for (int i = 0; i < dt_instructor.Rows.Count; i++)
                    {

                        DataRow[] dr_in = dt_instructor.Select("instructor_code='" + dt_instructor.Rows[i]["instructor_code"] + "' and course_code='" + dt_instructor.Rows[i]["course_code"] + "'");

                        DataRow[] dr_edu = dt_academic_work.Select("instructor_code='" + dt_instructor.Rows[i]["instructor_code"] + "' and detail_type='education'");

                        DataRow[] dr_work = dt_academic_work.Select("instructor_code='" + dt_instructor.Rows[i]["instructor_code"] + "'and detail_type='work'");

                        // for (int k = 0; k < dr_in.Length; k++)
                        //{


                        int max_cnt = 0;

                        max_cnt = (dr_in.Length >= dr_edu.Length) ? ((dr_in.Length >= dr_work.Length) ? dr_in.Length : dr_work.Length) : ((dr_edu.Length >= dr_work.Length) ? dr_edu.Length : dr_work.Length);

                        for (int j = 0; j < max_cnt; j++)
                        {
                            dt_report.Rows.Add();
                            if (j == 0)
                            {
                                if (dr_in.Length > 0)
                                {
                                    // dt_report.Rows.Add();

                                    dt_report.Rows[row_cnt]["Instructor Code"] = dr_in[0]["VF_code"];
                                    dt_report.Rows[row_cnt]["Title"] = dr_in[0]["title"];
                                    dt_report.Rows[row_cnt]["Full Name"] = dr_in[0]["instructor_name"];
                                    dt_report.Rows[row_cnt]["First Name"] = dr_in[0]["first_name"];
                                    dt_report.Rows[row_cnt]["Last Name"] = dr_in[0]["last_name"];
                                    dt_report.Rows[row_cnt]["Email ID"] = dr_in[0]["mail"];
                                    dt_report.Rows[row_cnt]["Mobile No"] = dr_in[0]["mobile_no"];
                                    dt_report.Rows[row_cnt]["Alternate Contact No"] = dr_in[0]["alternate_contact_no"];
                                    dt_report.Rows[row_cnt]["Blood Group"] = dr_in[0]["blood_group"];
                                    dt_report.Rows[row_cnt]["Date of Birth"] = dr_in[0]["dob"];
                                    dt_report.Rows[row_cnt]["Highest Qualification"] = dr_in[0]["highest_qualification"];
                                    dt_report.Rows[row_cnt]["Total Experience (Year)"] = dr_in[0]["total_experiance"];
