    [WebMethod(EnableSession = true)]
    public string update_workload_dtl(string instructor_list, string semester, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            string inst_str = "";
            string course_str = "";
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object>[] dic_instructor_list = ser.Deserialize<Dictionary<string, object>[]>(instructor_list);


            if (dic_instructor_list.Length > 0)
            {
                for (int i = 0; i < dic_instructor_list.Length; i++)
                {
                    if (i == 0)
                    {
                        inst_str = "'" + dic_instructor_list[i]["instructor_code"].ToString() + "'";
                        course_str = "'" + dic_instructor_list[i]["course_code"].ToString() + "'";
                    }
                    else
                    {
                        inst_str += "," + "'" + dic_instructor_list[i]["instructor_code"].ToString() + "'";
                        course_str += "," + "'" + dic_instructor_list[i]["course_code"].ToString() + "'";
                    }
                }

            }
            else
            {
                return "No Instructor found ";
            }
            //
            Boolean status = objmaster.update_workload_dtl(inst_str, course_str, semester, year_code, user_id, HttpContext.Current.Request.UserHostName);

            if (status)
            {
                return "true";
            }
            else
            {
                return "false";
            }
        }
        catch (Exception ex)
        {
            return "Problem in Data.";
        }
        return "";
    }

