    #region Attendance

    [WebMethod(EnableSession = true)]
    public string save_attendance(string punch_data)
    {
        // Save Compliance Details in compliance_entry table.

        int re = 0;

        try
        {
            string strHostName = System.Net.Dns.GetHostName();

            IPHostEntry ipEntry = System.Net.Dns.GetHostEntry(strHostName);

            DataTable dt_saved_attendance_data = objmaster.get_attendance_data(HttpContext.Current.Session["UserId"].ToString());

            if (punch_data == "true")
            {
                if (dt_saved_attendance_data != null)
                {
                    if (dt_saved_attendance_data.Rows[0]["entry_time"].ToString() != "")
                    {
                        return "Data already saved for Entry";
                    }
                }
                else
                {
                    DS_Attendance.attendance_mstRow punch_date = obj_attendance.attendance_mst.Newattendance_mstRow();

                    punch_date.user_id = HttpContext.Current.Session["UserId"].ToString();
                    punch_date.date_of_attendance = System.DateTime.Now;
                    punch_date.entry_time = System.DateTime.Now;
                    punch_date.entry_ip = ipEntry.AddressList[1].ToString();
                    punch_date.entry_com_name = System.Environment.MachineName;
                    punch_date.cancel_flag = "N";
                    punch_date.created_by = HttpContext.Current.Session["UserId"].ToString();
                    punch_date.created_date = System.DateTime.Now;
                    punch_date.created_host = ipEntry.AddressList[1].ToString(); ;

                    obj_attendance.attendance_mst.Addattendance_mstRow(punch_date);
                }
            }
            else
            {
                if (dt_saved_attendance_data != null)
                {
                    if (dt_saved_attendance_data.Rows[0]["exit_time"].ToString() != "")
                    {
                        return "Data already saved for Exit";
                    }
                    else
                    {
                        DataRow dr = dt_saved_attendance_data.Rows[0];

                        dr["exit_time"] = System.DateTime.Now;
                        dr["exit_ip"] = HttpContext.Current.Request.UserHostName;
                        dr["exit_com_name"] = System.Environment.MachineName;
                        dr["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                        dr["last_modified_date"] = System.DateTime.Now;
                        dr["last_modified_host"] = ipEntry.AddressList[1].ToString();

                        obj_attendance.attendance_mst.ImportRow(dr);
                    }
                }
                else
                {
                    return "Please first Save your Entry Punch.";
                }
            }

            JavaScriptSerializer ser = new JavaScriptSerializer();

            objBLReturnObject = objMaster.save_attendance(obj_attendance, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
        }
        catch (Exception ex)
        {
            return "Problem in Save DATA." + ex.ToString();
        }

        return objBLReturnObject.ServerMessage;
    }

