                    {
                        ds.Tables.Add(singleTable);
                    }
                }

                //DataTable dt_user_mst_data = objmaster.get_all_user_mst_data();
                //DataTable dt_inactive_user_mst_data = objMaster.get_Inactive_user_mst_data();
                //DataTable dt_course_mst_data = objMaster.Get_All_course_mst_data();
                //DataTable dt_dept_wise_course_data = objMaster.Get_all_course_data(semester_type);
                //DataTable dt_student_wise_course_upload_data = objMaster.get_student_wise_course_upload_data();

                DataTable dt_upload_direct_icici_branch = objmaster.get_upload_icici_branch_data(semester_type, year_code);
                DataTable dt_student_current_semester_dtl = objmaster.get_fee_collection_student_current_semester_dtl();
                DataTable dt_student_course_dtl = objmaster.get_fee_collection_student_course_dtl(semester_type, year_code);
                DataTable dt_user_fee_status = objmaster.get_fee_collection_user_fee_status_data(semester_type, year_code);

                user_mst = ds.Tables[0];

