                                fee_flag = 1;
                            }
                        }
                        else
                        {
                            fee_flag = 1;
                        }

                        if (fee_flag == 1)
                        {
                            if (dr_student_current_semester_dtl.Length > 0 && dr_student_course_dtl.Length > 0)
