                                    if (dr_student_course_dtl[0]["credits"] != null || dr_student_course_dtl[0]["credits"] != "")
                                    {
                                        total_credit = total_credit + Convert.ToInt32(dr_student_course_dtl[0]["credits"].ToString());
                                    }
                                }

                                //DSC_fees_status.user_fees_statusRow user_fees_status_row = fees_status.user_fees_status.Newuser_fees_statusRow();
                                DSC_Upload_Fee_Collection.user_fees_statusRow user_fees_status_row = fee_collection_upload.user_fees_status.Newuser_fees_statusRow();

                                user_fees_status_row.doc_no = "new";
                                user_fees_status_row.user_id = user_mst.Rows[i]["ROLLNO"].ToString().Trim();
