                                user_fees_status_row.dept_code = dr_student_current_semester_dtl[0]["dept_code"].ToString();

                                if (total_credit > 12) { user_fees_status_row.fees_status = "F"; }
                                else { user_fees_status_row.fees_status = "H"; }

                                user_fees_status_row.fees_amount = Convert.ToDecimal(user_mst.Rows[i]["AMT"].ToString().Trim());
                                user_fees_status_row.cancel_flag = "N";
                                user_fees_status_row.semester_type = semester_type;
                                user_fees_status_row.year_semester = year_code;
