                    fee_collection_upload_row.student_name = user_mst.Rows[i]["STUDENTNAME"].ToString().Trim();
                    fee_collection_upload_row.course = user_mst.Rows[i]["COURSE"].ToString().Trim();
                    fee_collection_upload_row.cheque_no = user_mst.Rows[i]["Cheque no"].ToString().Trim();
                    fee_collection_upload_row.bank_name = user_mst.Rows[i]["Bank name"].ToString().Trim();
                    fee_collection_upload_row.branch = user_mst.Rows[i]["Branch"].ToString().Trim();
                    fee_collection_upload_row.created_by = session_data["UserId"].ToString();
                    fee_collection_upload_row.created_date = DateTime.Now;
                    fee_collection_upload_row.created_host = HttpContext.Current.Request.UserHostName;
