                    dr_transaction_dtl["transaction_id"] = user_mst.Rows[i]["Cheque no"].ToString().Trim();
                    dr_transaction_dtl["amount"] = user_mst.Rows[i]["AMT"].ToString().Trim();

                    if (dt_transaction_dtl != null)
                    {
                        if (user_mst.Rows[i]["CASH/CHEQUE"].ToString().Trim() == "CASH")
                        {
                            dr_transaction_dtl["status"] = "Mismatch. Cash Transaction";
