                        {
                            DataRow[] dr = dt_transaction_dtl.Select("user_id = '" + dr_transaction_dtl["user_id"].ToString() + "' and dd_no2 = '" + dr_transaction_dtl["transaction_id"].ToString() + "' and is_admin_approved = 'A'");

