                                    else dr_transaction_dtl["fees_type"] = "Inst " + dr[0]["installment_no"].ToString();
                                }

                                double amount_to_pay = 0;
                                if (dr[0]["installment" + dr[0]["installment_no"].ToString()].ToString() != "")
                                {
                                    amount_to_pay = Convert.ToDouble(dr[0]["installment" + dr[0]["installment_no"].ToString()].ToString());
                                }

                                if (Convert.ToDouble(user_mst.Rows[i]["AMT"].ToString().Trim()) == amount_to_pay)
                                    dr_transaction_dtl["status"] = "Reconcilled";
                                else
                                    dr_transaction_dtl["status"] = "Amount Mismatch. Amount to pay : " + amount_to_pay;

                                //dr_transaction_dtl["status"] = "Reconcilled";
                            }
                            else
                            {
                                DataRow[] dr1 = dt_transaction_dtl.Select("user_id = '" + dr_transaction_dtl["user_id"].ToString() + "' and dd_no2 = '" + dr_transaction_dtl["transaction_id"].ToString() + "'");

                                if (dr1.Length > 0)
                                    dr_transaction_dtl["status"] = "Mismatch. Payslip not approved";
                                else
                                    dr_transaction_dtl["status"] = "Mismatch. Payslip Upload detail not found";
                            }
                        }
                        else
                        {
                            dr_transaction_dtl["status"] = "Mismatch. Transaction Type(CASH/CHEQUE) not found";
                        }
                    }
                    else
                        dr_transaction_dtl["status"] = "Payslip Upload Data not Found for semester";

                    dt_response.Rows.Add(dr_transaction_dtl);
                }

                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return return_ajax_data("False", jsondata);
                }
            }
        }
        catch (Exception ex)
        {
