                if (!user_mst.Columns.Contains("REMITTER CODE"))
                {
                    dr_error = dt_error.NewRow();
                    dr_error["Excel_RowNo"] = "1"; dr_error["Remark"] = "'REMITTER CODE' column not found";
                    dt_error.Rows.Add(dr_error);
                }

                if (!user_mst.Columns.Contains("AMOUNT"))
                {
                    dr_error = dt_error.NewRow();
                    dr_error["Excel_RowNo"] = "1"; dr_error["Remark"] = "'AMOUNT' column not found";
                    dt_error.Rows.Add(dr_error);
                }

                if (!user_mst.Columns.Contains("TRANSACTION REF NO"))
                {
                    dr_error = dt_error.NewRow();
                    dr_error["Excel_RowNo"] = "1"; dr_error["Remark"] = "'TRANSACTION REF NO' column not found";
                    dt_error.Rows.Add(dr_error);
                }

                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return return_ajax_data("False", jsondata);
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    isEmpty = true;

                    for (int j = 0; j < user_mst.Columns.Count; j++)
                    {
                        if (string.IsNullOrEmpty(user_mst.Rows[i][j].ToString()) == false)
                        {
                            isEmpty = false;
                            break;
                        }
                    }

                    if (isEmpty == true)
                    {
                        user_mst.Rows.RemoveAt(i);
                        i--;
                    }
                }

                if (user_mst.Rows.Count == 0)
                {
                    //return "null";
                    dr_error = dt_error.NewRow();
                    dr_error["Remark"] = "No data found in Excel.";
                    dt_error.Rows.Add(dr_error);

                    jsondata = GetJson1(dt_error);
                    return return_ajax_data("False", jsondata);
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    DataRow dr_transaction_dtl = dt_response.NewRow();

                    dr_transaction_dtl["user_id"] = user_mst.Rows[i]["REMITTER CODE"].ToString().Trim();
                    dr_transaction_dtl["amount"] = user_mst.Rows[i]["AMOUNT"].ToString().Trim();

                    if (dt_transaction_dtl != null)
                    {
                        DataRow[] dr = dt_transaction_dtl.Select("user_id = '" + user_mst.Rows[i]["REMITTER CODE"].ToString().Trim() + "' and payment_transaction_reference_id = '" + user_mst.Rows[i]["TRANSACTION REF NO"].ToString().Trim() + "'");

                        if (dr.Length > 0)
                        {
                            dr_transaction_dtl["transaction_id"] = dr[0]["transaction_id"].ToString();

                            if (dr[0]["fees_type"].ToString() == "H") dr_transaction_dtl["fees_type"] = "Half";
                            else if (dr[0]["fees_type"].ToString() == "F")
                            {
                                if (Convert.ToInt32(dr[0]["no_of_installment"].ToString()) == 1) dr_transaction_dtl["fees_type"] = "Full";
                                else dr_transaction_dtl["fees_type"] = "Inst " + dr[0]["cash_collected_by"].ToString();
                            }

                            if (dr[0]["payment_response_code"].ToString() == "0")
                            {
                                double amount_to_pay = 0;
                                if (dr[0]["installment" + dr[0]["cash_collected_by"].ToString()].ToString() != "")
                                {
                                    amount_to_pay = Convert.ToDouble(dr[0]["installment" + dr[0]["cash_collected_by"].ToString()].ToString());
                                }

                                if (Convert.ToDouble(user_mst.Rows[i]["AMOUNT"].ToString().Trim()) == amount_to_pay)
                                    dr_transaction_dtl["status"] = "Reconcilled";
                                else
                                    dr_transaction_dtl["status"] = "Amount Mismatch. Amount to pay : " + amount_to_pay;

                                //dr_transaction_dtl["status"] = "Reconcilled";
                            }
                            else
                                dr_transaction_dtl["status"] = "Mismatch. Not updated in system";
                        }
                        else
                            dr_transaction_dtl["status"] = "TransactionID not Found";
                    }
                    else
                        dr_transaction_dtl["status"] = "Trasaction Data not Found for semester";

                    dt_response.Rows.Add(dr_transaction_dtl);
                }

                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return return_ajax_data("False", jsondata);
                }
            }
        }
        catch (Exception ex)
        {
            //return "Problem in save data";
            dr_error = dt_error.NewRow();
            dr_error["Remark"] = "Problem in save data. " + ex.ToString();
            dt_error.Rows.Add(dr_error);

            jsondata = GetJson1(dt_error);
            return return_ajax_data("False", jsondata);
        }

        jsondata = GetJson1(dt_response);
        return return_ajax_data("True", jsondata);
    }

    public string ExcelFileToDatatable_upload_fees_reconciliation_kotak_online(String ExcelFileName, HttpContext context)
    {
        Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
        DataSet ds = new DataSet();

        DataTable dt_response = new DataTable();
        dt_response.Columns.Add("user_id");
        dt_response.Columns.Add("transaction_id");
        //dt_response.Columns.Add("merchant_ref_no");
        dt_response.Columns.Add("amount");
        dt_response.Columns.Add("fees_type");
        dt_response.Columns.Add("status");

        JavaScriptSerializer ser = new JavaScriptSerializer();

        string semester_type = context.Request.Form["semester_type"].ToString();
        string year_code = context.Request.Form["year_code"].ToString();
        string upload_type = context.Request.Form["upload_type"].ToString();
        Dictionary<string, object> session_data = ser.Deserialize<Dictionary<string, object>>(context.Request.Form["session_data"].ToString());

        DSC_Upload_Fee_Collection fee_collection_upload = new DSC_Upload_Fee_Collection();
        //DSC_fees_status fees_status = new DSC_fees_status();

        String sConnectionString = String.Empty;

        dt_error.Columns.Add("Excel_RowNo");
        dt_error.Columns.Add("User_Id");
        dt_error.Columns.Add("Remark");

        if (upload_type != "kotak_online")
        {
            dr_error = dt_error.NewRow();
            dr_error["Excel_RowNo"] = "";
            dr_error["User_Id"] = "";
            dr_error["Remark"] = "Upload Type Not Matched";
            dt_error.Rows.Add(dr_error);
        }

        string path = Server.MapPath("~/UploadFiles") + "\\" + ExcelFileName;

        OleDbConnection objConn = new OleDbConnection(sConnectionString);
        try
        {
            if (Path.GetExtension(ExcelFileName).ToLower() == ".xls")
                sConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + path + "; Extended Properties=Excel 8.0;";
            else
                sConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + path + ";Extended Properties=\"Excel 12.0 Xml;HDR=YES\"";

            objConn.ConnectionString = sConnectionString;
            try
            {
                objConn.Open();
            }
            catch (Exception ex)
            {
            }

            DataTable tables = objConn.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, new object[] { null, null, null, "TABLE" });
            OleDbCommand cmd = new OleDbCommand();
            cmd.Connection = objConn;
            OleDbDataAdapter adp = new OleDbDataAdapter(cmd);

            if (tables != null && tables.Rows.Count > 0)
            {
                DataTable[] excelSheetTables = new DataTable[tables.Rows.Count];
                int CurrentTable = 0;

                foreach (DataRow dr in tables.Rows)
                {
                    //if (!dr["TABLE_NAME"].ToString().Contains("$"))

                    if (!dr["TABLE_NAME"].ToString().Contains("xlnm#_FilterDatabase") && !dr["TABLE_NAME"].ToString().EndsWith("_"))
                    {
                        cmd.CommandText = "select * from [" + dr["TABLE_NAME"].ToString() + "]";
                        excelSheetTables[CurrentTable] = new DataTable(dr["TABLE_NAME"].ToString());
                        adp.Fill(excelSheetTables[CurrentTable]);
                        CurrentTable++;
                    }
                }

                foreach (DataTable singleTable in excelSheetTables)
                {
                    if (singleTable != null)
                    {
                        ds.Tables.Add(singleTable);
                    }
                }

                DataTable dt_transaction_dtl = objmaster.get_icici_citrus_data(semester_type, year_code);

                user_mst = ds.Tables[0];

                if (!user_mst.Columns.Contains("Order No") && !user_mst.Columns.Contains("Order No.") && !user_mst.Columns.Contains("Order No#"))
                {
                    dr_error = dt_error.NewRow();
                    dr_error["Excel_RowNo"] = "1"; dr_error["Remark"] = "'Order No' column not found";
                    dt_error.Rows.Add(dr_error);
                }
                else
                {
                    if (user_mst.Columns.Contains("Order No.")) user_mst.Columns["Order No."].ColumnName = "Order No";
                    else if (user_mst.Columns.Contains("Order No#")) user_mst.Columns["Order No#"].ColumnName = "Order No";
                }

                if (!user_mst.Columns.Contains("Settled Amt"))
                {
