            if (eventdata.Count > 0)
            {

                DS_MyCalendar.calendar_eventRow calander_events = obj_mycalander.calendar_event.Newcalendar_eventRow();

                if (eventdata["doc_no"].ToString().Trim() != "")
                {

                    DataTable dt = objmaster.get_all_calendar_event_data_docno_wise(eventdata["doc_no"].ToString().Trim());

                    if (dt != null)
                    {
                        if (dt.Rows.Count > 0)
                        {
                            DataRow dr = dt.Rows[0];

                            //calander_events.created_by = dt.Rows[0]["created_by"].ToString();
                            //calander_events.created_date = Convert.ToDateTime(dt.Rows[0]["created_date"].ToString());
                            //calander_events.created_host = dt.Rows[0]["created_host"].ToString();

                            if (eventdata["cancel_flag"].ToString() == "N")
                            {
                                dr["event"] = eventdata["event"].ToString();
                                dr["event_code"] = eventdata["event_code"].ToString();
                                dr["is_repeated"] = eventdata["is_repeated"].ToString();
                                dr["repeated_days"] = eventdata["repeated_days"].ToString();
                                dr["from_date"] = Convert.ToDateTime(eventdata["from_date"].ToString());
                                dr["to_date"] = Convert.ToDateTime(eventdata["to_date"].ToString());

                                dr["from_time"] = eventdata["from_time"].ToString();
                                dr["to_time"] = eventdata["to_time"].ToString();
                            }


                            dr["cancel_flag"] = eventdata["cancel_flag"].ToString();
                            dr["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                            dr["last_modified_date"] = System.DateTime.Now;
                            dr["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                            obj_mycalander.calendar_event.ImportRow(dr);
                        }
                        else
                        {
                            return "Problem in update event";
                        }

                    }
                    else
                    {
                        return "Problem in update event";
                    }
                }
                else
                {
                    calander_events.doc_no = "1";


                    calander_events.user_id = HttpContext.Current.Session["UserId"].ToString();
                    calander_events._event = eventdata["event"].ToString();
                    calander_events.event_code = eventdata["event_code"].ToString();

                    calander_events.is_repeated = eventdata["is_repeated"].ToString();
                    calander_events.repeated_days = eventdata["repeated_days"].ToString();

                    calander_events.from_date = Convert.ToDateTime(eventdata["from_date"].ToString());
                    calander_events.to_date = Convert.ToDateTime(eventdata["to_date"].ToString());

                    calander_events.from_time = eventdata["from_time"].ToString();
                    calander_events.to_time = eventdata["to_time"].ToString();
                    calander_events.cancel_flag = eventdata["cancel_flag"].ToString();

                    calander_events.created_by = HttpContext.Current.Session["UserId"].ToString();
                    calander_events.created_date = System.DateTime.Now;
                    calander_events.created_host = HttpContext.Current.Request.UserHostName;

                    obj_mycalander.calendar_event.Addcalendar_eventRow(calander_events);
                }


                objBLReturnObject = objMaster.save_calendar_event(obj_mycalander, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            }

        }
        catch (Exception ex)
        {
            return ex.ToString();
        }
        return objBLReturnObject.ServerMessage;

    }

