    [WebMethod(EnableSession = true)]
    public string Save_google_event(string path, HttpContext context)
    {

        try
        {

            IICalendarCollection calendars = iCalendar.LoadFromFile(@"" + path);

            ServerLog.ExceptionLog(calendars[0].Events.Count.ToString());

            Boolean google_file = path.Contains("contacts");

            if (!google_file)
            {
                google_file = path.Contains("group");
            }

            string file_type;

            if (google_file)
            {
                file_type = "contact";
            }
            else
            {
                file_type = "personal";
            }

            var All_events = calendars[0].Events.ToList();



            //  DataTable dt_saved_google_date = objmaster.get_google_calendar_event_data("", "", HttpContext.Current.Session["UserId"].ToString());
            int doc_no = 0;
            for (int i = 0; i < All_events.Count; i++)
            {
                doc_no = i;
                DataRow[] dr;
                DS_MyCalendar.calendar_google_dataRow calander_events = obj_mycalander.calendar_google_data.Newcalendar_google_dataRow();

                DateTime dtStart;
                DateTime dtEnd;

                string a;
                var from_date = "";
                var to_date = "";

                DateTime dtStamp;
                var uid = "";
                DateTime created;
                var description = "";
                DateTime lastModified;
                var location = "";
                var sequence = "";
                var status = "";
                var summary = "";
                var transparency = "";
                var duration = "";
                var from_time = "";
                var to_time = "";

                var end_never = "N";

                int event_occurence = 0, day_offset = 0;
                string is_repeated = "N";
                string repeated_days = "";
                string bymonthday = "";

                DateTime event_created_date = new DateTime();
                DateTime event_modified_date = new DateTime();
                DateTime event_dtStamp = new DateTime();

                string minute = "", hours = "";

                if (All_events[i].UID != null)
                    uid = All_events[i].UID.ToString().Replace("'", "`");

                //if (dt_saved_google_date != null)
                //{
                //    DataRow[] dr = dt_saved_google_date.Select("UID = '" + uid + "'");
                //}

                calander_events.doc_no = doc_no.ToString();

                calander_events.file_type = file_type;

                if (All_events[i].DTStart != null)
                {
                    //if (All_events[i].DTStart.IsUniversalTime)
                    //    dtStart = Convert.ToDateTime(All_events[i].DTStart.ToString().Replace("'", "`"));
                    //else
                    dtStart = Convert.ToDateTime(All_events[i].DTStart.UTC.ToString().Replace("'", "`"));

                    //if (All_events[i].DTStart.Hour.ToString() == "0" && All_events[i].DTStart.Minute.ToString() == "0")
                    if (dtStart.Hour.ToString() == "0" && dtStart.Minute.ToString() == "0")
                    {
                        from_date = dtStart.ToString();
                        from_time = "00:00";
                    }
                    else
                    {
                        //DateTime dt = Convert.ToDateTime(dtStart.Local.ToString());
                        DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(dtStart, TimeZoneInfo.Local);

                        hours = destTime.Hour.ToString();
                        minute = destTime.Minute.ToString();

                        from_date = destTime.ToShortDateString();

                        if (destTime.Hour.ToString() == "0" && destTime.Minute.ToString() == "0")
                        {
                            from_time = "00:00";
                        }
                        else
                        {

                            if (minute == "0")
                            {
                                minute = "00";
                            }
                            if (hours == "0")
                            {
                                hours = "00";
                            }
                            from_time = hours + ":" + minute;
                        }

                        // from_time = destTime.Hour + ":" + destTime.Minute;
                    }

                    calander_events.from_date = Convert.ToDateTime(from_date);
                    calander_events.from_time = from_time;



                }
                if (All_events[i].DTEnd != null)
                {


                    //if (All_events[i].DTEnd.IsUniversalTime)
                    //    dtEnd = Convert.ToDateTime(All_events[i].DTEnd.ToString().Replace("'", "`"));
                    //else
                    dtEnd = Convert.ToDateTime(All_events[i].DTEnd.UTC.ToString().Replace("'", "`"));

                    if (dtEnd.Hour.ToString() == "0" && dtEnd.Minute.ToString() == "0")
                    {


                        //if (All_events[i].IsAllDay == true)
                        //{
                        //    to_date = dtEnd.AddDays(-Convert.ToInt32(All_events[i].Duration)).ToString();
                        //}
                        //else
                        //{
                        to_date = dtEnd.ToString();
                        // }
                        to_time = "00:00";

                    }
                    else
                    {

                        //DateTime dt = Convert.ToDateTime(Convert.ToDateTime(All_events[i].DTEnd.Local.ToString()));
                        DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(dtEnd, TimeZoneInfo.Local);

                        to_date = destTime.ToShortDateString();

                        hours = destTime.Hour.ToString();
                        minute = destTime.Minute.ToString();

                        if (destTime.Hour.ToString() == "0" && destTime.Minute.ToString() == "0")
                        {
                            to_time = "00:00";
                        }
                        else
                        {

                            if (minute == "0")
                            {
                                minute = "00";
                            }
                            if (hours == "0")
                            {
                                hours = "00";
                            }
                            to_time = hours + ":" + minute;
                        }
                    }

                    calander_events.to_time = to_time;

                    if (All_events[i].IsAllDay == true)
                    {

                        if (All_events[i].Duration.Days > 0)
                        {
                            calander_events.to_date = Convert.ToDateTime(to_date).AddDays(-Convert.ToInt32(All_events[i].Duration.Days));
                        }

                    }
                    else
                    {
                        calander_events.to_date = Convert.ToDateTime(to_date);

                    }

                }

                if (All_events[i].RecurrenceRules.Count > 0)
                {
                    // if (All_events[i].RecurrenceRules[0].Until.) 
                    //    dtEnd = Convert.ToDateTime(All_events[i].RecurrenceRules[0].Until.ToString().Replace("'", "`"));
                    //else
                    is_repeated = "Y";

                    //  if (All_events[i].RecurrenceRules[0].Until.ToString() == "01/01/0001 12:00:00 AM")
                    if (All_events[i].RecurrenceRules[0].Until.ToString().Contains("/0001"))
                    {
                        if (All_events[i].RecurrenceRules[0].Count > 0)
                        {
                            event_occurence = All_events[i].RecurrenceRules[0].Count;
                        }
                        else
                        {
                            calander_events.end_never = "Y";
                        }
                    }
                    else
                    {
                        dtEnd = Convert.ToDateTime(All_events[i].RecurrenceRules[0].Until.ToUniversalTime().ToString().Replace("'", "`"));

                        if (dtEnd.Hour.ToString() == "0" && dtEnd.Minute.ToString() == "0")
                        {
                            to_date = dtEnd.ToString();
                            to_time = "00:00";

                        }
                        else
                        {

                            //    DateTime dt = Convert.ToDateTime(Convert.ToDateTime(dtEnd.Local.ToString()));
                            DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(dtEnd, TimeZoneInfo.Local);

                            to_date = destTime.ToShortDateString();

                            hours = destTime.Hour.ToString();
                            minute = destTime.Minute.ToString();

                            if (destTime.Hour.ToString() == "0" && destTime.Minute.ToString() == "0")
                            {
                                to_time = "00:00";
                            }
                            else
                            {

                                if (minute == "0")
                                {
                                    minute = "00";
                                }
                                if (hours == "0")
                                {
                                    hours = "00";
                                }
                                to_time = hours + ":" + minute;
                            }
                        }

                        calander_events.to_date = Convert.ToDateTime(to_date);
                        calander_events.to_time = to_time;

                    }

                    if (All_events[i].RecurrenceRules[0].ByDay.Count > 0)
                    {
                        for (int j = 0; j < All_events[i].RecurrenceRules[0].ByDay.Count; j++)
                        {
                            string day_code = "";
                            switch (All_events[i].RecurrenceRules[0].ByDay[j].DayOfWeek)
                            {
                                case DayOfWeek.Friday:
                                    day_code = "5";
                                    break;
                                case DayOfWeek.Monday:
                                    day_code = "1";
                                    break;
                                case DayOfWeek.Saturday:
                                    day_code = "6";
                                    break;
                                case DayOfWeek.Sunday:
                                    day_code = "0";
                                    break;
                                case DayOfWeek.Thursday:
                                    day_code = "4";
                                    break;
                                case DayOfWeek.Tuesday:
                                    day_code = "2";
                                    break;
                                case DayOfWeek.Wednesday:
                                    day_code = "3";
                                    break;
                                default:
                                    break;
                            }

                            if (repeated_days == "")
                            {
                                repeated_days = day_code;
                            }
                            else
                            {
                                repeated_days = repeated_days + "," + day_code;
                            }


                        }


                        if (All_events[i].RecurrenceRules[0].ByDay[0].Offset > 0)
                        {
                            day_offset = All_events[i].RecurrenceRules[0].ByDay[0].Offset;
                        }


                    }
                    else
                    {

                        if (All_events[i].RecurrenceRules[0].Frequency.ToString() == "Daily")
                        {
                            repeated_days = "0,1,2,3,4,5,6";
                        }
                    }



                    if (All_events[i].RecurrenceRules[0].ByMonthDay.Count > 0)
                    {
                        for (int j = 0; j < All_events[i].RecurrenceRules[0].ByMonthDay.Count; j++)
                        {
                            string day_code = All_events[i].RecurrenceRules[0].ByMonthDay[j].ToString();

                            if (bymonthday == "")
                            {
                                bymonthday = day_code;
                            }
                            else
                            {
                                bymonthday = bymonthday + "," + day_code;
                            }
                        }
                    }


                    calander_events.frequency = All_events[i].RecurrenceRules[0].Frequency.ToString();
                    calander_events.interval = All_events[i].RecurrenceRules[0].Interval.ToString();
                    calander_events.firstDayOfWeek = All_events[i].RecurrenceRules[0].FirstDayOfWeek.ToString();

                }



                if (All_events[i].Created != null)
                {
                    created = Convert.ToDateTime(All_events[i].Created.UTC.ToString().Replace("'", "`"));

                    //     DateTime dt = Convert.ToDateTime(Convert.ToDateTime(created.Local.ToString()));
                    DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(created, TimeZoneInfo.Local);

                    //  event_created_date = destTime;

                    calander_events.event_created_date = destTime.ToString();
                }

                if (All_events[i].LastModified != null)
                {
                    lastModified = Convert.ToDateTime(All_events[i].LastModified.UTC.ToString().Replace("'", "`"));

                    //    DateTime dt = Convert.ToDateTime(Convert.ToDateTime(lastModified.Local.ToString()));
                    DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(lastModified, TimeZoneInfo.Local);

                    // event_modified_date = destTime;

                    calander_events.event_modified_date = destTime.ToString();
                }

                if (All_events[i].DTStamp != null)
                {
                    dtStamp = Convert.ToDateTime(All_events[i].DTStamp.UTC.ToString().Replace("'", "`"));

                    //DateTime dt = Convert.ToDateTime(Convert.ToDateTime(dtStamp.Local.ToString()));
                    DateTime destTime = TimeZoneInfo.ConvertTimeFromUtc(dtStamp, TimeZoneInfo.Local);

                    //  event_dtStamp = destTime;

                    calander_events.dtStamp = destTime.ToString();
                }

                if (All_events[i].Description != null)
                {
                    description = All_events[i].Description.ToString().Replace("'", "`");
                    description = description.Replace('\n', ' ');
                    description = description.Replace('’', '`');
                }

                if (All_events[i].Location != null)
                {
                    location = All_events[i].Location.ToString().Replace("'", "`");
                    location = location.Replace('\n', ' ');
                    location = location.Replace('’', '`');
                }

                if (All_events[i].Sequence != null)
                    sequence = All_events[i].Sequence.ToString().Replace("'", "`");
                if (All_events[i].Status != null)
                    status = All_events[i].Status.ToString().Replace("'", "`");

                if (All_events[i].Summary != null)
                {
                    summary = All_events[i].Summary.ToString().Replace("'", "`");
                    summary = summary.Replace('\n', ' ');
                    summary = summary.Replace('’', '`');
                }

                if (All_events[i].Transparency != null)
                    transparency = All_events[i].Transparency.ToString().Replace("'", "`");
                if (All_events[i].Duration != null)
                    duration = All_events[i].Duration.ToString().Replace("'", "`");

                calander_events.uid = uid;

                calander_events.allDay = All_events[i].IsAllDay.ToString();

                calander_events.is_repeated = is_repeated;
                calander_events.repeated_days = repeated_days;
                calander_events.bymonthday = bymonthday;

                calander_events.description = description;
                calander_events.location = location;
                calander_events._event = summary;
                calander_events.occurrences_count = event_occurence.ToString();
                calander_events.offeset = day_offset.ToString();

                calander_events.sequence = sequence.ToString();
                calander_events.transparency = transparency.ToString();
                calander_events.duration = duration.ToString();

                calander_events.cancel_flag = "N";
                calander_events.user_id = HttpContext.Current.Session["UserId"].ToString();
                calander_events.created_by = HttpContext.Current.Session["UserId"].ToString();
                calander_events.created_date = System.DateTime.Now;
                calander_events.created_host = HttpContext.Current.Request.UserHostName;


                obj_mycalander.calendar_google_data.Addcalendar_google_dataRow(calander_events);

            }

            //  ServerLog.ExceptionLog("2");

            objBLReturnObject = objMaster.save_calendar_google_event(obj_mycalander, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName, file_type);

            //  ServerLog.ExceptionLog("3");
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog(ex.Message.ToString());

            return ex.ToString();
        }
        return objBLReturnObject.ServerMessage;

    }

