    [WebMethod(EnableSession = true)]
    public string get_calendare_report_data(string sem_code, string year_code)
    {
        decimal total_deleted_hrs = 0;
        Dictionary<string, string> obj_data = new Dictionary<string, string>();

        obj_data["sem_code"] = sem_code;
        obj_data["year_code"] = year_code;
        obj_data["user_id"] = HttpContext.Current.Session["UserId"].ToString();

        DataTable get_output_return_val = objmaster.get_output_return_val(obj_data);

        DataTable dt_calendar_data = objmaster.get_calendare_report_data(obj_data);

        DataTable dt_important_class_hrs = objmaster.get_important_class_hrs_calendare_report_data(obj_data);

        DataTable dt_deleted_class_hrs = objmaster.get_deleted_class_hrs_calendare_report_data(obj_data);

        if (dt_deleted_class_hrs != null)
        {
            total_deleted_hrs = Convert.ToDecimal(dt_deleted_class_hrs.Rows[0]["total"]);
        }



        if (dt_calendar_data != null)
        {
            if (dt_important_class_hrs != null)
            {

                DataRow[] dr_class_event = dt_calendar_data.Select("event_code = 'E1'");

                if (dr_class_event.Length > 0)
                {
                    dr_class_event[0]["total"] = Convert.ToDecimal(dr_class_event[0]["total"]) + Convert.ToDecimal(dt_important_class_hrs.Rows[0]["total_hrs"]) - total_deleted_hrs;
                }
                else
                {
                    DataRow dr;

                    dr = dt_calendar_data.NewRow();

                    dr["event_name"] = "Classes";
                    dr["total"] = Convert.ToDecimal(dt_important_class_hrs.Rows[0]["total_hrs"]) - total_deleted_hrs;

                    dt_calendar_data.Rows.Add(dr);
                }
            }
        }
        else
        {
            if (dt_important_class_hrs != null)
            {

                dt_calendar_data = new DataTable();

                dt_calendar_data.Columns.Add("event_name");
                dt_calendar_data.Columns.Add("total");

                DataRow dr;

                dr = dt_calendar_data.NewRow();

                dr["event_name"] = "Classes";
                dr["total"] = Convert.ToDecimal(dt_important_class_hrs.Rows[0]["total_hrs"]) - total_deleted_hrs;

                dt_calendar_data.Rows.Add(dr);

            }
        }

        if (dt_calendar_data != null)
        {
            jsondata = GetJson1(dt_calendar_data);

        }

        return jsondata;
    }

