    [WebMethod(EnableSession = true)]
    public string[] get_course_instructor_data_for_admin_dashboard()
    {
        //long Before = 0, After = 0, Removed = 0, Collected = 0;
        //Before = GC.GetTotalMemory(true);
        //DataTable dt = new DataTable();
        //After = GC.GetTotalMemory(true);
        //dt = new DataTable();
        //Removed = GC.GetTotalMemory(true);
        //dt = null;
        //Collected = GC.GetTotalMemory(true);

        DataTable course_data = objmaster.get_course_instructor_data_for_admin_dashboard(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);
        DataTable remarkcourse_data = objmaster.GetCoruseRemarkStatus(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

        //course_data = null;
        //Removed = GC.GetTotalMemory(true);
        //GC.Collect();
        //Collected = GC.GetTotalMemory(true);

        if (course_data != null)
        {
            DataTable instructor_data = objmaster.Get_course_instructor_data_for_modification(current_ws_sem, current_ws_year, "");
            DataTable dept_data = objmaster.Get_department_data();
            DataTable prog_data = objmaster.Get_programme_data();
            DataTable prog_level_data = objmaster.Get_programme_level_mst_data();

            course_data.Columns.Add("instructor");
            course_data.Columns.Add("faculty");
            course_data.Columns.Add("program");
            course_data.Columns.Add("program_level_code");

            for (int i = 0; i < course_data.Rows.Count; i++)
            {
                DataRow[] instructors = instructor_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                string instructor = "";

                for (int j = 0; j < instructors.Length; j++)
                {
                    instructor = instructor + instructors[j]["instructor_name"] + ", ";
                }

                if (instructor == "")
                {
                    course_data.Rows[i]["instructor"] = instructor;
                }
                else
                {
                    course_data.Rows[i]["instructor"] = instructor.Remove(instructor.Length - 2, 2);
                }

                DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");

                if (dept.Length > 0)
                {
                    course_data.Rows[i]["faculty"] = dept[0]["dept_name"];
                }
                else
                {
                    course_data.Rows[i]["faculty"] = "";
                }

                DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
                if (prog.Length > 0)
                {
                    course_data.Rows[i]["program"] = prog[0]["prog_name"];
                }
                else
                {
                    course_data.Rows[i]["program"] = "";
                }

                DataRow[] prog_level = prog_level_data.Select("prog_level_code = '" + course_data.Rows[i]["prog_level_code"] + "'");
                if (prog_level.Length > 0)
                {
                    course_data.Rows[i]["program_level_code"] = prog_level[0]["prog_level_desc"];
                }
                else
                {
                    course_data.Rows[i]["program_level_code"] = "";
                }
            }

            jsonarray[0] = GetJson1(course_data);
        }

        string ws_sem = "";
        string ws_year = "";

        dt_ws_current_sem = objmaster.Get_ws_cept_current_sem_data();

        if (dt_ws_current_sem != null)
        {
            ws_sem = dt_ws_current_sem.Rows[0]["sem_code"].ToString();
            ws_year = dt_ws_current_sem.Rows[0]["year_code"].ToString();
        }

        DataTable summer_course_data = objmaster.ws_get_course_instructor_data_for_admin_dashboard(HttpContext.Current.Session["UserId"].ToString(), ws_sem, ws_year);

        if (summer_course_data != null)
        {
            jsonarray[1] = GetJson1(summer_course_data);
        }
        if (remarkcourse_data != null)
        {
            jsonarray[2] = GetJson1(remarkcourse_data);
        }
        return jsonarray;
    }

