            if (dt_personal_details.Rows[0]["date_of_join"].ToString() != "")
            {

                dt_personal_details.Rows[0]["Cal_exp"] = (Convert.ToInt16(DateTime.Now.Year)) - Convert.ToInt16(DateTime.Parse(dt_personal_details.Rows[0]["date_of_join"].ToString()).Year);
            }
        }
        if (dt_personal_details != null)
        {
            jsonarray[0] = GetJson1(dt_personal_details);
        }

        if (dt_education_detail != null)
        {
            jsonarray[1] = GetJson1(dt_education_detail);
        }

        if (dt_profile_course_taught_detail != null)
        {
            jsonarray[2] = GetJson1(dt_profile_course_taught_detail);
        }
        else
        {
            DataTable dt_instructor_course_data_all_semester = objmaster.get_instructor_course_data_all_semester(user_id, current_ws_sem, current_ws_year);
            if (dt_instructor_course_data_all_semester != null)
            {
                jsonarray[2] = GetJson1(dt_instructor_course_data_all_semester);
            }
        }

        return jsonarray;
    }

