    [WebMethod(EnableSession = true)]
    public string Save_Feedback_questions_data(string sem_code, string year_code, string feedback_question_type)
    {
        try
        {
            var user_id = HttpContext.Current.Session["UserId"].ToString();
            DataTable dt_Feedback_questions_data = objmaster.Get_Feedback_questions_data(sem_code, year_code, feedback_question_type);

            DS_Feedback_Save entry_questions_data = new DS_Feedback_Save();

            entry_questions_data.EnforceConstraints = false;

            if (feedback_question_type == "FQ")
            {
                for (int i = 0; i < dt_Feedback_questions_data.Rows.Count; i++)
                {
                    DS_Feedback_Save.feedback_instructions_mstRow questions_data = entry_questions_data.feedback_instructions_mst.Newfeedback_instructions_mstRow();
                    questions_data.course_typology = dt_Feedback_questions_data.Rows[i]["course_typology"].ToString();
                    questions_data.course_typology_name = dt_Feedback_questions_data.Rows[i]["course_typology_name"].ToString();
                    questions_data.feedback_instruction = dt_Feedback_questions_data.Rows[i]["feedback_instruction"].ToString();
                    questions_data.sr_no = int.Parse(dt_Feedback_questions_data.Rows[i]["sr_no"].ToString());
                    questions_data.feedback_type = dt_Feedback_questions_data.Rows[i]["feedback_type"].ToString();
                    questions_data.not_applicable = dt_Feedback_questions_data.Rows[i]["not_applicable"].ToString();
                    questions_data.cancel_flag = dt_Feedback_questions_data.Rows[i]["cancel_flag"].ToString();
                    questions_data.semester_type = current_ws_sem;
                    questions_data.year_semester = current_ws_year;
                    questions_data.created_by = user_id;
                    questions_data.created_date = DateTime.Now;
                    questions_data.created_host = HttpContext.Current.Request.UserHostName.ToString();

                    entry_questions_data.feedback_instructions_mst.Addfeedback_instructions_mstRow(questions_data);
                }
                entry_questions_data.EnforceConstraints = true;

                objBLReturnObject = objMaster.save_feedback_instruction_data(entry_questions_data, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }
            else
            {
                for (int i = 0; i < dt_Feedback_questions_data.Rows.Count; i++)
                {
                    DS_Feedback_Save.feedback_instructions_mst_for_chartRow questions_data = entry_questions_data.feedback_instructions_mst_for_chart.Newfeedback_instructions_mst_for_chartRow();
                    questions_data.course_typology = dt_Feedback_questions_data.Rows[i]["course_typology"].ToString();
                    questions_data.course_typology_name = dt_Feedback_questions_data.Rows[i]["course_typology_name"].ToString();
                    questions_data.feedback_instruction = dt_Feedback_questions_data.Rows[i]["feedback_instruction"].ToString();
                    questions_data.sr_no = int.Parse(dt_Feedback_questions_data.Rows[i]["sr_no"].ToString());
                    questions_data.feedback_type = dt_Feedback_questions_data.Rows[i]["feedback_type"].ToString();
                    questions_data.not_applicable = dt_Feedback_questions_data.Rows[i]["not_applicable"].ToString();
                    questions_data.cancel_flag = dt_Feedback_questions_data.Rows[i]["cancel_flag"].ToString();
                    questions_data.semester_type = current_ws_sem;
                    questions_data.year_semester = current_ws_year;
                    questions_data.created_by = user_id;
                    questions_data.created_date = DateTime.Now;
                    questions_data.created_host = HttpContext.Current.Request.UserHostName.ToString();

                    entry_questions_data.feedback_instructions_mst_for_chart.Addfeedback_instructions_mst_for_chartRow(questions_data);
                }
                entry_questions_data.EnforceConstraints = true;

                objBLReturnObject = objMaster.save_feedback_instruction_chat_data(entry_questions_data, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

