    /// <summary>
    ///  Save All User Wise Email Id
    /// </summary>
    /// <param name="student_userid_emailid"></param>
    /// <returns></returns>

    [WebMethod(EnableSession = true)]
    public string save_all_userid_emailid(string student_userid_emailid)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(student_userid_emailid);

            DSC_userdataupload userdataupload = new DSC_userdataupload();

            for (int i = 0; i < data.Count; i++)
            {
                DSC_userdataupload.test_replacement_userRow test_replacement_user_row = userdataupload.test_replacement_user.Newtest_replacement_userRow();

                test_replacement_user_row.old_user_id = data[i]["old_user_id"].ToString();
                test_replacement_user_row.new_user_id = data[i]["new_user_id"].ToString();
                test_replacement_user_row.old_email_id = data[i]["old_email_id"].ToString();
                test_replacement_user_row.new_email_id = data[i]["new_email_id"].ToString();

                userdataupload.test_replacement_user.Addtest_replacement_userRow(test_replacement_user_row);
            }

            objBLReturnObject = objMaster.save_all_userid_emailid(userdataupload, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

