                        dr_error["Excel_RowNo"] = "1";
                        dr_error["User_Id"] = "Column 4";
                        dr_error["Remark"] = "'" + user_mst.Columns[3].ColumnName + "' is not a valid column name";

                        dt_error.Rows.Add(dr_error);
                    }
                }
                else
                {
