    /// <summary>
    /// Course List Insert
    /// </summary>
    /// <param name="sem_code"></param>
    /// <param name="year_code"></param>
    /// <returns></returns>
    [WebMethod(EnableSession = true)]
    public string get_selected_course_list_for_insert(string sem_code, string year_code)
    {

        //  string value = "Your ide is cute.";

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        int flag = 0;
        DataTable course_data = new DataTable();

        dt_ws_current_sem = objmaster.Get_cept_current_sem_data("course");

        if (dt_ws_current_sem != null)
        {
            current_ws_sem = dt_ws_current_sem.Rows[0]["sem_code"].ToString();
            current_ws_year = dt_ws_current_sem.Rows[0]["year_code"].ToString();
        }

        course_data = objmaster.get_selected_course_list_for_insert(user_id, user_type, user_prog_code, sem_code, year_code, current_ws_sem, current_ws_year);

        DataTable pending_approval_list = new DataTable();

        if (course_data != null)
        {

            try
            {
                if (course_data != null)
                {
                    if (course_data.Rows.Count > 0)
                    {
                        flag = 1;
                    }
                }
            }
            catch (Exception e)
            {
                return e.Message.ToString();
            }

            if (flag == 1)
            {
                DataTable instructor_data = objmaster.Get_course_instructor_data_for_modification(sem_code, year_code, "");
                DataTable area_data = objmaster.Get_course_area_data_for_modification(sem_code, year_code, "");
                DataTable time_data = objmaster.Get_course_time_day_data_for_modification(sem_code, year_code, "");
                DataTable type_data = objmaster.Get_typology_data();
                DataTable dept_data = objmaster.Get_department_data();
                DataTable prog_data = objmaster.Get_programme_data();
                DataTable prog_level_data = objmaster.Get_programme_level_mst_data();

                pending_approval_list.Columns.Add("course_code");
                pending_approval_list.Columns.Add("type");
                pending_approval_list.Columns.Add("course_type");
                pending_approval_list.Columns.Add("title");
                pending_approval_list.Columns.Add("credit");
                pending_approval_list.Columns.Add("occurence_week");
                pending_approval_list.Columns.Add("course_outline");
                pending_approval_list.Columns.Add("instructor");
                pending_approval_list.Columns.Add("course_desc");
                pending_approval_list.Columns.Add("prerequisite");
                pending_approval_list.Columns.Add("faculty");
                pending_approval_list.Columns.Add("program");
                pending_approval_list.Columns.Add("program_level_code");
                pending_approval_list.Columns.Add("semester");
                pending_approval_list.Columns.Add("day");
                pending_approval_list.Columns.Add("time");
                pending_approval_list.Columns.Add("area");
                pending_approval_list.Columns.Add("intake");
                pending_approval_list.Columns.Add("remark");
                pending_approval_list.Columns.Add("faculty_approval");
                pending_approval_list.Columns.Add("progcoord_approval");
                pending_approval_list.Columns.Add("ugpg_approval");

                for (int i = 0; i < course_data.Rows.Count; i++)
                {
                    DataRow dr = pending_approval_list.NewRow();

                    dr["course_code"] = course_data.Rows[i]["course_code"];

                    DataRow[] type = type_data.Select("type_code = '" + course_data.Rows[i]["course_typology"] + "'");
                    if (type.Length > 0)
                    {
                        dr["type"] = type[0]["type_name"];
                    }
                    else
                    {
                        dr["type"] = "";
                    }

                    dr["course_type"] = course_data.Rows[i]["course_type"];
                    dr["title"] = course_data.Rows[i]["course_name"];
                    dr["credit"] = course_data.Rows[i]["course_credits"];
                    dr["occurence_week"] = course_data.Rows[i]["occurrence_week"];
                    dr["course_outline"] = course_data.Rows[i]["course_outline"];

                    DataRow[] instructors = instructor_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                    string instructor = "";
                    for (int j = 0; j < instructors.Length; j++)
                    {
                        instructor = instructor + instructors[j]["instructor_name"] + ", ";
                    }
                    if (instructor == "")
                    {
                        dr["instructor"] = instructor;
                    }
                    else
                    {

                        dr["instructor"] = instructor.Remove(instructor.Length - 2, 2);
                    }

                    dr["course_desc"] = course_data.Rows[i]["course_desc"];
                    dr["prerequisite"] = course_data.Rows[i]["prerequisite"];

                    DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");
                    if (dept.Length > 0)
                    {
                        dr["faculty"] = dept[0]["dept_name"];
                    }
                    else
                    {
                        dr["faculty"] = "";
                    }

                    DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
                    if (prog.Length > 0)
                    {
                        dr["program"] = prog[0]["prog_name"];
                    }
                    else
                    {
                        dr["program"] = "";
                    }

                    DataRow[] prog_level = prog_level_data.Select("prog_level_code = '" + course_data.Rows[i]["prog_level_code"] + "'");
                    if (prog_level.Length > 0)
                    {
                        dr["program_level_code"] = prog_level[0]["prog_level_desc"];
                    }
                    else
                    {
                        dr["program_level_code"] = "";
                    }

                    dr["semester"] = course_data.Rows[i]["semester_code"];

                    DataRow[] daytimes = time_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                    string day = "";
                    string time = "";
                    for (int j = 0; j < daytimes.Length; j++)
                    {
                        day = day + daytimes[j]["day_name"] + ", ";
                        time = time + daytimes[j]["from_time"] + "-" + daytimes[j]["To_time"] + ", ";
                    }
                    if (day == "")
                    {
                        dr["day"] = day;
                    }
                    else
                    {
                        dr["day"] = day.Remove(day.Length - 2, 2);
                    }
                    if (time == "")
                    {
                        dr["time"] = time;
                    }
                    else
                    {
                        dr["time"] = time.Remove(time.Length - 2, 2);
                    }

                    string area = "";
                    if (area_data != null)
                    {
                        DataRow[] areas = area_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        for (int j = 0; j < areas.Length; j++)
                        {
                            area = area + areas[j]["area_name"] + ", ";
                        }
                    }

                    if (area == "")
                    {
                        dr["area"] = area;
                    }
                    else
                    {
                        dr["area"] = area.Remove(area.Length - 2, 2);
                    }

                    dr["intake"] = course_data.Rows[i]["available_seat"];
                    dr["remark"] = course_data.Rows[i]["remark"];


                    pending_approval_list.Rows.Add(dr);
                }
            }
        }

        if (pending_approval_list != null && pending_approval_list.Rows.Count > 0)
        {
            jsondata = GetJson1(pending_approval_list);
        }

        return jsondata;
    }

    /// <summary>
    /// Save Old Sem Data
    /// </summary>
    /// <param name="selected_course"></param>
    /// <param name="semester"></param>
    /// <param name="year"></param>
    /// <returns></returns>
    [WebMethod(EnableSession = true)]
    public string save_selected_data_from_old_semester(string selected_course, string semester, string year)
    {
        // Save Compliance Details in compliance_entry table.
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        string sem_code = "";
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            DSC_Course_Master course_master_upload = new DSC_Course_Master();

            string d_course_code = "";
            List<Dictionary<string, object>> course_data = ser.Deserialize<List<Dictionary<string, object>>>(selected_course);

            if (course_data.Count > 0)
            {
                dt_ws_current_sem = objmaster.Get_cept_current_sem_data("course");

                if (dt_ws_current_sem != null)
                {
                    current_ws_sem = dt_ws_current_sem.Rows[0]["sem_code"].ToString();
                    current_ws_year = dt_ws_current_sem.Rows[0]["year_code"].ToString();
                }

                for (int cd = 0; cd < course_data.Count; cd++)
                {

                    d_course_code = course_data[cd]["course_code"].ToString();

                    //    List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(mandatory_time);
                    DataTable cur_sem = objmaster.Get_Current_Semester_Detail();

                    DataTable course_mst_detail = objmaster.Get_course_data_for_modification(semester, year, d_course_code);

                    //DSC_Course_Master.course_mstRow course_mst_row = course_master_upload.course_mst.Newcourse_mstRow();

                    if (course_mst_detail != null)
                    {
                        DSC_Course_Master.course_mstRow course_mst_data_row = course_master_upload.course_mst.Newcourse_mstRow();

                        course_mst_data_row.ItemArray = course_mst_detail.Rows[0].ItemArray;

                        course_mst_data_row.faculty_approved = "N";
                        course_mst_data_row.progcoordinate_approved = "N";
                        course_mst_data_row.ugpgoffice_approved = "N";
                        course_mst_data_row.cancel_flag = "Y";
                        course_mst_data_row.created_by = HttpContext.Current.Session["UserId"].ToString() + "-" + "Added from selection";
                        course_mst_data_row.created_date = System.DateTime.Now;
                        course_mst_data_row.created_host = HttpContext.Current.Request.UserHostName;
                        course_mst_data_row.semester_type = current_ws_sem;
                        course_mst_data_row.year_semester = current_ws_year;

                        course_master_upload.course_mst.Addcourse_mstRow(course_mst_data_row);
                        // course_master_upload.course_mst.AcceptChanges();
                    }


                    // // 

                    // // Department Wise Course Detail

                    DataTable course_dept_data = objmaster.Get_course_department_data_for_modification(semester, year, d_course_code);

                    if (course_dept_data != null)
                    {
                        DSC_Course_Master.department_wise_course_dtlRow course_dept_data_row = course_master_upload.department_wise_course_dtl.Newdepartment_wise_course_dtlRow();

                        course_dept_data_row.ItemArray = course_dept_data.Rows[0].ItemArray;

                        course_dept_data_row.cancel_flag = "Y";
                        course_dept_data_row.created_by = HttpContext.Current.Session["UserId"].ToString() + "-" + "Added from selection";
                        course_dept_data_row.created_date = System.DateTime.Now;
                        course_dept_data_row.created_host = HttpContext.Current.Request.UserHostName;
                        course_dept_data_row.semester_type = current_ws_sem;
                        course_dept_data_row.year_semester = current_ws_year;

                        course_master_upload.department_wise_course_dtl.Adddepartment_wise_course_dtlRow(course_dept_data_row);
                    }

                    // // 

                    // // Course Wise Instructor
                    DataTable course_instructor_data = objmaster.Get_course_instructor_data_for_modification(semester, year, d_course_code);
                    DataRow[] dr_course_instructor_data = course_instructor_data.Select("cancel_flag='N'");

                    if (dr_course_instructor_data.Length > 0)
                    {
                        course_instructor_data = dr_course_instructor_data.CopyToDataTable();

                        if (course_instructor_data != null)
                        {
                            course_instructor_data.Columns.Remove("instructor_name");

                            for (int i = 0; i < course_instructor_data.Rows.Count; i++)
                            {
                                DSC_Course_Master.course_wise_instructorRow course_wise_instructor_row = course_master_upload.course_wise_instructor.Newcourse_wise_instructorRow();

                                course_wise_instructor_row.ItemArray = course_instructor_data.Rows[i].ItemArray;

                                course_wise_instructor_row.cancel_flag = "Y";
                                course_wise_instructor_row.created_by = HttpContext.Current.Session["UserId"].ToString() + "-" + "Added from selection";
                                course_wise_instructor_row.created_date = System.DateTime.Now;
                                course_wise_instructor_row.created_host = HttpContext.Current.Request.UserHostName;
                                course_wise_instructor_row.semester_type = current_ws_sem;
                                course_wise_instructor_row.year_semester = current_ws_year;

                                course_master_upload.course_wise_instructor.Addcourse_wise_instructorRow(course_wise_instructor_row);
                            }
                        }
                    }

                    // // 

                    // // Course Wise Area
                    DataTable course_area_data = objmaster.Get_course_area_data_for_modification(semester, year, d_course_code);
                    DataRow[] dr_course_area_data = course_area_data.Select("cancel_flag='N'");

                    if (dr_course_area_data.Length > 0)
                    {
                        course_area_data = dr_course_area_data.CopyToDataTable();

                        if (course_area_data != null)
                        {
                            course_area_data.Columns.Remove("area_name");

                            for (int i = 0; i < course_area_data.Rows.Count; i++)
                            {
                                DSC_Course_Master.course_wise_areaRow course_wise_area_row = course_master_upload.course_wise_area.Newcourse_wise_areaRow();

                                course_wise_area_row.ItemArray = course_area_data.Rows[i].ItemArray;

                                course_wise_area_row.cancel_flag = "Y";
                                course_wise_area_row.created_by = HttpContext.Current.Session["UserId"].ToString() + "-" + "Added from selection";
                                course_wise_area_row.created_date = System.DateTime.Now.ToString();
                                course_wise_area_row.created_host = HttpContext.Current.Request.UserHostName;
                                course_wise_area_row.semester_type = current_ws_sem;
                                course_wise_area_row.year_semester = current_ws_year;

                                course_master_upload.course_wise_area.Addcourse_wise_areaRow(course_wise_area_row);
                            }
                        }
                    }
                    // //
                    // // Course Wise Time
                    DataTable course_time_data = objmaster.Get_course_time_day_data_for_modification(semester, year, d_course_code);

                    DataRow[] dr_course_time_data = course_time_data.Select("cancel_flag='N'");

                    if (dr_course_time_data.Length > 0)
                    {
                        course_time_data = dr_course_time_data.CopyToDataTable();

                        if (course_time_data != null)
                        {
                            course_time_data.Columns.Remove("day_name");

                            for (int i = 0; i < course_time_data.Rows.Count; i++)
                            {
                                DSC_Course_Master.course_wise_timeRow course_wise_time_row = course_master_upload.course_wise_time.Newcourse_wise_timeRow();

                                course_wise_time_row.ItemArray = course_time_data.Rows[i].ItemArray;

                                course_wise_time_row.cancel_flag = "Y";
                                course_wise_time_row.created_by = HttpContext.Current.Session["UserId"].ToString() + "-" + "Added from selection";
                                course_wise_time_row.created_date = System.DateTime.Now.ToString();
                                course_wise_time_row.created_host = HttpContext.Current.Request.UserHostName;
                                course_wise_time_row.semester_type = current_ws_sem;
                                course_wise_time_row.year_semester = current_ws_year;
                                course_master_upload.course_wise_time.Addcourse_wise_timeRow(course_wise_time_row);
                            }
                        }
                    }
                    // // 
                }
                objBLReturnObject = objMaster.save_selected_data_from_old_semester(course_master_upload, "2000", user_id, HttpContext.Current.Request.UserHostName);
            }
            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
        //return "";

    }

