    /// <summary>
    /// Get Fees Details 
    /// </summary>
    /// <param name="fees_data"></param>
    /// <returns></returns>

    [WebMethod(EnableSession = true)]
    public string get_fees_bank_detail(string fees_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        Dictionary<string, object> obj_fees_dtl = ser.Deserialize<Dictionary<string, object>>(fees_data);

        string message = "";
        if (obj_fees_dtl["semester_type"] == null || obj_fees_dtl["semester_type"].ToString() == "") { message = "Please Select Semester"; }
        if (obj_fees_dtl["year_semester"] == null || obj_fees_dtl["year_semester"].ToString() == "") { message = "Please Select Year"; }
        if (obj_fees_dtl["dept_code"] == null || obj_fees_dtl["dept_code"].ToString() == "") { message = "Please Select Department"; }
        if (obj_fees_dtl["prog_code"] == null || obj_fees_dtl["prog_code"].ToString() == "") { message = "Please Select Program"; }
        if (obj_fees_dtl["year_code"] == null || obj_fees_dtl["year_code"].ToString() == "") { message = "Please Select Allocation Year"; }

        if (message == "")
        {
            DataTable fees_bank_detail = objmaster.get_fees_bank_dtl(obj_fees_dtl);

            if (fees_bank_detail != null)
            {
                jsondata = GetJson1(fees_bank_detail);
            }
        }

        return jsondata;
    }
    /// <summary>
    /// Save Bank Details
    /// </summary>
    /// <param name="fees_data"></param>
    /// <returns></returns>
    [WebMethod(EnableSession = true)]
    public string save_fees_bank_detail(string fees_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> obj_fees_dtl = ser.Deserialize<Dictionary<string, object>>(fees_data);

            string message = "";
            if (obj_fees_dtl["semester_type"] == null || obj_fees_dtl["semester_type"].ToString() == "") { message = "Please Select Semester"; }
            if (obj_fees_dtl["year_semester"] == null || obj_fees_dtl["year_semester"].ToString() == "") { message = "Please Select Year"; }
            if (obj_fees_dtl["dept_code"] == null || obj_fees_dtl["dept_code"].ToString() == "") { message = "Please Select Department"; }
            if (obj_fees_dtl["prog_code"] == null || obj_fees_dtl["prog_code"].ToString() == "") { message = "Please Select Program"; }
            if (obj_fees_dtl["year_code"] == null || obj_fees_dtl["year_code"].ToString() == "") { message = "Please Select Allocation Year"; }

            if (message != "")
            {
                jsondata = return_ajax_string("False", message);
                return jsondata;
            }

            DataTable get_fees_dtl = objmaster.get_fees_bank_dtl(obj_fees_dtl);

            DSC_FeesBankDetail fees_bank_dtl = new DSC_FeesBankDetail();

            if (get_fees_dtl != null)
            {
                jsondata = return_ajax_string("False", "Fees detail already Found");
            }
            else
            {
                DSC_FeesBankDetail.fees_bank_dtlRow fees_row1 = fees_bank_dtl.fees_bank_dtl.Newfees_bank_dtlRow();

                fees_row1.doc_no = "new1";
                fees_row1.dept_code = obj_fees_dtl["dept_code"].ToString();
                fees_row1.prog_code = obj_fees_dtl["prog_code"].ToString();
                fees_row1.bank_code = obj_fees_dtl["bank_code"].ToString();

                DSC_FeesBankDetail.fees_bank_dtlRow fees_row2 = fees_bank_dtl.fees_bank_dtl.Newfees_bank_dtlRow();

                fees_row2.doc_no = "new2";
                fees_row2.dept_code = obj_fees_dtl["dept_code"].ToString();
                fees_row2.prog_code = obj_fees_dtl["prog_code"].ToString();
                fees_row2.bank_code = obj_fees_dtl["bank_code"].ToString();

                fees_bank_dtl.fees_bank_dtl.Addfees_bank_dtlRow(fees_row1);
                fees_bank_dtl.fees_bank_dtl.Addfees_bank_dtlRow(fees_row2);

                for (int i = 0; i < 2; i++)
                {
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["dept_code"] = obj_fees_dtl["dept_code"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["prog_code"] = obj_fees_dtl["prog_code"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["account_name"] = obj_fees_dtl["account_name"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["bank_code"] = obj_fees_dtl["bank_code"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["year"] = obj_fees_dtl["year"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["year_code"] = obj_fees_dtl["year_code"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["semester_code"] = obj_fees_dtl["semester_code"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["semester_type"] = obj_fees_dtl["semester_type"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["year_semester"] = obj_fees_dtl["year_semester"].ToString();

                    fees_bank_dtl.fees_bank_dtl.Rows[i]["fine"] = obj_fees_dtl["fine"].ToString();
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["fine2"] = obj_fees_dtl["fine2"].ToString();

                    String startdate = obj_fees_dtl["start_date"].ToString();
                    if (startdate != null && startdate != string.Empty)
                    {
                        string[] sttime = startdate.ToString().Split('-');
                        string gh21 = sttime[2].ToString() + "/" + sttime[1].ToString() + "/" + sttime[0].ToString();
                        DateTime dt = Convert.ToDateTime(gh21);
                        String stdate = dt.ToString();

                        fees_bank_dtl.fees_bank_dtl.Rows[i]["start_date"] = stdate;
                    }
                    else
                    {
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["start_date"] = null;
                    }
                    //Convert.ToDateTime(obj_fees_dtl["start_date"].ToString());

                    String enddate = obj_fees_dtl["end_date"].ToString();
                    if (enddate != null && enddate != string.Empty)
                    {
                        string[] endtime = enddate.ToString().Split('-');
                        string gh22 = endtime[2].ToString() + "/" + endtime[1].ToString() + "/" + endtime[0].ToString();
                        DateTime dt_ = Convert.ToDateTime(gh22);
                        String endate = dt_.ToString();
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date"] = endate;
                    }
                    else
                    {
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date"] = null;
                    }

                    String enddate2 = obj_fees_dtl["end_date2"].ToString();
                    if (enddate2 != null && enddate2 != string.Empty)
                    {
                        string[] endtime2 = enddate2.ToString().Split('-');
                        string set_format_2 = endtime2[2].ToString() + "/" + endtime2[1].ToString() + "/" + endtime2[0].ToString();
                        DateTime dt2_ = Convert.ToDateTime(set_format_2);
                        String endate = dt2_.ToString();
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date2"] = endate;
                    }
                    else
                    {
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date2"] = obj_fees_dtl["end_date2"].ToString();
                    }

                    String enddate3 = obj_fees_dtl["end_date3"].ToString();
                    if (enddate3 != null && enddate3 != string.Empty)
                    {
                        string[] endtime3 = enddate3.ToString().Split('-');
                        string set_format_3 = endtime3[2].ToString() + "/" + endtime3[1].ToString() + "/" + endtime3[0].ToString();
                        DateTime dt3_ = Convert.ToDateTime(set_format_3);
                        String endate = dt3_.ToString();
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date3"] = endate;
                    }
                    else
                    {
                        fees_bank_dtl.fees_bank_dtl.Rows[i]["end_date3"] = obj_fees_dtl["end_date3"].ToString();
                    }

                    //Convert.ToDateTime(obj_fees_dtl["end_date"].ToString());

                    fees_bank_dtl.fees_bank_dtl.Rows[i]["deposit"] = "0";
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["fees1"] = "0";
                    fees_bank_dtl.fees_bank_dtl.Rows[i]["cancel_flag"] = "N";
                }
                fees_bank_dtl.fees_bank_dtl.Rows[0]["gender"] = "M";
                fees_bank_dtl.fees_bank_dtl.Rows[0]["fees"] = obj_fees_dtl["male_fees"].ToString();
                fees_bank_dtl.fees_bank_dtl.Rows[1]["gender"] = "F";
                fees_bank_dtl.fees_bank_dtl.Rows[1]["fees"] = obj_fees_dtl["female_fees"].ToString();

                objBLReturnObject = objMaster.save_fees_bank_dtl(fees_bank_dtl, "2000", user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in save data " + objBLReturnObject.ServerMessage;
                    //jsondata = return_ajax_string("False", "Problem in save data, Please try again");
                    jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                }
                else if (objBLReturnObject.ExecutionStatus == 1)
                {
                    jsondata = return_ajax_string("True", "Fees Saved Successfully");
                }
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }
        return jsondata;
    }

