    /// <summary>
    /// Excel File Upload Fees Bank Detaile
    /// </summary>
    /// <param name="ExcelFileName"></param>
    /// <param name="context"></param>
    /// <returns></returns>
    public string ExcelFileToDatatable_upload_fees_bank_dtl(String ExcelFileName, HttpContext context)
    {
        Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
        DataSet ds = new DataSet();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        string semester_type = context.Request.Form["semester_type"].ToString();
        string year_code = context.Request.Form["year_code"].ToString();

        String sConnectionString = String.Empty;

        dt_error.Columns.Add("Excel_RowNo");
        dt_error.Columns.Add("User_Id");
        dt_error.Columns.Add("Remark");

        string path = Server.MapPath("~/UploadFiles") + "\\" + ExcelFileName;

        OleDbConnection objConn = new OleDbConnection(sConnectionString);

        try
        {
            DataTable dt1 = new DataTable();

            if (Path.GetExtension(ExcelFileName).ToLower() == ".csv")
            {
                using (StreamReader sr = new StreamReader(path))
                {
                    string[] headers = sr.ReadLine().Split(',');
                    foreach (string header in headers)
                    {
                        dt1.Columns.Add(header.Replace('"', ' ').Trim());
                    }
                    while (!sr.EndOfStream)
                    {
                        string[] rows = sr.ReadLine().Split(',');
                        DataRow dr = dt1.NewRow();
                        for (int i = 0; i < headers.Length; i++)
                        {
                            dr[i] = rows[i].Replace('"', ' ').Trim();
                        }
                        dt1.Rows.Add(dr);
                    }

                }
            }

            else
            {
                if (Path.GetExtension(ExcelFileName).ToLower() == ".xls")
                    sConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + path + "; Extended Properties=Excel 8.0;";
                else if (Path.GetExtension(ExcelFileName).ToLower() == ".xlsx")
                    sConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + path + ";Extended Properties=\"Excel 12.0 Xml;HDR=YES\"";

                objConn.ConnectionString = sConnectionString;
                try
                {
                    objConn.Open();
                }
                catch (Exception ex)
                {
                }

                DataTable tables = objConn.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, new object[] { null, null, null, "TABLE" });
                OleDbCommand cmd = new OleDbCommand();
                cmd.Connection = objConn;
                OleDbDataAdapter adp = new OleDbDataAdapter(cmd);

                if (tables != null && tables.Rows.Count > 0)
                {
                    DataTable[] excelSheetTables = new DataTable[tables.Rows.Count];
                    int CurrentTable = 0;

                    foreach (DataRow dr in tables.Rows)
                    {
                        if (!dr["TABLE_NAME"].ToString().Contains("xlnm#_FilterDatabase") && !dr["TABLE_NAME"].ToString().EndsWith("_"))
                        {
                            cmd.CommandText = "select * from [" + dr["TABLE_NAME"].ToString() + "]";
                            excelSheetTables[CurrentTable] = new DataTable(dr["TABLE_NAME"].ToString());
                            adp.Fill(excelSheetTables[CurrentTable]);
                            CurrentTable++;
                        }
                    }

                    foreach (DataTable singleTable in excelSheetTables)
                    {
                        if (singleTable != null)
                        {
                            ds.Tables.Add(singleTable);
                        }
                    }
                }

            }

            DataTable fees_bank_detail = objmaster.get_all_fees_bank_detail(semester_type, year_code, "", "");

            if (Path.GetExtension(ExcelFileName).ToLower() == ".csv")
            {
                user_mst = dt1.Copy();
            }
            else
            {
                user_mst = ds.Tables[0];
            }


            for (int i = 0; i < user_mst.Columns.Count; i++)
            {
                switch (user_mst.Columns[i].ColumnName.ToLower())
                {
                    case "department": break;
                    case "program": break;
                    case "account_name": break;
                    case "bank_code": break;
                    case "allocation_year": break;
                    case "semester_code": break;
                    case "male_fees": break;
                    case "female_fees": break;
                    case "semester": break;
                    case "year_semester": break;
                    case "upto_7_days_fine": break;
                    case "upto_84_days_fine": break;
                    case "start_date": break;
                    case "end_date": break;
                    case "installment1": break;
                    case "installment2": break;
                    case "installment3": break;
                    case "installment4": break;
                    case "end_date2": break;
                    case "end_date3": break;
                    case "nationality": break;


                    default:
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = "1";
                            dr_error["User_Id"] = "Column " + (i + 1);
                            dr_error["Remark"] = "'" + user_mst.Columns[i].ColumnName + "' is not a valid column name";

                            dt_error.Rows.Add(dr_error);
                            break;
                        }
                }
            }

            if (dt_error.Rows.Count > 0)
            {
                jsondata = GetJson1(dt_error);
                return jsondata;
            }

            for (int i = 0; i < user_mst.Rows.Count; i++)
            {
                isEmpty = true;
                for (int j = 0; j < user_mst.Columns.Count; j++)
                {
                    if (string.IsNullOrEmpty(user_mst.Rows[i][j].ToString()) == false)
                    {
                        isEmpty = false;
                        break;
                    }
                }
                if (isEmpty == true)
                {
                    user_mst.Rows.RemoveAt(i);
                    i--;
                }
            }

            if (user_mst.Rows.Count == 0)
            {
                return "null";
            }

            DSC_FeesBankDetail fees_bank_dtl = new DSC_FeesBankDetail();
            int cnt = 0;
            for (int i = 0; i < user_mst.Rows.Count; i++)
            {
                string dept_code = "";
                string prog_code = "";

                for (int j = 0; j < user_mst.Columns.Count; j++)
                {
                    string col_name = user_mst.Columns[j].ColumnName.ToString();

                    if (user_mst.Rows[i][col_name].ToString().Trim() == "")
                    {
                        if (user_mst.Rows[i]["upto_84_days_fine"].ToString().Trim() == "")
                        {
                        }
                        else
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            dr_error["User_Id"] = "" + col_name;
                            dr_error["Remark"] = "Please enter " + col_name + "";

                            dt_error.Rows.Add(dr_error);
                        }
                    }
                }

                if (user_mst.Rows[i]["semester"].ToString().Trim() != semester_type.ToString().Trim())
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                    dr_error["User_Id"] = "Semester";
                    dr_error["Remark"] = "Semester Mismatch";

                    dt_error.Rows.Add(dr_error);
                }

                if (user_mst.Rows[i]["year_semester"].ToString().Trim() != year_code.ToString().Trim())
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                    dr_error["User_Id"] = "Year_semester";
                    dr_error["Remark"] = "Year_semester Mismatch";

                    dt_error.Rows.Add(dr_error);
                }

                switch (user_mst.Rows[i]["department"].ToString().Trim())
                {
                    case "Architecture": dept_code = "1"; break;
                    case "Design": dept_code = "2"; break;
                    case "Management": dept_code = "3"; break;
                    case "Planning": dept_code = "4"; break;
                    case "Technology": dept_code = "5"; break;
                    default:
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            dr_error["User_Id"] = "department";
                            dr_error["Remark"] = "Invalid Department";

                            dt_error.Rows.Add(dr_error);
                            break;
                        }
                }

                switch (user_mst.Rows[i]["program"].ToString().Trim())
                {
                    case "UG": prog_code = "1"; break;
                    case "PG": prog_code = "2"; break;
                    case "Doctoral": prog_code = "3"; break;
                    default:
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            dr_error["User_Id"] = "program";
                            dr_error["Remark"] = "Invalid Program";

                            dt_error.Rows.Add(dr_error);
                            break;
                        }
                }

                string allocation_year = "";

                if (user_mst.Rows[i]["allocation_year"].ToString().Trim() == "2013")
                {
                    allocation_year = "Y1";
                }
                else
                {
                    allocation_year = "Y" + user_mst.Rows[i]["allocation_year"].ToString().Trim();
                }

                if (fees_bank_detail != null)
                {
                    DataRow[] dr = fees_bank_detail.Select("semester_type = '" + semester_type.ToString().Trim() + "' and year_semester = '" + year_code.ToString().Trim() + "' and dept_name = '" + user_mst.Rows[i]["department"].ToString().Trim() + "' and prog_name = '" + user_mst.Rows[i]["program"].ToString().Trim() + "' and year_code = '" + allocation_year + "'");

                    if (dr.Length > 0)
                    {
                        dr_error = dt_error.NewRow();

                        dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                        //dr_error["User_Id"] = user_mst.Rows[i]["user_id"].ToString();
                        dr_error["Remark"] = "Fees already entered for '" + user_mst.Rows[i]["department"].ToString().Trim() + "' '" + user_mst.Rows[i]["program"].ToString().Trim() + "' and Allocation Year '" + user_mst.Rows[i]["allocation_year"].ToString().Trim() + "'";

                        dt_error.Rows.Add(dr_error);
                    }
                }

                if (dt_error.Rows.Count == 0)
                {
                    DSC_FeesBankDetail.fees_bank_dtlRow fees_row1 = fees_bank_dtl.fees_bank_dtl.Newfees_bank_dtlRow();

                    fees_row1.doc_no = "new" + (i + 1) + "_1";
                    fees_row1.dept_code = dept_code;
                    fees_row1.prog_code = prog_code;
                    fees_row1.bank_code = user_mst.Rows[i]["bank_code"].ToString().Trim();

                    DSC_FeesBankDetail.fees_bank_dtlRow fees_row2 = fees_bank_dtl.fees_bank_dtl.Newfees_bank_dtlRow();

                    fees_row2.doc_no = "new" + (i + 1) + "_2";
                    fees_row2.dept_code = dept_code;
                    fees_row2.prog_code = prog_code;
                    fees_row2.bank_code = user_mst.Rows[i]["bank_code"].ToString().Trim();

                    fees_bank_dtl.fees_bank_dtl.Addfees_bank_dtlRow(fees_row1);
                    fees_bank_dtl.fees_bank_dtl.Addfees_bank_dtlRow(fees_row2);

                    for (int j = cnt; j < (cnt + 2); j++)
                    {
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["dept_code"] = dept_code;
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["prog_code"] = prog_code;
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["account_name"] = user_mst.Rows[i]["account_name"].ToString().Trim();
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["bank_code"] = user_mst.Rows[i]["bank_code"].ToString().Trim();
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["year"] = user_mst.Rows[i]["allocation_year"].ToString().Trim() + "-" + (Convert.ToInt32(user_mst.Rows[i]["allocation_year"].ToString().Trim()) + 1).ToString().Substring(2);
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["year_code"] = allocation_year;
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["semester_code"] = user_mst.Rows[i]["semester_code"].ToString().Trim();
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["semester_type"] = user_mst.Rows[i]["semester"].ToString().Trim();
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["year_semester"] = user_mst.Rows[i]["year_semester"].ToString().Trim();
                        fees_bank_dtl.fees_bank_dtl.Rows[j]["fine"] = user_mst.Rows[i]["upto_7_days_fine"].ToString().Trim();
                        if (user_mst.Rows[i]["upto_84_days_fine"].ToString().Trim() != string.Empty && user_mst.Rows[i]["upto_84_days_fine"].ToString().Trim() != null)
                        {
                            fees_bank_dtl.fees_bank_dtl.Rows[j]["fine2"] = user_mst.Rows[i]["upto_84_days_fine"].ToString().Trim();
                        }
                        else
                        {
                            fees_bank_dtl.fees_bank_dtl.Rows[j]["fine2"] = "0";
                        }
