            int re = 0;
            bool flag = true;

            Masters obj_mst = new Masters();
            objBLReturnObject = obj_mst.save_fees_bank_dtl_upload(fees_bank_dtl, "2000", context.Session["UserId"].ToString(), context.Request.UserHostName);

