    [WebMethod(EnableSession = true)]
    public string get_fees_payment_dtl()
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            DataTable dt_user_fees_choice = new DataTable();
            DataTable dt_user_fees_installment_dtl = new DataTable();
            DataTable dt_user_fees_status = new DataTable();

            if (CFP_Student)
            {
                if (CFP_Sem == "1")
                {
                    dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 1st Sem Fees");
                    dt_user_fees_installment_dtl = objmaster.get_user_fees_installment_dtl(user_id, "CFP 1st Sem Fees");
                    dt_user_fees_status = objmaster.get_user_fees_status(user_id, "CFP 1st Sem Fees");
                }
                else if (CFP_Sem == "2")
                {
                    dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 2nd Sem Fees");
                    dt_user_fees_installment_dtl = objmaster.get_user_fees_installment_dtl(user_id, "CFP 2nd Sem Fees");
                    dt_user_fees_status = objmaster.get_user_fees_status(user_id, "CFP 2nd Sem Fees");
                }
            }
            else
            {
                dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");
                dt_user_fees_installment_dtl = objmaster.get_user_fees_installment_dtl(user_id, "fees");
                dt_user_fees_status = objmaster.get_user_fees_status(user_id, "fees");
            }

            //Get the Carry Forwarded Credits
            //DataTable dt_cur_sem = objmaster.Get_cept_current_sem_data("fees_installment");

            DataTable dt_carry_frwd_credits = objmaster.get_carry_frwd_credits(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());

            if (dt_carry_frwd_credits == null)
            {
                dt_carry_frwd_credits = objmaster.get_carry_frwd_credits(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());
            }

            ArrayList a = new ArrayList();

            if (dt_user_fees_choice != null)
            {
                a.Add(GetJson1(dt_user_fees_choice));
            }
            else
            {
                a.Add("null");
            }

            if (dt_user_fees_installment_dtl != null)
            {
                a.Add(GetJson1(dt_user_fees_installment_dtl));
            }
            else
            {
                a.Add("null");
            }

            if (dt_user_fees_status != null)
            {
                a.Add(GetJson1(dt_user_fees_status));
            }
            else
            {
                a.Add("null");
            }

            if (dt_carry_frwd_credits != null)
            {
                a.Add(GetJson1(dt_carry_frwd_credits));
            }
            else
            {
                a.Add("null");
            }

            jsondata = "{\"user_fees_choice\":" + a[0] + ",\"user_fees_installment_dtl\":" + a[1] + ",\"user_fees_status\":" + a[2] + ",\"user_credits_dtl\":" + a[3] + "}";
            return return_ajax_data("True", jsondata);
            //return "{\"status\":\"true\",\"message\":" + jsondata + "}";
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }

        return jsondata;
    }
