        string year_code = dt.Rows[0]["year_code"].ToString();
        string prog_code = dt.Rows[0]["prog_code"].ToString();
        string dept_code = dt.Rows[0]["dept_code"].ToString();

        bool insert_fine = false;
        decimal fine_amount = 0;
        int total_days = 0;
        decimal fine_days = 0;
        string last_date_of_fees = "";

        try
        {
            //DataTable dt_cur_sem = objmaster.Get_cept_current_sem_data("fees_installment");

            if (false)//day wise logic old
            {
                DataTable dt_fine_dtl = objmaster.get_fine_dtl_for_fees(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());

                if (installment_no == 1)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date"].ToString();
                }
                else if (installment_no == 2)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date2"].ToString();
                }
                else if (installment_no == 3)
                {
                    last_date_of_fees = dt_fine_dtl.Rows[0]["end_date3"].ToString();
                }

                if (dt_fine_dtl != null)
                {
                    //1. Check Deadline is cross or not? If cross then insert flag true and calculate fine_amount 
                    if (DateTime.Now > Convert.ToDateTime(last_date_of_fees))
                    {
                        insert_fine = true;

                        String days = "";

                        if (DateTime.Now > const_fine_last_date)
                        {
                            days = (const_fine_last_date - Convert.ToDateTime(last_date_of_fees)).TotalDays.ToString();//DateTime.Now //Mahroofbhai Call Fine Change Take Upto 12032020
                        }
                        else
                        {
                            days = (DateTime.Now - Convert.ToDateTime(last_date_of_fees)).TotalDays.ToString();//DateTime.Now //Mahroofbhai Call Fine Change Take Upto 12032020
                        }

                        total_days = Convert.ToInt32(Math.Ceiling(Convert.ToDecimal(days)));

                        if (total_days <= firstDay)
                        {
                            if (dt_fine_dtl.Rows[0]["fine"].ToString() != "")
                            {
                                fine_amount = Convert.ToDecimal(total_days) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine"].ToString());
                            }
                        }
                        else if (total_days <= secondDay)
                        {
                            if (dt_fine_dtl.Rows[0]["fine2"].ToString() != "")
                            {
                                fine_amount = Convert.ToDecimal(total_days - firstDay) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine2"].ToString());
                                fine_amount = fine_amount + (Convert.ToDecimal(firstDay) * Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine"].ToString()));//SevenDaysFine
                            }
                        }
                        else
                        {
                            //What to do?
                        }
                    }

                    //Start 18032020 - 3rd Installment
                    //if (installment_no == 3)
                    //{
                    //    if (Convert.ToDateTime("03/02/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("03/09/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(250);
                    //    }
                    //    else if (Convert.ToDateTime("03/09/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("03/16/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(750);
                    //    }
                    //    else if (Convert.ToDateTime("03/16/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("03/23/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(1250);
                    //    }
                    //    else if (Convert.ToDateTime("03/23/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("03/30/2020"))//28
                    //    {
                    //        fine_amount = Convert.ToDecimal(1750);
                    //    }
                    //    else if (Convert.ToDateTime("03/30/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("04/06/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(2550);
                    //    }
                    //    else if (Convert.ToDateTime("04/06/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("04/13/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(2750);
                    //    }
                    //    else if (Convert.ToDateTime("04/13/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("04/20/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(3250);
                    //    }
                    //    else if (Convert.ToDateTime("04/20/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("04/27/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(3750);
                    //    }
                    //    else if (Convert.ToDateTime("04/27/2020") <= DateTime.Now && DateTime.Now <= Convert.ToDateTime("05/04/2020"))
                    //    {
                    //        fine_amount = Convert.ToDecimal(4250);
                    //    }
                    //}
                    //End 18032020 - 3rd Installment

                    //Start 19032020 - 2nd Installment
                    //if (installment_no == 2)
                    //{
                    //    fine_amount = Convert.ToDecimal(0);
                    //}
                    //End 19032020 - 2nd Installment
                }

                fine_days = Convert.ToDecimal(total_days);

                if (insert_fine)
                {
                    DataTable dt_saved_fine_dtl = objmaster.get_fine_dtl_for_fees_installement_wise(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no);

                    if (dt_saved_fine_dtl != null)
                    {
                        //2. is_admin = Y then not to insert if not then insert(Makes all cancel_flag Y them=n insert) 2 Master
                        if (dt_saved_fine_dtl.Rows[0]["is_admin"].ToString() == "Y")
                        {
                            insert_fine = false;
                            fine_amount = Convert.ToDecimal(dt_saved_fine_dtl.Rows[0]["installment_fine"].ToString());
                            if (DateTime.Now > const_fine_last_date)
                            {
                                fine_days = total_days;//DateTime.Now //Mahroofbhai Call Fine Change Take Upto 12032020
                            }
                            else
                            {
                                fine_days = Convert.ToDecimal((Convert.ToDateTime(dt_saved_fine_dtl.Rows[0]["created_date"].ToString()) - Convert.ToDateTime(last_date_of_fees)).TotalDays);
                            }
                        }

                        if (insert_fine)
                        {
                            //Insert and Update Fine Second Fine for all user
                            //3. created_date = current_date then not to insert (If not then insert (Go ahead)) 2 Master
                            DateTime _dateJoin = Convert.ToDateTime(dt_saved_fine_dtl.Rows[0]["created_date"].ToString());
                            DateTime _CurDate = DateTime.Now;

                            if (_CurDate.Date == _dateJoin.Date)//check proper
                            {
                                insert_fine = false;
                                fine_amount = Convert.ToDecimal(dt_saved_fine_dtl.Rows[0]["installment_fine"].ToString());
                                if (DateTime.Now > const_fine_last_date)
                                {
                                    fine_days = total_days;//DateTime.Now //Mahroofbhai Call Fine Change Take Upto 12032020
                                }
                                else
                                {
                                    fine_days = Convert.ToDecimal((Convert.ToDateTime(dt_saved_fine_dtl.Rows[0]["created_date"].ToString()) - Convert.ToDateTime(last_date_of_fees)).TotalDays);
                                }
                            }
                        }

                        //If Student Uploaded Payslip Then No entry again.
                        DataTable dt_uploaded_payslip_dtl = objmaster.get_uploaded_payslip_dtl(installment_no.ToString(), user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());

                        if (dt_uploaded_payslip_dtl != null)
                        {
                            insert_fine = false;
                        }
                    }
                    else
                    {
                        //Insert Fine First Time for all user
                        insert_fine = true;
                    }
                }

                if (insert_fine)
                {
                    //update cancel_flag Y
                    bool result = objmaster.update_user_wise_fees_dtl(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no, fine_amount);

                    //insert
                    if (result)
                    {
                        result = objmaster.save_user_wise_fees_dtl(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no, fine_amount, "Online");
                    }
                }

            }
            else//slab wise logic 08 07 2020
            {
                //if (year_code == "Y2020" && prog_code == "1")
                //{

                //}
                //else
                //{
                string student_type = "";

                if (CFP_Student)
                {
                    student_type = "CFP";
                }
                else
                {
                    student_type = "REG";
                }

                DataTable dt_fine_dtl = objmaster.get_slab_wise_fine_dtl_for_fees(installment_no.ToString(), user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), student_type);

                if (dt_fine_dtl != null)
                {
                    if (dt_fine_dtl.Rows[0]["user_id"].ToString() == "all")
                    {
                        insert_fine = true;
                        fine_amount = Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine_amount"].ToString());
                    }
                    else
                    {
                        if (DateTime.Now < Convert.ToDateTime(dt_fine_dtl.Rows[0]["slab_start_date"].ToString()))
                        {
                            insert_fine = false;
                        }
                        else if (Convert.ToDateTime(dt_fine_dtl.Rows[0]["slab_start_date"].ToString()) <= DateTime.Now && DateTime.Now <= Convert.ToDateTime(dt_fine_dtl.Rows[0]["slab_end_date"].ToString()))
                        {
                            insert_fine = true;
                            fine_amount = Convert.ToDecimal(dt_fine_dtl.Rows[0]["fine_amount"].ToString());
                        }
                    }
                }

                if (insert_fine)
                {
                    DataTable dt_saved_fine_dtl = objmaster.get_fine_dtl_for_fees_installement_wise(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no);

                    if (dt_saved_fine_dtl != null)
                    {
                        //2. is_admin = Y then not to insert if not then insert(Makes all cancel_flag Y them=n insert) 2 Master
                        if (dt_saved_fine_dtl.Rows[0]["is_admin"].ToString() == "Y")
                        {
                            insert_fine = false;
                            fine_amount = Convert.ToDecimal(dt_saved_fine_dtl.Rows[0]["installment_fine"].ToString());
                        }

                        if (insert_fine)
                        {
                            //Insert and Update Fine Second Fine for all user
                            //3. created_date = current_date then not to insert (If not then insert (Go ahead)) 2 Master
                            DateTime _dateJoin = Convert.ToDateTime(dt_saved_fine_dtl.Rows[0]["created_date"].ToString());
                            DateTime _CurDate = DateTime.Now;

                            if (_CurDate.Date == _dateJoin.Date)//check proper
                            {
                                insert_fine = false;
                                fine_amount = Convert.ToDecimal(dt_saved_fine_dtl.Rows[0]["installment_fine"].ToString());
                            }
                        }

                        //If Student Uploaded Payslip Then No entry again.
                        DataTable dt_uploaded_payslip_dtl = objmaster.get_uploaded_payslip_dtl(installment_no.ToString(), user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());

                        if (dt_uploaded_payslip_dtl != null)
                        {
                            insert_fine = false;
                        }
                    }
                    else
                    {
                        //Insert Fine First Time for all user
                        insert_fine = true;
                    }
                }

                if (insert_fine)
                {
                    //update cancel_flag Y
                    bool result = objmaster.update_user_wise_fees_dtl(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no, fine_amount);

                    //insert
                    if (result)
                    {
                        result = objmaster.save_user_wise_fees_dtl(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), installment_no, fine_amount, "Online");
                    }
                }
                //}
            }

            //return fine amount to user
            jsondata = return_ajax_string(Math.Ceiling(fine_days).ToString(), fine_amount.ToString());
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }

        return jsondata;
    }

