    //Fees Changes
    [WebMethod(EnableSession = true)]
    public string get_fees_installment_dtl(string sem_code, string year_code, int no_of_installment, string chk_credits)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            //DataTable get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);

            DataTable get_fees_dtl = new DataTable();
            DataTable dt_user_fees_choice = new DataTable();

            if (CFP_Student)
            {
                if (CFP_Sem == "1")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_1(user_id, user_type, sem_code, year_code);
                    dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 1st Sem Fees");
                }
                else if (CFP_Sem == "2")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, user_type, sem_code, year_code);
                    dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "CFP 2nd Sem Fees");
                }
            }
            else
            {
                get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);
                dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");
            }

            //DataTable dt_cur_sem = objmaster.Get_cept_current_sem_data("fees_installment");

            DataTable dt_user_fees_data = objmaster.get_user_data_for_pay_slip_new(user_id, "", dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString(), HttpContext.Current.Session["gender"].ToString());

            //DataTable dt_user_fees_choice = objmaster.get_user_fees_choice(user_id, "fees");

            DataTable dt_student_fees_discount_dtl = objmaster.get_student_fees_discount_dtl(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());

            DataTable dt_carry_frwd_credits = objmaster.get_carry_frwd_credits(user_id, dt_cur_sem.Rows[0]["sem_code"].ToString(), dt_cur_sem.Rows[0]["year_code"].ToString());
            DSC_allocated_credits obj_allocated_credits_upload = new DSC_allocated_credits();
            int used_credits = 0;
            if (dt_carry_frwd_credits != null)
            {
                if (chk_credits == "Y")
                {
                    if (dt_carry_frwd_credits.Rows[0]["used_in"].ToString() == "connect")
                    {
                        used_credits = Int32.Parse(dt_carry_frwd_credits.Rows[0]["used_forwarded_credit"].ToString());
                    }
                    else
                    {
                        DSC_allocated_credits.student_allocated_credits_dtlRow row = obj_allocated_credits_upload.student_allocated_credits_dtl.Newstudent_allocated_credits_dtlRow();

                        row.ItemArray = dt_carry_frwd_credits.Rows[0].ItemArray;

                        used_credits = row.carry_forwarded_credit - row.used_forwarded_credit;

                        if (used_credits > 0)
                        {
                            row.used_forwarded_credit += used_credits;
                            row.used_in = "connect";

                            obj_allocated_credits_upload.student_allocated_credits_dtl.Addstudent_allocated_credits_dtlRow(row);
                        }
                    }
                }
                else if (chk_credits == "N" && dt_carry_frwd_credits.Rows[0]["used_in"].ToString() == "connect")
                {
                    DSC_allocated_credits.student_allocated_credits_dtlRow row = obj_allocated_credits_upload.student_allocated_credits_dtl.Newstudent_allocated_credits_dtlRow();

                    row.ItemArray = dt_carry_frwd_credits.Rows[0].ItemArray;

                    row.used_forwarded_credit = 0;
                    row.used_in = null;

                    obj_allocated_credits_upload.student_allocated_credits_dtl.Addstudent_allocated_credits_dtlRow(row);
                }
            }

            string half_fees_amount = "";
            if (dt_user_fees_choice != null && dt_user_fees_choice.Rows[0]["fees_status"].ToString() == "H")
            {
                string fees_dtl = Get_fees_amount_status_new();

                if (fees_dtl != "")
                {
                    JavaScriptSerializer ser = new JavaScriptSerializer();
                    Dictionary<string, object> obj_fees_dtl = ser.Deserialize<Dictionary<string, object>>(fees_dtl);

                    if (obj_fees_dtl["status"].ToString() == "True")
                    {
                        half_fees_amount = obj_fees_dtl["amount"].ToString();
                    }
                }
            }

            if (get_fees_dtl != null)
            {
                if (get_fees_dtl.Rows[0]["is_installment1_paid"].ToString() != "Y" && get_fees_dtl.Rows[0]["is_installment2_paid"].ToString() != "Y" && get_fees_dtl.Rows[0]["is_installment3_paid"].ToString() != "Y" && get_fees_dtl.Rows[0]["is_installment4_paid"].ToString() != "Y" && get_fees_dtl.Rows[0]["is_installment5_paid"].ToString() != "Y")
                {
                    if (dt_user_fees_data.Rows[0]["fees"].ToString() != "")
                    {
                        if (dt_student_fees_discount_dtl != null)
                        {
                            dt_user_fees_data.Rows[0]["fees"] = dt_student_fees_discount_dtl.Rows[0]["amount"].ToString();
                            dt_user_fees_data.Rows[0]["installment1"] = dt_student_fees_discount_dtl.Rows[0]["installment1"].ToString();
                            dt_user_fees_data.Rows[0]["installment2"] = dt_student_fees_discount_dtl.Rows[0]["installment2"].ToString();
                            dt_user_fees_data.Rows[0]["installment3"] = dt_student_fees_discount_dtl.Rows[0]["installment3"].ToString();
                            dt_user_fees_data.Rows[0]["installment4"] = dt_student_fees_discount_dtl.Rows[0]["installment4"].ToString();

                            //Open 5th Installment Start
                            //dt_user_fees_data.Rows[0]["installment5"] = dt_student_fees_discount_dtl.Rows[0]["installment5"].ToString();
                            //Open 5th Installment End
                        }

                        if (chk_credits == "Y" && used_credits > 0)
                        {
                            //dt_user_fees_data.Rows[0]["fees"] = ((Int32.Parse(dt_user_fees_data.Rows[0]["fees"].ToString()) / 20) * (20 - used_credits)).ToString();

                            dt_user_fees_data.Rows[0]["fees"] = ((Int32.Parse(dt_user_fees_data.Rows[0]["fees"].ToString()) / 20) * (20 - 0)).ToString();

                            //13122019 Commented
                            //dt_user_fees_data.Rows[0]["installment1"] = Int32.Parse(dt_user_fees_data.Rows[0]["fees"].ToString()) / 2;
