    [WebMethod(EnableSession = true)]
    public string save_installment_dtl(string installment_dtl, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> obj_installment_dtl = ser.Deserialize<Dictionary<string, object>>(installment_dtl);

            //DataTable get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);

            DataTable get_fees_dtl = new DataTable();

            if (CFP_Student)
            {
                if (CFP_Sem == "1")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_1(user_id, user_type, sem_code, year_code);
                }
                else if (CFP_Sem == "2")
                {
                    get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, user_type, sem_code, year_code);
                }
            }
            else
            {
                get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);
            }

            if (get_fees_dtl != null)
            {
                if (get_fees_dtl.Rows[0]["installment_status"].ToString() != "Y" && get_fees_dtl.Rows[0]["installment_status"].ToString() != "N")
                {
                    get_fees_dtl.Rows[0]["installment_status"] = obj_installment_dtl["installment_status"].ToString();

                    if (obj_installment_dtl["installment_status"].ToString() == "Y")
                    {
                        int no_of_installment = Convert.ToInt32(obj_installment_dtl["no_of_installment"].ToString());

                        get_fees_dtl.Rows[0]["no_of_installment"] = no_of_installment;

                        if (get_fees_dtl.Rows[0]["fees_amount"].ToString() != "")
                        {
                            get_fees_dtl.Rows[0]["installment1"] = Convert.ToDecimal(get_fees_dtl.Rows[0]["fees_amount"].ToString()) / no_of_installment;
                            if (no_of_installment > 1) get_fees_dtl.Rows[0]["installment2"] = Convert.ToDecimal(get_fees_dtl.Rows[0]["fees_amount"].ToString()) / no_of_installment;
                        }
                    }
                    else
                    {
                        get_fees_dtl.Rows[0]["no_of_installment"] = 1;
                        if (get_fees_dtl.Rows[0]["fees_amount"].ToString() != "")
                        {
                            get_fees_dtl.Rows[0]["installment1"] = get_fees_dtl.Rows[0]["fees_amount"];
                        }
                    }

                    DSC_Fees_Installment Fees_Installment = new DSC_Fees_Installment();

                    Fees_Installment.user_fees_installment_dtl.ImportRow(get_fees_dtl.Rows[0]);

                    objBLReturnObject = objMaster.save_installment_dtl(Fees_Installment, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                    }
                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        //get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);

                        if (CFP_Student)
                        {
                            if (CFP_Sem == "1")
                            {
                                get_fees_dtl = objmaster.get_fees_installment_dtl_sem_1(user_id, user_type, sem_code, year_code);
                            }
                            else if (CFP_Sem == "2")
                            {
                                get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, user_type, sem_code, year_code);
                            }
                        }
                        else
                        {
                            get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);
                        }

                        jsondata = return_ajax_data("True", GetJson1(get_fees_dtl));
                    }
                }
                else
                {
                    jsondata = return_ajax_string("False", "You have already saved your fees installment detail");
                }
            }
            else
            {
                jsondata = return_ajax_string("False", "You are not eligible to pay the fees for current semester");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }
        return jsondata;
    }
