    [WebMethod(EnableSession = true)]
    public string Get_fees_payment_pending_transaction(int installment_no, string fees_sem, string fees_year)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            DataTable get_pending_transaction = objmaster.Get_fees_payment_pending_transaction(user_id, installment_no, fees_sem, fees_year);

            if (get_pending_transaction != null)
            {
                jsondata = return_ajax_data("True", GetJson1(get_pending_transaction));
            }
            else
            {
                jsondata = return_ajax_string("False", "Pending Transaction not Found for Current Installment.");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", "Pending Transaction not Found for Current Installment.");
        }

        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string Create_request_for_check_order_status(string transaction_id)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string response = "";
        bool statusget = false;
        Payment objPayment = new Payment();

        try
        {
            string access_code = objPayment.Get_Kotak_access_code("");

            string enc_request = objPayment.Get_Kotak_encrypted_request_to_check_order_status(transaction_id);


            if (transaction_id != "")
            {
                try
                {
                    response = @"ezpaytranid=&amount=&paymentmode=&merchantid=387897&trandate=&pgreferenceno=" + transaction_id + "";

                    System.Net.ServicePointManager.SecurityProtocol = System.Net.SecurityProtocolType.Tls12;
                    HttpWebRequest request = (HttpWebRequest)WebRequest.Create("https://eazypay.icicibank.com/EazyPGVerify?");
                    request.Method = "POST";
                    request.ContentType = "application/x-www-form-urlencoded";
                    request.ContentLength = response.Length;
                    StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                    requestWriter.Write(response);
                    requestWriter.Close();


                    WebResponse webResponse = request.GetResponse();
                    Stream webStream = webResponse.GetResponseStream();
                    StreamReader responseReader = new StreamReader(webStream);
                    string response_api = responseReader.ReadToEnd();
                    responseReader.Close();

                    //string response_api = ""; 

                    //string url = "http://ceptapi.cept.ac.in:85/api/Test/verifypayment?transaction_id=" + transaction_id;
                    //HttpWebRequest request = (HttpWebRequest)WebRequest.Create(url);
                    //request.Method = "POST";

                    //using (HttpWebResponse response1 = (HttpWebResponse)request.GetResponse())
                    //{
                    //    using (StreamReader reader = new StreamReader(response1.GetResponseStream()))
                    //    {
                    //        response_api = reader.ReadToEnd();
                    //    }
                    //} 
                    statusget = objmaster.UpdateNEFTRTGSezpay(transaction_id, response_api, user_id);
                    if (statusget)
                    {
                        return "ICICI Paymetn Success";
                    }
                }
                catch (Exception ex)
                {

                    ServerLog.ExceptionLog("Error Eazypay ICICI Bank API Response Exception : " + ex.ToString());
                    ServerLog.ExceptionLog("Error Eazypay ICICI Bank API Response Exception Message : " + ex.Message.ToString());
                    return "Error";
                }
                
            }

            if (enc_request != "")
            {
                response = "";
                response = "enc_request=" + enc_request + "&access_code=" + access_code + "&command=orderStatusTracker&request_type=JSON&response_type=JSON&version=1.2";
                //jsondata = return_ajax_string("True", response);

                System.Net.ServicePointManager.SecurityProtocol = System.Net.SecurityProtocolType.Tls12;
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create("https://login.ccavenue.com/apis/servlet/DoWebTrans");
                request.Method = "POST";
                request.ContentType = "application/x-www-form-urlencoded";
                request.ContentLength = response.Length;
                StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                requestWriter.Write(response);
                requestWriter.Close();

                try
                {
                    WebResponse webResponse = request.GetResponse();
                    Stream webStream = webResponse.GetResponseStream();
                    StreamReader responseReader = new StreamReader(webStream);
                    string response_api = responseReader.ReadToEnd();
                    responseReader.Close();

                    ServerLog.ExceptionLog("Kotak API Response : " + response_api);

                    return response_api;
                    //return jsondata = return_ajax_string("True", response);
                }
                catch (Exception ex)
                {
                    ServerLog.ExceptionLog("Error Kotak API Response : " + ex.ToString());
                    //jsondata = return_ajax_string("False", ex.ToString());
                    return "Error";
                }
            }
            else
            {
                return "Error";
                //jsondata = return_ajax_string("False", "Error while encrypting Request to Check Fees Status.");
            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("Error Kotak API Response : " + ex.ToString());
            return "Error";
            //jsondata = return_ajax_string("False", "Error while creating Request to Check Fees Status.");
        }

        return "Error";
    }

    [WebMethod(EnableSession = true)]
    public string Create_request_for_check_order_status_by_admin(string transaction_id)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string response = "";
        Payment objPayment = new Payment();

        try
        {
            string access_code = objPayment.Get_Kotak_access_code("");

            string enc_request = objPayment.Get_Kotak_encrypted_request_to_check_order_status(transaction_id);

            if (enc_request != "")
            {
                response = "enc_request=" + enc_request + "&access_code=" + access_code + "&command=orderStatusTracker&request_type=JSON&response_type=JSON&version=1.2";
                //jsondata = return_ajax_string("True", response);

                System.Net.ServicePointManager.SecurityProtocol = System.Net.SecurityProtocolType.Tls12;
                HttpWebRequest request = (HttpWebRequest)WebRequest.Create("https://login.ccavenue.com/apis/servlet/DoWebTrans");
                request.Method = "POST";
                request.ContentType = "application/x-www-form-urlencoded";
                request.ContentLength = response.Length;
                StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                requestWriter.Write(response);
                requestWriter.Close();

                try
                {
                    WebResponse webResponse = request.GetResponse();
                    Stream webStream = webResponse.GetResponseStream();
                    StreamReader responseReader = new StreamReader(webStream);
                    string response_api = responseReader.ReadToEnd();
                    responseReader.Close();

                    ServerLog.ExceptionLog("Kotak API Response : " + response_api);

                    string[] segments = response_api.Split('&');
                    segments[1] = segments[1].Replace("enc_response=", "");
