            else
            {
                return "Error while encrypting request. Please try again later.";
                //jsondata = return_ajax_string("False", "Error while encrypting Request to Check Fees Status.");
            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("Error Kotak API Response : " + ex.ToString());
            return "Something went wrong. Please try again later.";
            //jsondata = return_ajax_string("False", "Error while creating Request to Check Fees Status.");
        }

        return "Something went wrong. Please try again later.";
    }

    [WebMethod(EnableSession = true)]
    public string Create_request_for_check_order_status_by_admin_multiple(string tid_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string response = "";
        Payment objPayment = new Payment();
        String final_response = "<b><center><h3><u>CCAvenue Payment Status Details</u></h3></center></b><br>";

        try
        {
            string access_code = objPayment.Get_Kotak_access_code("");

            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<string> lst_tid_data = ser.Deserialize<List<string>>(tid_data);

            if (lst_tid_data.Count > 0)
            {
                for (int i = 0; i < lst_tid_data.Count; i++)
                {
                    string enc_request = objPayment.Get_Kotak_encrypted_request_to_check_order_status(lst_tid_data[i].ToString());

                    if (enc_request != "")
                    {
                        response = "enc_request=" + enc_request + "&access_code=" + access_code + "&command=orderStatusTracker&request_type=JSON&response_type=JSON&version=1.2";
                        //jsondata = return_ajax_string("True", response);

                        System.Net.ServicePointManager.SecurityProtocol = System.Net.SecurityProtocolType.Tls12;
                        HttpWebRequest request = (HttpWebRequest)WebRequest.Create("https://login.ccavenue.com/apis/servlet/DoWebTrans");
                        request.Method = "POST";
                        request.ContentType = "application/x-www-form-urlencoded";
                        request.ContentLength = response.Length;
                        StreamWriter requestWriter = new StreamWriter(request.GetRequestStream(), System.Text.Encoding.ASCII);
                        requestWriter.Write(response);
                        requestWriter.Close();

                        try
                        {
                            WebResponse webResponse = request.GetResponse();
                            Stream webStream = webResponse.GetResponseStream();
                            StreamReader responseReader = new StreamReader(webStream);
                            string response_api = responseReader.ReadToEnd();
                            responseReader.Close();

                            ServerLog.ExceptionLog("Kotak API Response : " + response_api);

                            string[] segments = response_api.Split('&');
                            segments[1] = segments[1].Replace("enc_response=", "");
                            if (segments[0] == "status=1")
                            {
                                //return "Error while Getting Fees Status : <b>" + segments[1] + "</b>";
                                final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Error while Getting Fees Status : <b>" + segments[1] + "</b> <br/>";
                            }
                            if (segments[0] == "status=0")
                            {
                                string decResponse = objPayment.DecryptResponse(segments[1].ToString().Trim());

                                //JavaScriptSerializer ser = new JavaScriptSerializer();

                                Dictionary<string, object> Params = ser.Deserialize<Dictionary<string, object>>(decResponse);

                                ServerLog.ExceptionLog("Admin 1. Response From Kotak Neft-Rtgs : " + decResponse);

                                if (Params["error_desc"].ToString() == "")
                                {
                                    if (Params["order_status"].ToString() == "Shipped" || Params["order_status"].ToString() == "Successful")
                                    {
                                        string YCODE = "";
                                        string DCODE = "";

                                        string[] merchant_param4 = Params["param_value4"].ToString().Split('#');

                                        YCODE = merchant_param4[5].Trim();

                                        DataTable dtTranDetail = objmaster.GetTransactionDetails(Params["order_no"].ToString().Trim());

                                        if (dtTranDetail != null && dtTranDetail.Rows.Count > 0 && dtTranDetail.Rows[0]["payment_response_code"].ToString() != "0")
                                        {
                                            string student_id = dtTranDetail.Rows[0]["user_id"].ToString();

                                            try
                                            {
                                                DS_Payment obDS_Payment = new DS_Payment();

                                                obDS_Payment.EnforceConstraints = false;

                                                DataRow TranRow = dtTranDetail.Rows[0];

                                                DCODE = TranRow["dept_id"].ToString();

                                                //string program_course_id = TranRow["program_course_id"].ToString();
                                                TranRow["payment_return_flag"] = "Y";
                                                TranRow["payment_response_code"] = "0";
                                                TranRow["payment_response_msg"] = "Transaction Successful";
                                                TranRow["payment_transaction_reference_id"] = Params["reference_no"].ToString();//
                                                TranRow["payment_authorization_code"] = Params["order_bank_ref_no"].ToString();//
                                                                                                                               //TranRow["Citrus_PaymentMode"] = Request["paymentMode"];
                                                TranRow["Citrus_TxRefNo"] = Params["order_bank_ref_no"].ToString();//
                                                                                                                   //TranRow["Citrus_TxGateway"] = Request["TxGateway"];
                                                                                                                   //TranRow["Citrus_IssuerRefNo"] = Request["issuerCode"];
                                                TranRow["Citrus_TxStatus"] = "SUCCESS";
                                                TranRow["status_is_payment_received"] = "Y";
                                                TranRow["last_modified_date"] = DateTime.Now;
                                                TranRow["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString() + " - CCAvenue Manual";
                                                TranRow["last_modified_host"] = HttpContext.Current.Request.UserHostName;

                                                obDS_Payment.applicationpaymenttransaction.ImportRow(TranRow);

                                                DS_Payment.user_activity_logRow activity_row = obDS_Payment.user_activity_log.Newuser_activity_logRow();

                                                activity_row.activity_user = HttpContext.Current.Session["UserId"].ToString();
                                                activity_row.to_user = TranRow["user_id"].ToString();
                                                activity_row.activity_text = "Update CCAvenue Payment Transaction Details";
                                                activity_row.ref_no = Params["order_no"].ToString().Trim();//
                                                activity_row.screen_name = "Manual CCAvenue Payment Update";
                                                activity_row.created_date = DateTime.Now;
                                                activity_row.created_host = HttpContext.Current.Request.UserHostName;

                                                obDS_Payment.user_activity_log.Adduser_activity_logRow(activity_row);

                                                if (true)//objBLReturnObject.ExecutionStatus == 1
                                                {
                                                    if (dtTranDetail.Rows[0]["cash_collected_by"].ToString().Trim() != "")
                                                    {
                                                        string result = update_installation_payment_manually_by_admin(student_id, dtTranDetail.Rows[0]["cash_collected_by"].ToString(), dtTranDetail.Rows[0]["semester_type"].ToString(), dtTranDetail.Rows[0]["year_semester"].ToString(), dtTranDetail.Rows[0]["amount"].ToString(), YCODE, DCODE);
                                                        //if (result == "Amount is mismatch with Installment Details. Verify Installment Amount.")
                                                        //{
                                                        //    //return result;
                                                        //    final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + result + " <br/>";
                                                        //}
                                                        //else
                                                        //{
                                                        objBLReturnObject = objMaster.Save_manually_Online_transaction_data(obDS_Payment, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                                                        //}

                                                        if (result == "Installment already paid.")
                                                        {
                                                            //return result + " Payment Transaction became successful.";
                                                            final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + result + " Payment Transaction became successful. <br/>";
                                                        }
                                                        else if (result == "Data Saved Successfully")
                                                        {
                                                            //return "Payment Transaction became successful and Installment paid successfully.";
                                                            final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Payment Transaction became successful and Installment paid successfully. <br/>";
                                                        }
                                                        else
                                                        {
                                                            final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + result + " Payment Transaction became successful.";
                                                        }
                                                    }
                                                }

                                            }
                                            catch (Exception ex)
                                            {
                                                //return ex.ToString();
                                                final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + ex.ToString() + " <br/>";
                                            }

                                        }
                                        else
                                        {
                                            //return "Transaction is already successful.";
                                            final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Transaction is already successful. <br/>";
                                        }
                                    }
                                    else
                                    {
                                        //return "Transaction is " + Params["order_status"].ToString() + ". It's not successful yet.";
                                        final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Transaction is " + Params["order_status"].ToString() + ". It's not successful yet. <br/>";
                                    }
                                }
                                else
                                {
                                    final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + Params["error_desc"].ToString() + " <br/>";
                                }
                            }
                            else
                            {
                                //return "Error while Getting Fees Status";
                                final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Error while Getting Fees Status. <br/>";
                            }
                        }
                        catch (Exception ex)
                        {
                            ServerLog.ExceptionLog("Error Kotak API Response : " + ex.ToString());
                            //return "Error";
                            final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Server Error. <br/>";
                        }
                    }
                    else
                    {
                        //return "Error while encrypting request. Please try again later.";
                        final_response += "<b>" + lst_tid_data[i].ToString() + "</b> : " + "Error while encrypting request. Please try again later. <br/>";
                    }
                }

                return final_response;
            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("Error Kotak API Response : " + ex.ToString());
            return "Something went wrong. Please try again later.";
            //jsondata = return_ajax_string("False", "Error while creating Request to Check Fees Status.");
        }

        return "Something went wrong. Please try again later.";
    }

    [WebMethod(EnableSession = true)]
    public string DecryptResponseandMakePaymentSuccess(string enc_response)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        Payment objPayment = new Payment();

        try
        {
            string decResponse = objPayment.DecryptResponse(enc_response);

            if (decResponse != "")
            {
                jsondata = return_ajax_string("True", decResponse);
            }
            else
            {
                jsondata = return_ajax_string("False", "Error while Decrypting Response to Check Fees Status.");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", "Error while Decrypting Response to Check Fees Status.");
        }

        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string check_payment_status(string reference_no, string order_no)
    {
        Payment objPayment = new Payment();
        Dictionary<string, object> obj_data = new Dictionary<string, object>();
        try
        {
            Session["kotak_request_url"] = objPayment.Get_Kotak_request_url_neft_rtgs(); ;//Assigned kotak request as given in pdf
            Session["enc_request"] = objPayment.Get_Kotak_encrypted_request_neft_rtgs(reference_no, order_no);
            Session["access_code"] = objPayment.Get_Kotak_access_code_neft_rtgs();
            Session["request_type"] = "JSON";
            Session["response_type"] = "JSON";
            Session["Command"] = "orderStatusTracker";//Need to Set for redirect to kotak API 
            Session["reference_no"] = reference_no;
            Session["order_no"] = order_no;
            Session["version"] = 1.1;

            obj_data["kotak_request_url"] = objPayment.Get_Kotak_request_url_neft_rtgs(); ;//Assigned kotak request as given in pdf
            obj_data["enc_request"] = objPayment.Get_Kotak_encrypted_request_neft_rtgs(reference_no, order_no);
            obj_data["access_code"] = objPayment.Get_Kotak_access_code_neft_rtgs();
            obj_data["request_type"] = "JSON";
            obj_data["response_type"] = "JSON";
            obj_data["Command"] = "orderStatusTracker";//Need to Set for redirect to kotak API 
            obj_data["reference_no"] = reference_no;
            obj_data["order_no"] = order_no;
            obj_data["version"] = 1.1;

        }
        catch (Exception ex)
        {
            return return_ajax_string("False", "Problem in Save DATA" + ex.ToString());
        }

        return return_ajax_data("True", JsonConvert.SerializeObject(obj_data));
    }

