    [WebMethod(EnableSession = true)]
    public string update_installation_payment_manually(string user_id, string cur_installment, string semester, string year, string amount)
    {
        var sem_code = "";
        var year_code = "";
        int re = 0;

        try
        {
            //DataTable get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, "", sem_code, year_code);

            //DataTable get_fees_dtl = new DataTable();

            DataTable get_fees_dtl = objmaster.get_user_fees_installment_dtl_online_generation(user_id, semester, year);

            //DataTable dt_foundation_fees_sem_dtl_user = objmaster.Get_fees_sem_dtl_of_foundation_student(user_id);

            //if (dt_foundation_fees_sem_dtl_user != null)
            //{
            //    if (dt_foundation_fees_sem_dtl_user.Rows[0]["cur_foundation_sem"].ToString() == "1")
            //    {
            //        get_fees_dtl = objmaster.get_fees_installment_dtl_sem_1(user_id, "", sem_code, year_code);
            //    }
            //    else if (dt_foundation_fees_sem_dtl_user.Rows[0]["cur_foundation_sem"].ToString() == "2")
            //    {
            //        get_fees_dtl = objmaster.get_fees_installment_dtl_sem_2(user_id, "", sem_code, year_code);
            //    }
            //}
            //else
            //{
            //    get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, "", sem_code, year_code);
            //}

            if (get_fees_dtl != null)
            {
                if (amount != get_fees_dtl.Rows[0]["installment" + cur_installment].ToString())
                {
                    objBLReturnObject.ServerMessage = "Amount is mismatch with Installment Details. Verify Installment Amount.";
                    jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                    return objBLReturnObject.ServerMessage;
                }

                get_fees_dtl.Rows[0]["is_installment" + cur_installment + "_paid"] = "Y";

                DSC_Fees_Installment Fees_Installment = new DSC_Fees_Installment();

                Fees_Installment.user_fees_installment_dtl.ImportRow(get_fees_dtl.Rows[0]);

                objBLReturnObject = objMaster.save_installment_dtl(Fees_Installment, "2000", user_id, HttpContext.Current.Request.UserHostName);

                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                }
                else if (objBLReturnObject.ExecutionStatus == 1)
                {
                    if (cur_installment == "1")
                    {
                        DataTable dt = objmaster.Get_student_fees_saved_data_for_manually_accept(user_id, get_fees_dtl.Rows[0]["semester_type"].ToString(), get_fees_dtl.Rows[0]["year_semester"].ToString());

                        DataTable dt_current_sem = objmaster.get_fee_collection_student_current_semester_dtl();

                        if (dt != null)
                        {
                            DataRow modify_fees_row = dt.Rows[0];

                            modify_fees_row["last_modified_by"] = HttpContext.Current.Session["UserId"].ToString();
                            modify_fees_row["last_midified_date"] = System.DateTime.Now;
                            modify_fees_row["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                            modify_fees_row["fees_status"] = "F";
                            modify_fees_row["year_code"] = HttpContext.Current.Session["year_code"].ToString() + "-I";

                            obj_fees_status.user_fees_status.ImportRow(modify_fees_row);
                        }
                        else
                        {
                            DSC_fees_status.user_fees_statusRow user_fees = obj_fees_status.user_fees_status.Newuser_fees_statusRow();

                            user_fees.doc_no = re.ToString();
                            user_fees.user_id = user_id;
                            user_fees.fees_status = "F";
                            user_fees.cancel_flag = "N";
                            user_fees.semester_type = semester;
                            user_fees.year_semester = year;
                            user_fees.dept_code = HttpContext.Current.Session["dept_code"].ToString();
                            user_fees.year_code = HttpContext.Current.Session["year_code"].ToString() + "-I";
                            user_fees.installment_status = "N";
                            user_fees.created_by = HttpContext.Current.Session["UserId"].ToString();
                            user_fees.created_date = System.DateTime.Now;
                            user_fees.created_host = HttpContext.Current.Request.UserHostName;

                            if (dt_current_sem != null)
                            {
                                DataRow[] dr1 = dt_current_sem.Select("student_id='" + user_id + "'");

                                if (dr1.Length > 0)
                                {
                                    user_fees.semester_code = dr1[0]["semester_code"].ToString();
                                }
                                else
                                {
                                    user_fees.semester_code = "1";
                                }
                            }
                            else
                            {
                                user_fees.semester_code = "1";
                            }

                            obj_fees_status.user_fees_status.Adduser_fees_statusRow(user_fees);
                        }

                        objBLReturnObject = objMaster.save_upload_manually_payslip_dtl(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    }

                    jsondata = return_ajax_data("True", objBLReturnObject.ServerMessage);
                }
            }
            else
            {
                jsondata = return_ajax_string("False", "Your fees Installment Detail not Found");
            }

            ServerLog.FeesLog("UserID : " + HttpContext.Current.Session["UserId"].ToString() + " :: Semester:" + DateTime.Now + " :: Message" + objBLReturnObject.ServerMessage);
        }
        catch (Exception ex)
        {
            return "Problem in Save DATA.";

            ServerLog.FeesLogError("user_id:" + HttpContext.Current.Session["UserId"].ToString() + "semester:" + HttpContext.Current.Session["semester_code"].ToString() + " Error in Webservice method save_user_fees_after_online_payment " + DateTime.Now);
        }

        return objBLReturnObject.ServerMessage;
    }

