    [WebMethod(EnableSession = true)]
    public string save_installment_payslip_dtl(string manually_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        var sem_code = "";
        var year_code = "";
        int re = 0;
        int cur_installment = 0;
        string last_date_of_fees = "";

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> data = ser.Deserialize<Dictionary<string, object>>(manually_data);

            //DataTable get_fees_dtl = objmaster.get_fees_installment_dtl(user_id, user_type, sem_code, year_code);

            DataTable get_fees_dtl = new DataTable();

            DataTable dt_foundation_fees_sem_dtl_user = objmaster.Get_fees_sem_dtl_of_foundation_student(user_id);

