    [WebMethod(EnableSession = true)]
    public string fees_installment_reminder_mail(string req_obj)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> mail_detail = ser.Deserialize<Dictionary<string, object>>(req_obj);

            DS_UserFeesReminder user_fees_reminder = new DS_UserFeesReminder();

            var sem_code = mail_detail["sem_code"].ToString();
            var year_code = mail_detail["year"].ToString();
            var installment_no = mail_detail["installment_no"].ToString();
            var due_date = mail_detail["due_date"].ToString();
            var mail_subject = mail_detail["mail_subject"].ToString();
            var dept_code = "";
            var prog_code = "";

            DataTable dt_dept_prog_dtl = objmaster.get_department_wise_user_dtl(user_id, sem_code, year_code);

            if (dt_dept_prog_dtl != null)
            {
                for (int v = 0; v < dt_dept_prog_dtl.Rows.Count; v++)
                {
                    if (v == 0)
                    {
                        dept_code += "'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                        prog_code += "'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                    }
                    else
                    {
                        dept_code += ",'" + dt_dept_prog_dtl.Rows[v]["dept_code"] + "'";
                        prog_code += ",'" + dt_dept_prog_dtl.Rows[v]["prog_code"] + "'";
                    }
                }

                DataTable dt_installment_dtl = objmaster.get_installment_dtl_for_reminder_mail(sem_code, year_code, installment_no, dept_code, prog_code);

                if (dt_installment_dtl != null)
                {
                    string mail_result = objmail.fees_installment_reminder_mail(dt_installment_dtl, sem_code, year_code, installment_no, due_date, mail_subject);

                    if (mail_result == "Mail Sent Successfully")
                    {
                        for (int i = 0; i < dt_installment_dtl.Rows.Count; i++)
                        {
                            DS_UserFeesReminder.user_fees_reminder_dtlRow user_fees_reminder_dtl_row = user_fees_reminder.user_fees_reminder_dtl.Newuser_fees_reminder_dtlRow();

                            user_fees_reminder_dtl_row.user_id = dt_installment_dtl.Rows[i]["user_id"].ToString();
                            user_fees_reminder_dtl_row.fees_type = dt_installment_dtl.Rows[i]["fees_type"].ToString();
                            user_fees_reminder_dtl_row.installment_status = dt_installment_dtl.Rows[i]["installment_status"].ToString();
                            user_fees_reminder_dtl_row.no_of_installment = Convert.ToInt32(dt_installment_dtl.Rows[i]["no_of_installment"].ToString());
                            user_fees_reminder_dtl_row.fees_amount = Convert.ToInt32(dt_installment_dtl.Rows[i]["fees_amount"].ToString());

                            if (dt_installment_dtl.Rows[i]["installment1"].ToString() == "")
                                user_fees_reminder_dtl_row.installment1 = 0;
                            else
                                user_fees_reminder_dtl_row.installment1 = Convert.ToInt32(dt_installment_dtl.Rows[i]["installment1"].ToString());

                            if (dt_installment_dtl.Rows[i]["installment2"].ToString() == "")
                                user_fees_reminder_dtl_row.installment2 = 0;
                            else
                                user_fees_reminder_dtl_row.installment2 = Convert.ToInt32(dt_installment_dtl.Rows[i]["installment2"].ToString());

                            if (dt_installment_dtl.Rows[i]["installment3"].ToString() == "")
                                user_fees_reminder_dtl_row.installment3 = 0;
                            else
                                user_fees_reminder_dtl_row.installment3 = Convert.ToInt32(dt_installment_dtl.Rows[i]["installment3"].ToString());

                            if (dt_installment_dtl.Rows[i]["installment4"].ToString() == "")
                                user_fees_reminder_dtl_row.installment4 = 0;
                            else
                                user_fees_reminder_dtl_row.installment4 = Convert.ToInt32(dt_installment_dtl.Rows[i]["installment4"].ToString());

                            if (dt_installment_dtl.Rows[i]["installment5"].ToString() == "")
                                user_fees_reminder_dtl_row.installment5 = 0;
                            else
                                user_fees_reminder_dtl_row.installment5 = Convert.ToInt32(dt_installment_dtl.Rows[i]["installment5"].ToString());

                            user_fees_reminder_dtl_row.is_installment1_paid = dt_installment_dtl.Rows[i]["is_installment1_paid"].ToString();
                            user_fees_reminder_dtl_row.is_installment2_paid = dt_installment_dtl.Rows[i]["is_installment2_paid"].ToString();
                            user_fees_reminder_dtl_row.is_installment3_paid = dt_installment_dtl.Rows[i]["is_installment3_paid"].ToString();
                            user_fees_reminder_dtl_row.is_installment4_paid = dt_installment_dtl.Rows[i]["is_installment4_paid"].ToString();
                            user_fees_reminder_dtl_row.is_installment5_paid = dt_installment_dtl.Rows[i]["is_installment5_paid"].ToString();
                            user_fees_reminder_dtl_row.installment_no_mail = installment_no;
                            user_fees_reminder_dtl_row.cancel_flag = "N";
                            user_fees_reminder_dtl_row.created_by = user_id;
                            user_fees_reminder_dtl_row.created_date = DateTime.Now;
                            user_fees_reminder_dtl_row.created_host = HttpContext.Current.Request.UserHostName.ToString();
                            user_fees_reminder_dtl_row.semester_type = dt_installment_dtl.Rows[i]["semester_type"].ToString();
                            user_fees_reminder_dtl_row.year_semester = dt_installment_dtl.Rows[i]["year_semester"].ToString();

                            user_fees_reminder.user_fees_reminder_dtl.Adduser_fees_reminder_dtlRow(user_fees_reminder_dtl_row);
                        }

                        objBLReturnObject = objMaster.save_user_fees_reminder(user_fees_reminder, "2000", user_id, HttpContext.Current.Request.UserHostName);

                        if (objBLReturnObject.ExecutionStatus == 2)
                        {
                            jsondata = return_ajax_string("False", "Problem in update data : " + objBLReturnObject.ServerMessage);
                        }
                        else if (objBLReturnObject.ExecutionStatus == 1)
                        {
                            //jsondata = return_ajax_string("True", "Mail Sent Successfully");
                            jsondata = return_ajax_string("True", mail_result);
                        }

                    }
                    else
                    {
                        jsondata = return_ajax_string("False", mail_result);
                        return jsondata;
                    }
                }
                else
                {
                    jsondata = return_ajax_string("False", "Student Installment Detail not Found");
                    return jsondata;
                }
            }
            else
            {
                jsondata = return_ajax_string("False", "Department User Detail not Found");
                return jsondata;
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", "Problem in Send Mail. " + ex.ToString());
        }
        return jsondata;
    }

