    [WebMethod(EnableSession = true)]
    public string Save_course_studio_wise_group_data(string course_group, string student_group, string instructor_data, string course_code, string sem_code, string year_code, string sub_studio)
    {
        //Save Compliance Details in compliance_entry table.

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> course_grp_data = ser.Deserialize<List<Dictionary<string, object>>>(course_group);
            List<Dictionary<string, object>> student_grp_data = ser.Deserialize<List<Dictionary<string, object>>>(student_group);
            List<Dictionary<string, object>> instructor_grp_data = ser.Deserialize<List<Dictionary<string, object>>>(instructor_data);

            for (int i = 0; i < course_grp_data.Count; i++)
            {
                DSC_Course_Group.course_group_detailsRow save_course_data = obj_course_group.course_group_details.Newcourse_group_detailsRow();

                save_course_data.course_code = course_code;
                save_course_data.selected_group = course_grp_data[i]["selected_group"].ToString();
                save_course_data.group_code = course_grp_data[i]["group_code"].ToString();
                save_course_data.group_title = course_grp_data[i]["group_title"].ToString();
                //save_course_data.primary_instructor = course_grp_data[i]["primary_instructor"].ToString();
                save_course_data.primary_instructor = "";
                save_course_data.group_type = course_grp_data[i]["group_type"].ToString();
                save_course_data.project = course_grp_data[i]["project"].ToString();
                save_course_data.sub_studio_name = sub_studio;
                save_course_data.semester_type = sem_code;
                save_course_data.year_semester = year_code;

                save_course_data.cancel_flag = "N";
                save_course_data.created_by = HttpContext.Current.Session["UserId"].ToString();
                save_course_data.created_date = System.DateTime.Now;
                save_course_data.created_host = HttpContext.Current.Request.UserHostName;

                obj_course_group.course_group_details.Addcourse_group_detailsRow(save_course_data);
            }

            DataTable dt_student_saved_data = objmaster.get_student_group_saved_data(sem_code, year_code, "", "");

            for (int i = 0; i < student_grp_data.Count; i++)
            {
                DSC_Course_Group.student_course_group_detailsRow save_student_course = obj_course_group.student_course_group_details.Newstudent_course_group_detailsRow();

                save_student_course.course_code = course_code;

                if (dt_student_saved_data != null)
                {
                    DataRow[] dr = dt_student_saved_data.Select("user_id ='" + student_grp_data[i]["user_id"].ToString() + "' and course_code <> '" + course_code + "'");

                    if (dr.Length > 0)
                    {
                        return student_grp_data[i]["user_id"].ToString() + " is already saved in course code " + dr[0]["course_code"].ToString();
                    }
                }

                save_student_course.user_id = student_grp_data[i]["user_id"].ToString();
                save_student_course.representative = student_grp_data[i]["representative"].ToString();
                save_student_course.group_code = student_grp_data[i]["group_code"].ToString();
                save_student_course.course_type = student_grp_data[i]["course_type"].ToString();
                save_student_course.sub_studio_name = sub_studio;
                save_student_course.semester_type = sem_code.ToString();
                save_student_course.year_semester = year_code.ToString();

                save_student_course.cancel_flag = "N";
                save_student_course.created_by = HttpContext.Current.Session["UserId"].ToString();
                save_student_course.created_date = System.DateTime.Now;
                save_student_course.created_host = HttpContext.Current.Request.UserHostName;

                obj_course_group.student_course_group_details.Addstudent_course_group_detailsRow(save_student_course);
            }

            for (int i = 0; i < instructor_grp_data.Count; i++)
            {
                DSC_Course_Group.course_group_instructor_detailsRow save_instructor_data = obj_course_group.course_group_instructor_details.Newcourse_group_instructor_detailsRow();

                save_instructor_data.course_code = course_code;
                save_instructor_data.sub_studio_name = sub_studio;
                save_instructor_data.instructor_code = instructor_grp_data[i]["instructor_code"].ToString();
                save_instructor_data.priority = instructor_grp_data[i]["priority"].ToString();
                save_instructor_data.is_photo_for_projects = instructor_grp_data[i]["is_photo_for_projects"].ToString();

                save_instructor_data.semester_type = sem_code.ToString();
                save_instructor_data.year_semester = year_code.ToString();

                save_instructor_data.cancel_flag = "N";
                save_instructor_data.created_by = HttpContext.Current.Session["UserId"].ToString();
                save_instructor_data.created_date = System.DateTime.Now;
                save_instructor_data.created_host = HttpContext.Current.Request.UserHostName;

                obj_course_group.course_group_instructor_details.Addcourse_group_instructor_detailsRow(save_instructor_data);
            }
            ////objBLReturnObject = objMaster.save_user_fees(obj_fees_status, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            objBLReturnObject = objmaster.Save_course_studio_wise_group_data(obj_course_group, HttpContext.Current.Session["UserId"].ToString(), "", HttpContext.Current.Request.UserHostName, course_code, sem_code, year_code, sub_studio);
        }
        catch (Exception ex)
        {
            return "Problem in Save DATA.";
        }
        finally
        {

        }

        return objBLReturnObject.ServerMessage;
    }

