    [WebMethod(EnableSession = true)]
    public string Save_divide_studio_data(string studio_data, string course_code, string sem_code, string year_code)
    {
        // Save Compliance Details in compliance_entry table.
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> course_grp_data = ser.Deserialize<List<Dictionary<string, object>>>(studio_data);

            for (int i = 0; i < course_grp_data.Count; i++)
            {
                DSC_Course_Group.divide_studio_detailsRow save_studio_data = obj_course_group.divide_studio_details.Newdivide_studio_detailsRow();

                save_studio_data.course_code = course_code;
                save_studio_data.studio_type = course_grp_data[i]["studio_type"].ToString();
                save_studio_data.sub_studio_number = course_grp_data[i]["sub_studio_number"].ToString();
                save_studio_data.sub_studio_name = course_grp_data[i]["sub_studio_name"].ToString();
                save_studio_data.title = course_grp_data[i]["title"].ToString();

                save_studio_data.semester_type = sem_code;
                save_studio_data.year_semester = year_code;

                save_studio_data.cancel_flag = "N";
                save_studio_data.created_by = HttpContext.Current.Session["UserId"].ToString();
                save_studio_data.created_date = System.DateTime.Now;
                save_studio_data.created_host = HttpContext.Current.Request.UserHostName;


                obj_course_group.divide_studio_details.Adddivide_studio_detailsRow(save_studio_data);

            }

            objBLReturnObject = objmaster.Save_divide_studio_data(obj_course_group, HttpContext.Current.Session["UserId"].ToString(), "", HttpContext.Current.Request.UserHostName, course_code, sem_code, year_code);
        }
        catch (Exception ex)
        {
            return "Problem in Save DATA.";
        }
        finally
        {

        }


        return objBLReturnObject.ServerMessage;

    }

