    [WebMethod(EnableSession = true)]
    public string project_praposal(Dictionary<string, object> data)
    {
        Ds_Project_Training obj_Project_Training = new Ds_Project_Training();

        DataTable event_mst_data = objmaster.check_proposal_submited(current_project_sem, current_project_year, HttpContext.Current.Session["UserId"].ToString());

        if (event_mst_data != null)
        {
            return objBLReturnObject.ServerMessage = "Your Proposal Has Already Been Submitted !!";
        }
        else
        {
            try
            {
                if (data.Count > 0)
                {
                    Ds_Project_Training.Project_trainingRow project = obj_Project_Training.Project_training.NewProject_trainingRow();
                    project.user_id = data["userId"].ToString();
                    project.project_Category = data["project_category"].ToString();
                    project.project_category_other = data["project_category_other"].ToString();
                    project.project_site_name = data["project_site_name"].ToString();
                    project.project_objective = data["project_objective"].ToString();
                    project.location = data["locatiion"].ToString();
                    project.client_name = data["company_name"].ToString();
                    project.principle_consultant = data["principle_consultant"].ToString();
                    // project.project_category_other = data["project_category_other"].ToString();
                    project.structural_consultant = data["consultant"].ToString();
                    project.project_managment_consultant = data["proj_mgmt_consultant"].ToString();
                    project.mep_consultant = data["map_consultant"].ToString();
                    project.proof_consultant = data["proof_consultant"].ToString();
                    project.traffic_consultant = data["traffic_consultant"].ToString();
                    project.contractor = data["contractor"].ToString();
                    project.main_subcontractor = data["sub_contractor"].ToString();
                    project.scope_work = data["scope"].ToString();
                    project.cost_work_pakage = data["cost"].ToString();
                    project.physical_aspect_project = data["physical_aspects"].ToString();

                    if (data["project_start_date"].ToString() != "")
                    {
                        string date = getdate(data["project_start_date"].ToString());
                        project.project_start_date = Convert.ToDateTime(date.ToString());
                    }

                    if (data["project_completion_date"].ToString() != "")
                    {
                        string date = getdate(data["project_completion_date"].ToString());
                        project.project_complate_date_contract = Convert.ToDateTime(date.ToString());
                    }

                    project.project_current_status = data["project_current_status"].ToString();

                    if (data["project_completion_date_asPerStatus"].ToString() != "")
                    {
                        string date = getdate(data["project_completion_date_asPerStatus"].ToString());
                        project.project_complate_date_status = Convert.ToDateTime(date.ToString());
                    }

                    project.project_activity = data["project_activity"].ToString();
                    project.consult_participation = data["consult_participation"].ToString();
                    project.is_submit = data["is_submit"].ToString();
                    project.state_response = data["state_response"].ToString();
                    project.conform_email = data["confirm_email"].ToString();


                    if (data["file_path"] != "")
                    {
                        project.file_path = data["file_path"].ToString();
                    }
                    else
                    {
                        project.file_path = "";
                    }

                    project.train_stud_activity = data["train_stud_activity"].ToString();
                    project.train_stud_name = data["train_stud_name"].ToString();
                    project.project_training_under = data["project_training_under"].ToString();
                    project.cancel_flag = "N";
                    project.is_approved = "N";
                    project.semester_type = current_project_sem;
                    project.year_semester = current_project_year;
                    project.created_by = HttpContext.Current.Session["UserId"].ToString();
                    project.created_date = System.DateTime.Now;
                    project.created_host = HttpContext.Current.Request.UserHostName;
                    obj_Project_Training.Project_training.AddProject_trainingRow(project);

                    objBLReturnObject = objMaster.save_projecTraining(obj_Project_Training, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }

            }
            catch (Exception ex)
            {
                throw;
            }

        }

        return objBLReturnObject.ServerMessage;
    }

