    [WebMethod(EnableSession = true)]
    public string get_currunt_date()
    {
        string current_date;
        DateTime date = DateTime.Now;
        string hours = System.DateTime.Now.TimeOfDay.Hours.ToString();
        int compare_time = Convert.ToInt16(hours);

        //if (compare_time >= 19)
        if (compare_time >= 9)
        {
            current_date = date.ToString();
        }
        else if (compare_time < 9)
        {
            current_date = date.AddDays(-1).ToString(); ;
        }
        else
        {
            current_date = "false";
        }

        return current_date;
    }

