    [WebMethod(EnableSession = true)]
    public string project_site_join_report(Dictionary<string, object> data)
    {
        Ds_Project_Training obj_Project_Training = new Ds_Project_Training();

        DataTable event_mst_data = objmaster.check_sjr_submited(current_project_sem, current_project_year, HttpContext.Current.Session["UserId"].ToString());

        if (event_mst_data != null && data["is_submit"].ToString() != "U")
        {
            return objBLReturnObject.ServerMessage = "Site Joining Report Already Submitted !!";
        }
        else
        {
            try
            {
                if (data.Count > 0)
                {
                    Ds_Project_Training.project_site_join_reportRow project = obj_Project_Training.project_site_join_report.Newproject_site_join_reportRow();

                    project.user_id = data["userId"].ToString();

                    if (data["date_of_join"].ToString() != "")
                    {
                        string date = getdate(data["date_of_join"].ToString());
                        project.date_of_join = Convert.ToDateTime(date.ToString());
                        project.plan_entry_deadline = project.date_of_join.AddDays(8);
                    }

                    project.project_name = data["project_name"].ToString();
                    project.name_of_org_join = data["name_of_org_join"].ToString();
                    project.reporting_to = data["reporting_to"].ToString();
                    //project.site_address = data["site_address"].ToString();
                    project.address_from_communication = data["address_from_communication"].ToString();
                    project.site_email = data["site_email"].ToString();
                    project.site_mobile = data["site_mobile"].ToString();
                    project.landline = data["landline"].ToString();
                    project.communication_add_stud = data["communication_add_stud"].ToString();
                    project.stud_mobile = data["stud_mobile"].ToString();
                    project.from_working_hour = data["from_working_hour"].ToString();
                    project.to_working_hour = data["to_working_hour"].ToString();
                    project.from_lunch_hour = data["from_lunch_hour"].ToString();
                    project.to_lunch_hour = data["to_lunch_hour"].ToString();
                    //project.remark = data["stud_mobile"].ToString();
                    project.remark = data["remark"].ToString();

                    if (data["is_submit"].ToString() == "U") project.is_submit = "Y";
                    else project.is_submit = data["is_submit"].ToString();

                    project.file_path = data["file_path"].ToString();
                    project.state_site = data["state_site"].ToString();
                    project.city_site = data["city_site"].ToString();
                    project.state_student = data["state_student"].ToString();
                    project.city_student = data["city_student"].ToString();
                    project.cancel_flag = data["cancel_flag"].ToString();
                    project.semester_type = current_project_sem;
                    project.year_semester = current_project_year;
                    project.created_by = HttpContext.Current.Session["UserId"].ToString();
                    project.created_date = System.DateTime.Now;
                    project.created_host = HttpContext.Current.Request.UserHostName;
                    obj_Project_Training.project_site_join_report.Addproject_site_join_reportRow(project);

                    objBLReturnObject = objMaster.save_project_site_join(obj_Project_Training, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }
            }
            catch (Exception ex)
            {
                throw;
            }
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string project_planned(string data)
    {
        Ds_Project_Training obj_Project_Training = new Ds_Project_Training();


        JavaScriptSerializer ser = new JavaScriptSerializer();

        List<Dictionary<string, string>> data1 = ser.Deserialize<List<Dictionary<string, string>>>(data);
        try
        {
            if (data1.Count > 0)
            {

                for (int i = 0; i < data1.Count; i++)
                {


                    Ds_Project_Training.project_plannedRow project = obj_Project_Training.project_planned.Newproject_plannedRow();

                    project.user_id = HttpContext.Current.Session["UserId"].ToString();
                    if (data1[i]["date"].ToString() != "")
                    {
                        //project.date = Convert.ToDateTime(data1[i]["date"].ToString());

                        string[] arr_date = data1[i]["date"].ToString().Split('/');
                        project.date = new DateTime(Convert.ToInt32(arr_date[2]), Convert.ToInt32(arr_date[0]), Convert.ToInt32(arr_date[1]));
                    }
                    project.structure = data1[i]["structure"].ToString();
                    project.location = data1[i]["location"].ToString();
                    project.activity = data1[i]["activity"].ToString();
                    //project.Remark = data1[i]["remark"].ToString();
                    project.semester_type = current_project_sem;
                    project.year_semester = current_project_year;
                    project.created_by = HttpContext.Current.Session["UserId"].ToString();
                    project.created_date = System.DateTime.Now;
                    project.created_host = HttpContext.Current.Request.UserHostName;


                    obj_Project_Training.project_planned.Addproject_plannedRow(project);
                }
                //save_project_planned name of save methode
                objBLReturnObject = objMaster.save_project_planned(obj_Project_Training, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            }

        }
        catch (Exception ex)
        {
            throw;
        }
        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string get_date_for_planned()
    {
        string current_date = "";
        string week_date = "";
        DataTable event_mst_data = objmaster.get_date_for_planned(current_project_sem, current_project_year, HttpContext.Current.Session["UserId"].ToString());

        if (event_mst_data != null)
        {
            if (event_mst_data.Rows.Count > 0)
            {
                DataRow row = event_mst_data.Rows[0];
                string date_of_join = row["date_of_join"].ToString();
                DateTime date = Convert.ToDateTime(row["date_of_join"]);
                //DateTime week = date.AddDays(7);
                DateTime week = Convert.ToDateTime(row["plan_entry_deadline"]);

                DateTime current_date1 = System.DateTime.Now;
                Int32 diff2 = Convert.ToInt32(System.Math.Abs((date.Date - current_date1.Date).TotalDays));

                //if (diff2 < 8)
                if (current_date1 <= week)
                {
                    current_date = "false";
                }
                else
                {
                    current_date = "true";
                }
                DateTime date1 = new DateTime(2017, 1, 30);

                if (current_date1 < date1)
                {
                    current_date = "false";
                }

            }
        }
        return current_date;
    }

