    //nirav 10/01/2017 dialy sheet  methode
    [WebMethod(EnableSession = true)]
    public string project_save_dailysheet(string data)
    {
        bool flags = true;
        Ds_Project_Training obj_Project_Training = new Ds_Project_Training();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        List<Dictionary<string, string>> data1 = ser.Deserialize<List<Dictionary<string, string>>>(data);
        try
        {
            if (data1.Count > 0)
            {
                DateTime date = Convert.ToDateTime(data1[0]["date"]);
                string dt_1 = get_currunt_date();
                var current_date = Convert.ToDateTime(dt_1).ToString("M/d/yyyy").Replace('-', '/');

                flags = false;
                for (int i = 0; i < data1.Count; i++)
                {
                    Ds_Project_Training.project_dailysheetRow project = obj_Project_Training.project_dailysheet.Newproject_dailysheetRow();
                    project.user_id = HttpContext.Current.Session["UserId"].ToString();

                    if (data1[i]["date"].ToString() != "")
                    {
                        project.date = Convert.ToDateTime(data1[i]["date"].ToString());
                    }

                    project.code = Convert.ToInt16(data1[i]["code"].ToString());
                    project.hours = data1[i]["hours"].ToString();

                    if (data1[i]["skill"].ToString() == "")
                    {
                        project.skill = 0;
                    }
                    else
                    {
                        project.skill = Convert.ToInt16(data1[i]["skill"].ToString());
                    }

                    if (data1[i]["Unskill"].ToString() == "")
                    {
                        project.Unskill = 0;
                    }
                    else
                    {
                        project.Unskill = Convert.ToInt16(data1[i]["Unskill"].ToString());
                    }

                    project.qty = data1[i]["qty"].ToString();
                    project.uom = data1[i]["uom"].ToString();
                    project.semester_type = current_project_sem;
                    project.year_semester = current_project_year;
                    project.created_by = HttpContext.Current.Session["UserId"].ToString();
                    project.created_date = System.DateTime.Now;
                    project.created_host = HttpContext.Current.Request.UserHostName;

                    obj_Project_Training.project_dailysheet.Addproject_dailysheetRow(project);
                }

                //save_project_planned name of save methode
                objBLReturnObject = objMaster.save_project_dayilysheet(obj_Project_Training, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            }
        }
        catch (Exception ex)
        {
            throw;
        }

        return objBLReturnObject.ServerMessage;
    }

