    [WebMethod(EnableSession = true)]
    public string accept_reject_proposal(string user_id, string flag)
    {
        Boolean event_mst_data = objmaster.accept_reject_proposal(user_id, flag);

        string msg = "";
        if (event_mst_data == true)
        {
            if (flag == "A")
            {
                msg = "You Have Accepted The Proposal";
            }
            else if (flag == "R")
            {
                msg = "You Have Rejected The Proposal";
            }
        }
        else
        {

            if (flag == "A")
            {
                msg = "Problem in Accepted";
            }
            else if (flag == "R")
            {
                msg = "Problem in Rejected";
            }
        }

        return msg;


    }

