    [WebMethod(EnableSession = true)]
    public string alumini_registration(string JsonString)
    {
        Dictionary<string, string> obj = new Dictionary<string, string>();
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object> registration_data = ser.Deserialize<Dictionary<string, object>>(JsonString);

            DSC_Alumini_Registration alumini_registration_add = new DSC_Alumini_Registration();

            DSC_Alumini_Registration.alumini_registration_mstRow alumini_registration_row = alumini_registration_add.alumini_registration_mst.Newalumini_registration_mstRow();

            //alumini_registration_row.year_code = registration_data["year_code"].ToString();
            //alumini_registration_row.prog_level_code = registration_data["prog_level_code"].ToString();
            //alumini_registration_row.user_name = registration_data["name"].ToString();
            DataTable dt = objmaster.check_alumini_user(registration_data["user_id"].ToString(), registration_data["dob"].ToString().Trim());



            if (dt != null)
            {
                //  alumini_registration_row.dob = "N";

                DataTable dt_alumini_registration_dtl = objmaster.get_alumini_registration_details(dt.Rows[0]["user_id"].ToString(), "", "");

                if (dt_alumini_registration_dtl != null)
                {
                    obj["status"] = "false";
                    obj["message"] = "Your are already registered as Alumni.";
                    obj["user_id"] = "";
                    obj["verification_status"] = "N";
                    return JsonConvert.SerializeObject(obj);
                }

                if (dt.Rows[0]["user_status_flag"].ToString() != "A")
                {
                    obj["status"] = "false";
                    obj["message"] = "Your details are match in our data but you are not active please contact admin.";
                    obj["user_id"] = "";
                    obj["verification_status"] = "N";
                    return JsonConvert.SerializeObject(obj);
                }

                string birthdate = registration_data["dob"].ToString().Trim();

                if (birthdate.ToString().Trim() != "")
                {
                    String dst21 = birthdate.ToString();

                    string[] sdg21 = dst21.ToString().Split('/');
                    string gh21 = sdg21[2].ToString() + "/" + sdg21[1].ToString() + "/" + sdg21[0].ToString();

                    DateTime expiryto = Convert.ToDateTime(gh21);
                    String expiry2 = expiryto.ToString();

                    alumini_registration_row.dob = Convert.ToDateTime(expiry2);

                }
                if (registration_data["user_id"].ToString() != "")
                {
                    alumini_registration_row.user_id = dt.Rows[0]["user_id"].ToString();
                }
                else
                {

                }
                alumini_registration_row.user_name = dt.Rows[0]["user_name"].ToString();
                alumini_registration_row.mail = dt.Rows[0]["mail"].ToString();
                alumini_registration_row.year_code = dt.Rows[0]["year_code"].ToString();
                alumini_registration_row.prog_level_code = dt.Rows[0]["prog_level_code"].ToString();
                alumini_registration_row.is_verified = "Y";
                alumini_registration_row.is_mail_send = "YV";
                // alumini_registration_row.mail = registration_data["email"].ToString();
                alumini_registration_row.cancel_flag = "N";
                alumini_registration_row.created_by = dt.Rows[0]["user_id"].ToString();
                alumini_registration_row.created_date = DateTime.Now;
                alumini_registration_row.created_host = HttpContext.Current.Request.UserHostName;

                //course_master_upload.course_wise_time.Addcourse_wise_timeRow(course_wise_time_row);
                alumini_registration_add.alumini_registration_mst.Addalumini_registration_mstRow(alumini_registration_row);

                objBLReturnObject = objMaster.save_alumini_registration_data(alumini_registration_add, "2000", "", HttpContext.Current.Request.UserHostName, "");

                if (objBLReturnObject.ExecutionStatus == 1)
                {
                    obj["status"] = "true";
                    // obj["message"] = "You details have been verified with the graduate database. You can proceed to create your alumni account.";
                    obj["message"] = "Y?our details have been successfully verified with our database. Please create your account and update your details in the registry.";
                    obj["verification_status"] = "V";
                    obj["user_id"] = dt.Rows[0]["user_id"].ToString();
                    return JsonConvert.SerializeObject(obj);
                }
            }
            else
            {
                obj["status"] = "false";
                //  obj["message"] = "Your details did not match with the database we have. This could be either because the database is incomplete, or the student code you entered was wrong. Kindly fill in the following details and we will get back to you.";
                obj["message"] = "Your details could no be verified with our database at this time. This could either be because of an error in entering your information or because of incomplete database. Please fill in your details for manual verification. ?Your account will be activated as soon as your information is manually verified.";
                obj["user_id"] = "";
                obj["verification_status"] = "NV";
                return JsonConvert.SerializeObject(obj);


            }
        }
        catch (Exception ex)
        {

            obj["status"] = "false";
            obj["message"] = "Problem in Registration";
            obj["user_id"] = "";
            obj["verification_status"] = "N";

            return JsonConvert.SerializeObject(obj);
        }

        return objBLReturnObject.ServerMessage;
    }

