    [WebMethod(EnableSession = true)]
    public string save_alumini_credential(string JsonString)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        Dictionary<string, object> registration_data = ser.Deserialize<Dictionary<string, object>>(JsonString);

        EncryptPassword encrpt = new EncryptPassword();

        DataTable dt = objmaster.check_mail_user_mst(registration_data["email"].ToString());

        if (dt != null)
        {
            // return "This email id is already found in our master data";
            return return_ajax_string("Flase", "This email id is already found in our master data");
        }

        string pass = registration_data["password"].ToString();
        //Password = encrpt.sbs_encrypt(Password.ToString().Trim());
        string Password = "";
        Password = encoding_decoding.encryptPassword(pass.ToString().Trim());

        bool check = objmaster.update_alumini_credential(registration_data["user_id"].ToString(), registration_data["email"].ToString(), Password, HttpContext.Current.Request.UserHostName);

        if (check)
        {
            string user_type = LoginCheck(registration_data["email"].ToString(), pass, false);

            if (user_type == "Alumni")
            {
                return return_ajax_string("True", user_type);
            }
            else
            {
