            }
        }
        return return_ajax_string("False", "Problem in update data");
    }

    [WebMethod(EnableSession = true)]
    public string update_alumini_credential(string JsonString)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        Dictionary<string, object> registration_data = ser.Deserialize<Dictionary<string, object>>(JsonString);

        EncryptPassword encrpt = new EncryptPassword();

        DataTable dt = objmaster.check_mail_user_mst(registration_data["email"].ToString());

        if (dt == null)
        {
            // return "This email id is already found in our master data";
            return return_ajax_string("Flase", "Email id is not match");
        }
        else
        {
            DataTable dt_alumni_dtl = objmaster.get_alumini_registration_details(dt.Rows[0]["user_id"].ToString(), "Y", "");

            if (dt_alumni_dtl == null)
            {
                return return_ajax_string("Flase", "You alumni registration details not found");
            }

            if (dt.Rows.Count > 1)
            {
                return return_ajax_string("Flase", "Multiple email id is found in data");
            }
        }

        string pass = registration_data["password"].ToString();
        //Password = encrpt.sbs_encrypt(Password.ToString().Trim());
        string Password = "";
        Password = encoding_decoding.encryptPassword(pass.ToString().Trim());

        bool check = objmaster.update_alumini_credential(dt.Rows[0]["user_id"].ToString(), "", Password, HttpContext.Current.Request.UserHostName);

        if (check)
        {
            string user_type = LoginCheck(registration_data["email"].ToString(), pass, false);

            if (user_type == "Alumni")
            {
                return return_ajax_string("True", user_type);
            }
            else
            {
                return return_ajax_string("False", "Problem in Login");
            }
        }
        return return_ajax_string("False", "Problem in update data");
    }

