    [WebMethod(EnableSession = true)]
    public string save_alumni_verify_user(string verify_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            Dictionary<string, object> registration_data = ser.Deserialize<Dictionary<string, object>>(verify_data);

            EncryptPassword encrpt = new EncryptPassword();

            string email = registration_data["email"].ToString();

            DataTable dt = objmaster.check_mail_user_mst(email);

            if (dt != null)
            {
                if (dt.Rows[0]["user_id"].ToString() != registration_data["user_id"].ToString())
                {
                    return "This email id is already in our data for other user";
                }
            }

            string encrpt_email = encrpt_email = encoding_decoding.encryptPassword(email.ToString().Trim());

            string send_link = "https://connect.cept.ac.in/Alumni/change_password.aspx?id=" + encrpt_email;
            //  string send_link = "https://localhost:5405/CEPT/Alumni/change_password.aspx?email=" + encrpt_email;

            objBLReturnObject = objmaster.update_alumini_verify_user(registration_data, HttpContext.Current.Request.UserHostName, HttpContext.Current.Session["UserId"].ToString());

            if (objBLReturnObject.ExecutionStatus == 1)
            {
                bool mail_res = objmail.Send_verify_mail_to_alumni(send_link, registration_data["email"].ToString());
            }
        }
        catch (Exception ex)
        {

            return "Problem in verify alumni user";
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string save_alumni_verify_user_admin(string verify_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return "";
            }
            List<Dictionary<string, object>> registration_data = ser.Deserialize<List<Dictionary<string, object>>>(verify_data);

            EncryptPassword encrpt = new EncryptPassword();
            for (int verifiyloop = 0; verifiyloop < registration_data.Count; verifiyloop++)
            {
                string email = registration_data[verifiyloop]["email"].ToString();

                DataTable dt = objmaster.check_mail_user_mst(email);

                if (dt != null)
                {
                    if (dt.Rows[verifiyloop]["user_id"].ToString() != registration_data[verifiyloop]["user_id"].ToString())
                    {
                        return "This email id is already in our data for other user";
                    }
                }

                string encrpt_email = encrpt_email = encoding_decoding.encryptPassword(email.ToString().Trim());

                string send_link = "https://connect.cept.ac.in/Alumni/change_password.aspx?id=" + encrpt_email;
                //  string send_link = "https://localhost:5405/CEPT/Alumni/change_password.aspx?email=" + encrpt_email;

                objBLReturnObject = objmaster.update_alumini_verify_user(registration_data[verifiyloop], HttpContext.Current.Request.UserHostName, HttpContext.Current.Session["UserId"].ToString());

                if (objBLReturnObject.ExecutionStatus == 1)
                {
                    bool mail_res = objmail.Send_verify_mail_to_alumni(send_link, registration_data[verifiyloop]["email"].ToString());
                }
            }
        }
        catch (Exception ex)
        {

            return "Problem in verify alumni user";
        }

        return objBLReturnObject.ServerMessage;
    }

