    public string save_alumni_personal_data_report(string str_req_data)
    {
        string user_id = HttpContext.Current.Session["UserID"].ToString();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            Dictionary<string, string> dic_req_data = ser.Deserialize<Dictionary<string, string>>(str_req_data);

            if (1 == 1)
            {
                dic_req_data["sender_email"] = "";
                //   if (HttpContext.Current.Session["email"] != null) dic_req_data["sender_email"] = HttpContext.Current.Session["email"].ToString();
                dic_req_data.Add("is_registr", "FA");
                objmaster.save_alumni_personal_data(ref dic_req_data);

                if (dic_req_data["subscribe_newsletter"].ToString() == "Y" && dic_req_data["status"].ToString() == "True")
                {
                    try
                    {
                        MailChimp.MailChimpManager mc = new MailChimp.MailChimpManager("631e486231eb441f1c2c60b79f95dd04-us12");
                        //  ListResult lists = mc.GetLists();
                        MailChimp.Helper.EmailParameter email = new MailChimp.Helper.EmailParameter()
                        {
                            //Email = "call2kamlesh2007@gmail.com"
                            Email = HttpContext.Current.Session["email"].ToString()
                        };

                        MailChimp.Lists.MergeVar myMergeVars = new MailChimp.Lists.MergeVar();
                        //myMergeVars.Add("FNAME", "Test");
                        //myMergeVars.Add("LNAME", "Test");
                        myMergeVars.Add("FNAME", dic_req_data["first_name"].ToString());
                        myMergeVars.Add("LNAME", dic_req_data["middle_name"].ToString());
                        myMergeVars.Add("MMERGE3", "Yes");

                        MailChimp.Helper.EmailParameter results = mc.Subscribe("edf0e5a978", email, myMergeVars);
                    }
                    catch (Exception ex)
                    {
                        return return_ajax_string("False", "Data Saved Succesfully.but some problem found in email subscription.");
                    }
                }

                return return_ajax_string(dic_req_data["status"], dic_req_data["message"]);
            }
            else
            {
                return return_ajax_string("False", "Unable to Save. User ID Mismatch.");
            }
        }
        catch (Exception ex)
        {
            //return return_ajax_string("False", ex.ToString());
            return return_ajax_string("False", "Problem in Save Data. Please Try Again.");
        }

        return "";
    }

