    [WebMethod(EnableSession = true)]
    public string alumini_registration_Admin(string JsonString)
    {
        Dictionary<string, string> obj = new Dictionary<string, string>();
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> registration_data = ser.Deserialize<List<Dictionary<string, object>>>(JsonString);

            DSC_Alumini_Registration alumini_registration_add = new DSC_Alumini_Registration();

            for (int i = 0; i < registration_data.Count; i++)
            {
                DSC_Alumini_Registration.alumini_registration_mstRow alumini_registration_row = alumini_registration_add.alumini_registration_mst.Newalumini_registration_mstRow();

                DataTable dt = objmaster.check_alumini_user_Admin_Upload(registration_data[i]["mail"].ToString());
                DataTable dt_alumini_registration_dtl = objmaster.get_alumini_registration_details_Upload(registration_data[i]["mail"].ToString());


                if (dt_alumini_registration_dtl == null)
                {

                    string birthdate = registration_data[i]["dob"].ToString().Trim();

                    if (birthdate.ToString().Trim() != "")
                    {
                        String dst21 = birthdate.ToString();

                        string[] sdg21 = dst21.ToString().Split('/');
                        string gh21 = sdg21[2].ToString() + "/" + sdg21[1].ToString() + "/" + sdg21[0].ToString();

                        // DateTime expiryto = Convert.ToDateTime(gh21);

                        //String expiry2 = expiryto.ToString();
                        // String expiry2 = expiryto.ToString();

                        alumini_registration_row.dob = Convert.ToDateTime(dst21);

                    }
                    if (dt != null)
                    {
                        alumini_registration_row.user_id = dt.Rows[0]["user_id"].ToString();
                    }
                    else if (registration_data[i]["user_id"].ToString() != null && registration_data[i]["user_id"].ToString() != "")
                    {
                        alumini_registration_row.user_id = registration_data[i]["user_id"].ToString();
                    }
                    else
                    {
                        //Guid obj_GUID = Guid.NewGuid();
                        //alumini_registration_row.user_id = obj_GUID.ToString();

                    }
                    if (dt != null)
                    {

                        alumini_registration_row.user_name = dt.Rows[0]["user_name"].ToString();
                        alumini_registration_row.mail = dt.Rows[0]["mail"].ToString();
                        alumini_registration_row.year_code = registration_data[i]["year_code"].ToString();
                        alumini_registration_row.prog_level_code = registration_data[i]["prog_level_code"].ToString();


                    }
