    [WebMethod(EnableSession = true)]
    public string Get_Refund_Student_application()
    {
        DataTable dt = new DataTable();

        int st_deposite = 25000;
        int without_deposite_fees;
        int befor_charge_fees;
        int per_amount;
        int final_Refund_amount = 0;
        try
        {
            DataTable dt_refund = objmaster.Get_application_refund_data(HttpContext.Current.Session["UserId"].ToString());
            dt = objmaster.Get_student_refund_detail_online(HttpContext.Current.Session["UserId"].ToString());

            if (dt == null)
            {
                dt = objmaster.Get_student_refund_detail_Offline(HttpContext.Current.Session["UserId"].ToString());
                if (dt == null)
                {
                    return return_ajax_string("False", "Sorry Your are not eligible to fill the Refund application");
                }

            }
            if (dt != null)
            {
                dt.Columns.Add("refund_amount", typeof(string));

                dt.Columns.Add("reason_for_dropwithdrawal", typeof(string));
                dt.Columns.Add("name_of_account_holder", typeof(string));
                dt.Columns.Add("name_of_bank_address", typeof(string));
                dt.Columns.Add("account_type", typeof(string));
                dt.Columns.Add("IFSC_code", typeof(string));
                dt.Columns.Add("account_number", typeof(string));
                dt.Columns.Add("is_submit", typeof(string));
            }

            if (dt_refund != null)
            {

                dt.Rows[0]["refund_amount"] = dt_refund.Rows[0]["refund_amount"].ToString();
                dt.Rows[0]["reason_for_dropwithdrawal"] = dt_refund.Rows[0]["reason_for_dropwithdrawal"].ToString();
                dt.Rows[0]["name_of_account_holder"] = dt_refund.Rows[0]["name_of_account_holder"].ToString();
                dt.Rows[0]["name_of_bank_address"] = dt_refund.Rows[0]["name_of_bank_address"].ToString();
                dt.Rows[0]["account_type"] = dt_refund.Rows[0]["account_type"].ToString();
                dt.Rows[0]["IFSC_code"] = dt_refund.Rows[0]["IFSC_code"].ToString();
                dt.Rows[0]["account_number"] = dt_refund.Rows[0]["account_number"].ToString();
                dt.Rows[0]["is_submit"] = dt_refund.Rows[0]["is_submit"].ToString();

            }
            if (dt_refund == null)
            {
                if (dt.Rows[0]["amountpaid"].ToString() == "105000")
                {
                    without_deposite_fees = Convert.ToInt32(dt.Rows[0]["amountpaid"].ToString()) - st_deposite;

                    if (DateTime.Now.Date < (new DateTime(2017, 5, 18)) == true)
                    {
                        befor_charge_fees = without_deposite_fees - 5000;
                        final_Refund_amount = befor_charge_fees + st_deposite;

                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 18)) == true && DateTime.Now.Date <= (new DateTime(2017, 5, 30)) == true)
                    {

                        per_amount = (without_deposite_fees * 50) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;

                        final_Refund_amount = befor_charge_fees + st_deposite;
                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 31)) == true && DateTime.Now.Date <= (new DateTime(2017, 6, 27)) == true)
                    {

                        per_amount = (without_deposite_fees * 75) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;
                        final_Refund_amount = befor_charge_fees + st_deposite;
                    }
                    else if (DateTime.Now.Date > (new DateTime(2017, 6, 27)) == true)
                    {
                        befor_charge_fees = 0;
                        final_Refund_amount = befor_charge_fees + st_deposite;
                    }
                }
                else if (dt.Rows[0]["amountpaid"].ToString() == "65000")
                {
                    without_deposite_fees = Convert.ToInt32(dt.Rows[0]["amountpaid"].ToString()) - st_deposite;

                    if (DateTime.Now.Date < (new DateTime(2017, 5, 18)) == true)
                    {
                        befor_charge_fees = without_deposite_fees - 5000;
                        final_Refund_amount = befor_charge_fees + st_deposite;

                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 18)) == true && DateTime.Now.Date <= (new DateTime(2017, 5, 30)) == true)
                    {

                        per_amount = (without_deposite_fees * 50) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;
                        final_Refund_amount = befor_charge_fees + st_deposite;

                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 31)) == true && DateTime.Now.Date <= (new DateTime(2017, 6, 27)) == true)
                    {

                        per_amount = (without_deposite_fees * 75) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;
                        final_Refund_amount = befor_charge_fees + st_deposite;
                    }
                    else if (DateTime.Now.Date > (new DateTime(2017, 6, 27)) == true)
                    {
                        befor_charge_fees = 0;
                        final_Refund_amount = befor_charge_fees + st_deposite;
                    }
                }
                else if (dt.Rows[0]["amountpaid"].ToString() == "80000")
                {
                    without_deposite_fees = Convert.ToInt32(dt.Rows[0]["amountpaid"].ToString());

                    if (DateTime.Now.Date < (new DateTime(2017, 5, 18)) == true)
                    {
                        befor_charge_fees = without_deposite_fees - 5000;
                        final_Refund_amount = befor_charge_fees;

                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 18)) == true && DateTime.Now.Date <= (new DateTime(2017, 5, 30)) == true)
                    {

                        per_amount = (without_deposite_fees * 50) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;
                        final_Refund_amount = befor_charge_fees;


                    }
                    else if (DateTime.Now.Date >= (new DateTime(2017, 5, 31)) == true && DateTime.Now.Date <= (new DateTime(2017, 6, 27)) == true)
                    {

                        per_amount = (without_deposite_fees * 75) / 100;
                        befor_charge_fees = without_deposite_fees - per_amount;
                        final_Refund_amount = befor_charge_fees;
                    }
                    else if (DateTime.Now.Date > (new DateTime(2017, 6, 27)) == true)
                    {
                        befor_charge_fees = 0;
                        final_Refund_amount = befor_charge_fees;
                    }
                }
                else
                {


                }
                if (dt != null)
                {
                    dt.Rows[0]["refund_amount"] = final_Refund_amount;
                    //jsondata = GetJson1(dt);
                    return return_ajax_data("true", GetJson1(dt));
                }
            }
            else
            {
                return return_ajax_data("true", GetJson1(dt));
                //jsondata = GetJson1(dt);
            }
        }
        catch (Exception e)
        {
            return return_ajax_string("False", e.ToString());
        }
        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string save_fees_refund(string str_req_data)
    {
        string user_id = HttpContext.Current.Session["UserID"].ToString();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            Dictionary<string, string> dic_req_data = ser.Deserialize<Dictionary<string, string>>(str_req_data);

            if (HttpContext.Current.Session["email"] != null)
                dic_req_data["mail"] = HttpContext.Current.Session["email"].ToString();
            dic_req_data["user_id"] = HttpContext.Current.Session["UserID"].ToString();
            dic_req_data["prog_level_code"] = HttpContext.Current.Session["prog_level_code"].ToString();
            dic_req_data["host"] = HttpContext.Current.Request.UserHostName;
            dic_req_data["doc_no"] = null;

            DataTable dt = objmaster.Get_application_refund_data(dic_req_data["user_id"].ToString());
            if (dt != null)
            {
                dic_req_data["doc_no"] = dt.Rows[0]["doc_no"].ToString();
            }
            if (dt != null)
            {
                if (dt.Rows[0]["is_submit"].ToString() == "Y")
                    return return_ajax_string("False", "Your Application already submited");
            }
            objmaster.save_refund_application(ref dic_req_data);

            return return_ajax_string(dic_req_data["status"], dic_req_data["message"]);
        }
        catch (Exception ex)
        {
            //return return_ajax_string("False", ex.ToString());
            return return_ajax_string("False", "Problem in Save Data. Please Try Again.");
        }

        return "";
    }

