    [WebMethod(EnableSession = true)]
    public string save_student_profile(string str_req_data)
    {
        string user_id = HttpContext.Current.Session["UserID"].ToString();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        DS_Masters obj_mst = new DS_Masters();

        try
        {
            Dictionary<string, string> dic_req_data = ser.Deserialize<Dictionary<string, string>>(str_req_data);

            if (HttpContext.Current.Session["UserID"] != null)
            {
                dic_req_data["user_id"] = HttpContext.Current.Session["UserID"].ToString();

                DataTable dt = objmaster.Get_student_personal_data(dic_req_data["user_id"].ToString());

                if (dt != null)
                {
                    obj_mst.user_mst.ImportRow(dt.Rows[0]);
                    obj_mst.user_mst[0].first_name = dic_req_data["first_name"].ToString();
                    obj_mst.user_mst[0].middle_name = dic_req_data["middle_name"].ToString();
                    obj_mst.user_mst[0].last_name = dic_req_data["last_name"].ToString();
                    obj_mst.user_mst[0].blood_group = dic_req_data["blood_group"].ToString();
                }

                objBLReturnObject = objMaster.save_student_data(obj_mst, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    return return_ajax_string("false", objBLReturnObject.ServerMessage);
                }
                return return_ajax_string("true", objBLReturnObject.ServerMessage);
            }
        }
        catch (Exception ex)
        {
            //return return_ajax_string("False", ex.ToString());
            return return_ajax_string("false", ex.Message);
        }

        return "";
    }

