    [WebMethod(EnableSession = true)]
    public string Update_blood_group(string blood_group)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();

        try
        {
            Boolean saved = objmaster.Update_blood_group(user_id, blood_group);

            if (saved)
            {
                jsondata = return_ajax_string("True", "Blood Group Submitted Successfully.");
            }
            else
            {
                jsondata = return_ajax_string("False", "Error while submitting Blood Group.");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }

        return jsondata;
    }

