    [WebMethod(EnableSession = true)]
    public string get_student_foundation_dtl(string year_code)
    {
        if (year_code != "")
        {
            if (year_code == "2013") year_code = "Y1";
            else year_code = "Y" + year_code;
        }

        DataTable dt_student_foundation_dtl = objmaster.get_student_foundation_and_user_dtl(year_code);

        if (dt_student_foundation_dtl != null)
        {
            jsondata = GetJson1(dt_student_foundation_dtl);
        }

        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string save_student_foundation_dtl(string student_dtl, string year_code)
    {
        string user_id = HttpContext.Current.Session["UserID"].ToString();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        DSC_StudentFoundationDtl obj_student_dtl = new DSC_StudentFoundationDtl();

        try
        {
            if (year_code != "")
            {
                if (year_code == "2013") year_code = "Y1";
                else year_code = "Y" + year_code;
            }

            DataTable dt_student_foundation_dtl = objmaster.get_student_foundation_dtl(year_code);

            if (dt_student_foundation_dtl != null)
            {
                List<Dictionary<string, string>> arr_student_dtl = ser.Deserialize<List<Dictionary<string, string>>>(student_dtl);

                if (HttpContext.Current.Session["UserID"] != null)
                {
                    for (int i = 0; i < arr_student_dtl.Count; i++)
                    {
                        DataRow[] dr = dt_student_foundation_dtl.Select("user_id='" + arr_student_dtl[i]["user_id"].ToString() + "'");

                        if (dr.Length > 0)
                        {
                            DSC_StudentFoundationDtl.student_foundation_program_dtlRow dr_student_dtl = obj_student_dtl.student_foundation_program_dtl.Newstudent_foundation_program_dtlRow();

                            dr_student_dtl.ItemArray = dr[0].ItemArray;

                            dr_student_dtl.cur_foundation_sem = arr_student_dtl[i]["cur_sem"].ToString();
                            dr_student_dtl.status = arr_student_dtl[i]["status"].ToString();
                            dr_student_dtl.last_modified_by = HttpContext.Current.Session["UserID"].ToString();
                            dr_student_dtl.last_midified_date = DateTime.Now;
                            dr_student_dtl.last_modified_host = HttpContext.Current.Request.UserHostName;

                            obj_student_dtl.student_foundation_program_dtl.Addstudent_foundation_program_dtlRow(dr_student_dtl);
                        }
                    }

                    objBLReturnObject = objMaster.save_student_foundation_dtl(obj_student_dtl, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        return return_ajax_string("false", objBLReturnObject.ServerMessage);
                    }

                    return return_ajax_string("true", objBLReturnObject.ServerMessage);
                }
            }
            else
            {
                return return_ajax_string("false", "Student Foundation Details not Found");
            }
        }
        catch (Exception ex)
        {
            //return return_ajax_string("False", ex.ToString());
            return return_ajax_string("false", ex.Message);
        }

        return "";
    }

