    /// <summary>
    /// Save Course SubGroup Details
    /// </summary>
    /// <param name="req_data"></param>
    /// <returns></returns>
    [WebMethod(EnableSession = true)]
    public string save_course_subgroup_dtl(string req_data)
    {
        try
        {
            string user_id = HttpContext.Current.Session["UserID"].ToString();

            JavaScriptSerializer ser = new JavaScriptSerializer();
            Dictionary<string, object> obj_sub_group_dtl = ser.Deserialize<Dictionary<string, object>>(req_data);

            if (obj_sub_group_dtl["course_code"].ToString() == "")
            {
                return return_ajax_string("false", "Course Code not found");
            }

            if (obj_sub_group_dtl["sem_code"].ToString() == "")
            {
                return return_ajax_string("false", "Semester not found");
            }

            if (obj_sub_group_dtl["year_code"].ToString() == "")
            {
                return return_ajax_string("false", "Year Code not found");
            }

            string str_total_subgroup = obj_sub_group_dtl["total_subgroup"].ToString();
            ArrayList lst_instructor_dtl = (ArrayList)obj_sub_group_dtl["instructor_subgroup"];
            ArrayList lst_student_dtl = (ArrayList)obj_sub_group_dtl["student_subgroup"];

            DSC_StudentFoundationDtl obj_student_dtl = new DSC_StudentFoundationDtl();

            if (str_total_subgroup != "")
            {
                for (int i = 1; i <= Int32.Parse(str_total_subgroup); i++)
                {
                    DSC_StudentFoundationDtl.course_sub_groupRow sub_group_row = obj_student_dtl.course_sub_group.Newcourse_sub_groupRow();

                    sub_group_row.sub_group_id = obj_sub_group_dtl["course_code"].ToString() + "_SG" + i.ToString("00");
                    sub_group_row.course_code = obj_sub_group_dtl["course_code"].ToString();
                    sub_group_row.cancel_flag = "N";
                    sub_group_row.semester_type = obj_sub_group_dtl["sem_code"].ToString();
                    sub_group_row.year_semester = obj_sub_group_dtl["year_code"].ToString();
                    sub_group_row.created_by = HttpContext.Current.Session["UserID"].ToString();
                    sub_group_row.created_date = DateTime.Now;
                    sub_group_row.created_host = HttpContext.Current.Request.UserHostName;

                    obj_student_dtl.course_sub_group.Addcourse_sub_groupRow(sub_group_row);
                }
            }

            for (int i = 0; i < lst_instructor_dtl.Count; i++)
            {
                Dictionary<string, object> obj_instructor = (Dictionary<string, object>)lst_instructor_dtl[i];
                DSC_StudentFoundationDtl.course_sub_group_instructorRow instructor_row = obj_student_dtl.course_sub_group_instructor.Newcourse_sub_group_instructorRow();

                instructor_row.sub_group_id = obj_instructor["sub_group"].ToString();
                instructor_row.instructor_code = obj_instructor["instructor_code"].ToString();
                instructor_row.instructor_type = obj_instructor["instructor_type"].ToString();
                instructor_row.cancel_flag = "N";
                instructor_row.semester_type = obj_sub_group_dtl["sem_code"].ToString();
                instructor_row.year_semester = obj_sub_group_dtl["year_code"].ToString();
                instructor_row.created_by = HttpContext.Current.Session["UserID"].ToString();
                instructor_row.created_date = DateTime.Now;
                instructor_row.created_host = HttpContext.Current.Request.UserHostName;

                obj_student_dtl.course_sub_group_instructor.Addcourse_sub_group_instructorRow(instructor_row);
            }

            for (int i = 0; i < lst_student_dtl.Count; i++)
            {
                Dictionary<string, object> obj_student = (Dictionary<string, object>)lst_student_dtl[i];
                DSC_StudentFoundationDtl.course_sub_group_studentRow student_row = obj_student_dtl.course_sub_group_student.Newcourse_sub_group_studentRow();

                student_row.sub_group_id = obj_student["sub_group"].ToString();
                student_row.user_id = obj_student["user_id"].ToString();
                student_row.cancel_flag = "N";
                student_row.semester_type = obj_sub_group_dtl["sem_code"].ToString();
                student_row.year_semester = obj_sub_group_dtl["year_code"].ToString();
                student_row.created_by = HttpContext.Current.Session["UserID"].ToString();
                student_row.created_date = DateTime.Now;
                student_row.created_host = HttpContext.Current.Request.UserHostName;

                obj_student_dtl.course_sub_group_student.Addcourse_sub_group_studentRow(student_row);
            }

            if (obj_student_dtl.course_sub_group.Rows.Count > 0)
            {
                objBLReturnObject = objMaster.save_course_subgroup_dtl(obj_student_dtl, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                if (objBLReturnObject.ExecutionStatus == 2)
                {
                    return return_ajax_string("false", objBLReturnObject.ServerMessage);
                }

                return return_ajax_string("true", objBLReturnObject.ServerMessage);
            }
            else
            {
                return return_ajax_string("false", "Sub Group Detail not found");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("false", ex.Message);
        }

        return "";
    }

