    [WebMethod(EnableSession = true)]
    public string[] Get_OutlinePDF_For_VerticalStudio(string course_code, string sem_code, string year_code)
    {
        string sub_group_id = "";
        string group_id = "";
        int weeks = 16;

        //DataTable dt_mandatory = objmaster.get_course_outline_for_PDF(course_code, current_ws_sem, current_ws_year);
        DataTable dt_get_data = objmaster.Get_studio_code_course_wise(course_code, sem_code, year_code);
        if (dt_get_data != null)
        {
            if (dt_get_data.Rows[0]["new_course_code"].ToString() != "")
            {
                course_code = dt_get_data.Rows[0]["new_course_code"].ToString();
            }
            else if (dt_get_data.Rows[0]["course_code"].ToString() != "")
            {
                course_code = dt_get_data.Rows[0]["course_code"].ToString();
            }
            else if (dt_get_data.Rows[0]["studio_code"].ToString() != "")
            {
                course_code = dt_get_data.Rows[0]["studio_code"].ToString();
            }
        }
        DataTable dt_mandatory = objmaster.get_course_outline_for_PDF(course_code, sem_code, year_code);
        DataTable dt_course_type = objmaster.Get_courseTypemst_data();

        Ds_Student_Course_detail.student_mandatory_courseRow student_mandatory = obj_student.student_mandatory_course.Newstudent_mandatory_courseRow();

        DataTable course_weekly_percent_criteria = objmaster.Get_course_weekly_percent_criteria(course_code, sem_code, year_code);

        DataTable Course_wise_instructor = objmaster.Get_course_wise_instructor(course_code, sem_code, year_code);

        //portfoliolink
        DataTable Portfoliolink = objmaster.get_portfolio_link(course_code, sem_code, year_code);
        //Inst Time Slot
        DataTable dttimeslot = objmaster.Get_instructor_wise_course_time(course_code, sem_code, year_code);
        // Course_wise_time Slot
        DataTable course_time_slot_dt = objmaster.get_course_week_details(course_code, sem_code, year_code);

        if (dt_mandatory != null)
        {
            student_mandatory.course_code = dt_mandatory.Rows[0]["course_code"].ToString();
            student_mandatory.course_name = dt_mandatory.Rows[0]["course_name"].ToString();
            student_mandatory.semester = dt_mandatory.Rows[0]["semester_code"].ToString();
            student_mandatory.credits = dt_mandatory.Rows[0]["course_credits"].ToString();
            student_mandatory.course_desc = dt_mandatory.Rows[0]["course_desc"].ToString();
            student_mandatory.prerequisite = dt_mandatory.Rows[0]["prerequisite"].ToString();
            student_mandatory.prog_course_id = dt_mandatory.Rows[0]["prog_course_id"].ToString();
            student_mandatory.student_current_sem = dt_mandatory.Rows[0]["semester_code"].ToString();
            //student_mandatory.prog_level_code = dt_mandatory.Rows[0]["prog_level_code"].ToString();
            student_mandatory.course_typology = dt_mandatory.Rows[0]["course_typology"].ToString();
            student_mandatory.course_outline = dt_mandatory.Rows[0]["course_outline"].ToString();
            student_mandatory.week1 = dt_mandatory.Rows[0]["week1"].ToString();
            student_mandatory.week2 = dt_mandatory.Rows[0]["week2"].ToString();
            student_mandatory.week3 = dt_mandatory.Rows[0]["week3"].ToString();
            student_mandatory.week4 = dt_mandatory.Rows[0]["week4"].ToString();
            student_mandatory.week5 = dt_mandatory.Rows[0]["week5"].ToString();
            student_mandatory.week6 = dt_mandatory.Rows[0]["week6"].ToString();
            student_mandatory.week7 = dt_mandatory.Rows[0]["week7"].ToString();
            student_mandatory.week8 = dt_mandatory.Rows[0]["week8"].ToString();
            student_mandatory.week9 = dt_mandatory.Rows[0]["week9"].ToString();
            student_mandatory.week10 = dt_mandatory.Rows[0]["week10"].ToString();
            student_mandatory.week11 = dt_mandatory.Rows[0]["week11"].ToString();
            student_mandatory.week12 = dt_mandatory.Rows[0]["week12"].ToString();
            student_mandatory.week13 = dt_mandatory.Rows[0]["week13"].ToString();
            student_mandatory.week14 = dt_mandatory.Rows[0]["week14"].ToString();
            student_mandatory.week15 = dt_mandatory.Rows[0]["week15"].ToString();
            student_mandatory.week16 = dt_mandatory.Rows[0]["week16"].ToString();
            student_mandatory.course_structure = dt_mandatory.Rows[0]["course_structure"].ToString();
            student_mandatory.remark = dt_mandatory.Rows[0]["remark"].ToString();
            student_mandatory.eval_method1 = dt_mandatory.Rows[0]["eval_method1"].ToString();
            student_mandatory.eval_method4 = dt_mandatory.Rows[0]["eval_method4"].ToString();
            student_mandatory.eval_method5 = dt_mandatory.Rows[0]["eval_method5"].ToString();
            student_mandatory.problem_statement = dt_mandatory.Rows[0]["problem_statement"].ToString();
            student_mandatory.sub_category_id = dt_mandatory.Rows[0]["sub_category_id"].ToString();
            student_mandatory.studio_mode = dt_mandatory.Rows[0]["studio_mode"].ToString();
            student_mandatory.StudioSubTitle = dt_mandatory.Rows[0]["CouseSubTitle"].ToString();

            if (dt_course_type != null)
            {
                DataRow[] dr_type = dt_course_type.Select("type_code ='" + dt_mandatory.Rows[0]["course_typology"].ToString() + "'");

                if (dr_type.Length > 0)
                {
                    if (dr_type[0]["type_name"].ToString() != "")
                    {
                        student_mandatory.Course_type_name = dr_type[0]["type_name"].ToString();
                        sub_group_id = dr_type[0]["sub_group"].ToString();
                        group_id = dr_type[0]["group_id"].ToString();
                    }
                }
            }

            string instructor = "";
            if (dt_mandatory != null)
            {
                DataRow[] dr_instructor = dt_mandatory.Select("course_code = '" + course_code + "'");

                if (dr_instructor.Length > 0 && dr_instructor != null)
                {
                    for (int j = 0; j < dr_instructor.Length; j++)
                    {
                        instructor += dr_instructor[j]["instructor_name"].ToString() + ", ";
                    }

                    if (instructor != String.Empty)
                    {
                        //student_mandatory.instructor = instructor.Substring(0, instructor.Length - 1);
                        student_mandatory.instructor = instructor.Trim().TrimEnd(',');
                    }
                }
            }

            obj_student.student_mandatory_course.Addstudent_mandatory_courseRow(student_mandatory);
        }
        else
        {
        }

        DataTable dt = obj_student.student_mandatory_course;

        DataTable course_weeks_data = objmaster.get_course_weeks_typology_wise(dt_mandatory.Rows[0]["dept_code"].ToString(), dt_mandatory.Rows[0]["prog_code"].ToString(), dt_mandatory.Rows[0]["prog_level_code"].ToString(), group_id, dt_mandatory.Rows[0]["course_typology"].ToString());

        if (course_weeks_data != null)
        {
            weeks = Convert.ToInt32(course_weeks_data.Rows[0]["weeks"].ToString());
        }

        if (dt.Rows.Count > 0)
        {
            DataColumn dc1 = new DataColumn("semester_type", typeof(string));
            dc1.DefaultValue = dt_mandatory.Rows[0]["semester_type"].ToString();
            dt.Columns.Add(dc1);

            DataColumn dc2 = new DataColumn("year_semester", typeof(string));
            dc2.DefaultValue = dt_mandatory.Rows[0]["year_semester"].ToString();
            dt.Columns.Add(dc2);

            DataColumn dc3 = new DataColumn("dept_code", typeof(string));
            dc3.DefaultValue = dt_mandatory.Rows[0]["dept_code"].ToString();
            dt.Columns.Add(dc3);

            DataColumn dc4 = new DataColumn("department", typeof(string));
            dc4.DefaultValue = dt_mandatory.Rows[0]["dept_name"].ToString();
            dt.Columns.Add(dc4);

            DataColumn dc5 = new DataColumn("course_expense", typeof(string));
            dc5.DefaultValue = dt_mandatory.Rows[0]["course_expense"].ToString();
            dt.Columns.Add(dc5);

            DataColumn dc6 = new DataColumn("course_assessment", typeof(string));
            dc6.DefaultValue = dt_mandatory.Rows[0]["course_assessment"].ToString();
            dt.Columns.Add(dc6);

            DataColumn sub_group = new DataColumn("sub_group", typeof(string));
            sub_group.DefaultValue = sub_group_id;
            dt.Columns.Add(sub_group);

            DataColumn week = new DataColumn("week", typeof(string));
            week.DefaultValue = weeks;
            dt.Columns.Add(week);
        }

        if (dt != null)
        {
            jsonarray[0] = GetJson1(dt);
        }
        if (course_weekly_percent_criteria != null)
        {
            jsonarray[1] = GetJson1(course_weekly_percent_criteria);
        }
        if (Course_wise_instructor != null)
        {
            jsonarray[2] = GetJson1(Course_wise_instructor);
        }
        if (Portfoliolink != null)
        {
            jsonarray[3] = GetJson1(Portfoliolink);
        }
        if (dttimeslot != null)
        {
            jsonarray[4] = GetJson1(dttimeslot);
        }
        if (course_time_slot_dt != null)
        {
            jsonarray[5] = GetJson1(course_time_slot_dt);
        }
        return jsonarray;
    }

    [WebMethod(EnableSession = true)]
