    [WebMethod(EnableSession = true)]
    public string hostel_fees_payment(string student_selection, string cur_room, string block_name, string docname)
    {
        try
        {

            DSC_HostelFeesPayment obj_HostelFeesPayment = new DSC_HostelFeesPayment();
            DSC_HostelFeesPayment ref_obj_HostelFeesPayment = new DSC_HostelFeesPayment();

            DSC_HostelFeesPayment.hostelFeesPaymentTransactionRow HostelFeesPayment_row = obj_HostelFeesPayment.hostelFeesPaymentTransaction.NewhostelFeesPaymentTransactionRow();

            HostelFeesPayment_row.transaction_id = "1";
            HostelFeesPayment_row.user_id = HttpContext.Current.Session["UserID"].ToString();

            HostelFeesPayment_row.renew = student_selection;

            if (student_selection == "R")
                HostelFeesPayment_row.cur_room = cur_room;

            if (block_name != "")
            {
                HostelFeesPayment_row.block_name = block_name;
            }



            HostelFeesPayment_row.DocName = docname;
            HostelFeesPayment_row.current_sem_code = "0";
            HostelFeesPayment_row.dept_id = HttpContext.Current.Session["dept_code"].ToString();
            HostelFeesPayment_row.payment_send_flag = "Y";
            HostelFeesPayment_row.payment_return_flag = "N";
            string parameter_name = "";
            string gender = HttpContext.Current.Session["gender"].ToString();
            if (gender.ToLower() == "f")
            {
                parameter_name = "girls_hostel_fees_amount";
            }
            else if (gender.ToLower() == "m")
            { parameter_name = "boys_hostel_fees_amount"; }
            DataTable dt_param_data = objmaster.get_parameter_value(parameter_name);

            HostelFeesPayment_row.amount = Convert.ToDecimal(dt_param_data.Rows[0]["parameter_value"].ToString());//13000

            if (HttpContext.Current.Session["UserID"].ToString() == "pa1admin")
            {
                HostelFeesPayment_row.amount = 1;
            }
            if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
            {
                HostelFeesPayment_row.amount = 1;
            }

            HostelFeesPayment_row.status_is_active = "A";
            HostelFeesPayment_row.status_refund = "N";
            HostelFeesPayment_row.status_is_payment_received = "N";

            HostelFeesPayment_row.created_by = HttpContext.Current.Session["UserID"].ToString();
            HostelFeesPayment_row.created_date = DateTime.Now;
            HostelFeesPayment_row.created_host = HttpContext.Current.Request.UserHostName;

            obj_HostelFeesPayment.hostelFeesPaymentTransaction.AddhostelFeesPaymentTransactionRow(HostelFeesPayment_row);

            objBLReturnObject = objMaster.save_hostel_fees_payment(obj_HostelFeesPayment, "2000", "", HttpContext.Current.Request.UserHostName, ref ref_obj_HostelFeesPayment);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                if (ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["amount"].ToString() != "0")
                {
                    string message = "";
                    //string transaction_id = "";
                    //string user_id = "";
                    string dept_code = HttpContext.Current.Session["dept_code"].ToString();
                    //string current_sem_code = "";
                    //string trans_code = "";
                    Payment objPayment = new Payment();
                    Dictionary<string, object> param = new Dictionary<string, object>();
                    Dictionary<string, object> obj_data = new Dictionary<string, object>();

                    bool result = true;

                    string MerchantId = Payment.GetMerchantId(dept_code);

                    string hmac_url = Payment.Get_hmac_url(dept_code);

                    string return_url = "PaymentResponseKotak_HostelFees.aspx";

                    string str_path = "";
                    //if (HttpContext.Current.Request.Url.Segments.Length == 3)
                    //{
                    //    str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + "Student/";
                    //}
                    //else if (HttpContext.Current.Request.Url.Segments.Length == 4) 
                    //{
                    //    str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1] + "Student/";
                    //}

                    if (HttpContext.Current.Request.Url.Segments.Length == 3)
                    {
                        str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0];
                    }
                    else if (HttpContext.Current.Request.Url.Segments.Length == 4)
                    {
                        str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1];
                    }
                    string base_url = "https://" + str_path;
                    obj_data["status"] = result;
                    obj_data["message"] = message;
                    obj_data["user_id"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["user_id"];

                    obj_data["amount"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["amount"];
                    //obj_data["amount"] = 1;

                    obj_data["transaction_id"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["transaction_id"];
                    obj_data["merchant_id"] = MerchantId;
                    obj_data["currency"] = "INR";
                    obj_data["hmac_url"] = hmac_url;
                    obj_data["return_url"] = base_url + return_url;

                    //Kotak PG

                    Dictionary<string, object> dic_payment_dtl = new Dictionary<string, object>();
                    dic_payment_dtl["merchant_id"] = objPayment.Get_Kotak_MerchantId(dept_code);
                    dic_payment_dtl["order_id"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["transaction_id"];
                    dic_payment_dtl["amount"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["amount"];
                    dic_payment_dtl["currency"] = "INR";
                    dic_payment_dtl["redirect_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "PaymentResponseKotak_HostelFees.aspx";
                    dic_payment_dtl["cancel_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "PaymentResponseKotak_HostelFees.aspx";
                    dic_payment_dtl["language"] = "EN";

                    dic_payment_dtl["merchant_param1"] = ref_obj_HostelFeesPayment.hostelFeesPaymentTransaction.Rows[0]["user_id"];
                    dic_payment_dtl["merchant_param2"] = HttpContext.Current.Session["UserName"];
                    dic_payment_dtl["merchant_param3"] = dept_code;
                    dic_payment_dtl["merchant_param4"] = ""; // 28062019
                    dic_payment_dtl["is_hostel"] = "Y";

                    obj_data["kotak_request_url"] = objPayment.Get_Kotak_request_url(dept_code);
                    obj_data["encRequest"] = objPayment.Get_Kotak_encrypted_request(ref dic_payment_dtl);
                    obj_data["access_code"] = objPayment.Get_Kotak_access_code(dept_code);

                    Session["encRequest"] = obj_data["encRequest"];
                    Session["access_code"] = obj_data["access_code"];
                    Session["kotak_request_url"] = obj_data["kotak_request_url"];

                    return JsonConvert.SerializeObject(obj_data);
                }
                else
                {
                    Dictionary<string, object> obj_data = new Dictionary<string, object>();

                    obj_data["status"] = false;
                    obj_data["message"] = "Problem in Payment Redirection, Please try again.";

                    return JsonConvert.SerializeObject(obj_data);
                }
            }
        }
        catch (Exception ex)
        {
            Dictionary<string, object> obj_data = new Dictionary<string, object>();

            obj_data["status"] = false;
            obj_data["message"] = ex.Message;

            return JsonConvert.SerializeObject(obj_data);
            //return "Problem in Fees Payment. Plese try again.";
        }

        return objBLReturnObject.ServerMessage;
    }

