    [WebMethod(EnableSession = true)]
    public string save_parameters_value(string param_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> lst_param_data = ser.Deserialize<List<Dictionary<string, object>>>(param_data);

            DataTable dt_param_data = objmaster.get_parameter_value_all();

            if (dt_param_data != null)
            {
                DSC_Parameter param_mst = new DSC_Parameter();

                for (int i = 0; i < lst_param_data.Count; i++)
                {
                    DataRow[] dr_param_data = dt_param_data.Select("parameter_id='" + lst_param_data[i]["parameter_id"] + "'");

                    if (dr_param_data.Length > 0)
                    {
                        DSC_Parameter.parameter_mstRow param_row = param_mst.parameter_mst.Newparameter_mstRow();

                        param_row.ItemArray = dr_param_data[0].ItemArray;

                        if (param_row.parameter_name == "sws_drop_course_rights" && param_row.parameter_value == "D" && lst_param_data[i]["parameter_value"].ToString() == "E")
                        {
                            param_row.last_modified_date = DateTime.Now;
                        }
                        else if (param_row.parameter_name == "sws_drop_course_rights" && param_row.parameter_value == "E" && lst_param_data[i]["parameter_value"].ToString() == "D")
                        {
                            param_row.last_modified_date = DateTime.Now;
                        }

                        param_row.parameter_value = lst_param_data[i]["parameter_value"].ToString();

                        if (param_row.group_id == 2 || param_row.group_id == 3)
                            param_row.disable_message = lst_param_data[i]["disable_message"].ToString();

                        if (param_row.group_id == 3)
                            param_row.page_path = lst_param_data[i]["page_path"].ToString();

                        param_mst.parameter_mst.Addparameter_mstRow(param_row);
                    }
                }

                if (param_mst.parameter_mst.Rows.Count > 0)
                {
                    objBLReturnObject = objMaster.save_parameters_value(param_mst, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                    }
                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        jsondata = return_ajax_string("True", "Data Saved Successfully");
                    }
                }
                else
                {
                    jsondata = return_ajax_string("False", "No Data Found to update");
                }
            }
            else
            {
                jsondata = return_ajax_string("False", "Parameters Data not Found");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }

        return jsondata;
    }

