    [WebMethod(EnableSession = true)]
    public string save_parameters_current_sem(string param_data)///Kapil 21102020
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        //var ip = HttpContext.Current.Session[]
        try
        {
            string semester = "";
            string year_semester = "";
            string description = "";
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> lst_param_data = ser.Deserialize<List<Dictionary<string, object>>>(param_data);

            DataTable dt_param_data = objmaster.get_parameter_value_current_sem();

            if (dt_param_data != null)
            {
                DSC_Parameter param_mst = new DSC_Parameter();
                for (int i = 0; i < lst_param_data.Count; i++)
                {
                    if (lst_param_data[i]["type_desc"].ToString() == "ws_course")
                    {
                        semester = lst_param_data[i]["sem_code"].ToString();
                        year_semester = lst_param_data[i]["year_code"].ToString();
                        description = lst_param_data[i]["sem_desc"].ToString();
                    }
                    DataRow[] dr_param_data = dt_param_data.Select("doc_no='" + lst_param_data[i]["doc_no"] + "'");

                    if (dr_param_data.Length > 0)
                    {
                        DSC_Parameter.cept_current_semesterRow param_row = param_mst.cept_current_semester.Newcept_current_semesterRow();

                        param_row.ItemArray = dr_param_data[0].ItemArray;
                        param_row.doc_no = lst_param_data[i]["doc_no"].ToString();
                        param_row.sem_code = lst_param_data[i]["sem_code"].ToString();
                        param_row.sem_desc = lst_param_data[i]["sem_desc"].ToString();
                        param_row.year_code = lst_param_data[i]["year_code"].ToString();
                        param_row.last_modified_by = user_id;
                        param_row.last_midified_date = DateTime.Now;
                        param_row.last_modified_host = HttpContext.Current.Request.UserHostName;
                        param_mst.cept_current_semester.Addcept_current_semesterRow(param_row);
                    }
                }


                if (param_mst.cept_current_semester.Rows.Count > 0)
                {

                    objBLReturnObject = objMaster.save_parameters_current_sem(param_mst, "2000", user_id, HttpContext.Current.Request.UserHostName);
                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                        jsondata = return_ajax_string("False", objBLReturnObject.ServerMessage);
                    }

                    else if (objBLReturnObject.ExecutionStatus == 1)
                    {
                        Boolean status = objMaster.ws_current_sem_update(semester, year_semester, description, "Admin", HttpContext.Current.Request.UserHostName);

                        jsondata = return_ajax_string("True", "Data Saved Successfully");
                    }
                }
                else
                {
                    jsondata = return_ajax_string("False", "No Data Found to update");
                }

            }
            else
            {
                jsondata = return_ajax_string("False", "Parameters Data not Found");
            }
        }
        catch (Exception ex)
        {
            jsondata = return_ajax_string("False", ex.ToString());
        }

        return jsondata;

    }

