                    course_Wise_Drp_DtlRow.funded_seats = "2";
                    course_Wise_Drp_DtlRow.unfunded_seats = "3";
                    course_Wise_Drp_DtlRow.cancel_flag = "N";
                    obj_drp_dtl.course_wise_drp_dtl.Addcourse_wise_drp_dtlRow(course_Wise_Drp_DtlRow);
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["doc_no"] = 1;
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["course_code"] = user_mst.Rows[i]["Course_Code"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["topic"] = user_mst.Rows[i]["DRP_Title"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["form_type"] = "29";
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["vacant_seats"] = user_mst.Rows[i]["DRP_Seats"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["funded_seats"] = user_mst.Rows[i]["DRP_Funded_Seats"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["unfunded_seats"] = user_mst.Rows[i]["DRP_Un_Funded_Seats"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["abstracts"] = user_mst.Rows[i]["Abstract"].ToString();
