                    {
                        obj_drp_dtl.course_wise_drp_dtl.Rows[i]["reference"] = user_mst.Rows[i]["References"].ToString();
                    }
                    else
                    {
                        obj_drp_dtl.course_wise_drp_dtl.Rows[i]["reference"] = null;
                    }
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["semester_type"] = user_mst.Rows[i]["semester_type"].ToString();
                    ServerLog.ExceptionLog(" 3 semester_type :");
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["year_semester"] = user_mst.Rows[i]["year_semester"].ToString();
                    ServerLog.ExceptionLog(" 3 year_semester :");

                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["cancel_flag"] = "N";
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["created_by"] = HttpContext.Current.Session["UserId"].ToString();
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["created_date"] = DateTime.Now;
                    obj_drp_dtl.course_wise_drp_dtl.Rows[i]["created_host"] = HttpContext.Current.Request.UserHostName;
                }
            }

            if (dt_error.Rows.Count > 0)
            {
                jsondata = GetJson1(dt_error);
                return jsondata;
            }
            objBLReturnObject = objMaster.save_drp_dtl_upload(obj_drp_dtl, "2000", HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in save data " + objBLReturnObject.ServerMessage;

                return objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                return "DRP Details Saved Successfully";
            }

        }
        catch (Exception ex)
        {
            return "Problem in save data";
        }
        return objBLReturnObject.ServerMessage;
    }

