    [WebMethod(EnableSession = true)]
    public string get_submitted_student_clearance_form(string sem_code, string year_code, string student_id, string dept_type, string status)
    {
        string User_id = HttpContext.Current.Session["UserId"].ToString();
        string User_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable dt_param_data = null;

        DataTable clearance_form_current_sem_detail = objmaster.get_current_clearance_form_semester();

        if (sem_code == "" && year_code == "" && student_id == "")
        {
            if (User_type == "S")
            {
                DataTable checked_dt = objmaster.checked_data_for_clearance_certificate(User_id);

                if (checked_dt == null)
                {
                    sem_code = clearance_form_current_sem_detail.Rows[0]["sem_code"].ToString();
                    year_code = clearance_form_current_sem_detail.Rows[0]["year_code"].ToString();
                }
                else
                {
                    sem_code = checked_dt.Rows[0]["semester_type"].ToString();
                    year_code = checked_dt.Rows[0]["year_semester"].ToString();
                }
            }
            else
            {
                sem_code = clearance_form_current_sem_detail.Rows[0]["sem_code"].ToString();
                year_code = clearance_form_current_sem_detail.Rows[0]["year_code"].ToString();
            }

            DataTable filtered_status_data = null;

            dt_param_data = objmaster.get_submitted_student_clearance_form(sem_code, year_code, User_id, User_type + "#-");

            DataTable dt_department_ids = objmaster.get_department_id_submitted_clearance_form(sem_code, year_code, User_id, User_type);

            if (dt_department_ids != null)
            {
                if (dt_param_data != null)
                {
                    filtered_status_data = dt_param_data.Clone();
                }


                for (int i = 0; i < dt_department_ids.Rows.Count; i++)
                {
                    DataTable dt_stud_Details = dt_param_data.Select("department_id ='" + dt_department_ids.Rows[i]["department_id"].ToString() + "'").CopyToDataTable();

                    if (dt_stud_Details.Rows.Count > 2)
                    {
                        //It is Approved
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            if (dr.ItemArray[3].ToString() == "Approved")
                            {
                                filtered_status_data.Rows.Add(dr.ItemArray);
                            }
                        }
                    }
                    else if (dt_stud_Details.Rows.Count > 1)
                    {
                        bool A = false;
                        bool H = false;
                        //It is Pending > Approved
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            //If Approved
                            if (!A && !H)
                            {
                                if (dr.ItemArray[3].ToString() == "Approved")
                                {
                                    filtered_status_data.Rows.Add(dr.ItemArray);
                                    A = true;
                                }
                                if (dr.ItemArray[3].ToString() == "On Hold")
                                {
                                    filtered_status_data.Rows.Add(dr.ItemArray);
                                    H = true;
                                }
                            }
                        }
                        //It is Pending > On Hold
                    }
                    else if (dt_stud_Details.Rows.Count == 1)
                    {
                        //It is Pending 
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            filtered_status_data.Rows.Add(dr.ItemArray);
                        }
                    }
                }

                if (dt_param_data != null)
                {
                    dt_param_data = filtered_status_data.Clone();
                    dt_param_data = filtered_status_data.Copy();
                }
            }

        }
        else
        {
            if (student_id == "")
            {
                student_id = "-";
            }

            DataTable filtered_status_data = null;
            DataTable dt_users_ids = null;

            if (User_id == "AC004" && dept_type == "D5")
            {
                dt_param_data = objmaster.get_submitted_student_clearance_form_female_hostel(sem_code, year_code, User_id, User_type + "#" + student_id);
                dt_users_ids = objmaster.get_student_id_submitted_clearance_form_female_hostel(sem_code, year_code, User_id, User_type);
            }
            else
            {
                dt_param_data = objmaster.get_submitted_student_clearance_form(sem_code, year_code, User_id, User_type + "#" + student_id);
                dt_users_ids = objmaster.get_student_id_submitted_clearance_form(sem_code, year_code, User_id, User_type);
            }

            if (dt_users_ids != null)
            {
                if (dt_param_data != null)
                {
                    filtered_status_data = dt_param_data.Clone();
                }

                if (student_id != "-")
                {
                    DataTable dt_stud_Details = dt_param_data.Select("user_id ='" + student_id + "'").CopyToDataTable();

                    if (dt_stud_Details.Rows.Count > 2)
                    {
                        //It is Approved
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            if (dr.ItemArray[7].ToString() == "Approved")
                            {
                                filtered_status_data.Rows.Add(dr.ItemArray);
                            }
                        }
                    }
                    else if (dt_stud_Details.Rows.Count > 1)
                    {
                        bool A = false;
                        bool H = false;
                        //It is Pending > Approved
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            //If Approved
                            if (!A && !H)
                            {
                                if (dr.ItemArray[7].ToString() == "Approved")
                                {
                                    filtered_status_data.Rows.Add(dr.ItemArray);
                                    A = true;
                                }
                                if (dr.ItemArray[7].ToString() == "On Hold")
                                {
                                    filtered_status_data.Rows.Add(dr.ItemArray);
                                    H = true;
                                }
                            }
                        }
                        //It is Pending > On Hold
                    }
                    else if (dt_stud_Details.Rows.Count == 1)
                    {
                        //It is Pending 
                        foreach (DataRow dr in dt_stud_Details.Rows)
                        {
                            filtered_status_data.Rows.Add(dr.ItemArray);
                        }
                    }
                }
                else
                {
                    for (int i = 0; i < dt_users_ids.Rows.Count; i++)
                    {
                        DataTable dt_stud_Details = dt_param_data.Select("user_id ='" + dt_users_ids.Rows[i]["user_id"].ToString() + "'").CopyToDataTable();

                        if (dt_stud_Details.Rows.Count > 2)
                        {
                            //It is Approved
                            foreach (DataRow dr in dt_stud_Details.Rows)
                            {
                                if (dr.ItemArray[7].ToString() == "Approved")
                                {
                                    filtered_status_data.Rows.Add(dr.ItemArray);
                                }
                            }
                        }
                        else if (dt_stud_Details.Rows.Count > 1)
                        {
                            bool A = false;
                            bool H = false;
                            //It is Pending > Approved
                            foreach (DataRow dr in dt_stud_Details.Rows)
                            {
                                //If Approved
                                if (!A && !H)
                                {
                                    if (dr.ItemArray[7].ToString() == "Approved")
                                    {
                                        filtered_status_data.Rows.Add(dr.ItemArray);
                                        A = true;
                                    }
                                    if (dr.ItemArray[7].ToString() == "On Hold")
                                    {
                                        filtered_status_data.Rows.Add(dr.ItemArray);
                                        H = true;
                                    }
                                }
                            }
                            //It is Pending > On Hold
                        }
                        else if (dt_stud_Details.Rows.Count == 1)
                        {
                            //It is Pending 
                            foreach (DataRow dr in dt_stud_Details.Rows)
                            {
                                filtered_status_data.Rows.Add(dr.ItemArray);
                            }
                        }
                    }

                }
                if (dt_param_data != null)
                {
                    dt_param_data = filtered_status_data.Clone();
                    dt_param_data = filtered_status_data.Copy();
                }
            }
        }

        DataTable dtfiltereddata = new DataTable();

        if (status != "" && dt_param_data != null)
        {
            dtfiltereddata = dt_param_data.Clone();

            DataRow[] results = dt_param_data.Select("status ='" + status + "'");

            foreach (DataRow dr in results)
            {
                dtfiltereddata.Rows.Add(dr.ItemArray);
            }

            dt_param_data.Rows.Clear();

            foreach (DataRow dr in dtfiltereddata.Rows)
            {
                dt_param_data.Rows.Add(dr.ItemArray);
            }
        }

        if (dt_param_data != null)
        {
            jsondata = GetJson1(dt_param_data);
        }

        return jsondata;
    }


    [WebMethod(EnableSession = true)]
    public string get_submitted_student_clearance_form_new(string sem_code, string year_code, string student_id, string dept_type, string status)
