    [WebMethod(EnableSession = true)]
    public string submit_student_clearance_form(string student_clearance_form_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string User_id;
        Boolean submitted_form = false;
        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                User_id = HttpContext.Current.Session["UserId"].ToString();
            }

            DataTable clearance_form_current_sem_detail = objmaster.get_current_clearance_form_semester();

            ArrayList arr_student_clearance_form_data = ser.Deserialize<ArrayList>(student_clearance_form_data);

            for (int i = 0; i < arr_student_clearance_form_data.Count; i++)
            {

                Dictionary<string, object> data = (Dictionary<string, object>)arr_student_clearance_form_data[i];

                submitted_form = objmaster.Submission_Clearance_Form(data, clearance_form_current_sem_detail.Rows[0]["sem_code"].ToString(), clearance_form_current_sem_detail.Rows[0]["year_code"].ToString(), User_id);

                if (!submitted_form)
                {
                    Boolean delete_form = objmaster.deletion_of_Submission_Clearance_Form(clearance_form_current_sem_detail.Rows[0]["sem_code"].ToString(), clearance_form_current_sem_detail.Rows[0]["year_code"].ToString(), User_id);

                    return return_ajax_string("1", "Problem in Submitting Form.");
                }
            }

            if (submitted_form)
            {
                Mail objmail = new Mail();

                DataTable AckDetails = objmaster.Get_VF_TA_AA_Letter_Email_Body("ClearanceForm", "email");

                DataTable StudentDetails = objmaster.Get_student_personal_data(User_id);

                DataTable DepartmentDetails = objmaster.get_department_for_student_clearance(user_prog_code);

                bool mail_status = objmail.SendEmailWhileStudentSubmitClearanceForm(AckDetails, StudentDetails, DepartmentDetails);

                if (mail_status)
                {
                    return return_ajax_string("0", "Clearance Form Submitted and Mail Sent Successfully.");
                }
                else
                {
                    Boolean delete_form = objmaster.deletion_of_Submission_Clearance_Form(clearance_form_current_sem_detail.Rows[0]["sem_code"].ToString(), clearance_form_current_sem_detail.Rows[0]["year_code"].ToString(), User_id);

                    return return_ajax_string("1", "Problem in Sending Mail.");
                }
            }
            else
            {
                return return_ajax_string("1", "Problem in Submitting Form or Sending Mail.");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }
    }

    [WebMethod(EnableSession = true)]
    public string save_action_for_clearance_form(string action_request)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string user_id;
        string User_type = HttpContext.Current.Session["user_type"].ToString();
        Boolean save_action = false;
        string department_name = "";
        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "user id not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            Dictionary<string, object> obj_action_request = ser.Deserialize<Dictionary<string, object>>(action_request);

            if (user_id == "AC004" && obj_action_request["dept_type"].ToString() == "D5")
            {
                DataTable dt_param_data = objmaster.get_submitted_student_clearance_form_female_hostel(obj_action_request["sem"].ToString(), obj_action_request["year"].ToString(), user_id, User_type + "-#" + obj_action_request["student_id"].ToString());

                save_action = objmaster.Action_Save_Clearance_Form(obj_action_request, dt_param_data, user_id);

                department_name = dt_param_data.Rows[0]["department_name"].ToString();
            }
            else if (user_id == "CU00200")
            {
                DataTable dt_param_data = objmaster.get_user_mst_data(obj_action_request["sem"].ToString(), obj_action_request["year"].ToString(), "'" + obj_action_request["student_id"].ToString() + "'");

                save_action = objmaster.Action_Save_Clearance_Form(obj_action_request, dt_param_data, user_id);

                department_name = dt_param_data.Rows[0]["department_name"].ToString();
            }
            else
            {
                DataTable dt_param_data = objmaster.get_submitted_student_clearance_form(obj_action_request["sem"].ToString(), obj_action_request["year"].ToString(), user_id, User_type + "-#" + obj_action_request["student_id"].ToString());

                save_action = objmaster.Action_Save_Clearance_Form(obj_action_request, dt_param_data, user_id);

                if (User_type == "AC" && obj_action_request["action"].ToString() == "Approved")
                {
                    DataTable dt_param_data_AD = objmaster.get_AC2_data_of_account_details(obj_action_request["sem"].ToString(), obj_action_request["year"].ToString(), obj_action_request["student_id"].ToString());

                    save_action = objmaster.Action_Save_Clearance_Form(obj_action_request, dt_param_data_AD, user_id);
                }

                department_name = dt_param_data.Rows[0]["department_name"].ToString();
            }

            if (save_action)
            {
                if (obj_action_request["action"].ToString() == "Approved")
                {
                    DataTable AckDetails = objmaster.Get_VF_TA_AA_Letter_Email_Body("AClearanceForm", "email");

                    DataTable StudentDetails = objmaster.Get_student_personal_data(obj_action_request["student_id"].ToString());

                    bool mail_status = objmail.SendEmailWhileSaveActionClearanceForm(AckDetails, StudentDetails, department_name);
                }
                else if (obj_action_request["action"].ToString() == "On Hold")
                {
                    DataTable AckDetails = objmaster.Get_VF_TA_AA_Letter_Email_Body("HClearanceForm", "email");

                    DataTable StudentDetails = objmaster.Get_student_personal_data(obj_action_request["student_id"].ToString());

                    bool mail_status = objmail.SendEmailWhileSaveActionClearanceForm(AckDetails, StudentDetails, department_name);
                }

                return return_ajax_string("0", obj_action_request["action"].ToString() + " Action Saved and Mail Sent Successfully.");
            }
            else
            {
                return return_ajax_string("1", "Problem in Save data or Sending Mail");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }
    }

