    [WebMethod(EnableSession = true)]
    public string get_all_approved_clearance_form_for_registrar(string sem_code, string year_code, string student_id, string status)
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();
        DataTable sem_data_bind = null;
        DataTable dt = objmaster.clearance_sem_year(sem_code, year_code);

        if (dt != null)
        {
            for (int p = 0; p < dt.Rows.Count; p++)
            {
                sem_code = dt.Rows[p]["semester_type"].ToString();
                year_code = dt.Rows[p]["year_semester"].ToString();

                DataTable dt_param_data = objmaster.get_all_approved_clearance_form_for_registrar(sem_code, year_code, student_id);

                DataTable check_count_data = objmaster.get_all_approved_clearance_form_count_for_registrar(sem_code, year_code);

                if (year_code != "2020")
                {
                    check_count_data.Rows[0]["approval_count"] = Convert.ToInt32(check_count_data.Rows[0]["approval_count"]) - 1;//UGorPG If any 1 s less 1
                }

                String student_code = "";
                String approved_student_code = "";

                if (dt_param_data != null)
                {
                    for (int i = 0; i < dt_param_data.Rows.Count; i++)
                    {

                        if (dt_param_data.Rows[i]["prog_code"].ToString() == "3" && (Convert.ToDecimal(dt_param_data.Rows[i]["approved_count"].ToString()) == Convert.ToDecimal("10")))
                        {
                            if (student_code == "")
                                student_code += "'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                            else
                                student_code += ",'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                        }
                        else if (Convert.ToDecimal(dt_param_data.Rows[i]["approved_count"].ToString()) == Convert.ToDecimal(check_count_data.Rows[0]["approval_count"].ToString()))
                        {
                            if (dt_param_data.Rows[i]["prog_code"].ToString() == "3" && (Convert.ToDecimal(check_count_data.Rows[0]["approval_count"].ToString()) == Convert.ToDecimal("11")))
                            {
                                if (approved_student_code == "")
                                    approved_student_code += "'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                                else
                                    approved_student_code += ",'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                            }
                            else
                            {
                                if (student_code == "")
                                    student_code += "'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                                else
                                    student_code += ",'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                            }
                        }
                        else if (Convert.ToDecimal(dt_param_data.Rows[i]["approved_count"].ToString()) > Convert.ToDecimal(check_count_data.Rows[0]["approval_count"].ToString()))
                        {
                            if (approved_student_code == "")
                                approved_student_code += "'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                            else
                                approved_student_code += ",'" + dt_param_data.Rows[i]["user_id"].ToString() + "'";
                        }
                    }

                    dt_param_data = objmaster.get_user_mst_data(sem_code, year_code, student_code);

                    DataTable approved_dt_param_data = null;

                    if (approved_student_code != "")
                        approved_dt_param_data = objmaster.get_approved_user_mst_data(sem_code, year_code, approved_student_code);

                    if (approved_dt_param_data != null)
                    {
                        if (dt_param_data == null) dt_param_data = approved_dt_param_data.Clone();

                        foreach (DataRow dr in approved_dt_param_data.Rows)
                        {
                            dt_param_data.Rows.Add(dr.ItemArray);
                        }
                    }
                }
                else
                {
                    return jsondata;
                }

                DataTable dtfiltereddata = new DataTable();

                if (status != "" && dt_param_data != null)
                {
                    dtfiltereddata = dt_param_data.Clone();

                    DataRow[] results = dt_param_data.Select("status ='" + status + "'");

                    foreach (DataRow dr in results)
                    {
                        dtfiltereddata.Rows.Add(dr.ItemArray);
                    }

                    dt_param_data.Rows.Clear();

                    foreach (DataRow dr in dtfiltereddata.Rows)
                    {
                        dt_param_data.Rows.Add(dr.ItemArray);
                    }
                }

                if (dt_param_data != null)
                {
                    if (sem_data_bind == null)
                    {
                        sem_data_bind = dt_param_data.Clone();
                    }

                    foreach (DataRow dr in dt_param_data.Rows)
                    {
                        sem_data_bind.Rows.Add(dr.ItemArray);
                    }

                }
            }
        }
        if (sem_data_bind != null)
        {
            sem_data_bind.DefaultView.Sort = "user_id ASC";
            jsondata = GetJson1(sem_data_bind);
        }
        //if (dt_param_data != null)
        //{
        //    jsondata = GetJson1(dt_param_data);
        //}

        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string get_all_approved_clearance_form_for_account(string sem_code, string year_code, string student_id, string type)
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();

        DataTable dt_param_data = objmaster.get_all_approved_clearance_form_for_account(user_id, sem_code, year_code, student_id, type);

        DataTable dt_approved_data = objmaster.get_registrar_approved_clearance_form_for_account(user_id, sem_code, year_code, student_id);

        if (dt_param_data != null)
        {
            dt_param_data.Columns.Add("registrar_created_date");

            for (int i = 0; i < dt_param_data.Rows.Count; i++)
            {
                DataRow[] dt_approved_data_row;

                dt_approved_data_row = dt_approved_data.Select("user_id ='" + dt_param_data.Rows[i]["user_id"].ToString() + "'");

                dt_param_data.Rows[i]["registrar_created_date"] = dt_approved_data_row[0]["created_date"].ToString();
            }

            jsondata = GetJson1(dt_param_data);
        }

        return jsondata;
    }
