    [WebMethod(EnableSession = true)]
    public string GenerateOTP(string mobile_no)
    {
        string strrandom = string.Empty;

        try
        {
            char[] charArr = "0123456789".ToCharArray();

            Random objran = new Random();
            int noofcharacters = 4;
            for (int i = 0; i < noofcharacters; i++)
            {
                //It will not allow Repetation of Characters
                int pos = objran.Next(1, charArr.Length);
                if (!strrandom.Contains(charArr.GetValue(pos).ToString()))
                    strrandom += charArr.GetValue(pos);
                else
                    i--;

            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }

        if (strrandom != "")
        {
            bool SMS = objmail.SendSMS(mobile_no, strrandom);
            if (SMS)
            {
                HttpContext.Current.Session["OTP"] = strrandom;
                HttpContext.Current.Session["OTP_MobileNo"] = mobile_no;

                return return_ajax_string("0", "OTP Sent Successfully. Please Enter OTP and Click Register.");
            }
            else
            {
                return return_ajax_string("1", "OTP not Sent. Please try again later.");
            }
        }
        else
        {
            return return_ajax_string("1", "Failed to generate OTP. Please try again later.");
        }
    }

