            DataTable dt_next_doc_no = objmaster.GetNextDocNobyDocType("IS");
            string new_doc_number_formate = objmaster.formatewisedoc_no(dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString());
            dt_next_doc_no.Rows[0]["next_doc_no"] = new_doc_number_formate.ToString();

            DataTable dtUserAccountId = objmaster.check_user_by_user_id(dt_next_doc_no.Rows[0]["next_doc_no"].ToString());

            if (dtUserAccountId != null)
