                //return return_ajax_string("1", "User is Exists with User ID. Please try again.");
                int next_doc_no = Convert.ToInt32(dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString()) + 1;
                bool update_no = objmaster.UpdateNextDocNo(next_doc_no, "IS");
                dt_next_doc_no = objmaster.GetNextDocNobyDocType("IS");
