                    return return_ajax_string("1", "Registred Successful. Verification Email not sent. Contact CEPT University for verification.");
                }

            }
            else
            {
                //delete query
                bool delete_account = objmaster.DeleteUserAccount(dt_next_doc_no.Rows[0]["next_doc_no"].ToString());
                //bool delete_account = objmaster.DeleteUserAccount(data_next_doc_no.ToString());

                return return_ajax_string("1", "Error while Registering. Please try again later.");
