            return return_ajax_string("1", ex.ToString());
            //}
            //else
            //{
            //    return return_ajax_string("1", "OTP not found. Please generate OTP.");
            //}
        }
    }

    [WebMethod(EnableSession = true)]
    public string VerifyUserDetails(string mail, string verification_token)
    {
        try
        {
            //DataTable dt_alumini_registration_dtl_1st = objmaster.get_alumini_registration_details("", "Y", mail);

            //if (dt_alumini_registration_dtl_1st == null)
            //{
            //    DataTable dtUserAccount = objmaster.check_alumini_user_Admin_Upload(mail);

            //    if (dtUserAccount != null)
            //    {
            //        if (dtUserAccount.Rows[0]["user_status_flag"].ToString() == "A" && dtUserAccount.Rows[0]["status"].ToString() == "A")
            //        {
            //            return return_ajax_string("1", "E-Mail ID Already Verified.");
            //        }
            //    }
            //}

            DataTable dtVerifyToken = objmaster.VerifyToken(mail, verification_token);

            if (dtVerifyToken == null)
            {
                return return_ajax_string("1", "E-Mail ID Verification Token not matched or Already Verified.");
            }

            bool verified_user = objmaster.VerifyUserDetails(mail, verification_token);

            if (verified_user)
            {
                return return_ajax_string("0", "E-Mail Verification Successful. Now you can login to system.");
            }
            else
            {
                return return_ajax_string("1", "Email verification Failed. Please contact Administrator.");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }
    }

