    [WebMethod(EnableSession = true)]
    public string submit_interested_program(string interested_program_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string user_id;
        string mail_id = "";
        Boolean mail_status = false;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            string user_type = HttpContext.Current.Session["UserId"].ToString();

            DataTable dt_call_for_studio_current_sem_data = objmaster.getCurrentSemYearCallForStudio();

            ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_program_data);

            DSC_VF_Mgmt instructor_teaching_intrest = new DSC_VF_Mgmt();
            //DSC_Vertical_Studio_Selection_dtl studio_wise_instructor_dtl = new DSC_Vertical_Studio_Selection_dtl();
            DSC_Parameter studio_wise_instructor_dtl = new DSC_Parameter();

            int re = 0;
            string semester_type = "";
            string year_semester = "";
            string instCode = "";
            for (int i = 0; i < arr_interested_program_data.Count; i++)
            {
                Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];

                string dd = data["studio_title"].ToString().Replace("&#39;", "''");
                dd = dd.Replace("&#34;", "\"");
                dd = dd.Replace("&#40;", "(");
                dd = dd.Replace("&#41;", "(");
                dd = dd.Replace("&#60;", "<");
                dd = dd.Replace("&#62;", ">");
                dd = dd.Replace("&#64;", "@");
                dd = dd.Replace("&#38;", "&");
                dd = dd.Replace("&#47;", "/");


                string studio_subtitle = data["studio_subtitle"].ToString().Replace("&#39;", "''");
                studio_subtitle = studio_subtitle.Replace("&#34;", "\"");
                studio_subtitle = studio_subtitle.Replace("&#40;", "(");
                studio_subtitle = studio_subtitle.Replace("&#41;", "(");
                studio_subtitle = studio_subtitle.Replace("&#60;", "<");
                studio_subtitle = studio_subtitle.Replace("&#62;", ">");
                studio_subtitle = studio_subtitle.Replace("&#64;", "@");
                studio_subtitle = studio_subtitle.Replace("&#38;", "&");
                studio_subtitle = studio_subtitle.Replace("&#47;", "/");



                string studio_description = data["studio_description"].ToString().Replace("&#39;", "''");
                studio_description = studio_description.Replace("&#34;", "\"");
                studio_description = studio_description.Replace("&#40;", "(");
                studio_description = studio_description.Replace("&#41;", "(");
                studio_description = studio_description.Replace("&#60;", "<");
                studio_description = studio_description.Replace("&#62;", ">");
                studio_description = studio_description.Replace("&#64;", "@");
                studio_description = studio_description.Replace("&#38;", "&");
                studio_description = studio_description.Replace("&#47;", "/");

                DSC_VF_Mgmt.instructor_teaching_interestRow teaching_int_row = instructor_teaching_intrest.instructor_teaching_interest.Newinstructor_teaching_interestRow();

                semester_type = data["sem"].ToString();
                year_semester = data["year"].ToString();
                instCode = data["inst_code"].ToString();
                re = re + 1;
                teaching_int_row.doc_no = re.ToString();
                teaching_int_row.user_id = user_id;
                teaching_int_row.dept_code = data["dept_code"].ToString();
                teaching_int_row.prog_code = data["prog_code"].ToString();
                teaching_int_row.prog_level_code = data["prog_level_code"].ToString();
                teaching_int_row.studio_level = data["studio_level"].ToString();
                teaching_int_row.semester_type = data["sem"].ToString();
                teaching_int_row.year_semester = data["year"].ToString();
                teaching_int_row.cancel_flag = "N";
                teaching_int_row.created_by = user_id;
                teaching_int_row.created_date = DateTime.Now;
                teaching_int_row.created_host = HttpContext.Current.Request.UserHostName;
                teaching_int_row.studio_code = re.ToString();
                teaching_int_row.studio_title = dd;
                teaching_int_row.no_of_tutor = data["no_of_tutor"].ToString();
                teaching_int_row.teaching_mode = data["teaching_mode"].ToString();
                teaching_int_row.studio_description = studio_description;
                teaching_int_row.previous_sem_course_code = data["previous_sem_course_code"].ToString();
                teaching_int_row.previous_sem_code = data["previous_sem_code"].ToString();
                teaching_int_row.previous_year_code = data["previous_year_code"].ToString();
                teaching_int_row.studio_subtitle = studio_subtitle;


                // By Aashitha 25082023 
                teaching_int_row.previous_type = data["previous_type"].ToString();
                teaching_int_row.Portfolio_change_type = data["Portfolio_change_type"].ToString();


                instructor_teaching_intrest.instructor_teaching_interest.Addinstructor_teaching_interestRow(teaching_int_row);
                //instructor_teaching_intrest.instructor_teaching_interest.ImportRow(teaching_int_row);

                DSC_VF_Mgmt.instructor_studio_detailsRow studio_details_row = instructor_teaching_intrest.instructor_studio_details.Newinstructor_studio_detailsRow();
                studio_details_row.user_id = user_id;
                studio_details_row.studio_code = re.ToString();
                //studio_details_row.ppt_video = "";
                //studio_details_row.course_code = "";
                studio_details_row.approved = "N";

                studio_details_row.studio_brief_status = "N";
                studio_details_row.semester_type = data["sem"].ToString();
                studio_details_row.year_semester = data["year"].ToString();
                if (Convert.ToBoolean(data["mail_status"]) == true)
                {
                    studio_details_row.is_submit = "Y";
                }
                else { studio_details_row.is_submit = "N"; }
                studio_details_row.cancel_flag = "N";
                studio_details_row.created_by = user_id;
                studio_details_row.created_date = DateTime.Now;
                studio_details_row.created_host = HttpContext.Current.Request.UserHostName;
                mail_status = Convert.ToBoolean(data["mail_status"].ToString());
                instructor_teaching_intrest.instructor_studio_details.Addinstructor_studio_detailsRow(studio_details_row);


                //15022022


                string[] inst_data = data["inst_code"].ToString().Split(',');
                string[] tutor_data = data["tutor_type"].ToString().Split(',');
                string[] to_be_later = data["to_be_later"].ToString().Split(',');

                for (int k = 0; k < inst_data.Length; k++)
                {
                    // DSC_Vertical_Studio_Selection_dtl.studio_wise_instructor_dtlRow studio_wise_inst_row = studio_wise_instructor_dtl.studio_wise_instructor_dtl.Newstudio_wise_instructor_dtlRow();
                    DSC_Parameter.studio_wise_instructor_dtlRow studio_wise_inst_row = studio_wise_instructor_dtl.studio_wise_instructor_dtl.Newstudio_wise_instructor_dtlRow();

                    studio_wise_inst_row.studio_code = (k + 1).ToString();

                    //studio_wise_inst_row.studio_code = (k+1).ToString();

                    if (to_be_later[k].ToString() == "Y")
                    {
                        studio_wise_inst_row.instructor_code = inst_data[k].ToString();
                        studio_wise_inst_row.brief_edit_status = "N";
                        studio_wise_inst_row.tutor_type = null;
                        studio_wise_inst_row.semester_type = data["sem"].ToString();
                        studio_wise_inst_row.year_semester = data["year"].ToString();
                        studio_wise_inst_row.approved = "N";
                        studio_wise_inst_row.cancel_flag = "N";
                        studio_wise_inst_row.to_be_later = "Y";
                        studio_wise_inst_row.created_by = user_id;
                        studio_wise_inst_row.created_date = DateTime.Now;
                        studio_wise_inst_row.created_host = HttpContext.Current.Request.UserHostName;
                    }
                    else
                    {

                        studio_wise_inst_row.instructor_code = inst_data[k].ToString();
                        if (k == 0)
                        {
                            mail_id = inst_data[k].ToString();

                        }
                        else { mail_id += "," + inst_data[k].ToString(); }
                        if (tutor_data[k].ToString().Trim() == "T")
                        {
                            studio_wise_inst_row.brief_edit_status = "Y";
                        }
                        else { studio_wise_inst_row.brief_edit_status = "N"; }
                        studio_wise_inst_row.tutor_type = tutor_data[k].ToString();
                        studio_wise_inst_row.approved = "N";
                        studio_wise_inst_row.semester_type = data["sem"].ToString();
                        studio_wise_inst_row.year_semester = data["year"].ToString();
                        studio_wise_inst_row.cancel_flag = "N";
                        studio_wise_inst_row.created_by = user_id;
                        studio_wise_inst_row.created_date = DateTime.Now;
                        studio_wise_inst_row.created_host = HttpContext.Current.Request.UserHostName;
                    }
                    studio_wise_instructor_dtl.studio_wise_instructor_dtl.Addstudio_wise_instructor_dtlRow(studio_wise_inst_row);
                }


            }

            BLReturnObject Log_objBLReturnObject = new BLReturnObject();

            objBLReturnObject = objMaster.save_instructor_teaching_intrest_data(instructor_teaching_intrest, studio_wise_instructor_dtl, user_type, user_id, dt_call_for_studio_current_sem_data);

            //if (objBLReturnObject.ExecutionStatus == 1)
            //{
            //    return return_ajax_string("1", "Data Saved Successfully");
            //}

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                return return_ajax_string("1", "Problem in update data " + objBLReturnObject.ServerMessage);
            }
            else
            {

                string activity_description = "";
                string activity_action_name = "";
                string activity_type = "StudioProposal";
                string studio_code = objBLReturnObject.ServerMessage;
                string course_code = "";
                activity_description = "Save Studio Proposal";
                activity_action_name = "Save";
                string status_log = studio_log_create(user_id, activity_type, activity_description, activity_action_name, user_id, studio_code, course_code);

                #region RateBandinsert 
                bool InsertVFRateBand = objmaster.CalculateRateBandMonthWise(user_id, semester_type, year_semester, studio_code);
                #endregion

            }

            bool ppt_video_saved = objMaster.save_instructor_studio_details(instructor_teaching_intrest, user_type, user_id, dt_call_for_studio_current_sem_data, objBLReturnObject.ServerMessage);

            if (mail_status == true && ppt_video_saved == true)
            {
                DataTable dt_send_mail_data = objmaster.Get_VF_TA_AA_Letter_Email_Body("StudioProposal", "email");
                string[] user_wise_mail = mail_id.ToString().Split(',');

                //change mail

                for (int j = 0; j < user_wise_mail.Length; j++)
                {
                    DataTable user_dtl = objmaster.check_user_by_user_id(user_wise_mail[j].ToString());
                    DataTable mail_from_id_password = objmaster.check_frommail_id_password("StudioProposal");

                    bool status = objmail.sendmailforstudioDetails(user_id, user_type, user_dtl, mail_from_id_password, dt_send_mail_data);

                    //for (int j = 0; j < user_wise_mail.Length; j++) 
