    [WebMethod(EnableSession = true)]
    public string update_interested_program(string interested_program_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string user_id;
        Boolean mail_status = false;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }
            string user_type = HttpContext.Current.Session["UserId"].ToString();
            ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_program_data);

            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[0];

            bool update_proposal = objMaster.update_interested_program(user_id, data);
            mail_status = Convert.ToBoolean(data["mail_status"].ToString());

            if (mail_status == true && update_proposal == true)
            {
                DataTable dt_send_mail_data = objmaster.Get_VF_TA_AA_Letter_Email_Body("StudioProposal", "email");
                string[] inst_data = data["inst_code"].ToString().Split(',');
                string[] to_be_later = data["to_be_later"].ToString().Split(',');
                for (int i = 0; i < inst_data.Length; i++)
                {
                    if (to_be_later[i].ToString() != "Y")
                    {
                        DataTable user_dtl = objmaster.check_user_by_user_id(inst_data[i].ToString());
                        DataTable mail_from_id_password = objmaster.check_frommail_id_password("StudioProposal");
                        bool status = objmail.sendmailforstudioDetails(user_id, user_type, user_dtl, mail_from_id_password, dt_send_mail_data);
                    }

                }


            }

            if (update_proposal)
            {
                string activity_description = "";
                string activity_action_name = "";
                string activity_type = "StudioProposal";
                string studio_code = data["studio_code"].ToString();
                string course_code = "";
                activity_description = "Submit Studio Proposal";
                activity_action_name = "Submit";


                string status_log = studio_log_create(user_id, activity_type, activity_description, activity_action_name, user_id, studio_code, course_code);

                return return_ajax_string("1", "Selection saved.");
            }
            else
            {
                return return_ajax_string("1", "Error while selection saving.");
            }
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }
    }

