    [WebMethod(EnableSession = true)]
    public string call_for_studio_status_track(string studio_code)
    {
        string user_id = HttpContext.Current.Session["UserId"].ToString();

        DataTable dt_call_for_studio_current_sem_data = objmaster.getCurrentSemYearCallForStudio();

        DataTable dt_feedback_logic = new DataTable();

        DataSet ds_feedback_logic = objmaster.call_for_studio_status_track(user_id, dt_call_for_studio_current_sem_data.Rows[0]["sem_code"].ToString(), dt_call_for_studio_current_sem_data.Rows[0]["year_code"].ToString(), studio_code);

        dt_feedback_logic.Columns.Add("key");
        dt_feedback_logic.Columns.Add("value");

        DataRow dr;
        dr = dt_feedback_logic.NewRow();
        dr["key"] = "Personal_Details";
        dr["value"] = ds_feedback_logic.Tables[0].Rows[0]["Personal_Details"].ToString();
        dt_feedback_logic.Rows.Add(dr);

        DataRow dr1;
        dr1 = dt_feedback_logic.NewRow();
        dr1["key"] = "Teaching_Interest";
        dr1["value"] = ds_feedback_logic.Tables[1].Rows[0]["Teaching_Interest"].ToString();
        dt_feedback_logic.Rows.Add(dr1);

        DataRow dr2;
        dr2 = dt_feedback_logic.NewRow();
        dr2["key"] = "Studio_Details";
        dr2["value"] = ds_feedback_logic.Tables[2].Rows[0]["Studio_Details"].ToString();
        dt_feedback_logic.Rows.Add(dr2);

        DataRow dr3;
        dr3 = dt_feedback_logic.NewRow();
        dr3["key"] = "Bank_Details";
        dr3["value"] = ds_feedback_logic.Tables[3].Rows[0]["Bank_Details"].ToString();
        dt_feedback_logic.Rows.Add(dr3);

        DataRow dr4;
        dr4 = dt_feedback_logic.NewRow();
        dr4["key"] = "Core_Faculty";
        dr4["value"] = ds_feedback_logic.Tables[4].Rows[0]["Core_Faculty"].ToString();
        dt_feedback_logic.Rows.Add(dr4);

        DataRow dr5;
        dr5 = dt_feedback_logic.NewRow();
        dr5["key"] = "Studio_Details_Filled ";
        dr5["value"] = ds_feedback_logic.Tables[5].Rows[0]["Studio_Details_Filled"].ToString();
        dt_feedback_logic.Rows.Add(dr5);

        DataRow dr6;
        dr6 = dt_feedback_logic.NewRow();
        dr6["key"] = "Submitted";
        dr6["value"] = ds_feedback_logic.Tables[6].Rows[0]["Submitted"].ToString();
        dt_feedback_logic.Rows.Add(dr6);

        if (dt_feedback_logic != null)
        {
            jsondata = GetJson1(dt_feedback_logic);
        }
        return jsondata;
    }

