    [WebMethod(EnableSession = true)]
    public string submit_call_for_studio(string studio_code)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string user_id;

        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "User ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            string user_type = HttpContext.Current.Session["UserId"].ToString();

            DataTable dt_call_for_studio_current_sem_data = objmaster.getCurrentSemYearCallForStudio();

            DSC_VF_Mgmt instructor_stud_details = new DSC_VF_Mgmt();

            DataTable dtStudioDetails = objMaster.GetInstructorStudioProposalDetails(user_id, studio_code);

            if (dtStudioDetails != null)
            {
                DataRow dr = dtStudioDetails.Rows[0];
                dr["is_submit"] = "Y";
                dr["last_modified_by"] = user_id;
                dr["last_modified_date"] = DateTime.Now;
                dr["last_modified_host"] = HttpContext.Current.Request.UserHostName;
                instructor_stud_details.instructor_studio_details.ImportRow(dr);
            }

            BLReturnObject Log_objBLReturnObject = new BLReturnObject();

            bool ppt_video_saved = objMaster.save_instructor_studio_details(instructor_stud_details, user_type, user_id, dt_call_for_studio_current_sem_data, studio_code);
            ServerLog.ExceptionLog("Step 1 Proposal Save Data : " + user_id);
            //if (objBLReturnObject.ExecutionStatus == 1)
            //{
            //    return return_ajax_string("1", "Data Saved Successfully");
            //}

            if (!ppt_video_saved)
            {
                return return_ajax_string("1", "Problem in update data " + objBLReturnObject.ServerMessage);
                //return false;
            }
            else
            {
                if (dtStudioDetails != null)
                {
                    ServerLog.ExceptionLog("Step 1 Proposal: " + user_id);
                    bool insert_data_applicant = objmaster.insert_studio_applicant_data(dtStudioDetails.Rows[0]["semester_type"].ToString(), dtStudioDetails.Rows[0]["year_semester"].ToString(), user_id, studio_code, user_id);
                    ServerLog.ExceptionLog("Step 1 Proposal End: " + user_id);
                }

            }

            return return_ajax_string("1", "Proposal Submitted Successfully");
            //return true;
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
            //return false;
        }
    }

