    [WebMethod(EnableSession = true)]
    public string Existing_interested_program_submit(string interested_program_data)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string user_id;
        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            string user_type = HttpContext.Current.Session["UserId"].ToString();

            DataTable dt_call_for_studio_current_sem_data = objmaster.getCurrentSemYearCallForStudio();

            ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_program_data);

            DSC_VF_Mgmt instructor_teaching_intrest = new DSC_VF_Mgmt();
            DSC_Vertical_Studio_Selection_dtl studio_wise_instructor_dtl = new DSC_Vertical_Studio_Selection_dtl();

            int re = 0;

            for (int i = 0; i < arr_interested_program_data.Count; i++)
            {
                Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];

                DSC_VF_Mgmt.instructor_teaching_interestRow teaching_int_row = instructor_teaching_intrest.instructor_teaching_interest.Newinstructor_teaching_interestRow();
                re = re + 1;
                teaching_int_row.doc_no = re.ToString();
                teaching_int_row.user_id = user_id;
                teaching_int_row.dept_code = data["dept_code"].ToString();
                teaching_int_row.prog_code = data["prog_code"].ToString();
                teaching_int_row.prog_level_code = data["prog_level_code"].ToString();
                teaching_int_row.studio_level = data["studio_level"].ToString();
                teaching_int_row.semester_type = data["sem"].ToString();
                teaching_int_row.year_semester = data["year"].ToString();
                teaching_int_row.cancel_flag = "N";
                teaching_int_row.created_by = user_id;
                teaching_int_row.created_date = DateTime.Now;
                teaching_int_row.created_host = HttpContext.Current.Request.UserHostName;
                teaching_int_row.studio_code = re.ToString();
                teaching_int_row.studio_title = data["studio_title"].ToString().Replace("&#39;", "'");
                teaching_int_row.no_of_tutor = data["no_of_tutor"].ToString();
                teaching_int_row.teaching_mode = data["teaching_mode"].ToString();
                teaching_int_row.studio_description = data["studio_description"].ToString();
                instructor_teaching_intrest.instructor_teaching_interest.Addinstructor_teaching_interestRow(teaching_int_row);
                //instructor_teaching_intrest.instructor_teaching_interest.ImportRow(teaching_int_row);

                DSC_VF_Mgmt.instructor_studio_detailsRow studio_details_row = instructor_teaching_intrest.instructor_studio_details.Newinstructor_studio_detailsRow();
                studio_details_row.user_id = user_id;
                studio_details_row.studio_code = re.ToString();
                //studio_details_row.ppt_video = "";
                //studio_details_row.course_code = "";
                studio_details_row.approved = "Y";  //09032021
                studio_details_row.is_submit = "Y"; //09032021
                studio_details_row.studio_brief_status = "N";
                studio_details_row.semester_type = data["sem"].ToString();
                studio_details_row.year_semester = data["year"].ToString();
                studio_details_row.cancel_flag = "N";
                studio_details_row.created_by = user_id;
                studio_details_row.created_date = DateTime.Now;
                studio_details_row.created_host = HttpContext.Current.Request.UserHostName;
                instructor_teaching_intrest.instructor_studio_details.Addinstructor_studio_detailsRow(studio_details_row);


            }

            BLReturnObject Log_objBLReturnObject = new BLReturnObject();
            //15022022
            objBLReturnObject = objMaster.save_instructor_teaching_intrest_data(instructor_teaching_intrest, studio_wise_instructor_dtl, user_type, user_id, dt_call_for_studio_current_sem_data);

            //if (objBLReturnObject.ExecutionStatus == 1)
            //{
            //    return return_ajax_string("1", "Data Saved Successfully");
            //}

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                return return_ajax_string("1", "Problem in update data " + objBLReturnObject.ServerMessage);
            }

            bool ppt_video_saved = objMaster.save_instructor_studio_details(instructor_teaching_intrest, user_type, user_id, dt_call_for_studio_current_sem_data, objBLReturnObject.ServerMessage);

            if (ppt_video_saved)
                return return_ajax_string("1", objBLReturnObject.ServerMessage);
            else
                return return_ajax_string("0", "Error while saving studio proposal.");
        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());
        }
    }


