    [WebMethod(EnableSession = true)]
    public string save_all_students_attendance_value(string student_att_Data, string status)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(student_att_Data);

            DataTable no_of_session_held = objmaster.get_number_of_session_held_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            DataTable student_course_attendance = objmaster.get_student_wise_att_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            //DSC_Student_attendance exam_master_add = new DSC_Student_attendance();

            DSC_GradingMaster att_master_add = new DSC_GradingMaster();


            for (int i = 0; i < data.Count; i++)
            {
                DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();



                attendance_master.user_id = data[i]["user_id"].ToString();
                attendance_master.course_code = data[i]["course_code"].ToString();

                if (data[i]["no_of_session_attended"] != null && data[i]["no_of_session_attended"] != "")
                {
                    attendance_master.no_of_session_attended = Convert.ToInt32(data[i]["no_of_session_attended"].ToString());
                    double percentage = Convert.ToDouble(data[i]["no_of_session_attended"].ToString()) * 100 / Convert.ToDouble(no_of_session_held.Rows[0]["no_of_session_held"].ToString());
                    attendance_master.attendance_percentage = Convert.ToDouble(Math.Round(percentage, 2, MidpointRounding.AwayFromZero).ToString());


                }
                if (status == "true")
                {
                    attendance_master.is_submit = "Y";
                }
                else
                {
                    attendance_master.is_submit = "N";
                }

                attendance_master.cancel_flag = "N";
                if (student_course_attendance == null)
                {
                    attendance_master.created_by = user_id;
                    attendance_master.created_date = DateTime.Now;
                    attendance_master.created_host = HttpContext.Current.Request.UserHostName;
                }

                attendance_master.semester_type = data[i]["semester_type"].ToString();
                attendance_master.year_semester = data[i]["year_semester"].ToString();

                if (student_course_attendance != null)
                {

                    attendance_master.created_by = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "'"))[0]["created_by"].ToString();
                    attendance_master.created_date = Convert.ToDateTime((student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "'"))[0]["created_date"].ToString());
                    attendance_master.created_host = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "'"))[0]["created_host"].ToString();
                    attendance_master.last_modified_by = user_id;
                    attendance_master.last_modified_date = DateTime.Now;
                    attendance_master.last_modified_host = HttpContext.Current.Request.UserHostName;
                }

                att_master_add.student_wise_course_attendence.Addstudent_wise_course_attendenceRow(attendance_master);
            }

            objBLReturnObject = objMaster.save_student_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
            {
                if (status == "true")
                {
                    dynamic value = objMaster.update_course_wise_session(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());
                }

            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string ExcelFileToDatatable_upload_student_wise_attendance(String ExcelFileName, HttpContext context)
    {
        string excel_data_save_res = "";

        Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
        DataSet ds = new DataSet();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        string course_code = context.Request.Form["course_code"].ToString();
        string sem_code = context.Request.Form["semester_type"].ToString();
        string year_code = context.Request.Form["year_code"].ToString();

        Dictionary<string, object> session_data = ser.Deserialize<Dictionary<string, object>>(context.Request.Form["session_data"].ToString());

        //HttpContext.Current.Session = new System.Web.SessionState.HttpSessionState();

        Dictionary<string, object> sessionData = new Dictionary<string, object>();
        foreach (string key in session_data.Keys)
        {
            Session[key] = session_data[key];
        }
        DSC_Upload_Fee_Collection fee_collection_upload = new DSC_Upload_Fee_Collection();
        String sConnectionString = String.Empty;

        dt_error.Columns.Add("Excel_RowNo");
        dt_error.Columns.Add("User_Id");
        dt_error.Columns.Add("Remark");

        string path = Server.MapPath("~/UploadFiles") + "\\" + ExcelFileName;

        OleDbConnection objConn = new OleDbConnection(sConnectionString);
        try
        {
            if (Path.GetExtension(ExcelFileName).ToLower() == ".xls")
                //sConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + path + "; Extended Properties=Excel 8.0;";
                sConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + path + "; Extended Properties=\"Excel 8.0;HDR=NO;IMEX=0;\"";
            else
                sConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + path + ";Extended Properties=\"Excel 12.0 Xml;HDR=YES\"";

            objConn.ConnectionString = sConnectionString;
            try
            {
                objConn.Open();
            }
            catch (Exception ex)
            {
            }

            DataTable tables = objConn.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, new object[] { null, null, null, "TABLE" });
            OleDbCommand cmd = new OleDbCommand();
            cmd.Connection = objConn;
            OleDbDataAdapter adp = new OleDbDataAdapter(cmd);

            if (tables != null && tables.Rows.Count > 0)
            {
                DataTable[] excelSheetTables = new DataTable[tables.Rows.Count];
                int CurrentTable = 0;
                foreach (DataRow dr in tables.Rows)
                {
                    if (!dr["TABLE_NAME"].ToString().Contains("xlnm#_FilterDatabase") && !dr["TABLE_NAME"].ToString().EndsWith("_"))
                    {
                        cmd.CommandText = "select * from [" + dr["TABLE_NAME"].ToString() + "]";
                        excelSheetTables[CurrentTable] = new DataTable(dr["TABLE_NAME"].ToString());
                        adp.Fill(excelSheetTables[CurrentTable]);
                        CurrentTable++;
                    }

                }
                foreach (DataTable singleTable in excelSheetTables)
                {
                    if (singleTable != null)
                    {
                        ds.Tables.Add(singleTable);
                    }
                }


                DataTable student_marks_data = objmaster.get_student_wise_att_dtl(course_code, sem_code, year_code);
                DataTable dt_Excel_student_data = objmaster.get_student_wise_att_dtl(course_code, sem_code, year_code);
                if (dt_Excel_student_data != null)
                {
                    dt_Excel_student_data.Clear();
                }
                DataTable dataTable = new DataTable();
                dataTable.Clear();
                dataTable.Columns.Add("user_id");
                dataTable.Columns.Add("course_code");
                dataTable.Columns.Add("no_of_session_attended");
                dataTable.Columns.Add("semester_type");
                dataTable.Columns.Add("year_semester");
                DataRow[] dataRow;




                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return jsondata;
                }

                user_mst = ds.Tables[0];

                if (user_mst.Columns[0].ColumnName.ToUpper() != "STUDENT_CODE")
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = "1";
                    dr_error["User_Id"] = "Column 1";
                    dr_error["Remark"] = "'" + user_mst.Columns[0].ColumnName + "' is not a valid column name";

                    dt_error.Rows.Add(dr_error);
                }

                if (user_mst.Columns[1].ColumnName.ToUpper() != "NO_OF_SESSION_ATTENDED")
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = "1";
                    dr_error["User_Id"] = "Column 2";
                    dr_error["Remark"] = "'" + user_mst.Columns[1].ColumnName + "' is not a valid column name";

                    dt_error.Rows.Add(dr_error);
                }



                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return jsondata;
                }




                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    isEmpty = true;
                    for (int j = 0; j < user_mst.Columns.Count; j++)
                    {

                        if (string.IsNullOrEmpty(user_mst.Rows[i][j].ToString()) == false)
                        {

                            isEmpty = false;
                            break;
                        }
                    }
                    if (isEmpty == true)
                    {
                        user_mst.Rows.RemoveAt(i);
                        i--;
                    }
                }

                if (user_mst.Rows.Count == 0)
                {
                    return "null";
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    if (student_marks_data != null)
                    {
                        DataRow[] dr = student_marks_data.Select("user_id='" + user_mst.Rows[i]["STUDENT_CODE"].ToString().Trim() + "' and semester_type = '" + sem_code.ToString().Trim() + "' and year_semester = '" + year_code.ToString().Trim() + "'");

                        if (dr.Length > 0)
                        {
                            //if (course_exam_data.Rows.Count > 0)
                            //{
                            if (user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"].ToString() != "")
                            {
                                int attendance;
                                if (int.TryParse(user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"].ToString(), out attendance))
                                {
                                    dr[0]["no_of_session_attended"] = user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"];
                                }
                                else
                                {
                                    dr_error = dt_error.NewRow();

                                    dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                                    dr_error["User_Id"] = user_mst.Rows[i]["STUDENT_CODE"];
                                    dr_error["Remark"] = "NO_OF_SESSION_ATTENDED Value is not in a correct Format";

                                    dt_error.Rows.Add(dr_error);
                                }
                            }
                            dt_Excel_student_data.Rows.Add(dr[0].ItemArray);
                        }
                        else
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            //dr_error["User_Id"] = user_mst.Rows[i]["user_id"].ToString();
                            dr_error["Remark"] = "Student Code '" + user_mst.Rows[i]["STUDENT_CODE"].ToString().Trim() + "' not Found";

                            dt_error.Rows.Add(dr_error);
                        }
                    }

                    else
                    {
                        DataRow dr_new_CourseMaster = dataTable.NewRow();
                        if (user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"].ToString() != "")
                        {
                            int attendance;
                            if (int.TryParse(user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"].ToString(), out attendance))
                            {
                                dr_new_CourseMaster["no_of_session_attended"] = user_mst.Rows[i]["NO_OF_SESSION_ATTENDED"];
                                dr_new_CourseMaster["user_id"] = user_mst.Rows[i]["STUDENT_CODE"];
                                dr_new_CourseMaster["course_code"] = course_code;
                                dr_new_CourseMaster["semester_type"] = sem_code;
                                dr_new_CourseMaster["year_semester"] = year_code;
                            }
                            else
                            {
                                dr_error = dt_error.NewRow();

                                dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                                dr_error["User_Id"] = user_mst.Rows[i]["STUDENT_CODE"];
                                dr_error["Remark"] = "NO_OF_SESSION_ATTENDED Value is not in a correct Format";

                                dt_error.Rows.Add(dr_error);
                            }
                        }
                        dataTable.Rows.Add(dr_new_CourseMaster);


                    }
                }
                if (dt_error.Rows.Count > 0)
                {

                    jsondata = GetJson1(dt_error);

                    return jsondata;
                }
                string excel_data_string;
                if (dataTable.Rows.Count > 0)
                {
                    excel_data_string = GetJson1(dataTable);
                }
                else
                {
                    excel_data_string = GetJson1(dt_Excel_student_data);
                }

                excel_data_save_res = save_all_students_attendance_value(excel_data_string, "false");

            }
        }
        catch (Exception ex)
        {
            return "Problem in save data";
        }
        return excel_data_save_res;

    }

