    public string get_session_date_wise_dtl(String course_code, String sem_code, String year_code)
    {
        DataTable dt = objmaster.get_session_date_wise_dtl(course_code, sem_code, year_code);
        if (dt != null)
        {
            DataTable dt_new = objmaster.get_student_allcate_course_dtl_data_with_name(sem_code, year_code, course_code);
            if (dt_new != null)
            {
                if (dt.Rows.Count != dt_new.Rows.Count)
                {
                    for (int i = 0; i < dt_new.Rows.Count; i++)
                    {
                        DataRow[] dr_add_exits = dt.Select("user_id = '" + dt_new.Rows[i]["user_id"].ToString() + "'");
                        if (dr_add_exits.Length == 0)
                        {
                            DataRow dr = dt.NewRow();
                            dr["session_is_submit"] = "N";
                            dr["user_id"] = dt_new.Rows[i]["user_id"];
                            dr["course_code"] = dt_new.Rows[i]["course_code"];
                            dr["full_name"] = dt_new.Rows[i]["full_name"];
                            dr["sca_user_id"] = dt_new.Rows[i]["user_id"];
                            dt.Rows.Add(dr);
                        }

                    }

                }
            }
            jsondata = GetJson1(dt);
        }
        return jsondata;
    }



