            DataTable student_course_attendance = objmaster.get_student_session_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            //DSC_Student_attendance exam_master_add = new DSC_Student_attendance();

            DSC_GradingMaster att_master_add = new DSC_GradingMaster();


            for (int i = 0; i < data.Count; i++)
            {
                //DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();
                DSC_GradingMaster.student_wise_session_attendenceRow attendance_master = att_master_add.student_wise_session_attendence.Newstudent_wise_session_attendenceRow();



                attendance_master.user_id = data[i]["user_id"].ToString();
                attendance_master.course_code = data[i]["course_code"].ToString();
                attendance_master.session_id = data[i]["session_id"].ToString();
                if (data[i]["session_attended"] != null)
                    attendance_master.session_attended = data[i]["session_attended"].ToString();
                else
                    attendance_master.session_attended = null;
                if (status == "true")
                {
                    attendance_master.is_submit = "Y";
                }
                else
                {
                    attendance_master.is_submit = "N";
                }

                attendance_master.cancel_flag = "N";
                if (student_course_attendance == null)
                {
                    attendance_master.created_by = user_id;
                    attendance_master.created_date = DateTime.Now;
                    attendance_master.created_host = HttpContext.Current.Request.UserHostName;
                }

                attendance_master.semester_type = data[i]["semester_type"].ToString();
                attendance_master.year_semester = data[i]["year_semester"].ToString();

                if (student_course_attendance != null)
                {

                    DataRow[] dts = student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'");
                    if (dts.Length == 0)
                    {
                        attendance_master.created_by = user_id;
                        attendance_master.created_date = DateTime.Now;
                        attendance_master.created_host = HttpContext.Current.Request.UserHostName;
                    }
                    else
                    {
                        attendance_master.created_by = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_by"].ToString();
                        attendance_master.created_date = Convert.ToDateTime((student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_date"].ToString());
                        attendance_master.created_host = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_host"].ToString();
                        attendance_master.last_modified_by = user_id;
                        attendance_master.last_modified_date = DateTime.Now;
                        attendance_master.last_modified_host = HttpContext.Current.Request.UserHostName;
                    }
                }

                //att_master_add.student_wise_course_attendence.Addstudent_wise_course_attendenceRow(attendance_master);
                att_master_add.student_wise_session_attendence.Addstudent_wise_session_attendenceRow(attendance_master);
            }

            objBLReturnObject = objMaster.save_student_session_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
            {
                if (status == "true")
                {
                    DataTable dt = objMaster.get_student_wise_absend_present_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();



                        attendance_master.user_id = dt.Rows[i]["user_id"].ToString();

                        attendance_master.course_code = data[0]["course_code"].ToString();

                        if (dt.Rows[i]["user_id"].ToString() != null && dt.Rows[i]["user_id"].ToString() != "")
                        {
                            attendance_master.no_of_session_attended = Convert.ToInt32(dt.Rows[i]["present"].ToString());
                            int total_session = Convert.ToInt32(dt.Rows[i]["present"].ToString()) + Convert.ToInt32(dt.Rows[i]["absent"].ToString());
                            double percentage = Convert.ToDouble(dt.Rows[i]["present"].ToString()) * 100 / Convert.ToDouble(total_session);
                            attendance_master.attendance_percentage = Convert.ToDouble(Math.Round(percentage, 2, MidpointRounding.AwayFromZero).ToString());


                        }
                        attendance_master.semester_type = data[0]["semester_type"].ToString();
                        attendance_master.year_semester = data[0]["year_semester"].ToString();
                        if (status == "true")
                        {
                            attendance_master.is_submit = "Y";
                        }
                        else { attendance_master.is_submit = "N"; }

                        attendance_master.cancel_flag = "N";
                        attendance_master.created_by = user_id;
                        attendance_master.created_date = DateTime.Now;
                        attendance_master.created_host = HttpContext.Current.Request.UserHostName;


                        att_master_add.student_wise_course_attendence.Addstudent_wise_course_attendenceRow(attendance_master);
                    }

                    objBLReturnObject = objMaster.save_student_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                    if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
                    {
                        if (status == "true")
                        {
                            dynamic value = objMaster.update_course_wise_session(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());
                            dynamic value_att = objMaster.update_student_exam_dtl_table(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString(), att_master_add.student_wise_course_attendence);
                        }

                    }
                }

            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }


