    [WebMethod(EnableSession = true)]
    public string Update_Publish_Letter_Body(string str_req_data, string sub_body)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            ArrayList Letter_Email_body = ser.Deserialize<ArrayList>(str_req_data);

            Dictionary<string, object> dic_req_data = (Dictionary<string, object>)Letter_Email_body[0];

            objmaster.Update_Publish_Letter_Body(ref dic_req_data, sub_body);

            if (dic_req_data["status"].ToString() == "True")
            {
                return return_ajax_string(dic_req_data["status"].ToString(), dic_req_data["message"].ToString());
            }
            else
            {
                return return_ajax_string("False", "Unable to Save.");
            }

        }
        catch (Exception ex)
        {
            return return_ajax_string("False", "Problem in Save Data. Please Try Again.");
        }

        return "";
    }


    [WebMethod(EnableSession = true)]
    public string insert_Publish_Letter_Body(string str_req_data, string str_body)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        try
        {
            str_body = str_body.Replace('"', '\'');

            ArrayList Letter_Email_body = ser.Deserialize<ArrayList>(str_req_data);

            Dictionary<string, object> dic_req_data = (Dictionary<string, object>)Letter_Email_body[0];

            objmaster.insert_Publish_Letter_Body(ref dic_req_data, str_body);

            if (dic_req_data["status"].ToString() == "True")
            {
                return return_ajax_string(dic_req_data["status"].ToString(), dic_req_data["message"].ToString());
            }
            else
            {
                return return_ajax_string("False", "Unable to Save.");
            }

        }
        catch (Exception ex)
        {
            //return return_ajax_string("False", ex.ToString());
            return return_ajax_string("False", "Problem in Save Data. Please Try Again.");
        }

        return "";
    }

