    [WebMethod(EnableSession = true)]
    public string save_bonafide_data(string bonafide_dtl)
    {

        JavaScriptSerializer ser = new JavaScriptSerializer();
        string User_id;
        Dictionary<string, string> bonafide_data = ser.Deserialize<Dictionary<string, string>>(bonafide_dtl);
        bonafide_data["user_id"] = HttpContext.Current.Session["UserId"].ToString();
        bonafide_data["host_name"] = HttpContext.Current.Request.UserHostName;
        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "user id not found");
            }
            else
            {
                User_id = HttpContext.Current.Session["UserId"].ToString();
            }
            string path = Server.MapPath("~/Student_ID_Card/" + bonafide_data["user_id"] + ".pdf");
            if (!File.Exists(path))
            {
                bonafide_data["message"] = "Student_id_card not found";
                return return_ajax_string("1", bonafide_data["message"]);
            }

            objmaster.save_bonafide_data(ref bonafide_data);
            return return_ajax_string("True", bonafide_data["message"]);

        }
        catch (Exception ex)
        {
            return return_ajax_string("False", bonafide_data["message"] + ex.ToString());
        }
    }

