    #region Fees Slip
    [WebMethod(EnableSession = true)]
    public string Get_fees_Slip_dtl(String semester, String year)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable Get_Slip_dtl = objmaster.Get_fees_Slip_dtl(user_id, semester, year);
        if (Get_Slip_dtl != null)
        {
            Get_Slip_dtl.Columns.Add("installment_status");
            for (int k = 0; k < Get_Slip_dtl.Rows.Count; k++)
            {
                DataTable get_user_wise_inst_dtl = objmaster.Get_all_fees_payment_installment_data_installment_wise_and_userwise(semester, year, Get_Slip_dtl.Rows[k]["installment_no"].ToString(), user_id);
                if (get_user_wise_inst_dtl != null)
                {
                    Get_Slip_dtl.Rows[k]["installment_status"] = "Y";
                }
                else
                {
                    Get_Slip_dtl.Rows[k].Delete();
                }
            }
            Get_Slip_dtl.AcceptChanges();
        }


        //if (Get_Slip_dtl != null)
        //{
        DataTable get_ofline_dtl = objmaster.Get_offline_fees_Slip_dtl(user_id, semester, year);
        if (get_ofline_dtl != null && Get_Slip_dtl != null)
        {


            string duplicate_inst = MakeInQueryString(get_ofline_dtl, "installment_no");
            DataRow[] dt = Get_Slip_dtl.Select("installment_no Not In(" + duplicate_inst + ")");
            if (dt.Length > 0)
            {
                Get_Slip_dtl = Get_Slip_dtl.Select("installment_no Not In(" + duplicate_inst + ")").CopyToDataTable();
                foreach (DataRow dr in get_ofline_dtl.Rows)
                {
                    Get_Slip_dtl.Rows.Add(dr.ItemArray);
                }
                DataView dv = Get_Slip_dtl.DefaultView;
                dv.Sort = "installment_no asc";
                DataTable new_dt = dv.ToTable();
                jsondata = GetJson1(new_dt);
            }
            else
            {
                jsondata = GetJson1(get_ofline_dtl);
            }

            return jsondata;
        }
        else if (get_ofline_dtl != null)
        {
            jsondata = GetJson1(get_ofline_dtl);
            return jsondata;
        }
        if (Get_Slip_dtl != null)
        { jsondata = GetJson1(Get_Slip_dtl); }

        //}
        return jsondata;
    }
