    [WebMethod(EnableSession = true)]
    public string Get_instrctor_disable_for_feedback(String sem_code, String year_code, String course_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        ArrayList sorting_array = new ArrayList();
        DataTable Get_feedback_dtl = objmaster.Get_instrctor_disable_for_feedback(sem_code, year_code, course_code);
        int count_data = 0;
        if (Get_feedback_dtl != null)
        {
            string inst_count = Get_feedback_dtl.Rows[0]["inst_count"].ToString();
            for (int i = 1; i <= 15; i++)
            {
                Get_feedback_dtl.Columns.Add("instr_" + i, typeof(string));
            }
            for (int k = 0; k < Get_feedback_dtl.Rows.Count; k++)
            {
                sorting_array.Clear();
                //string[] sorting_array;
                count_data = 0;
                if (Get_feedback_dtl.Rows[k]["Disable_instructor_code"].ToString() != "")
                {
                    string[] arr_dis = Get_feedback_dtl.Rows[k]["Disable_instructor_code"].ToString().Split(',');
                    if (arr_dis.Length > 0)
                    {
                        for (int w = 0; w < arr_dis.Length; w++)
                        {
                            count_data = 0;
                            count_data = w + 1;
                            sorting_array.Add(arr_dis[w].ToString() + "/D");
                            //sorting_array[w] = arr_dis[w].ToString() + "/D";
                            //Get_feedback_dtl.Rows[k]["instr_" + count_data] = arr_dis[w].ToString() + "/D";

                        }
                    }
                }
                if (Get_feedback_dtl.Rows[k]["Enable_instructor_code"].ToString() != "")
                {
                    string[] arr_enb = Get_feedback_dtl.Rows[k]["Enable_instructor_code"].ToString().Split(',');
                    if (arr_enb.Length > 0)
                    {
                        int new_count = count_data;
                        for (int q = 0; q < arr_enb.Length; q++)
                        {
                            new_count = 0;
                            new_count = q + count_data + 1;
                            sorting_array.Add(arr_enb[q].ToString() + "/E");
                            //Get_feedback_dtl.Rows[k]["instr_" + new_count] = arr_enb[q].ToString() + "/E";
                        }
                    }
                }
                if (sorting_array.Count > 0)
                {
                    sorting_array.Sort();
                    for (int f = 1; f <= sorting_array.Count; f++)
                    {
                        Get_feedback_dtl.Rows[k]["instr_" + f] = sorting_array[f - 1];
                    }
                }
                //for (int u = Convert.ToInt32(inst_count) + 1; u <= 15; u++)
                //{
                //    int o = u + 1;
                //    Get_feedback_dtl.Columns.Add("instr_" + u, typeof(string));
                //}


            }
            jsondata = GetJson1(Get_feedback_dtl);
        }

        return jsondata;
    }


