                        DS_Feedback_Save.temp_feedback_instructor_disableRow Feedback_disbale_data = feedback_disable_for_course_and_instructor.temp_feedback_instructor_disable.Newtemp_feedback_instructor_disableRow();
                        Feedback_disbale_data.course_code = course_code;
                        Feedback_disbale_data.user_id = data[i]["user_id"].ToString();
                        Feedback_disbale_data.instructor_code = dataRows[0]["user_id"].ToString(); //data[i]["inst_code"].ToString();
                        Feedback_disbale_data.semester_type = sem_code;
                        Feedback_disbale_data.year_semester = year_code;
                        Feedback_disbale_data.cancel_flag = data[i]["cancel_flag"].ToString();
                        Feedback_disbale_data.created_by = temp_dtl.Rows[0]["created_by"].ToString();
                        Feedback_disbale_data.created_date = Convert.ToDateTime(temp_dtl.Rows[0]["created_date"].ToString());
                        Feedback_disbale_data.created_host = temp_dtl.Rows[0]["created_host"].ToString();
                        Feedback_disbale_data.last_modified_by = user_id;
                        Feedback_disbale_data.last_modified_date = DateTime.Now;
                        Feedback_disbale_data.last_modified_host = HttpContext.Current.Request.UserHostName.ToString();

                        feedback_disable_for_course_and_instructor.temp_feedback_instructor_disable.Addtemp_feedback_instructor_disableRow(Feedback_disbale_data);
                    }
                }
            }
            objBLReturnObject = objMaster.save_feedback_disable_instructor_data(feedback_disable_for_course_and_instructor, "2000", user_id, HttpContext.Current.Request.UserHostName);

        }

        catch (Exception ex)
