    [WebMethod(EnableSession = true)]
    public string create_user_admin_side(string json_All_instructor_data)
    {
        string otp = "";
        bool otp_error = false;
        bool save_inst_mst = false;
        bool save_rights = false;
        var reg_user_id = HttpContext.Current.Session["UserId"].ToString();
        JavaScriptSerializer ser = new JavaScriptSerializer();
        try
        {

            ArrayList obj_user_data1 = ser.Deserialize<ArrayList>(json_All_instructor_data);
            Dictionary<string, object> obj_user_data = (Dictionary<string, object>)obj_user_data1[0];
            DataTable dtUserAccount = objmaster.check_alumini_user_Admin_Upload(obj_user_data["mail"].ToString().Trim());

            if (dtUserAccount != null)
            {
                return return_ajax_string("1", "User exists with this email ID. Log-in using this account.");
            }
            DataTable dt_next_doc_no = objmaster.GetNextDocNobyDocType("I");

            DataTable dtUserAccountId = objmaster.check_user_by_user_id(dt_next_doc_no.Rows[0]["next_doc_no"].ToString());

            if (dtUserAccountId != null)
            {
                int next_doc_no = Convert.ToInt32(dt_next_doc_no.Rows[0]["next_doc_no_original"].ToString()) + 1;

                bool update_no = objmaster.UpdateNextDocNo(next_doc_no, "I");

                dt_next_doc_no = objmaster.GetNextDocNobyDocType("I");
            }

            string password = encoding_decoding.encryptPassword("admin1");


            bool save_user_mst = objmaster.create_user_new_account(obj_user_data, dt_next_doc_no.Rows[0]["next_doc_no"].ToString(), password, reg_user_id);

            if (obj_user_data["save_sub_status"].ToString() == "A")
            {
                if (obj_user_data["user_type"].ToString() == "I2")
                {
                    save_inst_mst = objmaster.create_new_ins_mst(obj_user_data, dt_next_doc_no.Rows[0]["next_doc_no"].ToString(), reg_user_id);
                    save_rights = objmaster.give_rights_to_admin_side_new_user(obj_user_data, dt_next_doc_no.Rows[0]["next_doc_no"].ToString(), reg_user_id);
                }
                else
                {
                    save_inst_mst = true;
                    save_rights = objmaster.give_rights_to_admin_side_new_user(obj_user_data, dt_next_doc_no.Rows[0]["next_doc_no"].ToString(), reg_user_id);
                }

            }
            else
            {
                save_inst_mst = true;
                save_rights = true;

            }

            if (save_user_mst && save_inst_mst && save_rights)
            {
                if (obj_user_data["save_sub_status"].ToString() == "A")
                {
                    //return return_ajax_string("0", "Submit successfully. Sign-in on Connect.");
                    return "Submit successfully. Sign-in on Connect.";
                }
                else
                {
                    return "Data Save successfully";
                    //return return_ajax_string("0", "Save successfully");
                }

            }
            else
            {
                //delete query
                if (obj_user_data["save_sub_status"].ToString() == "A")
                {
                    bool delete_account = objmaster.DeleteUserAccount(dt_next_doc_no.Rows[0]["next_doc_no"].ToString());
                }
                return "Problem In Data";
                //return return_ajax_string("1", "Error while Registering. Please try again later.");
            }


        }
        catch (Exception ex)
        {
            return return_ajax_string("1", ex.ToString());

        }
    }



