    [WebMethod(EnableSession = true)]
    public string get_timer_details()
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string milisecond = "900000";
        try
        {
            DataTable dt_check_registed_data = objmaster.check_student_allocate_current_sem_data(HttpContext.Current.Session["UserId"].ToString(), current_ws_sem, current_ws_year);

            if (dt_check_registed_data == null)
            {
                DataTable dt = objmaster.get_timer_details(user_id, current_ws_sem, current_ws_year);

                if (dt != null)
                {

                    bool update_delete_status = false;
                    string current_Date = DateTime.Now.ToString("yyyy/MM/dd");
                    string current_time = DateTime.Now.ToString("HH:mm");
                    DateTime reg_time = Convert.ToDateTime(dt.Rows[0]["registration_time"].ToString());
                    string reg_date = reg_time.ToString("yyyy/MM/dd");
                    string reg_min = reg_time.ToString("HH:mm");
                    TimeSpan duration = DateTime.Parse(current_time).Subtract(DateTime.Parse(reg_min));
                    double totalMinutes = duration.TotalMinutes;
                    double totalhours = ((int)duration.TotalHours);
                    if (current_Date == reg_date)
                    {
                        if (totalhours >= Convert.ToDouble("0") && totalMinutes >= Convert.ToDouble("15"))
                        {
                            bool status = objmaster.timeover_update_table(user_id, HttpContext.Current.Request.UserHostName, current_ws_sem, current_ws_year);
                            update_delete_status = status;
                        }
                        else
                        {   //< Convert.ToInt32("15")
                            if (totalMinutes >= 0)
                            {
                                int remening_mint = Convert.ToInt32("15") - Convert.ToInt32(totalMinutes);
                                return jsondata = Convert.ToString(remening_mint);
                            }
                            else { return jsondata = "15"; }

                        }
                    }
                    else
                    {
                        bool status = objmaster.timeover_update_table(user_id, HttpContext.Current.Request.UserHostName, current_ws_sem, current_ws_year);
                        update_delete_status = status;
                    }

                    if (update_delete_status == true)
                    {

                        bool status_data = objMaster.insert_course_timer_value(user_id, HttpContext.Current.Request.UserHostName, current_ws_sem, current_ws_year, milisecond);
                        if (status_data == true)
                        {
                            DataTable ret_dt = objmaster.get_timer_details(user_id, current_ws_sem, current_ws_year);
                            if (ret_dt != null)
                            {
                                return jsondata = GetJson1(ret_dt);
                            }
                        }
                    }
                    jsondata = GetJson1(dt);
                }
                else
                {
                    bool status_data = objMaster.insert_course_timer_value(user_id, HttpContext.Current.Request.UserHostName, current_ws_sem, current_ws_year, milisecond);
                    if (status_data == true)
                    {
                        DataTable ret_dt = objmaster.get_timer_details(user_id, current_ws_sem, current_ws_year);
                        if (ret_dt != null)
                        {
                            jsondata = GetJson1(ret_dt);
                        }
                    }
                }
                return jsondata;
            }
            else
            {
                return "";
            }
        }
        catch (Exception ex)
        {
            return jsondata;
        }
        return jsondata;
    }

