    [WebMethod(EnableSession = true)]
    public string Get_Certificate_dtl(string year_code, string dept_code, string prog_code, string sem_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        DataTable Get_data = objmaster.Get_Certificate_dtl(year_code, dept_code, prog_code, sem_code);

        if (Get_data != null)
        {
            DataTable Get_data_date = objmaster.Get_Certificate_dtl_datewise(year_code, dept_code, prog_code);
            if (Get_data_date != null)
            {
                for (int i = 0; i < Get_data.Rows.Count; i++)
                {
                    DataRow[] dr = Get_data_date.Select("user_id = '" + Get_data.Rows[i]["user_id"].ToString() + "'");
                    if (dr.Length > 0)
                    {
                        if (dr[0]["create_date"].ToString() != "")
                        {
                            Get_data.Rows[i]["created_date"] = dr[0]["create_date"].ToString();
                        }
                        if (dr[0]["last_modified_date"].ToString() != "")
                        { Get_data.Rows[i]["last_modified_date"] = dr[0]["last_modified_date"].ToString(); }


                    }
                }
            }


            jsondata = GetJson1(Get_data);
        }
        return jsondata;
    }


