    [WebMethod(EnableSession = true)]
    public dynamic update_studio_detail(String semester, String year, String detalis, String remark, String interested_remark_data)
    {

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        JavaScriptSerializer ser = new JavaScriptSerializer();
        ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_remark_data);
        string rateband = "";
        for (int i = 0; i < arr_interested_program_data.Count; i++)
        {
            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];
            remark = data["reject_remark"].ToString().Replace("&#39;", "'");
            rateband = data["rateband"].ToString();
        }

        //remark = encoding_decoding.encryptPassword(remark.ToString().Trim());

        dynamic status = objmaster.update_studio_details(semester, year, user_id, detalis, remark, rateband);

        if (Convert.ToString(status) == "true")
        {
            string[] details_value = detalis.Split('_');
            string activity_description = "";
            string activity_action_name = "";
            string activity_type = "Studio";
            if (details_value[0].ToString() == "M")
            {
                activity_description = "Proposal Remark";
                activity_action_name = "Remark";
            }
            else if (details_value[0].ToString() == "R")
            {
                activity_description = "Proposal Reject";
                activity_action_name = "Reject";
            }
            else
            {
                activity_description = "Proposal Authorize";
                activity_action_name = "Authorize";
            }

            string status_log = studio_log_create(details_value[0].ToString(), activity_type, activity_description, activity_action_name, user_id, details_value[1].ToString(), "");

        }
        return status;
    }


