    [WebMethod(EnableSession = true)]
    public string Deallocate_drp_request(String manually_data, String sem_code, String year_code, string drp_code, string flag_status)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string student_id = "";
        List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(manually_data);
        // DataTable user_details = objmaster.get_all_user_mst_data();
        try
        {
            for (int i = 0; i < data.Count; i++)
            {
                if (i == 0)
                {
                    student_id = "'" + data[i]["user_id"].ToString() + "'";
                }
                else
                {
                    student_id += "," + "'" + data[i]["user_id"].ToString() + "'";
                }
            }
            Boolean status = objmaster.Deallocate_drp_dtl(user_id, sem_code, year_code, student_id, drp_code, flag_status);
            if (status == true)
            {
                return "Save Data";
            }
        }

        catch (Exception ex)
        {
            return "Problem in Update data";
        }

        return "Save Data";

    }

