    #region delete and SWS Pending Initial
    [WebMethod(EnableSession = true)]
    public string get_ws_pending_initial_course_list(string sem_code, string year_code, string dept_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        bool authorize = false;
        DataTable dt_dean_dtl = objmaster.get_semyearwise_dean_user_dtl(user_id, user_type, sem_code, year_code);
        DataTable dt_fa_dtl = objmaster.get_semyearwise_fa_user_dtl(user_id, user_type, sem_code, year_code);

        if (user_type == "A")
        {
            authorize = true;
        }
        if (user_type == "FA")
        {
            if (dt_fa_dtl != null)
            {
                authorize = true;
            }

        }

        if (authorize)
        {
            DataTable dt_ws_course_proposal_data = objmaster.Get_ws_pending_initial_data(sem_code, year_code);
            DataTable dt_ws_course_proposal_instructor_data = objmaster.get_all_ws_course_proposal_instructor_data(sem_code, year_code);

            DataTable WS_Course_Wise_TA_Details = objmaster.WS_Course_Wise_TA_Details(sem_code, year_code);
            //DataTable dt_ws_course_proposal_workplan_data = objmaster.get_all_ws_course_proposal_workplan_data(sem_code, year_code);
            if (dt_ws_course_proposal_data != null)
            {
                string str_course = "";
                DataRow[] dr_ws_course_proposal_data = null;

                dt_ws_course_proposal_data.Columns.Add("instructors");
                dt_ws_course_proposal_data.Columns.Add("TA_instructors");


                for (int i = 0; i < dt_ws_course_proposal_data.Rows.Count; i++)
                {


                    DataRow[] dr_ws_course_proposal_instructor_data = dt_ws_course_proposal_instructor_data.Select("course_code='" + dt_ws_course_proposal_data.Rows[i]["course_code"].ToString() + "'");
                    DataRow[] dr_ws_course_TA_instructor_data;
                    if (WS_Course_Wise_TA_Details != null)
                    {
                        //string course_code_new = dt_ws_course_proposal_data.Rows[i]["ws_course_code"].ToString() != "" ? dt_ws_course_proposal_data.Rows[i]["ws_course_code"].ToString() : dt_ws_course_proposal_data.Rows[i]["course_code"].ToString();

                        string course_code_new = dt_ws_course_proposal_data.Rows[i]["course_code"].ToString();
                        dr_ws_course_TA_instructor_data = WS_Course_Wise_TA_Details.Select("course_code='" + course_code_new + "'");
                        if (dr_ws_course_TA_instructor_data.Length > 0)
                        {
                            dt_ws_course_proposal_data.Rows[i]["TA_instructors"] = dr_ws_course_TA_instructor_data[0]["TA_instructor_name"].ToString();
                        }

                    }


                    if (dr_ws_course_proposal_instructor_data.Length > 0)
                    {
                        string str_instructors = "";
                        str_instructors = dr_ws_course_proposal_instructor_data[0]["instructor_name"].ToString();

                        for (int j = 1; j < dr_ws_course_proposal_instructor_data.Length; j++)
                        {
                            str_instructors += ", " + dr_ws_course_proposal_instructor_data[j]["instructor_name"].ToString();
                        }

                        dt_ws_course_proposal_data.Rows[i]["instructors"] = str_instructors;
                    }
                }

                if (user_type == "FA")
                {
                    string inhabitation = "(";

                    inhabitation += "'" + dt_fa_dtl.Rows[0]["dept_code"].ToString().Trim() + "'";
                    for (int i = 1; i < dt_fa_dtl.Rows.Count; i++)
                        inhabitation += ",'" + dt_fa_dtl.Rows[i]["dept_code"].ToString().Trim() + "'";

                    inhabitation += ")";

                    DataRow[] dr = dt_ws_course_proposal_data.Select("instructor_approved in('N') and (dean_approved not in ('A') or dean_approved is null) and inhabitation in " + inhabitation);
                    if (dr.Length > 0)
                    {
                        dt_ws_course_proposal_data = dt_ws_course_proposal_data.Select("instructor_approved in('N') and (dean_approved not in ('A') or dean_approved is null) and inhabitation in " + inhabitation).CopyToDataTable();
                    }
                    else
                    {
                        dt_ws_course_proposal_data = null;
                    }

                }

                if (dt_ws_course_proposal_data != null)
                {
                    jsondata = GetJson1(dt_ws_course_proposal_data);
                }

                //}
            }
        }

        return jsondata;
    }
