    [WebMethod(EnableSession = true)]
    public string save_authorize_detail_v2(String manually_data, String sem_code, String year_code)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();
        string course_code = string.Empty;
        string inst_code = string.Empty;
        string course_inst_code = string.Empty;
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string hr_approved_flag = "";
        string uso_hr_approved_flag = "";
        DataRow[] studio_course_dtl;
        DataRow[] edit_workload_dtl;

        List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(manually_data);
        try
        {
            DataTable get_studio_course_dtl = objmaster.Get_studio_course_dtl(sem_code, year_code);
            DataTable get_edit_workload_dtl = objmaster.Get_workload_edit_dtl(sem_code, year_code);

            if (user_type == "D" || user_type == "PC")
            {
                for (int i = 0; i < data.Count; i++)
                {
                    // check Studio Mapping 
                    if (get_studio_course_dtl != null)
                    {
                        studio_course_dtl = get_studio_course_dtl.Select("course_code ='" + data[i]["course_code"].ToString() + "' and instructor_code = '" + data[i]["inst_code"].ToString() + "' ");
                        // Exits Course and Inst
                        if (studio_course_dtl.Length > 0)
                        {
                            edit_workload_dtl = get_edit_workload_dtl.Select("course_code ='" + data[i]["course_code"].ToString() + "' and instructor_code = '" + data[i]["inst_code"].ToString() + "' ");
                            if (edit_workload_dtl.Length > 0)
                            {
                                if (hr_approved_flag == "")
                                {
                                    hr_approved_flag = "('" + data[i]["course_code"].ToString() + "','" + data[i]["inst_code"].ToString() + "')";
                                }
                                else { hr_approved_flag += "," + "('" + data[i]["course_code"].ToString() + "','" + data[i]["inst_code"].ToString() + "')"; }
                            }
                            else
