    [WebMethod(EnableSession = true)]
    public string get_pending_at_cac_course(string sem_code, string year_code, string prog_code, string prog_level_code, string dept_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        var user_prog_code = HttpContext.Current.Session["prog_code"].ToString();

        int flag = 0;
        DataTable course_data = new DataTable();

        course_data = objmaster.get_pending_at_cac_course(user_id, user_type, user_prog_code, sem_code, year_code, prog_code, prog_level_code, dept_code);


        DataTable pending_approval_list = new DataTable();

        if (course_data != null)
        {
            try
            {
                if (user_type == "PC" || user_type == "FA")
                {
                    flag = 1;
                }
            }
            catch (Exception e)
            {
                return e.Message.ToString();
            }

            if (user_type == "PC" || user_type == "FA")
            {
                flag = 1;
            }
            if (user_id == "tlc")
            {
                flag = 1;
            }
            if (flag == 1)
            {
                DataTable instructor_data = objmaster.Get_course_instructor_data_for_modification(sem_code, year_code, "");
                DataTable instructor_AA_data = objmaster.Get_course_instructor_AA_data_for_modification(sem_code, year_code, "");
                DataTable instructor_TA_data = objmaster.Get_course_instructor_TA_data_for_modification(sem_code, year_code, "");
                DataTable area_data = objmaster.Get_course_area_data_for_modification(sem_code, year_code, "");
                DataTable time_data = objmaster.Get_course_time_day_data_for_modification(sem_code, year_code, "");
                DataTable type_data = objmaster.Get_typology_data();
                DataTable dept_data = objmaster.Get_department_data();
                DataTable prog_data = objmaster.Get_programme_data();
                DataTable prog_level_data = objmaster.Get_programme_level_mst_data();
                DataTable typegroup = objmaster.Get_typology_group_data();

                pending_approval_list.Columns.Add("course_code");
                pending_approval_list.Columns.Add("type");
                pending_approval_list.Columns.Add("course_type");
                pending_approval_list.Columns.Add("title");
                pending_approval_list.Columns.Add("credit");
                pending_approval_list.Columns.Add("occurence_week");
                pending_approval_list.Columns.Add("course_outline");
                pending_approval_list.Columns.Add("instructor");
                pending_approval_list.Columns.Add("instructor_AA");
                pending_approval_list.Columns.Add("instructor_TA");
                pending_approval_list.Columns.Add("course_desc");
                pending_approval_list.Columns.Add("prerequisite");
                pending_approval_list.Columns.Add("faculty");
                pending_approval_list.Columns.Add("program");
                pending_approval_list.Columns.Add("program_level_code");
                pending_approval_list.Columns.Add("semester");
                pending_approval_list.Columns.Add("day");
                pending_approval_list.Columns.Add("time");
                pending_approval_list.Columns.Add("area");
                pending_approval_list.Columns.Add("intake");
                pending_approval_list.Columns.Add("remark");
                pending_approval_list.Columns.Add("faculty_approval");
                pending_approval_list.Columns.Add("progcoord_approval");
                pending_approval_list.Columns.Add("ugpg_approval");
                pending_approval_list.Columns.Add("typegroup");
                pending_approval_list.Columns.Add("roomid");
                pending_approval_list.Columns.Add("backlog");
                pending_approval_list.Columns.Add("p_flag");
                pending_approval_list.Columns.Add("gpa_ngpa");//Retured By Ananth//
                pending_approval_list.Columns.Add("studio_level");// mode kapil 30112020
                pending_approval_list.Columns.Add("studio_mode");// mode kapil 30112020
                pending_approval_list.Columns.Add("Focuse");// mode kapil 30112020

                for (int i = 0; i < course_data.Rows.Count; i++)
                {
                    DataRow dr = pending_approval_list.NewRow();
                    dr["p_flag"] = course_data.Rows[i]["pflag"];
                    dr["course_code"] = course_data.Rows[i]["course_code"];
                    dr["gpa_ngpa"] = course_data.Rows[i]["gpa_ngpa"]; //Retured By Ananth//
                    dr["studio_mode"] = course_data.Rows[i]["studio_mode"];    // mode kapil 30112020
                    dr["backlog"] = course_data.Rows[i]["backlog"];    // mode kapil 30112020
                    dr["studio_level"] = course_data.Rows[i]["sub_category_id"];    // mode kapil 30112020
                    dr["Focuse"] = course_data.Rows[i]["Focuse"];

                    DataRow[] type = type_data.Select("type_code = '" + course_data.Rows[i]["course_typology"] + "'");

                    if (type.Length > 0)
                    {
                        DataRow[] drtypegroup = typegroup.Select("group_id = '" + type[0]["group_id"] + "'");
                        if (drtypegroup.Length > 0)
                        {
                            dr["typegroup"] = drtypegroup[0]["group_desc"];
                        }
                        else
                        {
                            dr["typegroup"] = "";
                        }
                    }
                    else
                    {
                        dr["typegroup"] = "";
                    }

                    if (type.Length > 0)
                    {
                        dr["type"] = type[0]["type_name"];
                    }
                    else
                    {
                        dr["type"] = "";
                    }

                    dr["course_type"] = course_data.Rows[i]["course_type"];
                    dr["title"] = course_data.Rows[i]["course_name"];
                    dr["credit"] = course_data.Rows[i]["course_credits"];
                    dr["occurence_week"] = course_data.Rows[i]["occurrence_week"];
                    dr["course_outline"] = course_data.Rows[i]["course_outline"];

                    if (instructor_data != null)
                    {
                        DataRow[] instructors = instructor_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        string instructor = "";
                        for (int j = 0; j < instructors.Length; j++)
                        {
                            instructor = instructor + instructors[j]["instructor_name"] + ", ";
                        }
                        if (instructor == "")
                        {
                            dr["instructor"] = instructor;
                        }
                        else
                        {
                            dr["instructor"] = instructor.Remove(instructor.Length - 2, 2);
                        }
                    }
                    else
                    {
                        dr["instructor"] = "";
                    }

                    if (instructor_AA_data != null)
                    {
                        DataRow[] instructors_AA = instructor_AA_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        string instructor_AA = "";
                        for (int j = 0; j < instructors_AA.Length; j++)
                        {
                            instructor_AA = instructor_AA + instructors_AA[j]["instructor_name"] + ", ";
                        }
                        if (instructor_AA == "")
                        {
                            dr["instructor_AA"] = instructor_AA;
                        }
                        else
                        {
                            dr["instructor_AA"] = instructor_AA.Remove(instructor_AA.Length - 2, 2);
                        }
                    }
                    else
                    {
                        dr["instructor_AA"] = "";
                    }

                    if (instructor_TA_data != null)
                    {
                        DataRow[] instructors_TA = instructor_TA_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        string instructor_TA = "";
                        for (int j = 0; j < instructors_TA.Length; j++)
                        {
                            instructor_TA = instructor_TA + instructors_TA[j]["instructor_name"] + ", ";
                        }
                        if (instructor_TA == "")
                        {
                            dr["instructor_TA"] = instructor_TA;
                        }
                        else
                        {
                            dr["instructor_TA"] = instructor_TA.Remove(instructor_TA.Length - 2, 2);
                        }
                    }
                    else
                    {
                        dr["instructor_TA"] = "";
                    }

                    dr["course_desc"] = course_data.Rows[i]["course_desc"];
                    dr["prerequisite"] = course_data.Rows[i]["prerequisite"];

                    DataRow[] dept = dept_data.Select("dept_code = '" + course_data.Rows[i]["dept_code"] + "'");
                    if (dept.Length > 0)
                    {
                        dr["faculty"] = dept[0]["dept_name"];
                    }
                    else
                    {
                        dr["faculty"] = "";
                    }

                    DataRow[] prog = prog_data.Select("prog_code = '" + course_data.Rows[i]["prog_code"] + "'");
                    if (prog.Length > 0)
                    {
                        dr["program"] = prog[0]["prog_name"];
                    }
                    else
                    {
                        dr["program"] = "";
                    }

                    DataRow[] prog_level = prog_level_data.Select("prog_level_code = '" + course_data.Rows[i]["prog_level_code"] + "'");
                    if (prog_level.Length > 0)
                    {
                        dr["program_level_code"] = prog_level[0]["prog_level_desc"];
                    }
                    else
                    {
                        dr["program_level_code"] = "";
                    }

                    dr["semester"] = course_data.Rows[i]["semester_code"];

                    if (time_data != null)
                    {
                        DataRow[] daytimes = time_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        string day = "";
                        string time = "";
                        string roomgroup = "";
                        for (int j = 0; j < daytimes.Length; j++)
                        {
                            string room_id = "";
                            if (daytimes[j]["room_id"].ToString() != "")
                            {
                                if (course_data.Rows[i]["faculty_approval"].ToString() == "Approved" || course_data.Rows[i]["progcoord_approval"].ToString() == "Approved" || course_data.Rows[i]["ugpg_approval"].ToString() == "Approved")
                                {
                                    room_id = daytimes[j]["room_id"].ToString();
                                }
                            }
                            if (room_id != "")
                                roomgroup = roomgroup + room_id + ",";
                            day = day + daytimes[j]["day_name"] + ", ";
                            time = time + daytimes[j]["from_time"] + "-" + daytimes[j]["To_time"] + ", ";
                        }


                        if (roomgroup == "")
                        {
                            dr["roomid"] = roomgroup;
                        }
                        else
                        {
                            dr["roomid"] = roomgroup.Remove(roomgroup.Length - 1, 1);
                        }
                        if (day == "")
                        {
                            dr["day"] = day;
                        }
                        else
                        {
                            dr["day"] = day.Remove(day.Length - 2, 2);
                        }
                        if (time == "")
                        {
                            dr["time"] = time;
                        }
                        else
                        {
                            dr["time"] = time.Remove(time.Length - 2, 2);
                        }
                    }

                    string area = "";
                    if (area_data != null)
                    {
                        DataRow[] areas = area_data.Select("course_code = '" + course_data.Rows[i]["course_code"].ToString() + "'");
                        for (int j = 0; j < areas.Length; j++)
                        {
                            area = area + areas[j]["area_name"] + ", ";
                        }
                    }

                    if (area == "")
                    {
                        dr["area"] = area;
                    }
                    else
                    {
                        dr["area"] = area.Remove(area.Length - 2, 2);
                    }

                    dr["intake"] = course_data.Rows[i]["available_seat"];
                    dr["backlog"] = course_data.Rows[i]["backlog"];
                    dr["remark"] = course_data.Rows[i]["remark"];
                    //if (course_data.Rows[i]["faculty_approved"].ToString() == "P" && course_data.Rows[i]["faculty_approval"].ToString() == "Pending" && course_data.Rows[i]["studio_brief_status"].ToString() == "Y")
                    //{ dr["faculty_approval"] = "Pending_Y"; }
                    //else
                    //{
                    //    dr["faculty_approval"] = course_data.Rows[i]["faculty_approval"];
                    //}
                    dr["faculty_approval"] = course_data.Rows[i]["faculty_approval"];
                    dr["progcoord_approval"] = course_data.Rows[i]["progcoord_approval"];
                    dr["ugpg_approval"] = course_data.Rows[i]["ugpg_approval"];

                    pending_approval_list.Rows.Add(dr);
                }
            }
        }

        if (pending_approval_list != null && pending_approval_list.Rows.Count > 0)
        {
            jsondata = GetJson1(pending_approval_list);
        }

        return jsondata;
    }


