    public string get_rateband_dtl_course_wise(string course_code, string sem_code, string year_code, string cancel_flag)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        DataTable dt_doc = new DataTable();
        DataTable dt_course_wise_instructor = objmaster.Get_CourseWiseInstructor_data_v2(course_code, sem_code, year_code, cancel_flag);

        DataTable instructor_workload_data = objmaster.get_vf_course_wise_workload_detail_v2(course_code, sem_code, year_code, cancel_flag);

        DataTable dt_inst_workload_data = objmaster.Get_CourseWiseWorkload_details(course_code, sem_code, year_code);

        if (instructor_workload_data != null)
        {
            instructor_workload_data.Columns.Add("percent_load");

            for (int i = 0; i < instructor_workload_data.Rows.Count; i++)
            {
                //DataRow[] dr = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "'");
                DataRow[] dr = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "' and is_tutorial='" + instructor_workload_data.Rows[i]["is_tutorial"].ToString() + "'");

                if (dr.Length > 0)
                {
                    instructor_workload_data.Rows[i]["percent_load"] = dr[0]["percent_load"];
                }

                DataRow[] dr1 = dt_course_wise_instructor.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "'");

                if (dr1.Length > 0)
                {
                    if (dr1[0]["rate_band_designation"].ToString() != "VFT")
                    {
                        instructor_workload_data.Rows[i]["designation"] = dr1[0]["rate_band_designation"];
                    }
                }
                if (dt_inst_workload_data != null)
                {
                    DataRow[] dr_inst_code = dt_inst_workload_data.Select("instructor_code='" + instructor_workload_data.Rows[i]["instructor_code"].ToString() + "'");
                    if (dr_inst_code.Length > 0)
                    {//total_exp,rate_band
                        instructor_workload_data.Rows[i]["total_experiance"] = dr_inst_code[0]["total_exp"];
                        instructor_workload_data.Rows[i]["rate_band"] = dr_inst_code[0]["rate_band"];
                    }
                }


            }
        }

        if (instructor_workload_data != null)
        {
            jsondata = GetJson1(instructor_workload_data);
        }
        return jsondata;
    }


