    [WebMethod(EnableSession = true)]
    public string course_wise_TA_save(string course_TA_data, string sem_code, string year_code, string course_code, string inst_type)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();

        int re = 0;
        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(course_TA_data);

            DSC_Course_Master course_master_upload = new DSC_Course_Master();

            bool status = objMaster.course_wise_TA_save(data[0]["instructor_code"].ToString().Trim(), sem_code, year_code, course_code, user_id, HttpContext.Current.Request.UserHostName.ToString(), inst_type);
            if (status)
            {
                if (inst_type == "TA")
                {
                    string rate_band_bind = insert_rateband_user_wise(course_code, sem_code, year_code, "N", data[0]["instructor_code"].ToString().Trim(), "");
                }

                return "Data Saved Successfully";
            }

        }
        catch (Exception ex)
