                        instructor_workload_row.total_contact_hrs = dt_workload.Rows[0]["avg_contact_hrs_per_week"].ToString();
                        instructor_workload_row.total_hrs = dt_workload.Rows[0]["avg_contact_hrs_per_week"].ToString();
