                        instructor_workload_row.total_hrs = "";
                        instructor_workload_row.total_hrs_in_semester = "";
                        strmsg = "[{\"weeks\":\"" + weeks_ + "\",\"contact_hrs\":\"" + contact_hrs_ + "\"}]";
