    [WebMethod(EnableSession = true)]
    public string PrintOutlinePdf(string student, string Sem, string Year)
    {
        ServerLog.ExceptionLog("PrintOutlinePdf");
        string sem = Sem;
        string year = Year;
        string student_code = student;

        GradeReportDetail grd = new GradeReportDetail();

        List<Dictionary<string, string>> lst_dic_tran_sem_year = new List<Dictionary<string, string>>();
        DataTable Courses = new DataTable();
        DataTable dt_stud_detail = grd.get_Student_Detail(student_code, sem, year);

        Courses.Columns.Add("course_code");
        Courses.Columns.Add("semester_type");
        Courses.Columns.Add("year_semester");
        Courses.Columns.Add("Course_Type");

        lst_dic_tran_sem_year.Add(new Dictionary<string, string>());
        lst_dic_tran_sem_year[0]["sem_code"] = sem;
        lst_dic_tran_sem_year[0]["year_code"] = year;

        for (int i = 0; i < 15; i++)
        {
            lst_dic_tran_sem_year.Add(new Dictionary<string, string>());

            if (lst_dic_tran_sem_year[i]["sem_code"] == "M")
            {
                lst_dic_tran_sem_year[i + 1]["sem_code"] = "S";
                lst_dic_tran_sem_year[i + 1]["year_code"] = (Convert.ToInt32(lst_dic_tran_sem_year[i]["year_code"]) + 1).ToString();
            }
            else if (lst_dic_tran_sem_year[i]["sem_code"] == "S")
            {
                lst_dic_tran_sem_year[i + 1]["sem_code"] = "M";
                lst_dic_tran_sem_year[i + 1]["year_code"] = lst_dic_tran_sem_year[i]["year_code"];
            }
        }

        for (int i = 0; i < lst_dic_tran_sem_year.Count; i++)
        {
            DataTable dt_course_detail = grd.get_Course_Detail(student_code, lst_dic_tran_sem_year[i]["sem_code"], lst_dic_tran_sem_year[i]["year_code"]);
            DataTable dt_grade_range = grd.get_Grade_Range(student_code, lst_dic_tran_sem_year[i]["sem_code"], lst_dic_tran_sem_year[i]["year_code"]);
            DataTable dt_ws_course_detail = grd.get_WS_Course_Detail(student_code, lst_dic_tran_sem_year[i]["sem_code"], lst_dic_tran_sem_year[i]["year_code"]);
            DataTable dt_ws_grade_range = grd.get_WS_Grade_Range(student_code, lst_dic_tran_sem_year[i]["sem_code"], lst_dic_tran_sem_year[i]["year_code"]);

            DataTable dt_course_grade_detail = grd.Calculate_grade(dt_stud_detail, dt_course_detail, dt_grade_range);
            DataTable dt_ws_course_grade_detail = grd.WS_Calculate_grade(dt_stud_detail, dt_ws_course_detail, dt_ws_grade_range);

            if (dt_course_grade_detail != null)
            {
                if (dt_course_grade_detail.Select("course_code IN ('CFP001','CFP002','CFP003','CFP004','CFP005','CFP006','CFP007','CFP008','CFP009','CFP010')").Length > 0)
                {
                    for (int j = 0; j < dt_course_grade_detail.Rows.Count; j++)
                    {
                        Courses.Rows.Add();
                        Courses.Rows[Courses.Rows.Count - 1]["course_code"] = dt_course_grade_detail.Rows[j]["course_code"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["semester_type"] = dt_course_grade_detail.Rows[j]["semester_type"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["year_semester"] = dt_course_grade_detail.Rows[j]["year_semester"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["Course_Type"] = "SM";
                    }
                }
                else if (dt_course_grade_detail.Select("remarks='PASS'").Length > 0)
                {
                    dt_course_grade_detail = dt_course_grade_detail.Select("remarks='PASS'").CopyToDataTable();
                    for (int j = 0; j < dt_course_grade_detail.Rows.Count; j++)
                    {
                        Courses.Rows.Add();
                        Courses.Rows[Courses.Rows.Count - 1]["course_code"] = dt_course_grade_detail.Rows[j]["course_code"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["semester_type"] = dt_course_grade_detail.Rows[j]["semester_type"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["year_semester"] = dt_course_grade_detail.Rows[j]["year_semester"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["Course_Type"] = "SM";
                    }
                }
            }

            if (dt_ws_course_detail != null)
            {
                if (dt_ws_course_detail.Select("remarks='PASS'").Length > 0)
                {
                    dt_ws_course_detail = dt_ws_course_detail.Select("remarks='PASS'").CopyToDataTable();
                    for (int j = 0; j < dt_ws_course_detail.Rows.Count; j++)
                    {
                        Courses.Rows.Add();
                        Courses.Rows[Courses.Rows.Count - 1]["course_code"] = dt_ws_course_detail.Rows[j]["course_code"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["semester_type"] = dt_ws_course_detail.Rows[j]["semester_type"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["year_semester"] = dt_ws_course_detail.Rows[j]["year_semester"].ToString();
                        Courses.Rows[Courses.Rows.Count - 1]["Course_Type"] = "SW";
                    }
                }
            }
        }

        if (Courses.Rows.Count > 0)
        {
            DataTable Data = grd.CourseData(Courses);
            var HTMLString = "";
            for (var i = 0; i < Data.Rows.Count; i++)
            {
                HTMLString +=
                    @"" + (i == (Data.Rows.Count - 1) ? "<div>" : "<div style='page-break-after: always;'>") +
                        @"<div class='panel-heading col-md-12' style='margin-top: 10px;'>
                            <div id='head_Data' style='text-align: center; font-weight: bold; font-style: initial;'>
                                " + Data.Rows[i]["Semester"] + ", " + Data.Rows[i]["year_semester"] + ", " + Data.Rows[i]["DepartmentName"] + ", " + @"CEPT University
                            </div>
                        </div>
                        <div class='panel-body'>
                            <div class='row' style='margin-top: 10px;'>
                                <div class='form-group color-blue'>
                                <br/>
                                </div>
                                <div class='form-group'>
                                    <table width='100%' style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>
                                        <tr style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'><b>Code</b></td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>" + Data.Rows[i]["course_code"] + @"</td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'><b>Course</b></td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;' colspan=3>" + Data.Rows[i]["course_name"] + @"</td>
                                        </tr>
                                        <tr style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'><b>Typology</b></td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>" + Data.Rows[i]["Typology"] + @"</td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'><b>Credits</b></td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>" + Data.Rows[i]["course_credits"] + @"</td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'><b>GPA/NonGPA</b></td>
                                            <td style='border: 1px solid black; border-collapse: collapse; padding: 8px;'>" + (Data.Rows[i]["gpa_ngpa"].ToString() == "G" ? "GPA" : "NonGPA") + @"</td>
                                        </tr>
