                if (Data.Rows[i]["course_outline"].ToString() != "")
                {
                    HTMLString += @"<div class='row' style='margin-top: 10px;'>
                                <div class='form-group color-blue'>
                                    <b style='color: #b4b4b4;'>Long Description :</b>
