                    dynamic LearningOutcome = JsonConvert.DeserializeObject<object>(Data.Rows[i]["eval_method5"].ToString() != "" ? Data.Rows[i]["eval_method5"].ToString() : "{'course_outcome1':'','course_outcome2':'','course_outcome3':'','course_outcome4':'','course_outcome5':''}");
                    //dynamic WorkPlan = JsonConvert.DeserializeObject<object>(Data.Rows[i]["methodology"].ToString() != "" ? Data.Rows[i]["methodology"].ToString() : "{'week1':'','week2':'','week3':'','week4':'','week5':'','week6':'','week7':'','week8':'','week9':'','week10':'','week11':'','week12':'','week13':'','week14':'','week15':'','week16':''}");
                    dynamic WorkPlan = Data.Rows[i]["methodology"].ToString().Split(new string[] { "SplitStringFromHere" }, StringSplitOptions.None);
                    ServerLog.ExceptionLog("Test WorkPlan" + Data.Rows[i]["course_code"]);
                    if (LearningOutcome.course_outcome1 != "")
