                    string[] LearningOutcome = Data.Rows[i]["eval_method5"].ToString().Split('•');
                    string[] WorkPlan = Data.Rows[i]["methodology"].ToString().Split('~');

                    if (LearningOutcome.Length > 0 && LearningOutcome[0] != "")
