    public string accept_ta_req(string doc_no, string studio_code, string semester_type, string year_semester, string instructor_code, string prog_code, string prog_level_code, string type)
    {
        string course_code = "";
        string user_id = HttpContext.Current.Session["UserId"].ToString();
        if (studio_code == "undefined")
        {
            return "false";
        }
        DataTable dtRatebandStatus = objmaster.GetRateBandData(semester_type, year_semester, instructor_code);
        //if (dtRatebandStatus == null)
        //{
        //    return "HR Not Approved RateBand";
        //
        //}
        bool status = objmaster.accept_ta_req_inst(doc_no, user_id, studio_code, semester_type, year_semester, instructor_code, prog_code, prog_level_code, type);

        if (status)
        {
            if (type == "23")
            {
                DataTable get_course_code = objMaster.Get_studio_code_course_wise(studio_code, semester_type, year_semester);
                course_code = get_course_code.Rows[0]["new_course_code"].ToString();
            }
            else { course_code = studio_code; }

            DataTable dt_course_flag = objMaster.Get_course_data_for_modification(semester_type, year_semester, course_code);
            bool status_ta = objMaster.course_wise_TA_save(instructor_code, semester_type, year_semester, course_code, user_id, HttpContext.Current.Request.UserHostName.ToString(), "TA");

            if (status_ta)
            {
                string rate_band_bind = insert_rateband_user_wise(course_code, semester_type, year_semester, dt_course_flag.Rows[0]["cancel_flag"].ToString(), instructor_code, "TA");
            }
            return "true";
        }

        return "false";
    }


