    [WebMethod(EnableSession = true)]
    public string Get_SWS_publish_Course_dtl_with_file_name(string semester_type, string year_semester, string dept_code)
    {
        var UserType = HttpContext.Current.Session["user_type"].ToString();
        DataTable data = objmaster.Get_SWS_publish_Course_dtl(semester_type, year_semester, dept_code);

        if (data != null)
        {
            string path = HttpContext.Current.Server.MapPath("~/SWS_StudentBonafideLetter");
            bool FileExits = File.Exists(path);
            if (!FileExits)
            {
                Directory.CreateDirectory(path);
            }
            if (semester_type == "S")
            {
                semester_type = "Summer";
            }
            else { semester_type = "Winter"; }
            for (int i = 0; i < data.Rows.Count; i++)
            {

                string filename = data.Rows[i]["course_code"].ToString().Trim() + "_" + semester_type + "_" + year_semester + ".pdf";
                if (File.Exists(path + "\\" + filename))
                {
                    data.Rows[i]["visa_file_name"] = "true";
                }

            }
            jsondata = GetJson1(data);
        }
        return jsondata;
    }


