                           && dr[0]["student_nationality"].ToString().Trim().ToLower() != "indiaan" && dr[0]["student_nationality"].ToString().Trim().ToLower() != "indian" && dr[0]["student_nationality"].ToString().Trim().ToLower() != "")
                        {
