                    html_str = html_str.Replace("@@coursedescription", get_student_course_dtl.Rows[0]["course_desc"].ToString());
                    html_str = html_str.Replace("@@totalfaculty", get_student_course_dtl.Rows[0]["total_instructors_involved"].ToString());
                    html_str = html_str.Replace("@@course_name", get_student_course_dtl.Rows[0]["course_name"].ToString());
