                    html_str = html_str.Replace("@@student_code", dr[0]["user_id"].ToString().Trim());
                    html_str = html_str.Replace("@@student_prog_name", dr[0]["student_prog_code"].ToString().Trim());
                    html_str = html_str.Replace("@@student_dept_name", dr[0]["student_dept_name"].ToString().Trim());
                    html_str = html_str.Replace("@@passport_no", dr[0]["student_passport_no"].ToString().Trim());

                    html_str = html_str.Replace("@@travel_start_date", dr[0]["TravelStartDate"].ToString());
                    html_str = html_str.Replace("@@travel_end_date", dr[0]["TravelEndDate"].ToString());

