                    {
                        html_str = html_str.Replace("@@title", "Mr.");
                        html_str = html_str.Replace("@@studentnamewithpassportnumber", "MR. " + get_student_course_dtl.Rows[0]["full_name"].ToString() + "(Passport No. : )");
                    }
                    else if (dr.Length > 0 && dr[0]["gender"].ToString().Trim().ToLower() == "f")
                    {
                        html_str = html_str.Replace("@@title", "Ms.");
                        html_str = html_str.Replace("@@studentnamewithpassportnumber", "MS. " + get_student_course_dtl.Rows[0]["full_name"].ToString() + "(Passport No. : )");
                    }
                    else
