                    else month = DateTime.Now.Month.ToString();
                    string lbl_date = DateTime.Now.Day.ToString() + "/" + month + "/" + DateTime.Now.Year.ToString();
                    html_str = html_str.Replace("@@lbl_date", lbl_date.ToString());
                    string str_div_html = "<table class='table table-bordered clsCourseTable' id='payment_table' style='flex: 0 0 auto;width: 100%; font-size:17px; '>" +
                                            "<tr>" +
