    [WebMethod(EnableSession = true)]
    public string ws_publish_letter_genrate(String sem_code, String year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        DataTable get_course_detl = objmaster.ws_publish_letter_genrate_course_dtl(sem_code, year_code, user_type, user_id);

        string semester = "";
        if (sem_code == "S")
        {
            semester = "Summer";
        }
        else
        {
            semester = "Winter";
        }

        if (get_course_detl != null)
        {
            String path = Server.MapPath("~/WSLetterPDF");
            get_course_detl.Columns.Add("pdf_status").ToString();
            for (int k = 0; k < get_course_detl.Rows.Count; k++)
            {
                String File_Name = get_course_detl.Rows[k]["instructor_code"].ToString() + "_" + get_course_detl.Rows[k]["instructor_name"].ToString().Replace(" ", "_") + "_" + semester + "_" + year_code + ".pdf";
                File_Name = File_Name.Replace(" ", "");
                if (File.Exists(path + "\\" + File_Name))
                {
                    get_course_detl.Rows[k]["pdf_status"] = "Y";
                }
                else
                {
                    get_course_detl.Rows[k]["pdf_status"] = "N";
                }
            }


            jsondata = GetJson1(get_course_detl);
        }

        if (get_course_detl != null)
        {
            jsondata = GetJson1(get_course_detl);
        }
        return jsondata;
    }


