    [WebMethod(EnableSession = true)]
    public string Get_Course_Wise_instructor_dtl(string semester_type, string year_semester, string course_code)
    {
        DataTable data = objmaster.Get_Course_Wise_instructor_dtl(semester_type, year_semester, course_code);

        if (data != null)
        {
            string path = HttpContext.Current.Server.MapPath("~/FacultyVisa");
            bool FileExits = File.Exists(path);
            if (!FileExits)
            {
                Directory.CreateDirectory(path);
            }
            if (semester_type == "S")
            {
                semester_type = "Summer";
            }
            else { semester_type = "Winter"; }
            for (int i = 0; i < data.Rows.Count; i++)
            {

                string filename = data.Rows[i]["instructor_code"].ToString().Trim() + "_" + data.Rows[i]["course_code"].ToString().Trim() + "_" + semester_type + "_" + year_semester + ".pdf";
                if (File.Exists(path + "\\" + filename))
                {
                    data.Rows[i]["visa_file_name"] = "true";
                }

            }
            jsondata = GetJson1(data);
        }
        return jsondata;
    }

