    [WebMethod(EnableSession = true)]
    public string sws_send_Appointment_mail_to_visiting_faculty(string instructor_list)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        String Instructor_type_email = "";
        String tea_email = "";

        try
        {

            JavaScriptSerializer ser = new JavaScriptSerializer();

            Dictionary<string, object>[] dic_instructor_list = ser.Deserialize<Dictionary<string, object>[]>(instructor_list);

            //Instructor_type_email = dic_instructor_list[0]["hdn_user_type"].ToString();
            //tea_email = dic_instructor_list[0]["hdn_tea_letter"].ToString();

            //string userType_for_Email = objmaster.get_user_type_for_letter_TA_AA(dic_instructor_list[0]["sem_code"].ToString(), dic_instructor_list[0]["year_code"].ToString(), dic_instructor_list[0]["instructor_code"].ToString());
            string directory_path = HttpContext.Current.Server.MapPath("~/WSLetterPDF");
            if (dic_instructor_list.Length > 0)
            {
                DataTable dt = objmaster.ws_Get_course_data_for_modification(dic_instructor_list[0]["sem_code"].ToString(), dic_instructor_list[0]["year_code"].ToString(), dic_instructor_list[0]["course_code"].ToString());
                DataTable dt_instructor_mst_data = objmaster.Get_All_instructor_mst_data();

                DataTable AckDetails = objmaster.Get_VF_TA_AA_Letter_Email_Body("SWS_Publish_Letter", "email");

                if (AckDetails != null)
                {
                    string res = objmail.SWS_Send_Appointment_Mail_to_visiting_faculty(dic_instructor_list, AckDetails, dt, directory_path);
                    return res;

                }
            }
            else
            {
                return "No Instructor found to Send Mail.";
            }


        }
        catch (Exception ex)
        {
            return "Problem in Send Mails.";
        }
        return "";
    }

