    [WebMethod(EnableSession = true)]
    public string WS_get_authorize_detail_vf_acceptance_new(string sem_code, string year_code, string prog_code, string prog_level_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        var user_typee = user_type;
        var instructor_type = "";

        if (instructor_type == "") instructor_type = "-";

        DataTable vising_faculty_data = objmaster.WS_get_authorize_detail_vf_acceptance(sem_code, year_code, user_id, user_typee, prog_code, prog_level_code);

        try
        {
            if (vising_faculty_data != null)
            {


                vising_faculty_data.Columns.Add("total_amount_paid");

                for (int i = 0; i < vising_faculty_data.Rows.Count; i++)
                {
                    if (vising_faculty_data.Rows[i]["rate_band"].ToString() != "" && vising_faculty_data.Rows[i]["total_contact_hrs"].ToString() != "")
                    {
                        vising_faculty_data.Rows[i]["total_amount_paid"] = (Convert.ToDouble(vising_faculty_data.Rows[i]["rate_band"].ToString()) * Convert.ToDouble(vising_faculty_data.Rows[i]["total_contact_hrs"].ToString())).ToString();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            vising_faculty_data = null;
        }

        if (vising_faculty_data != null)
        {
            jsondata = GetJson1(vising_faculty_data);
        }
        return jsondata;
    }

    [WebMethod(EnableSession = true)]
    public string WS_save_acceptance_detail(string sem_code, string year_code, string All_table_course_data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        int re = 0;
        try
        {
            if (user_type == "FA")
            {
                JavaScriptSerializer ser = new JavaScriptSerializer();

                ArrayList All_Instructor_data = ser.Deserialize<ArrayList>(All_table_course_data);

                ArrayList instructor_data = (ArrayList)All_Instructor_data[0];
                bool status = objmaster.WS_Acceptance_Details_Update(instructor_data, user_id, HttpContext.Current.Request.UserHostName, sem_code, year_code);
                if (status)
                {
                    return "Data Saved Successfully";

                }
                return "Problem in update data";
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA." + ex.ToString();
        }

        return "Data Saved Successfully";
        //return "";

    }


