    [WebMethod(EnableSession = true)]
    public string ws_ExcelFileToDatatable_upload_session_wise_attendance(String ExcelFileName, HttpContext context)
    {
        string excel_data_save_res = "";

        Regex regex = new Regex(@"^([\w\.\-]+)@([\w\-]+)((\.(\w){2,3})+)$");
        DataSet ds = new DataSet();

        JavaScriptSerializer ser = new JavaScriptSerializer();

        string course_code = context.Request.Form["course_code"].ToString();
        string sem_code = context.Request.Form["semester_type"].ToString();
        string year_code = context.Request.Form["year_code"].ToString();
        DataTable dt = new DataTable();
        Dictionary<string, object> session_data = ser.Deserialize<Dictionary<string, object>>(context.Request.Form["session_data"].ToString());
        ServerLog.ExceptionLog("session_wise_attendance Start ");
        //HttpContext.Current.Session = new System.Web.SessionState.HttpSessionState();

        Dictionary<string, object> sessionData = new Dictionary<string, object>();
        foreach (string key in session_data.Keys)
        {
            Session[key] = session_data[key];
        }
        // DSC_Upload_Fee_Collection fee_collection_upload = new DSC_Upload_Fee_Collection();
        String sConnectionString = String.Empty;

        dt_error.Columns.Add("Excel_RowNo");
        dt_error.Columns.Add("Session_Name");
        dt_error.Columns.Add("Remark");

        string path = Server.MapPath("~/UploadFiles") + "\\" + ExcelFileName;

        //using (ExcelPackage xlPackage = new ExcelPackage(new FileInfo(path)//@"C:\YourDirectory\sample.xlsx"))
        //{
        //    var myWorksheet = xlPackage.Workbook.Worksheets.First(); //select sheet here
        //    var totalRows = myWorksheet.Dimension.End.Row;
        //    var totalColumns = myWorksheet.Dimension.End.Column;

        //    var sb = new StringBuilder(); //this is your data
        //    for (int rowNum = 1; rowNum <= totalRows; rowNum++) //select starting row here
        //    {
        //        var row = myWorksheet.Cells[rowNum, 1, rowNum, totalColumns].Select(c => c.Value == null ? string.Empty : c.Value.ToString());
        //        sb.AppendLine(string.Join(",", row));
        //    }
        //}

        //FileStream fStream = File.Open(path, FileMode.Open, FileAccess.Read);
        //ExcelDataReader excelDataReader = ExcelReaderFactory.CreateOpenXmlReader(fStream);
        //DataSet resultDataSet = excelDataReader.AsDataSet();
        //excelDataReader.Close();

        using (XLWorkbook workBook = new XLWorkbook(path))
        {
            //Read the first Sheet from Excel file.
            IXLWorksheet workSheet = workBook.Worksheet(1);
            //Create a new DataTable.
            //Loop through the Worksheet rows.
            bool firstRow = true;
            foreach (IXLRow row in workSheet.Rows())
            {
                //Use the first row to add columns to DataTable.
                if (firstRow)
                {
                    foreach (IXLCell cell in row.Cells())
                    {
                        dt.Columns.Add(cell.Value.ToString());
                    }
                    firstRow = false;
                }
                else
                {
                    //Add rows to DataTable.
                    dt.Rows.Add();
                    int i = 0;
                    foreach (IXLCell cell in row.Cells(1, dt.Columns.Count))
                    {
                        if (cell.DataType.ToString() == "DateTime")
                        {
                            dt.Rows[dt.Rows.Count - 1][i] = ((System.DateTime)cell.Value).Day + "/" + ((System.DateTime)cell.Value).Month + "/" + ((System.DateTime)cell.Value).Year;
                            i++;
                        }
                        else
                        {
                            dt.Rows[dt.Rows.Count - 1][i] = cell.Value.ToString();
                            i++;
                        }
                    }
                }
            }
        }
        try
        {
            ServerLog.ExceptionLog("OleDbDataAdapter Connection ");
            if (dt != null && dt.Rows.Count > 0)
            {
                ServerLog.ExceptionLog("Command Excute ");
                DataTable dataTable = new DataTable();
                dataTable.Clear();

                dataTable.Columns.Add("course_code");
                dataTable.Columns.Add("session_name");
                dataTable.Columns.Add("session_date");
                dataTable.Columns.Add("semester_type");
                dataTable.Columns.Add("year_semester");
                DataRow[] dataRow;
                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return jsondata;
                }

                user_mst = dt; //ds.Tables[0];

                if (user_mst.Columns[0].ColumnName.ToUpper() != "SESSION_NAME")
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = "1";
                    dr_error["Session_Name"] = "Column 1";
                    dr_error["Remark"] = "'" + user_mst.Columns[0].ColumnName + "' is not a valid column name";

                    dt_error.Rows.Add(dr_error);
                }

                if (user_mst.Columns[1].ColumnName.ToUpper() != "SESSION_DATE")
                {
                    dr_error = dt_error.NewRow();

                    dr_error["Excel_RowNo"] = "1";
                    dr_error["Session_Name"] = "Column 2";
                    dr_error["Remark"] = "'" + user_mst.Columns[1].ColumnName + "' is not a valid column name";

                    dt_error.Rows.Add(dr_error);
                }



                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    ServerLog.ExceptionLog("ERRor Json " + jsondata);
                    return jsondata;
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    isEmpty = true;
                    for (int j = 0; j < user_mst.Columns.Count; j++)
                    {

                        if (string.IsNullOrEmpty(user_mst.Rows[i][j].ToString()) == false)
                        {

                            isEmpty = false;
                            break;
                        }
                    }
                    if (isEmpty == true)
                    {
                        user_mst.Rows.RemoveAt(i);
                        i--;
                    }
                }

                if (user_mst.Rows.Count == 0)
                {
                    return "null";
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    DataRow dr_new_CourseMaster = dataTable.NewRow();
                    if (user_mst.Rows[i]["SESSION_NAME"].ToString() != "")
                    {
                        int attendance;
                        if (user_mst.Rows[i]["SESSION_NAME"].ToString() != "")
                        {
                            dr_new_CourseMaster["session_name"] = user_mst.Rows[i]["SESSION_NAME"];
                            dr_new_CourseMaster["session_date"] = user_mst.Rows[i]["SESSION_DATE"].ToString();
                            dr_new_CourseMaster["course_code"] = course_code;
                            dr_new_CourseMaster["semester_type"] = sem_code;
                            dr_new_CourseMaster["year_semester"] = year_code;
                        }
                        else
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            dr_error["Session_Name"] = user_mst.Rows[i]["SESSION_NAME"];
                            dr_error["Remark"] = "SESSION_NAME Value is not in a correct Format";

                            dt_error.Rows.Add(dr_error);
                        }
                    }
                    dataTable.Rows.Add(dr_new_CourseMaster);

                }
                if (dt_error.Rows.Count > 0)
                {

                    jsondata = GetJson1(dt_error);

                    return jsondata;
                }
                string excel_data_string;
                if (dataTable.Rows.Count > 0)
                {
                    excel_data_string = GetJson1(dataTable);
                }
                else
                {
                    excel_data_string = "";
                }

                excel_data_save_res = ws_save_all_course_wise_session_value(excel_data_string, "false");

            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("session_wise_attendance End " + ex.Message);
            return "Problem in save data";
        }
        return excel_data_save_res;

    }


    public string ws_save_all_course_wise_session_value(string student_att_Data, string status)
    {
        ServerLog.ExceptionLog("student_session Save DataV2");
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(student_att_Data);

            //DataTable no_of_session_held = objmaster.get_number_of_session_held_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            //DataTable course_wise_session_dtl = objmaster.get_course_wise_session_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            //DSC_Student_attendance exam_master_add = new DSC_Student_attendance();

            DSC_GradingMaster att_master_add = new DSC_GradingMaster();


            for (int i = 0; i < data.Count; i++)
            {
                //DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();
                DSC_GradingMaster.ws_student_wise_course_attendenceRow attendance_master = att_master_add.ws_student_wise_course_attendence.Newws_student_wise_course_attendenceRow();

                //DSC_GradingMaster.course_wise_session_dtl
                //DSC_GradingMaster.course_wise_session_dtlRow course_Wise_Session = att_master_add.course_wise_session_dtl.Newcourse_wise_session_dtlRow();
                DSC_GradingMaster.ws_course_wise_session_dtlRow course_Wise_Session = att_master_add.ws_course_wise_session_dtl.Newws_course_wise_session_dtlRow();
                course_Wise_Session.course_code = data[i]["course_code"].ToString();
                course_Wise_Session.session_id = Convert.ToString(i);
                string[] arr;
                string str = data[i]["session_date"].ToString();

                if (str.Contains('/'))
                    arr = data[i]["session_date"].ToString().Split('/');
                else if (str.Contains('-'))
                    arr = data[i]["session_date"].ToString().Split('-');
                else
                    return "Session Date Format must be DD/MM/YYYY";

                string month_date = arr[1];
                string day_date = arr[0];

                if (Convert.ToInt32(arr[0]) <= 9 && arr[0].Length != 2)
                {
                    day_date = "0" + arr[0];
                }

                if (Convert.ToInt32(arr[1]) <= 9 && arr[1].Length != 2)
                {
                    month_date = "0" + arr[1];
                }

                if (Convert.ToInt32(month_date) > 12)
                {
                    return "Session Date Format must be DD/MM/YYYY";
                }

                string new_date = arr[2].Substring(0, 4) + "-" + month_date + "-" + day_date;

                ServerLog.ExceptionLog("student_session V2 New Date" + new_date);
                DateTime dt = DateTime.ParseExact(new_date, "yyyy-MM-dd", null);
                ServerLog.ExceptionLog("student_session V2 New Date" + dt);
                course_Wise_Session.session_date = dt;
                course_Wise_Session.is_cancelled = "N";
                course_Wise_Session.session_name = data[i]["session_name"].ToString();

                course_Wise_Session.cancel_flag = "N";

                course_Wise_Session.created_by = user_id;
                course_Wise_Session.created_date = DateTime.Now;
                course_Wise_Session.created_host = HttpContext.Current.Request.UserHostName;

                course_Wise_Session.semester_type = data[i]["semester_type"].ToString();
                course_Wise_Session.year_semester = data[i]["year_semester"].ToString();
                //att_master_add.course_wise_session_dtl.Addcourse_wise_session_dtlRow(course_Wise_Session);
                att_master_add.ws_course_wise_session_dtl.Addws_course_wise_session_dtlRow(course_Wise_Session);

            }

            //objBLReturnObject = objMaster.save_student_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);
            objBLReturnObject = objMaster.ws_save_course_wise_session_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                ServerLog.ExceptionLog("student_session V2" + objBLReturnObject.ServerMessage);
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
            {
                status = "true";
                if (status == "true")
                {
                    dynamic value = objMaster.ws_update_course_wise_session_mst(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString(), user_id);
                }

            }

        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("student_session V2" + ex.Message);
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }


