        {
            //Read the first Sheet from Excel file.
            IXLWorksheet workSheet = workBook.Worksheet(1);
            //Create a new DataTable.
            //Loop through the Worksheet rows.
            bool firstRow = true;
            foreach (IXLRow row in workSheet.Rows())
            {
                //Use the first row to add columns to DataTable.
                if (firstRow)
                {
                    foreach (IXLCell cell in row.Cells())
                    {
                        dt.Columns.Add(cell.Value.ToString());
                    }
                    firstRow = false;
                }
                else
                {
                    //Add rows to DataTable.
                    dt.Rows.Add();
                    int i = 0;
                    foreach (IXLCell cell in row.Cells(1, dt.Columns.Count))
                    {
                        dt.Rows[dt.Rows.Count - 1][i] = cell.Value.ToString();
                        i++;
                    }
                }


            }
        }

        try
        {
            if (dt != null && dt.Rows.Count > 0)
            {
                ServerLog.ExceptionLog("Table Connection");
                DataTable session_mst = objmaster.ws_get_course_wise_session_dtl(course_code, sem_code, year_code);
                DataTable new_data = objmaster.ws_get_session_date_wise_dtl(course_code, sem_code, year_code);
                DataTable student_marks_data = objmaster.ws_get_student_wise_att_dtl(course_code, sem_code, year_code);
                DataTable dt_Excel_student_data = objmaster.ws_get_student_wise_att_dtl(course_code, sem_code, year_code);

                if (dt_Excel_student_data != null)
                {
                    dt_Excel_student_data.Clear();
                }
                DataTable dataTable = new DataTable();
                dataTable.Clear();
                dataTable.Columns.Add("user_id");
                dataTable.Columns.Add("course_code");
                dataTable.Columns.Add("session_id");
                dataTable.Columns.Add("session_attended");
                dataTable.Columns.Add("semester_type");
                dataTable.Columns.Add("year_semester");
                DataRow[] dataRow;
                ServerLog.ExceptionLog("Add Column");
                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    return jsondata;
                }

                user_mst = dt;//ds.Tables[0];

                if (user_mst.Columns[0].ColumnName != "Student_code")
                {
                    dr_error = dt_error.NewRow();
                    dr_error["Excel_RowNo"] = "1";
                    dr_error["User_Id"] = "Column 1";
                    dr_error["Remark"] = "'" + user_mst.Columns[0].ColumnName + "' is not a valid column name";

                    dt_error.Rows.Add(dr_error);
                }
                for (int m = 0; m < session_mst.Rows.Count; m++)
                {
                    string create_column_name = session_mst.Rows[m]["session_name"].ToString() + " (" + session_mst.Rows[m]["session_date"].ToString() + ")";

                    if (user_mst.Columns[m + 1].ColumnName != create_column_name)
                    {
                        dr_error = dt_error.NewRow();

                        dr_error["Excel_RowNo"] = "1";
                        dr_error["User_Id"] = "Column 2";
                        dr_error["Remark"] = "'" + user_mst.Columns[m + 1].ColumnName + "' is not a valid column name";
                        dt_error.Rows.Add(dr_error);
                    }
                }
                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    ServerLog.ExceptionLog("Error" + jsondata);
                    return jsondata;
                }
                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    isEmpty = true;
                    for (int j = 0; j < user_mst.Columns.Count; j++)
                    {

                        if (string.IsNullOrEmpty(user_mst.Rows[i][j].ToString()) == false)
                        {

                            isEmpty = false;
                            break;
                        }
                    }
                    if (isEmpty == true)
                    {
                        user_mst.Rows.RemoveAt(i);
                        i--;
                    }
                }

                if (user_mst.Rows.Count == 0)
                {
                    return "null";
                }

                for (int i = 0; i < user_mst.Rows.Count; i++)
                {
                    for (int k = 1; k < user_mst.Columns.Count; k++)
                    {
                        if (user_mst.Rows[i]["Student_code"].ToString() != "")
                        {
                            //string column_name = user_mst.Columns[k].ColumnName.ToString();
                            if (user_mst.Rows[i][user_mst.Columns[k].ColumnName.ToString()].ToString() == "A" || user_mst.Rows[i][user_mst.Columns[k].ColumnName.ToString()].ToString() == "P")
                            {
                                DataRow dr_new_CourseMaster = dataTable.NewRow();
                                dr_new_CourseMaster["session_attended"] = user_mst.Rows[i][user_mst.Columns[k].ColumnName.ToString()];
                                dr_new_CourseMaster["session_id"] = session_mst.Rows[k - 1]["session_id"];
                                dr_new_CourseMaster["user_id"] = user_mst.Rows[i]["Student_code"];
                                dr_new_CourseMaster["course_code"] = course_code;
                                dr_new_CourseMaster["semester_type"] = sem_code;
                                dr_new_CourseMaster["year_semester"] = year_code;
                                dataTable.Rows.Add(dr_new_CourseMaster);

                            }
                            else
                            {
                                dr_error = dt_error.NewRow();
                                dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                                dr_error["User_Id"] = user_mst.Rows[i]["Student_code"];
                                dr_error["Remark"] = "SESSION ATTENDED Value is not in a correct Format.";
                                dt_error.Rows.Add(dr_error);
                            }
                        }
                        else
                        {
                            dr_error = dt_error.NewRow();

                            dr_error["Excel_RowNo"] = Convert.ToString(i + 2);
                            dr_error["User_Id"] = "";
                            dr_error["Remark"] = "please Enter User Id";

                            dt_error.Rows.Add(dr_error);
                        }
                    }
                }
                if (dt_error.Rows.Count > 0)
                {
                    jsondata = GetJson1(dt_error);
                    ServerLog.ExceptionLog("student_session End " + jsondata);
                    return jsondata;
                }
                string excel_data_string;
                if (dataTable.Rows.Count > 0)
                {
                    excel_data_string = GetJson1(dataTable);
                }
                else
                {
                    excel_data_string = "";
                }

                excel_data_save_res = ws_save_all_students_wise_session_value(excel_data_string, "false");
            }
        }
        catch (Exception ex)
        {
            ServerLog.ExceptionLog("student_session End " + ex.Message);
            return "Problem in save data";
        }
        return excel_data_save_res;

    }


    [WebMethod(EnableSession = true)]
    public string ws_save_all_students_wise_session_value(string student_att_Data, string status)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            JavaScriptSerializer ser = new JavaScriptSerializer();

            List<Dictionary<string, object>> data = ser.Deserialize<List<Dictionary<string, object>>>(student_att_Data);

            // DataTable no_of_session_held = objmaster.get_number_of_session_held_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            DataTable student_course_attendance = objmaster.ws_get_student_session_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

            //DSC_Student_attendance exam_master_add = new DSC_Student_attendance();

            DSC_GradingMaster att_master_add = new DSC_GradingMaster();


            for (int i = 0; i < data.Count; i++)
            {
                //DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();
                //DSC_GradingMaster.student_wise_session_attendenceRow attendance_master = att_master_add.student_wise_session_attendence.Newstudent_wise_session_attendenceRow();
                DSC_GradingMaster.ws_student_wise_session_attendenceRow attendance_master = att_master_add.ws_student_wise_session_attendence.Newws_student_wise_session_attendenceRow();



                attendance_master.user_id = data[i]["user_id"].ToString();
                attendance_master.course_code = data[i]["course_code"].ToString();
                attendance_master.session_id = data[i]["session_id"].ToString();
                if (data[i]["session_attended"] != null)
                    attendance_master.session_attended = data[i]["session_attended"].ToString();
                else
                    attendance_master.session_attended = null;
                if (status == "true")
                {
                    attendance_master.is_submit = "Y";
                }
                else
                {
                    attendance_master.is_submit = "N";
                }

                attendance_master.cancel_flag = "N";
                if (student_course_attendance == null)
                {
                    attendance_master.created_by = user_id;
                    attendance_master.created_date = DateTime.Now;
                    attendance_master.created_host = HttpContext.Current.Request.UserHostName;
                }

                attendance_master.semester_type = data[i]["semester_type"].ToString();
                attendance_master.year_semester = data[i]["year_semester"].ToString();

                if (student_course_attendance != null)
                {

                    DataRow[] dts = student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'");
                    if (dts.Length == 0)
                    {
                        attendance_master.created_by = user_id;
                        attendance_master.created_date = DateTime.Now;
                        attendance_master.created_host = HttpContext.Current.Request.UserHostName;
                    }
                    else
                    {
                        attendance_master.created_by = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_by"].ToString();
                        attendance_master.created_date = Convert.ToDateTime((student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_date"].ToString());
                        attendance_master.created_host = (student_course_attendance.Select("course_code='" + data[i]["course_code"].ToString() + "' and user_id='" + data[i]["user_id"].ToString() + "' and session_id ='" + data[i]["session_id"].ToString() + "'"))[0]["created_host"].ToString();
                        attendance_master.last_modified_by = user_id;
                        attendance_master.last_modified_date = DateTime.Now;
                        attendance_master.last_modified_host = HttpContext.Current.Request.UserHostName;
                    }
                }

                //att_master_add.student_wise_course_attendence.Addstudent_wise_course_attendenceRow(attendance_master);
                //att_master_add.student_wise_session_attendence.Addstudent_wise_session_attendenceRow(attendance_master);
                att_master_add.ws_student_wise_session_attendence.Addws_student_wise_session_attendenceRow(attendance_master);
            }

            objBLReturnObject = objMaster.ws_save_student_session_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
            {
                if (status == "true")
                {
                    DataTable dt = objMaster.ws_get_student_wise_absend_present_dtl(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());

                    for (int i = 0; i < dt.Rows.Count; i++)
                    {
                        //DSC_GradingMaster.student_wise_course_attendenceRow attendance_master = att_master_add.student_wise_course_attendence.Newstudent_wise_course_attendenceRow();
                        DSC_GradingMaster.ws_student_wise_course_attendenceRow attendance_master = att_master_add.ws_student_wise_course_attendence.Newws_student_wise_course_attendenceRow();



                        attendance_master.user_id = dt.Rows[i]["user_id"].ToString();

                        attendance_master.course_code = data[0]["course_code"].ToString();

                        if (dt.Rows[i]["user_id"].ToString() != null && dt.Rows[i]["user_id"].ToString() != "")
                        {
                            attendance_master.no_of_session_attended = Convert.ToInt32(dt.Rows[i]["present"].ToString());
                            int total_session = Convert.ToInt32(dt.Rows[i]["present"].ToString()) + Convert.ToInt32(dt.Rows[i]["absent"].ToString());
                            double percentage = Convert.ToDouble(dt.Rows[i]["present"].ToString()) * 100 / Convert.ToDouble(total_session);
                            attendance_master.attendance_percentage = Convert.ToDouble(Math.Round(percentage, 2, MidpointRounding.AwayFromZero).ToString());


                        }
                        attendance_master.semester_type = data[0]["semester_type"].ToString();
                        attendance_master.year_semester = data[0]["year_semester"].ToString();
                        if (status == "true")
                        {
                            attendance_master.is_submit = "Y";
                        }
                        else { attendance_master.is_submit = "N"; }

                        attendance_master.cancel_flag = "N";
                        attendance_master.created_by = user_id;
                        attendance_master.created_date = DateTime.Now;
                        attendance_master.created_host = HttpContext.Current.Request.UserHostName;


                        //att_master_add.student_wise_course_attendence.Addstudent_wise_course_attendenceRow(attendance_master);
                        att_master_add.ws_student_wise_course_attendence.Addws_student_wise_course_attendenceRow(attendance_master);
                    }

                    objBLReturnObject = objMaster.ws_save_student_att_dtl(att_master_add, "2000", user_id, HttpContext.Current.Request.UserHostName);

                    if (objBLReturnObject.ExecutionStatus == 2)
                    {
                        objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
                    }
                    if (objBLReturnObject.ServerMessage == "Data Saved Successfully")
                    {
                        if (status == "true")
                        {
                            dynamic value = objMaster.ws_update_course_wise_session(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString());
                            dynamic value_att = objMaster.ws_update_student_exam_dtl_table(data[0]["course_code"].ToString(), data[0]["semester_type"].ToString(), data[0]["year_semester"].ToString(), att_master_add.student_wise_course_attendence);
                        }

                    }
                }

            }

        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }


