    [WebMethod(EnableSession = true)]
    public dynamic insert_course_remark(String semester, String year, String interested_remark_data)
    {

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        JavaScriptSerializer ser = new JavaScriptSerializer();
        ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_remark_data);
        string remark = "";
        string course_code = "";
        string inst_code = "";
        for (int i = 0; i < arr_interested_program_data.Count; i++)
        {
            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];
            remark = data["remark"].ToString().Replace("&#39;", "'");
            course_code = data["course_code"].ToString();
            inst_code = data["instructor_code"].ToString();
        }

        //remark = encoding_decoding.encryptPassword(remark.ToString().Trim()); 

        dynamic status = objmaster.insert_course_remark(semester, year, user_id, HttpContext.Current.Request.UserHostName.ToString(), inst_code, course_code, remark);
        if (status)
        {
            bool mail_status = objmaster.Send_Mail_for_Course_auth(course_code, inst_code, "CourseAuthorizationRemark", remark, semester, year);
        }
        return status;
    }


    [WebMethod(EnableSession = true)]
    public dynamic insert_course_remark_coure_wise(String semester, String year, String interested_remark_data)
    {

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        JavaScriptSerializer ser = new JavaScriptSerializer();
        ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_remark_data);
        string remark = "";
        string course_code = "";
        string inst_code = "";
        for (int i = 0; i < arr_interested_program_data.Count; i++)
        {
            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];
            remark = data["remark"].ToString().Replace("&#39;", "'");
            course_code = data["course_code"].ToString();
            inst_code = data["instructor_code"].ToString();
        }

        //remark = encoding_decoding.encryptPassword(remark.ToString().Trim()); 

        dynamic status = objmaster.insert_course_remark_course_wise(semester, year, user_id, HttpContext.Current.Request.UserHostName.ToString(), inst_code, course_code, remark);
        if (status)
        {
            bool mail_status = objmaster.Send_Mail_for_Course_auth_without_course(course_code, inst_code, "CourseAuthorizationRemark", remark, semester, year);
        }
        return status;
    }


    [WebMethod(EnableSession = true)]
    public string WS_Uso_Hr_Authorized(string instructor_code, string sem_code, string year_code, string course_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();

        try
        {
            if (user_type == "HR")
            {
                bool saved_authorized = objmaster.WS_Uso_Hr_Authorized(instructor_code, sem_code, year_code, course_code, user_id);

                if (saved_authorized)
                {
                    objBLReturnObject.ServerMessage = "HR Authorized Successfully";

                    DSC_Course_Log course_log = new DSC_Course_Log();

                    DSC_Course_Log.course_master_change_logRow course_log_row = course_log.course_master_change_log.Newcourse_master_change_logRow();


                    course_log_row.log_id = "1";
                    course_log_row.user_id = user_id;
                    //course_log_row.course_code = dt_workload_dtl.Rows[0]["course_code"].ToString();
                    course_log_row.course_code = course_code + " Courses";
                    course_log_row.remark = "Modify Workload Authorize Detail by HR (USO) " + " " + sem_code + year_code;
                    course_log_row.created_by = user_id;
                    course_log_row.created_date = DateTime.Now;
                    course_log_row.created_host = HttpContext.Current.Request.UserHostName;


                    course_log.course_master_change_log.Addcourse_master_change_logRow(course_log_row);

                    BLReturnObject Log_objBLReturnObject = new BLReturnObject();

                    Log_objBLReturnObject = objmaster.add_course_log_details(course_log, "2000", user_id, HttpContext.Current.Request.UserHostName);
                }
                else
                {
                    objBLReturnObject.ServerMessage = "Problem in update data.";
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }

        return objBLReturnObject.ServerMessage;
    }

    [WebMethod(EnableSession = true)]
    public string Check_eligibility_L2(string studio_level, string sub_cat_id)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string status = "false";
        try
        {
            DataTable Get_current_sem = objmaster.Get_cept_current_sem_data("L3_Choice_Reg");
            DataTable Get_student_marks_dtl = objmaster.Get_Student_Exam_Marks_dtl(user_id);
            DataTable Get_course_Data = objmaster.Get_studio_level_status(user_id, studio_level);
            DataTable Get_Data_Count = objmaster.Get_level_course_count(user_id, studio_level);
            DataTable Get_Count_data = objmaster.Check_eligibility_year_wise(user_id, studio_level);
            DataTable Get_previe_sem = objmaster.Get_Student_prev_sem(user_id);

            DataTable check_intenship_credit = new DataTable();
            if (sub_cat_id == "29")
            {
                check_intenship_credit = objmaster.check_intenship_elg(user_id);
            }
            if (Get_course_Data != null && Get_Data_Count != null && Get_Count_data != null)
            {
                int total_credit = Convert.ToInt32(Get_Data_Count.Rows[0]["course_credits"].ToString());

                //DataRow[] dr = Get_course_Data.Select("final_grade = 'F'");
                //if (dr.Length > 0)
                //{
                //    for (int k = 0; k < dr.Length; k++)
                //    {
                //        total_credit = total_credit - Convert.ToInt32(dr[k]["credits"].ToString());
                //    }
                //}
                DataRow[] dr_new = Get_course_Data.Select("final_grade is null OR final_grade =''");
                if (dr_new.Length > 0)
                {
                    for (int i = 0; i < dr_new.Length; i++)
                    {
                        if (dr_new[i]["semester_type"].ToString() == Get_previe_sem.Rows[0]["semester_type"].ToString() && dr_new[i]["year_semester"].ToString() == Get_previe_sem.Rows[0]["year_semester"].ToString())
                        {
                            if (sub_cat_id == "26")
                            {
                                int cours_credits = Convert.ToInt32(Get_Data_Count.Rows[0]["course_credits"].ToString());
                                int credit_current_sem = Convert.ToInt32(dr_new[i]["credits"].ToString());
                                //total_credit = cours_credits - credit_current_sem;
                                total_credit = total_credit - credit_current_sem;
                            }
                            if (sub_cat_id == "29")
                            {
                                total_credit = total_credit - Convert.ToInt32(dr_new[i]["credits"].ToString());
                            }
                        }
                        else
                        {
                            //if (sub_cat_id == "23")
                            //{
                            total_credit = total_credit - Convert.ToInt32(dr_new[i]["credits"].ToString());
                            //}

                            //return status;
                            //check Fail Pass Status 
                        }
                    }
                }

                bool check_status = false;
                int course_count = total_credit;
                int req_min_credit = Convert.ToInt32(Get_Count_data.Rows[0]["req_min_credit"].ToString());
                int req_max_credit = Convert.ToInt32(Get_Count_data.Rows[0]["req_max_credit"].ToString());
                if ((course_count >= req_min_credit) && (course_count <= req_max_credit))
                {
                    check_status = true;
                }
                else if (sub_cat_id == "29")
                {
                    int total_credit_with_drp = Convert.ToInt32(Get_Data_Count.Rows[0]["course_credits"].ToString());
                    if (check_intenship_credit != null)
                    {
                        total_credit_with_drp = total_credit_with_drp + Convert.ToInt32(check_intenship_credit.Rows[0]["course_credits"].ToString());
                    }
                    DataRow[] check_drp_dr_new = Get_course_Data.Select("final_grade is null OR final_grade =''");
                    if (check_drp_dr_new.Length > 0)
                    {
                        for (int i = 0; i < check_drp_dr_new.Length; i++)
                        {
                            if (check_drp_dr_new[i]["semester_type"].ToString() != Get_previe_sem.Rows[0]["semester_type"].ToString() && check_drp_dr_new[i]["year_semester"].ToString() != Get_previe_sem.Rows[0]["year_semester"].ToString())
                            {
                                total_credit_with_drp = total_credit_with_drp - Convert.ToInt32(check_drp_dr_new[i]["credits"].ToString());
                            }
                        }
                    }
                    int inst_remening = 0;
                    if (check_intenship_credit != null)
                    {
                        inst_remening = total_credit_with_drp - Convert.ToInt32(check_intenship_credit.Rows[0]["course_credits"].ToString());
                    }

                    if ((total_credit_with_drp >= req_min_credit) && (total_credit_with_drp <= req_max_credit))
                    {
                        check_status = true;
                    }
                    else if ((inst_remening >= req_min_credit) && (inst_remening <= req_max_credit))
                    {
                        check_status = true;
                    }

                }
                else if (sub_cat_id == "26")
                {
                    int total_credit_with_int = Convert.ToInt32(Get_Data_Count.Rows[0]["course_credits"].ToString());

                    DataRow[] check_int_dr_new = Get_course_Data.Select("final_grade is null OR final_grade =''");
                    if (check_int_dr_new.Length > 0)
                    {
                        for (int i = 0; i < check_int_dr_new.Length; i++)
                        {
                            if (check_int_dr_new[i]["semester_type"].ToString() != Get_previe_sem.Rows[0]["semester_type"].ToString() && check_int_dr_new[i]["year_semester"].ToString() != Get_previe_sem.Rows[0]["year_semester"].ToString())
                            {
                                total_credit_with_int = total_credit_with_int - Convert.ToInt32(check_int_dr_new[i]["credits"].ToString());
                            }
                        }
                    }
                    if ((total_credit_with_int >= req_min_credit) && (total_credit_with_int <= req_max_credit))
                    {
                        check_status = true;
                    }

                }

                if (check_status)
                {
                    bool L3_status = objmaster.insert_L3_Data(Get_current_sem.Rows[0]["sem_code"].ToString(), Get_current_sem.Rows[0]["year_code"].ToString(), user_id, HttpContext.Current.Request.UserHostName.ToString(), sub_cat_id, user_type);
                    status = "true";
                    return status;
                }

            }
            return status;
        }
        catch (Exception ex)
        {
            return "Problem in update DATA.";
        }
    }


     

