        //Boolean GetSessionData = objmaster.SessionInsert(user_id, user_type, session_id);
        DataTable dt = new DataTable();
        DataTable dt_req = objmaster.SWS_allow_registration_for_particular_student(HttpContext.Current.Session["UserId"].ToString());
        if (dt_req != null && dt_req.Rows[0]["cancel_flag"].ToString() == "P")
        {
            dt = objmaster.Get_Datetime_wise_parameter_dtl("SW_Request_base_Course_Registration", "S");
        }
        else { dt = objmaster.Get_Datetime_wise_parameter_dtl("SW_Connect_Course_Registration", "S"); }
        //dt = objmaster.Get_Datetime_wise_parameter_dtl("SW_Connect_Course_Registration", "S");
        if (dt == null)
