        DataTable dt_current_sem = objmaster.Get_ws_cept_current_sem_data();
        string sem_code = dt_current_sem.Rows[0]["sem_code"].ToString();
        string year_code = dt_current_sem.Rows[0]["year_code"].ToString();
        string msg = "";
        if (status == "D")
        {
            bool allocation_delete = objmaster.sws_allocation_delete(HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code, course_type);
            if (allocation_delete)
            {
                msg = "Allocation Delete Succesfully for selected semester and year";
                return msg;
            }
        }

        if (course_type == "E")
        {


            DataTable SWS_Student_allocation = objmaster.SWS_Student_allocation_Timewise(sem_code, year_code);
            if (SWS_Student_allocation != null)
            {
                DataRow[] check_allocation_status = SWS_Student_allocation.Select("status ='P'");
                if (check_allocation_status.Length > 0)
                {
                    msg = "Allocation already published for selected semester and year";
                    return msg;
                }
            }


            DataTable short_data = objmaster.SWS_Student_Shortlist_Timewise(sem_code, year_code);
            //DataView view = new DataView(short_data);
            //DataTable distinctValues = view.ToTable(true, "user_id");
            DataTable distinctValues = objmaster.SWS_Student_Get_data_date_wise(sem_code, year_code);

            DataTable dt_elective_course = objmaster.Get_SWS_elective_course_data(sem_code, year_code);
            DataTable get_credit_combination = objmaster.Get_combination_detl(sem_code, year_code);

            DataTable custTable = new DataTable("Customers");
            DataColumn dtColumn;
            DataRow myDataRow;

            // Create id column
            dtColumn = new DataColumn();
            dtColumn.DataType = typeof(String);
            dtColumn.ColumnName = "doc_no";


            custTable.Columns.Add(dtColumn);


            if (short_data != null && dt_elective_course != null && get_credit_combination != null)
            {
                ArrayList allocation_list = new ArrayList();
                for (int i = 0; i < distinctValues.Rows.Count; i++) // Time Wise Short user 
                {
                    if (distinctValues.Rows[i]["user_id"].ToString() == "PLA22256" || distinctValues.Rows[i]["user_id"].ToString() == "PHD22410")
                    {
                        string test = "";

                    }
                    ServerLog.ExceptionLog("SWS Allocation Check User id Time wise " + distinctValues.Rows[i]["user_id"]);
                    DataRow[] dr = get_credit_combination.Select("user_id='" + distinctValues.Rows[i]["user_id"] + "'");
                    if (dr.Length > 0)
                    {
                        ServerLog.ExceptionLog("Check Length get_credit_combination Table " + distinctValues.Rows[i]["user_id"]);
                        int combination_count = Convert.ToInt32(dr[0]["no_of_combination"]);
                        ServerLog.ExceptionLog("Check combination Count " + combination_count);
                        for (int k = 1; k <= combination_count; k++)
                        {
                            ServerLog.ExceptionLog("Check combination Loop " + k);

                            for (int p = 1; p <= 8; p++)
                            {
                                ServerLog.ExceptionLog("Check piroity Loop " + p);
                                DataRow[] dr_allocation = short_data.Select("user_id='" + distinctValues.Rows[i]["user_id"] + "' and credit_combination ='" + k + "' and priority='" + p + "'");

                                if (dr_allocation.Length > 0)
                                {
                                    int SelectedIndex = short_data.Rows.IndexOf(dr_allocation[0]);
                                    DataRow[] check_dup_dr_allocation = short_data.Select("course_code='" + dr_allocation[0]["course_code"] + "' and user_id='" + distinctValues.Rows[i]["user_id"] + "' and status ='P' and priority='" + p + "'");
                                    DataRow[] check_total_sets_allow = short_data.Select("course_code='" + dr_allocation[0]["course_code"] + "' and status ='P'");

                                    DataRow[] check_user_allocation_dr_allocation = short_data.Select("course_code='" + dr_allocation[0]["course_code"] + "' and user_id='" + distinctValues.Rows[i]["user_id"] + "' and status ='P'");
                                    if (check_user_allocation_dr_allocation.Length == 0)
                                    {
                                        if (check_dup_dr_allocation.Length == 0)
                                        {
                                            if (check_total_sets_allow.Length > 0)
                                            {
                                                DataRow[] dr_course_count = dt_elective_course.Select("course_code ='" + dr_allocation[0]["course_code"] + "'");
                                                int course_available_seat = Convert.ToInt32(dr_course_count[0]["available_seat"].ToString());
                                                if (check_total_sets_allow.Length < course_available_seat)
                                                {
                                                    int row_count = Convert.ToInt32(dr_allocation[0]["row_num"].ToString());
                                                    myDataRow = custTable.NewRow();
                                                    myDataRow["doc_no"] = dr_allocation[0]["doc_no"].ToString();
                                                    custTable.Rows.Add(myDataRow);

                                                    short_data.Rows[SelectedIndex]["status"] = "P";
                                                    short_data.AcceptChanges();
                                                    break;
                                                }
                                            }
                                            else
                                            {
                                                DataRow[] dr_course_count = dt_elective_course.Select("course_code ='" + dr_allocation[0]["course_code"] + "'");
                                                int course_available_seat = Convert.ToInt32(dr_course_count[0]["available_seat"].ToString());
                                                if (check_total_sets_allow.Length < course_available_seat)
                                                {

                                                    int row_count = Convert.ToInt32(dr_allocation[0]["row_num"].ToString());
                                                    myDataRow = custTable.NewRow();
                                                    myDataRow["doc_no"] = dr_allocation[0]["doc_no"].ToString();
                                                    custTable.Rows.Add(myDataRow);
                                                    short_data.Rows[SelectedIndex]["status"] = "P";
                                                    short_data.AcceptChanges();
                                                    break;
                                                }
                                            }

                                        }
                                    }
                                    else
                                    {
                                        //if (dr_allocation[0]["course_code"] == "S23FA008" && distinctValues.Rows[i]["user_id"] == "PAT22228")
                                        //{
                                        //    string test = "";
                                        //}
                                    }


                                }
                            }

                        }

                    }
                }
            }


            bool allocation_status = objmaster.sws_allocation_save(custTable, HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code);
            if (allocation_status)
            {
                bool expire_save_data = objmaster.sws_Date_wise_Expire_save_data(HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code);
                if (expire_save_data)
                {
                    bool UpdateCredit = objmaster.SWSUpdatCredits(HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code);
                }


                msg = "Allocation published Succesfully for selected semester and year";
                return msg;
            }
        }
        else
        {
            DataTable SWS_Student_allocation_mandatory = objmaster.SWS_Student_allocation_mandatory(sem_code, year_code);
            bool mandatory_allocation_status = objmaster.sws_mandatory_allocation_save(SWS_Student_allocation_mandatory, HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code);
            if (mandatory_allocation_status)
            {
                bool expire_save_data = objmaster.sws_Date_wise_Expire_save_data(HttpContext.Current.Request.UserHostName.ToString(), HttpContext.Current.Session["UserId"].ToString(), sem_code, year_code);
                msg = "Mandatory Allocation published Succesfully for selected semester and year";
                return msg;
            }
        }

        return msg;
    }


    #region SWS Fees Payment

    [WebMethod(EnableSession = true)]
    public string sws_connect_fees_payment()
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        DataTable dt = objmaster.Get_Datetime_wise_parameter_dtl("ws_fees_payment", user_type);
        if (dt == null)
        {
            return "Time";
        }
        bool gst_status = false;
        try
        {
            string user_type_student = "";

            DataTable user_dtl = objmaster.check_user_by_user_id(user_id);
            if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "P")
            {
                user_type_student = "P";
                gst_status = true;
            }
            else if (user_dtl.Rows[0]["user_type"].ToString() == "E" && user_dtl.Rows[0]["prof_details"].ToString() == "S")
            {
                user_type_student = "S";
                gst_status = true;
            }
            else
            {
                user_type_student = user_type;
            }
            DataTable dataTable = objmaster.Get_fees_amount_pre_credit_WS_year_wise_manually(user_id, user_type);
            DataTable check_manually_course_dtl = objmaster.Get_sws_checkPayment_manually_course_dtl(user_id);
            DataTable dt_fees_enable = objmaster.get_parameter_screen_rights_dtl_with_user_type("ws_fees_payment", user_type_student);
            if (HttpContext.Current.Session["UserID"].ToString() != "ucadmin")
            {
                if (dataTable != null && check_manually_course_dtl != null)
                {

                }

                else if (dt_fees_enable.Rows[0]["parameter_value"].ToString() == "D")
                {

                    return "Online SWS Course fees payment option is currently closed. Please contact SWS office.";
                }
            }



            ServerLog.ExceptionLog("Get Data Smart Card");
            XSD.Masters_WS.DS_Payment_WS dS_Payment_WS = new XSD.Masters_WS.DS_Payment_WS();

            XSD.Masters_WS.DS_Payment_WS.ws_applicationpaymenttransactionRow ws_ApplicationpaymenttransactionRow = dS_Payment_WS.ws_applicationpaymenttransaction.Newws_applicationpaymenttransactionRow();

            ws_ApplicationpaymenttransactionRow.transaction_id = "1";
            ws_ApplicationpaymenttransactionRow.user_id = HttpContext.Current.Session["UserID"].ToString();

            ws_ApplicationpaymenttransactionRow.current_sem_code = "0";
            ws_ApplicationpaymenttransactionRow.dept_id = HttpContext.Current.Session["dept_code"].ToString();
            ws_ApplicationpaymenttransactionRow.payment_send_flag = "Y";
            ws_ApplicationpaymenttransactionRow.payment_return_flag = "N";
            DataTable dt_param_data = new DataTable();
            DataTable dt_credit_param_data = new DataTable();
            dt_credit_param_data = objmaster.Get_total_pay_credit(user_id);
            if (dataTable != null && check_manually_course_dtl != null)
            {
                dt_param_data = objmaster.Get_fees_amount_pre_credit_WS_year_wise_manually(user_id, user_type);

                ws_ApplicationpaymenttransactionRow.manually_course_status = "M";
                if (dt_credit_param_data != null)
                {
                    int total_credit = Convert.ToInt32(dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString())
                        + Convert.ToInt32(dt_credit_param_data.Rows[0]["total_credit"].ToString());
                    ws_ApplicationpaymenttransactionRow.total_credit = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                    ws_ApplicationpaymenttransactionRow.total_credit_pay = Convert.ToString(total_credit);
                }
                else
                {
                    ws_ApplicationpaymenttransactionRow.total_credit = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                    ws_ApplicationpaymenttransactionRow.total_credit_pay = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                }

            }
            else
            {
                //dt_param_data = objmaster.Get_fees_amount_pre_credit_WS_year_wise(user_id, user_type); 
                dt_param_data = objmaster.Get_fees_amount_pre_credit_WS_year_wise_new(user_id, user_type);
                if (dt_credit_param_data != null)
                {
                    int total_credit = Convert.ToInt32(dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString())
                        + Convert.ToInt32(dt_credit_param_data.Rows[0]["total_credit"].ToString());
                    ws_ApplicationpaymenttransactionRow.total_credit = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                    ws_ApplicationpaymenttransactionRow.total_credit_pay = Convert.ToString(total_credit);
                }
                else
                {
                    ws_ApplicationpaymenttransactionRow.total_credit = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                    ws_ApplicationpaymenttransactionRow.total_credit_pay = dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString();
                }

            }

            ServerLog.ExceptionLog("Get SWS Course Amount");
            int total_fees_amount = 0;
            int total_without_gst_fees_amount = 0;
            int fees_waiver_credits = 0;
            int fees_manually_waiver_credits = 0;
            int credit_amount = 0;
            if (dt_param_data != null)
            {
                //credit_amount = Convert.ToInt32(dt_param_data.Rows[0]["Total_credits"].ToString()) * Convert.ToInt32(dt_param_data.Rows[0]["fees_amount"].ToString());
                credit_amount = Convert.ToInt32(dt_param_data.Rows[0]["Total_credits_remaning_payment"].ToString()) * Convert.ToInt32(dt_param_data.Rows[0]["fees_amount"].ToString());

                if (dt_param_data.Rows[0]["fees_waiver_credits"].ToString() != "" && dt_param_data.Rows[0]["fees_waiver_credits"].ToString() != null)
                {
                    fees_waiver_credits = Convert.ToInt32(dt_param_data.Rows[0]["fees_waiver_credits"].ToString()) * Convert.ToInt32(dt_param_data.Rows[0]["fees_amount"].ToString());

                    if (dataTable != null && check_manually_course_dtl != null)
                    {
                        if (dataTable.Rows[0]["total_allocated_credit"].ToString() != "" || dataTable.Rows[0]["total_allocated_credit"].ToString() != "0")
                        {
                            fees_manually_waiver_credits = Convert.ToInt32(dt_param_data.Rows[0]["total_allocated_credit"].ToString()) * Convert.ToInt32(dt_param_data.Rows[0]["fees_amount"].ToString());
                            if (fees_waiver_credits != 0)
                            {
                                fees_waiver_credits = Convert.ToInt32(fees_waiver_credits) - Convert.ToInt32(fees_manually_waiver_credits);
                            }

                        }
                    }
                }
                if (fees_waiver_credits > credit_amount)
                {
                    total_fees_amount = fees_waiver_credits - credit_amount;
                }
                else
                {
                    total_fees_amount = credit_amount - fees_waiver_credits;
                }

                DataTable calculate_fees_amount = objmaster.calculate_fees_amount(user_id, user_type);

                if (calculate_fees_amount != null)
                {
                    total_without_gst_fees_amount = Convert.ToInt32(calculate_fees_amount.Rows[0]["payamount"].ToString());
                    total_fees_amount = Convert.ToInt32(calculate_fees_amount.Rows[0]["payamount"].ToString());
                }
                else
                {
                    total_without_gst_fees_amount = total_fees_amount;
                }

                if (gst_status)
                {
                    //18 % GST
                    int gst_rate = 18;
                    ws_ApplicationpaymenttransactionRow.igst_rate = gst_rate;
                    int GST = 0;
                    GST = (total_fees_amount * 18 / 100);
                    total_fees_amount = total_fees_amount + GST;
                    ws_ApplicationpaymenttransactionRow.igst_amount = GST;
                }
            }
            ws_ApplicationpaymenttransactionRow.amount = Convert.ToDecimal(total_without_gst_fees_amount);//13000
            if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
            {
                ws_ApplicationpaymenttransactionRow.total_amount = 1;
            }
            else { ws_ApplicationpaymenttransactionRow.total_amount = total_fees_amount; }

            //HostelFeesPayment_row.amount = Convert.ToDecimal("13000");//13000

            if (HttpContext.Current.Session["UserID"].ToString() == "pa1admin")
            {
                ws_ApplicationpaymenttransactionRow.amount = 1;
            }
            if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
            {
                ws_ApplicationpaymenttransactionRow.amount = 1;
            }


            #region New logic 
            //if (check_manually_course_dtl == null)
            //{
            DataTable Dt_RequiredToPayDat = objmaster.SWSCreditCalculation(user_id, dt_param_data.Rows[0]["semester_type"].ToString(), dt_param_data.Rows[0]["year_semester"].ToString());
            if (Dt_RequiredToPayDat != null)
            {
                DataTable dt_paymentdtl = objmaster.SWSCreditCalculationWithGST(user_id, dt_param_data.Rows[0]["semester_type"].ToString(), dt_param_data.Rows[0]["year_semester"].ToString(), gst_status);

                if (HttpContext.Current.Session["UserID"].ToString() == "pa1admin")
                {
                    ws_ApplicationpaymenttransactionRow.amount = 1;
                }
                if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
                {
                    ws_ApplicationpaymenttransactionRow.amount = 1;
                }
                else
                {
                    if (gst_status)
                    {
                        total_fees_amount = Convert.ToInt32(dt_paymentdtl.Rows[0]["total_amount_with_gst"].ToString());
                        ws_ApplicationpaymenttransactionRow.amount = Convert.ToDecimal(dt_paymentdtl.Rows[0]["total_amount_before_gst"].ToString());
                        ws_ApplicationpaymenttransactionRow.total_amount = total_fees_amount;
                        int gst_rate = 18;
                        ws_ApplicationpaymenttransactionRow.igst_rate = gst_rate;
                        ws_ApplicationpaymenttransactionRow.igst_amount = Convert.ToInt32(dt_paymentdtl.Rows[0]["total_gst_amount"].ToString()); ;
                    }
                    else
                    {
                        total_fees_amount = Convert.ToInt32(dt_paymentdtl.Rows[0]["total_amount_before_gst"].ToString());
                        ws_ApplicationpaymenttransactionRow.amount = Convert.ToDecimal(dt_paymentdtl.Rows[0]["total_amount_before_gst"].ToString());
                        ws_ApplicationpaymenttransactionRow.total_amount = total_fees_amount;
                    }

                }
            }
            //}

            #endregion




            ws_ApplicationpaymenttransactionRow.status_is_active = "A";
            ws_ApplicationpaymenttransactionRow.status_refund = "N";
            ws_ApplicationpaymenttransactionRow.status_is_payment_received = "N";
            ws_ApplicationpaymenttransactionRow.semester_type = dt_param_data.Rows[0]["semester_type"].ToString();
            ws_ApplicationpaymenttransactionRow.year_semester = dt_param_data.Rows[0]["year_semester"].ToString();

            ws_ApplicationpaymenttransactionRow.created_by = HttpContext.Current.Session["UserID"].ToString();
            ws_ApplicationpaymenttransactionRow.created_date = DateTime.Now;
            ws_ApplicationpaymenttransactionRow.created_host = HttpContext.Current.Request.UserHostName;

            dS_Payment_WS.ws_applicationpaymenttransaction.Addws_applicationpaymenttransactionRow(ws_ApplicationpaymenttransactionRow);
            objBLReturnObject = objmaster.save_SWSCourse_fees_payment(dS_Payment_WS, "2000", "", HttpContext.Current.Request.UserHostName, ref dS_Payment_WS);
            if (objBLReturnObject.ExecutionStatus == 2)
            {
                objBLReturnObject.ServerMessage = "Problem in update data " + objBLReturnObject.ServerMessage;
            }
            else if (objBLReturnObject.ExecutionStatus == 1)
            {
                ServerLog.ExceptionLog("Sws Course Step 1 ");
                if (dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["total_amount"].ToString() != "0")
                {
                    string message = "";
                    //string transaction_id = "";
                    //string user_id = "";
                    string dept_code = HttpContext.Current.Session["dept_code"].ToString();
                    //string current_sem_code = "";
                    //string trans_code = "";
                    Payment objPayment = new Payment();
                    Dictionary<string, object> param = new Dictionary<string, object>();
                    Dictionary<string, object> obj_data = new Dictionary<string, object>();

                    bool result = true;

                    string MerchantId = Payment.GetMerchantId(dept_code);

                    string hmac_url = Payment.Get_hmac_url(dept_code);

                    string return_url = "PaymentResponseKotak_SWSCourse.aspx";

                    string str_path = "";
                    //if (HttpContext.Current.Request.Url.Segments.Length == 3)
                    //{
                    //    str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + "Student/";
                    //}
                    //else if (HttpContext.Current.Request.Url.Segments.Length == 4) 
                    //{
                    //    str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1] + "Student/";
                    //}


                    if (HttpContext.Current.Request.Url.Segments.Length == 3)
                    {
                        str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0];
                    }
                    else if (HttpContext.Current.Request.Url.Segments.Length == 4)
                    {
                        str_path = HttpContext.Current.Request.Url.Authority + HttpContext.Current.Request.Url.Segments[0] + HttpContext.Current.Request.Url.Segments[1];
                    }

                    string base_url = "https://" + str_path;


                    obj_data["status"] = result;
                    obj_data["message"] = message;
                    obj_data["user_id"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["user_id"];
                    if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
                    {
                        obj_data["amount"] = 1;
                    }
                    else
                    {
                        obj_data["amount"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["total_amount"];
                    }

                    //obj_data["amount"] = 1;

                    obj_data["transaction_id"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["transaction_id"];
                    obj_data["merchant_id"] = MerchantId;
                    obj_data["currency"] = "INR";
                    obj_data["hmac_url"] = hmac_url;
                    obj_data["return_url"] = base_url + return_url;

                    //Kotak PG

                    Dictionary<string, object> dic_payment_dtl = new Dictionary<string, object>();

                    dic_payment_dtl["merchant_id"] = objPayment.Get_Kotak_MerchantId(dept_code);
                    dic_payment_dtl["order_id"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["transaction_id"];
                    if (HttpContext.Current.Session["UserID"].ToString() == "ucadmin")
                    {
                        dic_payment_dtl["amount"] = 1;
                    }
                    else
                    {
                        dic_payment_dtl["amount"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["total_amount"];
                    }

                    dic_payment_dtl["currency"] = "INR";
                    dic_payment_dtl["redirect_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "PaymentResponseKotak_SWSCourse.aspx";
                    dic_payment_dtl["cancel_url"] = HttpContext.Current.Request.Url.Scheme + "://" + str_path + "PaymentResponseKotak_SWSCourse.aspx";
                    dic_payment_dtl["language"] = "EN";

                    dic_payment_dtl["merchant_param1"] = dS_Payment_WS.ws_applicationpaymenttransaction.Rows[0]["user_id"];
                    dic_payment_dtl["merchant_param2"] = HttpContext.Current.Session["UserName"];
                    dic_payment_dtl["merchant_param3"] = dept_code;
                    dic_payment_dtl["merchant_param4"] = ""; // 28062019
                    dic_payment_dtl["is_swscoursepayment"] = "Y";

                    obj_data["kotak_request_url"] = objPayment.Get_Kotak_request_url(dept_code);
                    obj_data["encRequest"] = objPayment.Get_Kotak_encrypted_request(ref dic_payment_dtl);
                    obj_data["access_code"] = objPayment.Get_Kotak_access_code(dept_code);

                    Session["encRequest"] = obj_data["encRequest"];
                    Session["access_code"] = obj_data["access_code"];
                    Session["kotak_request_url"] = obj_data["kotak_request_url"];

                    return JsonConvert.SerializeObject(obj_data);
                }
                else
                {
                    Dictionary<string, object> obj_data = new Dictionary<string, object>();

                    obj_data["status"] = false;
                    obj_data["message"] = "Problem in Payment Redirection, Please try again.";

                    return JsonConvert.SerializeObject(obj_data);
                }
            }
        }
        catch (Exception ex)
        {
            return "Problem in Fees Payment. Plese try again.";
        }

        return objBLReturnObject.ServerMessage;
    }


    [WebMethod(EnableSession = true)]
