        DataTable Get_fees_credit_manually = objmaster.Get_fees_amount_pre_credit_WS_year_wise_manually(user_id, user_type);
        DataTable check_select_mandatory_course_select = objmaster.select_mandatory_course_dtl(user_id);
        DataTable CheckPaymnetStatusByCreditCalculation = objmaster.CheckPaymnetStatusByCreditCalculation(user_id);


        if (Get_date != null)
        {
            jsonarray[0] = GetJson1(Get_date);
        }
        if (Get_fees_credit != null)
        {
            jsonarray[1] = GetJson1(Get_fees_credit);
        }
        if (Get_fees_course_manually_dtl != null)
        {
            jsonarray[2] = GetJson1(Get_fees_course_manually_dtl);
        }
        if (Get_fees_credit_manually != null)
        {
