    [WebMethod(EnableSession = true)]
    public dynamic ws_course_allocate_user_for_send_mail(string sem_code, string year_code, string modstatus, string course_type)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        // M = Mail Send 
        // A = Final Allocation
        if (modstatus == "M")
        {

            bool publish_flag = objmaster.ws_insert_published_allocation(sem_code, year_code, user_id, HttpContext.Current.Request.UserHostName.ToString());
            DataTable dt_send_mail_data = objmaster.ws_course_allocate_user_for_send_mail(sem_code, year_code, course_type);
            string status = "";
            if (dt_send_mail_data != null)
            {
                DataTable dt_send_email_data = objmaster.Get_VF_TA_AA_Letter_Email_Body("CourseAlloc", "email");

                string subject = dt_send_email_data.Rows[0]["subject"].ToString();

                string remark = dt_send_email_data.Rows[0]["body"].ToString();
                status = objmail.sws_SendMailtostudentforPublish(dt_send_mail_data, remark, subject);
            }

            if (status == "success")
            {
                return "success";

            }
        }
        else if (modstatus == "A")
        {
            bool publish_flag = objmaster.WS_Course_allocation_Final(sem_code, year_code, HttpContext.Current.Request.UserHostName.ToString());
            if (publish_flag)
            {
                return "Allocated";
            }

        }

        return "false";
    }


