    [WebMethod(EnableSession = true)]
    public dynamic ws_insert_course_remark(String semester, String year, String interested_remark_data)
    {

        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        JavaScriptSerializer ser = new JavaScriptSerializer();
        ArrayList arr_interested_program_data = ser.Deserialize<ArrayList>(interested_remark_data);
        string remark = "";
        string course_code = "";
        string inst_code = "";
        for (int i = 0; i < arr_interested_program_data.Count; i++)
        {
            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];
            remark = data["remark"].ToString().Replace("&#39;", "'");
            course_code = data["course_code"].ToString();
            inst_code = data["instructor_code"].ToString();
        }

        //remark = encoding_decoding.encryptPassword(remark.ToString().Trim()); 

        dynamic status = objmaster.ws_insert_course_remark(semester, year, user_id, HttpContext.Current.Request.UserHostName.ToString(), inst_code, course_code, remark);
        if (status)
        {
            bool mail_status = objmaster.ws_Send_Mail_for_Course_auth(course_code, inst_code, "SWSHRRemark", remark, semester, year);
        }
        return status;
    }




