    [WebMethod]
    public string Get_tab_data(string sem_code, string year_code, string status)
    {
        DataTable rateband_data = objmaster.Get_tab_data(sem_code, year_code, status);
        DataTable approved_rateband_data = objmaster.Approved_rateband_dtl(sem_code, year_code);
        if (rateband_data != null)
        {

            for (int i = 0; i < rateband_data.Rows.Count; i++)
            {



                string htmltext = rateband_data.Rows[i]["htmltext"].ToString();
                htmltext = htmltext.Replace("@@Fullname", rateband_data.Rows[i]["full_name"].ToString());
                htmltext = htmltext.Replace("@@instructor_code", rateband_data.Rows[i]["instructor_code"].ToString());
                htmltext = htmltext.Replace("@@VF_code", rateband_data.Rows[i]["VF_code"].ToString());
                htmltext = htmltext.Replace("@@designation", rateband_data.Rows[i]["designation"].ToString());
                htmltext = htmltext.Replace("@@highestqualification", rateband_data.Rows[i]["highest_qualification"].ToString());
                htmltext = htmltext.Replace("@@nationality", rateband_data.Rows[i]["country"].ToString());
                htmltext = htmltext.Replace("@@totalratebandvalue", rateband_data.Rows[i]["rate_band"].ToString());
                htmltext = htmltext.Replace("@@mail", rateband_data.Rows[i]["mail"].ToString());
                htmltext = htmltext.Replace("@@TotalExperiance", rateband_data.Rows[i]["TotalExperiance"].ToString());
                htmltext = htmltext.Replace("@@aadhaar_no", rateband_data.Rows[i]["aadhaar_no"].ToString());
                htmltext = htmltext.Replace("@@passport_no", rateband_data.Rows[i]["passport_no"].ToString());
                htmltext = htmltext.Replace("@@pan_card_no", rateband_data.Rows[i]["pan_card_no"].ToString());
                htmltext = htmltext.Replace("@@cv_file_name", rateband_data.Rows[i]["cv_file_name"].ToString());
                htmltext = htmltext.Replace("@@portfolio_file_name", rateband_data.Rows[i]["portfolio_file_name"].ToString());
                htmltext = htmltext.Replace("@@profile_photo", rateband_data.Rows[i]["profile_photo"].ToString());


                if (approved_rateband_data != null)
                {
                    DataRow[] dr = approved_rateband_data.Select("instructor_code = '" + rateband_data.Rows[i]["instructor_code"] + "'");


                    if (dr.Length > 0 && approved_rateband_data != null)
                    {
                        rateband_data.Rows[i]["button_status"] = "TRUE";
                        htmltext = htmltext.Replace("@@remark_value", dr[0]["remark"].ToString());
                        htmltext = htmltext.Replace("@@block_approved", "block");
                        htmltext = htmltext.Replace("@@block_pending", "none");
                    }
                    else
                    {
                        if (rateband_data.Rows[i]["remark"].ToString() != "")
                        {
                            htmltext = htmltext.Replace("@@remark_value", rateband_data.Rows[i]["remark"].ToString());
                        }
                        else { htmltext = htmltext.Replace("@@remark_value", ""); }

                        htmltext = htmltext.Replace("@@block_approved", "none");
                        htmltext = htmltext.Replace("@@block_pending", "block");
                    }
                }
                else
                {
                    if (rateband_data.Rows[i]["remark"].ToString() != "")
                    {
                        htmltext = htmltext.Replace("@@remark_value", rateband_data.Rows[i]["remark"].ToString());
                    }
                    else { htmltext = htmltext.Replace("@@remark_value", ""); }

                    htmltext = htmltext.Replace("@@block_approved", "none");
                    htmltext = htmltext.Replace("@@block_pending", "block");
                }

                rateband_data.Rows[i]["htmltext"] = htmltext;

            }



            jsondata = GetJson1(rateband_data);
        }
        return jsondata;
    }


