        for (int i = 0; i < arr_interested_program_data.Count; i++)
        {
            Dictionary<string, object> data = (Dictionary<string, object>)arr_interested_program_data[i];
            remark = data["remark"].ToString().Replace("&#39;", "'");
            UserId = data["Student_id"].ToString();
            status_data = data["status"].ToString();
            type = data["type"].ToString();
        }
        dynamic status = objmaster.ProvisionalCertificate_remark(user_id, HttpContext.Current.Request.UserHostName.ToString(), UserId, remark, status_data, type);
        if (status && status_data == "R")
        {
            bool mail_status = objmaster.Send_Mail_for_ProvisionalCertificate(UserId, user_type, user_id);

        }
        return status;
    }


    [WebMethod(EnableSession = true)]
    public string update_student_Bank_dtl(string details_stu)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        string user_id;
        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            string user_type = HttpContext.Current.Session["UserId"].ToString();
            ArrayList arr_details_stu = ser.Deserialize<ArrayList>(details_stu);

            Dictionary<string, object> address_data = (Dictionary<string, object>)arr_details_stu[0];
            bool data_status = objmaster.update_student_Bank_dtl(user_id, address_data);
            if (data_status)
            {
                return "true";

            }
            else { return "false"; }



        }
        catch (Exception ex)
        {
            return "false";
        }
    }



    [WebMethod(EnableSession = true)]
    public string SaveSubmitFacultyTravelDtl(string details_other, string userid, string status, string FormStatus)
    {
        JavaScriptSerializer ser = new JavaScriptSerializer();

        string user_id;
        string host = HttpContext.Current.Request.UserHostName;
        try
        {
            if (HttpContext.Current.Session["UserId"].ToString() == null)
            {
                return return_ajax_string("1", "USer ID not found");
            }
            else
            {
                user_id = HttpContext.Current.Session["UserId"].ToString();
            }

            string user_type = HttpContext.Current.Session["UserId"].ToString();


            var arr_details_stu = ser.Deserialize<List<dynamic>>(details_other);

            string other_data = ser.Serialize(arr_details_stu[0]);
            string personal_data = ser.Serialize(arr_details_stu[1]);
            string travel_data = ser.Serialize(arr_details_stu[2]);
            string taxi_data = ser.Serialize(arr_details_stu[3]);
            string accommodation_data = ser.Serialize(arr_details_stu[4]);

            bool data_status = objmaster.SaveSubmitFacultyTravelDtl(user_id, other_data, personal_data, travel_data, taxi_data, accommodation_data, status, host, FormStatus);
            if (data_status)
            {
                return "true";

            }
            else { return "false"; }

        }
        catch (Exception ex)
        {
            return "false";
        }
    }



