    [WebMethod(EnableSession = true)]
    public string[] GetTRFAllData(string doc_no)
    {
        string[] data = new string[5];
        string jsondataOtherDetails = "";
        string jsondataPersonal = "";
        string jsondataTaxiDetails = "";
        string jsondataTravelDetails = "";
        string jsondataAccommodation = "";

        DataSet get_student_data = objmaster.GetTRFAllData(doc_no);


        DataTable OtherDetails = get_student_data.Tables[0];
        DataTable Personal_dtl = get_student_data.Tables[1];
        DataTable TravelDetails_dtl = get_student_data.Tables[2];
        DataTable TaxiDetails_dtl = get_student_data.Tables[3];
        DataTable AccommodationDetails_dtl = get_student_data.Tables[4];
        if (OtherDetails != null)
        {
            jsondataOtherDetails = GetJson1(OtherDetails);
        }
        if (Personal_dtl != null)
        {
            jsondataPersonal = GetJson1(Personal_dtl);
        }
        if (TaxiDetails_dtl != null)
        {
            jsondataTaxiDetails = GetJson1(TaxiDetails_dtl);
        }
        if (TravelDetails_dtl != null)
        {
            jsondataTravelDetails = GetJson1(TravelDetails_dtl);
        }
        if (AccommodationDetails_dtl != null)
        {
            jsondataAccommodation = GetJson1(AccommodationDetails_dtl);
        }
        data[0] = jsondataOtherDetails;
        data[1] = jsondataPersonal;
        data[2] = jsondataTravelDetails;
        data[3] = jsondataTaxiDetails;
        data[4] = jsondataAccommodation;

        return data;
    }


