            {
                dt_data.Rows[0]["semesterEnd"] = check_studentSemester.Rows[1]["semesterEnd"].ToString();
            }
            else
            {
                if (check_studentSemester.Rows[0]["SemCode"].ToString() == "M")
                {
                    dt_data.Rows[0]["semesterEnd"] = check_studentSemester.Rows[0]["semesterEnd"].ToString();
                }
                else { dt_data.Rows[0]["semesterEnd"] = check_studentSemester.Rows[1]["semesterEnd"].ToString(); }
