        //htmlToPdf.PageHeaderHtml = "<div style=''><hr style='color: black;height: 6px;background-color: #2f3f61;border: 0px solid #2f3f61;border-radius:45px;'></hr><div>";

        //htmlToPdf.PageFooterHtml = "";

        // new_string = html_header + new_string; 
        new_string = new_string;
        var pdfBytes = htmlToPdf.GeneratePdf(new_string);

        // System.Diagnostics.Process.Start(new_string);
        //path = path + "\\" + user_id + "_" + dt.Rows[0]["semester_type"].ToString() + "_" + dt.Rows[0]["year_semester"].ToString() + ".pdf";
        string file_name = StudentId + "_" + yearstudent + ".pdf";
        path = path + "\\" + StudentId + "_" + yearstudent + ".pdf";
        //path = path + "\\dd.pdf";
        path = path.Replace(" ", "");
        using (FileStream fs = new FileStream(path, FileMode.Create))
        {
            //ServerLog.ExceptionLog("File Create PDF");
            fs.Write(pdfBytes, 0, pdfBytes.Length);
            fs.Dispose();
            fs.Close();
            /// htmlToPdf.EndBatch();

        }


        return JsonConvert.SerializeObject(new { FileName = file_name, FilePath = "/MigrationCertificate/" + file_name, Status = "1" });
    }

