    #region SWS Save Grade Point

    [WebMethod(EnableSession = true)]
    public string Save_SWS_GraderPoint(string year_code, string dept_code, string prog_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        user_id = "";
        try
        {

            //Greade Point Save Or not Check 
            bool flag = false;
            DataTable dt_typology_data = objmaster.Get_typology_data();

            DataTable dt_ws_course_detail = objmaster.get_WS_Course_Detail_New(year_code, dept_code, prog_code);
            if (dt_ws_course_detail != null)
            {
                flag = true;

                if (flag)
                {
                    DataTable dt_stud_detail = objmaster.get_Student_Detail_new(year_code, dept_code, prog_code);
                    DataTable dt_ws_grade_range = objmaster.get_WS_Grade_Range_all();
                    DataTable dt_ws_course_grade_detail = objmaster.WS_Calculate_grade(dt_stud_detail, dt_ws_course_detail, dt_ws_grade_range);
                    DataTable SaveDataGet = objmaster.WS_GetDatasaveGradePointData();
                    dt_ws_course_grade_detail.Columns.Add("statussave").DefaultValue = "N";
                    if (SaveDataGet != null)
                    {
                        for (int i = 0; i < dt_ws_course_grade_detail.Rows.Count; i++)
                        {
                            DataRow[] dr = SaveDataGet.Select("studentid ='" + dt_ws_course_grade_detail.Rows[i]["user_id"].ToString() + "' " +
                                " and semester_type ='" + dt_ws_course_grade_detail.Rows[i]["semester_type"].ToString() + "'" +
                                " and year_semester ='" + dt_ws_course_grade_detail.Rows[i]["year_semester"].ToString() + "' " +
                                " and Course_Code ='" + dt_ws_course_grade_detail.Rows[i]["course_code"].ToString() + "'");

                            if (dr.Length > 0)
                            {
                                dt_ws_course_grade_detail.Rows[i]["grade"] = dr[0]["Grade"];
                                dt_ws_course_grade_detail.Rows[i]["grade_point"] = dr[0]["GradePoint"];
                                dt_ws_course_grade_detail.Rows[i]["remarks"] = dr[0]["FaillPassStatus"];
                                dt_ws_course_grade_detail.Rows[i]["statussave"] = "Y";
                            }
                        }
                    }

                    ArrayList a = new ArrayList();
                    if (dt_ws_course_detail != null)
                    {
                        a.Add(GetJson1(dt_ws_course_detail));
                    }
                    else
                    {
                        a.Add("null");
                    }
                    if (dt_ws_course_detail != null)
                    {
                        jsondata = "{\"stud_detail\":" + a[0] + "}";
                        return "{\"status\":\"true\",\"message\":" + jsondata + "}";
                    }
                    else
                    {
                        //return "No Marksheet found for selected Semester and Year";
                        return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
                    }

                }
                else
                {
                    //return "You have not completed the feedback, please fill the feedback to view your grades.";
                    //return "{\"status\":\"false\",\"message\":\"You have not completed the feedback, please fill the feedback to view your grades\"}";
                    return "{\"status\":\"falsee\",\"message\":\"Please submit the feedback to view the grade report\"}";
                }
            }
            else
            {
                return "{\"status\":\"false\",\"message\":\"No Marksheet found for selected Semester and Year\"}";
            }
        }
        catch (Exception ex)
        {
        }
        return jsondata;
    }

