    #region Student Account Ledger

    [WebMethod(EnableSession = true)]
    public string StudentAccountLedger(string Student_Code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        double TotalAmount = 0;
        int TotalSchAmount = 0;
        int rowcount = 0;
        DataTable dt_Fees_dtl = objMaster.Get_installMent_dtl_user_wise(Student_Code);
        DataTable dt_Tras_dtl = objMaster.GetTotalFeesDetails(Student_Code);
        DataTable dt_Scholarship_dtl = objMaster.GetTotalFeesDetailsScholarship(Student_Code);
        DataTable dt_Sws_dtl = objMaster.GetTotalFeesDetailsSWS(Student_Code);
        DataTable dt_hostel_dtl = objMaster.GetTotalFeesDetailshostelFeesPayment(Student_Code);

        DataTable dt_new = new DataTable();
        dt_new.Columns.Add("CreatedDate");
        dt_new.Columns.Add("Description");
        dt_new.Columns.Add("REFERENCE");
        dt_new.Columns.Add("Credit");
        dt_new.Columns.Add("semester");
        dt_new.Columns.Add("full_name");
        dt_new.Columns.Add("dept_name");
        DataRow[] swsdr = new DataRow[0];
        DataRow[] Scholarshipdr = new DataRow[0];

        if (dt_Fees_dtl != null)
        {
            for (int i = 0; i < dt_Fees_dtl.Rows.Count; i++)
            {
                TotalAmount = 0;
                DataRow[] dr = dt_Tras_dtl.Select("semester_type='" + dt_Fees_dtl.Rows[i]["semester_type"].ToString() + "' and year_semester = '" + dt_Fees_dtl.Rows[i]["year_semester"].ToString() + "'");

                if (dt_Sws_dtl != null)
                {
                    swsdr = dt_Sws_dtl.Select("semester_type='" + dt_Fees_dtl.Rows[i]["semester_type"].ToString() + "' and year_semester = '" + dt_Fees_dtl.Rows[i]["year_semester"].ToString() + "'");
                }


                if (dr.Length > 0)
                {

                    for (int p = 0; p < dr.Length; p++)
                    {
                        if (dt_new.Rows.Count > 0)
                        {
                            rowcount = dt_new.Rows.Count;
                        }
                        else { rowcount = 0; }
                        dt_new.Rows.Add();

                        dt_new.Rows[rowcount]["CreatedDate"] = dr[p]["CreatedDate"].ToString();
                        dt_new.Rows[rowcount]["Description"] = dr[p]["Description"].ToString();
                        dt_new.Rows[rowcount]["REFERENCE"] = dr[p]["REFERENCE"].ToString();
                        dt_new.Rows[rowcount]["Credit"] = dr[p]["Credit"].ToString();
                        TotalAmount = TotalAmount + Convert.ToDouble(dr[p]["Credit"].ToString());
                        dt_new.Rows[rowcount]["semester"] = dr[p]["semester"].ToString();
                        dt_new.Rows[rowcount]["full_name"] = dr[p]["full_name"].ToString();
                        dt_new.Rows[rowcount]["dept_name"] = dr[p]["dept_name"].ToString();
                    }
                }

                if (swsdr.Length > 0)
                {

                    for (int p = 0; p < swsdr.Length; p++)
                    {
                        if (dt_new.Rows.Count > 0)
                        {
                            rowcount = dt_new.Rows.Count;
                        }
                        else { rowcount = 0; }
                        dt_new.Rows.Add();

                        dt_new.Rows[rowcount]["CreatedDate"] = swsdr[p]["CreatedDate"].ToString();
                        dt_new.Rows[rowcount]["Description"] = swsdr[p]["Description"].ToString();
                        dt_new.Rows[rowcount]["REFERENCE"] = swsdr[p]["REFERENCE"].ToString();
                        dt_new.Rows[rowcount]["Credit"] = swsdr[p]["Credit"].ToString();
                        TotalAmount = TotalAmount + Convert.ToDouble(swsdr[p]["Credit"].ToString());
                        dt_new.Rows[rowcount]["semester"] = swsdr[p]["semester"].ToString();
                        dt_new.Rows[rowcount]["full_name"] = swsdr[p]["full_name"].ToString();
                        dt_new.Rows[rowcount]["dept_name"] = swsdr[p]["dept_name"].ToString();
                    }
                }

                //if (Scholarshipdr.Length > 0)
                //{

                //    for (int p = 0; p < Scholarshipdr.Length; p++)
                //    {
                //        if (dt_new.Rows.Count > 0)
                //        {
                //            rowcount = dt_new.Rows.Count;
                //        }
                //        else { rowcount = 0; }
                //        dt_new.Rows.Add();

                //        dt_new.Rows[rowcount]["CreatedDate"] = Scholarshipdr[p]["CreatedDate"].ToString();
                //        dt_new.Rows[rowcount]["Description"] = Scholarshipdr[p]["Description"].ToString();
                //        dt_new.Rows[rowcount]["REFERENCE"] = Scholarshipdr[p]["REFERENCE"].ToString();
                //        dt_new.Rows[rowcount]["Credit"] = Scholarshipdr[p]["Credit"].ToString();

                //        dt_new.Rows[rowcount]["semester"] = Scholarshipdr[p]["semester"].ToString();
                //    }
                //}

                if (TotalAmount > 0)
                {
                    if (dt_new.Rows.Count > 0)
                    {
                        rowcount = dt_new.Rows.Count;
                    }
                    else { rowcount = 0; }
                    int countrows = dt_new.Rows.Count - 1;
                    dt_new.Rows.Add();

                    dt_new.Rows[rowcount]["semester"] = dt_new.Rows[countrows]["semester"].ToString();
                    dt_new.Rows[rowcount]["Credit"] = "Total : " + TotalAmount;


                }
            }

            if (dt_Scholarship_dtl != null)
            {
                for (int p = 0; p < dt_Scholarship_dtl.Rows.Count; p++)
                {
                    if (dt_new.Rows.Count > 0)
                    {
                        rowcount = dt_new.Rows.Count;
                    }
                    else { rowcount = 0; }
                    dt_new.Rows.Add();

                    dt_new.Rows[rowcount]["CreatedDate"] = dt_Scholarship_dtl.Rows[p]["CreatedDate"].ToString();
                    dt_new.Rows[rowcount]["Description"] = dt_Scholarship_dtl.Rows[p]["Description"].ToString();
                    dt_new.Rows[rowcount]["REFERENCE"] = dt_Scholarship_dtl.Rows[p]["REFERENCE"].ToString();
                    dt_new.Rows[rowcount]["Credit"] = dt_Scholarship_dtl.Rows[p]["Credit"].ToString();
                    dt_new.Rows[rowcount]["dept_name"] = dt_Scholarship_dtl.Rows[p]["dept_name"].ToString();
                    dt_new.Rows[rowcount]["full_name"] = dt_Scholarship_dtl.Rows[p]["full_name"].ToString();
                    TotalSchAmount = TotalSchAmount + Convert.ToInt32(dt_Scholarship_dtl.Rows[p]["Credit"].ToString());

                    dt_new.Rows[rowcount]["semester"] = "ScholarShip";
                }
            }

            if (TotalSchAmount > 0)
            {
                if (dt_new.Rows.Count > 0)
                {
                    rowcount = dt_new.Rows.Count;
                }
                else { rowcount = 0; }
                int countrows = dt_new.Rows.Count - 1;
                dt_new.Rows.Add();

                dt_new.Rows[rowcount]["semester"] = "ScholarShip";
                dt_new.Rows[rowcount]["Credit"] = "Total : " + TotalSchAmount;


            }

            if (dt_hostel_dtl != null)
            {
                TotalSchAmount = 0;
                for (int p = 0; p < dt_hostel_dtl.Rows.Count; p++)
                {
                    if (dt_new.Rows.Count > 0)
                    {
                        rowcount = dt_new.Rows.Count;
                    }
                    else { rowcount = 0; }
                    dt_new.Rows.Add();

                    dt_new.Rows[rowcount]["CreatedDate"] = dt_hostel_dtl.Rows[p]["CreatedDate"].ToString();
                    dt_new.Rows[rowcount]["Description"] = dt_hostel_dtl.Rows[p]["Description"].ToString();
                    dt_new.Rows[rowcount]["REFERENCE"] = dt_hostel_dtl.Rows[p]["REFERENCE"].ToString();
                    dt_new.Rows[rowcount]["Credit"] = dt_hostel_dtl.Rows[p]["Credit"].ToString();
                    dt_new.Rows[rowcount]["dept_name"] = dt_hostel_dtl.Rows[p]["dept_name"].ToString();
                    dt_new.Rows[rowcount]["full_name"] = dt_hostel_dtl.Rows[p]["full_name"].ToString();
                    TotalSchAmount = TotalSchAmount + Convert.ToInt32(dt_hostel_dtl.Rows[p]["Credit"].ToString());
                    dt_new.Rows[rowcount]["semester"] = "Hostel Payment";
                }
            }

            if (dt_hostel_dtl != null)
            {
                if (dt_new.Rows.Count > 0)
                {
                    rowcount = dt_new.Rows.Count;
                }
                else { rowcount = 0; }
                int countrows = dt_new.Rows.Count - 1;
                dt_new.Rows.Add();

                dt_new.Rows[rowcount]["semester"] = "Hostel Payment";
                dt_new.Rows[rowcount]["Credit"] = "Total : " + TotalSchAmount;


            }
        }

        if (dt_new != null)
        {
            jsondata = GetJson1(dt_new);
        }
        return jsondata;


    }
