    #region FileUpload

    [WebMethod(EnableSession = true)]
    public string FileUpload(string fileBytes, string fileName, string doc_title, string usertype)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        try
        {
            byte[] fileData = Convert.FromBase64String(fileBytes);
            string filePath = Path.Combine(Server.MapPath("~/UserManual"), fileName);

            if (!Directory.Exists(Server.MapPath("~/UploadFiles")))
            {
                Directory.CreateDirectory(Server.MapPath("~/UserManual"));
            }
            File.WriteAllBytes(filePath, fileData);

            dynamic status = objmaster.Insert_User_Manual_dtl(doc_title, usertype, fileName, user_id);

            return "{\"success\": true, \"message\": \"File uploaded successfully.\"}";
        }
        catch (Exception ex)
        {
            return "{\"success\": false, \"message\": \"No file uploaded.\"}";
