    [WebMethod(EnableSession = true)]
    public string UploadExceldata(string fileBytes, string year, string semester)
    {
        string host_user_id = HttpContext.Current.Session["UserId"].ToString();
        string host_name = HttpContext.Current.Request.UserHostName;
        string path = DateTime.Today.ToString("yyyy_MM_dd") + DateTime.Now.ToString("_hh_mm_ss_tt_");
        string fileName = path + "_" + host_user_id + ".xlsx";
        byte[] fileData = Convert.FromBase64String(fileBytes);
        string filePath = Path.Combine(Server.MapPath("~/uploadRateBandExcel"), fileName);

        if (!Directory.Exists(Server.MapPath("~/uploadRateBandExcel")))
        {
            Directory.CreateDirectory(Server.MapPath("~/uploadRateBandExcel"));
        }
        File.WriteAllBytes(filePath, fileData);


        try
        {
            DataTable dt = new DataTable();
            dt.Columns.Add("instructor_code", typeof(string));
            dt.Columns.Add("rate_band", typeof(string));
            dt.Columns.Add("designation", typeof(string));
            dt.Columns.Add("designation_letter", typeof(string));
            dt.Columns.Add("TotalExperience", typeof(string));
            dt.Columns.Add("highest_qualification", typeof(string));
            dt.Columns.Add("ApproveRateBand", typeof(string));
            dt.Columns.Add("DegreeID", typeof(string));
            using (var stream = new MemoryStream(fileData))
            {
                using (var workbook = new XLWorkbook(stream))
                {
                    var worksheet = workbook.Worksheet(1);
                    var rows = worksheet.RangeUsed().RowsUsed();
                    foreach (var row in rows.Skip(1)) // Skip header row
                    {
                        DataRow dataRow = dt.NewRow();
                        dataRow["instructor_code"] = row.Cell(1).GetValue<string>();
                        dataRow["rate_band"] = row.Cell(2).GetValue<string>();
                        dataRow["designation"] = row.Cell(3).GetValue<string>();
                        dataRow["designation_letter"] = row.Cell(4).GetValue<string>();
                        dataRow["TotalExperience"] = row.Cell(5).GetValue<string>();
                        dataRow["highest_qualification"] = row.Cell(6).GetValue<string>();
                        dataRow["ApproveRateBand"] = row.Cell(7).GetValue<string>();
                        dataRow["DegreeID"] = row.Cell(8).GetValue<string>();

                        dt.Rows.Add(dataRow);


                    }
                }
            }

            if (dt.Rows.Count > 0)
            {
                bool statusget = objmaster.InsertRateBandDataExcel(dt, host_user_id, semester, year, host_name);
            }
        }
        catch (Exception ex)
        {

            return "Error: " + ex.Message;
        }


        return "File uploaded and processed successfully.";

    }


    [WebMethod(EnableSession = true)]
    public string SaveRateBandOnlyTAUser(string total_weeks, string total_contact_hrs, string justification, string additional_hours, string course_code, string sem_code, string year_code, string inst_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string CurrentRateBand = ""; 

        string strmsg = "[{\"weeks\":\"" + total_weeks + "\",\"contact_hrs\":\"" + total_contact_hrs + "\"}]";
        string strmsg_rateband = "[{\"status\":\"true\",\"Rateband\":\"" + CurrentRateBand + "\"}]";

        string total_hrs_in_semester = total_contact_hrs.ToString();

        DataTable Get_TotalContact_hrs = objmaster.Get_total_contact_hrs_coursewise(inst_code, sem_code, year_code, course_code, total_hrs_in_semester);

        if (Get_TotalContact_hrs != null)
        {
            if (Convert.ToDouble(Get_TotalContact_hrs.Rows[0]["total_contact_hrs"]) <= 40)
            {
                bool status_for_update = objmaster.update_TA_Workload(total_weeks, total_contact_hrs, justification, additional_hours, course_code, inst_code, sem_code, year_code, strmsg, user_id);
                if (status_for_update)
                {
                    return jsondata = "true";
                }
                else { return jsondata = "false"; }
            }
            else
            {
                return jsondata = "You Cannot Exceed 40 Contact Hours Of Tutor. If you need to go above this limit, please contact the UG/PG office.";
            }

        }
        else 
        {

            bool status_for_update = objmaster.update_TA_Workload(total_weeks, total_contact_hrs, justification, additional_hours, course_code, inst_code, sem_code, year_code, strmsg, user_id);
            if (status_for_update)
            {
                return jsondata = "true";
            }
            else  
            {
                return jsondata = "false"; 
            }
        }
        return "false";
    }



