    [WebMethod(EnableSession = true)]
    public string SaveRateBandNew(string commit_data, string sem_code, string year_code)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string host_name = HttpContext.Current.Request.UserHostName;
        JavaScriptSerializer ser = new JavaScriptSerializer();

        List<string> lst_commit_data = ser.Deserialize<List<string>>(commit_data);
        string commaSeparated = string.Join(",", lst_commit_data.Select(x => "'" + x + "'"));

        bool status_data = objmaster.insert_published_allocation_new(sem_code, year_code, user_id, host_name, commaSeparated);
        if (status_data)
        {
            return "RateBand Submitted Successfully";
        }
        return "Rate band has not been submitted.";
    }


