                //        Get_date.Rows[i]["SUB" + k + "_REMARKS"] = dr[k - 1]["SUB1_REMARKS"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_TYPE"] = dr[k - 1]["SUB1_TYPE"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_CREDIT"] = dr[k - 1]["SUB1_CREDIT"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_GRADE"] = dr[k - 1]["SUB1_GRADE"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_GRADE_POINTS"] = dr[k - 1]["SUB1_GRADE_POINTS"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_CREDIT_POINTS"] = dr[k - 1]["SUB1_CREDIT_POINTS"].ToString();
                //        Get_date.Rows[i]["SUB" + k + "_STATUS"] = dr[k - 1]["SUB1_STATUS"].ToString();
                //    }
                //}


                double totalcredit = 0;
                double TOT_CREDIT_POINTS = 0;
                int subjectIndex = 1; // Start counting subjects

                // first handle normal subjects (dr)
                for (int k = 1; k <= dr.Length; k++)
                {
                    string sem_code = "S";
                    string year_code = dr[k - 1]["year"].ToString();
                    if (dr[k - 1]["TERM_TYPE"].ToString() == "Monsoon")
                        sem_code = "M";
                    if (dr[k - 1]["TERM_TYPE"].ToString() == "Winter")
                        sem_code = "W";

                    DataRow[] dr_GetNADSGPACSPADtl = GetNADSGPACSPADtl.Select("studentid = '" + Get_date.Rows[i]["RROLL"].ToString() + "' AND semester = '" + sem_code + "' AND year_semester = '" + year_code + "'");
                    if (dr_GetNADSGPACSPADtl.Length > 0)
                    {
                        //Get_date.Rows[i]["CGPA"] = dr_GetNADSGPACSPADtl[0]["Total_cgpa_four_digit"].ToString();
                        Get_date.Rows[i]["CGPA"] = dr_GetNADSGPACSPADtl[0]["semester_wise_cgpa"].ToString();
                        Get_date.Rows[i]["SGPA"] = dr_GetNADSGPACSPADtl[0]["SemesterGPA"].ToString();
                        //Get_date.Rows[i]["SGPA"] = dr_GetNADSGPACSPADtl[0]["semester_wise_cgpa_four_digit"].ToString();
                    }

                    totalcredit += Convert.ToDouble(dr[k - 1]["SUB1_CREDIT"].ToString());
                    TOT_CREDIT_POINTS += Convert.ToDouble(dr[k - 1]["SUB1_CREDIT_POINTS"].ToString());
                    Get_date.Rows[i]["TOT_CREDIT"] = totalcredit;
                    Get_date.Rows[i]["TOT_CREDIT_POINTS"] = TOT_CREDIT_POINTS;
                    Get_date.Rows[i]["YEAR"] = dr[k - 1]["year"].ToString();
                    Get_date.Rows[i]["SEM"] = dr[k - 1]["SEM"].ToString();
                    Get_date.Rows[i]["TERM_TYPE"] = dr[k - 1]["TERM_TYPE"].ToString();

                    Get_date.Rows[i]["SUB" + subjectIndex] = dr[k - 1]["SUB1"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "NM"] = dr[k - 1]["SUB1NM"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_REMARKS"] = dr[k - 1]["SUB1_REMARKS"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_TYPE"] = dr[k - 1]["SUB1_TYPE"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_CREDIT"] = dr[k - 1]["SUB1_CREDIT"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_GRADE"] = dr[k - 1]["SUB1_GRADE"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_GRADE_POINTS"] = dr[k - 1]["SUB1_GRADE_POINTS"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_CREDIT_POINTS"] = dr[k - 1]["SUB1_CREDIT_POINTS"].ToString();
                    Get_date.Rows[i]["SUB" + subjectIndex + "_STATUS"] = dr[k - 1]["SUB1_STATUS"].ToString();

                    subjectIndex++; // move to next slot
                }


                if (dr1 != null && dr1.Length > 0)
                {
                    for (int m = 0; m < dr1.Length; m++)
                    {
                        totalcredit += Convert.ToDouble(dr1[m]["SUB1_CREDIT"].ToString());
                        TOT_CREDIT_POINTS += Convert.ToDouble(dr1[m]["SUB1_CREDIT_POINTS"].ToString());
                        Get_date.Rows[i]["TOT_CREDIT"] = totalcredit;
                        Get_date.Rows[i]["TOT_CREDIT_POINTS"] = TOT_CREDIT_POINTS;

                        // Continue from next available subjectIndex
                        Get_date.Rows[i]["SUB" + subjectIndex] = dr1[m]["SUB1"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "NM"] = dr1[m]["SUB1NM"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_REMARKS"] = dr1[m]["SUB1_REMARKS"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_TYPE"] = dr1[m]["SUB1_TYPE"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_CREDIT"] = dr1[m]["SUB1_CREDIT"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_GRADE"] = dr1[m]["SUB1_GRADE"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_GRADE_POINTS"] = dr1[m]["SUB1_GRADE_POINTS"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_CREDIT_POINTS"] = dr1[m]["SUB1_CREDIT_POINTS"].ToString();
                        Get_date.Rows[i]["SUB" + subjectIndex + "_STATUS"] = dr1[m]["SUB1_STATUS"].ToString();

                        subjectIndex++; // keep going
                    }
                }


            }
        }


        if (Get_date != null)
        {
            jsonarray[0] = GetJson1(Get_date);
        }

        return jsonarray;
    }
