    [WebMethod(EnableSession = true)]
    public string save_budget_data(object data)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        try
        {
            string json = new JavaScriptSerializer().Serialize(data);
            var serializer = new JavaScriptSerializer();
            var parsedData = serializer.Deserialize<Dictionary<string, List<Dictionary<string, object>>>>(json);
           
            if (parsedData.ContainsKey("A"))
            { 
                //string courseCode = "";
                //string SubTypeId = "A006";
                //string Details = "";
                foreach (var row in parsedData["A"])
                {

                    string courseCode = row["course_code"].ToString();
                    string csSubTypeId = row["cs_sub_type_id"].ToString();
                    string Details = row["Details"].ToString();

                    // Step 1: Check if record exists
                    DataTable exists = objmaster.CheckIfRecordExistsA(courseCode, csSubTypeId, Details);

                    if (exists != null && exists.Rows.Count > 0)
                    {
                        // Step 2: Update cancel_flag to 'Y'
                        bool updation = objmaster.UpdateCancelFlagA(courseCode, csSubTypeId, Details);
                    }

                    bool a = objmaster.SaveToTableA(row, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }

            }
            if (parsedData.ContainsKey("B"))
            {
                foreach (var row in parsedData["B"])
                {
                    if (string.IsNullOrWhiteSpace(row["value"].ToString()))
                    {
                        continue;
                    }
                    string courseCode = row["course_code"].ToString();
                    string csSubTypeId = row["cs_sub_type_id"].ToString();
                    string Details = row["Details"].ToString();


                    // Step 1: Check if record exists
                    DataTable exists = objmaster.CheckIfRecordExistsB(courseCode, csSubTypeId, Details);

                    if (exists != null && exists.Rows.Count > 0)
                    {
                        // Step 2: Update cancel_flag to 'Y'
                        bool updation = objmaster.UpdateCancelFlagB(courseCode, csSubTypeId, Details);
                    }

                    bool b = objmaster.SaveToTableB(row, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }
            }
            if (parsedData.ContainsKey("C"))
            {
                foreach (var row in parsedData["C"])
                {
                    if (string.IsNullOrWhiteSpace(row["value"].ToString()))
                    {
                        continue;
                    }
                    string courseCode = row["course_code"].ToString();
                    string csSubTypeId = row["cs_sub_type_id"].ToString();
                    string Details = row["Details"].ToString();

                    // Step 1: Check if record exists
                    DataTable exists = objmaster.CheckIfRecordExistsC(courseCode, csSubTypeId, Details);

                    if (exists != null && exists.Rows.Count > 0)
                    {
                        // Step 2: Update cancel_flag to 'Y'
                        bool updation = objmaster.UpdateCancelFlagC(courseCode, csSubTypeId, Details);
                    }

                    bool c = objmaster.SaveToTableC(row, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }
            }
            if (parsedData.ContainsKey("D"))
            {
                foreach (var row in parsedData["D"])
                {

                    string courseCode = row["course_code"].ToString();
                    string csSubTypeId = row["cs_sub_type_id"].ToString();
                    string Details = row["Details"].ToString();


                    // Step 1: Check if record exists
                    DataTable exists = objmaster.CheckIfRecordExistsD(courseCode, csSubTypeId);

                    if (exists != null && exists.Rows.Count > 0)
                    {
                        // Step 2: Update cancel_flag to 'Y'
                        bool updation = objmaster.UpdateCancelFlagD(courseCode, csSubTypeId);
                    }

                    bool d = objmaster.SaveToTableD(row, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                }
            }
            if (parsedData.ContainsKey("CourseInfo"))
            {
                foreach (var row in parsedData["CourseInfo"])
                {
                    string courseCode = row["course_code"].ToString();
                    string semester_type = row["semester_type"].ToString();
                    string year_semester = row["year_semester"].ToString();

                    DataTable exists = objmaster.CheckCourseInfo(courseCode, semester_type, year_semester);
                    if (exists != null && exists.Rows.Count > 0)
                    {
                        bool updation = objmaster.UpdateCancelFlagforCourseInfo(courseCode, semester_type, year_semester);
                        if (!updation) return "false";
                    }
                    bool saved = objmaster.SaveCourseInfo(row,HttpContext.Current.Session["UserId"].ToString(),HttpContext.Current.Request.UserHostName, exists, user_type);

                    if (!saved) return "false";
                }
            }


            if (parsedData.ContainsKey("instructor_details"))
            {
                foreach (var row in parsedData["instructor_details"])
                {
                    string courseCode = row["course_code"].ToString();
                    string semester_type = row["semester_type"].ToString();
