                    bool a = objmaster.SaveToTableinstructorDetails(row, HttpContext.Current.Session["UserId"].ToString(), HttpContext.Current.Request.UserHostName);
                    if (!a) return "false";
                }
            }



            return "success";
        }
        catch (Exception ex)
        {
            return "error: " + ex.Message;
        }
