                foreach (var row in parsedData["C"])
                {
                    if (string.IsNullOrWhiteSpace(row["value"].ToString()))
                        continue;

                    string courseCode = row["course_code"].ToString();
                    string csSubTypeId = row["cs_sub_type_id"].ToString();
                    string Details = row["Details"].ToString();

