    [WebMethod(EnableSession = true)]
    public string SaveDeclarationData(string formDataJson, string crdfDataJson,string referenceDataJson)
    {
        var user_id = HttpContext.Current.Session["UserId"].ToString();
        var user_type = HttpContext.Current.Session["user_type"].ToString();
        string host_name = HttpContext.Current.Request.UserHostName;
        var crdfstatus = "No";
        bool declarationResult = false;
        bool crdfResult = false;
        bool referenceResult = false;

        Dictionary<string, object> formData = new Dictionary<string, object>();
        Dictionary<string, object> crdfData = new Dictionary<string, object>();
        Dictionary<string, object> referenceData = new Dictionary<string, object>();

        if (!string.IsNullOrEmpty(formDataJson))
        {
            var jsonObject = JsonConvert.DeserializeObject<Dictionary<string, object>>(formDataJson);
        }
        if (!string.IsNullOrEmpty(crdfDataJson))
        {
            var SaveCRDF = JsonConvert.DeserializeObject<List<Dictionary<string, object>>>(crdfDataJson);
            crdfResult = personalDetails.SaveCRDF(SaveCRDF, user_id, host_name, crdfstatus);
        }
        if (crdfResult && !string.IsNullOrEmpty(referenceDataJson))
        {
            var SaveRefrence = JsonConvert.DeserializeObject<List<Dictionary<string, object>>>(referenceDataJson);
            referenceResult = personalDetails.SaveReference(SaveRefrence, user_id, host_name);
        }


        if (crdfResult && referenceResult && !string.IsNullOrEmpty(formDataJson))
        {
            var jsonObjectdec = JsonConvert.DeserializeObject<Dictionary<string, object>>(formDataJson);
            declarationResult = personalDetails.SaveDeclarationData(jsonObjectdec, user_id, host_name, user_type);
        }



        //if (!string.IsNullOrEmpty(formDataJson))
        //{
        //    var jsonObject = JsonConvert.DeserializeObject<Dictionary<string, object>>(formDataJson);
        //    if (jsonObject != null)
        //    {
        //        formData = jsonObject;
        //    }
        //}
        //bool result = personalDetails.SaveDeclarationData(formData, user_id, host_name);
        //if (result)
        //{
        //    return Constants.JsonResponse.CreateSuccessResponse("Declaration details saved successfully");
        //}
        //else
        //{
        //    return Constants.JsonResponse.CreateErrorResponse("Failed to DeclarationDetails ", "Database operation failed");
        //}

        if (crdfResult && referenceResult && declarationResult)
        {
            return Constants.JsonResponse.CreateSuccessResponse("All details saved successfully");
        }
        else if (!crdfResult)
        {
            return Constants.JsonResponse.CreateErrorResponse("Failed to save CRDF details", "Database operation failed");
        }
        else if (!referenceResult)
        {
            return Constants.JsonResponse.CreateErrorResponse("Failed to save Reference details", "Database operation failed");
        }
        else
        {
            return Constants.JsonResponse.CreateErrorResponse("Failed to save Declaration details", "Database operation failed");
        }

    }


   

