    [WebMethod(EnableSession = true)]
    public string DownloadZip(Dictionary<string, List<string>> files)
    {
        try
        {
            string CVPath = HttpContext.Current.Server.MapPath("~/InstructorCVUpload");
            string PortfolioPath = HttpContext.Current.Server.MapPath("~/InstructorPortfolioUpload");

            string FolderPathToZip = CVPath + "\\Document";
            string ZipFilePath = FolderPathToZip + ".zip";

            if (File.Exists(ZipFilePath))
            {
                File.Delete(ZipFilePath);
            }

            using (var zip = new Ionic.Zip.ZipFile())
            {
                if (files.ContainsKey("CV") && files["CV"] != null)
                {
                    foreach (var fileName in files["CV"])
                    {
                        string path = Path.Combine(CVPath, fileName);
                        if (File.Exists(path))
                        {
                            zip.AddFile(path, "CV");
                        }
                    }
                }

                if (files.ContainsKey("Portfolio") && files["Portfolio"] != null)
                {
                    foreach (var fileName in files["Portfolio"])
                    {
                        string path = Path.Combine(PortfolioPath, fileName);
                        if (File.Exists(path))
                        {
                            zip.AddFile(path, "Portfolio");
                        }
                    }
                }

                zip.Save(ZipFilePath);
            }

            // return relative path so browser can download it
            string relativeUrl = "/InstructorCVUpload/Document.zip";
            return relativeUrl;
        }
        catch
        {
            return "ERROR";
        }
    }

    [WebMethod(EnableSession = true)]
    public string DownloadZip_work(Dictionary<string, List<string>> files)
    {
        try
        {
            string workPath = HttpContext.Current.Server.MapPath("~/InstructorWorkExperiencecertificate");

            string FolderPathToZip = workPath + "\\Document";
            string ZipFilePath = FolderPathToZip + ".zip";

            if (File.Exists(ZipFilePath))
            {
                File.Delete(ZipFilePath);
            }

            using (var zip = new Ionic.Zip.ZipFile())
            {
                if (files.ContainsKey("Work_Certificates") && files["Work_Certificates"] != null)
                {
                    foreach (var fileName in files["Work_Certificates"])
                    {
                        string path = Path.Combine(workPath, fileName);
                        if (File.Exists(path))
                        {
                            zip.AddFile(path, "Work_Certificates");
                        }
                    }
                }

                zip.Save(ZipFilePath);
            }


            string relativeUrl = "/InstructorWorkExperiencecertificate/Document.zip";
            return relativeUrl;
        }
        catch
        {
            return "ERROR";
        }
    }


