    [WebMethod(EnableSession = true)]
    public string DownloadFacultyAppraisalCertZip(Dictionary<string, List<string>> files)
    {
        try
        {
            string baseFolderPath = HttpContext.Current.Server.MapPath("~/ApprisalFileUploads");

            string zipFilePath = Path.Combine(baseFolderPath, "FacultyAppraisal.zip");

            if (File.Exists(zipFilePath))
            {
                File.Delete(zipFilePath);
            }

            using (var zip = new Ionic.Zip.ZipFile())
            {
                foreach (var category in files.Keys)
                {
                    var fileList = files[category];
                    if (fileList != null)
                    {
                        foreach (var fileName in fileList)
                        {
                            if (!string.IsNullOrWhiteSpace(fileName))
                            {
                                string fullPath = Path.Combine(baseFolderPath, fileName);
                                if (File.Exists(fullPath))
                                {
                                    zip.AddFile(fullPath, category); 
                                }
                            }
                        }
                    }
                }
                zip.Save(zipFilePath);
            }
            string relativeUrl = "/ApprisalFileUploads/FacultyAppraisal.zip";
            return relativeUrl;
        }
        catch (Exception ex)
        {
            return "ERROR";
        }
    }
}